-- -----------------------------------------------------------------------------
-- public.pay_workbench_dirty_event_enqueue(p_job_type text, p_scope_kind text, p_scope_id text, p_candidate_id uuid, p_targeted_timesheet_ids uuid[], p_linked_timesheet_ids uuid[], p_payload_json jsonb, p_reason text, p_priority integer, p_run_at_utc timestamp with time zone)
-- Installed pg_get_functiondef MD5: e13fd99e709b5461d558647e1f6263cc
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.pay_workbench_dirty_event_enqueue(p_job_type text, p_scope_kind text, p_scope_id text, p_candidate_id uuid DEFAULT NULL::uuid, p_targeted_timesheet_ids uuid[] DEFAULT ARRAY[]::uuid[], p_linked_timesheet_ids uuid[] DEFAULT ARRAY[]::uuid[], p_payload_json jsonb DEFAULT '{}'::jsonb, p_reason text DEFAULT NULL::text, p_priority integer DEFAULT '-1000'::integer, p_run_at_utc timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_job_type text := UPPER(BTRIM(COALESCE(p_job_type, '')));
  v_scope_kind text := UPPER(BTRIM(COALESCE(p_scope_kind, '')));
  v_scope_id text := NULLIF(BTRIM(COALESCE(p_scope_id, '')), '');
  v_targeted_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_linked_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_targeted_key_part text := 'ALL';
  v_dedupe_key text;
  v_reason text := NULLIF(BTRIM(COALESCE(p_reason, '')), '');
  v_payload_json jsonb := '{}'::jsonb;
  v_incoming_payload jsonb := '{}'::jsonb;
  v_latest_source_change_seq bigint := 0;
  v_job_id uuid;
  v_job_status text;
  v_job_payload jsonb;
  v_priority integer := COALESCE(p_priority, -1000);
  v_run_at_utc timestamptz := COALESCE(p_run_at_utc, v_now);
  v_scope_uuid uuid := NULL::uuid;
BEGIN
  IF v_job_type NOT IN (
    'WORKBENCH_CANDIDATE_DIRTY_APPLY',
    'WORKBENCH_FINANCE_CASE_DIRTY_APPLY',
    'CONTRACT_CLIENT_DIRTY_FANOUT'
  ) THEN
    RAISE EXCEPTION 'Unsupported Banking Pay dirty event job_type: %', p_job_type
      USING ERRCODE = '22023';
  END IF;

  IF v_scope_kind = '' OR v_scope_id IS NULL THEN
    RAISE EXCEPTION 'Banking Pay dirty event requires scope_kind and scope_id'
      USING ERRCODE = '22023';
  END IF;

  IF v_scope_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_scope_uuid := v_scope_id::uuid;
  END IF;

  IF v_job_type IN ('WORKBENCH_FINANCE_CASE_DIRTY_APPLY', 'CONTRACT_CLIENT_DIRTY_FANOUT')
     AND v_scope_uuid IS NULL THEN
    RAISE EXCEPTION 'Banking Pay dirty event scope_id must be a UUID for job_type %, scope_kind %, scope_id %', v_job_type, v_scope_kind, v_scope_id
      USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(array_agg(DISTINCT target_id ORDER BY target_id), ARRAY[]::uuid[])
  INTO v_targeted_timesheet_ids
  FROM unnest(COALESCE(p_targeted_timesheet_ids, ARRAY[]::uuid[])) AS target_id
  WHERE target_id IS NOT NULL;

  SELECT COALESCE(array_agg(DISTINCT linked_id ORDER BY linked_id), ARRAY[]::uuid[])
  INTO v_linked_timesheet_ids
  FROM unnest(COALESCE(p_linked_timesheet_ids, ARRAY[]::uuid[])) AS linked_id
  WHERE linked_id IS NOT NULL;

  IF COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) > 0 THEN
    v_targeted_key_part := array_to_string(v_targeted_timesheet_ids, ',');
  END IF;

  IF p_candidate_id IS NOT NULL THEN
    PERFORM public._change_bump('pay_candidate:' || p_candidate_id::text);

    SELECT COALESCE(change_counter.seq, 0)
    INTO v_latest_source_change_seq
    FROM public.app_change_counters AS change_counter
    WHERE change_counter.entity_key = 'pay_candidate:' || p_candidate_id::text;
  END IF;

  v_latest_source_change_seq := GREATEST(
    COALESCE(v_latest_source_change_seq, 0),
    COALESCE(CASE WHEN COALESCE(p_payload_json->>'latest_source_change_seq', '') ~ '^\d+$' THEN (p_payload_json->>'latest_source_change_seq')::bigint END, 0),
    COALESCE(CASE WHEN COALESCE(p_payload_json->>'source_change_seq', '') ~ '^\d+$' THEN (p_payload_json->>'source_change_seq')::bigint END, 0),
    COALESCE(CASE WHEN COALESCE(p_payload_json->>'source_change_sequence', '') ~ '^\d+$' THEN (p_payload_json->>'source_change_sequence')::bigint END, 0)
  );

  IF v_reason IS NULL THEN
    v_reason := 'DIRTY_TRIGGER:' || v_scope_kind;
  END IF;

  IF v_job_type = 'WORKBENCH_CANDIDATE_DIRTY_APPLY' THEN
    IF p_candidate_id IS NULL THEN
      RAISE EXCEPTION 'Candidate dirty apply job requires p_candidate_id'
        USING ERRCODE = '22023';
    END IF;
    v_dedupe_key := 'DIRTY_TRIGGER:WORKBENCH_CANDIDATE_DIRTY_APPLY:CANDIDATE:'
      || p_candidate_id::text
      || ':TIMESHEETS:' || v_targeted_key_part;
  ELSIF v_job_type = 'WORKBENCH_FINANCE_CASE_DIRTY_APPLY' THEN
    v_dedupe_key := 'DIRTY_TRIGGER:WORKBENCH_FINANCE_CASE_DIRTY_APPLY:' || v_scope_kind || ':' || v_scope_id;
  ELSE
    v_dedupe_key := 'DIRTY_TRIGGER:CONTRACT_CLIENT_DIRTY_FANOUT:' || v_scope_kind || ':' || v_scope_id;
  END IF;

  v_incoming_payload := jsonb_strip_nulls(
    COALESCE(p_payload_json, '{}'::jsonb)
    || jsonb_build_object(
      'job_type', v_job_type,
      'scope_kind', v_scope_kind,
      'scope_id', v_scope_id,
      'queue_class', 'DIRTY_TRIGGER_PRIORITY',
      'priority_class', 'DIRTY_TRIGGER_PRIORITY',
      'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
      'finance_case_id', CASE WHEN v_job_type = 'WORKBENCH_FINANCE_CASE_DIRTY_APPLY' AND v_scope_uuid IS NOT NULL THEN v_scope_uuid::text ELSE NULL::text END,
      'contract_id', CASE WHEN v_job_type = 'CONTRACT_CLIENT_DIRTY_FANOUT' AND v_scope_kind = 'CONTRACT' AND v_scope_uuid IS NOT NULL THEN v_scope_uuid::text ELSE NULL::text END,
      'client_id', CASE WHEN v_job_type = 'CONTRACT_CLIENT_DIRTY_FANOUT' AND v_scope_kind = 'CLIENT' AND v_scope_uuid IS NOT NULL THEN v_scope_uuid::text ELSE NULL::text END,
      'umbrella_id', CASE WHEN v_job_type = 'CONTRACT_CLIENT_DIRTY_FANOUT' AND v_scope_kind = 'UMBRELLA' AND v_scope_uuid IS NOT NULL THEN v_scope_uuid::text ELSE NULL::text END,
      'targeted_timesheet_ids', COALESCE(to_jsonb(v_targeted_timesheet_ids), '[]'::jsonb),
      'linked_timesheet_ids', COALESCE(to_jsonb(v_linked_timesheet_ids), '[]'::jsonb),
      'reason', v_reason,
      'reason_latest', v_reason,
      'reason_count', 1,
      'trigger_source', COALESCE(p_payload_json->>'trigger_source', p_payload_json->>'trigger_table', v_scope_kind),
      'latest_source_change_seq', v_latest_source_change_seq,
      'source_change_seq', v_latest_source_change_seq,
      'source_change_sequence', v_latest_source_change_seq,
      'latest_event_at_utc', v_now::text,
      'event_at_utc', v_now::text,
      'rerun_required', false,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
      'policy_x_dirtying_only', true,
      'economic_truth_mutation_allowed', false
    )
  );

  v_payload_json := public._pay_workbench_dirty_payload_merge('{}'::jsonb, v_incoming_payload);

  INSERT INTO public.banking_pay_workbench_jobs AS queued_job (
    job_type,
    status,
    priority,
    run_at_utc,
    attempt_count,
    max_attempts,
    dedupe_key,
    snapshot_run_id,
    session_id,
    candidate_id,
    payload_json,
    created_at_utc,
    updated_at_utc,
    started_at_utc,
    completed_at_utc,
    failed_at_utc,
    last_error_json
  )
  VALUES (
    v_job_type,
    'QUEUED',
    v_priority,
    v_run_at_utc,
    0,
    8,
    v_dedupe_key,
    NULL,
    NULL,
    CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DIRTY_APPLY' THEN p_candidate_id ELSE NULL::uuid END,
    v_payload_json,
    v_now,
    v_now,
    NULL,
    NULL,
    NULL,
    NULL
  )
  ON CONFLICT (dedupe_key) WHERE status IN ('QUEUED', 'RUNNING')
  DO UPDATE
  SET priority = LEAST(queued_job.priority, EXCLUDED.priority),
      run_at_utc = LEAST(queued_job.run_at_utc, EXCLUDED.run_at_utc),
      updated_at_utc = v_now,
      failed_at_utc = CASE WHEN queued_job.status = 'QUEUED' THEN NULL ELSE queued_job.failed_at_utc END,
      last_error_json = CASE WHEN queued_job.status = 'QUEUED' THEN NULL::jsonb ELSE queued_job.last_error_json END,
      payload_json = public._pay_workbench_dirty_payload_merge(
        COALESCE(queued_job.payload_json, '{}'::jsonb),
        COALESCE(EXCLUDED.payload_json, '{}'::jsonb)
        || CASE
             WHEN queued_job.status = 'RUNNING' THEN jsonb_build_object('rerun_required', true)
             ELSE '{}'::jsonb
           END
      )
  RETURNING queued_job.id, queued_job.status, queued_job.payload_json
  INTO v_job_id, v_job_status, v_job_payload;

  PERFORM public._temp_diag_log(
    'TEMP_TRIGGER_DIRTY_STAGE',
    'TEMP_BANKING_PAY_DIRTY',
    v_scope_id,
    jsonb_build_object(
      'function_name', 'pay_workbench_dirty_event_enqueue',
      'stage', CASE WHEN v_job_status = 'RUNNING' THEN 'dirty_enqueue_coalesced_existing_running' ELSE 'dirty_enqueue_inserted_or_coalesced_queued' END,
      'job_id', v_job_id::text,
      'job_type', v_job_type,
      'dedupe_key', v_dedupe_key,
      'queue_class', 'DIRTY_TRIGGER_PRIORITY',
      'priority', v_priority,
      'scope_kind', v_scope_kind,
      'scope_id', v_scope_id,
      'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
      'targeted_timesheet_count', COALESCE(array_length(v_targeted_timesheet_ids, 1), 0),
      'latest_source_change_seq', v_latest_source_change_seq,
      'rerun_required', COALESCE((v_job_payload->>'rerun_required')::boolean, false)
    )
  );

  RETURN jsonb_build_object(
    'ok', true,
    'job_id', v_job_id::text,
    'job_type', v_job_type,
    'status', v_job_status,
    'dedupe_key', v_dedupe_key,
    'queue_class', 'DIRTY_TRIGGER_PRIORITY',
    'priority', v_priority,
    'scope_kind', v_scope_kind,
    'scope_id', v_scope_id,
    'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
    'targeted_timesheet_count', COALESCE(array_length(v_targeted_timesheet_ids, 1), 0),
    'latest_source_change_seq', v_latest_source_change_seq,
    'rerun_required', COALESCE((v_job_payload->>'rerun_required')::boolean, false)
  );
END;
$function$;

ALTER FUNCTION public.pay_workbench_dirty_event_enqueue(p_job_type text, p_scope_kind text, p_scope_id text, p_candidate_id uuid, p_targeted_timesheet_ids uuid[], p_linked_timesheet_ids uuid[], p_payload_json jsonb, p_reason text, p_priority integer, p_run_at_utc timestamp with time zone) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.pay_workbench_dirty_event_enqueue(p_job_type text, p_scope_kind text, p_scope_id text, p_candidate_id uuid, p_targeted_timesheet_ids uuid[], p_linked_timesheet_ids uuid[], p_payload_json jsonb, p_reason text, p_priority integer, p_run_at_utc timestamp with time zone) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.pay_workbench_dirty_event_enqueue(p_job_type text, p_scope_kind text, p_scope_id text, p_candidate_id uuid, p_targeted_timesheet_ids uuid[], p_linked_timesheet_ids uuid[], p_payload_json jsonb, p_reason text, p_priority integer, p_run_at_utc timestamp with time zone) TO postgres;
GRANT EXECUTE ON FUNCTION public.pay_workbench_dirty_event_enqueue(p_job_type text, p_scope_kind text, p_scope_id text, p_candidate_id uuid, p_targeted_timesheet_ids uuid[], p_linked_timesheet_ids uuid[], p_payload_json jsonb, p_reason text, p_priority integer, p_run_at_utc timestamp with time zone) TO service_role;

-- -----------------------------------------------------------------------------
-- public.pay_workbench_enqueue_candidate_refresh(p_snapshot_run_id uuid, p_candidate_id uuid, p_reason text, p_actor_user_id uuid, p_payload_json jsonb)
-- Installed pg_get_functiondef MD5: 13e76063b68e27483e09c637379b04ac
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.pay_workbench_enqueue_candidate_refresh(p_snapshot_run_id uuid, p_candidate_id uuid, p_reason text DEFAULT NULL::text, p_actor_user_id uuid DEFAULT NULL::uuid, p_payload_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_payload_json jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_payload_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_payload_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_session_id uuid := NULL::uuid;
  v_session_id_text text := NULL::text;
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_actor_user_id uuid := p_actor_user_id;
  v_live_change_seq bigint := 0;
  v_payload_source_change_seq bigint := NULL::bigint;
  v_source_change_seq bigint := 0;
  v_job_type text := 'WORKBENCH_CANDIDATE_SOURCE_BUILD';
  v_refresh_scope_kind text := 'CANDIDATE_FULL_LIVE';
  v_pay_channel_scope text := 'ALL';
  v_targeted_timesheet_ids_json jsonb := '[]'::jsonb;
  v_linked_timesheet_ids_json jsonb := '[]'::jsonb;
  v_queue_identity_targeted_timesheet_ids_json jsonb := '[]'::jsonb;
  v_queue_identity_linked_timesheet_ids_json jsonb := '[]'::jsonb;
  v_source_build_run_id_text text := NULL::text;
  v_source_build_run_id uuid := NULL::uuid;
  v_source_build_hash text := NULL::text;
  v_source_build_seed_text text := NULL::text;
  v_initial_cursor_json jsonb := '{}'::jsonb;
  v_cursor_token text := 'none';
  v_session_signature_token text := 'none';
  v_stage_limit integer := 100;
  v_dedupe_key text;
  v_job_id uuid;
  v_job_status text;
  v_job_was_inserted boolean := false;
  v_insert_row_count integer := 0;
  v_reason text := COALESCE(NULLIF(BTRIM(COALESCE(p_reason, '')), ''), 'WORKBENCH_CANDIDATE_SOURCE_BUILD');
  v_payload_out_json jsonb := '{}'::jsonb;
  v_classifier_result jsonb := '{}'::jsonb;
  v_force_legacy boolean := false;
  v_force_broad_legacy boolean := false;
  v_resolved_job_type text := NULL::text;
  v_projection_run_id uuid := NULL::uuid;
  v_projection_run_id_text text := NULL::text;
  v_projection_mode text := 'LEGACY';
  v_projection_class text := 'UNKNOWN';
  v_resolved_mode text := 'LEGACY';
  v_no_job_reason text := NULL::text;
  v_delta_jobs_superseded integer := 0;
  v_delta_ids_hash text := NULL::text;
  v_delta_coalescing_key text := NULL::text;
  v_delta_coalescing_hash text := NULL::text;
  v_delta_active_running_job_id uuid := NULL::uuid;
  v_existing_delta_job public.banking_pay_workbench_jobs%ROWTYPE;
  v_existing_delta_source_change_seq bigint := 0;
  v_existing_delta_event_count integer := 0;
  v_merged_delta_event_count integer := 1;
  v_existing_delta_projection_run_id_text text := NULL::text;
  v_delta_merge_reused_existing boolean := false;
  v_payload_shadow_compare_required boolean := false;
  v_payload_shadow_compare_enforced boolean := false;
  v_rotation_scope_json jsonb := '{}'::jsonb;
  v_early_preflight_result jsonb := '{}'::jsonb;
  v_early_preflight_action text := 'PROCEED';
  v_early_preflight_targeted_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_early_preflight_linked_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_shadow_compare_required boolean := false;
  v_shadow_compare_enforced boolean := false;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  IF p_snapshot_run_id IS NULL THEN
    RAISE EXCEPTION 'snapshot_run_id is required';
  END IF;

  IF p_candidate_id IS NULL THEN
    RAISE EXCEPTION 'candidate_id is required';
  END IF;

  PERFORM 1
  FROM public.banking_pay_snapshot_runs AS snapshot_run
  WHERE snapshot_run.id = p_snapshot_run_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'banking_pay_snapshot_runs row % not found', p_snapshot_run_id;
  END IF;

  PERFORM 1
  FROM public.candidates AS candidate_row
  WHERE candidate_row.id = p_candidate_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'candidates row % not found', p_candidate_id;
  END IF;

  v_session_id_text := NULLIF(BTRIM(COALESCE(
    v_payload_json->>'session_id',
    v_payload_json->>'source_session_id',
    v_payload_json->>'workbench_session_id',
    v_payload_json#>>'{workbench,session_id}',
    ''
  )), '');

  IF v_session_id_text IS NULL THEN
    RETURN jsonb_build_object(
      'ok', true,
      'job_id', NULL::text,
      'job_type', NULL::text,
      'canonical_job_type', NULL::text,
      'snapshot_run_id', p_snapshot_run_id::text,
      'session_id', NULL::text,
      'candidate_id', p_candidate_id::text,
      'source_change_seq', 0,
      'source_build_required', true,
      'line_work_required', true,
      'delta_refresh_required', false,
      'full_snapshot_job', false,
      'no_op', true,
      'deferred', true,
      'requires_workbench_session', true,
      'reason', v_reason,
      'message', 'Banking Pay candidate refresh now requires a row-backed workbench session.'
    );
  END IF;

  IF v_session_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_ENQUEUE_CANDIDATE_REFRESH_SESSION_ID_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_ENQUEUE_CANDIDATE_REFRESH_SESSION_ID_INVALID',
              'session_id', v_session_id_text,
              'candidate_id', p_candidate_id::text
            )::text;
  END IF;

  v_session_id := v_session_id_text::uuid;

  SELECT COALESCE(array_agg(DISTINCT parsed_target_ids.timesheet_id_value ORDER BY parsed_target_ids.timesheet_id_value), ARRAY[]::uuid[])
  INTO v_early_preflight_targeted_timesheet_ids
  FROM (
    SELECT NULLIF(BTRIM(targeted_values.value), '')::uuid AS timesheet_id_value
    FROM jsonb_array_elements_text(
      CASE
        WHEN jsonb_typeof(v_payload_json->'targeted_timesheet_ids') = 'array' THEN v_payload_json->'targeted_timesheet_ids'
        WHEN jsonb_typeof(v_payload_json#>'{source_build,targeted_timesheet_ids}') = 'array' THEN v_payload_json#>'{source_build,targeted_timesheet_ids}'
        WHEN jsonb_typeof(v_payload_json#>'{preview_decisions_json,targeted_timesheet_ids}') = 'array' THEN v_payload_json#>'{preview_decisions_json,targeted_timesheet_ids}'
        WHEN jsonb_typeof(v_payload_json->'targeted_timesheet_ids') = 'string' THEN jsonb_build_array(v_payload_json->>'targeted_timesheet_ids')
        WHEN jsonb_typeof(v_payload_json#>'{source_build,targeted_timesheet_ids}') = 'string' THEN jsonb_build_array(v_payload_json#>>'{source_build,targeted_timesheet_ids}')
        WHEN jsonb_typeof(v_payload_json#>'{preview_decisions_json,targeted_timesheet_ids}') = 'string' THEN jsonb_build_array(v_payload_json#>>'{preview_decisions_json,targeted_timesheet_ids}')
        ELSE '[]'::jsonb
      END
    ) AS targeted_values(value)
    WHERE NULLIF(BTRIM(targeted_values.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) AS parsed_target_ids;

  SELECT COALESCE(array_agg(DISTINCT parsed_linked_ids.timesheet_id_value ORDER BY parsed_linked_ids.timesheet_id_value), ARRAY[]::uuid[])
  INTO v_early_preflight_linked_timesheet_ids
  FROM (
    SELECT NULLIF(BTRIM(linked_values.value), '')::uuid AS timesheet_id_value
    FROM jsonb_array_elements_text(
      CASE
        WHEN jsonb_typeof(v_payload_json->'linked_timesheet_ids') = 'array' THEN v_payload_json->'linked_timesheet_ids'
        WHEN jsonb_typeof(v_payload_json#>'{source_build,linked_timesheet_ids}') = 'array' THEN v_payload_json#>'{source_build,linked_timesheet_ids}'
        WHEN jsonb_typeof(v_payload_json#>'{preview_decisions_json,linked_timesheet_ids}') = 'array' THEN v_payload_json#>'{preview_decisions_json,linked_timesheet_ids}'
        WHEN jsonb_typeof(v_payload_json->'linked_timesheet_ids') = 'string' THEN jsonb_build_array(v_payload_json->>'linked_timesheet_ids')
        WHEN jsonb_typeof(v_payload_json#>'{source_build,linked_timesheet_ids}') = 'string' THEN jsonb_build_array(v_payload_json#>>'{source_build,linked_timesheet_ids}')
        WHEN jsonb_typeof(v_payload_json#>'{preview_decisions_json,linked_timesheet_ids}') = 'string' THEN jsonb_build_array(v_payload_json#>>'{preview_decisions_json,linked_timesheet_ids}')
        ELSE '[]'::jsonb
      END
    ) AS linked_values(value)
    WHERE NULLIF(BTRIM(linked_values.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) AS parsed_linked_ids;

  IF COALESCE(array_length(v_early_preflight_targeted_timesheet_ids, 1), 0) > 0 THEN
    SELECT public.pay_workbench_authorise_delta_hotkey_preflight(
      p_session_id => v_session_id,
      p_candidate_id => p_candidate_id,
      p_targeted_timesheet_ids => v_early_preflight_targeted_timesheet_ids,
      p_linked_timesheet_ids => v_early_preflight_linked_timesheet_ids,
      p_payload_json => v_payload_json || jsonb_build_object(
        'session_id', v_session_id::text,
        'source_session_id', v_session_id::text,
        'candidate_id', p_candidate_id::text,
        'snapshot_run_id', p_snapshot_run_id::text,
        'source_snapshot_run_id', p_snapshot_run_id::text,
        'refresh_scope_kind', 'TARGETED_TIMESHEETS',
        'projection_mode', 'DELTA',
        'projection_class', 'NORMAL_TIMESHEET',
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
      ),
      p_reason => v_reason,
      p_actor_user_id => v_actor_user_id,
      p_source_change_seq => NULL::bigint
    ) INTO v_early_preflight_result;

    v_early_preflight_action := COALESCE(v_early_preflight_result->>'action', 'PROCEED');

    IF v_early_preflight_action IN ('REUSED_QUEUED_SAME_FAMILY_JOB', 'UPDATED_WAITING_AFTER_RUNNING_JOB') THEN
      RETURN jsonb_strip_nulls(jsonb_build_object(
        'ok', true,
        'job_id', NULLIF(BTRIM(COALESCE(v_early_preflight_result->>'job_id', '')), ''),
        'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'canonical_job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'resolved_mode', 'DELTA',
        'snapshot_run_id', p_snapshot_run_id::text,
        'session_id', v_session_id::text,
        'candidate_id', p_candidate_id::text,
        'source_change_seq', CASE WHEN COALESCE(v_early_preflight_result->>'latest_source_change_seq', '') ~ '^[0-9]{1,18}$' THEN (v_early_preflight_result->>'latest_source_change_seq')::bigint ELSE NULL::bigint END,
        'dedupe_key', NULLIF(BTRIM(COALESCE(v_early_preflight_result->>'normalised_delta_family_key', '')), ''),
        'reason', v_reason,
        'refresh_scope_kind', 'TARGETED_TIMESHEETS',
        'targeted_timesheet_ids', COALESCE(v_early_preflight_result->'targeted_timesheet_ids', '[]'::jsonb),
        'linked_timesheet_ids', COALESCE(v_early_preflight_result->'linked_timesheet_ids', '[]'::jsonb),
        'queue_identity_targeted_timesheet_ids', COALESCE(v_early_preflight_result->'queue_identity_targeted_timesheet_ids', v_early_preflight_result->'resolved_family_timesheet_ids', v_early_preflight_result->'targeted_timesheet_ids', '[]'::jsonb),
        'queue_identity_linked_timesheet_ids', COALESCE(v_early_preflight_result->'queue_identity_linked_timesheet_ids', '[]'::jsonb),
        'source_build_required', false,
        'line_work_required', false,
        'line_work_only', false,
        'delta_refresh_required', true,
        'scope_status', 'DELTA_REFRESH_PENDING',
        'projection_mode', 'DELTA',
        'projection_class', 'NORMAL_TIMESHEET',
        'full_snapshot_job', false,
        'reused', true,
        'early_preflight_action', v_early_preflight_action,
        'early_preflight_result', COALESCE(v_early_preflight_result, '{}'::jsonb),
        'early_preflight_returned_before_session_lock', true,
        'session_lock_skipped', true,
        'scope_lock_skipped', true,
        'classifier_work_skipped', true,
        'dirty_marking_skipped', true,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
      ));
    END IF;
  END IF;

  SELECT session_row.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = v_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'banking_pay_workbench_sessions row % not found', v_session_id;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_session_row.status, ''))) <> 'OPEN'
     OR v_session_row.discarded_at_utc IS NOT NULL THEN
    RAISE EXCEPTION 'banking_pay_workbench_session % is not open', v_session_id;
  END IF;

  IF v_session_row.source_snapshot_run_id IS DISTINCT FROM p_snapshot_run_id THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_ENQUEUE_CANDIDATE_REFRESH_SNAPSHOT_MISMATCH'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_ENQUEUE_CANDIDATE_REFRESH_SNAPSHOT_MISMATCH',
              'session_id', v_session_id::text,
              'payload_snapshot_run_id', p_snapshot_run_id::text,
              'session_snapshot_run_id', v_session_row.source_snapshot_run_id::text
            )::text;
  END IF;

  PERFORM 1
  FROM public.banking_pay_workbench_session_scope AS session_scope
  WHERE session_scope.session_id = v_session_id
    AND session_scope.candidate_id = p_candidate_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'candidate % is not in workbench session scope %', p_candidate_id, v_session_id;
  END IF;

  v_actor_user_id := COALESCE(v_actor_user_id, v_session_row.actor_user_id);

  SELECT COALESCE(change_counter.seq, 0)
  INTO v_live_change_seq
  FROM public.app_change_counters AS change_counter
  WHERE change_counter.entity_key = 'pay_candidate:' || p_candidate_id::text;

  IF COALESCE(v_payload_json->>'source_change_seq', '') ~ '^[0-9]{1,18}$' THEN
    v_payload_source_change_seq := (v_payload_json->>'source_change_seq')::bigint;
  ELSIF COALESCE(v_payload_json->>'source_change_sequence', '') ~ '^[0-9]{1,18}$' THEN
    v_payload_source_change_seq := (v_payload_json->>'source_change_sequence')::bigint;
  ELSIF COALESCE(v_payload_json#>>'{source_build,source_change_seq}', '') ~ '^[0-9]{1,18}$' THEN
    v_payload_source_change_seq := (v_payload_json#>>'{source_build,source_change_seq}')::bigint;
  END IF;

  v_source_change_seq := GREATEST(COALESCE(v_payload_source_change_seq, 0), COALESCE(v_live_change_seq, 0));

  SELECT COALESCE(jsonb_agg(parsed_target_ids.timesheet_id_text ORDER BY parsed_target_ids.timesheet_id_text), '[]'::jsonb)
  INTO v_targeted_timesheet_ids_json
  FROM (
    SELECT DISTINCT NULLIF(BTRIM(targeted_values.value), '') AS timesheet_id_text
    FROM jsonb_array_elements_text(
      CASE
        WHEN jsonb_typeof(v_payload_json->'targeted_timesheet_ids') = 'array' THEN v_payload_json->'targeted_timesheet_ids'
        WHEN jsonb_typeof(v_payload_json#>'{source_build,targeted_timesheet_ids}') = 'array' THEN v_payload_json#>'{source_build,targeted_timesheet_ids}'
        WHEN jsonb_typeof(v_payload_json#>'{preview_decisions_json,targeted_timesheet_ids}') = 'array' THEN v_payload_json#>'{preview_decisions_json,targeted_timesheet_ids}'
        WHEN jsonb_typeof(v_payload_json->'targeted_timesheet_ids') = 'string' THEN jsonb_build_array(v_payload_json->>'targeted_timesheet_ids')
        WHEN jsonb_typeof(v_payload_json#>'{source_build,targeted_timesheet_ids}') = 'string' THEN jsonb_build_array(v_payload_json#>>'{source_build,targeted_timesheet_ids}')
        WHEN jsonb_typeof(v_payload_json#>'{preview_decisions_json,targeted_timesheet_ids}') = 'string' THEN jsonb_build_array(v_payload_json#>>'{preview_decisions_json,targeted_timesheet_ids}')
        ELSE '[]'::jsonb
      END
    ) AS targeted_values(value)
    WHERE NULLIF(BTRIM(targeted_values.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) AS parsed_target_ids;

  SELECT COALESCE(jsonb_agg(parsed_linked_ids.timesheet_id_text ORDER BY parsed_linked_ids.timesheet_id_text), '[]'::jsonb)
  INTO v_linked_timesheet_ids_json
  FROM (
    SELECT DISTINCT NULLIF(BTRIM(linked_values.value), '') AS timesheet_id_text
    FROM jsonb_array_elements_text(
      CASE
        WHEN jsonb_typeof(v_payload_json->'linked_timesheet_ids') = 'array' THEN v_payload_json->'linked_timesheet_ids'
        WHEN jsonb_typeof(v_payload_json#>'{source_build,linked_timesheet_ids}') = 'array' THEN v_payload_json#>'{source_build,linked_timesheet_ids}'
        WHEN jsonb_typeof(v_payload_json#>'{preview_decisions_json,linked_timesheet_ids}') = 'array' THEN v_payload_json#>'{preview_decisions_json,linked_timesheet_ids}'
        WHEN jsonb_typeof(v_payload_json->'linked_timesheet_ids') = 'string' THEN jsonb_build_array(v_payload_json->>'linked_timesheet_ids')
        WHEN jsonb_typeof(v_payload_json#>'{source_build,linked_timesheet_ids}') = 'string' THEN jsonb_build_array(v_payload_json#>>'{source_build,linked_timesheet_ids}')
        WHEN jsonb_typeof(v_payload_json#>'{preview_decisions_json,linked_timesheet_ids}') = 'string' THEN jsonb_build_array(v_payload_json#>>'{preview_decisions_json,linked_timesheet_ids}')
        ELSE '[]'::jsonb
      END
    ) AS linked_values(value)
    WHERE NULLIF(BTRIM(linked_values.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) AS parsed_linked_ids;

  v_refresh_scope_kind := NULLIF(UPPER(BTRIM(COALESCE(
    v_payload_json->>'refresh_scope_kind',
    v_payload_json#>>'{source_build,refresh_scope_kind}',
    v_payload_json#>>'{preview_decisions_json,refresh_scope_kind}',
    ''
  ))), '');

  IF v_refresh_scope_kind IS NULL OR v_refresh_scope_kind NOT IN ('TARGETED_TIMESHEETS', 'CANDIDATE_FULL_LIVE') THEN
    v_refresh_scope_kind := CASE
      WHEN jsonb_array_length(COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb)) > 0
        OR jsonb_array_length(COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb)) > 0
      THEN 'TARGETED_TIMESHEETS'
      ELSE 'CANDIDATE_FULL_LIVE'
    END;
  END IF;


  v_queue_identity_targeted_timesheet_ids_json := COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb);
  v_queue_identity_linked_timesheet_ids_json := COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb);

  IF v_refresh_scope_kind = 'TARGETED_TIMESHEETS'
     AND jsonb_array_length(COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb)) > 0
     AND to_regprocedure('public._pay_workbench_normalise_timesheet_rotation_scope_payload(uuid[],uuid[])') IS NOT NULL THEN
    SELECT public._pay_workbench_normalise_timesheet_rotation_scope_payload(
      COALESCE((
        SELECT array_agg(DISTINCT targeted_value.value::uuid ORDER BY targeted_value.value::uuid)
        FROM jsonb_array_elements_text(COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb)) AS targeted_value(value)
        WHERE targeted_value.value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      ), ARRAY[]::uuid[]),
      COALESCE((
        SELECT array_agg(DISTINCT linked_value.value::uuid ORDER BY linked_value.value::uuid)
        FROM jsonb_array_elements_text(COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb)) AS linked_value(value)
        WHERE linked_value.value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      ), ARRAY[]::uuid[])
    )
    INTO v_rotation_scope_json;

    v_payload_json := public._pay_workbench_merge_targeted_scope_payload(
      v_payload_json,
      jsonb_build_object(
        'targeted_timesheet_ids_requested', COALESCE(v_rotation_scope_json->'requested_targeted_timesheet_ids', v_targeted_timesheet_ids_json),
        'linked_timesheet_ids_requested', COALESCE(v_rotation_scope_json->'requested_linked_timesheet_ids', v_linked_timesheet_ids_json),
        'requested_timesheet_ids', COALESCE(v_rotation_scope_json->'requested_timesheet_ids', v_targeted_timesheet_ids_json),
        'family_timesheet_ids', COALESCE(v_rotation_scope_json->'family_timesheet_ids', v_targeted_timesheet_ids_json),
        'targeted_timesheet_ids', COALESCE(v_rotation_scope_json->'targeted_timesheet_ids', v_targeted_timesheet_ids_json),
        'linked_timesheet_ids', COALESCE(v_rotation_scope_json->'linked_timesheet_ids', v_linked_timesheet_ids_json, '[]'::jsonb),
        'queue_identity_targeted_timesheet_ids', COALESCE(v_rotation_scope_json->'queue_identity_targeted_timesheet_ids', v_rotation_scope_json->'family_timesheet_ids', v_targeted_timesheet_ids_json),
        'queue_identity_linked_timesheet_ids', COALESCE(v_rotation_scope_json->'queue_identity_linked_timesheet_ids', '[]'::jsonb),
        'queue_identity_timesheet_ids', COALESCE(v_rotation_scope_json->'queue_identity_timesheet_ids', v_rotation_scope_json->'family_timesheet_ids', v_targeted_timesheet_ids_json),
        'rotation_family_scope_for_queue_identity', true,
        'queue_identity_preserves_targeted_linked_semantics', true,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
      )
    );
    v_targeted_timesheet_ids_json := COALESCE(v_rotation_scope_json->'targeted_timesheet_ids', v_targeted_timesheet_ids_json);
    v_linked_timesheet_ids_json := COALESCE(v_rotation_scope_json->'linked_timesheet_ids', v_linked_timesheet_ids_json, '[]'::jsonb);
    v_queue_identity_targeted_timesheet_ids_json := COALESCE(v_rotation_scope_json->'queue_identity_targeted_timesheet_ids', v_rotation_scope_json->'family_timesheet_ids', v_targeted_timesheet_ids_json, '[]'::jsonb);
    v_queue_identity_linked_timesheet_ids_json := COALESCE(v_rotation_scope_json->'queue_identity_linked_timesheet_ids', '[]'::jsonb);
  END IF;

  v_pay_channel_scope := NULLIF(UPPER(BTRIM(COALESCE(
    v_payload_json->>'pay_channel_scope',
    v_payload_json#>>'{source_build,pay_channel_scope}',
    v_payload_json#>>'{preview_decisions_json,pay_channel_scope}',
    v_session_row.filters_json->>'pay_channel_scope',
    v_session_row.filters_json#>>'{filters,pay_channel_scope}',
    'ALL'
  ))), '');

  IF v_pay_channel_scope NOT IN ('PAYE', 'UMBRELLA', 'ALL', 'LOANS') THEN
    v_pay_channel_scope := 'ALL';
  END IF;

  v_force_legacy := lower(BTRIM(COALESCE(v_payload_json->>'force_legacy', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_force_broad_legacy := lower(BTRIM(COALESCE(v_payload_json->>'force_broad_legacy', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');

  IF jsonb_typeof(v_payload_json->'classifier_result') = 'object' THEN
    v_classifier_result := v_payload_json->'classifier_result';
  ELSIF v_payload_json ? 'fast_path_allowed' OR v_payload_json ? 'resolved_job_type' THEN
    v_classifier_result := v_payload_json;
  ELSIF to_regprocedure('public.pay_workbench_delta_refresh_classify_v1(uuid,uuid,jsonb)') IS NOT NULL THEN
    v_classifier_result := public.pay_workbench_delta_refresh_classify_v1(
      v_session_id,
      p_candidate_id,
      v_payload_json
      || jsonb_build_object(
        'session_id', v_session_id::text,
        'candidate_id', p_candidate_id::text,
        'session_version', COALESCE(v_session_row.version, 0),
        'source_change_seq', COALESCE(v_source_change_seq, 0),
        'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
        'targeted_timesheet_ids', COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb),
        'linked_timesheet_ids', COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb),
        'pay_channel_scope', v_pay_channel_scope,
        'force_legacy', v_force_legacy,
        'force_broad_legacy', v_force_broad_legacy
      )
    );
  ELSE
    v_classifier_result := jsonb_build_object(
      'ok', true,
      'fast_path_allowed', false,
      'resolved_job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
      'projection_mode', 'LEGACY',
      'projection_class', COALESCE(NULLIF(UPPER(BTRIM(COALESCE(v_payload_json->>'projection_class', ''))), ''), 'UNKNOWN_TRIGGER'),
      'scope_status', 'SOURCE_BUILD_PENDING',
      'fallback_required', true,
      'fallback_reason', 'DELTA_CLASSIFIER_NOT_INSTALLED'
    );
  END IF;

  v_classifier_result := COALESCE(v_classifier_result, '{}'::jsonb)
    - 'old_row_json'
    - 'new_row_json'
    - 'old_row'
    - 'new_row'
    - 'source_row_json'
    - 'work_payload_json'
    - 'result_row_json'
    - 'preview_row_json'
    - 'row_payload_json'
    - 'line_payload_json'
    - 'projection_rows'
    - 'projected_rows';

  v_resolved_mode := UPPER(BTRIM(COALESCE(v_classifier_result->>'resolved_mode', v_classifier_result->>'routing_decision', v_classifier_result->>'projection_mode', 'LEGACY')));
  IF v_resolved_mode NOT IN ('DELTA', 'PATCH_ONLY', 'CLONE_REBASE', 'LEGACY', 'BLOCKED') THEN
    v_resolved_mode := 'LEGACY';
  END IF;

  v_resolved_job_type := UPPER(BTRIM(COALESCE(v_classifier_result->>'resolved_job_type', CASE WHEN v_resolved_mode = 'DELTA' THEN 'WORKBENCH_CANDIDATE_DELTA_REFRESH' WHEN v_resolved_mode = 'LEGACY' THEN 'WORKBENCH_CANDIDATE_SOURCE_BUILD' ELSE 'NOOP' END)));
  v_projection_mode := UPPER(BTRIM(COALESCE(v_classifier_result->>'projection_mode', v_payload_json->>'projection_mode', 'LEGACY')));
  v_projection_class := UPPER(BTRIM(COALESCE(v_classifier_result->>'projection_class', v_payload_json->>'projection_class', 'UNKNOWN')));

  IF jsonb_typeof(v_classifier_result->'targeted_timesheet_ids') = 'array' THEN
    v_targeted_timesheet_ids_json := v_classifier_result->'targeted_timesheet_ids';
  END IF;
  IF jsonb_typeof(v_classifier_result->'linked_timesheet_ids') = 'array' THEN
    v_linked_timesheet_ids_json := v_classifier_result->'linked_timesheet_ids';
  END IF;

  IF jsonb_typeof(v_payload_json->'queue_identity_targeted_timesheet_ids') = 'array' THEN
    v_queue_identity_targeted_timesheet_ids_json := COALESCE(v_payload_json->'queue_identity_targeted_timesheet_ids', v_queue_identity_targeted_timesheet_ids_json, '[]'::jsonb);
  ELSIF jsonb_array_length(COALESCE(v_queue_identity_targeted_timesheet_ids_json, '[]'::jsonb)) = 0 THEN
    v_queue_identity_targeted_timesheet_ids_json := COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb);
  END IF;

  IF jsonb_typeof(v_payload_json->'queue_identity_linked_timesheet_ids') = 'array' THEN
    v_queue_identity_linked_timesheet_ids_json := COALESCE(v_payload_json->'queue_identity_linked_timesheet_ids', '[]'::jsonb);
  ELSIF jsonb_array_length(COALESCE(v_queue_identity_linked_timesheet_ids_json, '[]'::jsonb)) = 0 THEN
    v_queue_identity_linked_timesheet_ids_json := COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb);
  END IF;

  IF v_force_legacy IS TRUE OR v_force_broad_legacy IS TRUE THEN
    v_resolved_mode := 'LEGACY';
    v_resolved_job_type := 'WORKBENCH_CANDIDATE_SOURCE_BUILD';
  END IF;

  v_payload_shadow_compare_required := lower(BTRIM(COALESCE(
    v_payload_json->>'shadow_compare_required',
    v_payload_json->>'shadow_compare',
    v_payload_json->>'shadow_mode',
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');

  v_payload_shadow_compare_enforced := lower(BTRIM(COALESCE(
    v_payload_json->>'shadow_compare_enforced',
    v_payload_json->>'enforce_shadow_compare',
    v_payload_json->>'shadow_enforced',
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');

  v_shadow_compare_required := (
    lower(BTRIM(COALESCE(v_classifier_result#>>'{complexity_flags,delta_shadow_mode}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR lower(BTRIM(COALESCE(v_classifier_result#>>'{complexity_flags,payload_shadow_mode}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR lower(BTRIM(COALESCE(v_classifier_result->>'shadow_compare_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR v_payload_shadow_compare_required
  );

  v_shadow_compare_enforced := COALESCE(v_shadow_compare_required, false) AND (
    COALESCE(v_payload_shadow_compare_enforced, false)
    OR lower(BTRIM(COALESCE(v_classifier_result->>'shadow_compare_enforced', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
  );

  IF v_resolved_mode IN ('PATCH_ONLY', 'CLONE_REBASE', 'BLOCKED') THEN
    v_no_job_reason := CASE
      WHEN v_resolved_mode = 'PATCH_ONLY' THEN COALESCE(NULLIF(v_classifier_result->>'fallback_reason', ''), 'PATCH_ONLY_NO_SOURCE_BUILD_JOB')
      WHEN v_resolved_mode = 'CLONE_REBASE' THEN COALESCE(NULLIF(v_classifier_result->>'fallback_reason', ''), 'CLONE_REBASE_NOT_A_CANDIDATE_SOURCE_BUILD_JOB')
      ELSE COALESCE(NULLIF(v_classifier_result->>'fallback_reason', ''), 'CLASSIFIER_BLOCKED_REFRESH')
    END;

    UPDATE public.banking_pay_workbench_session_scope AS no_job_scope
    SET status = CASE
          WHEN v_resolved_mode = 'PATCH_ONLY' THEN COALESCE(NULLIF(v_classifier_result->>'scope_status', ''), 'PATCH_ONLY_PENDING')
          WHEN v_resolved_mode = 'CLONE_REBASE' THEN COALESCE(NULLIF(v_classifier_result->>'scope_status', ''), 'CLONE_REBASE_PENDING')
          ELSE COALESCE(NULLIF(v_classifier_result->>'scope_status', ''), no_job_scope.status)
        END,
        pending_job_id = NULL,
        dirty = false,
        error_json = NULL::jsonb,
        updated_at_utc = v_now
    WHERE no_job_scope.session_id = v_session_id
      AND no_job_scope.candidate_id = p_candidate_id
      AND v_resolved_mode IN ('PATCH_ONLY', 'CLONE_REBASE');

    RETURN jsonb_strip_nulls(jsonb_build_object(
      'ok', true,
      'job_id', NULL::text,
      'job_type', NULL::text,
      'canonical_job_type', NULL::text,
      'snapshot_run_id', p_snapshot_run_id::text,
      'session_id', v_session_id::text,
      'candidate_id', p_candidate_id::text,
      'session_version', COALESCE(v_session_row.version, 0),
      'source_change_seq', COALESCE(v_source_change_seq, 0),
      'reason', v_reason,
      'resolved_mode', v_resolved_mode,
      'projection_mode', v_projection_mode,
      'projection_class', v_projection_class,
      'refresh_scope_kind', v_refresh_scope_kind,
      'targeted_timesheet_ids', COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb),
      'linked_timesheet_ids', COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb),
      'pay_channel_scope', v_pay_channel_scope,
      'source_build_required', false,
      'line_work_required', false,
      'line_work_only', false,
      'delta_refresh_required', false,
      'patch_only', v_resolved_mode = 'PATCH_ONLY',
      'clone_rebase_required', v_resolved_mode = 'CLONE_REBASE',
      'blocked', v_resolved_mode = 'BLOCKED',
      'no_op', v_resolved_mode = 'BLOCKED',
      'deferred', v_resolved_mode = 'CLONE_REBASE',
      'fallback_required', lower(BTRIM(COALESCE(v_classifier_result->>'fallback_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
      'fallback_reason', v_no_job_reason,
      'classifier_result', v_classifier_result
    ));
  END IF;

  IF v_resolved_mode = 'DELTA'
     AND v_resolved_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
     AND lower(BTRIM(COALESCE(v_classifier_result->>'fast_path_allowed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
     AND v_force_legacy IS NOT TRUE
     AND v_force_broad_legacy IS NOT TRUE THEN
    v_job_type := 'WORKBENCH_CANDIDATE_DELTA_REFRESH';
  ELSE
    v_resolved_mode := 'LEGACY';
    v_job_type := 'WORKBENCH_CANDIDATE_SOURCE_BUILD';
  END IF;

  IF COALESCE(v_payload_json->>'source_build_limit', '') ~ '^[0-9]{1,9}$' THEN
    v_stage_limit := LEAST(GREATEST((v_payload_json->>'source_build_limit')::integer, 1), 100);
  ELSIF COALESCE(v_payload_json#>>'{stage_limits,source_build}', '') ~ '^[0-9]{1,9}$' THEN
    v_stage_limit := LEAST(GREATEST((v_payload_json#>>'{stage_limits,source_build}')::integer, 1), 100);
  ELSIF COALESCE(v_payload_json->>'limit', '') ~ '^[0-9]{1,9}$' THEN
    v_stage_limit := LEAST(GREATEST((v_payload_json->>'limit')::integer, 1), 100);
  ELSE
    SELECT LEAST(GREATEST(COALESCE(
      CASE
        WHEN COALESCE(to_jsonb(settings_row)->>'banking_pay_workbench_source_build_units_per_job', '') ~ '^[0-9]{1,9}$'
          THEN (to_jsonb(settings_row)->>'banking_pay_workbench_source_build_units_per_job')::integer
        ELSE NULL::integer
      END,
      CASE
        WHEN COALESCE(to_jsonb(settings_row)->>'banking_pay_workbench_stage_work_units_per_job', '') ~ '^[0-9]{1,9}$'
          THEN (to_jsonb(settings_row)->>'banking_pay_workbench_stage_work_units_per_job')::integer
        ELSE NULL::integer
      END,
      25
    ), 1), 100)
    INTO v_stage_limit
    FROM public.settings_defaults AS settings_row
    WHERE settings_row.id = 1
    LIMIT 1;

    v_stage_limit := COALESCE(v_stage_limit, 25);
  END IF;

  v_initial_cursor_json := CASE
    WHEN jsonb_typeof(v_payload_json->'cursor_json') = 'object' THEN v_payload_json->'cursor_json'
    WHEN jsonb_typeof(v_payload_json->'cursor') = 'object' THEN v_payload_json->'cursor'
    WHEN jsonb_typeof(v_payload_json->'source_cursor') = 'object' THEN v_payload_json->'source_cursor'
    WHEN jsonb_typeof(v_payload_json#>'{source_build,cursor}') = 'object' THEN v_payload_json#>'{source_build,cursor}'
    ELSE '{}'::jsonb
  END;

  v_cursor_token := md5(COALESCE(v_initial_cursor_json, '{}'::jsonb)::text);
  v_session_signature_token := md5(COALESCE(v_session_row.session_signature, ''));

  IF v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN
    v_projection_run_id_text := NULLIF(BTRIM(COALESCE(v_payload_json->>'projection_run_id', v_classifier_result->>'projection_run_id', '')), '');
    IF v_projection_run_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_projection_run_id := v_projection_run_id_text::uuid;
    ELSE
      v_projection_run_id := gen_random_uuid();
    END IF;

    v_delta_ids_hash := md5(
      COALESCE(v_queue_identity_targeted_timesheet_ids_json, v_targeted_timesheet_ids_json, '[]'::jsonb)::text
      || ':'
      || COALESCE(v_queue_identity_linked_timesheet_ids_json, v_linked_timesheet_ids_json, '[]'::jsonb)::text
    );

    v_delta_coalescing_key := 'WORKBENCH_CANDIDATE_DELTA_REFRESH_FAMILY'
    || ':session:' || COALESCE(v_session_id::text, 'none')
    || ':version:' || COALESCE(COALESCE(v_session_row.version, 0), 0)::text
    || ':projection_mode:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(NULLIF(COALESCE(NULLIF(v_projection_mode, 'LEGACY'), 'DELTA'), ''), 'DELTA'))), ''), 'DELTA')
    || ':projection_class:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(NULLIF(v_projection_class, ''), 'UNKNOWN'))), ''), 'UNKNOWN')
    || ':refresh_scope:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(NULLIF(COALESCE(NULLIF(v_refresh_scope_kind, 'CANDIDATE_FULL_LIVE'), 'TARGETED_TIMESHEETS'), ''), 'TARGETED_TIMESHEETS'))), ''), 'TARGETED_TIMESHEETS')
    || ':candidate:' || COALESCE(p_candidate_id::text, 'none')
    || ':timesheets:' || COALESCE(v_delta_ids_hash, md5('[]:[]'));
    v_delta_coalescing_hash := md5(v_delta_coalescing_key);

    SELECT running_delta_job.id
    INTO v_delta_active_running_job_id
    FROM public.banking_pay_workbench_jobs AS running_delta_job
    WHERE running_delta_job.session_id = v_session_id
      AND running_delta_job.candidate_id = p_candidate_id
      AND UPPER(BTRIM(COALESCE(running_delta_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
      AND UPPER(BTRIM(COALESCE(running_delta_job.status, ''))) = 'RUNNING'
      AND (
        COALESCE(running_delta_job.payload_json->>'normalised_delta_family_key', running_delta_job.payload_json->>'delta_family_key', running_delta_job.payload_json->>'delta_coalescing_key', '') = v_delta_coalescing_key
        OR (
            SELECT
              'WORKBENCH_CANDIDATE_DELTA_REFRESH_FAMILY'
              || ':session:' || COALESCE(NULLIF(BTRIM(COALESCE(
                running_delta_job.session_id::text,
                (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'session_id',
                (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'workbench_session_id',
                (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'source_session_id',
                (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'target_session_id',
                ''
              )), ''), 'none')
              || ':version:' || COALESCE(
                CASE
                  WHEN delta_family_values.session_version_text ~ '^-?[0-9]{1,18}$'
                    THEN delta_family_values.session_version_text::bigint
                  ELSE COALESCE(COALESCE(v_session_row.version, 0), 0)::bigint
                END,
                0
              )::text
              || ':projection_mode:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
                NULLIF(delta_family_values.projection_mode_text, ''),
                NULLIF(COALESCE(NULLIF(v_projection_mode, 'LEGACY'), 'DELTA'), ''),
                'DELTA'
              ))), ''), 'DELTA')
              || ':projection_class:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
                NULLIF(delta_family_values.projection_class_text, ''),
                NULLIF(v_projection_class, ''),
                'UNKNOWN'
              ))), ''), 'UNKNOWN')
              || ':refresh_scope:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
                NULLIF(delta_family_values.refresh_scope_kind_text, ''),
                NULLIF(COALESCE(NULLIF(v_refresh_scope_kind, 'CANDIDATE_FULL_LIVE'), 'TARGETED_TIMESHEETS'), ''),
                CASE
                  WHEN jsonb_array_length(COALESCE(delta_family_targeted.targeted_timesheet_ids_json, '[]'::jsonb)) > 0
                    OR jsonb_array_length(COALESCE(delta_family_linked.linked_timesheet_ids_json, '[]'::jsonb)) > 0
                    THEN 'TARGETED_TIMESHEETS'
                  ELSE 'CANDIDATE_FULL_LIVE'
                END
              ))), ''), 'CANDIDATE_FULL_LIVE')
              || ':candidate:' || COALESCE(NULLIF(BTRIM(COALESCE(
                running_delta_job.candidate_id::text,
                (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'candidate_id',
                ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>>'{candidate,id}'),
                ''
              )), ''), 'none')
              || ':timesheets:' || md5(
                COALESCE(delta_family_targeted.targeted_timesheet_ids_json, '[]'::jsonb)::text
                || ':'
                || COALESCE(delta_family_linked.linked_timesheet_ids_json, '[]'::jsonb)::text
              )
            FROM (
              SELECT
                NULLIF(BTRIM(COALESCE(
                  (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'session_version',
                  (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'workbench_session_version',
                  (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'version',
                  CASE WHEN COALESCE(v_session_row.version, 0) IS NULL THEN NULL ELSE (COALESCE(v_session_row.version, 0))::text END,
                  '0'
                )), '') AS session_version_text,
                UPPER(BTRIM(COALESCE(
                  NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'projection_mode', ''),
                  NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'resolved_mode', ''),
                  NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'mode', ''),
                  NULLIF(COALESCE(NULLIF(v_projection_mode, 'LEGACY'), 'DELTA'), ''),
                  'DELTA'
                ))) AS projection_mode_text,
                UPPER(BTRIM(COALESCE(
                  NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'projection_class', ''),
                  NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'classifier_projection_class', ''),
                  NULLIF(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>>'{classifier_result,projection_class}'), ''),
                  NULLIF(v_projection_class, ''),
                  'UNKNOWN'
                ))) AS projection_class_text,
                UPPER(BTRIM(COALESCE(
                  NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'refresh_scope_kind', ''),
                  NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'scope_kind', ''),
                  NULLIF(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>>'{source_build,refresh_scope_kind}'), ''),
                  NULLIF(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>>'{preview_decisions_json,refresh_scope_kind}'), ''),
                  NULLIF(COALESCE(NULLIF(v_refresh_scope_kind, 'CANDIDATE_FULL_LIVE'), 'TARGETED_TIMESHEETS'), '')
                ))) AS refresh_scope_kind_text
            ) AS delta_family_values
            CROSS JOIN (
              SELECT COALESCE(jsonb_agg(delta_family_targeted_sorted.timesheet_id_text ORDER BY delta_family_targeted_sorted.timesheet_id_text), '[]'::jsonb) AS targeted_timesheet_ids_json
              FROM (
                SELECT DISTINCT NULLIF(BTRIM(delta_family_targeted_raw.value), '') AS timesheet_id_text
                FROM jsonb_array_elements_text(
                  CASE
                    WHEN jsonb_typeof((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids') = 'array'
                      THEN (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids'
                    WHEN jsonb_typeof((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids') = 'string'
                      THEN jsonb_build_array((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_ids')
                    WHEN jsonb_typeof(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{source_build,targeted_timesheet_ids}')) = 'array'
                      THEN ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{source_build,targeted_timesheet_ids}')
                    WHEN jsonb_typeof(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,targeted_timesheet_ids}')) = 'array'
                      THEN ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,targeted_timesheet_ids}')
                    WHEN NULLIF(BTRIM(COALESCE(
                           (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_id',
                           (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'timesheet_id',
                           ''
                         )), '') IS NOT NULL
                      THEN jsonb_build_array(COALESCE(
                        (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_id',
                        (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'timesheet_id'
                      ))
                    ELSE '[]'::jsonb
                  END
                ) AS delta_family_targeted_raw(value)
                WHERE NULLIF(BTRIM(delta_family_targeted_raw.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              ) AS delta_family_targeted_sorted
            ) AS delta_family_targeted
            CROSS JOIN (
              SELECT COALESCE(jsonb_agg(delta_family_linked_sorted.timesheet_id_text ORDER BY delta_family_linked_sorted.timesheet_id_text), '[]'::jsonb) AS linked_timesheet_ids_json
              FROM (
                SELECT DISTINCT NULLIF(BTRIM(delta_family_linked_raw.value), '') AS timesheet_id_text
                FROM jsonb_array_elements_text(
                  CASE
                    WHEN jsonb_typeof((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids') = 'array'
                      THEN (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids'
                    WHEN jsonb_typeof((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids') = 'string'
                      THEN jsonb_build_array((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'linked_timesheet_ids')
                    WHEN jsonb_typeof(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{source_build,linked_timesheet_ids}')) = 'array'
                      THEN ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{source_build,linked_timesheet_ids}')
                    WHEN jsonb_typeof(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,linked_timesheet_ids}')) = 'array'
                      THEN ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,linked_timesheet_ids}')
                    ELSE '[]'::jsonb
                  END
                ) AS delta_family_linked_raw(value)
                WHERE NULLIF(BTRIM(delta_family_linked_raw.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              ) AS delta_family_linked_sorted
            ) AS delta_family_linked
          ) = v_delta_coalescing_key
      )
    ORDER BY running_delta_job.started_at_utc ASC NULLS LAST, running_delta_job.created_at_utc ASC, running_delta_job.id ASC
    LIMIT 1;

    v_dedupe_key := CASE
      WHEN v_delta_active_running_job_id IS NOT NULL THEN
        v_delta_coalescing_key || ':waiting_after_running:' || v_delta_active_running_job_id::text
      ELSE
        v_delta_coalescing_key
    END;

    v_payload_out_json := jsonb_strip_nulls(
      v_payload_json
      || jsonb_build_object(
        'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'canonical_job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'resolved_mode', 'DELTA',
        'projection_run_id', v_projection_run_id::text,
        'projection_mode', COALESCE(NULLIF(v_projection_mode, 'LEGACY'), 'DELTA'),
        'projection_class', v_projection_class,
        'phase', 'INIT_PREFLIGHT',
        'cursor_json', '{}'::jsonb,
        'targeted_timesheet_ids', COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb),
        'linked_timesheet_ids', COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb),
        'queue_identity_targeted_timesheet_ids', COALESCE(v_queue_identity_targeted_timesheet_ids_json, v_targeted_timesheet_ids_json, '[]'::jsonb),
        'queue_identity_linked_timesheet_ids', COALESCE(v_queue_identity_linked_timesheet_ids_json, v_linked_timesheet_ids_json, '[]'::jsonb),
        'source_change_seq', COALESCE(v_source_change_seq, 0),
        'source_change_sequence', COALESCE(v_source_change_seq, 0),
        'latest_source_change_seq', COALESCE(v_source_change_seq, 0),
        'delta_coalescing_key', v_delta_coalescing_key,
        'delta_family_key', v_delta_coalescing_key,
        'normalised_delta_family_key', v_delta_coalescing_key,
        'delta_coalescing_hash', v_delta_coalescing_hash,
        'coalesced_source_change_seqs', jsonb_build_array(COALESCE(v_source_change_seq, 0)),
        'coalesced_event_count', 1,
        'latest_event_at_utc', v_now::text,
        'source_build_required', false,
        'line_work_required', false,
        'delta_refresh_required', true,
        'legacy_fallback_job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
      )
      || jsonb_build_object(
        'reason', v_reason,
        'actor_user_id', CASE WHEN v_actor_user_id IS NULL THEN NULL ELSE v_actor_user_id::text END,
        'snapshot_run_id', p_snapshot_run_id::text,
        'source_snapshot_run_id', p_snapshot_run_id::text,
        'session_id', v_session_id::text,
        'source_session_id', v_session_id::text,
        'workbench_session_id', v_session_id::text,
        'session_version', COALESCE(v_session_row.version, 0),
        'session_signature', v_session_row.session_signature,
        'pay_channel_scope', v_pay_channel_scope,
        'refresh_scope_kind', COALESCE(NULLIF(v_refresh_scope_kind, 'CANDIDATE_FULL_LIVE'), 'TARGETED_TIMESHEETS'),
        'candidate_id', p_candidate_id::text,
        'dedupe_key', v_dedupe_key,
        'shadow_compare_required', COALESCE(v_shadow_compare_required, false),
        'shadow_compare_enforced', COALESCE(v_shadow_compare_enforced, false),
        'classifier_result', v_classifier_result,
        'fallback_required', false,
        'fallback_reason', NULL::text,
        'force_legacy', false,
        'force_broad_legacy', false
      )
      || jsonb_build_object(
        'mutation_context', NULLIF(BTRIM(COALESCE(v_payload_json->>'mutation_context', v_payload_json->>'lifecycle_mutation_context', v_payload_json->>'lifecycle_context', '')), ''),
        'lifecycle_mutation_context', NULLIF(BTRIM(COALESCE(v_payload_json->>'lifecycle_mutation_context', v_payload_json->>'mutation_context', v_payload_json->>'lifecycle_context', '')), ''),
        'trigger_table', NULLIF(BTRIM(COALESCE(v_payload_json->>'trigger_table', v_payload_json#>>'{trigger,table}', '')), ''),
        'trigger_operation', NULLIF(BTRIM(COALESCE(v_payload_json->>'trigger_operation', v_payload_json->>'trigger_op', v_payload_json#>>'{trigger,operation}', '')), ''),
        'trigger_op', NULLIF(BTRIM(COALESCE(v_payload_json->>'trigger_op', v_payload_json->>'trigger_operation', v_payload_json#>>'{trigger,operation}', '')), ''),
        'authorise_boundary_changed', lower(BTRIM(COALESCE(v_payload_json->>'authorise_boundary_changed', v_classifier_result#>>'{complexity_flags,authorise_boundary_changed}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
        'unauthorise_boundary_changed', lower(BTRIM(COALESCE(v_payload_json->>'unauthorise_boundary_changed', v_classifier_result#>>'{complexity_flags,unauthorise_boundary_changed}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
        'explicit_banking_pay_action', lower(BTRIM(COALESCE(v_payload_json->>'explicit_banking_pay_action', v_classifier_result#>>'{complexity_flags,explicit_banking_pay_action}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
        'banking_pay_dirty_required', lower(BTRIM(COALESCE(v_payload_json->>'banking_pay_dirty_required', v_classifier_result->>'banking_pay_dirty_required', v_classifier_result#>>'{complexity_flags,banking_pay_dirty_required}', 'true'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
        'ordinary_timesheet_edit_save_no_dirty', lower(BTRIM(COALESCE(v_payload_json->>'ordinary_timesheet_edit_save_no_dirty', v_classifier_result#>>'{complexity_flags,ordinary_timesheet_edit_save_no_dirty}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      )
    );
  ELSE
    v_source_build_run_id_text := NULLIF(BTRIM(COALESCE(
      v_payload_json->>'source_build_run_id',
      v_payload_json#>>'{source_build,source_build_run_id}',
      v_payload_json#>>'{source_build,run_id}',
      v_initial_cursor_json->>'source_build_run_id',
      ''
    )), '');

    IF v_source_build_run_id_text IS NOT NULL THEN
      IF v_source_build_run_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_ENQUEUE_CANDIDATE_REFRESH_SOURCE_BUILD_RUN_ID_INVALID'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_WORKBENCH_ENQUEUE_CANDIDATE_REFRESH_SOURCE_BUILD_RUN_ID_INVALID',
                  'source_build_run_id', v_source_build_run_id_text,
                  'session_id', v_session_id::text,
                  'candidate_id', p_candidate_id::text
                )::text;
      END IF;
      v_source_build_run_id := v_source_build_run_id_text::uuid;
    ELSE
      v_source_build_seed_text := concat_ws(':',
        'WORKBENCH_CANDIDATE_SOURCE_BUILD',
        p_snapshot_run_id::text,
        v_session_id::text,
        p_candidate_id::text,
        COALESCE(v_session_row.version, 0)::text,
        COALESCE(v_source_change_seq, 0)::text,
        v_refresh_scope_kind,
        md5(COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb)::text),
        md5(COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb)::text),
        v_pay_channel_scope,
        v_reason
      );
      v_source_build_hash := md5(v_source_build_seed_text);
      v_source_build_run_id := (
        substr(v_source_build_hash, 1, 8) || '-' ||
        substr(v_source_build_hash, 9, 4) || '-' ||
        substr(v_source_build_hash, 13, 4) || '-' ||
        substr(v_source_build_hash, 17, 4) || '-' ||
        substr(v_source_build_hash, 21, 12)
      )::uuid;
    END IF;

    v_dedupe_key := 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
      || ':session:' || v_session_id::text
      || ':version:' || COALESCE(v_session_row.version, 0)::text
      || ':snapshot:' || v_session_row.source_snapshot_run_id::text
      || ':signature:' || v_session_signature_token
      || ':candidate:' || p_candidate_id::text
      || ':source_change:' || COALESCE(v_source_change_seq, 0)::text
      || ':source_build:' || v_source_build_run_id::text
      || ':cursor:' || v_cursor_token;

    v_payload_out_json := jsonb_strip_nulls(
      v_payload_json
      || jsonb_build_object(
        'job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
        'resolved_mode', 'LEGACY',
        'canonical_job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
        'reason', v_reason,
        'actor_user_id', CASE WHEN v_actor_user_id IS NULL THEN NULL ELSE v_actor_user_id::text END,
        'snapshot_run_id', p_snapshot_run_id::text,
        'source_snapshot_run_id', p_snapshot_run_id::text,
        'session_id', v_session_id::text,
        'source_session_id', v_session_id::text,
        'workbench_session_id', v_session_id::text,
        'session_version', COALESCE(v_session_row.version, 0),
        'session_signature', v_session_row.session_signature,
        'session_signature_token', v_session_signature_token
      )
      || jsonb_build_object(
        'candidate_id', p_candidate_id::text,
        'source_change_seq', COALESCE(v_source_change_seq, 0),
        'source_change_sequence', COALESCE(v_source_change_seq, 0),
        'source_build_run_id', v_source_build_run_id::text,
        'refresh_scope_kind', v_refresh_scope_kind,
        'targeted_timesheet_ids', COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb),
        'linked_timesheet_ids', COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb),
        'targeted_timesheet_ids_requested', COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb),
        'linked_timesheet_ids_requested', COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb)
      )
      || jsonb_build_object(
        'pay_channel_scope', v_pay_channel_scope,
        'source_build_required', true,
        'line_work_required', true,
        'line_work_only', false,
        'delta_refresh_required', false,
        'source_build_action', 'BUILD_SOURCE',
        'line_work_action', 'SOURCE_BUILD_THEN_SEED',
        'source_build_limit', v_stage_limit,
        'limit', v_stage_limit,
        'source_cursor', COALESCE(v_initial_cursor_json, '{}'::jsonb),
        'cursor_json', COALESCE(v_initial_cursor_json, '{}'::jsonb),
        'cursor_token', v_cursor_token
      )
      || jsonb_build_object(
        'trigger_table', NULLIF(BTRIM(COALESCE(v_payload_json->>'trigger_table', v_payload_json#>>'{trigger,table}', '')), ''),
        'trigger_operation', NULLIF(BTRIM(COALESCE(v_payload_json->>'trigger_operation', v_payload_json->>'trigger_op', v_payload_json#>>'{trigger,operation}', '')), ''),
        'trigger_op', NULLIF(BTRIM(COALESCE(v_payload_json->>'trigger_op', v_payload_json->>'trigger_operation', v_payload_json#>>'{trigger,operation}', '')), ''),
        'dedupe_key', v_dedupe_key,
        'created_by_helper', 'pay_workbench_enqueue_candidate_refresh',
        'created_at_utc', v_now::text,
        'classifier_result', v_classifier_result
      )
      || jsonb_build_object(
        'source_build', jsonb_strip_nulls(jsonb_build_object(
          'required', true,
          'run_id', v_source_build_run_id::text,
          'source_build_run_id', v_source_build_run_id::text,
          'source_change_seq', COALESCE(v_source_change_seq, 0),
          'session_version', COALESCE(v_session_row.version, 0),
          'refresh_scope_kind', v_refresh_scope_kind,
          'targeted_timesheet_ids', COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb),
          'linked_timesheet_ids', COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb),
          'pay_channel_scope', v_pay_channel_scope,
          'limit', v_stage_limit,
          'cursor', COALESCE(v_initial_cursor_json, '{}'::jsonb),
          'reason', v_reason
        ))
      )
    );
  END IF;

  IF v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN
    SELECT existing_delta_job.*
    INTO v_existing_delta_job
    FROM public.banking_pay_workbench_jobs AS existing_delta_job
    WHERE existing_delta_job.session_id = v_session_id
      AND existing_delta_job.candidate_id = p_candidate_id
      AND UPPER(BTRIM(COALESCE(existing_delta_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
      AND UPPER(BTRIM(COALESCE(existing_delta_job.status, ''))) = 'QUEUED'
      AND (
        COALESCE(existing_delta_job.payload_json->>'normalised_delta_family_key', existing_delta_job.payload_json->>'delta_family_key', existing_delta_job.payload_json->>'delta_coalescing_key', '') = v_delta_coalescing_key
        OR (
            SELECT
              'WORKBENCH_CANDIDATE_DELTA_REFRESH_FAMILY'
              || ':session:' || COALESCE(NULLIF(BTRIM(COALESCE(
                existing_delta_job.session_id::text,
                (COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'session_id',
                (COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'workbench_session_id',
                (COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'source_session_id',
                (COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'target_session_id',
                ''
              )), ''), 'none')
              || ':version:' || COALESCE(
                CASE
                  WHEN delta_family_values.session_version_text ~ '^-?[0-9]{1,18}$'
                    THEN delta_family_values.session_version_text::bigint
                  ELSE COALESCE(COALESCE(v_session_row.version, 0), 0)::bigint
                END,
                0
              )::text
              || ':projection_mode:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
                NULLIF(delta_family_values.projection_mode_text, ''),
                NULLIF(COALESCE(NULLIF(v_projection_mode, 'LEGACY'), 'DELTA'), ''),
                'DELTA'
              ))), ''), 'DELTA')
              || ':projection_class:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
                NULLIF(delta_family_values.projection_class_text, ''),
                NULLIF(v_projection_class, ''),
                'UNKNOWN'
              ))), ''), 'UNKNOWN')
              || ':refresh_scope:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
                NULLIF(delta_family_values.refresh_scope_kind_text, ''),
                NULLIF(COALESCE(NULLIF(v_refresh_scope_kind, 'CANDIDATE_FULL_LIVE'), 'TARGETED_TIMESHEETS'), ''),
                CASE
                  WHEN jsonb_array_length(COALESCE(delta_family_targeted.targeted_timesheet_ids_json, '[]'::jsonb)) > 0
                    OR jsonb_array_length(COALESCE(delta_family_linked.linked_timesheet_ids_json, '[]'::jsonb)) > 0
                    THEN 'TARGETED_TIMESHEETS'
                  ELSE 'CANDIDATE_FULL_LIVE'
                END
              ))), ''), 'CANDIDATE_FULL_LIVE')
              || ':candidate:' || COALESCE(NULLIF(BTRIM(COALESCE(
                existing_delta_job.candidate_id::text,
                (COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'candidate_id',
                ((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))#>>'{candidate,id}'),
                ''
              )), ''), 'none')
              || ':timesheets:' || md5(
                COALESCE(delta_family_targeted.targeted_timesheet_ids_json, '[]'::jsonb)::text
                || ':'
                || COALESCE(delta_family_linked.linked_timesheet_ids_json, '[]'::jsonb)::text
              )
            FROM (
              SELECT
                NULLIF(BTRIM(COALESCE(
                  (COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'session_version',
                  (COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'workbench_session_version',
                  (COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'version',
                  CASE WHEN COALESCE(v_session_row.version, 0) IS NULL THEN NULL ELSE (COALESCE(v_session_row.version, 0))::text END,
                  '0'
                )), '') AS session_version_text,
                UPPER(BTRIM(COALESCE(
                  NULLIF((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'projection_mode', ''),
                  NULLIF((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'resolved_mode', ''),
                  NULLIF((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'mode', ''),
                  NULLIF(COALESCE(NULLIF(v_projection_mode, 'LEGACY'), 'DELTA'), ''),
                  'DELTA'
                ))) AS projection_mode_text,
                UPPER(BTRIM(COALESCE(
                  NULLIF((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'projection_class', ''),
                  NULLIF((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'classifier_projection_class', ''),
                  NULLIF(((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))#>>'{classifier_result,projection_class}'), ''),
                  NULLIF(v_projection_class, ''),
                  'UNKNOWN'
                ))) AS projection_class_text,
                UPPER(BTRIM(COALESCE(
                  NULLIF((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'refresh_scope_kind', ''),
                  NULLIF((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'scope_kind', ''),
                  NULLIF(((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))#>>'{source_build,refresh_scope_kind}'), ''),
                  NULLIF(((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))#>>'{preview_decisions_json,refresh_scope_kind}'), ''),
                  NULLIF(COALESCE(NULLIF(v_refresh_scope_kind, 'CANDIDATE_FULL_LIVE'), 'TARGETED_TIMESHEETS'), '')
                ))) AS refresh_scope_kind_text
            ) AS delta_family_values
            CROSS JOIN (
              SELECT COALESCE(jsonb_agg(delta_family_targeted_sorted.timesheet_id_text ORDER BY delta_family_targeted_sorted.timesheet_id_text), '[]'::jsonb) AS targeted_timesheet_ids_json
              FROM (
                SELECT DISTINCT NULLIF(BTRIM(delta_family_targeted_raw.value), '') AS timesheet_id_text
                FROM jsonb_array_elements_text(
                  CASE
                    WHEN jsonb_typeof((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids') = 'array'
                      THEN (COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids'
                    WHEN jsonb_typeof((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids') = 'string'
                      THEN jsonb_build_array((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_ids')
                    WHEN jsonb_typeof(((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))#>'{source_build,targeted_timesheet_ids}')) = 'array'
                      THEN ((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))#>'{source_build,targeted_timesheet_ids}')
                    WHEN jsonb_typeof(((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,targeted_timesheet_ids}')) = 'array'
                      THEN ((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,targeted_timesheet_ids}')
                    WHEN NULLIF(BTRIM(COALESCE(
                           (COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_id',
                           (COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'timesheet_id',
                           ''
                         )), '') IS NOT NULL
                      THEN jsonb_build_array(COALESCE(
                        (COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_id',
                        (COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'timesheet_id'
                      ))
                    ELSE '[]'::jsonb
                  END
                ) AS delta_family_targeted_raw(value)
                WHERE NULLIF(BTRIM(delta_family_targeted_raw.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              ) AS delta_family_targeted_sorted
            ) AS delta_family_targeted
            CROSS JOIN (
              SELECT COALESCE(jsonb_agg(delta_family_linked_sorted.timesheet_id_text ORDER BY delta_family_linked_sorted.timesheet_id_text), '[]'::jsonb) AS linked_timesheet_ids_json
              FROM (
                SELECT DISTINCT NULLIF(BTRIM(delta_family_linked_raw.value), '') AS timesheet_id_text
                FROM jsonb_array_elements_text(
                  CASE
                    WHEN jsonb_typeof((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids') = 'array'
                      THEN (COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids'
                    WHEN jsonb_typeof((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids') = 'string'
                      THEN jsonb_build_array((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'linked_timesheet_ids')
                    WHEN jsonb_typeof(((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))#>'{source_build,linked_timesheet_ids}')) = 'array'
                      THEN ((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))#>'{source_build,linked_timesheet_ids}')
                    WHEN jsonb_typeof(((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,linked_timesheet_ids}')) = 'array'
                      THEN ((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,linked_timesheet_ids}')
                    ELSE '[]'::jsonb
                  END
                ) AS delta_family_linked_raw(value)
                WHERE NULLIF(BTRIM(delta_family_linked_raw.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              ) AS delta_family_linked_sorted
            ) AS delta_family_linked
          ) = v_delta_coalescing_key
      )
      AND lower(BTRIM(COALESCE(existing_delta_job.payload_json->>'force_legacy', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
      AND lower(BTRIM(COALESCE(existing_delta_job.payload_json->>'force_broad_legacy', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
    ORDER BY
      CASE
        WHEN COALESCE(existing_delta_job.payload_json->>'source_change_seq', '') ~ '^-?[0-9]{1,18}$'
          THEN (existing_delta_job.payload_json->>'source_change_seq')::bigint
        ELSE 0::bigint
      END DESC,
      existing_delta_job.priority ASC,
      existing_delta_job.run_at_utc ASC,
      existing_delta_job.created_at_utc ASC,
      existing_delta_job.id ASC
    LIMIT 1
    FOR UPDATE;

    IF FOUND THEN
      -- Reused queued latest-state heads must not inherit an old projection/cursor identity.
      v_existing_delta_projection_run_id_text := NULLIF(BTRIM(COALESCE(v_existing_delta_job.payload_json->>'projection_run_id', '')), '');
      v_projection_run_id := gen_random_uuid();

      v_existing_delta_source_change_seq := GREATEST(
        CASE WHEN COALESCE(v_existing_delta_job.payload_json->>'latest_source_change_seq', '') ~ '^-?[0-9]{1,18}$'
          THEN (v_existing_delta_job.payload_json->>'latest_source_change_seq')::bigint ELSE 0::bigint END,
        CASE WHEN COALESCE(v_existing_delta_job.payload_json->>'source_change_seq', '') ~ '^-?[0-9]{1,18}$'
          THEN (v_existing_delta_job.payload_json->>'source_change_seq')::bigint ELSE 0::bigint END,
        CASE WHEN COALESCE(v_existing_delta_job.payload_json->>'source_change_sequence', '') ~ '^-?[0-9]{1,18}$'
          THEN (v_existing_delta_job.payload_json->>'source_change_sequence')::bigint ELSE 0::bigint END
      );
      v_existing_delta_event_count := CASE
        WHEN COALESCE(v_existing_delta_job.payload_json->>'coalesced_event_count', '') ~ '^[0-9]{1,9}$'
          THEN GREATEST((v_existing_delta_job.payload_json->>'coalesced_event_count')::integer, 1)
        ELSE 1
      END;
      v_merged_delta_event_count := v_existing_delta_event_count + 1;

      v_payload_out_json := public._pay_workbench_merge_targeted_scope_payload(
        COALESCE(v_existing_delta_job.payload_json, '{}'::jsonb),
        COALESCE(v_payload_out_json, '{}'::jsonb)
      ) || jsonb_build_object(
        'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'canonical_job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'projection_run_id', v_projection_run_id::text,
        'projection_mode', COALESCE(NULLIF(v_projection_mode, 'LEGACY'), 'DELTA'),
        'projection_class', v_projection_class,
        'phase', 'INIT_PREFLIGHT',
        'source_build_required', false,
        'line_work_required', false,
        'delta_refresh_required', true,
        'legacy_fallback_job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
      );

      v_source_change_seq := GREATEST(
        COALESCE(v_live_change_seq, 0),
        COALESCE(v_source_change_seq, 0),
        COALESCE(v_existing_delta_source_change_seq, 0),
        CASE WHEN COALESCE(v_payload_out_json->>'latest_source_change_seq', '') ~ '^-?[0-9]{1,18}$'
          THEN (v_payload_out_json->>'latest_source_change_seq')::bigint ELSE 0::bigint END,
        CASE WHEN COALESCE(v_payload_out_json->>'source_change_seq', '') ~ '^-?[0-9]{1,18}$'
          THEN (v_payload_out_json->>'source_change_seq')::bigint ELSE 0::bigint END,
        CASE WHEN COALESCE(v_payload_out_json->>'source_change_sequence', '') ~ '^-?[0-9]{1,18}$'
          THEN (v_payload_out_json->>'source_change_sequence')::bigint ELSE 0::bigint END
      );

      SELECT COALESCE(jsonb_agg(merged_target_ids.timesheet_id_text ORDER BY merged_target_ids.timesheet_id_text), '[]'::jsonb)
      INTO v_targeted_timesheet_ids_json
      FROM (
        SELECT DISTINCT NULLIF(BTRIM(targeted_values.value), '') AS timesheet_id_text
        FROM jsonb_array_elements_text(
          CASE
            WHEN jsonb_typeof(v_payload_out_json->'targeted_timesheet_ids') = 'array' THEN v_payload_out_json->'targeted_timesheet_ids'
            WHEN jsonb_typeof(v_payload_out_json->'targeted_timesheet_ids') = 'string' THEN jsonb_build_array(v_payload_out_json->>'targeted_timesheet_ids')
            ELSE '[]'::jsonb
          END
        ) AS targeted_values(value)
        WHERE NULLIF(BTRIM(targeted_values.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      ) AS merged_target_ids;

      SELECT COALESCE(jsonb_agg(merged_linked_ids.timesheet_id_text ORDER BY merged_linked_ids.timesheet_id_text), '[]'::jsonb)
      INTO v_linked_timesheet_ids_json
      FROM (
        SELECT DISTINCT NULLIF(BTRIM(linked_values.value), '') AS timesheet_id_text
        FROM jsonb_array_elements_text(
          CASE
            WHEN jsonb_typeof(v_payload_out_json->'linked_timesheet_ids') = 'array' THEN v_payload_out_json->'linked_timesheet_ids'
            WHEN jsonb_typeof(v_payload_out_json->'linked_timesheet_ids') = 'string' THEN jsonb_build_array(v_payload_out_json->>'linked_timesheet_ids')
            ELSE '[]'::jsonb
          END
        ) AS linked_values(value)
        WHERE NULLIF(BTRIM(linked_values.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      ) AS merged_linked_ids;

      v_delta_ids_hash := md5(
        COALESCE(v_queue_identity_targeted_timesheet_ids_json, v_targeted_timesheet_ids_json, '[]'::jsonb)::text
        || ':'
        || COALESCE(v_queue_identity_linked_timesheet_ids_json, v_linked_timesheet_ids_json, '[]'::jsonb)::text
      );

      v_delta_coalescing_key := 'WORKBENCH_CANDIDATE_DELTA_REFRESH_FAMILY'
    || ':session:' || COALESCE(v_session_id::text, 'none')
    || ':version:' || COALESCE(COALESCE(v_session_row.version, 0), 0)::text
    || ':projection_mode:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(NULLIF(COALESCE(NULLIF(v_projection_mode, 'LEGACY'), 'DELTA'), ''), 'DELTA'))), ''), 'DELTA')
    || ':projection_class:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(NULLIF(v_projection_class, ''), 'UNKNOWN'))), ''), 'UNKNOWN')
    || ':refresh_scope:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(NULLIF(COALESCE(NULLIF(v_refresh_scope_kind, 'CANDIDATE_FULL_LIVE'), 'TARGETED_TIMESHEETS'), ''), 'TARGETED_TIMESHEETS'))), ''), 'TARGETED_TIMESHEETS')
    || ':candidate:' || COALESCE(p_candidate_id::text, 'none')
    || ':timesheets:' || COALESCE(v_delta_ids_hash, md5('[]:[]'));
      v_delta_coalescing_hash := md5(v_delta_coalescing_key);

      v_payload_out_json := jsonb_strip_nulls(
        (COALESCE(v_payload_out_json, '{}'::jsonb) - ARRAY[
          'cursor',
          'cursor_json',
          'next_cursor',
          'next_cursor_json',
          'source_cursor',
          'write_cursor_json',
          'candidate_cursor',
          'cursor_token',
          'has_cursor',
          'continuation_reason',
          'source_job_id',
          'continuation_source_job_id',
          'bounded_continuation_source_job_id',
          'parent_job_id',
          'next_phase',
          'write_phase',
          'source_result_summary',
          'source_result_has_more',
          'source_result_next_cursor_present'
        ]::text[])
        || jsonb_build_object(
          'cursor_json', '{}'::jsonb,
          'continuation', false,
          'phase', 'INIT_PREFLIGHT',
          'run_mode', CASE WHEN v_delta_active_running_job_id IS NULL THEN 'LATEST_STATE_HEAD' ELSE 'LATEST_RERUN_AFTER_RUNNING' END,
          'normalised_delta_family_key', v_delta_coalescing_key,
          'delta_family_key', v_delta_coalescing_key,
          'delta_coalescing_key', v_delta_coalescing_key,
          'delta_coalescing_hash', v_delta_coalescing_hash
        )
      );

      SELECT running_delta_job.id
      INTO v_delta_active_running_job_id
      FROM public.banking_pay_workbench_jobs AS running_delta_job
      WHERE running_delta_job.session_id = v_session_id
        AND running_delta_job.candidate_id = p_candidate_id
        AND UPPER(BTRIM(COALESCE(running_delta_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
        AND UPPER(BTRIM(COALESCE(running_delta_job.status, ''))) = 'RUNNING'
        AND running_delta_job.id IS DISTINCT FROM v_existing_delta_job.id
        AND (
          COALESCE(running_delta_job.payload_json->>'normalised_delta_family_key', running_delta_job.payload_json->>'delta_family_key', running_delta_job.payload_json->>'delta_coalescing_key', '') = v_delta_coalescing_key
          OR (
              SELECT
                'WORKBENCH_CANDIDATE_DELTA_REFRESH_FAMILY'
                || ':session:' || COALESCE(NULLIF(BTRIM(COALESCE(
                  running_delta_job.session_id::text,
                  (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'session_id',
                  (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'workbench_session_id',
                  (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'source_session_id',
                  (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'target_session_id',
                  ''
                )), ''), 'none')
                || ':version:' || COALESCE(
                  CASE
                    WHEN delta_family_values.session_version_text ~ '^-?[0-9]{1,18}$'
                      THEN delta_family_values.session_version_text::bigint
                    ELSE COALESCE(COALESCE(v_session_row.version, 0), 0)::bigint
                  END,
                  0
                )::text
                || ':projection_mode:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
                  NULLIF(delta_family_values.projection_mode_text, ''),
                  NULLIF(COALESCE(NULLIF(v_projection_mode, 'LEGACY'), 'DELTA'), ''),
                  'DELTA'
                ))), ''), 'DELTA')
                || ':projection_class:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
                  NULLIF(delta_family_values.projection_class_text, ''),
                  NULLIF(v_projection_class, ''),
                  'UNKNOWN'
                ))), ''), 'UNKNOWN')
                || ':refresh_scope:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
                  NULLIF(delta_family_values.refresh_scope_kind_text, ''),
                  NULLIF(COALESCE(NULLIF(v_refresh_scope_kind, 'CANDIDATE_FULL_LIVE'), 'TARGETED_TIMESHEETS'), ''),
                  CASE
                    WHEN jsonb_array_length(COALESCE(delta_family_targeted.targeted_timesheet_ids_json, '[]'::jsonb)) > 0
                      OR jsonb_array_length(COALESCE(delta_family_linked.linked_timesheet_ids_json, '[]'::jsonb)) > 0
                      THEN 'TARGETED_TIMESHEETS'
                    ELSE 'CANDIDATE_FULL_LIVE'
                  END
                ))), ''), 'CANDIDATE_FULL_LIVE')
                || ':candidate:' || COALESCE(NULLIF(BTRIM(COALESCE(
                  running_delta_job.candidate_id::text,
                  (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'candidate_id',
                  ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>>'{candidate,id}'),
                  ''
                )), ''), 'none')
                || ':timesheets:' || md5(
                  COALESCE(delta_family_targeted.targeted_timesheet_ids_json, '[]'::jsonb)::text
                  || ':'
                  || COALESCE(delta_family_linked.linked_timesheet_ids_json, '[]'::jsonb)::text
                )
              FROM (
                SELECT
                  NULLIF(BTRIM(COALESCE(
                    (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'session_version',
                    (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'workbench_session_version',
                    (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'version',
                    CASE WHEN COALESCE(v_session_row.version, 0) IS NULL THEN NULL ELSE (COALESCE(v_session_row.version, 0))::text END,
                    '0'
                  )), '') AS session_version_text,
                  UPPER(BTRIM(COALESCE(
                    NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'projection_mode', ''),
                    NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'resolved_mode', ''),
                    NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'mode', ''),
                    NULLIF(COALESCE(NULLIF(v_projection_mode, 'LEGACY'), 'DELTA'), ''),
                    'DELTA'
                  ))) AS projection_mode_text,
                  UPPER(BTRIM(COALESCE(
                    NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'projection_class', ''),
                    NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'classifier_projection_class', ''),
                    NULLIF(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>>'{classifier_result,projection_class}'), ''),
                    NULLIF(v_projection_class, ''),
                    'UNKNOWN'
                  ))) AS projection_class_text,
                  UPPER(BTRIM(COALESCE(
                    NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'refresh_scope_kind', ''),
                    NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'scope_kind', ''),
                    NULLIF(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>>'{source_build,refresh_scope_kind}'), ''),
                    NULLIF(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>>'{preview_decisions_json,refresh_scope_kind}'), ''),
                    NULLIF(COALESCE(NULLIF(v_refresh_scope_kind, 'CANDIDATE_FULL_LIVE'), 'TARGETED_TIMESHEETS'), '')
                  ))) AS refresh_scope_kind_text
              ) AS delta_family_values
              CROSS JOIN (
                SELECT COALESCE(jsonb_agg(delta_family_targeted_sorted.timesheet_id_text ORDER BY delta_family_targeted_sorted.timesheet_id_text), '[]'::jsonb) AS targeted_timesheet_ids_json
                FROM (
                  SELECT DISTINCT NULLIF(BTRIM(delta_family_targeted_raw.value), '') AS timesheet_id_text
                  FROM jsonb_array_elements_text(
                    CASE
                      WHEN jsonb_typeof((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids') = 'array'
                        THEN (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids'
                      WHEN jsonb_typeof((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids') = 'string'
                        THEN jsonb_build_array((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_ids')
                      WHEN jsonb_typeof(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{source_build,targeted_timesheet_ids}')) = 'array'
                        THEN ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{source_build,targeted_timesheet_ids}')
                      WHEN jsonb_typeof(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,targeted_timesheet_ids}')) = 'array'
                        THEN ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,targeted_timesheet_ids}')
                      WHEN NULLIF(BTRIM(COALESCE(
                             (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_id',
                             (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'timesheet_id',
                             ''
                           )), '') IS NOT NULL
                        THEN jsonb_build_array(COALESCE(
                          (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_id',
                          (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'timesheet_id'
                        ))
                      ELSE '[]'::jsonb
                    END
                  ) AS delta_family_targeted_raw(value)
                  WHERE NULLIF(BTRIM(delta_family_targeted_raw.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                ) AS delta_family_targeted_sorted
              ) AS delta_family_targeted
              CROSS JOIN (
                SELECT COALESCE(jsonb_agg(delta_family_linked_sorted.timesheet_id_text ORDER BY delta_family_linked_sorted.timesheet_id_text), '[]'::jsonb) AS linked_timesheet_ids_json
                FROM (
                  SELECT DISTINCT NULLIF(BTRIM(delta_family_linked_raw.value), '') AS timesheet_id_text
                  FROM jsonb_array_elements_text(
                    CASE
                      WHEN jsonb_typeof((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids') = 'array'
                        THEN (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids'
                      WHEN jsonb_typeof((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids') = 'string'
                        THEN jsonb_build_array((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'linked_timesheet_ids')
                      WHEN jsonb_typeof(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{source_build,linked_timesheet_ids}')) = 'array'
                        THEN ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{source_build,linked_timesheet_ids}')
                      WHEN jsonb_typeof(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,linked_timesheet_ids}')) = 'array'
                        THEN ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,linked_timesheet_ids}')
                      ELSE '[]'::jsonb
                    END
                  ) AS delta_family_linked_raw(value)
                  WHERE NULLIF(BTRIM(delta_family_linked_raw.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                ) AS delta_family_linked_sorted
              ) AS delta_family_linked
            ) = v_delta_coalescing_key
        )
      ORDER BY running_delta_job.started_at_utc ASC NULLS LAST, running_delta_job.created_at_utc ASC, running_delta_job.id ASC
      LIMIT 1;

      v_dedupe_key := CASE
        WHEN v_delta_active_running_job_id IS NOT NULL THEN
          v_delta_coalescing_key || ':waiting_after_running:' || v_delta_active_running_job_id::text
        ELSE
          v_delta_coalescing_key
      END;

      v_payload_out_json := jsonb_strip_nulls(
        v_payload_out_json
        || jsonb_build_object(
          'dedupe_key', v_dedupe_key,
          'targeted_timesheet_ids', COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb),
          'linked_timesheet_ids', COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb),
          'queue_identity_targeted_timesheet_ids', COALESCE(v_queue_identity_targeted_timesheet_ids_json, v_targeted_timesheet_ids_json, '[]'::jsonb),
          'queue_identity_linked_timesheet_ids', COALESCE(v_queue_identity_linked_timesheet_ids_json, v_linked_timesheet_ids_json, '[]'::jsonb),
          'projection_run_id', v_projection_run_id::text,
          'source_change_seq', COALESCE(v_source_change_seq, 0),
          'source_change_sequence', COALESCE(v_source_change_seq, 0),
          'latest_source_change_seq', COALESCE(v_source_change_seq, 0),
          'delta_coalescing_key', v_delta_coalescing_key,
          'delta_family_key', v_delta_coalescing_key,
          'normalised_delta_family_key', v_delta_coalescing_key,
          'delta_coalescing_hash', v_delta_coalescing_hash,
          'coalesced_event_count', GREATEST(COALESCE(v_merged_delta_event_count, 1), 1),
          'coalesced_source_change_seqs', jsonb_build_array(COALESCE(v_existing_delta_source_change_seq, 0), COALESCE(v_source_change_seq, 0)),
          'latest_event_at_utc', v_now::text,
          'scope_merge_applied', true,
          'scope_merge_at_utc', v_now::text,
          'cursor_json', '{}'::jsonb,
          'continuation', false,
          'phase', 'INIT_PREFLIGHT',
          'run_mode', CASE WHEN v_delta_active_running_job_id IS NULL THEN 'LATEST_STATE_HEAD' ELSE 'LATEST_RERUN_AFTER_RUNNING' END
        )
      );

      UPDATE public.banking_pay_workbench_jobs AS existing_delta_update
      SET dedupe_key = v_dedupe_key,
          priority = LEAST(existing_delta_update.priority, 43),
          run_at_utc = LEAST(existing_delta_update.run_at_utc, v_now),
          payload_json = v_payload_out_json,
          updated_at_utc = v_now
      WHERE existing_delta_update.id = v_existing_delta_job.id
      RETURNING existing_delta_update.id,
                existing_delta_update.status,
                false
      INTO v_job_id,
           v_job_status,
           v_job_was_inserted;

      v_delta_merge_reused_existing := true;
    END IF;
  END IF;

  IF v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN
    v_payload_out_json := jsonb_strip_nulls(
      (COALESCE(v_payload_out_json, '{}'::jsonb) - ARRAY[
        'old_row_json',
        'new_row_json',
        'old_row',
        'new_row',
        'source_row_json',
        'work_payload_json',
        'result_row_json',
        'preview_row_json',
        'row_payload_json',
        'line_payload_json',
        'projection_rows',
        'projected_rows',
        'cursor',
        'cursor_json',
        'next_cursor',
        'next_cursor_json',
        'source_cursor',
        'write_cursor_json',
        'candidate_cursor',
        'cursor_token',
        'has_cursor',
        'continuation_reason',
        'source_job_id',
        'continuation_source_job_id',
        'bounded_continuation_source_job_id',
        'parent_job_id',
        'next_phase',
        'write_phase',
        'source_result_summary',
        'source_result_has_more',
        'source_result_next_cursor_present'
      ]::text[])
      || jsonb_build_object(
        'continuation', false,
        'cursor_json', '{}'::jsonb,
        'run_mode', CASE WHEN v_delta_active_running_job_id IS NULL THEN 'LATEST_STATE_HEAD' ELSE 'LATEST_RERUN_AFTER_RUNNING' END,
        'phase', 'INIT_PREFLIGHT'
      )
    );
  END IF;

  IF v_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD' THEN
    UPDATE public.banking_pay_workbench_jobs AS queued_delta_job
    SET status = 'SUCCEEDED',
        completed_at_utc = v_now,
        updated_at_utc = v_now,
        payload_json = jsonb_strip_nulls(
          COALESCE(queued_delta_job.payload_json, '{}'::jsonb)
          || jsonb_build_object(
            'superseded_by_legacy', true,
            'superseded_by_legacy_at_utc', v_now::text,
            'superseded_reason', COALESCE(NULLIF(v_classifier_result->>'fallback_reason', ''), 'LEGACY_REFRESH_WINS'),
            'legacy_source_change_seq', COALESCE(v_source_change_seq, 0)
          )
        )
    WHERE queued_delta_job.session_id = v_session_id
      AND queued_delta_job.candidate_id = p_candidate_id
      AND UPPER(BTRIM(COALESCE(queued_delta_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
      AND UPPER(BTRIM(COALESCE(queued_delta_job.status, ''))) = 'QUEUED';
    GET DIAGNOSTICS v_delta_jobs_superseded = ROW_COUNT;
  END IF;

  IF v_job_id IS NULL THEN
    INSERT INTO public.banking_pay_workbench_jobs AS enqueue_job (
      job_type,
      status,
      priority,
      run_at_utc,
      attempt_count,
      max_attempts,
      dedupe_key,
      snapshot_run_id,
      session_id,
      candidate_id,
      payload_json,
      created_at_utc,
      updated_at_utc,
      started_at_utc,
      completed_at_utc,
      failed_at_utc,
      last_error_json
    )
    VALUES (
      v_job_type,
      'QUEUED',
      CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN 43 ELSE 44 END,
      v_now,
      0,
      8,
      v_dedupe_key,
      p_snapshot_run_id,
      v_session_id,
      p_candidate_id,
      v_payload_out_json,
      v_now,
      v_now,
      NULL::timestamptz,
      NULL::timestamptz,
      NULL::timestamptz,
      NULL::jsonb
    )
    ON CONFLICT (dedupe_key) WHERE status IN ('QUEUED', 'RUNNING')
    DO UPDATE
    SET priority = LEAST(enqueue_job.priority, EXCLUDED.priority),
        run_at_utc = LEAST(enqueue_job.run_at_utc, EXCLUDED.run_at_utc),
        payload_json = CASE
          WHEN EXCLUDED.job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN
            jsonb_strip_nulls(
              (public._pay_workbench_merge_targeted_scope_payload(
                COALESCE(enqueue_job.payload_json, '{}'::jsonb),
                COALESCE(EXCLUDED.payload_json, '{}'::jsonb)
              ) - ARRAY[
                'cursor',
                'cursor_json',
                'next_cursor',
                'next_cursor_json',
                'source_cursor',
                'write_cursor_json',
                'candidate_cursor',
                'cursor_token',
                'has_cursor',
                'continuation_reason',
                'source_job_id',
                'continuation_source_job_id',
                'bounded_continuation_source_job_id',
                'parent_job_id',
                'next_phase',
                'write_phase',
                'source_result_summary',
                'source_result_has_more',
                'source_result_next_cursor_present'
              ]::text[])
              || jsonb_build_object(
                'cursor_json', '{}'::jsonb,
                'continuation', false,
                'phase', 'INIT_PREFLIGHT',
                'run_mode', CASE
                  WHEN lower(BTRIM(COALESCE(EXCLUDED.payload_json->>'waiting_after_running_delta_job', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN 'LATEST_RERUN_AFTER_RUNNING'
                  ELSE 'LATEST_STATE_HEAD'
                END,
                'latest_source_change_seq', GREATEST(
                  CASE WHEN COALESCE(enqueue_job.payload_json->>'latest_source_change_seq', '') ~ '^-?[0-9]{1,18}$' THEN (enqueue_job.payload_json->>'latest_source_change_seq')::bigint ELSE 0::bigint END,
                  CASE WHEN COALESCE(enqueue_job.payload_json->>'source_change_seq', '') ~ '^-?[0-9]{1,18}$' THEN (enqueue_job.payload_json->>'source_change_seq')::bigint ELSE 0::bigint END,
                  CASE WHEN COALESCE(EXCLUDED.payload_json->>'latest_source_change_seq', '') ~ '^-?[0-9]{1,18}$' THEN (EXCLUDED.payload_json->>'latest_source_change_seq')::bigint ELSE 0::bigint END,
                  CASE WHEN COALESCE(EXCLUDED.payload_json->>'source_change_seq', '') ~ '^-?[0-9]{1,18}$' THEN (EXCLUDED.payload_json->>'source_change_seq')::bigint ELSE 0::bigint END
                )
              )
            )
          ELSE public._pay_workbench_merge_targeted_scope_payload(
            COALESCE(enqueue_job.payload_json, '{}'::jsonb),
            COALESCE(EXCLUDED.payload_json, '{}'::jsonb)
          )
        END,
        updated_at_utc = v_now
    WHERE NOT (
      UPPER(BTRIM(COALESCE(enqueue_job.status, ''))) = 'RUNNING'
      AND EXCLUDED.job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
    )
    RETURNING enqueue_job.id,
              enqueue_job.status,
              (xmax = 0)
    INTO v_job_id, v_job_status, v_job_was_inserted;

    GET DIAGNOSTICS v_insert_row_count = ROW_COUNT;

    IF COALESCE(v_insert_row_count, 0) = 0
       AND v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN
      SELECT running_delta_job.id
      INTO v_delta_active_running_job_id
      FROM public.banking_pay_workbench_jobs AS running_delta_job
      WHERE running_delta_job.session_id = v_session_id
        AND running_delta_job.candidate_id = p_candidate_id
        AND UPPER(BTRIM(COALESCE(running_delta_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
        AND UPPER(BTRIM(COALESCE(running_delta_job.status, ''))) = 'RUNNING'
        AND (
          COALESCE(running_delta_job.payload_json->>'normalised_delta_family_key', running_delta_job.payload_json->>'delta_family_key', running_delta_job.payload_json->>'delta_coalescing_key', '') = v_delta_coalescing_key
          OR (
            SELECT
              'WORKBENCH_CANDIDATE_DELTA_REFRESH_FAMILY'
              || ':session:' || COALESCE(NULLIF(BTRIM(COALESCE(
                running_delta_job.session_id::text,
                (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'session_id',
                (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'workbench_session_id',
                (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'source_session_id',
                (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'target_session_id',
                ''
              )), ''), 'none')
              || ':version:' || COALESCE(
                CASE
                  WHEN delta_family_values.session_version_text ~ '^-?[0-9]{1,18}$'
                    THEN delta_family_values.session_version_text::bigint
                  ELSE COALESCE(COALESCE(v_session_row.version, 0), 0)::bigint
                END,
                0
              )::text
              || ':projection_mode:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
                NULLIF(delta_family_values.projection_mode_text, ''),
                NULLIF(COALESCE(NULLIF(v_projection_mode, 'LEGACY'), 'DELTA'), ''),
                'DELTA'
              ))), ''), 'DELTA')
              || ':projection_class:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
                NULLIF(delta_family_values.projection_class_text, ''),
                NULLIF(v_projection_class, ''),
                'UNKNOWN'
              ))), ''), 'UNKNOWN')
              || ':refresh_scope:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
                NULLIF(delta_family_values.refresh_scope_kind_text, ''),
                NULLIF(COALESCE(NULLIF(v_refresh_scope_kind, 'CANDIDATE_FULL_LIVE'), 'TARGETED_TIMESHEETS'), ''),
                CASE
                  WHEN jsonb_array_length(COALESCE(delta_family_targeted.targeted_timesheet_ids_json, '[]'::jsonb)) > 0
                    OR jsonb_array_length(COALESCE(delta_family_linked.linked_timesheet_ids_json, '[]'::jsonb)) > 0
                    THEN 'TARGETED_TIMESHEETS'
                  ELSE 'CANDIDATE_FULL_LIVE'
                END
              ))), ''), 'CANDIDATE_FULL_LIVE')
              || ':candidate:' || COALESCE(NULLIF(BTRIM(COALESCE(
                running_delta_job.candidate_id::text,
                (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'candidate_id',
                ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>>'{candidate,id}'),
                ''
              )), ''), 'none')
              || ':timesheets:' || md5(
                COALESCE(delta_family_targeted.targeted_timesheet_ids_json, '[]'::jsonb)::text
                || ':'
                || COALESCE(delta_family_linked.linked_timesheet_ids_json, '[]'::jsonb)::text
              )
            FROM (
              SELECT
                NULLIF(BTRIM(COALESCE(
                  (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'session_version',
                  (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'workbench_session_version',
                  (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'version',
                  CASE WHEN COALESCE(v_session_row.version, 0) IS NULL THEN NULL ELSE (COALESCE(v_session_row.version, 0))::text END,
                  '0'
                )), '') AS session_version_text,
                UPPER(BTRIM(COALESCE(
                  NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'projection_mode', ''),
                  NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'resolved_mode', ''),
                  NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'mode', ''),
                  NULLIF(COALESCE(NULLIF(v_projection_mode, 'LEGACY'), 'DELTA'), ''),
                  'DELTA'
                ))) AS projection_mode_text,
                UPPER(BTRIM(COALESCE(
                  NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'projection_class', ''),
                  NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'classifier_projection_class', ''),
                  NULLIF(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>>'{classifier_result,projection_class}'), ''),
                  NULLIF(v_projection_class, ''),
                  'UNKNOWN'
                ))) AS projection_class_text,
                UPPER(BTRIM(COALESCE(
                  NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'refresh_scope_kind', ''),
                  NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'scope_kind', ''),
                  NULLIF(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>>'{source_build,refresh_scope_kind}'), ''),
                  NULLIF(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>>'{preview_decisions_json,refresh_scope_kind}'), ''),
                  NULLIF(COALESCE(NULLIF(v_refresh_scope_kind, 'CANDIDATE_FULL_LIVE'), 'TARGETED_TIMESHEETS'), '')
                ))) AS refresh_scope_kind_text
            ) AS delta_family_values
            CROSS JOIN (
              SELECT COALESCE(jsonb_agg(delta_family_targeted_sorted.timesheet_id_text ORDER BY delta_family_targeted_sorted.timesheet_id_text), '[]'::jsonb) AS targeted_timesheet_ids_json
              FROM (
                SELECT DISTINCT NULLIF(BTRIM(delta_family_targeted_raw.value), '') AS timesheet_id_text
                FROM jsonb_array_elements_text(
                  CASE
                    WHEN jsonb_typeof((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids') = 'array'
                      THEN (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids'
                    WHEN jsonb_typeof((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids') = 'string'
                      THEN jsonb_build_array((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_ids')
                    WHEN jsonb_typeof(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{source_build,targeted_timesheet_ids}')) = 'array'
                      THEN ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{source_build,targeted_timesheet_ids}')
                    WHEN jsonb_typeof(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,targeted_timesheet_ids}')) = 'array'
                      THEN ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,targeted_timesheet_ids}')
                    WHEN NULLIF(BTRIM(COALESCE(
                           (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_id',
                           (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'timesheet_id',
                           ''
                         )), '') IS NOT NULL
                      THEN jsonb_build_array(COALESCE(
                        (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_id',
                        (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'timesheet_id'
                      ))
                    ELSE '[]'::jsonb
                  END
                ) AS delta_family_targeted_raw(value)
                WHERE NULLIF(BTRIM(delta_family_targeted_raw.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              ) AS delta_family_targeted_sorted
            ) AS delta_family_targeted
            CROSS JOIN (
              SELECT COALESCE(jsonb_agg(delta_family_linked_sorted.timesheet_id_text ORDER BY delta_family_linked_sorted.timesheet_id_text), '[]'::jsonb) AS linked_timesheet_ids_json
              FROM (
                SELECT DISTINCT NULLIF(BTRIM(delta_family_linked_raw.value), '') AS timesheet_id_text
                FROM jsonb_array_elements_text(
                  CASE
                    WHEN jsonb_typeof((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids') = 'array'
                      THEN (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids'
                    WHEN jsonb_typeof((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids') = 'string'
                      THEN jsonb_build_array((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'linked_timesheet_ids')
                    WHEN jsonb_typeof(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{source_build,linked_timesheet_ids}')) = 'array'
                      THEN ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{source_build,linked_timesheet_ids}')
                    WHEN jsonb_typeof(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,linked_timesheet_ids}')) = 'array'
                      THEN ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,linked_timesheet_ids}')
                    ELSE '[]'::jsonb
                  END
                ) AS delta_family_linked_raw(value)
                WHERE NULLIF(BTRIM(delta_family_linked_raw.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              ) AS delta_family_linked_sorted
            ) AS delta_family_linked
          ) = v_delta_coalescing_key
          OR running_delta_job.dedupe_key = v_dedupe_key
        )
      ORDER BY running_delta_job.started_at_utc ASC NULLS LAST, running_delta_job.created_at_utc ASC, running_delta_job.id ASC
      LIMIT 1;

      IF v_delta_active_running_job_id IS NOT NULL THEN
        v_dedupe_key := v_delta_coalescing_key || ':waiting_after_running:' || v_delta_active_running_job_id::text;

        v_payload_out_json := jsonb_strip_nulls(
          COALESCE(v_payload_out_json, '{}'::jsonb)
          || jsonb_build_object(
            'dedupe_key', v_dedupe_key,
            'delta_active_running_job_id', v_delta_active_running_job_id::text,
            'waiting_after_running_delta_job', true,
            'waiting_after_running_enqueued_at_utc', v_now::text,
            'delta_running_conflict_fail_closed', true
          )
        );

        INSERT INTO public.banking_pay_workbench_jobs AS waiting_enqueue_job (
          job_type,
          status,
          priority,
          run_at_utc,
          attempt_count,
          max_attempts,
          dedupe_key,
          snapshot_run_id,
          session_id,
          candidate_id,
          payload_json,
          created_at_utc,
          updated_at_utc,
          started_at_utc,
          completed_at_utc,
          failed_at_utc,
          last_error_json
        )
        VALUES (
          v_job_type,
          'QUEUED',
          43,
          v_now,
          0,
          8,
          v_dedupe_key,
          p_snapshot_run_id,
          v_session_id,
          p_candidate_id,
          v_payload_out_json,
          v_now,
          v_now,
          NULL::timestamptz,
          NULL::timestamptz,
          NULL::timestamptz,
          NULL::jsonb
        )
        ON CONFLICT (dedupe_key) WHERE status IN ('QUEUED', 'RUNNING')
        DO UPDATE
        SET priority = LEAST(waiting_enqueue_job.priority, EXCLUDED.priority),
            run_at_utc = LEAST(waiting_enqueue_job.run_at_utc, EXCLUDED.run_at_utc),
            payload_json = jsonb_strip_nulls(
              (public._pay_workbench_merge_targeted_scope_payload(
                COALESCE(waiting_enqueue_job.payload_json, '{}'::jsonb),
                COALESCE(EXCLUDED.payload_json, '{}'::jsonb)
              ) - ARRAY[
                'cursor',
                'cursor_json',
                'next_cursor',
                'next_cursor_json',
                'source_cursor',
                'write_cursor_json',
                'candidate_cursor',
                'cursor_token',
                'has_cursor',
                'continuation_reason',
                'source_job_id',
                'continuation_source_job_id',
                'bounded_continuation_source_job_id',
                'parent_job_id',
                'next_phase',
                'write_phase',
                'source_result_summary',
                'source_result_has_more',
                'source_result_next_cursor_present'
              ]::text[])
              || jsonb_build_object(
                'cursor_json', '{}'::jsonb,
                'continuation', false,
                'phase', 'INIT_PREFLIGHT',
                'run_mode', 'LATEST_RERUN_AFTER_RUNNING',
                'waiting_after_running_delta_job', true,
                'latest_source_change_seq', GREATEST(
                  CASE WHEN COALESCE(waiting_enqueue_job.payload_json->>'latest_source_change_seq', '') ~ '^-?[0-9]{1,18}$' THEN (waiting_enqueue_job.payload_json->>'latest_source_change_seq')::bigint ELSE 0::bigint END,
                  CASE WHEN COALESCE(waiting_enqueue_job.payload_json->>'source_change_seq', '') ~ '^-?[0-9]{1,18}$' THEN (waiting_enqueue_job.payload_json->>'source_change_seq')::bigint ELSE 0::bigint END,
                  CASE WHEN COALESCE(EXCLUDED.payload_json->>'latest_source_change_seq', '') ~ '^-?[0-9]{1,18}$' THEN (EXCLUDED.payload_json->>'latest_source_change_seq')::bigint ELSE 0::bigint END,
                  CASE WHEN COALESCE(EXCLUDED.payload_json->>'source_change_seq', '') ~ '^-?[0-9]{1,18}$' THEN (EXCLUDED.payload_json->>'source_change_seq')::bigint ELSE 0::bigint END
                )
              )
            ),
            updated_at_utc = v_now
        WHERE UPPER(BTRIM(COALESCE(waiting_enqueue_job.status, ''))) <> 'RUNNING'
        RETURNING waiting_enqueue_job.id,
                  waiting_enqueue_job.status,
                  (xmax = 0)
        INTO v_job_id, v_job_status, v_job_was_inserted;

        GET DIAGNOSTICS v_insert_row_count = ROW_COUNT;
      END IF;
    END IF;

    IF v_job_id IS NULL THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_ENQUEUE_CANDIDATE_REFRESH_ACTIVE_DELTA_HEAD_CONFLICT'
        USING ERRCODE = '55000',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_ENQUEUE_CANDIDATE_REFRESH_ACTIVE_DELTA_HEAD_CONFLICT',
                'session_id', v_session_id::text,
                'candidate_id', p_candidate_id::text,
                'job_type', v_job_type,
                'delta_coalescing_key', v_delta_coalescing_key,
                'dedupe_key', v_dedupe_key,
                'active_running_job_id', CASE WHEN v_delta_active_running_job_id IS NULL THEN NULL ELSE v_delta_active_running_job_id::text END,
                'message', 'A running delta refresh head was detected during enqueue conflict handling and a safe waiting-head could not be created.'
              )::text;
    END IF;
  END IF;

  UPDATE public.banking_pay_workbench_session_scope AS session_scope
  SET status = CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN 'DELTA_REFRESH_PENDING' ELSE 'SOURCE_BUILD_PENDING' END,
      pending_job_id = v_job_id,
      dirty = true,
      error_json = NULL::jsonb,
      updated_at_utc = v_now
  WHERE session_scope.session_id = v_session_id
    AND session_scope.candidate_id = p_candidate_id;

  PERFORM public._audit_insert(
    'banking_pay_workbench_job',
    v_job_id::text,
    CASE WHEN v_job_was_inserted THEN 'QUEUED' ELSE 'REUSED' END,
    NULL::jsonb,
    jsonb_build_object(
      'id', v_job_id::text,
      'job_type', v_job_type,
    'resolved_mode', v_resolved_mode,
      'status', v_job_status,
      'snapshot_run_id', p_snapshot_run_id::text,
      'session_id', v_session_id::text,
      'candidate_id', p_candidate_id::text,
      'dedupe_key', v_dedupe_key,
      'source_change_seq', COALESCE(v_source_change_seq, 0),
      'source_build_run_id', CASE WHEN v_source_build_run_id IS NULL THEN NULL ELSE v_source_build_run_id::text END,
      'projection_run_id', CASE WHEN v_projection_run_id IS NULL THEN NULL ELSE v_projection_run_id::text END,
      'refresh_scope_kind', v_refresh_scope_kind,
      'targeted_timesheet_count', jsonb_array_length(COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb)),
      'linked_timesheet_count', jsonb_array_length(COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb)),
      'queue_identity_targeted_timesheet_ids', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN COALESCE(v_queue_identity_targeted_timesheet_ids_json, v_targeted_timesheet_ids_json, '[]'::jsonb) ELSE NULL::jsonb END,
      'queue_identity_linked_timesheet_ids', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN COALESCE(v_queue_identity_linked_timesheet_ids_json, v_linked_timesheet_ids_json, '[]'::jsonb) ELSE NULL::jsonb END,
      'source_build_required', v_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
      'line_work_required', v_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
      'delta_refresh_required', v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
      'delta_scope_merge_reused_existing', COALESCE(v_delta_merge_reused_existing, false),
      'delta_coalescing_key', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN v_delta_coalescing_key ELSE NULL::text END,
      'delta_coalescing_hash', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN v_delta_coalescing_hash ELSE NULL::text END,
      'delta_active_running_job_id', CASE WHEN v_delta_active_running_job_id IS NULL THEN NULL ELSE v_delta_active_running_job_id::text END,
      'delta_jobs_superseded_by_legacy', COALESCE(v_delta_jobs_superseded, 0)
    ),
    'WORKBENCH_CANDIDATE_REFRESH_JOB_ENQUEUE',
    v_actor_user_id
  );

  RETURN jsonb_strip_nulls(jsonb_build_object(
    'ok', true,
    'job_id', v_job_id::text,
    'job_type', v_job_type,
    'canonical_job_type', v_job_type,
    'resolved_mode', v_resolved_mode,
    'snapshot_run_id', p_snapshot_run_id::text,
    'session_id', v_session_id::text,
    'candidate_id', p_candidate_id::text,
    'session_version', COALESCE(v_session_row.version, 0),
    'source_change_seq', COALESCE(v_source_change_seq, 0),
    'source_build_run_id', CASE WHEN v_source_build_run_id IS NULL THEN NULL ELSE v_source_build_run_id::text END,
    'projection_run_id', CASE WHEN v_projection_run_id IS NULL THEN NULL ELSE v_projection_run_id::text END,
    'dedupe_key', v_dedupe_key,
    'reason', v_reason,
    'refresh_scope_kind', v_refresh_scope_kind,
    'targeted_timesheet_ids', COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb),
    'linked_timesheet_ids', COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb),
    'queue_identity_targeted_timesheet_ids', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN COALESCE(v_queue_identity_targeted_timesheet_ids_json, v_targeted_timesheet_ids_json, '[]'::jsonb) ELSE NULL::jsonb END,
    'queue_identity_linked_timesheet_ids', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN COALESCE(v_queue_identity_linked_timesheet_ids_json, v_linked_timesheet_ids_json, '[]'::jsonb) ELSE NULL::jsonb END,
    'pay_channel_scope', v_pay_channel_scope,
    'source_build_required', v_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
    'line_work_required', v_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
    'line_work_only', false,
    'delta_refresh_required', v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
    'scope_status', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN 'DELTA_REFRESH_PENDING' ELSE 'SOURCE_BUILD_PENDING' END,
    'projection_mode', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN COALESCE(NULLIF(v_projection_mode, 'LEGACY'), 'DELTA') ELSE NULL::text END,
    'projection_class', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN v_projection_class ELSE NULL::text END,
    'full_snapshot_job', false,
    'reused', NOT v_job_was_inserted,
    'delta_scope_merge_reused_existing', COALESCE(v_delta_merge_reused_existing, false),
    'delta_coalescing_key', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN v_delta_coalescing_key ELSE NULL::text END,
    'delta_coalescing_hash', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN v_delta_coalescing_hash ELSE NULL::text END,
    'delta_active_running_job_id', CASE WHEN v_delta_active_running_job_id IS NULL THEN NULL ELSE v_delta_active_running_job_id::text END,
    'delta_jobs_superseded_by_legacy', COALESCE(v_delta_jobs_superseded, 0),
    'classifier_result', v_classifier_result
  ));
END;
$function$;

ALTER FUNCTION public.pay_workbench_enqueue_candidate_refresh(p_snapshot_run_id uuid, p_candidate_id uuid, p_reason text, p_actor_user_id uuid, p_payload_json jsonb) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.pay_workbench_enqueue_candidate_refresh(p_snapshot_run_id uuid, p_candidate_id uuid, p_reason text, p_actor_user_id uuid, p_payload_json jsonb) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.pay_workbench_enqueue_candidate_refresh(p_snapshot_run_id uuid, p_candidate_id uuid, p_reason text, p_actor_user_id uuid, p_payload_json jsonb) TO postgres;
GRANT EXECUTE ON FUNCTION public.pay_workbench_enqueue_candidate_refresh(p_snapshot_run_id uuid, p_candidate_id uuid, p_reason text, p_actor_user_id uuid, p_payload_json jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.pay_workbench_enqueue_candidate_refresh(p_snapshot_run_id uuid, p_candidate_id uuid, p_reason text, p_actor_user_id uuid, p_payload_json jsonb) TO service_role;

-- -----------------------------------------------------------------------------
-- public.pay_workbench_scope_change_finalize_trg_v1()
-- Installed pg_get_functiondef MD5: eae95763e85538f8f32bfb4e25a1582d
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.pay_workbench_scope_change_finalize_trg_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_state text;
  v_candidate_count integer := 0;
  v_job_count integer := 0;
  v_generation bigint;
BEGIN
  SELECT scope_tx.state
  INTO v_state
  FROM public.banking_pay_scope_change_transactions AS scope_tx
  WHERE scope_tx.tx_token = NEW.tx_token
  FOR UPDATE;

  IF NOT FOUND OR v_state <> 'PENDING' THEN
    RETURN NEW;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.banking_pay_workbench_jobs AS coordinator_job
    WHERE coordinator_job.scope_change_tx_token = NEW.tx_token
      AND UPPER(BTRIM(COALESCE(coordinator_job.job_type, ''))) = 'WORKBENCH_SCOPE_RECONCILE'
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_COORDINATOR_SOURCE_TOKEN_FORBIDDEN'
      USING ERRCODE = 'P0001';
  END IF;

  SELECT COUNT(*)::integer
  INTO v_candidate_count
  FROM public.app_change_counters AS candidate_counter
  WHERE candidate_counter.scope_change_tx_token = NEW.tx_token;

  SELECT COUNT(*)::integer
  INTO v_job_count
  FROM public.banking_pay_workbench_jobs AS staged_job
  WHERE staged_job.scope_change_tx_token = NEW.tx_token
    AND UPPER(BTRIM(COALESCE(staged_job.job_type, ''))) <> 'WORKBENCH_SCOPE_RECONCILE';

  IF v_candidate_count = 0 AND v_job_count = 0 THEN
    UPDATE public.banking_pay_scope_change_transactions AS scope_tx
    SET state = 'NOOP',
        finalized_at_utc = clock_timestamp()
    WHERE scope_tx.tx_token = NEW.tx_token;
    RETURN NEW;
  END IF;

  PERFORM set_config('cloudtms.scope_generation_finalising', 'true', true);

  -- These rows were staged earlier by this transaction. The deterministic
  -- lock pass documents and enforces the finaliser's lock order.
  PERFORM 1
  FROM public.app_change_counters AS staged_counter
  WHERE staged_counter.scope_change_tx_token = NEW.tx_token
  ORDER BY staged_counter.entity_key
  FOR UPDATE;

  PERFORM 1
  FROM public.banking_pay_workbench_jobs AS staged_job
  WHERE staged_job.scope_change_tx_token = NEW.tx_token
  ORDER BY staged_job.id
  FOR UPDATE;

  INSERT INTO public.app_change_counters AS generation_counter(
    entity_key, seq, updated_at
  ) VALUES (
    'pay_candidate_scope_generation', 1, clock_timestamp()
  )
  ON CONFLICT (entity_key) DO UPDATE
  SET seq = generation_counter.seq + 1,
      updated_at = clock_timestamp()
  RETURNING seq INTO v_generation;

  UPDATE public.app_change_counters AS candidate_counter
  SET scope_change_generation = GREATEST(
        COALESCE(candidate_counter.scope_change_generation, 0),
        v_generation
      ),
      scope_change_tx_token = NULL::uuid
  WHERE candidate_counter.scope_change_tx_token = NEW.tx_token;

  UPDATE public.banking_pay_workbench_jobs AS staged_job
  SET scope_change_generation = GREATEST(
        COALESCE(staged_job.scope_change_generation, 0),
        v_generation
      ),
      scope_change_tx_token = NULL::uuid,
      payload_json = COALESCE(staged_job.payload_json, '{}'::jsonb)
        || jsonb_build_object('scope_change_generation', v_generation),
      updated_at_utc = clock_timestamp()
  WHERE staged_job.scope_change_tx_token = NEW.tx_token
    AND UPPER(BTRIM(COALESCE(staged_job.job_type, ''))) <> 'WORKBENCH_SCOPE_RECONCILE';

  UPDATE public.banking_pay_scope_change_transactions AS scope_tx
  SET state = 'FINALIZED',
      allocated_generation = v_generation,
      finalized_at_utc = clock_timestamp()
  WHERE scope_tx.tx_token = NEW.tx_token;

  RETURN NEW;
END;
$function$;

ALTER FUNCTION public.pay_workbench_scope_change_finalize_trg_v1() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.pay_workbench_scope_change_finalize_trg_v1() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.pay_workbench_scope_change_finalize_trg_v1() TO postgres;
GRANT EXECUTE ON FUNCTION public.pay_workbench_scope_change_finalize_trg_v1() TO service_role;

-- -----------------------------------------------------------------------------
-- public.candidate_pay_method_change_refresh_scope_v1(p_candidate_id uuid, p_source_method text, p_target_method text)
-- Installed pg_get_functiondef MD5: ade7473eabd12525f5c93847181f90dd
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.candidate_pay_method_change_refresh_scope_v1(p_candidate_id uuid, p_source_method text, p_target_method text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_source_method text := UPPER(BTRIM(COALESCE(p_source_method, '')));
  v_target_method text := UPPER(BTRIM(COALESCE(p_target_method, '')));
  v_candidate_current_method text;
  v_latest_source_change_seq bigint := 0;
  v_authoritative_sessions_json jsonb := '[]'::jsonb;
  v_replaced_source_session_ids_json jsonb := '[]'::jsonb;
  v_represented_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_authorised_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_active_advance_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_retained_finance_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_targeted_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_target_details_json jsonb := '[]'::jsonb;
  v_preview_row_count integer := 0;
  v_source_target_mismatch_count integer := 0;
  v_uuid_re text := '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
  v_route_operation_id_text text := NULLIF(BTRIM(COALESCE(current_setting('cloudtms.candidate_pay_method_change_operation_id', true), '')), '');
  v_route_actor_user_id_text text := NULLIF(BTRIM(COALESCE(current_setting('cloudtms.candidate_pay_method_change_actor_user_id', true), '')), '');
  v_route_reason text := NULLIF(BTRIM(COALESCE(current_setting('cloudtms.candidate_pay_method_change_reason', true), '')), '');
  v_route_operation_id uuid := NULL::uuid;
  v_route_actor_user_id uuid := NULL::uuid;
  v_route_actor_role text := NULL::text;
  v_route_job_id uuid := NULL::uuid;
  v_route_job_status text := NULL::text;
  v_route_job_payload jsonb := '{}'::jsonb;
  v_route_dedupe_key text := NULL::text;
  v_route_job_count integer := 0;
  v_route_existing_raw_count integer := 0;
  v_route_existing_invalid_count integer := 0;
  v_route_existing_duplicate_count integer := 0;
  v_route_existing_targeted_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_now timestamptz := clock_timestamp();
BEGIN
  IF p_candidate_id IS NULL THEN
    RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_CANDIDATE_REQUIRED'
      USING ERRCODE = '22023';
  END IF;

  IF v_source_method NOT IN ('PAYE', 'UMBRELLA') THEN
    RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_SOURCE_METHOD_INVALID'
      USING ERRCODE = '22023', DETAIL = COALESCE(p_source_method, '');
  END IF;

  IF v_target_method NOT IN ('PAYE', 'UMBRELLA') THEN
    RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_TARGET_METHOD_INVALID'
      USING ERRCODE = '22023', DETAIL = COALESCE(p_target_method, '');
  END IF;

  IF v_source_method = v_target_method THEN
    RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_METHODS_MUST_DIFFER'
      USING ERRCODE = '22023';
  END IF;

  SELECT UPPER(BTRIM(COALESCE(candidate_row.pay_method, '')))
  INTO v_candidate_current_method
  FROM public.candidates AS candidate_row
  WHERE candidate_row.id = p_candidate_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_CANDIDATE_NOT_FOUND'
      USING ERRCODE = 'P0002', DETAIL = p_candidate_id::text;
  END IF;

  -- Preview/plan calls must be bound to the candidate's current committed
  -- source route.  The dedicated apply transaction is the only exception:
  -- its trigger calls this helper after the candidate row has already moved
  -- to the target route and supplies the operation/actor context through
  -- transaction-local settings.
  IF v_route_operation_id_text IS NULL
     AND v_route_actor_user_id_text IS NULL
     AND v_candidate_current_method IS DISTINCT FROM v_source_method THEN
    RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_SOURCE_METHOD_STALE'
      USING ERRCODE = '40001',
            DETAIL = jsonb_build_object(
              'candidate_id', p_candidate_id::text,
              'expected_source_method', v_source_method,
              'current_candidate_method', v_candidate_current_method,
              'target_method', v_target_method,
              'refresh_required', true
            )::text;
  END IF;

  SELECT COALESCE(change_counter.seq, 0)
  INTO v_latest_source_change_seq
  FROM public.app_change_counters AS change_counter
  WHERE change_counter.entity_key = 'pay_candidate:' || p_candidate_id::text;

  v_latest_source_change_seq := COALESCE(v_latest_source_change_seq, 0);

  WITH candidate_open_scope AS (
    SELECT
      workbench_session.id AS session_id,
      workbench_session.actor_user_id,
      workbench_session.pay_date,
      workbench_session.week_ending_cutoff,
      workbench_session.version AS session_version,
      workbench_session.progress_state,
      workbench_session.progress_counter_version,
      workbench_session.updated_at_utc,
      MAX(workbench_session.pay_date) OVER (
        PARTITION BY workbench_session.actor_user_id
      ) AS latest_actor_open_pay_date
    FROM public.banking_pay_workbench_session_scope AS session_scope
    JOIN public.banking_pay_workbench_sessions AS workbench_session
      ON workbench_session.id = session_scope.session_id
    WHERE UPPER(BTRIM(COALESCE(workbench_session.status, ''))) = 'OPEN'
      AND workbench_session.discarded_at_utc IS NULL
      AND workbench_session.replacement_session_id IS NULL
      AND session_scope.candidate_id = p_candidate_id
  ),
  authoritative_sessions AS (
    SELECT DISTINCT
      candidate_scope.session_id,
      candidate_scope.actor_user_id,
      candidate_scope.pay_date,
      candidate_scope.week_ending_cutoff,
      candidate_scope.session_version,
      candidate_scope.progress_state,
      candidate_scope.progress_counter_version,
      candidate_scope.updated_at_utc
    FROM candidate_open_scope AS candidate_scope
    WHERE candidate_scope.pay_date = candidate_scope.latest_actor_open_pay_date
  ),
  retained_case_scope AS (
    SELECT
      finance_case.id AS finance_case_id,
      finance_case.linked_timesheet_id,
      finance_case.status,
      finance_case.outstanding_amount,
      finance_case.updated_at
    FROM public.pay_advances AS finance_case
    WHERE finance_case.candidate_id = p_candidate_id
      AND finance_case.written_off_at_utc IS NULL
      AND (
        finance_case.advance_kind IN (
          'OVERPAYMENT'::public.pay_advance_kind_enum,
          'UNDERPAYMENT'::public.pay_advance_kind_enum
        )
        OR finance_case.case_type IN (
          'OVERPAYMENT'::public.pay_finance_case_type_enum,
          'UNDERPAYMENT'::public.pay_finance_case_type_enum
        )
      )
  ),
  retained_finance_authority_rows AS (
    -- Current open finance authority.
    SELECT DISTINCT
      COALESCE(finance_component.linked_timesheet_id, retained_case.linked_timesheet_id) AS timesheet_id,
      NULLIF(UPPER(BTRIM(COALESCE(finance_component.source_pay_method, ''))), '') AS source_pay_method,
      10::integer AS authority_priority,
      COALESCE(finance_component.updated_at_utc, retained_case.updated_at) AS authority_at_utc,
      'OPEN_FINANCE_CASE_OR_COMPONENT'::text AS authority_source
    FROM retained_case_scope AS retained_case
    LEFT JOIN public.pay_finance_case_components AS finance_component
      ON finance_component.finance_case_id = retained_case.finance_case_id
     AND finance_component.candidate_id = p_candidate_id
    WHERE retained_case.status IN (
        'ACTIVE'::public.pay_advance_status_enum,
        'PAUSED'::public.pay_advance_status_enum
      )
      AND (
        ROUND(COALESCE(retained_case.outstanding_amount, 0), 2) > 0
        OR (
          finance_component.id IS NOT NULL
          AND finance_component.closed_at_utc IS NULL
          AND ROUND(COALESCE(finance_component.remaining_source_amount, 0), 2) > 0
        )
      )
      AND COALESCE(finance_component.linked_timesheet_id, retained_case.linked_timesheet_id) IS NOT NULL

    UNION ALL

    -- Frozen active Draft authority. SETTLED is deliberately excluded here;
    -- settled authority is proven from the frozen item and settlement evidence
    -- in the next branch, so it cannot be counted as both active and settled.
    SELECT DISTINCT
      COALESCE(finance_component.linked_timesheet_id, retained_case.linked_timesheet_id) AS timesheet_id,
      NULLIF(UPPER(BTRIM(COALESCE(
        active_reservation.frozen_source_pay_method,
        finance_component.source_pay_method,
        ''
      ))), '') AS source_pay_method,
      20::integer AS authority_priority,
      COALESCE(active_reservation.committed_at_utc, active_reservation.created_at_utc) AS authority_at_utc,
      'ACTIVE_FINANCE_RESERVATION'::text AS authority_source
    FROM public.pay_advance_reservations AS active_reservation
    JOIN retained_case_scope AS retained_case
      ON retained_case.finance_case_id = active_reservation.finance_case_id
    LEFT JOIN public.pay_finance_case_components AS finance_component
      ON finance_component.id = active_reservation.finance_component_id
     AND finance_component.finance_case_id = retained_case.finance_case_id
     AND finance_component.candidate_id = p_candidate_id
    WHERE UPPER(BTRIM(COALESCE(active_reservation.status, ''))) IN ('RESERVED', 'COMMITTED')
      AND active_reservation.released_at_utc IS NULL
      AND COALESCE(finance_component.linked_timesheet_id, retained_case.linked_timesheet_id) IS NOT NULL

    UNION ALL

    -- Immutable settled movements that still contribute to projected retained
    -- value. Voided/reversed no-money authority is excluded exactly once.
    SELECT DISTINCT
      COALESCE(batch_item.timesheet_id, finance_component.linked_timesheet_id, retained_case.linked_timesheet_id) AS timesheet_id,
      NULLIF(UPPER(BTRIM(COALESCE(
        batch_item.frozen_source_pay_method,
        finance_component.source_pay_method,
        batch_item.pay_channel,
        ''
      ))), '') AS source_pay_method,
      30::integer AS authority_priority,
      COALESCE(bank_transfer.completed_at_utc, batch_candidate.settled_at_utc, batch_item.created_at) AS authority_at_utc,
      'ACTIVE_SETTLED_FINANCE_MOVEMENT'::text AS authority_source
    FROM public.pay_batch_items AS batch_item
    JOIN public.pay_batch_candidates AS batch_candidate
      ON batch_candidate.id = batch_item.pay_batch_candidate_id
     AND batch_candidate.candidate_id = p_candidate_id
    JOIN retained_case_scope AS retained_case
      ON retained_case.finance_case_id = batch_item.finance_case_id
    LEFT JOIN public.pay_finance_case_components AS finance_component
      ON finance_component.id = batch_item.finance_component_id
     AND finance_component.finance_case_id = retained_case.finance_case_id
     AND finance_component.candidate_id = p_candidate_id
    LEFT JOIN public.pay_bank_transfers AS bank_transfer
      ON bank_transfer.id = batch_item.pay_bank_transfer_id
    WHERE batch_item.is_voided IS NOT TRUE
      AND UPPER(BTRIM(COALESCE(batch_item.item_type, ''))) IN ('OVERPAYMENT_RECOVERY', 'UNDERPAYMENT_PAYMENT')
      AND (
        UPPER(BTRIM(COALESCE(batch_candidate.settlement_status, ''))) = 'SETTLED'
        OR batch_candidate.settled_at_utc IS NOT NULL
        OR UPPER(BTRIM(COALESCE(bank_transfer.status, ''))) = 'COMPLETED'
        OR bank_transfer.completed_at_utc IS NOT NULL
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_items AS applied_reversal
        WHERE applied_reversal.pay_batch_item_id = batch_item.id
          AND applied_reversal.status = 'APPLIED'
          AND applied_reversal.correction_item_kind IN ('PRE_BANK_CANCEL', 'NO_MONEY_UNWIND', 'SETTLED_REVERSAL')
      )
      AND COALESCE(batch_item.timesheet_id, finance_component.linked_timesheet_id, retained_case.linked_timesheet_id) IS NOT NULL

    UNION ALL

    -- Applied corrections are retained only where they are one of the exact
    -- authority-changing correction kinds and remain linked to this finance
    -- lineage. Generic historic events do not broaden route-change scope.
    SELECT DISTINCT
      COALESCE(correction_item.timesheet_id, finance_component.linked_timesheet_id, retained_case.linked_timesheet_id) AS timesheet_id,
      NULLIF(UPPER(BTRIM(COALESCE(finance_component.source_pay_method, ''))), '') AS source_pay_method,
      40::integer AS authority_priority,
      COALESCE(correction_item.applied_at_utc, correction_item.created_at_utc) AS authority_at_utc,
      'APPLIED_FINANCE_CORRECTION'::text AS authority_source
    FROM public.pay_payment_correction_items AS correction_item
    JOIN retained_case_scope AS retained_case
      ON retained_case.finance_case_id = correction_item.finance_case_id
    LEFT JOIN public.pay_finance_case_components AS finance_component
      ON finance_component.id = correction_item.finance_component_id
     AND finance_component.finance_case_id = retained_case.finance_case_id
     AND finance_component.candidate_id = p_candidate_id
    WHERE correction_item.candidate_id = p_candidate_id
      AND correction_item.status = 'APPLIED'
      AND correction_item.correction_item_kind IN ('PRE_BANK_CANCEL', 'NO_MONEY_UNWIND', 'SETTLED_REVERSAL')
      AND COALESCE(correction_item.timesheet_id, finance_component.linked_timesheet_id, retained_case.linked_timesheet_id) IS NOT NULL
  ),
  canonical_seed_ids AS (
    SELECT COALESCE(
      array_agg(DISTINCT seed.timesheet_id ORDER BY seed.timesheet_id),
      ARRAY[]::uuid[]
    ) AS timesheet_ids
    FROM (
      SELECT current_timesheet.timesheet_id
      FROM public.timesheets AS current_timesheet
      JOIN public.contracts AS current_contract
        ON current_contract.id = current_timesheet.contract_id
       AND current_contract.candidate_id = p_candidate_id
      WHERE current_timesheet.is_current IS TRUE

      UNION

      SELECT current_financial.timesheet_id
      FROM public.timesheets_financials AS current_financial
      WHERE current_financial.candidate_id = p_candidate_id
        AND current_financial.is_current IS TRUE
        AND current_financial.timesheet_id IS NOT NULL

      UNION

      SELECT payment_override.timesheet_id
      FROM public.timesheet_payment_overrides AS payment_override
      WHERE payment_override.candidate_id = p_candidate_id
        AND UPPER(BTRIM(COALESCE(payment_override.override_type, ''))) = 'ADVANCE_THIS_PAYMENT'
        AND payment_override.cleared_at_utc IS NULL
        AND payment_override.consumed_at_utc IS NULL
        AND payment_override.consumed_by_pay_batch_id IS NULL
        AND payment_override.timesheet_id IS NOT NULL

      UNION

      SELECT retained_authority.timesheet_id
      FROM retained_finance_authority_rows AS retained_authority
      WHERE retained_authority.timesheet_id IS NOT NULL
    ) AS seed
  ),
  rotation_scope AS (
    SELECT
      rotation_row.requested_timesheet_id,
      rotation_row.booking_id,
      rotation_row.canonical_timesheet_id,
      rotation_row.family_timesheet_id,
      rotation_row.family_is_current,
      rotation_row.family_version,
      rotation_row.requested_is_canonical
    FROM public._pay_timesheet_rotation_scope(
      COALESCE((SELECT canonical_seed_ids.timesheet_ids FROM canonical_seed_ids), ARRAY[]::uuid[])
    ) AS rotation_row
  ),
  canonical_ids AS (
    SELECT DISTINCT
      COALESCE(rotation_row.canonical_timesheet_id, seed_id.timesheet_id) AS timesheet_id
    FROM unnest(
      COALESCE((SELECT canonical_seed_ids.timesheet_ids FROM canonical_seed_ids), ARRAY[]::uuid[])
    ) AS seed_id(timesheet_id)
    LEFT JOIN rotation_scope AS rotation_row
      ON rotation_row.requested_timesheet_id = seed_id.timesheet_id
    WHERE COALESCE(rotation_row.canonical_timesheet_id, seed_id.timesheet_id) IS NOT NULL
  ),
  canonical_qualification AS (
    SELECT
      canonical_id.timesheet_id,
      (
        current_timesheet.archived_at_utc IS NULL
        AND current_timesheet.revoked_at IS NULL
        AND current_timesheet.is_current IS TRUE
        AND current_timesheet.authorised_at_server IS NOT NULL
      ) AS is_authorised,
      EXISTS (
        SELECT 1
        FROM public.timesheet_payment_overrides AS payment_override
        WHERE payment_override.candidate_id = p_candidate_id
          AND UPPER(BTRIM(COALESCE(payment_override.override_type, ''))) = 'ADVANCE_THIS_PAYMENT'
          AND payment_override.cleared_at_utc IS NULL
          AND payment_override.consumed_at_utc IS NULL
          AND payment_override.consumed_by_pay_batch_id IS NULL
          AND (
            payment_override.timesheet_id = canonical_id.timesheet_id
            OR payment_override.timesheet_id IN (
              SELECT family_row.family_timesheet_id
              FROM rotation_scope AS family_row
              WHERE family_row.canonical_timesheet_id = canonical_id.timesheet_id
            )
          )
      ) AS has_active_advance,
      EXISTS (
        SELECT 1
        FROM retained_finance_authority_rows AS retained_authority
        WHERE retained_authority.timesheet_id = canonical_id.timesheet_id
           OR retained_authority.timesheet_id IN (
             SELECT family_row.family_timesheet_id
             FROM rotation_scope AS family_row
             WHERE family_row.canonical_timesheet_id = canonical_id.timesheet_id
           )
      ) AS has_retained_finance_authority,
      UPPER(BTRIM(COALESCE(
        current_financial.pay_method,
        retained_finance_authority.source_pay_method,
        current_contract.pay_method_snapshot,
        ''
      ))) AS source_pay_method
    FROM canonical_ids AS canonical_id
    LEFT JOIN public.timesheets AS current_timesheet
      ON current_timesheet.timesheet_id = canonical_id.timesheet_id
     AND current_timesheet.is_current IS TRUE
    LEFT JOIN LATERAL (
      SELECT financial_row.pay_method
      FROM public.timesheets_financials AS financial_row
      WHERE financial_row.timesheet_id = canonical_id.timesheet_id
        AND financial_row.is_current IS TRUE
        AND financial_row.candidate_id = p_candidate_id
      ORDER BY financial_row.timesheet_version DESC, financial_row.id DESC
      LIMIT 1
    ) AS current_financial ON TRUE
    LEFT JOIN LATERAL (
      SELECT retained_authority.source_pay_method
      FROM retained_finance_authority_rows AS retained_authority
      WHERE (
          retained_authority.timesheet_id = canonical_id.timesheet_id
          OR retained_authority.timesheet_id IN (
            SELECT family_row.family_timesheet_id
            FROM rotation_scope AS family_row
            WHERE family_row.canonical_timesheet_id = canonical_id.timesheet_id
          )
        )
        AND retained_authority.source_pay_method IN ('PAYE', 'UMBRELLA')
      ORDER BY
        retained_authority.authority_priority,
        retained_authority.authority_at_utc DESC NULLS LAST,
        retained_authority.source_pay_method
      LIMIT 1
    ) AS retained_finance_authority ON TRUE
    LEFT JOIN public.contracts AS current_contract
      ON current_contract.id = current_timesheet.contract_id
     AND current_contract.candidate_id = p_candidate_id
  ),
  qualifying_timesheets AS (
    SELECT
      qualification.timesheet_id,
      qualification.is_authorised,
      qualification.has_active_advance,
      qualification.has_retained_finance_authority,
      qualification.source_pay_method
    FROM canonical_qualification AS qualification
    WHERE qualification.is_authorised IS TRUE
       OR qualification.has_active_advance IS TRUE
       OR qualification.has_retained_finance_authority IS TRUE
  ),
  current_preview_rows AS (
    SELECT DISTINCT
      authoritative_session.session_id,
      authoritative_session.session_version,
      preview_row.id AS preview_row_id,
      preview_row.timesheet_id AS requested_timesheet_id,
      COALESCE(current_preview_timesheet.timesheet_id, preview_row.timesheet_id) AS canonical_timesheet_id
    FROM authoritative_sessions AS authoritative_session
    JOIN public.banking_pay_workbench_preview_rows AS preview_row
      ON preview_row.session_id = authoritative_session.session_id
     AND preview_row.candidate_id = p_candidate_id
     AND preview_row.session_version = authoritative_session.session_version
    LEFT JOIN public.timesheets AS requested_preview_timesheet
      ON requested_preview_timesheet.timesheet_id = preview_row.timesheet_id
    LEFT JOIN LATERAL (
      SELECT candidate_current_timesheet.timesheet_id
      FROM public.timesheets AS candidate_current_timesheet
      WHERE requested_preview_timesheet.booking_id IS NOT NULL
        AND candidate_current_timesheet.booking_id = requested_preview_timesheet.booking_id
        AND candidate_current_timesheet.is_current IS TRUE
      ORDER BY candidate_current_timesheet.version DESC NULLS LAST,
               candidate_current_timesheet.updated_at DESC NULLS LAST,
               candidate_current_timesheet.created_at DESC NULLS LAST,
               candidate_current_timesheet.timesheet_id DESC
      LIMIT 1
    ) AS current_preview_timesheet ON TRUE
    WHERE preview_row.timesheet_id IS NOT NULL
  ),
  represented_ids AS (
    SELECT COALESCE(
      array_agg(DISTINCT preview_row.canonical_timesheet_id ORDER BY preview_row.canonical_timesheet_id),
      ARRAY[]::uuid[]
    ) AS timesheet_ids
    FROM current_preview_rows AS preview_row
    WHERE preview_row.canonical_timesheet_id IS NOT NULL
  ),
  session_rollup AS (
    SELECT
      authoritative_session.session_id,
      authoritative_session.actor_user_id,
      authoritative_session.pay_date,
      authoritative_session.week_ending_cutoff,
      authoritative_session.session_version,
      authoritative_session.progress_state,
      authoritative_session.progress_counter_version,
      authoritative_session.updated_at_utc,
      COUNT(DISTINCT current_preview.preview_row_id)::integer AS preview_row_count,
      COALESCE(
        array_agg(DISTINCT current_preview.canonical_timesheet_id ORDER BY current_preview.canonical_timesheet_id)
          FILTER (WHERE current_preview.canonical_timesheet_id IS NOT NULL),
        ARRAY[]::uuid[]
      ) AS represented_timesheet_ids,
      COALESCE(
        (SELECT array_agg(qualifying.timesheet_id ORDER BY qualifying.timesheet_id) FROM qualifying_timesheets AS qualifying),
        ARRAY[]::uuid[]
      ) AS qualifying_timesheet_ids
    FROM authoritative_sessions AS authoritative_session
    LEFT JOIN current_preview_rows AS current_preview
      ON current_preview.session_id = authoritative_session.session_id
     AND current_preview.session_version = authoritative_session.session_version
    GROUP BY
      authoritative_session.session_id,
      authoritative_session.actor_user_id,
      authoritative_session.pay_date,
      authoritative_session.week_ending_cutoff,
      authoritative_session.session_version,
      authoritative_session.progress_state,
      authoritative_session.progress_counter_version,
      authoritative_session.updated_at_utc
  )
  SELECT
    COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'session_id', session_row.session_id::text,
          'actor_user_id', session_row.actor_user_id::text,
          'pay_date', session_row.pay_date::text,
          'week_ending_cutoff', session_row.week_ending_cutoff::text,
          'session_version', session_row.session_version,
          'progress_state', session_row.progress_state,
          'progress_counter_version', session_row.progress_counter_version,
          'preview_row_count', session_row.preview_row_count,
          'represented_timesheet_ids', to_jsonb(session_row.represented_timesheet_ids),
          'qualifying_timesheet_ids', to_jsonb(session_row.qualifying_timesheet_ids),
          'updated_at_utc', session_row.updated_at_utc::text
        )
        ORDER BY session_row.updated_at_utc DESC, session_row.session_id
      )
      FROM session_rollup AS session_row
    ), '[]'::jsonb),
    COALESCE((SELECT COUNT(*)::integer FROM current_preview_rows), 0),
    COALESCE((SELECT represented_ids.timesheet_ids FROM represented_ids), ARRAY[]::uuid[]),
    COALESCE((
      SELECT array_agg(qualification.timesheet_id ORDER BY qualification.timesheet_id)
      FROM canonical_qualification AS qualification
      WHERE qualification.is_authorised IS TRUE
    ), ARRAY[]::uuid[]),
    COALESCE((
      SELECT array_agg(qualification.timesheet_id ORDER BY qualification.timesheet_id)
      FROM canonical_qualification AS qualification
      WHERE qualification.has_active_advance IS TRUE
    ), ARRAY[]::uuid[]),
    COALESCE((
      SELECT array_agg(qualification.timesheet_id ORDER BY qualification.timesheet_id)
      FROM canonical_qualification AS qualification
      WHERE qualification.has_retained_finance_authority IS TRUE
    ), ARRAY[]::uuid[]),
    COALESCE((
      SELECT array_agg(qualifying.timesheet_id ORDER BY qualifying.timesheet_id)
      FROM qualifying_timesheets AS qualifying
    ), ARRAY[]::uuid[]),
    COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'timesheet_id', qualifying.timesheet_id::text,
          'is_authorised', qualifying.is_authorised,
          'has_active_advance', qualifying.has_active_advance,
          'has_retained_finance_authority', qualifying.has_retained_finance_authority,
          'source_pay_method', NULLIF(qualifying.source_pay_method, ''),
          'target_pay_method', v_target_method,
          'source_target_mismatch', (
            qualifying.source_pay_method IN ('PAYE', 'UMBRELLA')
            AND qualifying.source_pay_method <> v_target_method
          )
        )
        ORDER BY qualifying.timesheet_id
      )
      FROM qualifying_timesheets AS qualifying
    ), '[]'::jsonb),
    COALESCE((
      SELECT COUNT(*)::integer
      FROM qualifying_timesheets AS qualifying
      WHERE qualifying.source_pay_method IN ('PAYE', 'UMBRELLA')
        AND qualifying.source_pay_method <> v_target_method
    ), 0)
  INTO
    v_authoritative_sessions_json,
    v_preview_row_count,
    v_represented_timesheet_ids,
    v_authorised_timesheet_ids,
    v_active_advance_timesheet_ids,
    v_retained_finance_timesheet_ids,
    v_targeted_timesheet_ids,
    v_target_details_json,
    v_source_target_mismatch_count;

  WITH authoritative_session_ids AS (
    SELECT (session_value->>'session_id')::uuid AS session_id
    FROM jsonb_array_elements(v_authoritative_sessions_json) AS session_values(session_value)
    WHERE COALESCE(session_value->>'session_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  )
  SELECT COALESCE(
    jsonb_agg(source_session.id::text ORDER BY source_session.updated_at_utc DESC, source_session.id),
    '[]'::jsonb
  )
  INTO v_replaced_source_session_ids_json
  FROM public.banking_pay_workbench_sessions AS source_session
  WHERE source_session.replacement_session_id IN (
    SELECT authoritative_session.session_id
    FROM authoritative_session_ids AS authoritative_session
  )
    AND (
      EXISTS (
        SELECT 1
        FROM public.banking_pay_workbench_session_scope AS source_scope
        WHERE source_scope.session_id = source_session.id
          AND source_scope.candidate_id = p_candidate_id
      )
      OR EXISTS (
        SELECT 1
        FROM public.banking_pay_workbench_preview_rows AS source_preview
        WHERE source_preview.session_id = source_session.id
          AND source_preview.candidate_id = p_candidate_id
      )
    );

  IF v_route_operation_id_text IS NOT NULL OR v_route_actor_user_id_text IS NOT NULL THEN
    IF v_route_operation_id_text IS NULL OR v_route_operation_id_text !~* v_uuid_re THEN
      RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_OPERATION_CONTEXT_REQUIRED'
        USING ERRCODE = '22023';
    END IF;

    IF v_route_actor_user_id_text IS NULL OR v_route_actor_user_id_text !~* v_uuid_re THEN
      RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_ACTOR_CONTEXT_REQUIRED'
        USING ERRCODE = '22023';
    END IF;

    v_route_operation_id := v_route_operation_id_text::uuid;
    v_route_actor_user_id := v_route_actor_user_id_text::uuid;

    SELECT LOWER(BTRIM(COALESCE(actor_row.role, '')))
    INTO v_route_actor_role
    FROM public.tms_users AS actor_row
    WHERE actor_row.id = v_route_actor_user_id
      AND actor_row.is_active IS TRUE;

    IF NOT FOUND OR v_route_actor_role <> 'admin' THEN
      RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_ADMIN_REQUIRED'
        USING ERRCODE = '42501', DETAIL = v_route_actor_user_id::text;
    END IF;

    IF v_candidate_current_method IS DISTINCT FROM v_target_method THEN
      RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_TARGET_NOT_COMMITTED'
        USING ERRCODE = '40001',
              DETAIL = jsonb_build_object(
                'candidate_id', p_candidate_id::text,
                'candidate_current_method', v_candidate_current_method,
                'expected_target_method', v_target_method,
                'operation_id', v_route_operation_id::text
              )::text;
    END IF;

    v_route_dedupe_key := 'CANDIDATE_PAY_METHOD_CHANGE:' || p_candidate_id::text || ':' || v_route_operation_id::text;
    PERFORM pg_advisory_xact_lock(hashtext('candidate_pay_method_change_job:' || v_route_operation_id::text));

    SELECT COUNT(*)::integer
    INTO v_route_job_count
    FROM public.banking_pay_workbench_jobs AS existing_job
    WHERE existing_job.dedupe_key = v_route_dedupe_key;

    IF v_route_job_count > 1 THEN
      RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_DURABLE_QUEUE_DUPLICATED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'candidate_id', p_candidate_id::text,
                'operation_id', v_route_operation_id::text,
                'dedupe_key', v_route_dedupe_key,
                'job_count', v_route_job_count
              )::text;
    END IF;

    SELECT
      existing_job.id,
      existing_job.status,
      COALESCE(existing_job.payload_json, '{}'::jsonb)
    INTO
      v_route_job_id,
      v_route_job_status,
      v_route_job_payload
    FROM public.banking_pay_workbench_jobs AS existing_job
    WHERE existing_job.dedupe_key = v_route_dedupe_key
    ORDER BY existing_job.updated_at_utc DESC, existing_job.id DESC
    LIMIT 1
    FOR UPDATE;

    IF v_route_job_id IS NOT NULL THEN
      IF COALESCE(v_route_job_payload->>'candidate_id', '') <> p_candidate_id::text
         OR COALESCE(v_route_job_payload->>'route_change_operation_id', '') <> v_route_operation_id::text
         OR UPPER(BTRIM(COALESCE(v_route_job_payload->>'route_change_source_method', ''))) <> v_source_method
         OR UPPER(BTRIM(COALESCE(v_route_job_payload->>'route_change_target_method', ''))) <> v_target_method THEN
        RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_DURABLE_QUEUE_AUTHORITY_MISMATCH'
          USING ERRCODE = 'P0001', DETAIL = v_route_job_id::text;
      END IF;

      SELECT
        COUNT(*)::integer,
        COUNT(*) FILTER (WHERE raw_target.value !~* v_uuid_re)::integer,
        COALESCE(
          array_agg(DISTINCT raw_target.value::uuid ORDER BY raw_target.value::uuid)
            FILTER (WHERE raw_target.value ~* v_uuid_re),
          ARRAY[]::uuid[]
        )
      INTO
        v_route_existing_raw_count,
        v_route_existing_invalid_count,
        v_route_existing_targeted_timesheet_ids
      FROM jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(v_route_job_payload->'targeted_timesheet_ids') = 'array'
            THEN v_route_job_payload->'targeted_timesheet_ids'
          ELSE '[]'::jsonb
        END
      ) AS raw_target(value);

      v_route_existing_duplicate_count := GREATEST(
        COALESCE(v_route_existing_raw_count, 0)
          - COALESCE(v_route_existing_invalid_count, 0)
          - COALESCE(array_length(v_route_existing_targeted_timesheet_ids, 1), 0),
        0
      );

      IF COALESCE(v_route_existing_invalid_count, 0) <> 0
         OR COALESCE(v_route_existing_duplicate_count, 0) <> 0
         OR v_route_existing_targeted_timesheet_ids IS DISTINCT FROM v_targeted_timesheet_ids
         OR LOWER(BTRIM(COALESCE(v_route_job_payload->>'exact_target_scope', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
         OR UPPER(BTRIM(COALESCE(v_route_job_payload->>'refresh_scope_kind', ''))) <> 'TARGETED_TIMESHEETS' THEN
        RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_DURABLE_QUEUE_SET_MISMATCH'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'job_id', v_route_job_id::text,
                  'expected_targeted_timesheet_ids', to_jsonb(v_targeted_timesheet_ids),
                  'persisted_targeted_timesheet_ids', to_jsonb(v_route_existing_targeted_timesheet_ids),
                  'invalid_target_count', v_route_existing_invalid_count,
                  'effective_duplicate_count', v_route_existing_duplicate_count
                )::text;
      END IF;

      v_latest_source_change_seq := COALESCE(
        CASE
          WHEN COALESCE(v_route_job_payload->>'source_change_seq', '') ~ '^[0-9]{1,18}$'
            THEN (v_route_job_payload->>'source_change_seq')::bigint
          ELSE v_latest_source_change_seq
        END,
        v_latest_source_change_seq,
        0
      );
    ELSE
      PERFORM public._change_bump('pay_candidate:' || p_candidate_id::text);

      SELECT COALESCE(change_counter.seq, 0)
      INTO v_latest_source_change_seq
      FROM public.app_change_counters AS change_counter
      WHERE change_counter.entity_key = 'pay_candidate:' || p_candidate_id::text;

      v_latest_source_change_seq := COALESCE(v_latest_source_change_seq, 0);

      v_route_job_payload := (
        jsonb_build_object(
          'job_type', 'WORKBENCH_CANDIDATE_DIRTY_APPLY',
          'scope_kind', 'CANDIDATE',
          'scope_id', p_candidate_id::text,
          'candidate_id', p_candidate_id::text,
          'reason', COALESCE(v_route_reason, 'PAY_METHOD_CHANGE'),
          'dirty_reason', COALESCE(v_route_reason, 'PAY_METHOD_CHANGE'),
          'candidate_pay_method_change', true,
          'candidate_payment_status_changed', true,
          'pay_method_changed', true,
          'prospective_only', true,
          'old_pay_method', v_source_method,
          'new_pay_method', v_target_method,
          'route_change_operation_id', v_route_operation_id::text,
          'route_change_actor_user_id', v_route_actor_user_id::text,
          'actor_user_id', v_route_actor_user_id::text,
          'route_change_reason', COALESCE(v_route_reason, 'PAY_METHOD_CHANGE'),
          'route_change_source_method', v_source_method,
          'route_change_target_method', v_target_method,
          'latest_source_change_seq', v_latest_source_change_seq,
          'source_change_seq', v_latest_source_change_seq,
          'source_change_sequence', v_latest_source_change_seq
        )
        || jsonb_build_object(
          'refresh_scope_kind', 'TARGETED_TIMESHEETS',
          'targeted_timesheet_ids', to_jsonb(v_targeted_timesheet_ids),
          'targeted_scope_is_empty', COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) = 0,
          'exact_target_scope', true,
          'coverage_basis', 'CANONICAL_TIMESHEETS_WITH_RETAINED_FINANCE_AUTHORITY',
          'coverage_complete', true,
          'authorised_timesheet_ids', to_jsonb(v_authorised_timesheet_ids),
          'authorised_timesheet_count', COALESCE(array_length(v_authorised_timesheet_ids, 1), 0),
          'active_advance_timesheet_ids', to_jsonb(v_active_advance_timesheet_ids),
          'active_advance_timesheet_count', COALESCE(array_length(v_active_advance_timesheet_ids, 1), 0),
          'retained_finance_timesheet_ids', to_jsonb(v_retained_finance_timesheet_ids),
          'retained_finance_timesheet_count', COALESCE(array_length(v_retained_finance_timesheet_ids, 1), 0),
          'authoritative_sessions', v_authoritative_sessions_json,
          'replaced_source_session_ids', v_replaced_source_session_ids_json,
          'target_details', v_target_details_json,
          'source_target_mismatch_count', COALESCE(v_source_target_mismatch_count, 0),
          'source_build_required', COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) > 0,
          'line_work_required', COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) > 0,
          'line_work_only', false,
          'line_work_action', 'SOURCE_BUILD',
          'rerun_required', false
        )
        || jsonb_build_object(
          'contracts_changed', 0,
          'contract_weeks_changed', 0,
          'timesheets_changed', 0,
          'rates_changed', 0,
          'tsfin_repricing_rows', 0,
          'source_records_mutated', false,
          'economic_truth_mutation_allowed', false,
          'refresh_completion_requires_terminal_exact_scope', true,
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
          'policy_x_dirtying_only', true
        )
      );

      INSERT INTO public.banking_pay_workbench_jobs (
        job_type,
        status,
        priority,
        run_at_utc,
        attempt_count,
        max_attempts,
        dedupe_key,
        snapshot_run_id,
        session_id,
        candidate_id,
        payload_json,
        created_at_utc,
        updated_at_utc,
        started_at_utc,
        completed_at_utc,
        failed_at_utc,
        last_error_json
      )
      VALUES (
        'WORKBENCH_CANDIDATE_DIRTY_APPLY',
        CASE WHEN COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) = 0 THEN 'SUCCEEDED' ELSE 'QUEUED' END,
        -1000,
        v_now,
        0,
        8,
        v_route_dedupe_key,
        NULL,
        NULL,
        p_candidate_id,
        v_route_job_payload,
        v_now,
        v_now,
        NULL,
        CASE WHEN COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) = 0 THEN v_now ELSE NULL END,
        NULL,
        NULL
      )
      RETURNING id, status, payload_json
      INTO v_route_job_id, v_route_job_status, v_route_job_payload;
    END IF;
  END IF;

  RETURN (
    jsonb_build_object(
      'ok', true,
      'candidate_id', p_candidate_id::text,
      'candidate_current_method', v_candidate_current_method,
      'source_method', v_source_method,
      'target_method', v_target_method,
      'latest_source_change_seq', v_latest_source_change_seq,
      'source_change_seq', v_latest_source_change_seq,
      'durable_job_id', CASE WHEN v_route_job_id IS NULL THEN NULL ELSE v_route_job_id::text END,
      'durable_job_status', v_route_job_status,
      'durable_job_dedupe_key', v_route_dedupe_key,
      'durable_scope_persisted', v_route_job_id IS NOT NULL,
      'coverage_basis', 'CANONICAL_TIMESHEETS_WITH_RETAINED_FINANCE_AUTHORITY',
      'coverage_complete', true,
      'exact_scope', true,
      'authoritative_sessions', v_authoritative_sessions_json,
      'replaced_source_session_ids', v_replaced_source_session_ids_json,
      'represented_timesheet_ids', to_jsonb(v_represented_timesheet_ids),
      'authorised_timesheet_ids', to_jsonb(v_authorised_timesheet_ids),
      'active_advance_timesheet_ids', to_jsonb(v_active_advance_timesheet_ids),
      'retained_finance_timesheet_ids', to_jsonb(v_retained_finance_timesheet_ids)
    )
    || jsonb_build_object(
      'targeted_timesheet_ids', to_jsonb(v_targeted_timesheet_ids),
      'targeted_scope_is_empty', COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) = 0,
      'authoritative_session_count', jsonb_array_length(v_authoritative_sessions_json),
      'preview_row_count', v_preview_row_count,
      'represented_timesheet_count', COALESCE(array_length(v_represented_timesheet_ids, 1), 0),
      'authorised_timesheet_count', COALESCE(array_length(v_authorised_timesheet_ids, 1), 0),
      'active_advance_timesheet_count', COALESCE(array_length(v_active_advance_timesheet_ids, 1), 0),
      'retained_finance_timesheet_count', COALESCE(array_length(v_retained_finance_timesheet_ids, 1), 0),
      'targeted_timesheet_count', COALESCE(array_length(v_targeted_timesheet_ids, 1), 0),
      'source_target_mismatch_count', COALESCE(v_source_target_mismatch_count, 0),
      'target_details', v_target_details_json,
      'contracts_changed', 0,
      'contract_weeks_changed', 0,
      'timesheets_changed', 0,
      'rates_changed', 0,
      'tsfin_repricing_rows', 0,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
      'policy_x_dirtying_only', true
    )
  );
END;
$function$;

ALTER FUNCTION public.candidate_pay_method_change_refresh_scope_v1(p_candidate_id uuid, p_source_method text, p_target_method text) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.candidate_pay_method_change_refresh_scope_v1(p_candidate_id uuid, p_source_method text, p_target_method text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.candidate_pay_method_change_refresh_scope_v1(p_candidate_id uuid, p_source_method text, p_target_method text) TO postgres;
GRANT EXECUTE ON FUNCTION public.candidate_pay_method_change_refresh_scope_v1(p_candidate_id uuid, p_source_method text, p_target_method text) TO service_role;

-- -----------------------------------------------------------------------------
-- public.pay_workbench_contract_client_dirty_fanout_chunk(p_job_id uuid, p_cursor_json jsonb, p_limit integer)
-- Installed pg_get_functiondef MD5: 4230c3cd60c64f3c767d5332220681b7
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.pay_workbench_contract_client_dirty_fanout_chunk(p_job_id uuid, p_cursor_json jsonb DEFAULT NULL::jsonb, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 100);
  v_job_row public.banking_pay_workbench_jobs%ROWTYPE;
  v_payload_json jsonb := '{}'::jsonb;
  v_cursor_json jsonb := '{}'::jsonb;
  v_scope_kind text := '';
  v_scope_id_text text := NULL::text;
  v_scope_id uuid := NULL::uuid;
  v_specific_scope_id_text text := NULL::text;
  v_specific_scope_id uuid := NULL::uuid;
  v_payload_candidate_id_text text := NULL::text;
  v_payload_candidate_id uuid := NULL::uuid;
  v_payload_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_payload_candidate_value jsonb := NULL::jsonb;
  v_payload_candidate_value_text text := NULL::text;
  v_payload_candidate_index integer := 0;
  v_cursor_candidate_id_text text := NULL::text;
  v_cursor_candidate_id uuid := NULL::uuid;
  v_reason text := NULL::text;
  v_trigger_table text := NULL::text;
  v_trigger_op text := NULL::text;
  v_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_candidate_ids_json jsonb := '[]'::jsonb;
  v_candidate_count integer := 0;
  v_has_more boolean := false;
  v_last_candidate_id uuid := NULL::uuid;
  v_next_cursor_json jsonb := NULL::jsonb;
  v_affected_scope_count integer := 0;
  v_affected_session_count integer := 0;
  v_jobs_queued_or_reused integer := 0;
  v_source_rows_marked_dirty_count integer := 0;
  v_gate_candidate_id uuid := NULL::uuid;
  v_gate_result jsonb := '{}'::jsonb;
  v_gate_allowed_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_gate_blocked boolean := false;
  v_gate_blocked_candidate_id uuid := NULL::uuid;
  v_gate_last_allowed_candidate_id uuid := NULL::uuid;
  v_gate_allowed_count integer := 0;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  IF p_job_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_FANOUT_JOB_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_DIRTY_FANOUT_JOB_ID_REQUIRED'
            )::text;
  END IF;

  SELECT fanout_job.*
  INTO v_job_row
  FROM public.banking_pay_workbench_jobs AS fanout_job
  WHERE fanout_job.id = p_job_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_FANOUT_JOB_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_DIRTY_FANOUT_JOB_NOT_FOUND',
              'job_id', p_job_id::text
            )::text;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_job_row.job_type, ''))) <> 'CONTRACT_CLIENT_DIRTY_FANOUT' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_FANOUT_JOB_TYPE_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_DIRTY_FANOUT_JOB_TYPE_INVALID',
              'job_id', v_job_row.id::text,
              'job_type', v_job_row.job_type
            )::text;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_job_row.status, ''))) <> 'RUNNING' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_FANOUT_JOB_NOT_RUNNING'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_DIRTY_FANOUT_JOB_NOT_RUNNING',
              'job_id', v_job_row.id::text,
              'status', v_job_row.status
            )::text;
  END IF;

  IF v_job_row.scope_change_generation IS NOT NULL THEN
    PERFORM set_config(
      'cloudtms.banking_pay_inherited_scope_generation',
      v_job_row.scope_change_generation::text,
      true
    );
  END IF;

  v_payload_json := CASE
    WHEN jsonb_typeof(COALESCE(v_job_row.payload_json, '{}'::jsonb)) = 'object'
      THEN COALESCE(v_job_row.payload_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;

  v_cursor_json := CASE
    WHEN p_cursor_json IS NOT NULL
         AND jsonb_typeof(p_cursor_json) = 'object'
      THEN p_cursor_json
    WHEN jsonb_typeof(v_payload_json->'cursor_json') = 'object'
      THEN v_payload_json->'cursor_json'
    WHEN jsonb_typeof(v_payload_json->'cursor') = 'object'
      THEN v_payload_json->'cursor'
    ELSE '{}'::jsonb
  END;

  v_scope_kind := UPPER(BTRIM(COALESCE(v_payload_json->>'scope_kind', '')));

  IF v_scope_kind NOT IN ('CONTRACT', 'CLIENT', 'UMBRELLA') THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_FANOUT_SCOPE_KIND_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_DIRTY_FANOUT_SCOPE_KIND_INVALID',
              'job_id', v_job_row.id::text,
              'scope_kind', v_scope_kind
            )::text;
  END IF;

  v_scope_id_text := COALESCE(
    NULLIF(BTRIM(COALESCE(v_payload_json->>'scope_id', '')), ''),
    CASE
      WHEN v_scope_kind = 'CONTRACT'
        THEN NULLIF(BTRIM(COALESCE(v_payload_json->>'contract_id', '')), '')
      WHEN v_scope_kind = 'CLIENT'
        THEN NULLIF(BTRIM(COALESCE(v_payload_json->>'client_id', '')), '')
      WHEN v_scope_kind = 'UMBRELLA'
        THEN NULLIF(BTRIM(COALESCE(v_payload_json->>'umbrella_id', '')), '')
      ELSE NULL::text
    END
  );

  IF COALESCE(v_scope_id_text, '')
     !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_FANOUT_SCOPE_ID_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_DIRTY_FANOUT_SCOPE_ID_INVALID',
              'job_id', v_job_row.id::text,
              'scope_kind', v_scope_kind,
              'scope_id', v_scope_id_text
            )::text;
  END IF;

  v_scope_id := v_scope_id_text::uuid;

  v_specific_scope_id_text := CASE
    WHEN v_scope_kind = 'CONTRACT'
      THEN NULLIF(BTRIM(COALESCE(v_payload_json->>'contract_id', '')), '')
    WHEN v_scope_kind = 'CLIENT'
      THEN NULLIF(BTRIM(COALESCE(v_payload_json->>'client_id', '')), '')
    WHEN v_scope_kind = 'UMBRELLA'
      THEN NULLIF(BTRIM(COALESCE(v_payload_json->>'umbrella_id', '')), '')
    ELSE NULL::text
  END;

  IF v_specific_scope_id_text IS NOT NULL THEN
    IF v_specific_scope_id_text
       !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_FANOUT_SPECIFIC_SCOPE_ID_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_DIRTY_FANOUT_SPECIFIC_SCOPE_ID_INVALID',
                'job_id', v_job_row.id::text,
                'scope_kind', v_scope_kind,
                'scope_id', v_scope_id::text,
                'specific_scope_id', v_specific_scope_id_text
              )::text;
    END IF;

    v_specific_scope_id := v_specific_scope_id_text::uuid;

    IF v_specific_scope_id IS DISTINCT FROM v_scope_id THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_FANOUT_SCOPE_PAYLOAD_CONFLICT'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_DIRTY_FANOUT_SCOPE_PAYLOAD_CONFLICT',
                'job_id', v_job_row.id::text,
                'scope_kind', v_scope_kind,
                'scope_id', v_scope_id::text,
                'specific_scope_id', v_specific_scope_id::text
              )::text;
    END IF;
  END IF;

  IF v_payload_json ? 'candidate_ids' THEN
    IF jsonb_typeof(v_payload_json->'candidate_ids') IS DISTINCT FROM 'array' THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_FANOUT_CANDIDATE_IDS_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_DIRTY_FANOUT_CANDIDATE_IDS_INVALID',
                'job_id', v_job_row.id::text,
                'candidate_ids', v_payload_json->'candidate_ids'
              )::text;
    END IF;

    v_payload_candidate_index := 0;

    FOR v_payload_candidate_value IN
      SELECT payload_candidate.value
      FROM jsonb_array_elements(v_payload_json->'candidate_ids') AS payload_candidate(value)
    LOOP
      v_payload_candidate_index := v_payload_candidate_index + 1;
      v_payload_candidate_value_text := CASE
        WHEN jsonb_typeof(v_payload_candidate_value) = 'string'
          THEN NULLIF(BTRIM(v_payload_candidate_value #>> '{}'), '')
        ELSE NULL::text
      END;

      IF COALESCE(v_payload_candidate_value_text, '')
         !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_FANOUT_CANDIDATE_IDS_INVALID'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_WORKBENCH_DIRTY_FANOUT_CANDIDATE_IDS_INVALID',
                  'job_id', v_job_row.id::text,
                  'candidate_index', v_payload_candidate_index,
                  'candidate_value', v_payload_candidate_value
                )::text;
      END IF;

      v_payload_candidate_ids := array_append(
        v_payload_candidate_ids,
        v_payload_candidate_value_text::uuid
      );
    END LOOP;

    SELECT COALESCE(
      array_agg(DISTINCT payload_candidate.candidate_id ORDER BY payload_candidate.candidate_id),
      ARRAY[]::uuid[]
    )
    INTO v_payload_candidate_ids
    FROM unnest(v_payload_candidate_ids) AS payload_candidate(candidate_id);
  END IF;

  v_payload_candidate_id_text := NULLIF(
    BTRIM(COALESCE(v_payload_json->>'candidate_id', '')),
    ''
  );

  IF v_payload_candidate_id_text IS NOT NULL THEN
    IF v_payload_candidate_id_text
       !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_FANOUT_CANDIDATE_ID_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_DIRTY_FANOUT_CANDIDATE_ID_INVALID',
                'job_id', v_job_row.id::text,
                'candidate_id', v_payload_candidate_id_text
              )::text;
    END IF;

    v_payload_candidate_id := v_payload_candidate_id_text::uuid;
  END IF;

  v_cursor_candidate_id_text := COALESCE(
    NULLIF(BTRIM(COALESCE(v_cursor_json->>'last_candidate_id', '')), ''),
    NULLIF(BTRIM(COALESCE(v_cursor_json->>'after_candidate_id', '')), ''),
    NULLIF(BTRIM(COALESCE(v_cursor_json->>'candidate_id', '')), '')
  );

  IF v_cursor_candidate_id_text IS NOT NULL THEN
    IF v_cursor_candidate_id_text
       !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_FANOUT_CURSOR_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_DIRTY_FANOUT_CURSOR_INVALID',
                'job_id', v_job_row.id::text,
                'cursor_json', v_cursor_json
              )::text;
    END IF;

    v_cursor_candidate_id := v_cursor_candidate_id_text::uuid;
  END IF;

  v_reason := COALESCE(
    NULLIF(BTRIM(COALESCE(v_payload_json->>'reason', '')), ''),
    'DIRTY_FANOUT:' || v_scope_kind
  );
  v_trigger_table := NULLIF(BTRIM(COALESCE(v_payload_json->>'trigger_table', '')), '');
  v_trigger_op := NULLIF(BTRIM(COALESCE(v_payload_json->>'trigger_op', '')), '');

  WITH candidate_pool AS (
    SELECT historical_candidate.candidate_id
    FROM unnest(v_payload_candidate_ids) AS historical_candidate(candidate_id)
    WHERE historical_candidate.candidate_id IS NOT NULL

    UNION

    SELECT v_payload_candidate_id AS candidate_id
    WHERE v_payload_candidate_id IS NOT NULL

    UNION

    SELECT derived_payload_candidate.candidate_id
    FROM public._pay_workbench_candidate_serial_candidate_ids(v_job_row.candidate_id, v_payload_json) AS derived_payload_candidate(candidate_id)
    WHERE derived_payload_candidate.candidate_id IS NOT NULL

    UNION

    SELECT contract_scope.candidate_id
    FROM public.contracts AS contract_scope
    WHERE v_scope_kind = 'CONTRACT'
      AND contract_scope.id = v_scope_id
      AND contract_scope.candidate_id IS NOT NULL

    UNION

    SELECT client_contract.candidate_id
    FROM public.contracts AS client_contract
    WHERE v_scope_kind = 'CLIENT'
      AND client_contract.client_id = v_scope_id
      AND client_contract.candidate_id IS NOT NULL

    UNION

    SELECT umbrella_candidate.id
    FROM public.candidates AS umbrella_candidate
    WHERE v_scope_kind = 'UMBRELLA'
      AND umbrella_candidate.umbrella_id = v_scope_id
  ),
  ordered_candidates AS (
    SELECT candidate_pool.candidate_id,
           ROW_NUMBER() OVER (ORDER BY candidate_pool.candidate_id) AS candidate_ordinal
    FROM candidate_pool
    WHERE candidate_pool.candidate_id IS NOT NULL
      AND (
        v_cursor_candidate_id IS NULL
        OR candidate_pool.candidate_id > v_cursor_candidate_id
      )
    ORDER BY candidate_pool.candidate_id
    LIMIT (v_limit + 1)
  ),
  selected_candidates AS (
    SELECT ordered_candidates.candidate_id,
           ordered_candidates.candidate_ordinal
    FROM ordered_candidates
    WHERE ordered_candidates.candidate_ordinal <= v_limit
  )
  SELECT
    COALESCE(
      array_agg(
        selected_candidates.candidate_id
        ORDER BY selected_candidates.candidate_id
      ),
      ARRAY[]::uuid[]
    ),
    COALESCE(COUNT(*)::integer, 0),
    EXISTS (
      SELECT 1
      FROM ordered_candidates AS extra_candidate
      WHERE extra_candidate.candidate_ordinal > v_limit
    ),
    (
      SELECT last_selected.candidate_id
      FROM selected_candidates AS last_selected
      ORDER BY last_selected.candidate_id DESC
      LIMIT 1
    )
  INTO
    v_candidate_ids,
    v_candidate_count,
    v_has_more,
    v_last_candidate_id
  FROM selected_candidates;

  v_candidate_ids_json := COALESCE(to_jsonb(v_candidate_ids), '[]'::jsonb);

  IF v_has_more AND v_last_candidate_id IS NOT NULL THEN
    v_next_cursor_json := jsonb_build_object(
      'last_candidate_id', v_last_candidate_id::text,
      'scope_kind', v_scope_kind,
      'scope_id', v_scope_id::text
    );
  ELSE
    v_next_cursor_json := NULL::jsonb;
  END IF;

  IF COALESCE(v_candidate_count, 0) = 0 THEN
    RETURN jsonb_build_object(
      'ok', true,
      'job_id', v_job_row.id::text,
      'job_type', v_job_row.job_type,
      'scope_kind', v_scope_kind,
      'scope_id', v_scope_id::text,
      'reason', v_reason,
      'limit', v_limit,
      'cursor_json', v_cursor_json,
      'candidate_ids', '[]'::jsonb,
      'candidate_count', 0,
      'processed_count', 0,
      'affected_scope_count', 0,
      'affected_session_count', 0,
      'enqueued_count', 0,
      'has_more', false,
      'next_cursor', NULL::jsonb,
      'next_cursor_json', NULL::jsonb,
      'candidate_line_calculation_performed', false
    );
  END IF;

  v_gate_allowed_candidate_ids := ARRAY[]::uuid[];
  v_gate_blocked := false;
  v_gate_blocked_candidate_id := NULL::uuid;
  v_gate_last_allowed_candidate_id := NULL::uuid;

  FOREACH v_gate_candidate_id IN ARRAY v_candidate_ids
  LOOP
    v_gate_result := public._pay_workbench_candidate_serial_try_gate(
      p_job_id => v_job_row.id,
      p_candidate_id => v_gate_candidate_id,
      p_job_type => v_job_row.job_type,
      p_payload_json => v_payload_json || jsonb_build_object(
        'candidate_id', v_gate_candidate_id::text,
        'candidate_serial_candidate_id', v_gate_candidate_id::text,
        'candidate_serial_key', public._pay_workbench_candidate_serial_key(v_gate_candidate_id),
        'fanout_scope_kind', v_scope_kind,
        'fanout_scope_id', v_scope_id::text,
        'cursor_json', v_cursor_json
      ),
      p_reason => 'CANDIDATE_SERIAL_CONTRACT_CLIENT_FANOUT_GATE'
    );

    IF lower(BTRIM(COALESCE(v_gate_result->>'blocked', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
       OR lower(BTRIM(COALESCE(v_gate_result->>'allowed', 'true'))) IN ('false', 'f', '0', 'no', 'n', 'off') THEN
      v_gate_blocked := true;
      v_gate_blocked_candidate_id := v_gate_candidate_id;
      EXIT;
    END IF;

    v_gate_allowed_candidate_ids := array_append(v_gate_allowed_candidate_ids, v_gate_candidate_id);
    v_gate_last_allowed_candidate_id := v_gate_candidate_id;
  END LOOP;

  IF v_gate_blocked IS TRUE THEN
    SELECT COALESCE(array_agg(DISTINCT allowed_candidate.candidate_id ORDER BY allowed_candidate.candidate_id), ARRAY[]::uuid[])
    INTO v_candidate_ids
    FROM unnest(COALESCE(v_gate_allowed_candidate_ids, ARRAY[]::uuid[])) AS allowed_candidate(candidate_id)
    WHERE allowed_candidate.candidate_id IS NOT NULL;

    v_candidate_count := COALESCE(array_length(v_candidate_ids, 1), 0);
    v_candidate_ids_json := COALESCE(to_jsonb(v_candidate_ids), '[]'::jsonb);
    v_has_more := true;
    v_last_candidate_id := v_gate_last_allowed_candidate_id;

    v_next_cursor_json := jsonb_strip_nulls(
      CASE
        WHEN v_gate_last_allowed_candidate_id IS NOT NULL THEN
          jsonb_build_object(
            'last_candidate_id', v_gate_last_allowed_candidate_id::text,
            'scope_kind', v_scope_kind,
            'scope_id', v_scope_id::text
          )
        ELSE
          COALESCE(v_cursor_json, '{}'::jsonb)
          || jsonb_build_object(
            'scope_kind', v_scope_kind,
            'scope_id', v_scope_id::text
          )
      END
      || jsonb_build_object(
        'candidate_serial_blocked_candidate_id', v_gate_blocked_candidate_id::text,
        'candidate_serial_blocked_at_utc', v_now::text,
        'candidate_serial_wait_reason', COALESCE(v_gate_result->>'reason', 'CANDIDATE_SERIAL_CONTRACT_CLIENT_FANOUT_DELAYED'),
        'candidate_serial_delayed', true
      )
    );

    PERFORM public._pay_workbench_candidate_serial_audit(
      'CANDIDATE_SERIAL_CONTRACT_CLIENT_FANOUT_DELAYED',
      v_job_row.id,
      v_gate_blocked_candidate_id,
      COALESCE(v_gate_result, '{}'::jsonb) || jsonb_build_object(
        'job_type', v_job_row.job_type,
        'scope_kind', v_scope_kind,
        'scope_id', v_scope_id::text,
        'cursor_json', v_cursor_json,
        'next_cursor_json', v_next_cursor_json,
        'allowed_before_block_count', COALESCE(v_candidate_count, 0),
        'blocked_candidate_preserved', true,
        'candidate_mutation_skipped_for_blocked_candidate', true
      ),
      'CANDIDATE_SERIAL_CONTRACT_CLIENT_FANOUT_DELAYED',
      NULL::uuid
    );

    IF COALESCE(v_candidate_count, 0) = 0 THEN
      UPDATE public.banking_pay_workbench_jobs AS delayed_job
      SET payload_json = public._pay_workbench_dirty_payload_merge(
            COALESCE(delayed_job.payload_json, '{}'::jsonb),
            jsonb_build_object(
              'candidate_serial_delayed', true,
              'candidate_serial_blocked_candidate_id', v_gate_blocked_candidate_id::text,
              'candidate_serial_wait_reason', COALESCE(v_gate_result->>'reason', 'CANDIDATE_SERIAL_CONTRACT_CLIENT_FANOUT_DELAYED'),
              'next_cursor_json', v_next_cursor_json,
              'cursor_json', v_next_cursor_json,
              'has_more', true,
              'rerun_required', true,
              'candidate_mutation_skipped_for_blocked_candidate', true,
              'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
            )
          ),
          updated_at_utc = v_now
      WHERE delayed_job.id = v_job_row.id;

      RETURN jsonb_build_object(
        'ok', true,
        'job_id', v_job_row.id::text,
        'job_type', v_job_row.job_type,
        'scope_kind', v_scope_kind,
        'scope_id', v_scope_id::text,
        'reason', v_reason,
        'limit', v_limit,
        'cursor_json', v_cursor_json,
        'candidate_ids', '[]'::jsonb,
        'candidate_count', 0,
        'processed_count', 0,
        'affected_scope_count', 0,
        'affected_session_count', 0,
        'enqueued_count', 0,
        'has_more', true,
        'next_cursor', v_next_cursor_json,
        'next_cursor_json', v_next_cursor_json,
        'candidate_serial_delayed', true,
        'candidate_serial_blocked_candidate_id', v_gate_blocked_candidate_id::text,
        'candidate_mutation_skipped_for_blocked_candidate', true,
        'candidate_line_calculation_performed', false
      );
    END IF;
  END IF;

  CREATE TEMPORARY TABLE IF NOT EXISTS pay_workbench_dirty_fanout_candidates (
    candidate_id uuid PRIMARY KEY,
    source_change_seq bigint NOT NULL DEFAULT 0
  ) ON COMMIT DROP;

  CREATE TEMPORARY TABLE IF NOT EXISTS pay_workbench_dirty_fanout_affected_scope (
    session_id uuid NOT NULL,
    candidate_id uuid NOT NULL,
    PRIMARY KEY (session_id, candidate_id)
  ) ON COMMIT DROP;

  TRUNCATE TABLE pg_temp.pay_workbench_dirty_fanout_candidates;
  TRUNCATE TABLE pg_temp.pay_workbench_dirty_fanout_affected_scope;

  INSERT INTO pg_temp.pay_workbench_dirty_fanout_candidates (
    candidate_id,
    source_change_seq
  )
  SELECT page_candidate.candidate_id,
         0::bigint
  FROM unnest(v_candidate_ids) AS page_candidate(candidate_id)
  ON CONFLICT (candidate_id) DO NOTHING;

  WITH bumped_counters AS (
    INSERT INTO public.app_change_counters AS candidate_counter (
      entity_key,
      seq,
      updated_at
    )
    SELECT
      'pay_candidate:' || fanout_candidate.candidate_id::text,
      1::bigint,
      v_now
    FROM pg_temp.pay_workbench_dirty_fanout_candidates AS fanout_candidate
    ON CONFLICT (entity_key)
    DO UPDATE
    SET seq = candidate_counter.seq + 1,
        updated_at = v_now
    RETURNING candidate_counter.entity_key,
              candidate_counter.seq
  )
  UPDATE pg_temp.pay_workbench_dirty_fanout_candidates AS fanout_candidate
  SET source_change_seq = bumped_counter.seq
  FROM bumped_counters AS bumped_counter
  WHERE bumped_counter.entity_key = 'pay_candidate:' || fanout_candidate.candidate_id::text;

  WITH candidate_open_scope AS (
    SELECT
      scope_row.session_id,
      scope_row.candidate_id,
      open_session.actor_user_id,
      open_session.pay_date,
      MAX(open_session.pay_date) OVER (
        PARTITION BY open_session.actor_user_id
      ) AS latest_actor_open_pay_date
    FROM public.banking_pay_workbench_session_scope AS scope_row
    JOIN public.banking_pay_workbench_sessions AS open_session
      ON open_session.id = scope_row.session_id
    JOIN pg_temp.pay_workbench_dirty_fanout_candidates AS fanout_candidate
      ON fanout_candidate.candidate_id = scope_row.candidate_id
    WHERE open_session.status = 'OPEN'
      AND open_session.discarded_at_utc IS NULL
  ),
  affected_scope AS (
    UPDATE public.banking_pay_workbench_session_scope AS scope_update
    SET status = 'SOURCE_BUILD_PENDING',
        dirty = true,
        error_json = NULL::jsonb,
        updated_at_utc = v_now
    FROM candidate_open_scope AS target_scope
    WHERE target_scope.session_id = scope_update.session_id
      AND target_scope.candidate_id = scope_update.candidate_id
      AND target_scope.pay_date = target_scope.latest_actor_open_pay_date
    RETURNING scope_update.session_id,
              scope_update.candidate_id
  )
  INSERT INTO pg_temp.pay_workbench_dirty_fanout_affected_scope (
    session_id,
    candidate_id
  )
  SELECT affected_scope.session_id,
         affected_scope.candidate_id
  FROM affected_scope
  ON CONFLICT (session_id, candidate_id) DO NOTHING;

  GET DIAGNOSTICS v_affected_scope_count = ROW_COUNT;

  WITH affected_session_summary AS (
    SELECT
      affected_scope.session_id,
      COUNT(*)::integer AS affected_candidate_count,
      (array_agg(
        affected_scope.candidate_id
        ORDER BY affected_scope.candidate_id DESC
      ))[1] AS last_candidate_id
    FROM pg_temp.pay_workbench_dirty_fanout_affected_scope AS affected_scope
    GROUP BY affected_scope.session_id
  ),
  updated_sessions AS (
    UPDATE public.banking_pay_workbench_sessions AS session_update
    SET progress_state = 'DIRTY',
        scope_pending_count = GREATEST(
          COALESCE(session_update.scope_pending_count, 0),
          1
        ),
        candidate_sample_rows_json = jsonb_build_array(
          jsonb_build_object(
            'candidate_id', affected_summary.last_candidate_id::text,
            'status', 'SOURCE_BUILD_PENDING',
            'reason', v_reason
          )
        ),
        progress_json = jsonb_strip_nulls(
          COALESCE(session_update.progress_json, '{}'::jsonb)
          || jsonb_build_object(
            'last_dirty_candidate_id', affected_summary.last_candidate_id::text,
            'last_dirty_reason', v_reason,
            'last_dirty_at_utc', v_now::text,
            'last_dirty_fanout_job_id', v_job_row.id::text,
            'last_dirty_fanout_scope_kind', v_scope_kind,
            'last_dirty_fanout_scope_id', v_scope_id::text,
            'last_dirty_fanout_candidate_count', affected_summary.affected_candidate_count
          )
        ),
        progress_counter_version = COALESCE(session_update.progress_counter_version, 0)
          + affected_summary.affected_candidate_count,
        progress_updated_at_utc = v_now,
        updated_at_utc = v_now
    FROM affected_session_summary AS affected_summary
    WHERE session_update.id = affected_summary.session_id
    RETURNING session_update.id
  )
  SELECT COUNT(*)::integer
  INTO v_affected_session_count
  FROM updated_sessions;

  WITH dirtied_source_rows AS (
    UPDATE public.banking_pay_workbench_candidate_source_lines AS source_line
    SET status = 'DIRTY',
        source_row_json = jsonb_strip_nulls(
          COALESCE(source_line.source_row_json, '{}'::jsonb)
          || jsonb_build_object(
            'dirty_reason', v_reason,
            'dirty_fanout_job_id', v_job_row.id::text,
            'dirty_fanout_scope_kind', v_scope_kind,
            'dirty_fanout_scope_id', v_scope_id::text,
            'dirty_trigger_table', v_trigger_table,
            'dirty_trigger_operation', v_trigger_op,
            'dirty_at_utc', v_now::text
          )
        ),
        updated_at_utc = v_now
    FROM pg_temp.pay_workbench_dirty_fanout_affected_scope AS affected_scope
    WHERE source_line.session_id = affected_scope.session_id
      AND source_line.candidate_id = affected_scope.candidate_id
      AND source_line.status = 'CURRENT'
    RETURNING source_line.id
  )
  SELECT COUNT(*)::integer
  INTO v_source_rows_marked_dirty_count
  FROM dirtied_source_rows;

  WITH upserted_jobs AS (
    INSERT INTO public.banking_pay_workbench_jobs AS refresh_job (
      job_type,
      status,
      priority,
      run_at_utc,
      attempt_count,
      max_attempts,
      dedupe_key,
      snapshot_run_id,
      session_id,
      candidate_id,
      payload_json,
      created_at_utc,
      updated_at_utc,
      started_at_utc,
      completed_at_utc,
      failed_at_utc,
      last_error_json
    )
    SELECT
      'WORKBENCH_CANDIDATE_SOURCE_BUILD',
      'QUEUED',
      44,
      v_now,
      0,
      8,
      'WORKBENCH_CANDIDATE_SOURCE_BUILD:'
        || open_session.id::text
        || ':'
        || affected_scope.candidate_id::text
        || ':v'
        || COALESCE(open_session.version, 0)::text
        || ':s'
        || COALESCE(fanout_candidate.source_change_seq, 0)::text
        || ':snapshot:'
        || open_session.source_snapshot_run_id::text
        || ':signature:'
        || md5(COALESCE(open_session.session_signature, ''))
        || ':source_build:'
        || source_build_identity.source_build_run_id::text
        || ':cursor:START',
      open_session.source_snapshot_run_id,
      open_session.id,
      affected_scope.candidate_id,
      jsonb_build_object(
        'trigger_table', v_trigger_table,
        'trigger_operation', v_trigger_op,
        'trigger_op', v_trigger_op,
        'scope_kind', 'CANDIDATE',
        'scope_id', affected_scope.candidate_id::text,
        'candidate_id', affected_scope.candidate_id::text,
        'reason', v_reason,
        'source_change_seq', fanout_candidate.source_change_seq,
        'source_change_sequence', fanout_candidate.source_change_seq,
        'refresh_scope_kind', 'CANDIDATE_FULL_LIVE',
        'candidate_serial_key', public._pay_workbench_candidate_serial_key(affected_scope.candidate_id),
        'candidate_serial_candidate_id', affected_scope.candidate_id::text,
        'candidate_serial_active_chain_id', COALESCE(NULLIF(BTRIM(COALESCE(v_job_row.payload_json->>'candidate_serial_active_chain_id', '')), ''), v_job_row.id::text),
        'candidate_serial_source_job_id', v_job_row.id::text,
        'candidate_serial_reason', 'CANDIDATE_SERIAL_FANOUT_SOURCE_BUILD_QUEUED'
      )
      || jsonb_build_object(
        'targeted_timesheet_ids', '[]'::jsonb,
        'linked_timesheet_ids', '[]'::jsonb,
        'session_id', open_session.id::text,
        'source_session_id', open_session.id::text,
        'session_version', COALESCE(open_session.version, 0),
        'session_signature', open_session.session_signature,
        'snapshot_run_id', open_session.source_snapshot_run_id::text,
        'source_snapshot_run_id', open_session.source_snapshot_run_id::text,
        'source_build_run_id', source_build_identity.source_build_run_id::text,
        'source_fanout_job_id', v_job_row.id::text
      )
      || jsonb_build_object(
        'fanout_scope_kind', v_scope_kind,
        'fanout_scope_id', v_scope_id::text,
        'job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
        'canonical_job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
        'source_build_required', true,
        'line_work_required', true,
        'line_work_only', false,
        'source_build_action', 'BUILD_SOURCE',
        'line_work_action', 'SOURCE_BUILD',
        'pay_channel_scope', COALESCE(NULLIF(UPPER(BTRIM(COALESCE(open_session.filters_json->>'pay_channel_scope', open_session.filters_json#>>'{filters,pay_channel_scope}', ''))), ''), 'ALL'),
        'limit', v_limit,
        'source_build_limit', v_limit,
        'source_rows_marked_dirty_count', COALESCE(v_source_rows_marked_dirty_count, 0)
      ),
      v_now,
      v_now,
      NULL::timestamptz,
      NULL::timestamptz,
      NULL::timestamptz,
      NULL::jsonb
    FROM pg_temp.pay_workbench_dirty_fanout_affected_scope AS affected_scope
    JOIN public.banking_pay_workbench_sessions AS open_session
      ON open_session.id = affected_scope.session_id
     AND open_session.status = 'OPEN'
     AND open_session.discarded_at_utc IS NULL
    JOIN pg_temp.pay_workbench_dirty_fanout_candidates AS fanout_candidate
      ON fanout_candidate.candidate_id = affected_scope.candidate_id
    CROSS JOIN LATERAL (
      SELECT md5(concat_ws(':',
        'WORKBENCH_CANDIDATE_SOURCE_BUILD',
        open_session.source_snapshot_run_id::text,
        open_session.id::text,
        affected_scope.candidate_id::text,
        COALESCE(open_session.version, 0)::text,
        COALESCE(fanout_candidate.source_change_seq, 0)::text,
        'CANDIDATE_FULL_LIVE',
        v_scope_kind,
        v_scope_id::text,
        v_reason
      )) AS source_build_hash
    ) AS source_build_hash
    CROSS JOIN LATERAL (
      SELECT (
        substr(source_build_hash.source_build_hash, 1, 8) || '-' ||
        substr(source_build_hash.source_build_hash, 9, 4) || '-' ||
        substr(source_build_hash.source_build_hash, 13, 4) || '-' ||
        substr(source_build_hash.source_build_hash, 17, 4) || '-' ||
        substr(source_build_hash.source_build_hash, 21, 12)
      )::uuid AS source_build_run_id
    ) AS source_build_identity
    ON CONFLICT (dedupe_key) WHERE status IN ('QUEUED', 'RUNNING')
    DO UPDATE
    SET priority = LEAST(refresh_job.priority, EXCLUDED.priority),
        run_at_utc = LEAST(refresh_job.run_at_utc, EXCLUDED.run_at_utc),
        payload_json = public._pay_workbench_merge_targeted_scope_payload(
          COALESCE(refresh_job.payload_json, '{}'::jsonb),
          COALESCE(EXCLUDED.payload_json, '{}'::jsonb)
        ),
        updated_at_utc = v_now
    RETURNING refresh_job.id
  )
  SELECT COUNT(*)::integer
  INTO v_jobs_queued_or_reused
  FROM upserted_jobs;

  RETURN jsonb_build_object(
      'ok', true,
      'job_id', v_job_row.id::text,
      'job_type', v_job_row.job_type,
      'scope_kind', v_scope_kind,
      'scope_id', v_scope_id::text,
      'reason', v_reason,
      'trigger_table', v_trigger_table,
      'trigger_op', v_trigger_op,
      'limit', v_limit,
      'cursor_json', v_cursor_json,
      'candidate_ids', v_candidate_ids_json,
      'candidate_count', COALESCE(v_candidate_count, 0),
      'processed_count', COALESCE(v_candidate_count, 0),
      'affected_scope_count', COALESCE(v_affected_scope_count, 0),
      'affected_session_count', COALESCE(v_affected_session_count, 0),
      'enqueued_count', COALESCE(v_jobs_queued_or_reused, 0),
      'jobs_queued_or_reused', COALESCE(v_jobs_queued_or_reused, 0),
      'source_rows_marked_dirty_count', COALESCE(v_source_rows_marked_dirty_count, 0),
      'first_stage_job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
    )
    || jsonb_build_object(
      'has_more', COALESCE(v_has_more, false),
      'candidate_serial_delayed', COALESCE(v_gate_blocked, false),
      'candidate_serial_blocked_candidate_id', CASE WHEN v_gate_blocked_candidate_id IS NULL THEN NULL::text ELSE v_gate_blocked_candidate_id::text END,
      'next_cursor', v_next_cursor_json,
      'next_cursor_json', v_next_cursor_json,
      'last_candidate_id', CASE
        WHEN v_last_candidate_id IS NULL THEN NULL::text
        ELSE v_last_candidate_id::text
      END,
      'candidate_line_calculation_performed', false,
      'session_created', false,
      'rpc_fanout_performed', false
    );
END;
$function$;

