     AND v_payload_session_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     AND v_payload_session_id_text::uuid IS DISTINCT FROM p_session_id THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_SESSION_ID_MISMATCH'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_SESSION_ID_MISMATCH',
              'argument_session_id', p_session_id::text,
              'payload_session_id', v_payload_session_id_text
            )::text;
  ELSIF v_payload_session_id_text IS NOT NULL
        AND v_payload_session_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_SESSION_ID_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_SESSION_ID_INVALID',
              'payload_session_id', v_payload_session_id_text
            )::text;
  END IF;

  v_payload_candidate_id_text := NULLIF(BTRIM(COALESCE(
    v_payload_json->>'candidate_id',
    v_payload_json#>>'{candidate,id}',
    v_cursor_json->>'candidate_id',
    ''
  )), '');

  IF v_payload_candidate_id_text IS NOT NULL
     AND v_payload_candidate_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     AND v_payload_candidate_id_text::uuid IS DISTINCT FROM p_candidate_id THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_CANDIDATE_ID_MISMATCH'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_CANDIDATE_ID_MISMATCH',
              'argument_candidate_id', p_candidate_id::text,
              'payload_candidate_id', v_payload_candidate_id_text
            )::text;
  ELSIF v_payload_candidate_id_text IS NOT NULL
        AND v_payload_candidate_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_CANDIDATE_ID_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_CANDIDATE_ID_INVALID',
              'payload_candidate_id', v_payload_candidate_id_text
            )::text;
  END IF;

  v_source_build_run_id_text := NULLIF(BTRIM(COALESCE(
    v_payload_json->>'source_build_run_id',
    v_payload_json#>>'{source_build,run_id}',
    v_payload_json#>>'{source_build,source_build_run_id}',
    v_cursor_json->>'source_build_run_id',
    ''
  )), '');

  IF v_source_build_run_id_text IS NULL
     OR v_source_build_run_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_RUN_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_RUN_ID_REQUIRED',
              'message', 'WORKBENCH_CANDIDATE_SOURCE_BUILD requires a stable source_build_run_id in payload_json.'
            )::text;
  END IF;
  v_source_build_run_id := v_source_build_run_id_text::uuid;

  v_source_change_seq_text := NULLIF(BTRIM(COALESCE(
    v_cursor_json->>'source_change_seq',
    v_payload_json->>'source_change_seq',
    v_payload_json->>'source_change_sequence',
    v_payload_json#>>'{source_build,source_change_seq}',
    ''
  )), '');

  v_source_change_seq_was_supplied := v_source_change_seq_text IS NOT NULL;

  IF v_source_change_seq_text IS NULL THEN
    v_source_change_seq := 0;
  ELSIF v_source_change_seq_text ~ '^[0-9]{1,18}$' THEN
    v_source_change_seq := v_source_change_seq_text::bigint;
  ELSE
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_SOURCE_CHANGE_SEQ_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_SOURCE_CHANGE_SEQ_INVALID',
              'source_change_seq', v_source_change_seq_text
            )::text;
  END IF;

  v_payload_session_version_text := NULLIF(BTRIM(COALESCE(
    v_payload_json->>'session_version',
    v_payload_json#>>'{source_build,session_version}',
    v_cursor_json->>'session_version',
    ''
  )), '');

  IF v_payload_session_version_text IS NULL THEN
    v_session_version := COALESCE(v_session_row.version, 1);
  ELSIF v_payload_session_version_text ~ '^[0-9]{1,18}$' THEN
    v_session_version := v_payload_session_version_text::bigint;
  ELSE
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_SESSION_VERSION_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_SESSION_VERSION_INVALID',
              'session_version', v_payload_session_version_text
            )::text;
  END IF;

  IF v_session_version IS DISTINCT FROM COALESCE(v_session_row.version, 1) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_SESSION_VERSION_STALE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_SESSION_VERSION_STALE',
              'payload_session_version', v_session_version,
              'current_session_version', COALESCE(v_session_row.version, 1)
            )::text;
  END IF;

  v_payload_snapshot_run_id_text := NULLIF(BTRIM(COALESCE(
    v_payload_json->>'source_snapshot_run_id',
    v_payload_json->>'snapshot_run_id',
    v_payload_json#>>'{source_build,source_snapshot_run_id}',
    v_cursor_json->>'source_snapshot_run_id',
    ''
  )), '');

  IF v_payload_snapshot_run_id_text IS NULL THEN
    v_payload_snapshot_run_id := v_session_row.source_snapshot_run_id;
  ELSIF v_payload_snapshot_run_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_payload_snapshot_run_id := v_payload_snapshot_run_id_text::uuid;
  ELSE
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_SNAPSHOT_RUN_ID_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_SNAPSHOT_RUN_ID_INVALID',
              'source_snapshot_run_id', v_payload_snapshot_run_id_text
            )::text;
  END IF;

  IF v_payload_snapshot_run_id IS DISTINCT FROM v_session_row.source_snapshot_run_id THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_SNAPSHOT_RUN_ID_MISMATCH'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_SNAPSHOT_RUN_ID_MISMATCH',
              'payload_source_snapshot_run_id', v_payload_snapshot_run_id::text,
              'session_source_snapshot_run_id', v_session_row.source_snapshot_run_id::text
            )::text;
  END IF;

  v_payload_session_signature := NULLIF(BTRIM(COALESCE(
    v_payload_json->>'session_signature',
    v_payload_json#>>'{source_build,session_signature}',
    v_cursor_json->>'session_signature',
    ''
  )), '');

  IF v_payload_session_signature IS NOT NULL
     AND v_payload_session_signature IS DISTINCT FROM v_session_row.session_signature THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_SESSION_SIGNATURE_MISMATCH'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_SESSION_SIGNATURE_MISMATCH',
              'payload_session_signature', v_payload_session_signature,
              'current_session_signature', v_session_row.session_signature
            )::text;
  END IF;

  v_payload_refresh_scope_kind := NULLIF(UPPER(BTRIM(COALESCE(
    v_payload_json->>'refresh_scope_kind',
    v_payload_json#>>'{source_build,refresh_scope_kind}',
    v_payload_json#>>'{preview_decisions_json,refresh_scope_kind}',
    ''
  ))), '');

  IF v_payload_refresh_scope_kind NOT IN ('TARGETED_TIMESHEETS', 'CANDIDATE_FULL_LIVE') THEN
    v_payload_refresh_scope_kind := NULL::text;
  END IF;

  v_cursor_requested_refresh_scope_kind := NULLIF(UPPER(BTRIM(COALESCE(
    v_cursor_json->>'requested_refresh_scope_kind',
    ''
  ))), '');

  IF v_cursor_requested_refresh_scope_kind NOT IN ('TARGETED_TIMESHEETS', 'CANDIDATE_FULL_LIVE') THEN
    v_cursor_requested_refresh_scope_kind := NULL::text;
  END IF;

  v_source_build_cursor_continuation := (
    (
      LOWER(BTRIM(COALESCE(v_payload_json->>'continuation', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      OR UPPER(BTRIM(COALESCE(
        v_payload_json->>'reason',
        v_payload_json->>'continuation_reason',
        v_payload_json#>>'{source_build,reason}',
        ''
      ))) = 'SOURCE_BUILD_CURSOR_CONTINUATION'
    )
    AND (
      NULLIF(BTRIM(COALESCE(v_cursor_json->>'last_timesheet_id', '')), '') IS NOT NULL
      OR NULLIF(BTRIM(COALESCE(v_cursor_json->>'last_source_ordinal', '')), '') IS NOT NULL
    )
  );

  v_refresh_scope_kind := COALESCE(
    CASE
      WHEN COALESCE(v_source_build_cursor_continuation, false)
        THEN v_cursor_requested_refresh_scope_kind
      ELSE NULL::text
    END,
    v_payload_refresh_scope_kind,
    v_cursor_requested_refresh_scope_kind,
    'CANDIDATE_FULL_LIVE'
  );

  IF v_refresh_scope_kind NOT IN ('TARGETED_TIMESHEETS', 'CANDIDATE_FULL_LIVE') THEN
    v_refresh_scope_kind := 'CANDIDATE_FULL_LIVE';
  END IF;
  v_requested_refresh_scope_kind := v_refresh_scope_kind;

  v_pay_channel_scope := NULLIF(UPPER(BTRIM(COALESCE(
    v_payload_json->>'pay_channel_scope',
    v_payload_json#>>'{source_build,pay_channel_scope}',
    v_payload_json#>>'{preview_decisions_json,pay_channel_scope}',
    v_session_row.filters_json->>'pay_channel_scope',
    v_session_row.filters_json#>>'{filters,pay_channel_scope}',
    'ALL'
  ))), '');

  IF v_pay_channel_scope NOT IN ('PAYE', 'UMBRELLA', 'ALL', 'LOANS') THEN
    v_pay_channel_scope := 'ALL';
  END IF;

  SELECT CASE
           WHEN UPPER(BTRIM(COALESCE(candidate_row.pay_method, ''))) IN ('PAYE', 'UMBRELLA')
             THEN UPPER(BTRIM(candidate_row.pay_method))
           ELSE 'ALL'
         END
  INTO v_candidate_pay_channel_scope
  FROM public.candidates AS candidate_row
  WHERE candidate_row.id = p_candidate_id
  LIMIT 1;

  SELECT COALESCE(jsonb_agg(parsed_target_ids.timesheet_id_text ORDER BY parsed_target_ids.timesheet_id_text), '[]'::jsonb)
  INTO v_targeted_timesheet_ids_json
  FROM (
    SELECT DISTINCT NULLIF(BTRIM(targeted_values.value), '') AS timesheet_id_text
    FROM jsonb_array_elements_text(
      CASE
        WHEN jsonb_typeof(v_payload_json->'targeted_timesheet_ids') = 'array' THEN v_payload_json->'targeted_timesheet_ids'
        WHEN jsonb_typeof(v_payload_json#>'{source_build,targeted_timesheet_ids}') = 'array' THEN v_payload_json#>'{source_build,targeted_timesheet_ids}'
        WHEN jsonb_typeof(v_payload_json#>'{preview_decisions_json,targeted_timesheet_ids}') = 'array' THEN v_payload_json#>'{preview_decisions_json,targeted_timesheet_ids}'
        WHEN jsonb_typeof(v_payload_json->'targeted_timesheet_ids') = 'string' THEN jsonb_build_array(v_payload_json->>'targeted_timesheet_ids')
        WHEN jsonb_typeof(v_payload_json#>'{source_build,targeted_timesheet_ids}') = 'string' THEN jsonb_build_array(v_payload_json#>>'{source_build,targeted_timesheet_ids}')
        WHEN jsonb_typeof(v_payload_json#>'{preview_decisions_json,targeted_timesheet_ids}') = 'string' THEN jsonb_build_array(v_payload_json#>>'{preview_decisions_json,targeted_timesheet_ids}')
        ELSE '[]'::jsonb
      END
    ) AS targeted_values(value)
    WHERE NULLIF(BTRIM(targeted_values.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) AS parsed_target_ids;

  SELECT COALESCE(jsonb_agg(parsed_linked_ids.timesheet_id_text ORDER BY parsed_linked_ids.timesheet_id_text), '[]'::jsonb)
  INTO v_linked_timesheet_ids_json
  FROM (
    SELECT DISTINCT NULLIF(BTRIM(linked_values.value), '') AS timesheet_id_text
    FROM jsonb_array_elements_text(
      CASE
        WHEN jsonb_typeof(v_payload_json->'linked_timesheet_ids') = 'array' THEN v_payload_json->'linked_timesheet_ids'
        WHEN jsonb_typeof(v_payload_json#>'{source_build,linked_timesheet_ids}') = 'array' THEN v_payload_json#>'{source_build,linked_timesheet_ids}'
        WHEN jsonb_typeof(v_payload_json#>'{preview_decisions_json,linked_timesheet_ids}') = 'array' THEN v_payload_json#>'{preview_decisions_json,linked_timesheet_ids}'
        WHEN jsonb_typeof(v_payload_json->'linked_timesheet_ids') = 'string' THEN jsonb_build_array(v_payload_json->>'linked_timesheet_ids')
        WHEN jsonb_typeof(v_payload_json#>'{source_build,linked_timesheet_ids}') = 'string' THEN jsonb_build_array(v_payload_json#>>'{source_build,linked_timesheet_ids}')
        WHEN jsonb_typeof(v_payload_json#>'{preview_decisions_json,linked_timesheet_ids}') = 'string' THEN jsonb_build_array(v_payload_json#>>'{preview_decisions_json,linked_timesheet_ids}')
        ELSE '[]'::jsonb
      END
    ) AS linked_values(value)
    WHERE NULLIF(BTRIM(linked_values.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) AS parsed_linked_ids;

  SELECT COALESCE(
    jsonb_agg(parsed_finance_case_ids.finance_case_id_text ORDER BY parsed_finance_case_ids.finance_case_id_text),
    '[]'::jsonb
  )
  INTO v_finance_case_ids_json
  FROM (
    SELECT DISTINCT NULLIF(BTRIM(finance_case_values.value), '') AS finance_case_id_text
    FROM jsonb_array_elements_text(
      CASE
        WHEN jsonb_typeof(v_payload_json->'finance_case_ids') = 'array' THEN v_payload_json->'finance_case_ids'
        WHEN jsonb_typeof(v_payload_json#>'{source_build,finance_case_ids}') = 'array' THEN v_payload_json#>'{source_build,finance_case_ids}'
        WHEN jsonb_typeof(v_payload_json#>'{preview_decisions_json,finance_case_ids}') = 'array' THEN v_payload_json#>'{preview_decisions_json,finance_case_ids}'
        WHEN jsonb_typeof(v_payload_json->'finance_case_id') = 'string' THEN jsonb_build_array(v_payload_json->>'finance_case_id')
        ELSE '[]'::jsonb
      END
    ) AS finance_case_values(value)
    WHERE NULLIF(BTRIM(finance_case_values.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) AS parsed_finance_case_ids;

  v_targeted_payload_received := jsonb_array_length(COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb)) > 0
    OR jsonb_array_length(COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb)) > 0
    OR jsonb_array_length(COALESCE(v_finance_case_ids_json, '[]'::jsonb)) > 0;

  IF v_refresh_scope_kind = 'TARGETED_TIMESHEETS'
     AND COALESCE(v_targeted_payload_received, false) IS NOT TRUE
     AND LOWER(BTRIM(COALESCE(v_payload_json->>'source_build_allow_full_fallback', v_payload_json#>>'{source_build,allow_full_fallback}', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on') THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_TARGETED_IDS_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_TARGETED_IDS_REQUIRED',
              'refresh_scope_kind', v_refresh_scope_kind,
              'message', 'TARGETED_TIMESHEETS source-build requires targeted_timesheet_ids or linked_timesheet_ids unless explicit full fallback is allowed.'
            )::text;
  END IF;

  IF v_cursor_json->>'last_timesheet_id' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_cursor_last_timesheet_id := (v_cursor_json->>'last_timesheet_id')::uuid;
  END IF;

  IF COALESCE(v_cursor_json->>'last_source_ordinal', '') ~ '^[0-9]{1,18}$' THEN
    v_cursor_source_ordinal_base := (v_cursor_json->>'last_source_ordinal')::bigint;
  ELSE
    v_cursor_source_ordinal_base := 0;
  END IF;

  v_first_source_page := v_cursor_last_timesheet_id IS NULL AND COALESCE(v_cursor_source_ordinal_base, 0) <= 0;

  SELECT COUNT(*)::integer
  INTO v_existing_source_row_count
  FROM public.banking_pay_workbench_candidate_source_lines AS existing_source_rows
  WHERE existing_source_rows.session_id = p_session_id
    AND existing_source_rows.candidate_id = p_candidate_id
    AND existing_source_rows.status = 'CURRENT';

  v_old_sync_marker := CASE
    WHEN jsonb_typeof(v_session_row.progress_json #> ARRAY['overpayment_sync_completed_by_candidate', p_candidate_id::text]) = 'object'
      THEN COALESCE(v_session_row.progress_json #> ARRAY['overpayment_sync_completed_by_candidate', p_candidate_id::text], '{}'::jsonb)
    ELSE '{}'::jsonb
  END;

  /* A historic bare completion marker is diagnostic only.  Reconciliation authority
     is re-established from the current session/run/scope/economic state below. */
  v_sync_completed := false;
  v_sync_attested := false;
  v_sync_marker_reused := false;

  SELECT COALESCE(ARRAY_AGG(parsed_target_ids.timesheet_id ORDER BY parsed_target_ids.timesheet_id), ARRAY[]::uuid[])
  INTO v_targeted_timesheet_ids
  FROM (
    SELECT DISTINCT targeted_id.value::uuid AS timesheet_id
    FROM jsonb_array_elements_text(COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb)) AS targeted_id(value)
    WHERE targeted_id.value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) AS parsed_target_ids;

  SELECT COALESCE(ARRAY_AGG(parsed_linked_ids.timesheet_id ORDER BY parsed_linked_ids.timesheet_id), ARRAY[]::uuid[])
  INTO v_linked_timesheet_ids
  FROM (
    SELECT DISTINCT linked_id.value::uuid AS timesheet_id
    FROM jsonb_array_elements_text(COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb)) AS linked_id(value)
    WHERE linked_id.value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) AS parsed_linked_ids;

  SELECT COALESCE(ARRAY_AGG(parsed_finance_case_ids.finance_case_id ORDER BY parsed_finance_case_ids.finance_case_id), ARRAY[]::uuid[])
  INTO v_finance_case_ids
  FROM (
    SELECT DISTINCT finance_case_id.value::uuid AS finance_case_id
    FROM jsonb_array_elements_text(COALESCE(v_finance_case_ids_json, '[]'::jsonb)) AS finance_case_id(value)
    WHERE finance_case_id.value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) AS parsed_finance_case_ids;

  IF v_requested_refresh_scope_kind = 'TARGETED_TIMESHEETS' THEN
    IF to_regprocedure(
         'public._pay_workbench_refresh_dependency_closure_v1(uuid,uuid[],uuid[],uuid[],integer,integer)'
       ) IS NULL THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_REFRESH_DEPENDENCY_CLOSURE_UNAVAILABLE'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_REFRESH_DEPENDENCY_CLOSURE_UNAVAILABLE',
                'session_id', p_session_id::text,
                'candidate_id', p_candidate_id::text
              )::text;
    END IF;

    EXECUTE
      'SELECT public._pay_workbench_refresh_dependency_closure_v1($1,$2,$3,$4,$5,$6)'
    INTO v_dependency_closure_json
    USING
      p_candidate_id,
      v_targeted_timesheet_ids,
      v_linked_timesheet_ids,
      v_finance_case_ids,
      250,
      100;

    v_dependency_closure_requires_full :=
      LOWER(BTRIM(COALESCE(
        v_dependency_closure_json->>'requires_full_candidate',
        'true'
      ))) IN ('true', 't', '1', 'yes', 'y', 'on')
      OR LOWER(BTRIM(COALESCE(
        v_dependency_closure_json->>'coverage_complete',
        'false'
      ))) NOT IN ('true', 't', '1', 'yes', 'y', 'on');
    v_dependency_closure_reason := NULLIF(BTRIM(COALESCE(
      v_dependency_closure_json->>'fallback_reason',
      ''
    )), '');

    IF v_dependency_closure_requires_full THEN
      v_requested_refresh_scope_kind := 'CANDIDATE_FULL_LIVE';
      v_refresh_scope_kind := 'CANDIDATE_FULL_LIVE';
      v_targeted_timesheet_ids := ARRAY[]::uuid[];
      v_linked_timesheet_ids := ARRAY[]::uuid[];
      v_finance_case_ids := ARRAY[]::uuid[];
      v_targeted_timesheet_ids_json := '[]'::jsonb;
      v_linked_timesheet_ids_json := '[]'::jsonb;
      v_finance_case_ids_json := '[]'::jsonb;
      v_fallback_used := true;
      v_fallback_reason := COALESCE(
        v_dependency_closure_reason,
        'DEPENDENCY_CLOSURE_INCOMPLETE'
      );
    ELSE
      SELECT COALESCE(array_agg(DISTINCT value::uuid ORDER BY value::uuid), ARRAY[]::uuid[])
      INTO v_targeted_timesheet_ids
      FROM jsonb_array_elements_text(
        COALESCE(v_dependency_closure_json->'effective_targeted_timesheet_ids', '[]'::jsonb)
      ) AS effective_timesheet(value)
      WHERE value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

      SELECT COALESCE(array_agg(DISTINCT value::uuid ORDER BY value::uuid), ARRAY[]::uuid[])
      INTO v_linked_timesheet_ids
      FROM jsonb_array_elements_text(
        COALESCE(v_dependency_closure_json->'effective_linked_timesheet_ids', '[]'::jsonb)
      ) AS effective_linked_timesheet(value)
      WHERE value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

      SELECT COALESCE(array_agg(DISTINCT value::uuid ORDER BY value::uuid), ARRAY[]::uuid[])
      INTO v_finance_case_ids
      FROM jsonb_array_elements_text(
        COALESCE(v_dependency_closure_json->'effective_finance_case_ids', '[]'::jsonb)
      ) AS effective_finance_case(value)
      WHERE value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

      v_targeted_timesheet_ids_json := to_jsonb(v_targeted_timesheet_ids);
      v_linked_timesheet_ids_json := to_jsonb(v_linked_timesheet_ids);
      v_finance_case_ids_json := to_jsonb(v_finance_case_ids);
    END IF;
  END IF;

  /* A targeted refresh of one import-authoritative correction leg must rebuild
     the whole correction chain.  The residual materialiser deliberately emits
     one net PRE_DRAFT_LIVE_TRUTH row per economic component and therefore needs
     a source carrier from the root or another member for every component.  A
     single-leg scope can never satisfy that invariant reliably. */
  IF v_requested_refresh_scope_kind = 'TARGETED_TIMESHEETS'
     AND EXISTS (
       SELECT 1
       FROM unnest(
         COALESCE(v_targeted_timesheet_ids, ARRAY[]::uuid[])
         || COALESCE(v_linked_timesheet_ids, ARRAY[]::uuid[])
       ) AS requested_correction_scope(timesheet_id)
       CROSS JOIN LATERAL (
         SELECT public.timesheet_correction_chain_scope_v1(
           requested_correction_scope.timesheet_id, false, 32, 100
         ) AS chain_json
       ) AS requested_chain
       WHERE COALESCE((requested_chain.chain_json->>'valid')::boolean, false)
         AND EXISTS (
           SELECT 1
           FROM jsonb_array_elements_text(
             COALESCE(requested_chain.chain_json->'member_timesheet_ids', '[]'::jsonb)
           ) AS chain_member(value)
           WHERE chain_member.value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
             AND COALESCE((
               public._ctms_import_correction_classify_v1(chain_member.value::uuid)
                 ->>'is_import_authoritative_correction'
             )::boolean, false)
         )
     ) THEN
    IF EXISTS (
      SELECT 1
      FROM unnest(
        COALESCE(v_targeted_timesheet_ids, ARRAY[]::uuid[])
        || COALESCE(v_linked_timesheet_ids, ARRAY[]::uuid[])
      ) AS requested_correction_scope(timesheet_id)
      CROSS JOIN LATERAL (
        SELECT public.timesheet_correction_chain_scope_v1(
          requested_correction_scope.timesheet_id, false, 32, 100
        ) AS chain_json
      ) AS requested_chain
      WHERE COALESCE((public._ctms_import_correction_classify_v1(requested_correction_scope.timesheet_id)
          ->>'is_import_authoritative_correction')::boolean, false)
        AND COALESCE((requested_chain.chain_json->>'valid')::boolean, false) IS NOT TRUE
    ) THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_CORRECTION_CHAIN_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_CORRECTION_CHAIN_INVALID',
                'session_id', p_session_id::text,
                'candidate_id', p_candidate_id::text,
                'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
              )::text;
    END IF;

    WITH requested_scope AS (
      SELECT DISTINCT requested_id AS timesheet_id
      FROM unnest(
        COALESCE(v_targeted_timesheet_ids, ARRAY[]::uuid[])
        || COALESCE(v_linked_timesheet_ids, ARRAY[]::uuid[])
      ) AS requested_values(requested_id)
      WHERE requested_id IS NOT NULL
    ), correction_chains AS (
      SELECT requested_chain.chain_json
      FROM requested_scope
      CROSS JOIN LATERAL (
        SELECT public.timesheet_correction_chain_scope_v1(
          requested_scope.timesheet_id, false, 32, 100
        ) AS chain_json
      ) AS requested_chain
      WHERE COALESCE((requested_chain.chain_json->>'valid')::boolean, false)
        AND EXISTS (
          SELECT 1
          FROM jsonb_array_elements_text(
            COALESCE(requested_chain.chain_json->'member_timesheet_ids', '[]'::jsonb)
          ) AS chain_member(value)
          WHERE chain_member.value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            AND COALESCE((
              public._ctms_import_correction_classify_v1(chain_member.value::uuid)
                ->>'is_import_authoritative_correction'
            )::boolean, false)
        )
    ), expanded_member_ids AS (
      SELECT DISTINCT member_id.value::uuid AS timesheet_id
      FROM correction_chains
      CROSS JOIN LATERAL jsonb_array_elements_text(
        COALESCE(correction_chains.chain_json->'member_timesheet_ids', '[]'::jsonb)
      ) AS member_id(value)
      WHERE member_id.value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ), expanded_target_scope AS (
      SELECT targeted_id AS timesheet_id
      FROM unnest(COALESCE(v_targeted_timesheet_ids, ARRAY[]::uuid[])) AS targeted_values(targeted_id)
      UNION
      SELECT expanded_member_ids.timesheet_id
      FROM expanded_member_ids
    )
    SELECT COALESCE(ARRAY_AGG(expanded_target_scope.timesheet_id ORDER BY expanded_target_scope.timesheet_id), ARRAY[]::uuid[])
    INTO v_targeted_timesheet_ids
    FROM expanded_target_scope;

    -- Linked scope carries resolution context but does not guarantee that a
    -- payable source row is materialised. Promote every correction member to
    -- the actual targeted set and retain only genuinely additional linked
    -- identifiers here.
    SELECT COALESCE(ARRAY_AGG(linked_id ORDER BY linked_id), ARRAY[]::uuid[])
    INTO v_linked_timesheet_ids
    FROM unnest(COALESCE(v_linked_timesheet_ids, ARRAY[]::uuid[])) AS linked_values(linked_id)
    WHERE NOT (linked_id = ANY(COALESCE(v_targeted_timesheet_ids, ARRAY[]::uuid[])));

    v_targeted_timesheet_ids_json := to_jsonb(COALESCE(v_targeted_timesheet_ids, ARRAY[]::uuid[]));
    v_linked_timesheet_ids_json := to_jsonb(COALESCE(v_linked_timesheet_ids, ARRAY[]::uuid[]));
  END IF;

  IF EXISTS (
    SELECT 1
    FROM unnest(COALESCE(v_targeted_timesheet_ids, ARRAY[]::uuid[]) || COALESCE(v_linked_timesheet_ids, ARRAY[]::uuid[])) AS requested_scope(timesheet_id)
    WHERE requested_scope.timesheet_id IS NOT NULL
      AND NOT EXISTS (
        SELECT 1
        FROM public.timesheets_financials AS requested_tsfin
        WHERE requested_tsfin.timesheet_id = requested_scope.timesheet_id
          AND requested_tsfin.candidate_id = p_candidate_id
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.pay_advances AS requested_case
        WHERE requested_case.linked_timesheet_id = requested_scope.timesheet_id
          AND requested_case.candidate_id = p_candidate_id
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.pay_finance_case_components AS requested_component
        WHERE requested_component.linked_timesheet_id = requested_scope.timesheet_id
          AND requested_component.candidate_id = p_candidate_id
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.timesheet_payment_overrides AS requested_override
        WHERE requested_override.timesheet_id = requested_scope.timesheet_id
          AND requested_override.candidate_id = p_candidate_id
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.ts_pay_adjustments AS requested_adjustment
        WHERE requested_adjustment.timesheet_id = requested_scope.timesheet_id
          AND requested_adjustment.candidate_id = p_candidate_id
      )
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_SCOPE_CANDIDATE_MISMATCH'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_SCOPE_CANDIDATE_MISMATCH',
              'session_id', p_session_id::text,
              'candidate_id', p_candidate_id::text,
              'targeted_timesheet_ids', COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb),
              'linked_timesheet_ids', COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb)
            )::text;
  END IF;

  v_filter_client_id_text := NULLIF(BTRIM(COALESCE(
    v_session_row.filters_json->>'client_id',
    v_session_row.filters_json->>'client_filter_single',
    v_session_row.filters_json#>>'{filters,client_id}',
    v_session_row.filters_json#>>'{client,id}',
    ''
  )), '');

  IF v_filter_client_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_client_filter_single := v_filter_client_id_text::uuid;
  ELSE
    v_client_filter_single := NULL::uuid;
  END IF;

  SELECT COALESCE(ARRAY_AGG(parsed_force_timesheet_id.timesheet_id ORDER BY parsed_force_timesheet_id.timesheet_id), ARRAY[]::uuid[])
  INTO v_force_include_timesheet_ids
  FROM (
    SELECT DISTINCT force_timesheet_id.value::uuid AS timesheet_id
    FROM jsonb_array_elements_text(
      CASE
        WHEN jsonb_typeof(v_session_row.filters_json->'force_include_timesheet_ids') = 'array' THEN v_session_row.filters_json->'force_include_timesheet_ids'
        WHEN jsonb_typeof(v_session_row.filters_json->'forced_timesheet_ids') = 'array' THEN v_session_row.filters_json->'forced_timesheet_ids'
        WHEN jsonb_typeof(v_session_row.filters_json#>'{scope,force_include_timesheet_ids}') = 'array' THEN v_session_row.filters_json#>'{scope,force_include_timesheet_ids}'
        ELSE '[]'::jsonb
      END
    ) AS force_timesheet_id(value)
    WHERE force_timesheet_id.value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      AND EXISTS (
        SELECT 1
        FROM public.timesheets_financials AS force_tsfin
        WHERE force_tsfin.timesheet_id = force_timesheet_id.value::uuid
          AND force_tsfin.candidate_id = p_candidate_id
      )
  ) AS parsed_force_timesheet_id;

  SELECT COALESCE(ARRAY_AGG(parsed_exclude_timesheet_id.timesheet_id ORDER BY parsed_exclude_timesheet_id.timesheet_id), ARRAY[]::uuid[])
  INTO v_exclude_timesheet_ids
  FROM (
    SELECT DISTINCT exclude_timesheet_id.value::uuid AS timesheet_id
    FROM jsonb_array_elements_text(
      CASE
        WHEN jsonb_typeof(v_session_row.filters_json->'exclude_timesheet_ids') = 'array' THEN v_session_row.filters_json->'exclude_timesheet_ids'
        WHEN jsonb_typeof(v_session_row.filters_json#>'{scope,exclude_timesheet_ids}') = 'array' THEN v_session_row.filters_json#>'{scope,exclude_timesheet_ids}'
        ELSE '[]'::jsonb
      END
    ) AS exclude_timesheet_id(value)
    WHERE exclude_timesheet_id.value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      AND EXISTS (
        SELECT 1
        FROM public.timesheets_financials AS exclude_tsfin
        WHERE exclude_tsfin.timesheet_id = exclude_timesheet_id.value::uuid
          AND exclude_tsfin.candidate_id = p_candidate_id
      )
  ) AS parsed_exclude_timesheet_id;

  v_mismatch_choices_json := CASE
    WHEN jsonb_typeof(v_session_row.filters_json->'mismatch_choices') = 'object' THEN COALESCE(v_session_row.filters_json->'mismatch_choices', '{}'::jsonb)
    WHEN jsonb_typeof(v_session_row.filters_json#>'{mismatch,choices}') = 'object' THEN COALESCE(v_session_row.filters_json#>'{mismatch,choices}', '{}'::jsonb)
    ELSE '{}'::jsonb
  END;

  SELECT COALESCE(change_counter.seq, 0)
  INTO v_current_source_change_seq
  FROM (SELECT 1) AS anchor
  LEFT JOIN public.app_change_counters AS change_counter
    ON change_counter.entity_key = 'pay_candidate:' || p_candidate_id::text;

  v_initial_source_change_seq := COALESCE(v_current_source_change_seq, 0);

  IF COALESCE(v_source_change_seq_was_supplied, false) IS TRUE
     AND COALESCE(v_current_source_change_seq, 0) IS DISTINCT FROM COALESCE(v_source_change_seq, 0) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_SOURCE_CHANGE_SEQ_STALE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_SOURCE_CHANGE_SEQ_STALE',
              'session_id', p_session_id::text,
              'candidate_id', p_candidate_id::text,
              'payload_source_change_seq', COALESCE(v_source_change_seq, 0),
              'current_source_change_seq', COALESCE(v_current_source_change_seq, 0)
            )::text;
  ELSIF COALESCE(v_source_change_seq_was_supplied, false) IS NOT TRUE THEN
    /* Older valid callers may omit the sequence.  Bind the run to the current
       candidate authority before any economic work rather than defaulting to 0. */
    v_source_change_seq := COALESCE(v_current_source_change_seq, 0);
  END IF;

  IF COALESCE(v_first_source_page, true) IS NOT TRUE THEN
    /*
     * The first page establishes and persists the complete candidate-wide
     * pre-draft reconciliation attestation. A continuation is bound to the
     * same session version, snapshot, source sequence and source-build run, so
     * repeating the full entitlement/reservation/settlement scan on every page
     * adds no authority and can exceed the Worker runtime budget.
     *
     * Never accept a bare historic completion marker. Reuse is permitted only
     * when every immutable run/economic boundary below matches exactly. A
     * missing or stale marker fails closed to the continuation and restarts
     * the same bounded run at its first page; it never silently skips
     * reconciliation.
     */
    IF COALESCE(v_old_sync_marker, '{}'::jsonb) = '{}'::jsonb
       OR LOWER(BTRIM(COALESCE(v_old_sync_marker->>'completed', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
       OR LOWER(BTRIM(COALESCE(v_old_sync_marker->>'attested', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
       OR LOWER(BTRIM(COALESCE(v_old_sync_marker->>'ok', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
       OR NULLIF(BTRIM(COALESCE(v_old_sync_marker->>'session_id', '')), '') IS DISTINCT FROM p_session_id::text
       OR NULLIF(BTRIM(COALESCE(v_old_sync_marker->>'candidate_id', '')), '') IS DISTINCT FROM p_candidate_id::text
       OR NULLIF(BTRIM(COALESCE(v_old_sync_marker->>'session_version', '')), '') IS DISTINCT FROM v_session_version::text
       OR NULLIF(BTRIM(COALESCE(v_old_sync_marker->>'source_change_seq', '')), '') IS DISTINCT FROM v_source_change_seq::text
       OR NULLIF(BTRIM(COALESCE(v_old_sync_marker->>'source_build_run_id', '')), '') IS DISTINCT FROM v_source_build_run_id::text
       OR NULLIF(BTRIM(COALESCE(v_old_sync_marker->>'source_snapshot_run_id', '')), '')
            IS DISTINCT FROM (CASE
              WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL::text
              ELSE v_session_row.source_snapshot_run_id::text
            END)
       OR NULLIF(BTRIM(COALESCE(v_old_sync_marker->>'session_signature', '')), '')
            IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_session_row.session_signature, '')), '')
       OR UPPER(BTRIM(COALESCE(v_old_sync_marker->>'pay_channel_scope', ''))) IS DISTINCT FROM v_candidate_pay_channel_scope
       OR UPPER(BTRIM(COALESCE(v_old_sync_marker->>'refresh_scope_kind', ''))) IS DISTINCT FROM v_requested_refresh_scope_kind
       OR UPPER(BTRIM(COALESCE(v_old_sync_marker->>'policy_x_authority_scope', ''))) <> 'PRE_DRAFT_LIVE_TRUTH'
       OR jsonb_typeof(v_old_sync_marker->'scope_timesheet_ids') IS DISTINCT FROM 'array' THEN
      /*
       * The marker can be absent when the first page completed its economic
       * work while the optional NOWAIT session-progress write was contended.
       * Re-enter with an empty cursor so this same stable run re-attests from
       * live pre-draft truth. The first-page persistence fence below will roll
       * the transaction back for the normal durable retry if contention
       * remains.
       */
      RETURN public.pay_workbench_candidate_source_build_chunk(
        p_session_id,
        p_candidate_id,
        '{}'::jsonb,
        v_payload_json
          || jsonb_build_object(
            'continuation_attestation_restart', true,
            'continuation_attestation_restart_at_utc',
              clock_timestamp()::text
          ),
        v_limit
      );
    END IF;

    SELECT COALESCE(
             ARRAY_AGG(scope_member.value::uuid ORDER BY scope_member.value::uuid),
             ARRAY[]::uuid[]
           )
    INTO v_sync_scope_timesheet_ids
    FROM jsonb_array_elements_text(v_old_sync_marker->'scope_timesheet_ids') AS scope_member(value)
    WHERE scope_member.value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

    IF COALESCE(array_length(v_sync_scope_timesheet_ids, 1), 0)
         IS DISTINCT FROM COALESCE(
           CASE
             WHEN BTRIM(COALESCE(v_old_sync_marker->>'scope_timesheet_count', '')) ~ '^[0-9]{1,9}$'
               THEN (v_old_sync_marker->>'scope_timesheet_count')::integer
             ELSE NULL::integer
           END,
           0
         ) THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_CONTINUATION_ATTESTATION_SCOPE_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_CONTINUATION_ATTESTATION_SCOPE_INVALID',
                'session_id', p_session_id::text,
                'candidate_id', p_candidate_id::text,
                'source_build_run_id', v_source_build_run_id::text
              )::text;
    END IF;

    v_sync_scope_timesheet_ids_json := COALESCE(v_old_sync_marker->'scope_timesheet_ids', '[]'::jsonb);
    v_post_sync_scope_timesheet_ids := COALESCE(v_sync_scope_timesheet_ids, ARRAY[]::uuid[]);
    v_post_sync_scope_timesheet_ids_json := v_sync_scope_timesheet_ids_json;
    v_sync_scope_digest := NULLIF(BTRIM(COALESCE(v_old_sync_marker->>'scope_digest', '')), '');
    v_post_sync_scope_digest := v_sync_scope_digest;
    v_sync_negative_digest := NULLIF(BTRIM(COALESCE(v_old_sync_marker->>'negative_component_digest', '')), '');
    v_post_sync_negative_digest := v_sync_negative_digest;
    v_sync_baseline_digest := NULLIF(BTRIM(COALESCE(v_old_sync_marker->>'settled_baseline_digest', '')), '');
    v_post_sync_baseline_digest := v_sync_baseline_digest;
    v_post_sync_candidate_pay_channel_scope := v_candidate_pay_channel_scope;
    v_post_sync_source_change_seq := v_source_change_seq;
    v_current_source_change_seq := v_source_change_seq;

    v_sync_negative_component_count := CASE
      WHEN BTRIM(COALESCE(v_old_sync_marker->>'negative_component_count', '')) ~ '^[0-9]{1,9}$'
        THEN (v_old_sync_marker->>'negative_component_count')::integer
      ELSE 0
    END;
    v_post_sync_negative_component_count := v_sync_negative_component_count;
    v_sync_durable_component_count := CASE
      WHEN BTRIM(COALESCE(v_old_sync_marker->>'durable_component_count', '')) ~ '^[0-9]{1,9}$'
        THEN (v_old_sync_marker->>'durable_component_count')::integer
      ELSE 0
    END;
    v_sync_protected_component_count := CASE
      WHEN BTRIM(COALESCE(v_old_sync_marker->>'protected_component_count', '')) ~ '^[0-9]{1,9}$'
        THEN (v_old_sync_marker->>'protected_component_count')::integer
      ELSE 0
    END;
    v_sync_resolution_pending_component_count := CASE
      WHEN BTRIM(COALESCE(v_old_sync_marker->>'resolution_pending_component_count', '')) ~ '^[0-9]{1,9}$'
        THEN (v_old_sync_marker->>'resolution_pending_component_count')::integer
      ELSE 0
    END;
    v_sync_uncovered_component_count := CASE
      WHEN BTRIM(COALESCE(v_old_sync_marker->>'uncovered_component_count', '')) ~ '^[0-9]{1,9}$'
        THEN (v_old_sync_marker->>'uncovered_component_count')::integer
      ELSE 0
    END;
    v_sync_result_code := COALESCE(NULLIF(BTRIM(v_old_sync_marker->>'result_code'), ''), 'REUSED_DURABLE_ATTESTATION');
    v_sync_candidate_covered := COALESCE(v_sync_uncovered_component_count, 0) = 0;
    v_sync_invoked := false;
    v_sync_marker_reused := true;
    v_sync_result := jsonb_build_object(
      'ok', true,
      'invoked', false,
      'reason', 'SOURCE_BUILD_CONTINUATION_DURABLE_ATTESTATION_REUSED',
      'pay_channel_scope', v_candidate_pay_channel_scope,
      'authoritative_timesheet_scope', true,
      'scope_timesheet_ids', v_sync_scope_timesheet_ids_json,
      'preview_candidate_coverage_complete', true
    );
    v_sync_attestation := v_old_sync_marker
      || jsonb_build_object(
        'sync_invoked', false,
        'sync_marker_reused', true,
        'old_marker_present', true,
        'old_marker_accepted_as_authority', true,
        'reused_at_utc', clock_timestamp()
      );
    v_sync_completed := true;
    v_sync_attested := true;
  ELSE
  WITH seed_timesheet_ids AS (
    SELECT targeted_id AS timesheet_id
    FROM unnest(COALESCE(v_targeted_timesheet_ids, ARRAY[]::uuid[])) AS targeted_values(targeted_id)
    WHERE v_requested_refresh_scope_kind = 'TARGETED_TIMESHEETS'

    UNION

    SELECT linked_id AS timesheet_id
    FROM unnest(COALESCE(v_linked_timesheet_ids, ARRAY[]::uuid[])) AS linked_values(linked_id)
    WHERE v_requested_refresh_scope_kind = 'TARGETED_TIMESHEETS'

    UNION

    SELECT force_id AS timesheet_id
    FROM unnest(COALESCE(v_force_include_timesheet_ids, ARRAY[]::uuid[])) AS force_values(force_id)

    UNION

    SELECT current_tsfin.timesheet_id
    FROM public.timesheets_financials AS current_tsfin
    JOIN public.timesheets AS current_timesheet
      ON current_timesheet.timesheet_id = current_tsfin.timesheet_id
     AND current_timesheet.is_current = true
     AND current_timesheet.archived_at_utc IS NULL
    WHERE v_requested_refresh_scope_kind = 'CANDIDATE_FULL_LIVE'
      AND current_tsfin.candidate_id = p_candidate_id
      AND current_tsfin.is_current = true

    UNION

    SELECT finance_case.linked_timesheet_id
    FROM public.pay_advances AS finance_case
    WHERE v_requested_refresh_scope_kind = 'CANDIDATE_FULL_LIVE'
      AND finance_case.candidate_id = p_candidate_id
      AND finance_case.linked_timesheet_id IS NOT NULL

    UNION

    SELECT finance_component.linked_timesheet_id
    FROM public.pay_finance_case_components AS finance_component
    WHERE v_requested_refresh_scope_kind = 'CANDIDATE_FULL_LIVE'
      AND finance_component.candidate_id = p_candidate_id
      AND finance_component.linked_timesheet_id IS NOT NULL

    UNION

    SELECT payment_override.timesheet_id
    FROM public.timesheet_payment_overrides AS payment_override
    WHERE v_requested_refresh_scope_kind = 'CANDIDATE_FULL_LIVE'
      AND payment_override.candidate_id = p_candidate_id
      AND payment_override.consumed_at_utc IS NULL
      AND payment_override.cleared_at_utc IS NULL

    UNION

    SELECT unpaid_adjustment.timesheet_id
    FROM public.ts_pay_adjustments AS unpaid_adjustment
    WHERE v_requested_refresh_scope_kind = 'CANDIDATE_FULL_LIVE'
      AND unpaid_adjustment.candidate_id = p_candidate_id
      AND unpaid_adjustment.paid_at_utc IS NULL

    UNION

    SELECT active_snooze.timesheet_id
    FROM public.pay_item_snoozes AS active_snooze
    WHERE v_requested_refresh_scope_kind = 'CANDIDATE_FULL_LIVE'
      AND active_snooze.candidate_id = p_candidate_id
      AND active_snooze.timesheet_id IS NOT NULL
      AND active_snooze.cleared_at_utc IS NULL
      AND active_snooze.cancelled_at_utc IS NULL

    UNION

    SELECT retained_batch_item.timesheet_id
    FROM public.pay_batch_candidates AS retained_batch_candidate
    JOIN public.pay_batch_items AS retained_batch_item
      ON retained_batch_item.pay_batch_candidate_id = retained_batch_candidate.id
    WHERE v_requested_refresh_scope_kind = 'CANDIDATE_FULL_LIVE'
      AND retained_batch_candidate.candidate_id = p_candidate_id
      AND retained_batch_item.timesheet_id IS NOT NULL
      AND COALESCE(retained_batch_item.is_voided, false) IS NOT TRUE

    UNION

    SELECT retained_correction.timesheet_id
    FROM public.pay_payment_correction_items AS retained_correction
    WHERE v_requested_refresh_scope_kind = 'CANDIDATE_FULL_LIVE'
      AND retained_correction.candidate_id = p_candidate_id
      AND retained_correction.timesheet_id IS NOT NULL
      AND UPPER(BTRIM(COALESCE(retained_correction.status, ''))) = 'APPLIED'
  ), seed_array AS (
    SELECT COALESCE(ARRAY_AGG(DISTINCT seed_timesheet_ids.timesheet_id ORDER BY seed_timesheet_ids.timesheet_id), ARRAY[]::uuid[]) AS timesheet_ids
    FROM seed_timesheet_ids
    WHERE seed_timesheet_ids.timesheet_id IS NOT NULL
  ), expanded_timesheet_ids AS (
    SELECT seed_timesheet_ids.timesheet_id
    FROM seed_timesheet_ids
    WHERE seed_timesheet_ids.timesheet_id IS NOT NULL

    UNION

    /* Full-live seeds normally contain only current/frozen carriers.  Import-
       authoritative correction residuals, however, are chain economic truth:
       an archived reversal or replacement member can still carry the positive
       side required to net a current negative recovery.  Promote every valid
       chain member before source collection so full-live and targeted refreshes
       materialise the same complete component family. */
    SELECT correction_member.value::uuid
    FROM seed_timesheet_ids AS correction_seed
    JOIN public.timesheets AS correction_seed_timesheet
      ON correction_seed_timesheet.timesheet_id = correction_seed.timesheet_id
    CROSS JOIN LATERAL (
      SELECT public.timesheet_correction_chain_scope_v1(
        correction_seed.timesheet_id, false, 32, 100
      ) AS chain_json
    ) AS correction_chain
    CROSS JOIN LATERAL jsonb_array_elements_text(
      COALESCE(correction_chain.chain_json->'member_timesheet_ids', '[]'::jsonb)
    ) AS correction_member(value)
    WHERE correction_seed.timesheet_id IS NOT NULL
      AND EXISTS (
        SELECT 1
        FROM public.timesheets_financials AS correction_seed_financials
        WHERE correction_seed_financials.timesheet_id = correction_seed.timesheet_id
          AND correction_seed_financials.candidate_id = p_candidate_id
      )
      AND COALESCE((correction_chain.chain_json->>'valid')::boolean, false)
      AND EXISTS (
        SELECT 1
        FROM jsonb_array_elements_text(
          COALESCE(correction_chain.chain_json->'member_timesheet_ids', '[]'::jsonb)
        ) AS classified_member(value)
        WHERE classified_member.value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          AND COALESCE((public._ctms_import_correction_classify_v1(classified_member.value::uuid)
            ->>'is_import_authoritative_correction')::boolean, false)
      )
      AND correction_member.value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'

    UNION

    SELECT rotation_scope.canonical_timesheet_id
    FROM seed_array
    JOIN public._pay_timesheet_rotation_scope(seed_array.timesheet_ids) AS rotation_scope ON true
    WHERE rotation_scope.canonical_timesheet_id IS NOT NULL

    UNION

    SELECT rotation_scope.family_timesheet_id
    FROM seed_array
    JOIN public._pay_timesheet_rotation_scope(seed_array.timesheet_ids) AS rotation_scope ON true
    WHERE rotation_scope.family_timesheet_id IS NOT NULL
  )
  SELECT COALESCE(ARRAY_AGG(DISTINCT expanded_timesheet_ids.timesheet_id ORDER BY expanded_timesheet_ids.timesheet_id), ARRAY[]::uuid[])
  INTO v_sync_scope_timesheet_ids
  FROM expanded_timesheet_ids
  WHERE expanded_timesheet_ids.timesheet_id IS NOT NULL
    AND NOT (expanded_timesheet_ids.timesheet_id = ANY(COALESCE(v_exclude_timesheet_ids, ARRAY[]::uuid[])))
    AND (
      v_client_filter_single IS NULL
      OR EXISTS (
        SELECT 1
        FROM public.timesheets_financials AS scoped_tsfin
        WHERE scoped_tsfin.timesheet_id = expanded_timesheet_ids.timesheet_id
          AND scoped_tsfin.candidate_id = p_candidate_id
          AND scoped_tsfin.client_id = v_client_filter_single
      )
      OR EXISTS (
        SELECT 1
        FROM public.pay_advances AS scoped_finance_case
        WHERE scoped_finance_case.linked_timesheet_id = expanded_timesheet_ids.timesheet_id
          AND scoped_finance_case.candidate_id = p_candidate_id
          AND scoped_finance_case.client_id = v_client_filter_single
      )
      OR EXISTS (
        SELECT 1
        FROM public.pay_finance_case_components AS scoped_finance_component
        WHERE scoped_finance_component.linked_timesheet_id = expanded_timesheet_ids.timesheet_id
          AND scoped_finance_component.candidate_id = p_candidate_id
          AND scoped_finance_component.client_id = v_client_filter_single
      )
    );

  SELECT COALESCE(jsonb_agg(scope_id::text ORDER BY scope_id), '[]'::jsonb)
  INTO v_sync_scope_timesheet_ids_json
  FROM unnest(COALESCE(v_sync_scope_timesheet_ids, ARRAY[]::uuid[])) AS sync_scope(scope_id);

  v_sync_scope_digest := md5(
    COALESCE(v_sync_scope_timesheet_ids_json::text, '[]') || '|' ||
    COALESCE(v_requested_refresh_scope_kind, 'CANDIDATE_FULL_LIVE') || '|' ||
    COALESCE(v_candidate_pay_channel_scope, '') || '|' ||
    COALESCE(v_client_filter_single::text, '')
  );

  DROP TABLE IF EXISTS pg_temp._tmp_pay_wb_sync_rotation_scope;
  CREATE TEMPORARY TABLE pg_temp._tmp_pay_wb_sync_rotation_scope ON COMMIT DROP AS
  SELECT DISTINCT
    rotation_scope.requested_timesheet_id,
    rotation_scope.canonical_timesheet_id,
    rotation_scope.family_timesheet_id
  FROM public._pay_timesheet_rotation_scope(COALESCE(v_sync_scope_timesheet_ids, ARRAY[]::uuid[])) AS rotation_scope;

  DROP TABLE IF EXISTS pg_temp._tmp_pay_wb_sync_negative_components;
  CREATE TEMPORARY TABLE pg_temp._tmp_pay_wb_sync_negative_components ON COMMIT DROP AS
  WITH live_entitlement_components AS (
    SELECT
      entitlement_component.timesheet_id,
      UPPER(BTRIM(entitlement_component.key_type)) AS key_type,
      BTRIM(entitlement_component.key_value) AS key_value,
      ROUND(COALESCE(entitlement_component.truth_ex_vat, 0), 2) AS truth_ex_vat,
      ROUND(COALESCE(entitlement_component.baseline_ex_vat, 0), 2) AS baseline_ex_vat
    FROM public._pay_current_timesheet_entitlement_components(COALESCE(v_sync_scope_timesheet_ids, ARRAY[]::uuid[])) AS entitlement_component
    WHERE NULLIF(BTRIM(COALESCE(entitlement_component.key_type, '')), '') IS NOT NULL
      AND NULLIF(BTRIM(COALESCE(entitlement_component.key_value, '')), '') IS NOT NULL
  ), active_entitlement_reservations AS (
    SELECT
      reserved_component.timesheet_id,
      UPPER(BTRIM(reserved_component.key_type)) AS key_type,
      BTRIM(reserved_component.key_value) AS key_value,
      ROUND(COALESCE(reserved_component.amount_ex_vat, 0), 2) AS reserved_ex_vat
    FROM public._pay_reserved_components(COALESCE(v_sync_scope_timesheet_ids, ARRAY[]::uuid[]), NULL::uuid) AS reserved_component
    WHERE NULLIF(BTRIM(COALESCE(reserved_component.key_type, '')), '') IS NOT NULL
      AND NULLIF(BTRIM(COALESCE(reserved_component.key_value, '')), '') IS NOT NULL
  ), live_economic_keys AS (
    SELECT
      live_component.timesheet_id,
      live_component.key_type,
      live_component.key_value
    FROM live_entitlement_components AS live_component

    UNION

    SELECT
      reserved_component.timesheet_id,
      reserved_component.key_type,
      reserved_component.key_value
    FROM active_entitlement_reservations AS reserved_component
  ), raw_outstanding_components AS (
    SELECT
      live_key.timesheet_id,
      live_key.key_type,
      live_key.key_value,
      ROUND(COALESCE(live_component.truth_ex_vat, 0), 2) AS truth_ex_vat,
      ROUND(COALESCE(live_component.baseline_ex_vat, 0), 2) AS baseline_ex_vat,
      ROUND(COALESCE(reserved_component.reserved_ex_vat, 0), 2) AS reserved_ex_vat,
      ROUND(
        COALESCE(live_component.truth_ex_vat, 0)
        - COALESCE(live_component.baseline_ex_vat, 0)
        - COALESCE(reserved_component.reserved_ex_vat, 0),
        2
      ) AS outstanding_ex_vat
    FROM live_economic_keys AS live_key
    LEFT JOIN live_entitlement_components AS live_component
      ON live_component.timesheet_id = live_key.timesheet_id
     AND live_component.key_type = live_key.key_type
     AND live_component.key_value = live_key.key_value
    LEFT JOIN active_entitlement_reservations AS reserved_component
      ON reserved_component.timesheet_id = live_key.timesheet_id
     AND reserved_component.key_type = live_key.key_type
     AND reserved_component.key_value = live_key.key_value
  ), active_settled_component_basis AS (
    SELECT
      active_settled_component.timesheet_id,
      COUNT(*)::integer AS active_settled_component_count,
      md5(COALESCE(jsonb_agg(
        jsonb_build_object(
          'key_type', active_settled_component.key_type,
          'key_value', active_settled_component.key_value,
          'amount_ex_vat', ROUND(COALESCE(active_settled_component.amount_ex_vat, 0), 2),
          'amount_inc_vat', ROUND(COALESCE(active_settled_component.amount_inc_vat, 0), 2)
        ) ORDER BY active_settled_component.key_type, active_settled_component.key_value
      )::text, '[]')) AS active_settled_signature
    FROM public._pay_active_settled_components(
      COALESCE(v_sync_scope_timesheet_ids, ARRAY[]::uuid[])
    ) AS active_settled_component
    GROUP BY active_settled_component.timesheet_id
  )
  SELECT
    raw_outstanding_component.timesheet_id,
    raw_outstanding_component.key_type,
    raw_outstanding_component.key_value,
    raw_outstanding_component.truth_ex_vat,
    raw_outstanding_component.baseline_ex_vat,
    raw_outstanding_component.reserved_ex_vat,
    raw_outstanding_component.outstanding_ex_vat,
    CASE
      WHEN COALESCE(active_settled_basis.active_settled_component_count, 0) > 0
        THEN active_settled_basis.active_settled_signature
      ELSE COALESCE(
        timesheet_pay_state.last_settled_signature,
        md5(COALESCE(timesheet_pay_state.last_settled_snapshot_json::text, '{}'))
      )
    END AS baseline_signature
  FROM raw_outstanding_components AS raw_outstanding_component
  LEFT JOIN public.timesheet_pay_state AS timesheet_pay_state
    ON timesheet_pay_state.timesheet_id = raw_outstanding_component.timesheet_id
  LEFT JOIN active_settled_component_basis AS active_settled_basis
    ON active_settled_basis.timesheet_id = raw_outstanding_component.timesheet_id
  WHERE raw_outstanding_component.outstanding_ex_vat < 0;

  /*
   * Capture durable correction-resolution membership before the source-row
   * rewrite below. The rewrite intentionally replaces the candidate's
   * correction source rows; asking the residual helper afterwards creates a
   * short-lived blind spot on continuation pages and can misclassify an
   * already-pending coupled component as unattested.
   */
  SELECT COALESCE(
    ARRAY_AGG(DISTINCT pending_member.value::uuid ORDER BY pending_member.value::uuid),
    ARRAY[]::uuid[]
  )
  INTO v_current_resolution_pending_member_ids
  FROM jsonb_array_elements(
    public._ctms_candidate_correction_residuals_v1(
      p_session_id,
      p_candidate_id,
      NULL::uuid,
      'PAY_WORKBENCH_SOURCE_BUILD_ATTESTATION'
    )
  ) AS pending_residual(value)
  CROSS JOIN LATERAL jsonb_array_elements_text(
    COALESCE(pending_residual.value->'member_timesheet_ids', '[]'::jsonb)
  ) AS pending_member(value)
  WHERE COALESCE((pending_residual.value->>'draftable')::boolean, false) IS NOT TRUE
    AND COALESCE(pending_residual.value->>'block_code', '')
          = 'CORRECTION_CHAIN_PAY_METHOD_RESOLUTION_REQUIRED'
    AND COALESCE((pending_residual.value->>'unresolved_count')::integer, 0) > 0
    AND COALESCE((pending_residual.value->>'reservation_overrun_count')::integer, 0) = 0
    AND COALESCE((pending_residual.value->>'component_count')::integer, 0) > 0
    AND pending_member.value
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

  PERFORM public._ctms_rewrite_source_build_correction_negative_components_v1(
    p_session_id,
    p_candidate_id,
    COALESCE(v_sync_scope_timesheet_ids, ARRAY[]::uuid[])
  );

  SELECT COUNT(*)::integer,
         md5(COALESCE(jsonb_agg(
           jsonb_build_object(
             'timesheet_id', negative_component.timesheet_id::text,
             'key_type', negative_component.key_type,
             'key_value', negative_component.key_value,
             'truth_ex_vat', ROUND(negative_component.truth_ex_vat, 2)::numeric(12,2),
             'baseline_ex_vat', ROUND(negative_component.baseline_ex_vat, 2)::numeric(12,2),
             'reserved_ex_vat', ROUND(negative_component.reserved_ex_vat, 2)::numeric(12,2),
             'outstanding_ex_vat', ROUND(negative_component.outstanding_ex_vat, 2)::numeric(12,2)
           ) ORDER BY negative_component.timesheet_id, negative_component.key_type, negative_component.key_value
         )::text, '[]'))
  INTO v_sync_negative_component_count,
       v_sync_negative_digest
  FROM pg_temp._tmp_pay_wb_sync_negative_components AS negative_component;

  SELECT md5(COALESCE(jsonb_agg(
           jsonb_build_object(
             'timesheet_id', settled_component.timesheet_id::text,
             'key_type', settled_component.key_type,
             'key_value', settled_component.key_value,
             'amount_ex_vat', ROUND(COALESCE(settled_component.amount_ex_vat, 0), 2),
             'amount_inc_vat', ROUND(COALESCE(settled_component.amount_inc_vat, 0), 2)
           ) ORDER BY settled_component.timesheet_id, settled_component.key_type, settled_component.key_value
         )::text, '[]'))
  INTO v_sync_baseline_digest
  FROM public._pay_active_settled_components(COALESCE(v_sync_scope_timesheet_ids, ARRAY[]::uuid[])) AS settled_component;

  v_initial_validation_elapsed_ms := round((extract(epoch from (clock_timestamp() - v_diag_phase_started_at)) * 1000.0)::numeric, 3);
  v_diag_phase_started_at := clock_timestamp();

  IF v_candidate_pay_channel_scope IN ('PAYE', 'UMBRELLA')
     AND COALESCE(v_first_source_page, true)
     AND COALESCE(array_length(v_sync_scope_timesheet_ids, 1), 0) > 0 THEN
    v_sync_started_at_utc := clock_timestamp();
    v_sync_invoked := true;
    v_sync_authority_token := md5(
      txid_current()::text || '|' ||
      p_session_id::text || '|' ||
      p_candidate_id::text || '|' ||
      v_source_build_run_id::text || '|' ||
      clock_timestamp()::text || '|' ||
      random()::text
    );
    PERFORM set_config(
      'cloudtms.pay_workbench_overpayment_sync_token',
      v_sync_authority_token,
      true
    );

    v_sync_result := public.pay_sync_overpayments_from_preview(
      p_pay_date => v_session_row.pay_date,
      p_week_ending_cutoff => v_session_row.week_ending_cutoff,
      p_actor_user_id => v_session_row.actor_user_id,
      p_pay_channel_scope => v_candidate_pay_channel_scope,
      p_candidate_ids => ARRAY[p_candidate_id]::uuid[],
      p_mismatch_choices => COALESCE(v_mismatch_choices_json, '{}'::jsonb)
        || jsonb_build_object(
          'overpayment_sync_authoritative_timesheet_scope', true,
          'authoritative_timesheet_scope', true,
          'overpayment_sync_authority_token', v_sync_authority_token,
          'refresh_scope_kind', 'TARGETED_TIMESHEETS',
          'targeted_timesheet_ids', COALESCE(v_sync_scope_timesheet_ids_json, '[]'::jsonb),
          'targeted_timesheet_ids_requested', COALESCE(v_sync_scope_timesheet_ids_json, '[]'::jsonb),
          'linked_timesheet_ids', '[]'::jsonb,
          'linked_timesheet_ids_requested', '[]'::jsonb,
          'source_build_allow_full_fallback', false
        )
        || jsonb_build_object(
          'source_build_run_id', v_source_build_run_id::text,
          'source_change_seq', v_source_change_seq,
          'workbench_session_id', p_session_id::text,
          'session_version', v_session_version,
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
        )
        || jsonb_build_object(
          'overpayment_sync_scope_digest', v_sync_scope_digest,
          'overpayment_sync_negative_component_digest', v_sync_negative_digest,
          'overpayment_sync_settled_baseline_digest', v_sync_baseline_digest
        ),
      p_client_filter_single => v_client_filter_single,
      p_force_include_timesheet_ids => COALESCE(v_sync_scope_timesheet_ids, ARRAY[]::uuid[]),
      p_exclude_timesheet_ids => COALESCE(v_exclude_timesheet_ids, ARRAY[]::uuid[])
    );

    PERFORM set_config(
      'cloudtms.pay_workbench_overpayment_sync_token',
      '',
      true
    );

    IF jsonb_typeof(COALESCE(v_sync_result, '{}'::jsonb)) <> 'object'
       OR LOWER(BTRIM(COALESCE(v_sync_result->>'ok', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
       OR LOWER(BTRIM(COALESCE(v_sync_result->>'preview_candidate_coverage_complete', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
       OR LOWER(BTRIM(COALESCE(v_sync_result->>'authoritative_timesheet_scope', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
       OR (
            CASE
              WHEN jsonb_typeof(v_sync_result->'scope_timesheet_ids') = 'array'
                THEN COALESCE(v_sync_result->'scope_timesheet_ids', '[]'::jsonb)
              ELSE '[]'::jsonb
            END
          ) IS DISTINCT FROM COALESCE(v_sync_scope_timesheet_ids_json, '[]'::jsonb) THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_OVERPAYMENT_SYNC_FAILED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_OVERPAYMENT_SYNC_FAILED',
                'session_id', p_session_id::text,
                'candidate_id', p_candidate_id::text,
                'source_build_run_id', v_source_build_run_id::text,
                'sync_result', COALESCE(v_sync_result, '{}'::jsonb)
              )::text;
    END IF;
  ELSIF v_candidate_pay_channel_scope IN ('PAYE', 'UMBRELLA')
        AND COALESCE(v_first_source_page, true) THEN
    v_sync_result := jsonb_build_object(
      'ok', true,
      'invoked', false,
      'reason', 'AUTHORITATIVE_EMPTY_TIMESHEET_SCOPE',
      'pay_channel_scope', v_candidate_pay_channel_scope,
      'authoritative_timesheet_scope', true,
      'explicit_empty_timesheet_scope', true,
      'scope_timesheet_ids', '[]'::jsonb,
      'preview_candidate_coverage_complete', true
    );
  ELSIF v_candidate_pay_channel_scope IN ('PAYE', 'UMBRELLA') THEN
    v_sync_result := jsonb_build_object(
      'ok', true,
      'invoked', false,
      'reason', 'SOURCE_BUILD_CONTINUATION_DURABLE_REVALIDATION',
      'pay_channel_scope', v_candidate_pay_channel_scope,
      'authoritative_timesheet_scope', true,
      'scope_timesheet_ids', COALESCE(v_sync_scope_timesheet_ids_json, '[]'::jsonb),
      'preview_candidate_coverage_complete', true
    );
  ELSE
    v_sync_result := jsonb_build_object(
      'ok', true,
      'invoked', false,
      'reason', 'PAY_CHANNEL_NOT_RECONCILABLE',
      'pay_channel_scope', v_candidate_pay_channel_scope
    );
  END IF;

  /* Reconciliation writes finance authority and its existing dirty triggers may
     legitimately advance the candidate sequence in this same transaction.  Rebuild
     the current scope/economic fingerprint after sync.  Adopt the new sequence only
     when route, scope, negative economics and settled baseline are unchanged. */
  SELECT CASE
           WHEN UPPER(BTRIM(COALESCE(candidate_row.pay_method, ''))) IN ('PAYE', 'UMBRELLA')
             THEN UPPER(BTRIM(candidate_row.pay_method))
           ELSE 'ALL'
         END
  INTO v_post_sync_candidate_pay_channel_scope
  FROM public.candidates AS candidate_row
  WHERE candidate_row.id = p_candidate_id
  LIMIT 1;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_CANDIDATE_NOT_FOUND_POST_SYNC'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_CANDIDATE_NOT_FOUND_POST_SYNC',
              'session_id', p_session_id::text,
              'candidate_id', p_candidate_id::text
            )::text;
  END IF;

  WITH post_seed_timesheet_ids AS (
    SELECT targeted_id AS timesheet_id
    FROM unnest(COALESCE(v_targeted_timesheet_ids, ARRAY[]::uuid[])) AS targeted_values(targeted_id)
    WHERE v_requested_refresh_scope_kind = 'TARGETED_TIMESHEETS'

    UNION

    SELECT linked_id AS timesheet_id
    FROM unnest(COALESCE(v_linked_timesheet_ids, ARRAY[]::uuid[])) AS linked_values(linked_id)
    WHERE v_requested_refresh_scope_kind = 'TARGETED_TIMESHEETS'

    UNION

    SELECT force_id AS timesheet_id
    FROM unnest(COALESCE(v_force_include_timesheet_ids, ARRAY[]::uuid[])) AS force_values(force_id)

    UNION

    SELECT current_tsfin.timesheet_id
    FROM public.timesheets_financials AS current_tsfin
    JOIN public.timesheets AS current_timesheet
      ON current_timesheet.timesheet_id = current_tsfin.timesheet_id
     AND current_timesheet.is_current = true
     AND current_timesheet.archived_at_utc IS NULL
    WHERE v_requested_refresh_scope_kind = 'CANDIDATE_FULL_LIVE'
      AND current_tsfin.candidate_id = p_candidate_id
      AND current_tsfin.is_current = true

    UNION

    SELECT finance_case.linked_timesheet_id
    FROM public.pay_advances AS finance_case
    WHERE v_requested_refresh_scope_kind = 'CANDIDATE_FULL_LIVE'
      AND finance_case.candidate_id = p_candidate_id
      AND finance_case.linked_timesheet_id IS NOT NULL

    UNION

    SELECT finance_component.linked_timesheet_id
    FROM public.pay_finance_case_components AS finance_component
    WHERE v_requested_refresh_scope_kind = 'CANDIDATE_FULL_LIVE'
      AND finance_component.candidate_id = p_candidate_id
      AND finance_component.linked_timesheet_id IS NOT NULL

    UNION

    SELECT payment_override.timesheet_id
    FROM public.timesheet_payment_overrides AS payment_override
    WHERE v_requested_refresh_scope_kind = 'CANDIDATE_FULL_LIVE'
      AND payment_override.candidate_id = p_candidate_id
      AND payment_override.consumed_at_utc IS NULL
      AND payment_override.cleared_at_utc IS NULL

    UNION

    SELECT unpaid_adjustment.timesheet_id
    FROM public.ts_pay_adjustments AS unpaid_adjustment
    WHERE v_requested_refresh_scope_kind = 'CANDIDATE_FULL_LIVE'
      AND unpaid_adjustment.candidate_id = p_candidate_id
      AND unpaid_adjustment.paid_at_utc IS NULL

    UNION

    SELECT active_snooze.timesheet_id
    FROM public.pay_item_snoozes AS active_snooze
    WHERE v_requested_refresh_scope_kind = 'CANDIDATE_FULL_LIVE'
      AND active_snooze.candidate_id = p_candidate_id
      AND active_snooze.timesheet_id IS NOT NULL
      AND active_snooze.cleared_at_utc IS NULL
      AND active_snooze.cancelled_at_utc IS NULL

    UNION

    SELECT retained_batch_item.timesheet_id
    FROM public.pay_batch_candidates AS retained_batch_candidate
    JOIN public.pay_batch_items AS retained_batch_item
      ON retained_batch_item.pay_batch_candidate_id = retained_batch_candidate.id
    WHERE v_requested_refresh_scope_kind = 'CANDIDATE_FULL_LIVE'
      AND retained_batch_candidate.candidate_id = p_candidate_id
      AND retained_batch_item.timesheet_id IS NOT NULL
      AND COALESCE(retained_batch_item.is_voided, false) IS NOT TRUE

    UNION

    SELECT retained_correction.timesheet_id
    FROM public.pay_payment_correction_items AS retained_correction
    WHERE v_requested_refresh_scope_kind = 'CANDIDATE_FULL_LIVE'
      AND retained_correction.candidate_id = p_candidate_id
      AND retained_correction.timesheet_id IS NOT NULL
      AND UPPER(BTRIM(COALESCE(retained_correction.status, ''))) = 'APPLIED'
  ), post_seed_array AS (
    SELECT COALESCE(ARRAY_AGG(DISTINCT post_seed_timesheet_ids.timesheet_id ORDER BY post_seed_timesheet_ids.timesheet_id), ARRAY[]::uuid[]) AS timesheet_ids
    FROM post_seed_timesheet_ids
    WHERE post_seed_timesheet_ids.timesheet_id IS NOT NULL
  ), post_expanded_timesheet_ids AS (
    SELECT post_seed_timesheet_ids.timesheet_id
    FROM post_seed_timesheet_ids
    WHERE post_seed_timesheet_ids.timesheet_id IS NOT NULL

    UNION

    SELECT correction_member.value::uuid
    FROM post_seed_timesheet_ids AS correction_seed
    JOIN public.timesheets AS correction_seed_timesheet
      ON correction_seed_timesheet.timesheet_id = correction_seed.timesheet_id
    CROSS JOIN LATERAL (
      SELECT public.timesheet_correction_chain_scope_v1(
        correction_seed.timesheet_id, false, 32, 100
      ) AS chain_json
    ) AS correction_chain
    CROSS JOIN LATERAL jsonb_array_elements_text(
      COALESCE(correction_chain.chain_json->'member_timesheet_ids', '[]'::jsonb)
    ) AS correction_member(value)
    WHERE correction_seed.timesheet_id IS NOT NULL
      AND EXISTS (
        SELECT 1
        FROM public.timesheets_financials AS correction_seed_financials
        WHERE correction_seed_financials.timesheet_id = correction_seed.timesheet_id
          AND correction_seed_financials.candidate_id = p_candidate_id
      )
      AND COALESCE((correction_chain.chain_json->>'valid')::boolean, false)
      AND EXISTS (
        SELECT 1
        FROM jsonb_array_elements_text(
          COALESCE(correction_chain.chain_json->'member_timesheet_ids', '[]'::jsonb)
        ) AS classified_member(value)
        WHERE classified_member.value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          AND COALESCE((public._ctms_import_correction_classify_v1(classified_member.value::uuid)
            ->>'is_import_authoritative_correction')::boolean, false)
      )
      AND correction_member.value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'

    UNION

    SELECT rotation_scope.canonical_timesheet_id
    FROM post_seed_array
    JOIN public._pay_timesheet_rotation_scope(post_seed_array.timesheet_ids) AS rotation_scope ON true
    WHERE rotation_scope.canonical_timesheet_id IS NOT NULL

    UNION

    SELECT rotation_scope.family_timesheet_id
    FROM post_seed_array
    JOIN public._pay_timesheet_rotation_scope(post_seed_array.timesheet_ids) AS rotation_scope ON true
    WHERE rotation_scope.family_timesheet_id IS NOT NULL
  )
  SELECT COALESCE(ARRAY_AGG(DISTINCT post_expanded_timesheet_ids.timesheet_id ORDER BY post_expanded_timesheet_ids.timesheet_id), ARRAY[]::uuid[])
  INTO v_post_sync_scope_timesheet_ids
  FROM post_expanded_timesheet_ids
  WHERE post_expanded_timesheet_ids.timesheet_id IS NOT NULL
    AND NOT (post_expanded_timesheet_ids.timesheet_id = ANY(COALESCE(v_exclude_timesheet_ids, ARRAY[]::uuid[])))
    AND (
      v_client_filter_single IS NULL
      OR EXISTS (
        SELECT 1
        FROM public.timesheets_financials AS post_scoped_tsfin
        WHERE post_scoped_tsfin.timesheet_id = post_expanded_timesheet_ids.timesheet_id
          AND post_scoped_tsfin.candidate_id = p_candidate_id
          AND post_scoped_tsfin.client_id = v_client_filter_single
      )
      OR EXISTS (
        SELECT 1
        FROM public.pay_advances AS post_scoped_finance_case
        WHERE post_scoped_finance_case.linked_timesheet_id = post_expanded_timesheet_ids.timesheet_id
          AND post_scoped_finance_case.candidate_id = p_candidate_id
          AND post_scoped_finance_case.client_id = v_client_filter_single
      )
      OR EXISTS (
        SELECT 1
        FROM public.pay_finance_case_components AS post_scoped_finance_component
        WHERE post_scoped_finance_component.linked_timesheet_id = post_expanded_timesheet_ids.timesheet_id
          AND post_scoped_finance_component.candidate_id = p_candidate_id
          AND post_scoped_finance_component.client_id = v_client_filter_single
      )
    );

  SELECT COALESCE(jsonb_agg(scope_id::text ORDER BY scope_id), '[]'::jsonb)
  INTO v_post_sync_scope_timesheet_ids_json
  FROM unnest(COALESCE(v_post_sync_scope_timesheet_ids, ARRAY[]::uuid[])) AS post_sync_scope(scope_id);

  v_post_sync_scope_digest := md5(
    COALESCE(v_post_sync_scope_timesheet_ids_json::text, '[]') || '|' ||
    COALESCE(v_requested_refresh_scope_kind, 'CANDIDATE_FULL_LIVE') || '|' ||
    COALESCE(v_post_sync_candidate_pay_channel_scope, '') || '|' ||
    COALESCE(v_client_filter_single::text, '')
  );

  /* The post-sync scope can legitimately expand when the reconciliation
     creates or rediscovers durable finance-case authority.  Rebuild the
     rotation map from that final scope before attesting the resulting
     components; retaining the pre-sync map makes newly discovered family
     members impossible to attest. */
  TRUNCATE TABLE pg_temp._tmp_pay_wb_sync_rotation_scope;
  INSERT INTO pg_temp._tmp_pay_wb_sync_rotation_scope (
    requested_timesheet_id,
    canonical_timesheet_id,
    family_timesheet_id
  )
  SELECT DISTINCT
    rotation_scope.requested_timesheet_id,
    rotation_scope.canonical_timesheet_id,
    rotation_scope.family_timesheet_id
  FROM public._pay_timesheet_rotation_scope(
    COALESCE(v_post_sync_scope_timesheet_ids, ARRAY[]::uuid[])
  ) AS rotation_scope;

  TRUNCATE TABLE pg_temp._tmp_pay_wb_sync_negative_components;

  WITH post_live_entitlement_components AS (
    SELECT
      entitlement_component.timesheet_id,
      UPPER(BTRIM(entitlement_component.key_type)) AS key_type,
      BTRIM(entitlement_component.key_value) AS key_value,
      ROUND(COALESCE(entitlement_component.truth_ex_vat, 0), 2) AS truth_ex_vat,
      ROUND(COALESCE(entitlement_component.baseline_ex_vat, 0), 2) AS baseline_ex_vat
    FROM public._pay_current_timesheet_entitlement_components(COALESCE(v_post_sync_scope_timesheet_ids, ARRAY[]::uuid[])) AS entitlement_component
    WHERE NULLIF(BTRIM(COALESCE(entitlement_component.key_type, '')), '') IS NOT NULL
      AND NULLIF(BTRIM(COALESCE(entitlement_component.key_value, '')), '') IS NOT NULL
  ), post_active_entitlement_reservations AS (
    SELECT
      reserved_component.timesheet_id,
      UPPER(BTRIM(reserved_component.key_type)) AS key_type,
      BTRIM(reserved_component.key_value) AS key_value,
      ROUND(COALESCE(reserved_component.amount_ex_vat, 0), 2) AS reserved_ex_vat
    FROM public._pay_reserved_components(COALESCE(v_post_sync_scope_timesheet_ids, ARRAY[]::uuid[]), NULL::uuid) AS reserved_component
    WHERE NULLIF(BTRIM(COALESCE(reserved_component.key_type, '')), '') IS NOT NULL
      AND NULLIF(BTRIM(COALESCE(reserved_component.key_value, '')), '') IS NOT NULL
  ), post_live_economic_keys AS (
    SELECT
      live_component.timesheet_id,
      live_component.key_type,
      live_component.key_value
    FROM post_live_entitlement_components AS live_component

    UNION

    SELECT
      reserved_component.timesheet_id,
      reserved_component.key_type,
      reserved_component.key_value
    FROM post_active_entitlement_reservations AS reserved_component
  ), post_raw_outstanding_components AS (
    SELECT
      live_key.timesheet_id,
      live_key.key_type,
      live_key.key_value,
      ROUND(COALESCE(live_component.truth_ex_vat, 0), 2) AS truth_ex_vat,
      ROUND(COALESCE(live_component.baseline_ex_vat, 0), 2) AS baseline_ex_vat,
      ROUND(COALESCE(reserved_component.reserved_ex_vat, 0), 2) AS reserved_ex_vat,
      ROUND(
        COALESCE(live_component.truth_ex_vat, 0)
        - COALESCE(live_component.baseline_ex_vat, 0)
        - COALESCE(reserved_component.reserved_ex_vat, 0),
        2
      ) AS outstanding_ex_vat
    FROM post_live_economic_keys AS live_key
    LEFT JOIN post_live_entitlement_components AS live_component
      ON live_component.timesheet_id = live_key.timesheet_id
     AND live_component.key_type = live_key.key_type
     AND live_component.key_value = live_key.key_value
    LEFT JOIN post_active_entitlement_reservations AS reserved_component
      ON reserved_component.timesheet_id = live_key.timesheet_id
     AND reserved_component.key_type = live_key.key_type
     AND reserved_component.key_value = live_key.key_value
  ), post_active_settled_component_basis AS (
    SELECT
      post_active_settled_component.timesheet_id,
      COUNT(*)::integer AS active_settled_component_count,
      md5(COALESCE(jsonb_agg(
        jsonb_build_object(
          'key_type', post_active_settled_component.key_type,
          'key_value', post_active_settled_component.key_value,
          'amount_ex_vat', ROUND(COALESCE(post_active_settled_component.amount_ex_vat, 0), 2),
          'amount_inc_vat', ROUND(COALESCE(post_active_settled_component.amount_inc_vat, 0), 2)
        ) ORDER BY post_active_settled_component.key_type, post_active_settled_component.key_value
      )::text, '[]')) AS active_settled_signature
    FROM public._pay_active_settled_components(
      COALESCE(v_post_sync_scope_timesheet_ids, ARRAY[]::uuid[])
    ) AS post_active_settled_component
    GROUP BY post_active_settled_component.timesheet_id
  )
  INSERT INTO pg_temp._tmp_pay_wb_sync_negative_components (
    timesheet_id,
    key_type,
    key_value,
    truth_ex_vat,
    baseline_ex_vat,
    reserved_ex_vat,
    outstanding_ex_vat,
    baseline_signature
  )
  SELECT
    post_negative.timesheet_id,
    post_negative.key_type,
    post_negative.key_value,
    post_negative.truth_ex_vat,
    post_negative.baseline_ex_vat,
    post_negative.reserved_ex_vat,
    post_negative.outstanding_ex_vat,
    CASE
      WHEN COALESCE(post_active_settled_basis.active_settled_component_count, 0) > 0
        THEN post_active_settled_basis.active_settled_signature
      ELSE COALESCE(
        post_timesheet_pay_state.last_settled_signature,
        md5(COALESCE(post_timesheet_pay_state.last_settled_snapshot_json::text, '{}'))
      )
    END
  FROM post_raw_outstanding_components AS post_negative
  LEFT JOIN public.timesheet_pay_state AS post_timesheet_pay_state
    ON post_timesheet_pay_state.timesheet_id = post_negative.timesheet_id
  LEFT JOIN post_active_settled_component_basis AS post_active_settled_basis
    ON post_active_settled_basis.timesheet_id = post_negative.timesheet_id
  WHERE post_negative.outstanding_ex_vat < 0;

  PERFORM public._ctms_rewrite_source_build_correction_negative_components_v1(
    p_session_id,
    p_candidate_id,
    COALESCE(v_post_sync_scope_timesheet_ids, ARRAY[]::uuid[])
  );

  SELECT COUNT(*)::integer,
         md5(COALESCE(jsonb_agg(
           jsonb_build_object(
             'timesheet_id', post_negative.timesheet_id::text,
             'key_type', post_negative.key_type,
             'key_value', post_negative.key_value,
             'truth_ex_vat', ROUND(post_negative.truth_ex_vat, 2)::numeric(12,2),
             'baseline_ex_vat', ROUND(post_negative.baseline_ex_vat, 2)::numeric(12,2),
             'reserved_ex_vat', ROUND(post_negative.reserved_ex_vat, 2)::numeric(12,2),
             'outstanding_ex_vat', ROUND(post_negative.outstanding_ex_vat, 2)::numeric(12,2)
           ) ORDER BY post_negative.timesheet_id, post_negative.key_type, post_negative.key_value
         )::text, '[]'))
  INTO v_post_sync_negative_component_count,
       v_post_sync_negative_digest
  FROM pg_temp._tmp_pay_wb_sync_negative_components AS post_negative;

  SELECT COALESCE(jsonb_agg(
           jsonb_build_object(
             'timesheet_id', bounded_negative.timesheet_id::text,
             'key_type', bounded_negative.key_type,
             'key_value', bounded_negative.key_value,
             'truth_ex_vat', ROUND(bounded_negative.truth_ex_vat, 2)::numeric(12,2),
             'baseline_ex_vat', ROUND(bounded_negative.baseline_ex_vat, 2)::numeric(12,2),
             'reserved_ex_vat', ROUND(bounded_negative.reserved_ex_vat, 2)::numeric(12,2),
             'outstanding_ex_vat', ROUND(bounded_negative.outstanding_ex_vat, 2)::numeric(12,2)
           )
           ORDER BY bounded_negative.timesheet_id,
                    bounded_negative.key_type,
                    bounded_negative.key_value
         ), '[]'::jsonb)
  INTO v_post_sync_negative_components_diagnostic
  FROM (
    SELECT *
    FROM pg_temp._tmp_pay_wb_sync_negative_components
    ORDER BY timesheet_id, key_type, key_value
    LIMIT 20
  ) AS bounded_negative;

  SELECT md5(COALESCE(jsonb_agg(
           jsonb_build_object(
             'timesheet_id', post_settled.timesheet_id::text,
             'key_type', post_settled.key_type,
             'key_value', post_settled.key_value,
             'amount_ex_vat', ROUND(COALESCE(post_settled.amount_ex_vat, 0), 2),
             'amount_inc_vat', ROUND(COALESCE(post_settled.amount_inc_vat, 0), 2)
           ) ORDER BY post_settled.timesheet_id, post_settled.key_type, post_settled.key_value
         )::text, '[]'))
  INTO v_post_sync_baseline_digest
  FROM public._pay_active_settled_components(COALESCE(v_post_sync_scope_timesheet_ids, ARRAY[]::uuid[])) AS post_settled;

  SELECT COALESCE(change_counter.seq, 0)
  INTO v_post_sync_source_change_seq
  FROM (SELECT 1) AS post_sync_anchor
  LEFT JOIN public.app_change_counters AS change_counter
    ON change_counter.entity_key = 'pay_candidate:' || p_candidate_id::text;

  IF v_post_sync_candidate_pay_channel_scope IS DISTINCT FROM v_candidate_pay_channel_scope
     OR v_post_sync_scope_digest IS DISTINCT FROM v_sync_scope_digest
     OR v_post_sync_negative_component_count IS DISTINCT FROM v_sync_negative_component_count
     OR v_post_sync_negative_digest IS DISTINCT FROM v_sync_negative_digest
     OR v_post_sync_baseline_digest IS DISTINCT FROM v_sync_baseline_digest THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_AUTHORITY_CHANGED_DURING_RECONCILIATION'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_AUTHORITY_CHANGED_DURING_RECONCILIATION',
              'session_id', p_session_id::text,
              'candidate_id', p_candidate_id::text,
              'initial_source_change_seq', COALESCE(v_initial_source_change_seq, 0),
              'post_sync_source_change_seq', COALESCE(v_post_sync_source_change_seq, 0),
              'initial_pay_channel_scope', v_candidate_pay_channel_scope,
              'post_sync_pay_channel_scope', v_post_sync_candidate_pay_channel_scope,
              'initial_scope_digest', v_sync_scope_digest,
              'post_sync_scope_digest', v_post_sync_scope_digest,
              'initial_negative_component_digest', v_sync_negative_digest,
              'post_sync_negative_component_digest', v_post_sync_negative_digest,
              'initial_negative_component_count', v_sync_negative_component_count,
              'post_sync_negative_component_count', v_post_sync_negative_component_count,
              'post_sync_negative_components', v_post_sync_negative_components_diagnostic,
              'initial_settled_baseline_digest', v_sync_baseline_digest,
              'post_sync_settled_baseline_digest', v_post_sync_baseline_digest
            )::text;
  END IF;

  /* The sequence advance is accepted only after the complete current economic
     fingerprint above remains identical.  Continuations and source rows use the
     adopted sequence returned by this function. */
  v_source_change_seq := COALESCE(v_post_sync_source_change_seq, 0);
  v_current_source_change_seq := COALESCE(v_post_sync_source_change_seq, 0);

  IF COALESCE(v_sync_negative_component_count, 0) > 0
     AND v_candidate_pay_channel_scope NOT IN ('PAYE', 'UMBRELLA') THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_NEGATIVE_COMPONENT_UNSUPPORTED_PAY_CHANNEL'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_NEGATIVE_COMPONENT_UNSUPPORTED_PAY_CHANNEL',
              'session_id', p_session_id::text,
              'candidate_id', p_candidate_id::text,
              'pay_channel_scope', v_candidate_pay_channel_scope,
              'negative_component_count', COALESCE(v_sync_negative_component_count, 0)
            )::text;
  END IF;

  IF COALESCE(v_sync_invoked, false) THEN
    WITH raw_sync_rows AS (
      SELECT negative_sync_row.value AS sync_row_json
      FROM jsonb_array_elements(
        CASE WHEN jsonb_typeof(v_sync_result->'negative_preview_timesheets') = 'array' THEN v_sync_result->'negative_preview_timesheets' ELSE '[]'::jsonb END
      ) AS negative_sync_row(value)

      UNION ALL

      SELECT candidate_sync_row.value AS sync_row_json
      FROM jsonb_array_elements(
        CASE WHEN jsonb_typeof(v_sync_result->'timesheet_finance_case_candidates') = 'array' THEN v_sync_result->'timesheet_finance_case_candidates' ELSE '[]'::jsonb END
      ) AS candidate_sync_row(value)
    ), parsed_sync_rows AS (
      SELECT
        NULLIF(BTRIM(COALESCE(raw_sync_rows.sync_row_json->>'candidate_id', '')), '') AS candidate_id_text,
        CASE
          WHEN NULLIF(BTRIM(COALESCE(raw_sync_rows.sync_row_json->>'timesheet_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN NULLIF(BTRIM(COALESCE(raw_sync_rows.sync_row_json->>'timesheet_id', '')), '')::uuid
          ELSE NULL::uuid
        END AS timesheet_id
      FROM raw_sync_rows
    )
    SELECT COUNT(*)::integer
    INTO v_sync_result_out_of_scope_count
    FROM parsed_sync_rows
    WHERE parsed_sync_rows.candidate_id_text IS DISTINCT FROM p_candidate_id::text
       OR parsed_sync_rows.timesheet_id IS NULL
       OR NOT (parsed_sync_rows.timesheet_id = ANY(COALESCE(v_sync_scope_timesheet_ids, ARRAY[]::uuid[])));

    IF COALESCE(v_sync_result_out_of_scope_count, 0) > 0 THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_OVERPAYMENT_SYNC_SCOPE_MISMATCH'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_OVERPAYMENT_SYNC_SCOPE_MISMATCH',
                'session_id', p_session_id::text,
                'candidate_id', p_candidate_id::text,
                'source_build_run_id', v_source_build_run_id::text,
                'scope_digest', v_sync_scope_digest,
                'out_of_scope_result_count', COALESCE(v_sync_result_out_of_scope_count, 0)
              )::text;
    END IF;
  END IF;

  IF COALESCE(v_sync_negative_component_count, 0) = 0 THEN
    v_sync_candidate_covered := true;
  ELSIF COALESCE(v_sync_invoked, false) THEN
    SELECT NOT EXISTS (
      SELECT 1
      FROM pg_temp._tmp_pay_wb_sync_negative_components AS negative_component
      WHERE NOT EXISTS (
        SELECT 1
        FROM (
          SELECT negative_sync_row.value AS sync_row_json
          FROM jsonb_array_elements(
            CASE WHEN jsonb_typeof(v_sync_result->'negative_preview_timesheets') = 'array' THEN v_sync_result->'negative_preview_timesheets' ELSE '[]'::jsonb END
          ) AS negative_sync_row(value)

          UNION ALL

          SELECT candidate_sync_row.value AS sync_row_json
          FROM jsonb_array_elements(
            CASE WHEN jsonb_typeof(v_sync_result->'timesheet_finance_case_candidates') = 'array' THEN v_sync_result->'timesheet_finance_case_candidates' ELSE '[]'::jsonb END
          ) AS candidate_sync_row(value)
        ) AS sync_rows
        WHERE NULLIF(BTRIM(COALESCE(sync_rows.sync_row_json->>'candidate_id', '')), '') = p_candidate_id::text
          AND EXISTS (
            SELECT 1
            FROM pg_temp._tmp_pay_wb_sync_rotation_scope AS candidate_rotation_scope
            WHERE candidate_rotation_scope.requested_timesheet_id = negative_component.timesheet_id
              AND NULLIF(BTRIM(COALESCE(sync_rows.sync_row_json->>'timesheet_id', '')), '') IN (
                candidate_rotation_scope.requested_timesheet_id::text,
                candidate_rotation_scope.canonical_timesheet_id::text,
                candidate_rotation_scope.family_timesheet_id::text
              )
          )
      )
    )
    INTO v_sync_candidate_covered;
  ELSE
    v_sync_candidate_covered := true;
  END IF;

  WITH negative_timesheet_totals AS (
    SELECT
      negative_component.timesheet_id,
      ROUND(COALESCE(SUM(ABS(negative_component.outstanding_ex_vat)), 0), 2) AS overpayment_amount_ex
    FROM pg_temp._tmp_pay_wb_sync_negative_components AS negative_component
    GROUP BY negative_component.timesheet_id
  ), component_coverage AS (
    SELECT
      negative_component.timesheet_id,
      negative_component.key_type,
      negative_component.key_value,
      CASE
        WHEN EXISTS (
          SELECT 1
          FROM jsonb_array_elements_text(
            coalesce(
              v_sync_result
                ->'correction_resolution_pending_member_timesheet_ids',
              '[]'::jsonb
            )
          ) pending_member(value)
          WHERE pending_member.value::uuid
                = negative_component.timesheet_id
        )
        OR negative_component.timesheet_id = ANY(
          COALESCE(v_current_resolution_pending_member_ids, ARRAY[]::uuid[])
        ) THEN 'RESOLUTION_PENDING'
        WHEN EXISTS (
          SELECT 1
          FROM pg_temp._tmp_pay_wb_sync_rotation_scope AS rotation_scope
          JOIN public.pay_advances AS finance_case
            ON finance_case.linked_timesheet_id = rotation_scope.family_timesheet_id
           AND finance_case.candidate_id = p_candidate_id
           AND finance_case.case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum
          JOIN public.pay_finance_case_components AS finance_component
            ON finance_component.finance_case_id = finance_case.id
           AND finance_component.candidate_id = p_candidate_id
           AND finance_component.linked_timesheet_id = finance_case.linked_timesheet_id
           AND UPPER(BTRIM(finance_component.component_key_type)) = negative_component.key_type
           AND BTRIM(finance_component.component_key_value) = negative_component.key_value
          WHERE rotation_scope.requested_timesheet_id = negative_component.timesheet_id
            AND (
              finance_case.baseline_signature IS NOT DISTINCT FROM negative_component.baseline_signature
              OR (
                LOWER(BTRIM(COALESCE(finance_component.source_family_key, '')))
                    LIKE 'correction-chain:%'
                AND NULLIF(
                      BTRIM(COALESCE(
                        finance_component.source_basis_json
                          ->>'correction_chain_residual_fingerprint',
                        ''
                      )),
                      ''
                    ) IS NOT NULL
                AND finance_case.baseline_signature IS NOT DISTINCT FROM NULLIF(
                      BTRIM(COALESCE(
                        finance_component.source_basis_json
                          ->>'correction_chain_residual_fingerprint',
                        ''
                      )),
                      ''
                    )
              )
            )
            AND finance_case.written_off_at_utc IS NULL
            AND finance_component.closed_at_utc IS NULL
            AND ROUND(COALESCE(finance_component.source_amount, 0), 2) >= ABS(negative_component.outstanding_ex_vat) - 0.01
            AND ABS(ROUND(
              COALESCE(finance_case.outstanding_amount, 0)
              - COALESCE((
                  SELECT SUM(COALESCE(case_component_remaining.remaining_source_amount, 0))
                  FROM public.pay_finance_case_components AS case_component_remaining
                  WHERE case_component_remaining.finance_case_id = finance_case.id
                    AND case_component_remaining.closed_at_utc IS NULL
                ), 0),
              2
            )) <= 0.01
            AND (
              (
                ROUND(COALESCE(finance_component.remaining_source_amount, 0), 2) > 0
                AND ROUND(COALESCE(finance_case.outstanding_amount, 0), 2) > 0
                AND finance_case.cleared_at_utc IS NULL
                AND UPPER(BTRIM(COALESCE(finance_case.status::text, ''))) = 'ACTIVE'
              )
              OR (
                ROUND(COALESCE(finance_component.remaining_source_amount, 0), 2) = 0
                AND ROUND(COALESCE(finance_case.outstanding_amount, 0), 2) = 0
                AND UPPER(BTRIM(COALESCE(finance_case.status::text, ''))) = 'PAID_OFF'
                AND (
                  EXISTS (
                    SELECT 1
                    FROM public.pay_finance_case_events AS component_settlement_event
                    WHERE component_settlement_event.finance_case_id = finance_case.id
                      AND component_settlement_event.finance_component_id = finance_component.id
                      AND UPPER(BTRIM(COALESCE(component_settlement_event.event_type, ''))) = 'COMPONENT_SETTLED'
                      AND BTRIM(COALESCE(component_settlement_event.after_json->>'remaining_source_amount', ''))
                          ~ '^-?[0-9]+([.][0-9]+)?$'
                      AND ROUND((component_settlement_event.after_json->>'remaining_source_amount')::numeric, 2) = 0
                  )
                  OR ROUND(COALESCE((
                    SELECT SUM(ABS(COALESCE(
                      settled_component_reservation.reserved_source_amount,
                      public._pay_batch_item_source_reservation_amount_ex_vat(settled_component_item.id),
                      settled_component_item.frozen_source_amount,
                      settled_component_item.amount_ex_vat,
                      settled_component_item.amount_inc_vat,
                      settled_component_reservation.reserved_amount,
                      0
                    )))
                    FROM public.pay_batch_items AS settled_component_item
                    JOIN public.pay_batch_candidates AS settled_component_candidate
                      ON settled_component_candidate.id = settled_component_item.pay_batch_candidate_id
                    LEFT JOIN public.pay_bank_transfers AS settled_component_transfer
                      ON settled_component_transfer.id = settled_component_item.pay_bank_transfer_id
                    LEFT JOIN public.pay_advance_reservations AS settled_component_reservation
                      ON settled_component_reservation.pay_batch_item_id = settled_component_item.id
                    WHERE COALESCE(settled_component_item.is_voided, false) IS NOT TRUE
                      AND UPPER(BTRIM(COALESCE(settled_component_item.item_type, ''))) = 'OVERPAYMENT_RECOVERY'
                      AND (
                        COALESCE(
                          settled_component_reservation.finance_component_id,
                          settled_component_item.finance_component_id
                        ) = finance_component.id
                        OR (
                          COALESCE(
                            settled_component_reservation.finance_component_id,
                            settled_component_item.finance_component_id
                          ) IS NULL
                          AND COALESCE(
                            settled_component_reservation.finance_case_id,
                            settled_component_item.finance_case_id,
                            CASE
                              WHEN UPPER(BTRIM(SPLIT_PART(COALESCE(settled_component_item.source_ref, ''), ':', 1))) = 'ADVANCE'
                               AND NULLIF(BTRIM(SPLIT_PART(COALESCE(settled_component_item.source_ref, ''), ':', 2)), '')
                                   ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                              THEN NULLIF(BTRIM(SPLIT_PART(COALESCE(settled_component_item.source_ref, ''), ':', 2)), '')::uuid
                              ELSE NULL::uuid
                            END
                          ) = finance_case.id
                          AND UPPER(BTRIM(COALESCE(
                            settled_component_item.frozen_component_key_type,
                            settled_component_item.frozen_component_snapshot_json->>'component_key_type',
                            settled_component_item.frozen_source_basis_json->>'component_key_type',
                            ''
                          ))) = negative_component.key_type
                          AND BTRIM(COALESCE(
                            settled_component_item.frozen_component_key_value,
                            settled_component_item.frozen_component_snapshot_json->>'component_key_value',
                            settled_component_item.frozen_source_basis_json->>'component_key_value',
                            ''
                          )) = negative_component.key_value
                          AND (
                            settled_component_item.timesheet_id IS NULL
                            OR settled_component_item.timesheet_id = finance_component.linked_timesheet_id
                            OR EXISTS (
                              SELECT 1
                              FROM pg_temp._tmp_pay_wb_sync_rotation_scope AS settled_component_rotation_scope
                              WHERE settled_component_rotation_scope.requested_timesheet_id = negative_component.timesheet_id
                                AND settled_component_item.timesheet_id IN (
                                  settled_component_rotation_scope.requested_timesheet_id,
                                  settled_component_rotation_scope.canonical_timesheet_id,
                                  settled_component_rotation_scope.family_timesheet_id
                                )
                            )
                          )
                        )
                      )
                      AND NOT EXISTS (
                        SELECT 1
                        FROM public.pay_payment_correction_items AS settled_component_correction
                        WHERE settled_component_correction.pay_batch_item_id = settled_component_item.id
                          AND settled_component_correction.status = 'APPLIED'
                          AND settled_component_correction.correction_item_kind IN (
                            'PRE_BANK_CANCEL',
                            'NO_MONEY_UNWIND',
                            'SETTLED_REVERSAL'
                          )
                      )
                      AND (
                        UPPER(BTRIM(COALESCE(settled_component_candidate.settlement_status, ''))) = 'SETTLED'
                        OR settled_component_candidate.settled_at_utc IS NOT NULL
                        OR UPPER(BTRIM(COALESCE(settled_component_transfer.status, ''))) = 'COMPLETED'
                        OR settled_component_transfer.completed_at_utc IS NOT NULL
                        OR UPPER(BTRIM(COALESCE(settled_component_reservation.status, ''))) = 'SETTLED'
                        OR settled_component_reservation.settled_at_utc IS NOT NULL
                      )
                  ), 0), 2) >= ABS(negative_component.outstanding_ex_vat) - 0.01
                )
              )
            )
        ) THEN 'DURABLE_COMPONENT'
        WHEN EXISTS (
          SELECT 1
          FROM public.pay_advances AS protected_case
          WHERE protected_case.linked_timesheet_id = negative_component.timesheet_id
            AND protected_case.candidate_id = p_candidate_id
            AND protected_case.case_type IN (
              'OVERPAYMENT'::public.pay_finance_case_type_enum,
              'UNDERPAYMENT'::public.pay_finance_case_type_enum
            )
            AND (
              protected_case.written_off_at_utc IS NOT NULL
              OR protected_case.cleared_at_utc IS NOT NULL
              OR UPPER(BTRIM(COALESCE(protected_case.status::text, ''))) NOT IN ('ACTIVE', 'PAID_OFF')
              OR EXISTS (
                SELECT 1
                FROM public.pay_finance_case_events AS protected_lifecycle_event
                WHERE protected_lifecycle_event.finance_case_id = protected_case.id
                  AND (
                    UPPER(BTRIM(COALESCE(protected_lifecycle_event.event_type, ''))) LIKE '%WRITE%OFF%'
                    OR UPPER(BTRIM(COALESCE(protected_lifecycle_event.event_type, ''))) LIKE '%RESTRUCT%'
                    OR UPPER(BTRIM(COALESCE(protected_lifecycle_event.event_type, ''))) LIKE '%MANUAL%'
                  )
              )
            )
            AND EXISTS (
              SELECT 1
              FROM public.pay_finance_case_events AS protected_sync_event
              WHERE protected_sync_event.finance_case_id = protected_case.id
                AND UPPER(BTRIM(COALESCE(protected_sync_event.event_type, ''))) = 'SYNC_SKIPPED'
                AND UPPER(BTRIM(COALESCE(protected_sync_event.reason, ''))) = 'PREVIEW_FINANCE_SYNC_SKIPPED_PROTECTED_CASE'
                AND LOWER(BTRIM(COALESCE(protected_sync_event.after_json->>'sync_skipped', 'false'))) IN (
                  '1',
                  'true',
                  't',
                  'yes',
                  'y',
                  'on'
                )
                AND UPPER(BTRIM(COALESCE(protected_sync_event.after_json->>'target_case_type', ''))) = 'OVERPAYMENT'
                AND LOWER(BTRIM(COALESCE(protected_sync_event.after_json->>'component_sync_skipped', 'false'))) IN (
                  '1',
                  'true',
                  't',
                  'yes',
                  'y',
                  'on'
                )
                AND LOWER(BTRIM(COALESCE(protected_sync_event.after_json->>'component_authority_preserved', 'false'))) IN (
                  '1',
                  'true',
                  't',
                  'yes',
                  'y',
                  'on'
                )
                AND NULLIF(BTRIM(COALESCE(protected_sync_event.after_json->>'workbench_session_id', '')), '') = p_session_id::text
                AND NULLIF(BTRIM(COALESCE(protected_sync_event.after_json->>'source_build_run_id', '')), '') = v_source_build_run_id::text
                AND NULLIF(BTRIM(COALESCE(protected_sync_event.after_json->>'session_version', '')), '') = v_session_version::text
                AND UPPER(BTRIM(COALESCE(protected_sync_event.after_json->>'target_pay_channel_scope', ''))) = v_candidate_pay_channel_scope
                AND NULLIF(BTRIM(COALESCE(protected_sync_event.after_json->>'overpayment_sync_scope_digest', '')), '') IS NOT DISTINCT FROM v_sync_scope_digest
                AND NULLIF(BTRIM(COALESCE(protected_sync_event.after_json->>'overpayment_sync_negative_component_digest', '')), '') IS NOT DISTINCT FROM v_sync_negative_digest
                AND NULLIF(BTRIM(COALESCE(protected_sync_event.after_json->>'overpayment_sync_settled_baseline_digest', '')), '') IS NOT DISTINCT FROM v_sync_baseline_digest
                AND UPPER(BTRIM(COALESCE(protected_sync_event.after_json->>'policy_x_authority_scope', ''))) = 'PRE_DRAFT_LIVE_TRUTH'
                AND NULLIF(
                      BTRIM(COALESCE(protected_sync_event.after_json->>'target_baseline_signature', '')),
                      ''
                    ) IS NOT DISTINCT FROM NULLIF(BTRIM(COALESCE(negative_component.baseline_signature, '')), '')
                AND CASE
                      WHEN BTRIM(COALESCE(protected_sync_event.after_json->>'target_original_amount', ''))
                           ~ '^-?[0-9]+([.][0-9]+)?$'
                      THEN ROUND(
                             ABS((protected_sync_event.after_json->>'target_original_amount')::numeric),
                             2
                           )
                      ELSE NULL::numeric
                    END = negative_timesheet_total.overpayment_amount_ex
            )
        ) THEN 'PROTECTED_CASE'
        ELSE 'UNCOVERED'
      END AS coverage_kind
    FROM pg_temp._tmp_pay_wb_sync_negative_components AS negative_component
    JOIN negative_timesheet_totals AS negative_timesheet_total
      ON negative_timesheet_total.timesheet_id = negative_component.timesheet_id
  )
  SELECT
    COUNT(*) FILTER (WHERE component_coverage.coverage_kind = 'DURABLE_COMPONENT')::integer,
    COUNT(*) FILTER (WHERE component_coverage.coverage_kind = 'PROTECTED_CASE')::integer,
    COUNT(*) FILTER (WHERE component_coverage.coverage_kind = 'RESOLUTION_PENDING')::integer,
    COUNT(*) FILTER (WHERE component_coverage.coverage_kind = 'UNCOVERED')::integer
  INTO v_sync_durable_component_count,
       v_sync_protected_component_count,
       v_sync_resolution_pending_component_count,
       v_sync_uncovered_component_count
  FROM component_coverage;

  /* A successful reconciliation need not echo a component that was already
     durably represented. A component awaiting the existing PAYE/umbrella
     resolution UI is intentionally not finance authority: the sync helper
     suppresses its mutation and draft creation remains fail-closed until the
     resolution is saved. Sync-result rows remain scope-checked above. */
  v_sync_candidate_covered := (
    COALESCE(v_sync_uncovered_component_count, 0) = 0
    AND COALESCE(v_sync_durable_component_count, 0)
        + COALESCE(v_sync_protected_component_count, 0)
        + COALESCE(v_sync_resolution_pending_component_count, 0)
        = COALESCE(v_sync_negative_component_count, 0)
  );

  IF COALESCE(v_sync_candidate_covered, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_OVERPAYMENT_SYNC_UNATTESTED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_OVERPAYMENT_SYNC_UNATTESTED',
              'session_id', p_session_id::text,
              'candidate_id', p_candidate_id::text,
              'source_build_run_id', v_source_build_run_id::text,
              'source_change_seq', v_source_change_seq,
              'candidate_covered', COALESCE(v_sync_candidate_covered, false),
              'negative_component_count', COALESCE(v_sync_negative_component_count, 0),
              'durable_component_count', COALESCE(v_sync_durable_component_count, 0),
              'protected_component_count', COALESCE(v_sync_protected_component_count, 0),
              'resolution_pending_component_count',
                COALESCE(v_sync_resolution_pending_component_count, 0),
              'uncovered_component_count', COALESCE(v_sync_uncovered_component_count, 0),
              'sync_result', COALESCE(v_sync_result, '{}'::jsonb)
            )::text;
  END IF;

  v_sync_result_code := CASE
    WHEN COALESCE(v_sync_negative_component_count, 0) = 0 THEN 'NO_NEGATIVE_COMPONENTS'
    WHEN COALESCE(v_sync_resolution_pending_component_count, 0) > 0
      THEN 'PAY_METHOD_RESOLUTION_REQUIRED'
    WHEN COALESCE(v_sync_protected_component_count, 0) = COALESCE(v_sync_negative_component_count, 0) THEN 'PROTECTED_TERMINAL'
    WHEN COALESCE(v_sync_protected_component_count, 0) > 0 THEN 'RECONCILED_WITH_PROTECTED_COMPONENTS'
    ELSE 'RECONCILED_DURABLE_CASE_COMPONENTS'
  END;

  v_sync_attestation := jsonb_build_object(
    'completed', true,
    'attested', true,
    'ok', true,
    'result_code', v_sync_result_code,
    'attested_at_utc', clock_timestamp()::text,
    'session_id', p_session_id::text,
    'session_version', v_session_version,
    'candidate_id', p_candidate_id::text,
    'pay_channel_scope', v_candidate_pay_channel_scope,
    'source_change_seq', v_source_change_seq,
    'source_build_run_id', v_source_build_run_id::text
  )
  || jsonb_build_object(
    'refresh_scope_kind', v_requested_refresh_scope_kind,
    'scope_timesheet_ids', COALESCE(v_sync_scope_timesheet_ids_json, '[]'::jsonb),
    'scope_timesheet_count', COALESCE(array_length(v_sync_scope_timesheet_ids, 1), 0),
    'scope_digest', v_sync_scope_digest,
    'negative_component_digest', v_sync_negative_digest,
    'settled_baseline_digest', v_sync_baseline_digest,
    'negative_component_count', COALESCE(v_sync_negative_component_count, 0),
    'durable_component_count', COALESCE(v_sync_durable_component_count, 0),
    'protected_component_count', COALESCE(v_sync_protected_component_count, 0),
    'resolution_pending_component_count',
      COALESCE(v_sync_resolution_pending_component_count, 0),
    'uncovered_component_count', COALESCE(v_sync_uncovered_component_count, 0),
    'sync_invoked', COALESCE(v_sync_invoked, false),
    'sync_marker_reused', false
  )
  || jsonb_build_object(
    'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
    'session_signature', v_session_row.session_signature,
    'old_marker_present', COALESCE(v_old_sync_marker, '{}'::jsonb) <> '{}'::jsonb,
    'old_marker_accepted_as_authority', false,
    'source_change_seq_supplied', COALESCE(v_source_change_seq_was_supplied, false),
    'initial_source_change_seq', COALESCE(v_initial_source_change_seq, 0),
    'post_sync_source_change_seq', COALESCE(v_post_sync_source_change_seq, 0),
    'sequence_advanced_with_stable_economic_fingerprint', COALESCE(v_post_sync_source_change_seq, 0) > COALESCE(v_initial_source_change_seq, 0),
    'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
  );

  v_sync_completed := true;
  v_sync_attested := true;
  END IF;

  v_overpayment_sync_elapsed_ms := round((extract(epoch from (clock_timestamp() - v_diag_phase_started_at)) * 1000.0)::numeric, 3);
  v_diag_phase_started_at := clock_timestamp();

  IF v_sync_authority_token IS NULL THEN
    v_sync_authority_token := md5(
      txid_current()::text || '|' ||
      p_session_id::text || '|' ||
      p_candidate_id::text || '|' ||
      v_source_build_run_id::text || '|' ||
      clock_timestamp()::text || '|' ||
      random()::text
    );
  END IF;

  BEGIN
    PERFORM set_config(
      'cloudtms.pay_workbench_overpayment_sync_token',
      v_sync_authority_token,
      true
    );

    v_preview_decisions_json := COALESCE(v_session_row.filters_json, '{}'::jsonb)
      || COALESCE(v_payload_json, '{}'::jsonb)
      || jsonb_build_object(
        'preview_context_mode', 'PAGE',
        'workbench_source_build_mode', true,
        'source_build_mode', true,
        'job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
        'refresh_scope_kind', v_refresh_scope_kind,
        'targeted_timesheet_ids', COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb),
        'linked_timesheet_ids', COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb),
        'finance_case_ids', COALESCE(v_finance_case_ids_json, '[]'::jsonb),
        'targeted_timesheet_ids_requested', COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb),
        'linked_timesheet_ids_requested', COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb),
        'source_build_force_include_timesheet_ids', COALESCE(v_post_sync_scope_timesheet_ids_json, '[]'::jsonb),
        'pay_channel_scope', v_pay_channel_scope,
        'source_build_run_id', v_source_build_run_id::text,
        'source_change_seq', v_source_change_seq,
        'session_version', v_session_version,
        'overpayment_sync_authority_token', v_sync_authority_token
      )
      || jsonb_build_object(
        'source_snapshot_run_id', v_session_row.source_snapshot_run_id::text,
        'session_signature', v_session_row.session_signature,
        'source_page_limit', v_limit,
        'source_cursor', COALESCE(v_cursor_json, '{}'::jsonb),
        'source_build_allow_full_fallback', LOWER(BTRIM(COALESCE(v_payload_json->>'source_build_allow_full_fallback', v_payload_json#>>'{source_build,allow_full_fallback}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
        'source_build_fallback_reason', NULLIF(BTRIM(COALESCE(v_payload_json->>'source_build_fallback_reason', v_payload_json#>>'{source_build,fallback_reason}', '')), ''),
        'overpayment_sync_completed', COALESCE(v_sync_attested, false),
        'overpayment_sync_attestation', COALESCE(v_sync_attestation, '{}'::jsonb),
        'overpayment_sync_pay_channel_scope', v_candidate_pay_channel_scope,
        'reason', NULLIF(BTRIM(COALESCE(v_payload_json->>'reason', v_payload_json#>>'{source_build,reason}', '')), ''),
        'trigger_table', NULLIF(BTRIM(COALESCE(v_payload_json->>'trigger_table', v_payload_json#>>'{trigger,table}', '')), ''),
        'trigger_operation', NULLIF(BTRIM(COALESCE(v_payload_json->>'trigger_operation', v_payload_json#>>'{trigger,operation}', '')), '')
      );

    v_context_json := public.pay_preview_build_context(
      p_pay_date => v_session_row.pay_date,
      p_week_ending_cutoff => v_session_row.week_ending_cutoff,
      p_actor_user_id => v_session_row.actor_user_id,
      p_candidate_id => p_candidate_id,
      p_client_id => NULL::uuid,
      p_preview_decisions_json => v_preview_decisions_json
    );

    v_context_json := v_context_json
    || jsonb_build_object(
      'workbench_session_id', p_session_id::text,
      'session_id', p_session_id::text,
      'workbench_resolution_session_id', p_session_id::text,
      'workbench_source_build_mode', true,
      'source_build_mode', true,
      'job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
      'refresh_scope_kind', v_refresh_scope_kind,
      'targeted_timesheet_ids', COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb),
      'linked_timesheet_ids', COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb),
      'finance_case_ids', COALESCE(v_finance_case_ids_json, '[]'::jsonb),
      'targeted_timesheet_ids_requested', COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb),
      'linked_timesheet_ids_requested', COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb),
      'source_build_force_include_timesheet_ids', COALESCE(v_post_sync_scope_timesheet_ids_json, '[]'::jsonb),
      'pay_channel_scope', v_pay_channel_scope,
      'source_build_run_id', v_source_build_run_id::text,
      'source_change_seq', v_source_change_seq,
      'session_version', v_session_version
    )
    || jsonb_build_object(
      'source_snapshot_run_id', v_session_row.source_snapshot_run_id::text,
      'session_signature', v_session_row.session_signature,
      'source_page_limit', v_limit,
      'source_cursor', COALESCE(v_cursor_json, '{}'::jsonb),
      'overpayment_sync_completed', COALESCE(v_sync_attested, false),
      'overpayment_sync_attestation', COALESCE(v_sync_attestation, '{}'::jsonb),
      'overpayment_sync_pay_channel_scope', v_candidate_pay_channel_scope
    );

    v_preview_context_elapsed_ms := round((extract(epoch from (clock_timestamp() - v_diag_phase_started_at)) * 1000.0)::numeric, 3);
    v_diag_phase_started_at := clock_timestamp();

    v_collect_result := public.pay_preview_candidate_collect_scope(
      p_context_json => v_context_json,
      p_candidate_id => p_candidate_id,
      p_cursor_json => v_cursor_json,
      p_limit => v_limit
    );

    PERFORM set_config(
      'cloudtms.pay_workbench_overpayment_sync_token',
      '',
      true
    );

  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config(
      'cloudtms.pay_workbench_overpayment_sync_token',
      '',
      true
    );
    RAISE;
  END;

  v_collect_call_wall_elapsed_ms := round((extract(epoch from (clock_timestamp() - v_diag_phase_started_at)) * 1000.0)::numeric, 3);
  v_diag_phase_started_at := clock_timestamp();

  v_collect_diagnostics_json := CASE
    WHEN jsonb_typeof(v_collect_result->'source_build_collect_diagnostics') = 'object'
      THEN COALESCE(v_collect_result->'source_build_collect_diagnostics', '{}'::jsonb)
    ELSE '{}'::jsonb
  END;

  v_actual_refresh_scope_kind := COALESCE(
    NULLIF(BTRIM(v_collect_diagnostics_json->>'actual_refresh_scope_kind'), ''),
    NULLIF(BTRIM(v_collect_result->>'refresh_scope_kind'), ''),
    v_refresh_scope_kind
  );
  v_has_more := LOWER(BTRIM(COALESCE(v_collect_diagnostics_json->>'has_more', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_source_cursor_out_json := CASE
    WHEN jsonb_typeof(v_collect_diagnostics_json->'cursor_out') = 'object' THEN v_collect_diagnostics_json->'cursor_out'
    ELSE NULL::jsonb
  END;
  v_source_cursor_in_json := CASE
    WHEN jsonb_typeof(v_collect_diagnostics_json->'cursor_in') = 'object' THEN v_collect_diagnostics_json->'cursor_in'
    ELSE COALESCE(v_cursor_json, '{}'::jsonb)
  END;
  v_collect_elapsed_ms := CASE WHEN COALESCE(v_collect_diagnostics_json->>'collect_elapsed_ms', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (v_collect_diagnostics_json->>'collect_elapsed_ms')::numeric ELSE 0 END;
  v_source_page_count := CASE WHEN COALESCE(v_collect_diagnostics_json->>'source_page_count', '') ~ '^-?[0-9]+$' THEN (v_collect_diagnostics_json->>'source_page_count')::integer ELSE 0 END;
  v_source_remaining_after_cursor_count := CASE WHEN COALESCE(v_collect_diagnostics_json->>'source_remaining_after_cursor_count', '') ~ '^-?[0-9]+$' THEN (v_collect_diagnostics_json->>'source_remaining_after_cursor_count')::integer ELSE 0 END;
  v_fallback_used := LOWER(BTRIM(COALESCE(v_collect_diagnostics_json->>'fallback_used', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_fallback_reason := NULLIF(BTRIM(COALESCE(v_collect_diagnostics_json->>'fallback_reason', '')), '');
  v_candidate_filter_applied_early := LOWER(BTRIM(COALESCE(v_collect_diagnostics_json->>'candidate_filter_applied_early', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_timesheet_filter_applied_early := LOWER(BTRIM(COALESCE(v_collect_diagnostics_json->>'timesheet_filter_applied_early', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_large_aggregation_avoided := LOWER(BTRIM(COALESCE(v_collect_diagnostics_json->>'large_aggregation_avoided', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');

  v_diag_phase_started_at := clock_timestamp();

  v_canonical_result := public.pay_preview_candidate_build_canonical_lines(
    p_context_json => v_context_json,
    p_candidate_id => p_candidate_id
  );

  v_canonical_call_wall_elapsed_ms := round((extract(epoch from (clock_timestamp() - v_diag_phase_started_at)) * 1000.0)::numeric, 3);
  v_diag_phase_started_at := clock_timestamp();

  v_canonical_diagnostics_json := CASE
    WHEN jsonb_typeof(v_canonical_result->'source_build_canonical_diagnostics') = 'object'
      THEN COALESCE(v_canonical_result->'source_build_canonical_diagnostics', '{}'::jsonb)
    ELSE '{}'::jsonb
  END;

  v_canonical_elapsed_ms := CASE WHEN COALESCE(v_canonical_diagnostics_json->>'canonical_elapsed_ms', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (v_canonical_diagnostics_json->>'canonical_elapsed_ms')::numeric ELSE 0 END;
  v_classifier_elapsed_ms := v_canonical_elapsed_ms;
  v_collect_called_inside_canonical := LOWER(BTRIM(COALESCE(v_canonical_diagnostics_json->>'collect_called_inside_canonical', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');

  IF COALESCE(v_collect_called_inside_canonical, false) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_CANONICAL_RECOLLECTED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_CANONICAL_RECOLLECTED',
              'session_id', p_session_id::text,
              'candidate_id', p_candidate_id::text
            )::text;
  END IF;

  IF to_regclass('pg_temp.canonical_preview_lines') IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_CANONICAL_LINES_MISSING'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_CANONICAL_LINES_MISSING',
              'session_id', p_session_id::text,
              'candidate_id', p_candidate_id::text
            )::text;
  END IF;

  v_diag_phase_started_at := clock_timestamp();

  DROP TABLE IF EXISTS pg_temp._tmp_pay_wb_preview_line_seed_source;
  CREATE TEMPORARY TABLE pg_temp._tmp_pay_wb_preview_line_seed_source ON COMMIT DROP AS
  WITH base_rows_raw AS (
    SELECT
      ROW_NUMBER() OVER (
        ORDER BY
          public.pay_workbench_preview_section_from_line_json(canonical_rows.line_json),
          COALESCE(canonical_rows.line_json->>'preview_row_id', canonical_rows.line_json->>'line_id', canonical_rows.line_json->>'case_key', md5(canonical_rows.line_json::text))
      )::bigint AS base_ordinal,
      canonical_rows.candidate_id,
      canonical_rows.line_json,
      canonical_rows.pay_channel,
      canonical_rows.paye_treatment,
      canonical_rows.amount_ex_vat,
      canonical_rows.is_excluded_from_allocation,
      public.pay_workbench_preview_section_from_line_json(canonical_rows.line_json) AS target_section,
      UPPER(NULLIF(BTRIM(COALESCE(canonical_rows.line_json->>'line_type', canonical_rows.line_json->>'case_type', '')), '')) AS line_type,
      CASE
        WHEN NULLIF(BTRIM(COALESCE(canonical_rows.line_json->>'real_business_timesheet_id', canonical_rows.line_json#>>'{economic_key,timesheet_id}', canonical_rows.line_json->>'timesheet_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN NULLIF(BTRIM(COALESCE(canonical_rows.line_json->>'real_business_timesheet_id', canonical_rows.line_json#>>'{economic_key,timesheet_id}', canonical_rows.line_json->>'timesheet_id', '')), '')::uuid
        ELSE NULL::uuid
      END AS requested_timesheet_id,
      NULLIF(BTRIM(COALESCE(canonical_rows.line_json->>'preview_row_id', canonical_rows.line_json->>'line_id', canonical_rows.line_json->>'case_key', md5(canonical_rows.line_json::text))), '') AS parent_line_key
    FROM pg_temp.canonical_preview_lines AS canonical_rows
    WHERE canonical_rows.candidate_id = p_candidate_id
  ), base_requested_timesheets AS (
    SELECT DISTINCT
      base_rows_raw.requested_timesheet_id
    FROM base_rows_raw
    WHERE base_rows_raw.requested_timesheet_id IS NOT NULL
  ), base_rotation_scope AS (
    SELECT
      rotation_scope_rows.requested_timesheet_id,
      rotation_scope_rows.canonical_timesheet_id,
      rotation_scope_rows.family_is_current,
      rotation_scope_rows.family_version,
      rotation_scope_rows.family_timesheet_id
    FROM public._pay_timesheet_rotation_scope(
      (
        SELECT COALESCE(
          array_agg(base_requested_timesheets.requested_timesheet_id ORDER BY base_requested_timesheets.requested_timesheet_id),
          ARRAY[]::uuid[]
        )
        FROM base_requested_timesheets
      )
    ) AS rotation_scope_rows
  ), base_requested_canonical AS (
    SELECT DISTINCT ON (base_rotation_scope.requested_timesheet_id)
      base_rotation_scope.requested_timesheet_id,
      COALESCE(base_rotation_scope.canonical_timesheet_id, base_rotation_scope.requested_timesheet_id) AS canonical_timesheet_id
    FROM base_rotation_scope
    WHERE base_rotation_scope.requested_timesheet_id IS NOT NULL
    ORDER BY
      base_rotation_scope.requested_timesheet_id,
      base_rotation_scope.family_is_current DESC NULLS LAST,
      base_rotation_scope.family_version DESC NULLS LAST,
      base_rotation_scope.family_timesheet_id
  ), base_rows AS (
    SELECT
      base_rows_raw.base_ordinal,
      base_rows_raw.candidate_id,
      jsonb_strip_nulls(
        base_rows_raw.line_json
        || jsonb_build_object(
          'timesheet_id', CASE WHEN COALESCE(base_requested_canonical.canonical_timesheet_id, base_rows_raw.requested_timesheet_id) IS NULL THEN NULL ELSE COALESCE(base_requested_canonical.canonical_timesheet_id, base_rows_raw.requested_timesheet_id)::text END,
          'real_business_timesheet_id', CASE WHEN COALESCE(base_requested_canonical.canonical_timesheet_id, base_rows_raw.requested_timesheet_id) IS NULL THEN NULL ELSE COALESCE(base_requested_canonical.canonical_timesheet_id, base_rows_raw.requested_timesheet_id)::text END
        )
        || CASE
          WHEN base_rows_raw.requested_timesheet_id IS NOT NULL
           AND COALESCE(base_requested_canonical.canonical_timesheet_id, base_rows_raw.requested_timesheet_id) IS DISTINCT FROM base_rows_raw.requested_timesheet_id
          THEN jsonb_build_object('rotation_requested_timesheet_id', base_rows_raw.requested_timesheet_id::text)
          ELSE '{}'::jsonb
        END
        || CASE
          WHEN LOWER(BTRIM(COALESCE(base_rows_raw.line_json#>>'{case_resolution_summary,has_resolved_rate}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          THEN jsonb_build_object(
            'has_resolved_rate', true,
            'resolved_rate_family', NULLIF(BTRIM(COALESCE(base_rows_raw.line_json#>>'{case_resolution_summary,resolved_rate_family}', '')), ''),
            'resolved_rate_case_key', NULLIF(BTRIM(COALESCE(base_rows_raw.line_json#>>'{case_resolution_summary,resolved_rate_case_key}', '')), ''),
            'resolved_rate_timesheet_id', NULLIF(BTRIM(COALESCE(base_rows_raw.line_json#>>'{case_resolution_summary,resolved_rate_timesheet_id}', '')), ''),
            'resolved_rate_candidate_id', NULLIF(BTRIM(COALESCE(base_rows_raw.line_json#>>'{case_resolution_summary,resolved_rate_candidate_id}', '')), ''),
            'resolved_rate_source_anchor_case_key', NULLIF(BTRIM(COALESCE(base_rows_raw.line_json#>>'{case_resolution_summary,resolved_rate_source_anchor_case_key}', '')), ''),
            'resolved_rate_source_anchor_timesheet_id', NULLIF(BTRIM(COALESCE(base_rows_raw.line_json#>>'{case_resolution_summary,resolved_rate_source_anchor_timesheet_id}', '')), ''),
            'resolved_rate_applied_via_linked_scope', LOWER(BTRIM(COALESCE(base_rows_raw.line_json#>>'{case_resolution_summary,resolved_rate_applied_via_linked_scope}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
            'resolved_rate_clear_payload_json', CASE
              WHEN jsonb_typeof(base_rows_raw.line_json#>'{case_resolution_summary,resolved_rate_clear_payload_json}') = 'object'
                THEN base_rows_raw.line_json#>'{case_resolution_summary,resolved_rate_clear_payload_json}'
              ELSE NULL::jsonb
            END
          )
          ELSE '{}'::jsonb
        END
      ) AS line_json,
      base_rows_raw.pay_channel,
      base_rows_raw.paye_treatment,
      base_rows_raw.amount_ex_vat,
      base_rows_raw.is_excluded_from_allocation,
      base_rows_raw.target_section,
      base_rows_raw.line_type,
      (
        lower(btrim(coalesce(base_rows_raw.line_json->>'has_resolved_rate', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
        or lower(btrim(coalesce(base_rows_raw.line_json#>>'{case_resolution_summary,has_resolved_rate}', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
        or lower(btrim(coalesce(base_rows_raw.line_json#>>'{case_resolution_summary,resolved_rate_applied}', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
        or lower(btrim(coalesce(base_rows_raw.line_json#>>'{case_resolution_summary,resolved_rate_active}', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
        or (
          coalesce(base_rows_raw.line_json#>>'{case_resolution_summary,resolved_rate_component_count}', '') ~ '^[0-9]+$'
          and (base_rows_raw.line_json#>>'{case_resolution_summary,resolved_rate_component_count}')::integer > 0
        )
      ) AS has_resolved_rate,
      jsonb_array_length(
        CASE
          WHEN jsonb_typeof(coalesce(base_rows_raw.line_json->'section_segment_rows', base_rows_raw.line_json->'segment_rows')) = 'array'
            THEN coalesce(base_rows_raw.line_json->'section_segment_rows', base_rows_raw.line_json->'segment_rows')
          ELSE '[]'::jsonb
        END
      ) > 0 AS has_timesheet_segment_rows,
      (
        lower(btrim(coalesce(base_rows_raw.line_json->>'resolved_segment_rows_replace_source_total', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
        and (
          lower(btrim(coalesce(base_rows_raw.line_json->>'has_resolved_rate', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
          or lower(btrim(coalesce(base_rows_raw.line_json#>>'{case_resolution_summary,has_resolved_rate}', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
          or lower(btrim(coalesce(base_rows_raw.line_json#>>'{case_resolution_summary,resolved_rate_applied}', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
          or lower(btrim(coalesce(base_rows_raw.line_json#>>'{case_resolution_summary,resolved_rate_active}', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
          or (
            coalesce(base_rows_raw.line_json#>>'{case_resolution_summary,resolved_rate_component_count}', '') ~ '^[0-9]+$'
            and (base_rows_raw.line_json#>>'{case_resolution_summary,resolved_rate_component_count}')::integer > 0
          )
        )
        and jsonb_array_length(
          CASE
            WHEN jsonb_typeof(coalesce(base_rows_raw.line_json->'section_segment_rows', base_rows_raw.line_json->'segment_rows')) = 'array'
              THEN coalesce(base_rows_raw.line_json->'section_segment_rows', base_rows_raw.line_json->'segment_rows')
            ELSE '[]'::jsonb
          END
        ) > 0
      ) AS resolved_segment_rows_replace_source_total,
      COALESCE(base_requested_canonical.canonical_timesheet_id, base_rows_raw.requested_timesheet_id) AS timesheet_id,
      base_rows_raw.parent_line_key
    FROM base_rows_raw
    LEFT JOIN base_requested_canonical
      ON base_requested_canonical.requested_timesheet_id = base_rows_raw.requested_timesheet_id
  ), timesheet_segment_rows AS (
    SELECT
      base_rows.base_ordinal,
      base_rows.candidate_id,
      base_rows.timesheet_id,
      base_rows.target_section,
      base_rows.parent_line_key,
      ('segment:' || segment_rows.segment_ord::text) AS split_suffix,
      segment_rows.segment_ord::bigint AS split_ordinal,
      'SEGMENT_DELTA'::text AS item_type,
      NULL::text AS key_type_hint,
      NULL::text AS key_value_hint,
      segment_rows.segment_json,
      jsonb_strip_nulls(
        (
          base_rows.line_json
          - 'case_components'
          - 'component_key_type'
          - 'component_key_value'
          - 'frozen_component_key_type'
          - 'frozen_component_key_value'
          - 'frozen_component_classification'
          - 'frozen_component_snapshot_json'
          - 'source_basis_json'
          - 'frozen_source_basis_json'
        )
        || jsonb_build_object(
          'source_kind', 'VALID_PREVIEW_LINE',
          'preview_row_id', base_rows.parent_line_key || ':segment:' || segment_rows.segment_ord::text,
          'line_id', base_rows.parent_line_key || ':segment:' || segment_rows.segment_ord::text,
          'line_key', base_rows.parent_line_key || ':segment:' || segment_rows.segment_ord::text,
          'row_key', base_rows.parent_line_key || ':segment:' || segment_rows.segment_ord::text
        )
        || jsonb_build_object(
          'presentation_role', 'CHILD',
          'presentation_parent_line_id', base_rows.parent_line_key,
          'amount_ex_vat', segment_rows.segment_amount_ex_vat,
          'amount_display', segment_rows.segment_amount_ex_vat,
          'section_amount_ex_vat', segment_rows.segment_amount_ex_vat,
          'section_amount_display', segment_rows.segment_amount_ex_vat
        )
        || jsonb_build_object(
          'segment_rows', jsonb_build_array(segment_rows.segment_json),
          'section_segment_rows', jsonb_build_array(segment_rows.segment_json),
          'segment_count', 1,
          'section_segment_count', 1,
          'section_non_segment_amount_ex_vat', 0,
          'segment_id', NULLIF(BTRIM(COALESCE(segment_rows.segment_json->>'segment_id', '')), '')
        )
        || jsonb_build_object(
          'segment_key', NULLIF(BTRIM(COALESCE(segment_rows.segment_json->>'segment_key', '')), ''),
          'segment_stable_key', NULLIF(BTRIM(COALESCE(segment_rows.segment_json->>'segment_stable_key', '')), ''),
          'work_date', NULLIF(BTRIM(COALESCE(segment_rows.segment_json->>'work_date', segment_rows.segment_json->>'date', '')), ''),
          'date', NULLIF(BTRIM(COALESCE(segment_rows.segment_json->>'date', segment_rows.segment_json->>'work_date', '')), ''),
          'source_basis_json', segment_rows.segment_json
        )
        || jsonb_build_object(
          'case_components', segment_case_components.segment_case_components_json
        )
      ) AS seed_line_json
    FROM base_rows
    CROSS JOIN LATERAL (
      SELECT
        segment_element.value AS segment_json,
        segment_element.ordinality::integer AS segment_ord,
        ROUND(COALESCE(
          CASE WHEN COALESCE(segment_element.value->>'pay_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (segment_element.value->>'pay_amount_ex_vat')::numeric ELSE NULL::numeric END,
          CASE WHEN COALESCE(segment_element.value->>'effective_delta_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (segment_element.value->>'effective_delta_ex_vat')::numeric ELSE NULL::numeric END,
          CASE WHEN COALESCE(segment_element.value->>'delta_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (segment_element.value->>'delta_pay_ex_vat')::numeric ELSE NULL::numeric END,
          CASE WHEN COALESCE(segment_element.value->>'raw_delta_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (segment_element.value->>'raw_delta_ex_vat')::numeric ELSE NULL::numeric END,
          0::numeric
        ), 2) AS segment_amount_ex_vat
      FROM jsonb_array_elements(COALESCE(base_rows.line_json->'section_segment_rows', base_rows.line_json->'segment_rows', '[]'::jsonb)) WITH ORDINALITY AS segment_element(value, ordinality)
      WHERE segment_element.value IS NOT NULL
        AND jsonb_typeof(segment_element.value) = 'object'
    ) AS segment_rows
    CROSS JOIN LATERAL (
      WITH segment_identity AS (
        SELECT
          NULLIF(BTRIM(COALESCE(segment_rows.segment_json->>'work_date', segment_rows.segment_json->>'date', '')), '') AS work_date,
          NULLIF(BTRIM(COALESCE(segment_rows.segment_json->>'segment_id', '')), '') AS segment_id,
          NULLIF(BTRIM(COALESCE(segment_rows.segment_json->>'segment_key', '')), '') AS segment_key,
          NULLIF(BTRIM(COALESCE(segment_rows.segment_json->>'segment_stable_key', '')), '') AS segment_stable_key
      ), component_candidates AS (
        SELECT
          component_element.value,
          component_element.ordinality,
          UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_type', component_element.value->>'key_type', '')), '')) AS component_key_type,
          NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_value', component_element.value->>'key_value', '')), '') AS component_key_value,
          NULLIF(BTRIM(COALESCE(component_element.value->>'work_date', component_element.value->>'date', component_element.value->>'source_work_date', component_element.value#>>'{source_basis_json,work_date}', component_element.value#>>'{source_basis_json,date}', '')), '') AS component_work_date,
          NULLIF(BTRIM(COALESCE(component_element.value->>'segment_id', component_element.value#>>'{source_basis_json,segment_id}', '')), '') AS component_segment_id,
          NULLIF(BTRIM(COALESCE(component_element.value->>'segment_key', component_element.value#>>'{source_basis_json,segment_key}', '')), '') AS component_segment_key,
          NULLIF(BTRIM(COALESCE(component_element.value->>'segment_stable_key', component_element.value#>>'{source_basis_json,segment_stable_key}', '')), '') AS component_segment_stable_key
        FROM jsonb_array_elements(
          CASE
            WHEN jsonb_typeof(base_rows.line_json->'case_components') = 'array' THEN base_rows.line_json->'case_components'
            ELSE '[]'::jsonb
          END
        ) WITH ORDINALITY AS component_element(value, ordinality)
        WHERE component_element.value IS NOT NULL
          AND jsonb_typeof(component_element.value) = 'object'
          AND NOT (
            UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_type', '')), '')) IN ('EXPENSE_CODE', 'ADDITIONAL_CODE')
            AND NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_value', '')), '') IS NOT NULL
          )
      ), matched_components AS (
        SELECT component_candidates.value, component_candidates.ordinality
        FROM component_candidates
        CROSS JOIN segment_identity
        WHERE (
          segment_identity.work_date IS NOT NULL
          AND (
            component_candidates.component_work_date = segment_identity.work_date
            OR (component_candidates.component_key_type = 'TS_DAY' AND component_candidates.component_key_value = segment_identity.work_date)
          )
        )
        OR (segment_identity.segment_id IS NOT NULL AND component_candidates.component_segment_id = segment_identity.segment_id)
        OR (segment_identity.segment_key IS NOT NULL AND component_candidates.component_segment_key = segment_identity.segment_key)
        OR (segment_identity.segment_stable_key IS NOT NULL AND component_candidates.component_segment_stable_key = segment_identity.segment_stable_key)
      )
      SELECT COALESCE(
        (SELECT jsonb_agg(matched_components.value ORDER BY matched_components.ordinality) FROM matched_components),
        (SELECT jsonb_agg(component_candidates.value ORDER BY component_candidates.ordinality) FROM component_candidates),
        '[]'::jsonb
      ) AS segment_case_components_json
    ) AS segment_case_components
    WHERE base_rows.target_section = 'canonical_preview_lines'
      AND base_rows.line_type = 'TIMESHEET_PAYMENT'
      AND LOWER(BTRIM(COALESCE(base_rows.line_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      AND ROUND(COALESCE(segment_rows.segment_amount_ex_vat, 0), 2) <> 0
  ), timesheet_non_segment_rows AS (
    SELECT
      base_rows.base_ordinal,
      base_rows.candidate_id,
      base_rows.timesheet_id,
      base_rows.target_section,
      base_rows.parent_line_key,
      'non_segment:total'::text AS split_suffix,
      900000::bigint AS split_ordinal,
      'SEGMENT_DELTA'::text AS item_type,
      'TS_TOTAL'::text AS key_type_hint,
      'TOTAL'::text AS key_value_hint,
      '{}'::jsonb AS segment_json,
      jsonb_strip_nulls(
        (
          base_rows.line_json
          - 'case_components'
          - 'component_key_type'
          - 'component_key_value'
          - 'frozen_component_key_type'
          - 'frozen_component_key_value'
          - 'frozen_component_classification'
          - 'frozen_component_snapshot_json'
          - 'source_basis_json'
          - 'frozen_source_basis_json'
        )
        || jsonb_build_object(
          'source_kind', 'VALID_PREVIEW_LINE',
          'preview_row_id', base_rows.parent_line_key || ':non_segment:total',
          'line_id', base_rows.parent_line_key || ':non_segment:total',
          'line_key', base_rows.parent_line_key || ':non_segment:total',
          'row_key', base_rows.parent_line_key || ':non_segment:total'
        )
        || jsonb_build_object(
          'presentation_role', 'CHILD',
          'presentation_parent_line_id', base_rows.parent_line_key,
          'amount_ex_vat', non_segment_amounts.non_segment_amount_ex_vat,
          'amount_display', non_segment_amounts.non_segment_amount_ex_vat,
          'section_amount_ex_vat', non_segment_amounts.non_segment_amount_ex_vat,
          'section_amount_display', non_segment_amounts.non_segment_amount_ex_vat
        )
        || jsonb_build_object(
          'segment_rows', '[]'::jsonb,
          'section_segment_rows', '[]'::jsonb,
          'segment_count', 0,
          'section_segment_count', 0,
          'section_non_segment_amount_ex_vat', non_segment_amounts.non_segment_amount_ex_vat,
          'source_basis_json', jsonb_build_object('component_key_type', 'TS_TOTAL', 'component_key_value', 'TOTAL')
        )
        || jsonb_build_object(
          'case_components', non_segment_case_components.non_fixed_case_components_json
        )
      ) AS seed_line_json
    FROM base_rows
    CROSS JOIN LATERAL (
      SELECT
        ROUND(COALESCE(
          CASE WHEN COALESCE(base_rows.line_json->>'section_non_segment_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (base_rows.line_json->>'section_non_segment_amount_ex_vat')::numeric ELSE NULL::numeric END,
          CASE WHEN jsonb_array_length(COALESCE(base_rows.line_json->'section_segment_rows', base_rows.line_json->'segment_rows', '[]'::jsonb)) = 0
                 AND COALESCE(base_rows.line_json->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
               THEN (base_rows.line_json->>'amount_ex_vat')::numeric ELSE NULL::numeric END,
          0::numeric
        ), 2) AS gross_non_segment_amount_ex_vat
    ) AS gross_non_segment_amounts
    CROSS JOIN LATERAL (
      SELECT
        ROUND(COALESCE(SUM(
          CASE
            WHEN COALESCE(base_rows.line_json->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
             AND (base_rows.line_json->>'amount_ex_vat')::numeric < 0
            THEN -ABS(ROUND(COALESCE(
              CASE WHEN COALESCE(component_element.value->>'preview_due_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'preview_due_amount_ex_vat')::numeric ELSE NULL::numeric END,
              CASE WHEN COALESCE(component_element.value->>'allocated_source_due_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'allocated_source_due_amount_ex_vat')::numeric ELSE NULL::numeric END,
              CASE WHEN COALESCE(component_element.value->>'target_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'target_pay_ex_vat')::numeric ELSE NULL::numeric END,
              CASE WHEN COALESCE(component_element.value->>'component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'component_amount_ex_vat')::numeric ELSE NULL::numeric END,
              CASE WHEN COALESCE(component_element.value->>'source_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'source_pay_ex_vat')::numeric ELSE NULL::numeric END,
              CASE WHEN COALESCE(component_element.value->>'remaining_source_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'remaining_source_amount')::numeric ELSE NULL::numeric END,
              0::numeric
            ), 2))
            ELSE ABS(ROUND(COALESCE(
              CASE WHEN COALESCE(component_element.value->>'preview_due_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'preview_due_amount_ex_vat')::numeric ELSE NULL::numeric END,
              CASE WHEN COALESCE(component_element.value->>'allocated_source_due_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'allocated_source_due_amount_ex_vat')::numeric ELSE NULL::numeric END,
              CASE WHEN COALESCE(component_element.value->>'target_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'target_pay_ex_vat')::numeric ELSE NULL::numeric END,
              CASE WHEN COALESCE(component_element.value->>'component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'component_amount_ex_vat')::numeric ELSE NULL::numeric END,
              CASE WHEN COALESCE(component_element.value->>'source_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'source_pay_ex_vat')::numeric ELSE NULL::numeric END,
              CASE WHEN COALESCE(component_element.value->>'remaining_source_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'remaining_source_amount')::numeric ELSE NULL::numeric END,
              0::numeric
            ), 2))
          END
        ), 0::numeric), 2) AS explicit_reimbursement_amount_ex_vat
      FROM jsonb_array_elements(COALESCE(base_rows.line_json->'case_components', '[]'::jsonb)) AS component_element(value)
      WHERE base_rows.line_type = 'TIMESHEET_PAYMENT'
        AND component_element.value IS NOT NULL
        AND jsonb_typeof(component_element.value) = 'object'
        AND UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_type', '')), '')) IN ('EXPENSE_CODE', 'ADDITIONAL_CODE')
        AND NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_value', '')), '') IS NOT NULL
        AND (
          UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_type', '')), '')) <> 'EXPENSE_CODE'
          OR UPPER(BTRIM(COALESCE(component_element.value->>'presentation_section', 'READY_TO_PAY'))) = 'READY_TO_PAY'
        )
    ) AS explicit_component_amounts
    CROSS JOIN LATERAL (
      SELECT ROUND(
        COALESCE(gross_non_segment_amounts.gross_non_segment_amount_ex_vat, 0)
        - COALESCE(explicit_component_amounts.explicit_reimbursement_amount_ex_vat, 0),
        2
      ) AS non_segment_amount_ex_vat
    ) AS non_segment_amounts
    CROSS JOIN LATERAL (
      SELECT COALESCE(
        jsonb_agg(component_element.value ORDER BY component_element.ordinality),
        '[]'::jsonb
      ) AS non_fixed_case_components_json
      FROM jsonb_array_elements(
        CASE
          WHEN jsonb_typeof(base_rows.line_json->'case_components') = 'array' THEN base_rows.line_json->'case_components'
          ELSE '[]'::jsonb
        END
      ) WITH ORDINALITY AS component_element(value, ordinality)
      WHERE NOT (
        component_element.value IS NOT NULL
        AND jsonb_typeof(component_element.value) = 'object'
        AND UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_type', '')), '')) IN ('EXPENSE_CODE', 'ADDITIONAL_CODE')
        AND NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_value', '')), '') IS NOT NULL
      )
    ) AS non_segment_case_components
    WHERE base_rows.target_section = 'canonical_preview_lines'
      AND base_rows.line_type = 'TIMESHEET_PAYMENT'
      AND LOWER(BTRIM(COALESCE(base_rows.line_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      AND NOT (
        COALESCE(base_rows.has_resolved_rate, false)
        AND COALESCE(base_rows.has_timesheet_segment_rows, false)
        AND COALESCE(base_rows.resolved_segment_rows_replace_source_total, false)
      )
      AND ROUND(COALESCE(non_segment_amounts.non_segment_amount_ex_vat, 0), 2) <> 0
  ), finance_component_rows AS (
    SELECT
      base_rows.base_ordinal,
      base_rows.candidate_id,
      component_timesheet.timesheet_id,
      component_identity.component_target_section as target_section,
      component_identity.component_parent_line_key as parent_line_key,
      component_identity.component_split_suffix as split_suffix,
      component_identity.component_split_ordinal as split_ordinal,
      CASE
        WHEN base_rows.line_type = 'OVERPAYMENT_RECOVERY' THEN 'OVERPAYMENT_RECOVERY'
        WHEN base_rows.line_type = 'UNDERPAYMENT_PAYMENT' THEN 'UNDERPAYMENT_PAYMENT'
        WHEN UPPER(NULLIF(BTRIM(COALESCE(component_rows.component_json->>'component_key_type', '')), '')) IN ('TS_DAY', 'TS_TOTAL') THEN 'SEGMENT_DELTA'
        WHEN UPPER(NULLIF(BTRIM(COALESCE(component_rows.component_json->>'component_key_type', '')), '')) = 'ADJUSTMENT_CODE' THEN 'ADJUSTMENT_DELTA'
        WHEN UPPER(NULLIF(BTRIM(COALESCE(component_rows.component_json->>'component_key_type', '')), '')) = 'EXPENSE_CODE'
         AND UPPER(NULLIF(BTRIM(COALESCE(component_rows.component_json->>'component_key_value', '')), '')) = 'MILEAGE' THEN 'MILEAGE_DELTA'
        WHEN UPPER(NULLIF(BTRIM(COALESCE(component_rows.component_json->>'component_key_type', '')), '')) IN ('EXPENSE_CODE', 'ADDITIONAL_CODE') THEN 'EXPENSE_DELTA'
        ELSE base_rows.line_type
      END AS item_type,
      UPPER(NULLIF(BTRIM(COALESCE(component_rows.component_json->>'component_key_type', '')), '')) AS key_type_hint,
      NULLIF(BTRIM(COALESCE(component_rows.component_json->>'component_key_value', '')), '') AS key_value_hint,
      '{}'::jsonb AS segment_json,
      jsonb_strip_nulls(
        (
          base_rows.line_json
          - 'case_components'
          - 'component_key_type'
          - 'component_key_value'
          - 'frozen_component_key_type'
          - 'frozen_component_key_value'
          - 'frozen_component_classification'
          - 'frozen_component_snapshot_json'
          - 'source_basis_json'
          - 'frozen_source_basis_json'
        )
        || jsonb_build_object(
          'source_kind', case when component_identity.component_target_section = 'internal_only' then 'INTERNAL_ONLY' else 'VALID_PREVIEW_LINE' end,
          'preview_row_id', component_identity.component_line_key,
          'line_id', component_identity.component_line_key,
          'line_key', component_identity.component_line_key,
          'row_key', component_identity.component_line_key,
          'target_section', component_identity.component_target_section,
          'section', component_identity.component_target_section
        )
        || jsonb_build_object(
          'presentation_role', 'CHILD',
          'presentation_parent_line_id', component_identity.component_parent_line_key,
          'presentation_section', case
            when component_identity.component_target_section = 'canonical_preview_lines' then 'READY_TO_PAY'
            when component_identity.component_target_section = 'blocked_for_pay' then 'BLOCKED_FOR_PAY'
            else 'INTERNAL_ONLY'
          end,
          'item_type', CASE
            WHEN base_rows.line_type = 'OVERPAYMENT_RECOVERY' THEN 'OVERPAYMENT_RECOVERY'
            WHEN base_rows.line_type = 'UNDERPAYMENT_PAYMENT' THEN 'UNDERPAYMENT_PAYMENT'
            WHEN UPPER(NULLIF(BTRIM(COALESCE(component_rows.component_json->>'component_key_type', '')), '')) IN ('TS_DAY', 'TS_TOTAL') THEN 'SEGMENT_DELTA'
            WHEN UPPER(NULLIF(BTRIM(COALESCE(component_rows.component_json->>'component_key_type', '')), '')) = 'ADJUSTMENT_CODE' THEN 'ADJUSTMENT_DELTA'
            WHEN UPPER(NULLIF(BTRIM(COALESCE(component_rows.component_json->>'component_key_type', '')), '')) = 'EXPENSE_CODE'
             AND UPPER(NULLIF(BTRIM(COALESCE(component_rows.component_json->>'component_key_value', '')), '')) = 'MILEAGE' THEN 'MILEAGE_DELTA'
            WHEN UPPER(NULLIF(BTRIM(COALESCE(component_rows.component_json->>'component_key_type', '')), '')) IN ('EXPENSE_CODE', 'ADDITIONAL_CODE') THEN 'EXPENSE_DELTA'
            ELSE base_rows.line_type
          END,
          'finance_component_id', NULLIF(BTRIM(COALESCE(component_rows.component_json->>'finance_component_id', '')), ''),
          'component_key_type', component_identity.component_key_type,
          'component_key_value', component_identity.component_key_value,
          'source_ref', component_identity.expense_source_ref,
          'expense_code', case when component_identity.is_expense_component then component_identity.component_key_value else null end,
          'source_basis_fingerprint', case when component_identity.is_expense_component then component_identity.source_basis_fingerprint else null end,
          'expense_source_basis_fingerprint', case when component_identity.is_expense_component then component_identity.source_basis_fingerprint else null end,
          'expense_source_basis_json', case when component_identity.is_expense_component then component_identity.expense_source_basis_json else null end
        )
        || case
          when component_identity.is_expense_component then
            jsonb_build_object(
              'snooze_identity', component_rows.component_json->'snooze_identity',
              'snooze_state', component_rows.component_json->'snooze_state',
              'expense_presentation_state', component_rows.component_json->>'expense_presentation_state',
              'expense_identity_stale', lower(btrim(coalesce(component_rows.component_json->>'expense_identity_stale', 'false'))) in ('true','t','1','yes','y','on'),
              'draftable', lower(btrim(coalesce(component_rows.component_json->>'draftable', 'false'))) in ('true','t','1','yes','y','on'),
              'is_ready_for_draft', lower(btrim(coalesce(component_rows.component_json->>'is_ready_for_draft', 'false'))) in ('true','t','1','yes','y','on'),
              'is_excluded_from_allocation', lower(btrim(coalesce(component_rows.component_json->>'is_excluded_from_allocation', 'true'))) in ('true','t','1','yes','y','on'),
              'selection_allowed', lower(btrim(coalesce(component_rows.component_json->>'selection_allowed', 'false'))) in ('true','t','1','yes','y','on')
            )
            || jsonb_build_object(
              'presentation_reason', case
                when component_identity.expense_identity_valid is not true then 'EXPENSE_SOURCE_IDENTITY_INVALID'
                when component_identity.component_target_section = 'blocked_for_pay'
                 and lower(btrim(coalesce(component_rows.component_json#>>'{snooze_state,state}', ''))) = 'stale_source_identity'
                  then 'EXPENSE_SOURCE_IDENTITY_STALE'
                when component_identity.component_target_section = 'blocked_for_pay' then 'DATED_EXPENSE_SNOOZE'
                when component_identity.component_target_section = 'internal_only' then 'INDEFINITE_EXPENSE_SNOOZE'
                else 'READY_TO_PAY'
              end,
              'blocked_reason_codes', case
                when component_identity.expense_identity_valid is not true then jsonb_build_array('EXPENSE_SOURCE_IDENTITY_INVALID')
                when component_identity.component_target_section = 'blocked_for_pay'
                 and upper(btrim(coalesce(component_rows.component_json#>>'{snooze_state,state}', ''))) = 'STALE_SOURCE_IDENTITY'
                  then jsonb_build_array('EXPENSE_SOURCE_IDENTITY_STALE')
                when component_identity.component_target_section = 'blocked_for_pay'
                  then jsonb_build_array('BLOCKED_DATED_EXPENSE_SNOOZE')
                else '[]'::jsonb
              end
            )
          else '{}'::jsonb
        end
        || jsonb_build_object(
          'case_components', jsonb_build_array(
            CASE
              WHEN ROUND(ABS(COALESCE(component_rows.source_amount_ex_vat, 0)), 2) > 0 THEN
                component_rows.component_json
                || jsonb_build_object(
                  'source_pay_ex_vat', component_rows.source_amount_ex_vat,
                  'source_amount_ex_vat', component_rows.source_amount_ex_vat,
                  'source_entitlement_amount_ex_vat', component_rows.source_amount_ex_vat,
                  'source_reservation_amount_ex_vat', component_rows.source_amount_ex_vat,
                  'frozen_source_amount', component_rows.source_amount_ex_vat
                )
                || jsonb_build_object(
                  'source_basis_json',
                  COALESCE(component_rows.component_json->'source_basis_json', '{}'::jsonb)
                  || jsonb_build_object(
                    'source_pay_ex_vat', component_rows.source_amount_ex_vat,
                    'source_amount_ex_vat', component_rows.source_amount_ex_vat,
                    'source_entitlement_amount_ex_vat', component_rows.source_amount_ex_vat,
                    'source_reservation_amount_ex_vat', component_rows.source_amount_ex_vat
                  )
                )
              ELSE component_rows.component_json
            END
          )
        )
        || jsonb_build_object(
          'amount_ex_vat', component_rows.signed_component_amount_ex_vat,
          'amount_display', component_rows.signed_component_amount_ex_vat,
          'preview_amount_ex_vat', component_rows.signed_component_amount_ex_vat,
          'source_basis_json', CASE
            WHEN ROUND(ABS(COALESCE(component_rows.source_amount_ex_vat, 0)), 2) > 0 THEN
              COALESCE(component_rows.component_json->'source_basis_json', '{}'::jsonb)
              || jsonb_build_object(
                'source_pay_ex_vat', component_rows.source_amount_ex_vat,
                'source_amount_ex_vat', component_rows.source_amount_ex_vat,
                'source_entitlement_amount_ex_vat', component_rows.source_amount_ex_vat,
                'source_reservation_amount_ex_vat', component_rows.source_amount_ex_vat
              )
            ELSE COALESCE(component_rows.component_json->'source_basis_json', '{}'::jsonb)
          END,
          'frozen_component_snapshot_json', CASE
            WHEN ROUND(ABS(COALESCE(component_rows.source_amount_ex_vat, 0)), 2) > 0 THEN
              component_rows.component_json
              || jsonb_build_object(
                'source_pay_ex_vat', component_rows.source_amount_ex_vat,
                'source_amount_ex_vat', component_rows.source_amount_ex_vat,
                'source_entitlement_amount_ex_vat', component_rows.source_amount_ex_vat,
                'source_reservation_amount_ex_vat', component_rows.source_amount_ex_vat,
                'frozen_source_amount', component_rows.source_amount_ex_vat
              )
              || jsonb_build_object(
                'source_basis_json',
                COALESCE(component_rows.component_json->'source_basis_json', '{}'::jsonb)
                || jsonb_build_object(
                  'source_pay_ex_vat', component_rows.source_amount_ex_vat,
                  'source_amount_ex_vat', component_rows.source_amount_ex_vat,
                  'source_entitlement_amount_ex_vat', component_rows.source_amount_ex_vat,
                  'source_reservation_amount_ex_vat', component_rows.source_amount_ex_vat
                )
              )
            ELSE component_rows.component_json
          END
        )
        || jsonb_build_object(
          'frozen_component_key_type', UPPER(NULLIF(BTRIM(COALESCE(component_rows.component_json->>'component_key_type', '')), '')),
          'frozen_component_key_value', NULLIF(BTRIM(COALESCE(component_rows.component_json->>'component_key_value', '')), ''),
          'frozen_component_classification', NULLIF(BTRIM(COALESCE(component_rows.component_json->>'classification', '')), ''),
          'frozen_source_basis_json', CASE
            WHEN ROUND(ABS(COALESCE(component_rows.source_amount_ex_vat, 0)), 2) > 0 THEN
              COALESCE(component_rows.component_json->'source_basis_json', '{}'::jsonb)
              || jsonb_build_object(
                'source_pay_ex_vat', component_rows.source_amount_ex_vat,
                'source_amount_ex_vat', component_rows.source_amount_ex_vat,
                'source_entitlement_amount_ex_vat', component_rows.source_amount_ex_vat,
                'source_reservation_amount_ex_vat', component_rows.source_amount_ex_vat
              )
            ELSE COALESCE(component_rows.component_json->'source_basis_json', '{}'::jsonb)
          END,
          'frozen_source_amount', component_rows.source_amount_ex_vat
        )
        || jsonb_build_object(
          'source_entitlement_amount_ex_vat', component_rows.source_amount_ex_vat,
          'source_reservation_amount_ex_vat', component_rows.source_amount_ex_vat,
          'source_amount_ex_vat', component_rows.source_amount_ex_vat,
          'remaining_source_amount', component_rows.source_amount_ex_vat,
          'target_pay_ex_vat', component_rows.signed_component_amount_ex_vat
        )
        || jsonb_build_object(
          'saved_target_pay_method', NULLIF(BTRIM(COALESCE(component_rows.component_json->>'saved_target_pay_method', '')), ''),
          'saved_resolution_mode', NULLIF(BTRIM(COALESCE(component_rows.component_json->>'saved_resolution_mode', '')), ''),
          'saved_resolution_payload_json', COALESCE(component_rows.component_json->'saved_resolution_payload_json', '{}'::jsonb),
          'saved_resolution_result_json', COALESCE(component_rows.component_json->'saved_resolution_result_json', '{}'::jsonb)
        )
        || jsonb_build_object(
          'resolution_mode', NULLIF(BTRIM(COALESCE(component_rows.component_json->>'saved_resolution_mode', '')), ''),
          'resolution_payload_json', COALESCE(component_rows.component_json->'saved_resolution_payload_json', '{}'::jsonb),
          'resolution_result_json', COALESCE(component_rows.component_json->'saved_resolution_result_json', '{}'::jsonb),
          'frozen_resolution_mode', NULLIF(BTRIM(COALESCE(component_rows.component_json->>'saved_resolution_mode', '')), ''),
          'frozen_resolution_payload_json', COALESCE(component_rows.component_json->'saved_resolution_payload_json', '{}'::jsonb),
          'frozen_resolution_result_json', COALESCE(component_rows.component_json->'saved_resolution_result_json', '{}'::jsonb)
        )
      ) AS seed_line_json
    FROM base_rows
    CROSS JOIN LATERAL (
      SELECT
        component_element.value AS component_json,
        component_element.ordinality::integer AS component_ord,
        ROUND(COALESCE(
          CASE WHEN COALESCE(component_element.value->>'preview_due_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'preview_due_amount_ex_vat')::numeric ELSE NULL::numeric END,
          CASE WHEN COALESCE(component_element.value->>'allocated_source_due_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'allocated_source_due_amount_ex_vat')::numeric ELSE NULL::numeric END,
          CASE WHEN COALESCE(component_element.value->>'target_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'target_pay_ex_vat')::numeric ELSE NULL::numeric END,
          CASE WHEN COALESCE(component_element.value->>'component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'component_amount_ex_vat')::numeric ELSE NULL::numeric END,
          CASE WHEN COALESCE(component_element.value->>'source_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'source_pay_ex_vat')::numeric ELSE NULL::numeric END,
          CASE WHEN COALESCE(component_element.value->>'remaining_source_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'remaining_source_amount')::numeric ELSE NULL::numeric END,
          0::numeric
        ), 2) AS unsigned_component_amount_ex_vat,
        ROUND(COALESCE(
          CASE WHEN COALESCE(component_element.value->>'source_reservation_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' AND ROUND(ABS((component_element.value->>'source_reservation_amount_ex_vat')::numeric), 2) > 0 THEN ABS((component_element.value->>'source_reservation_amount_ex_vat')::numeric) ELSE NULL::numeric END,
          CASE WHEN COALESCE(component_element.value->>'source_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' AND ROUND(ABS((component_element.value->>'source_amount_ex_vat')::numeric), 2) > 0 THEN ABS((component_element.value->>'source_amount_ex_vat')::numeric) ELSE NULL::numeric END,
          CASE WHEN COALESCE(component_element.value->>'source_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' AND ROUND(ABS((component_element.value->>'source_amount')::numeric), 2) > 0 THEN ABS((component_element.value->>'source_amount')::numeric) ELSE NULL::numeric END,
          CASE WHEN COALESCE(component_element.value->>'source_entitlement_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' AND ROUND(ABS((component_element.value->>'source_entitlement_amount_ex_vat')::numeric), 2) > 0 THEN ABS((component_element.value->>'source_entitlement_amount_ex_vat')::numeric) ELSE NULL::numeric END,
          CASE WHEN COALESCE(component_element.value->>'pay_outstanding_clamped_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' AND ROUND(ABS((component_element.value->>'pay_outstanding_clamped_amount_ex_vat')::numeric), 2) > 0 THEN ABS((component_element.value->>'pay_outstanding_clamped_amount_ex_vat')::numeric) ELSE NULL::numeric END,
          CASE WHEN COALESCE(component_element.value->>'pay_outstanding_available_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' AND ROUND(ABS((component_element.value->>'pay_outstanding_available_ex_vat')::numeric), 2) > 0 THEN ABS((component_element.value->>'pay_outstanding_available_ex_vat')::numeric) ELSE NULL::numeric END,
          CASE WHEN COALESCE(component_element.value->>'remaining_source_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' AND ROUND(ABS((component_element.value->>'remaining_source_amount')::numeric), 2) > 0 THEN ABS((component_element.value->>'remaining_source_amount')::numeric) ELSE NULL::numeric END,
          CASE WHEN COALESCE(component_element.value#>>'{source_basis_json,source_reservation_amount_ex_vat}', '') ~ '^-?[0-9]+(\.[0-9]+)?$' AND ROUND(ABS((component_element.value#>>'{source_basis_json,source_reservation_amount_ex_vat}')::numeric), 2) > 0 THEN ABS((component_element.value#>>'{source_basis_json,source_reservation_amount_ex_vat}')::numeric) ELSE NULL::numeric END,
          CASE WHEN COALESCE(component_element.value#>>'{source_basis_json,source_entitlement_amount_ex_vat}', '') ~ '^-?[0-9]+(\.[0-9]+)?$' AND ROUND(ABS((component_element.value#>>'{source_basis_json,source_entitlement_amount_ex_vat}')::numeric), 2) > 0 THEN ABS((component_element.value#>>'{source_basis_json,source_entitlement_amount_ex_vat}')::numeric) ELSE NULL::numeric END,
          CASE WHEN COALESCE(component_element.value#>>'{source_basis_json,source_amount_ex_vat}', '') ~ '^-?[0-9]+(\.[0-9]+)?$' AND ROUND(ABS((component_element.value#>>'{source_basis_json,source_amount_ex_vat}')::numeric), 2) > 0 THEN ABS((component_element.value#>>'{source_basis_json,source_amount_ex_vat}')::numeric) ELSE NULL::numeric END,
          CASE WHEN COALESCE(component_element.value#>>'{source_basis_json,source_pay_ex_vat}', '') ~ '^-?[0-9]+(\.[0-9]+)?$' AND ROUND(ABS((component_element.value#>>'{source_basis_json,source_pay_ex_vat}')::numeric), 2) > 0 THEN ABS((component_element.value#>>'{source_basis_json,source_pay_ex_vat}')::numeric) ELSE NULL::numeric END,
          CASE WHEN COALESCE(component_element.value->>'source_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' AND ROUND(ABS((component_element.value->>'source_pay_ex_vat')::numeric), 2) > 0 THEN ABS((component_element.value->>'source_pay_ex_vat')::numeric) ELSE NULL::numeric END,
          CASE WHEN COALESCE(component_element.value->>'source_pay_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' AND ROUND(ABS((component_element.value->>'source_pay_amount_ex_vat')::numeric), 2) > 0 THEN ABS((component_element.value->>'source_pay_amount_ex_vat')::numeric) ELSE NULL::numeric END,
          CASE WHEN UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'classification', '')), '')) = 'REIMBURSEMENT_GROSS_FIXED' AND COALESCE(component_element.value->>'preview_due_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' AND ROUND(ABS((component_element.value->>'preview_due_amount_ex_vat')::numeric), 2) > 0 THEN ABS((component_element.value->>'preview_due_amount_ex_vat')::numeric) ELSE NULL::numeric END,
          CASE WHEN UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'classification', '')), '')) = 'REIMBURSEMENT_GROSS_FIXED' AND COALESCE(component_element.value->>'target_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' AND ROUND(ABS((component_element.value->>'target_pay_ex_vat')::numeric), 2) > 0 THEN ABS((component_element.value->>'target_pay_ex_vat')::numeric) ELSE NULL::numeric END,
          0::numeric
        ), 2) AS source_amount_ex_vat,
        CASE
          WHEN COALESCE(base_rows.line_json->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
           AND (base_rows.line_json->>'amount_ex_vat')::numeric < 0
          THEN -ABS(ROUND(COALESCE(
            CASE WHEN COALESCE(component_element.value->>'preview_due_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'preview_due_amount_ex_vat')::numeric ELSE NULL::numeric END,
            CASE WHEN COALESCE(component_element.value->>'allocated_source_due_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'allocated_source_due_amount_ex_vat')::numeric ELSE NULL::numeric END,
            CASE WHEN COALESCE(component_element.value->>'target_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'target_pay_ex_vat')::numeric ELSE NULL::numeric END,
            CASE WHEN COALESCE(component_element.value->>'component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'component_amount_ex_vat')::numeric ELSE NULL::numeric END,
            CASE WHEN COALESCE(component_element.value->>'source_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'source_pay_ex_vat')::numeric ELSE NULL::numeric END,
            CASE WHEN COALESCE(component_element.value->>'remaining_source_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'remaining_source_amount')::numeric ELSE NULL::numeric END,
            0::numeric
          ), 2))
          ELSE ABS(ROUND(COALESCE(
            CASE WHEN COALESCE(component_element.value->>'preview_due_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'preview_due_amount_ex_vat')::numeric ELSE NULL::numeric END,
            CASE WHEN COALESCE(component_element.value->>'allocated_source_due_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'allocated_source_due_amount_ex_vat')::numeric ELSE NULL::numeric END,
            CASE WHEN COALESCE(component_element.value->>'target_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'target_pay_ex_vat')::numeric ELSE NULL::numeric END,
            CASE WHEN COALESCE(component_element.value->>'component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'component_amount_ex_vat')::numeric ELSE NULL::numeric END,
            CASE WHEN COALESCE(component_element.value->>'source_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'source_pay_ex_vat')::numeric ELSE NULL::numeric END,
            CASE WHEN COALESCE(component_element.value->>'remaining_source_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (component_element.value->>'remaining_source_amount')::numeric ELSE NULL::numeric END,
            0::numeric
          ), 2))
        END AS signed_component_amount_ex_vat
      FROM jsonb_array_elements(COALESCE(base_rows.line_json->'case_components', '[]'::jsonb)) WITH ORDINALITY AS component_element(value, ordinality)
      WHERE component_element.value IS NOT NULL
        AND jsonb_typeof(component_element.value) = 'object'
    ) AS component_rows
    CROSS JOIN LATERAL (
      SELECT
        UPPER(NULLIF(BTRIM(COALESCE(component_rows.component_json->>'component_key_type', '')), '')) AS component_key_type,
        UPPER(NULLIF(BTRIM(COALESCE(component_rows.component_json->>'component_key_value', component_rows.component_json->>'expense_code', '')), '')) AS component_key_value,
        CASE
          WHEN jsonb_typeof(component_rows.component_json->'expense_source_basis_json') = 'object'
            THEN COALESCE(component_rows.component_json->'expense_source_basis_json', '{}'::jsonb)
          WHEN jsonb_typeof(component_rows.component_json->'source_basis_json') = 'object'
            THEN COALESCE(component_rows.component_json->'source_basis_json', '{}'::jsonb)
          ELSE '{}'::jsonb
        END AS expense_source_basis_json,
        LOWER(NULLIF(BTRIM(COALESCE(
          component_rows.component_json->>'source_basis_fingerprint',
          component_rows.component_json->>'expense_source_basis_fingerprint',
          ''
        )), '')) AS source_basis_fingerprint,
        LOWER(NULLIF(BTRIM(COALESCE(component_rows.component_json->>'source_ref', '')), '')) AS expense_source_ref
    ) AS component_contract
    CROSS JOIN LATERAL (
      SELECT
        (component_contract.component_key_type = 'EXPENSE_CODE') AS is_expense_component,
        (
          component_contract.component_key_type = 'EXPENSE_CODE'
          AND component_contract.component_key_value IN ('EXPENSES', 'TRAVEL', 'ACCOMMODATION', 'OTHER', 'MILEAGE')
          AND component_contract.source_basis_fingerprint ~ '^[0-9a-f]{32}$'
          AND component_contract.expense_source_ref ~ (
            '^timesheet-expense:' || base_rows.timesheet_id::text ||
            ':' || lower(component_contract.component_key_value) ||
            ':' || component_contract.source_basis_fingerprint || '$'
          )
          AND md5(COALESCE(component_contract.expense_source_basis_json, '{}'::jsonb)::text)
              = component_contract.source_basis_fingerprint
        ) AS expense_identity_valid,
        component_contract.component_key_type,
        component_contract.component_key_value,
        component_contract.expense_source_basis_json,
        component_contract.source_basis_fingerprint,
        component_contract.expense_source_ref,
        CASE
          WHEN component_contract.component_key_type = 'EXPENSE_CODE'
            THEN base_rows.timesheet_id::text
          ELSE base_rows.parent_line_key
        END AS component_parent_line_key,
        CASE
          WHEN component_contract.component_key_type = 'EXPENSE_CODE'
            THEN 'component:expense:' || md5(component_contract.component_key_value)
          ELSE 'component:' || COALESCE(NULLIF(BTRIM(component_rows.component_json->>'finance_component_id'), ''), component_rows.component_ord::text)
        END AS component_split_suffix,
        CASE
          WHEN component_contract.component_key_type = 'EXPENSE_CODE' THEN
            800000::bigint + CASE component_contract.component_key_value
              WHEN 'EXPENSES' THEN 1
              WHEN 'TRAVEL' THEN 2
              WHEN 'ACCOMMODATION' THEN 3
              WHEN 'OTHER' THEN 4
              WHEN 'MILEAGE' THEN 5
              ELSE 99
            END
          ELSE component_rows.component_ord::bigint
        END AS component_split_ordinal,
        CASE
          WHEN component_contract.component_key_type = 'EXPENSE_CODE'
           AND NOT (
             component_contract.component_key_value IN ('EXPENSES', 'TRAVEL', 'ACCOMMODATION', 'OTHER', 'MILEAGE')
             AND component_contract.source_basis_fingerprint ~ '^[0-9a-f]{32}$'
             AND component_contract.expense_source_ref ~ (
               '^timesheet-expense:' || base_rows.timesheet_id::text ||
               ':' || lower(component_contract.component_key_value) ||
               ':' || component_contract.source_basis_fingerprint || '$'
             )
             AND md5(COALESCE(component_contract.expense_source_basis_json, '{}'::jsonb)::text)
                 = component_contract.source_basis_fingerprint
           ) THEN 'blocked_for_pay'
          WHEN component_contract.component_key_type = 'EXPENSE_CODE'
           AND UPPER(BTRIM(COALESCE(component_rows.component_json->>'presentation_section', ''))) = 'READY_TO_PAY'
            THEN 'canonical_preview_lines'
          WHEN component_contract.component_key_type = 'EXPENSE_CODE'
           AND UPPER(BTRIM(COALESCE(component_rows.component_json->>'presentation_section', ''))) = 'BLOCKED_FOR_PAY'
            THEN 'blocked_for_pay'
          WHEN component_contract.component_key_type = 'EXPENSE_CODE'
            THEN 'internal_only'
          ELSE base_rows.target_section
        END AS component_target_section,
        CASE
          WHEN component_contract.component_key_type = 'EXPENSE_CODE'
            THEN base_rows.timesheet_id::text || ':component:expense:' || md5(component_contract.component_key_value)
          ELSE base_rows.parent_line_key || ':component:' || COALESCE(NULLIF(BTRIM(component_rows.component_json->>'finance_component_id'), ''), component_rows.component_ord::text)
        END AS component_line_key
    ) AS component_identity
    CROSS JOIN LATERAL (
      SELECT base_rows.timesheet_id AS timesheet_id
    ) AS component_timesheet
    WHERE jsonb_array_length(COALESCE(base_rows.line_json->'case_components', '[]'::jsonb)) > 0
      AND ROUND(COALESCE(component_rows.signed_component_amount_ex_vat, 0), 2) <> 0
      AND (
        (
          component_identity.is_expense_component
          AND base_rows.line_type = 'TIMESHEET_PAYMENT'
          AND base_rows.target_section = component_identity.component_target_section
        )
        OR
        (
          NOT component_identity.is_expense_component
          AND base_rows.target_section = 'canonical_preview_lines'
          AND (
            base_rows.line_type <> 'TIMESHEET_PAYMENT'
            OR (
              base_rows.line_type = 'TIMESHEET_PAYMENT'
              AND component_identity.component_key_type = 'ADDITIONAL_CODE'
              AND component_identity.component_key_value IS NOT NULL
            )
          )
          AND LOWER(BTRIM(COALESCE(base_rows.line_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        )
      )
  ), hidden_expense_component_candidates AS (
    SELECT DISTINCT ON (hidden_base.timesheet_id, hidden_base.expense_code)
      hidden_base.candidate_id,
      hidden_base.timesheet_id,
      hidden_base.booking_id,
      hidden_base.ts_role,
      hidden_base.ts_band,
      hidden_base.client_id,
      hidden_base.client_name,
      hidden_base.week_ending_date,
      hidden_base.candidate_pay_method,
      hidden_base.cand_tms_ref,
      hidden_base.cand_display_name,
      hidden_base.expense_code,
      hidden_base.expense_label,
      hidden_base.expense_item_type,
      hidden_base.expense_source_ref,
      hidden_base.source_basis_fingerprint,
      hidden_base.expense_source_basis_json,
      hidden_base.component_amount_ex_vat,
      hidden_base.component_json,
      hidden_base.component_ordinal
    FROM (
      SELECT
        canonical_timesheet.candidate_id,
        canonical_timesheet.timesheet_id,
        canonical_timesheet.booking_id,
        canonical_timesheet.ts_role,
        canonical_timesheet.ts_band,
        canonical_timesheet.client_id,
        canonical_timesheet.client_name,
        canonical_timesheet.week_ending_date,
        canonical_timesheet.candidate_pay_method,
        canonical_timesheet.cand_tms_ref,
        canonical_timesheet.cand_display_name,
        UPPER(NULLIF(BTRIM(COALESCE(
          component_element.value->>'component_key_value',
          component_element.value->>'expense_code',
          ''
        )), '')) AS expense_code,
        COALESCE(
          NULLIF(BTRIM(COALESCE(component_element.value->>'expense_label', '')), ''),
          CASE UPPER(NULLIF(BTRIM(COALESCE(
            component_element.value->>'component_key_value',
            component_element.value->>'expense_code',
            ''
          )), ''))
            WHEN 'EXPENSES' THEN 'Expenses'
            WHEN 'TRAVEL' THEN 'Travel'
            WHEN 'ACCOMMODATION' THEN 'Accommodation'
            WHEN 'OTHER' THEN 'Other'
            WHEN 'MILEAGE' THEN 'Mileage'
            ELSE NULL::text
          END
        ) AS expense_label,
        CASE
          WHEN UPPER(NULLIF(BTRIM(COALESCE(
            component_element.value->>'component_key_value',
            component_element.value->>'expense_code',
            ''
          )), '')) = 'MILEAGE' THEN 'MILEAGE_DELTA'
          ELSE 'EXPENSE_DELTA'
        END AS expense_item_type,
        LOWER(NULLIF(BTRIM(COALESCE(component_element.value->>'source_ref', '')), '')) AS expense_source_ref,
        LOWER(NULLIF(BTRIM(COALESCE(
          component_element.value->>'source_basis_fingerprint',
          component_element.value->>'expense_source_basis_fingerprint',
          ''
        )), '')) AS source_basis_fingerprint,
        CASE
          WHEN jsonb_typeof(component_element.value->'expense_source_basis_json') = 'object'
            THEN COALESCE(component_element.value->'expense_source_basis_json', '{}'::jsonb)
          WHEN jsonb_typeof(component_element.value->'source_basis_json') = 'object'
            THEN COALESCE(component_element.value->'source_basis_json', '{}'::jsonb)
          ELSE '{}'::jsonb
        END AS expense_source_basis_json,
        ROUND(COALESCE(
          CASE WHEN COALESCE(component_element.value->>'ready_preview_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
            THEN (component_element.value->>'ready_preview_amount_ex_vat')::numeric ELSE NULL::numeric END,
          CASE WHEN COALESCE(component_element.value->>'preview_component_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
            THEN (component_element.value->>'preview_component_amount_ex_vat')::numeric ELSE NULL::numeric END,
          CASE WHEN COALESCE(component_element.value->>'component_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
            THEN (component_element.value->>'component_amount_ex_vat')::numeric ELSE NULL::numeric END,
          CASE WHEN COALESCE(component_element.value->>'target_pay_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
            THEN (component_element.value->>'target_pay_ex_vat')::numeric ELSE NULL::numeric END,
          0::numeric
        ), 2) AS component_amount_ex_vat,
        component_element.value AS component_json,
        component_element.ordinality::integer AS component_ordinal
      FROM pg_temp.canonical_timesheet_lines AS canonical_timesheet
      CROSS JOIN LATERAL jsonb_array_elements(
        CASE
          WHEN jsonb_typeof(canonical_timesheet.case_components_json) = 'array'
            THEN COALESCE(canonical_timesheet.case_components_json, '[]'::jsonb)
          ELSE '[]'::jsonb
        END
      ) WITH ORDINALITY AS component_element(value, ordinality)
      WHERE component_element.value IS NOT NULL
        AND jsonb_typeof(component_element.value) = 'object'
        AND UPPER(BTRIM(COALESCE(component_element.value->>'component_key_type', ''))) = 'EXPENSE_CODE'
        AND UPPER(BTRIM(COALESCE(component_element.value->>'presentation_section', ''))) = 'INTERNAL_ONLY'
        AND UPPER(BTRIM(COALESCE(component_element.value->>'expense_presentation_state', ''))) = 'HIDDEN_INDEFINITE'
    ) AS hidden_base
    WHERE hidden_base.expense_code IN ('EXPENSES', 'TRAVEL', 'ACCOMMODATION', 'OTHER', 'MILEAGE')
      AND hidden_base.source_basis_fingerprint ~ '^[0-9a-f]{32}$'
      AND hidden_base.expense_source_ref ~ (
        '^timesheet-expense:' || hidden_base.timesheet_id::text || ':' ||
        LOWER(hidden_base.expense_code) || ':' || hidden_base.source_basis_fingerprint || '$'
      )
      AND md5(COALESCE(hidden_base.expense_source_basis_json, '{}'::jsonb)::text)
          = hidden_base.source_basis_fingerprint
      AND ROUND(COALESCE(hidden_base.component_amount_ex_vat, 0), 2) <> 0
    ORDER BY
      hidden_base.timesheet_id,
      hidden_base.expense_code,
      hidden_base.component_ordinal
  ), hidden_expense_source_rows AS (
    SELECT
      (
        COALESCE((SELECT MAX(existing_base.base_ordinal) FROM base_rows AS existing_base), 0)
        + ROW_NUMBER() OVER (
          ORDER BY
            hidden_component.timesheet_id,
            CASE hidden_component.expense_code
              WHEN 'EXPENSES' THEN 1
              WHEN 'TRAVEL' THEN 2
              WHEN 'ACCOMMODATION' THEN 3
              WHEN 'OTHER' THEN 4
              WHEN 'MILEAGE' THEN 5
              ELSE 99
            END,
            hidden_component.expense_code
        )
      )::bigint AS base_ordinal,
      hidden_component.candidate_id,
      hidden_component.timesheet_id,
      'internal_only'::text AS target_section,
      hidden_component.timesheet_id::text AS parent_line_key,
      ('component:expense:' || md5(hidden_component.expense_code))::text AS split_suffix,
      (
        800000 + CASE hidden_component.expense_code
          WHEN 'EXPENSES' THEN 1
          WHEN 'TRAVEL' THEN 2
          WHEN 'ACCOMMODATION' THEN 3
          WHEN 'OTHER' THEN 4
          WHEN 'MILEAGE' THEN 5
          ELSE 99
        END
      )::bigint AS split_ordinal,
      hidden_component.expense_item_type AS item_type,
      'EXPENSE_CODE'::text AS key_type_hint,
      hidden_component.expense_code AS key_value_hint,
      '{}'::jsonb AS segment_json,
      jsonb_strip_nulls(
        jsonb_build_object(
          'source_kind', 'INTERNAL_ONLY',
          'preview_row_id', hidden_component.timesheet_id::text || ':component:expense:' || md5(hidden_component.expense_code),
          'line_id', hidden_component.timesheet_id::text || ':component:expense:' || md5(hidden_component.expense_code),
          'line_key', hidden_component.timesheet_id::text || ':component:expense:' || md5(hidden_component.expense_code),
          'row_key', hidden_component.timesheet_id::text || ':component:expense:' || md5(hidden_component.expense_code),
          'target_section', 'internal_only',
          'section', 'internal_only'
        )
        || jsonb_build_object(
          'candidate_id', hidden_component.candidate_id::text,
          'tms_ref', hidden_component.cand_tms_ref,
          'display_name', hidden_component.cand_display_name,
          'candidate_display_name', hidden_component.cand_display_name,
          'line_type', 'TIMESHEET_PAYMENT',
          'case_type', 'TIMESHEET_PAYMENT',
          'case_key', 'timesheet:' || hidden_component.timesheet_id::text,
          'timesheet_id', hidden_component.timesheet_id::text,
          'real_business_timesheet_id', hidden_component.timesheet_id::text,
          'booking_id', hidden_component.booking_id
        )
        || jsonb_build_object(
          'client_id', CASE WHEN hidden_component.client_id IS NULL THEN NULL ELSE hidden_component.client_id::text END,
          'client_name', hidden_component.client_name,
          'week_ending_date', CASE WHEN hidden_component.week_ending_date IS NULL THEN NULL ELSE hidden_component.week_ending_date::text END,
          'role', hidden_component.ts_role,
          'band', hidden_component.ts_band,
          'pay_channel', hidden_component.candidate_pay_method,
          'paye_treatment', CASE WHEN hidden_component.candidate_pay_method = 'PAYE' THEN 'GROSS_ADD' ELSE 'NONE' END,
          'route_type', 'NORMAL_PAYMENT',
          'item_type', hidden_component.expense_item_type,
          'component_key_type', 'EXPENSE_CODE',
          'component_key_value', hidden_component.expense_code
        )
        || jsonb_build_object(
          'economic_key', jsonb_build_object(
            'timesheet_id', hidden_component.timesheet_id::text,
            'key_type', 'EXPENSE_CODE',
            'key_value', hidden_component.expense_code
          ),
          'amount_ex_vat', hidden_component.component_amount_ex_vat,
          'amount_display', hidden_component.component_amount_ex_vat,
          'preview_amount_ex_vat', hidden_component.component_amount_ex_vat,
          'section_amount_ex_vat', hidden_component.component_amount_ex_vat,
          'section_amount_display', hidden_component.component_amount_ex_vat,
          'presentation_section', 'INTERNAL_ONLY',
          'presentation_role', 'CHILD',
          'presentation_parent_line_id', hidden_component.timesheet_id::text,
          'presentation_reason', 'INDEFINITE_EXPENSE_SNOOZE'
        )
        || jsonb_build_object(
          'draftable', false,
          'is_ready_for_draft', false,
          'is_excluded_from_allocation', true,
          'selection_allowed', false,
          'readiness_state', 'INTERNAL_ONLY',
          'source_ref', hidden_component.expense_source_ref,
          'expense_code', hidden_component.expense_code,
          'expense_label', hidden_component.expense_label,
          'source_basis_fingerprint', hidden_component.source_basis_fingerprint,
          'expense_source_basis_fingerprint', hidden_component.source_basis_fingerprint,
          'expense_source_basis_json', hidden_component.expense_source_basis_json,
          'source_basis_json', hidden_component.expense_source_basis_json
        )
        || jsonb_build_object(
          'snooze_identity', hidden_component.component_json->'snooze_identity',
          'snooze_state', hidden_component.component_json->'snooze_state',
          'expense_presentation_state', 'HIDDEN_INDEFINITE',
          'expense_identity_stale', false,
          'case_components', jsonb_build_array(hidden_component.component_json),
          'materialisation_suppressed', true,
          'materialisation_suppressed_reason', 'INDEFINITE_EXPENSE_SNOOZE',
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
        )
      ) AS seed_line_json
    FROM hidden_expense_component_candidates AS hidden_component
  ), parent_display_rows AS (
    SELECT
      base_rows.base_ordinal,
      base_rows.candidate_id,
      base_rows.timesheet_id,
      base_rows.target_section,
      base_rows.parent_line_key,
      'parent'::text AS split_suffix,
      0::bigint AS split_ordinal,
      CASE
        WHEN base_rows.line_type = 'MANUAL_ADJUSTMENT_CARRY_FORWARD' THEN 'MANUAL_CARRY_FORWARD'
        ELSE base_rows.line_type
      END AS item_type,
      CASE
        WHEN base_rows.line_type = 'MANUAL_ADJUSTMENT_CARRY_FORWARD' THEN 'MANUAL_CARRY_FORWARD'
        ELSE UPPER(NULLIF(BTRIM(COALESCE(base_rows.line_json->>'component_key_type', base_rows.line_json->>'frozen_component_key_type', '')), ''))
      END AS key_type_hint,
      CASE
        WHEN base_rows.line_type = 'MANUAL_ADJUSTMENT_CARRY_FORWARD' THEN NULLIF(BTRIM(COALESCE(base_rows.line_json->>'manual_adjustment_carry_forward_id', REPLACE(base_rows.line_json->>'source_ref', 'carry_forward:', ''), base_rows.parent_line_key, '')), '')
        ELSE NULLIF(BTRIM(COALESCE(base_rows.line_json->>'component_key_value', base_rows.line_json->>'frozen_component_key_value', '')), '')
      END AS key_value_hint,
      '{}'::jsonb AS segment_json,
      jsonb_strip_nulls(
        base_rows.line_json
        || case
          when base_rows.line_type = 'TIMESHEET_PAYMENT'
           and base_rows.target_section = 'blocked_for_pay'
           and round(coalesce(parent_expense_amounts.blocked_expense_amount_ex_vat, 0), 2) <> 0
          then jsonb_build_object(
            'amount_ex_vat', round(
              coalesce(case when coalesce(base_rows.line_json->>'amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (base_rows.line_json->>'amount_ex_vat')::numeric else null::numeric end, 0)
              - coalesce(parent_expense_amounts.blocked_expense_amount_ex_vat, 0),
              2
            ),
            'amount_display', round(
              coalesce(case when coalesce(base_rows.line_json->>'amount_display', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (base_rows.line_json->>'amount_display')::numeric else null::numeric end, 0)
              - coalesce(parent_expense_amounts.blocked_expense_amount_ex_vat, 0),
              2
            ),
            'section_amount_ex_vat', round(
              coalesce(case when coalesce(base_rows.line_json->>'section_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (base_rows.line_json->>'section_amount_ex_vat')::numeric else null::numeric end, 0)
              - coalesce(parent_expense_amounts.blocked_expense_amount_ex_vat, 0),
              2
            ),
            'section_amount_display', round(
              coalesce(case when coalesce(base_rows.line_json->>'section_amount_display', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (base_rows.line_json->>'section_amount_display')::numeric else null::numeric end, 0)
              - coalesce(parent_expense_amounts.blocked_expense_amount_ex_vat, 0),
              2
            ),
            'section_non_segment_amount_ex_vat', round(
              coalesce(case when coalesce(base_rows.line_json->>'section_non_segment_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (base_rows.line_json->>'section_non_segment_amount_ex_vat')::numeric else null::numeric end, 0)
              - coalesce(parent_expense_amounts.blocked_expense_amount_ex_vat, 0),
              2
            ),
            'split_expense_child_amount_ex_vat', round(coalesce(parent_expense_amounts.blocked_expense_amount_ex_vat, 0), 2)
          )
          else '{}'::jsonb
        end
        || jsonb_build_object(
          'source_kind', 'VALID_PREVIEW_LINE',
          'preview_row_id', base_rows.parent_line_key,
          'line_id', base_rows.parent_line_key,
          'line_key', base_rows.parent_line_key,
          'row_key', base_rows.parent_line_key,
          'target_section', base_rows.target_section
        )
        || CASE
          WHEN base_rows.target_section IN ('cases_resolutions', 'blocked_for_pay') THEN jsonb_build_object(
            'draftable', false,
            'is_ready_for_draft', false,
            'is_excluded_from_allocation', true,
            'selection_allowed', false
          )
          ELSE '{}'::jsonb
        END
      ) AS seed_line_json
    FROM base_rows
    LEFT JOIN LATERAL (
      SELECT round(coalesce(sum(
        coalesce(
          case when coalesce(expense_component.value->>'ready_preview_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (expense_component.value->>'ready_preview_amount_ex_vat')::numeric else null::numeric end,
          case when coalesce(expense_component.value->>'preview_component_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (expense_component.value->>'preview_component_amount_ex_vat')::numeric else null::numeric end,
          case when coalesce(expense_component.value->>'component_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (expense_component.value->>'component_amount_ex_vat')::numeric else null::numeric end,
          0::numeric
        )
      ), 0), 2) as blocked_expense_amount_ex_vat
      FROM jsonb_array_elements(
        CASE WHEN jsonb_typeof(base_rows.line_json->'case_components') = 'array'
          THEN COALESCE(base_rows.line_json->'case_components', '[]'::jsonb)
          ELSE '[]'::jsonb
        END
      ) AS expense_component(value)
      WHERE UPPER(BTRIM(COALESCE(expense_component.value->>'component_key_type', ''))) = 'EXPENSE_CODE'
        AND UPPER(BTRIM(COALESCE(expense_component.value->>'presentation_section', ''))) = 'BLOCKED_FOR_PAY'
    ) AS parent_expense_amounts ON true
    WHERE base_rows.target_section IN ('cases_resolutions', 'blocked_for_pay')
       OR (
          base_rows.target_section = 'canonical_preview_lines'
          AND base_rows.line_type = 'MANUAL_ADJUSTMENT_CARRY_FORWARD'
       )
       OR (
          base_rows.target_section = 'canonical_preview_lines'
          AND base_rows.line_type <> 'TIMESHEET_PAYMENT'
          AND base_rows.line_type <> 'MANUAL_ADJUSTMENT_CARRY_FORWARD'
          AND jsonb_array_length(COALESCE(base_rows.line_json->'case_components', '[]'::jsonb)) = 0
       )
  ), unioned_rows AS (
    SELECT * FROM timesheet_segment_rows
    UNION ALL
    SELECT * FROM timesheet_non_segment_rows
    UNION ALL
    SELECT * FROM finance_component_rows
    UNION ALL
    SELECT * FROM hidden_expense_source_rows
    UNION ALL
    SELECT * FROM parent_display_rows
  ), keyed_rows AS (
    SELECT
      unioned_rows.*,
      public.pay_workbench_preview_line_economic_key(
        p_line_json => unioned_rows.seed_line_json,
        p_timesheet_id => unioned_rows.timesheet_id,
        p_item_type => unioned_rows.item_type,
        p_segment_json => unioned_rows.segment_json,
        p_key_type_hint => unioned_rows.key_type_hint,
        p_key_value_hint => unioned_rows.key_value_hint
      ) AS economic_key_json
    FROM unioned_rows
  ), contracted_rows AS (
    SELECT
      keyed_rows.*,
      public.pay_workbench_preview_line_contract_ok(
        p_line_json => keyed_rows.seed_line_json,
        p_economic_key_json => keyed_rows.economic_key_json,
        p_target_section => keyed_rows.target_section
      ) AS contract_json
    FROM keyed_rows
  ), numbered_rows AS (
    SELECT
      ROW_NUMBER() OVER (
        ORDER BY contracted_rows.base_ordinal, contracted_rows.split_ordinal, contracted_rows.parent_line_key, contracted_rows.split_suffix
      )::bigint AS line_ordinal,
      contracted_rows.*
    FROM contracted_rows
    WHERE LOWER(BTRIM(COALESCE(contracted_rows.contract_json->>'ok', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
       OR (
         contracted_rows.target_section = 'internal_only'
         AND UPPER(BTRIM(COALESCE(contracted_rows.seed_line_json->>'source_kind', ''))) = 'INTERNAL_ONLY'
         AND UPPER(BTRIM(COALESCE(contracted_rows.seed_line_json#>>'{snooze_identity,identity_type}', ''))) = 'TIMESHEET_EXPENSE'
         AND UPPER(BTRIM(COALESCE(contracted_rows.seed_line_json->>'expense_presentation_state', ''))) = 'HIDDEN_INDEFINITE'
         AND LOWER(BTRIM(COALESCE(contracted_rows.seed_line_json->>'source_ref', ''))) ~
             '^timesheet-expense:[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}:(expenses|travel|accommodation|other|mileage):[0-9a-f]{32}$'
       )
  )
  SELECT numbered_rows.*
  FROM numbered_rows;

  v_temp_transform_elapsed_ms := round((extract(epoch from (clock_timestamp() - v_diag_phase_started_at)) * 1000.0)::numeric, 3);
  v_diag_phase_started_at := clock_timestamp();

  SELECT COUNT(*)::integer
  INTO v_source_canonical_preview_line_count
  FROM pg_temp.canonical_preview_lines AS source_count_rows
  WHERE source_count_rows.candidate_id = p_candidate_id;

  SELECT COUNT(*) FILTER (
           WHERE LOWER(BTRIM(COALESCE(materialisable_rows.contract_json->>'ok', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
         )::integer
  INTO v_materialisable_source_line_count
  FROM pg_temp._tmp_pay_wb_preview_line_seed_source AS materialisable_rows;

  v_contract_rejected_count := GREATEST(COALESCE(v_source_canonical_preview_line_count, 0) - COALESCE(v_materialisable_source_line_count, 0), 0);

  SELECT COUNT(DISTINCT source_timesheet_rows.timesheet_id)::integer
  INTO v_timesheets_seen
  FROM pg_temp._tmp_pay_wb_preview_line_seed_source AS source_timesheet_rows
  WHERE source_timesheet_rows.timesheet_id IS NOT NULL;

  v_temp_counts_elapsed_ms := round((extract(epoch from (clock_timestamp() - v_diag_phase_started_at)) * 1000.0)::numeric, 3);
  v_diag_phase_started_at := clock_timestamp();

  DROP TABLE IF EXISTS pg_temp._tmp_pay_wb_source_build_scope_timesheet_ids;
  CREATE TEMPORARY TABLE pg_temp._tmp_pay_wb_source_build_scope_timesheet_ids ON COMMIT DROP AS
    SELECT DISTINCT parsed_scope_ids.timesheet_id
    FROM (
      SELECT NULLIF(BTRIM(target_scope_values.value), '')::uuid AS timesheet_id
      FROM jsonb_array_elements_text(
        CASE WHEN jsonb_typeof(v_collect_result->'targeted_timesheet_ids') = 'array' THEN v_collect_result->'targeted_timesheet_ids' ELSE '[]'::jsonb END
      ) AS target_scope_values(value)
      WHERE NULLIF(BTRIM(target_scope_values.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'

      UNION

      SELECT NULLIF(BTRIM(linked_scope_values.value), '')::uuid AS timesheet_id
      FROM jsonb_array_elements_text(
        CASE WHEN jsonb_typeof(v_collect_result->'linked_timesheet_ids') = 'array' THEN v_collect_result->'linked_timesheet_ids' ELSE '[]'::jsonb END
      ) AS linked_scope_values(value)
      WHERE NULLIF(BTRIM(linked_scope_values.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'

      UNION

      SELECT source_rows.timesheet_id
      FROM pg_temp._tmp_pay_wb_preview_line_seed_source AS source_rows
      WHERE source_rows.timesheet_id IS NOT NULL
    ) AS parsed_scope_ids
    WHERE parsed_scope_ids.timesheet_id IS NOT NULL;

  v_scope_timesheet_temp_elapsed_ms := round((extract(epoch from (clock_timestamp() - v_diag_phase_started_at)) * 1000.0)::numeric, 3);
  v_diag_phase_started_at := clock_timestamp();

  SELECT final_session_row.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions AS final_session_row
  WHERE final_session_row.id = p_session_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_SESSION_NOT_FOUND_FINAL'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_SESSION_NOT_FOUND_FINAL',
              'session_id', p_session_id::text,
              'session_lock_scope', 'LOCKLESS_FINAL_REVALIDATION_OPTIONAL_NOWAIT_PROGRESS'
            )::text;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_session_row.status, ''))) <> 'OPEN'
     OR v_session_row.discarded_at_utc IS NOT NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_SESSION_NOT_OPEN_FINAL'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_SESSION_NOT_OPEN_FINAL',
              'session_id', p_session_id::text,
              'status', v_session_row.status,
              'session_lock_scope', 'LOCKLESS_FINAL_REVALIDATION_OPTIONAL_NOWAIT_PROGRESS'
            )::text;
  END IF;

  IF v_session_version IS DISTINCT FROM COALESCE(v_session_row.version, 1) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_SESSION_VERSION_STALE_FINAL'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_SESSION_VERSION_STALE_FINAL',
              'payload_session_version', v_session_version,
              'current_session_version', COALESCE(v_session_row.version, 1),
              'session_lock_scope', 'LOCKLESS_FINAL_REVALIDATION_OPTIONAL_NOWAIT_PROGRESS'
            )::text;
  END IF;

  IF v_payload_snapshot_run_id IS DISTINCT FROM v_session_row.source_snapshot_run_id THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_SNAPSHOT_RUN_ID_MISMATCH_FINAL'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_SNAPSHOT_RUN_ID_MISMATCH_FINAL',
              'payload_source_snapshot_run_id', CASE WHEN v_payload_snapshot_run_id IS NULL THEN NULL ELSE v_payload_snapshot_run_id::text END,
              'session_source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
              'session_lock_scope', 'LOCKLESS_FINAL_REVALIDATION_OPTIONAL_NOWAIT_PROGRESS'
            )::text;
  END IF;

  IF v_initial_session_signature IS DISTINCT FROM v_session_row.session_signature THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_SESSION_SIGNATURE_STALE_FINAL'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_SESSION_SIGNATURE_STALE_FINAL',
              'initial_session_signature', v_initial_session_signature,
              'current_session_signature', v_session_row.session_signature,
              'session_lock_scope', 'LOCKLESS_FINAL_REVALIDATION_OPTIONAL_NOWAIT_PROGRESS'
            )::text;
  END IF;

  SELECT COALESCE(change_counter.seq, 0)
  INTO v_final_source_change_seq
  FROM (SELECT 1) AS anchor
  LEFT JOIN public.app_change_counters AS change_counter
    ON change_counter.entity_key = 'pay_candidate:' || p_candidate_id::text;

  IF COALESCE(v_final_source_change_seq, 0) IS DISTINCT FROM COALESCE(v_source_change_seq, 0) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_SOURCE_CHANGE_SEQ_STALE_FINAL'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_SOURCE_CHANGE_SEQ_STALE_FINAL',
              'session_id', p_session_id::text,
              'candidate_id', p_candidate_id::text,
              'payload_source_change_seq', COALESCE(v_source_change_seq, 0),
              'current_source_change_seq', COALESCE(v_final_source_change_seq, 0)
            )::text;
  END IF;

  IF COALESCE(v_sync_attested, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_RECONCILIATION_ATTESTATION_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_RECONCILIATION_ATTESTATION_REQUIRED',
              'session_id', p_session_id::text,
              'candidate_id', p_candidate_id::text,
              'source_build_run_id', v_source_build_run_id::text
            )::text;
  END IF;

  v_final_revalidation_elapsed_ms := round((extract(epoch from (clock_timestamp() - v_diag_phase_started_at)) * 1000.0)::numeric, 3);
  v_diag_phase_started_at := clock_timestamp();

  IF v_requested_refresh_scope_kind = 'CANDIDATE_FULL_LIVE'
     AND COALESCE(v_first_source_page, true) THEN
    UPDATE public.banking_pay_workbench_candidate_source_lines AS source_line_retire
    SET status = 'SUPERSEDED',
        updated_at_utc = v_now
    WHERE source_line_retire.session_id = p_session_id
      AND source_line_retire.candidate_id = p_candidate_id
      AND source_line_retire.status = 'CURRENT'
      AND NOT (
        source_line_retire.session_version = v_session_version
        AND source_line_retire.source_change_seq = v_source_change_seq
        AND source_line_retire.source_build_run_id = v_source_build_run_id
      );

    GET DIAGNOSTICS v_source_rows_superseded = ROW_COUNT;
  ELSIF v_actual_refresh_scope_kind = 'TARGETED_TIMESHEETS' THEN
    UPDATE public.banking_pay_workbench_candidate_source_lines AS source_line_retire
    SET status = 'SUPERSEDED',
        updated_at_utc = v_now
    WHERE source_line_retire.session_id = p_session_id
      AND source_line_retire.candidate_id = p_candidate_id
      AND source_line_retire.status = 'CURRENT'
      AND (
        source_line_retire.timesheet_id IN (
          SELECT scope_timesheet_ids.timesheet_id
          FROM pg_temp._tmp_pay_wb_source_build_scope_timesheet_ids AS scope_timesheet_ids
        )
        OR (
          NULLIF(BTRIM(COALESCE(source_line_retire.source_row_json->>'finance_case_id', '')), '')
            ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          AND (source_line_retire.source_row_json->>'finance_case_id')::uuid
                = ANY(COALESCE(v_finance_case_ids, ARRAY[]::uuid[]))
        )
        OR (
          NULLIF(BTRIM(COALESCE(source_line_retire.source_row_json->>'dependency_family_key', '')), '')
            IN (
              SELECT DISTINCT CASE
                WHEN NULLIF(BTRIM(COALESCE(new_family.seed_line_json->>'finance_case_id', '')), '')
                     ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                  THEN 'finance:' || (new_family.seed_line_json->>'finance_case_id')
                WHEN new_family.timesheet_id IS NOT NULL
                  THEN 'timesheet:' || new_family.timesheet_id::text
                ELSE 'line-parent:' || new_family.parent_line_key
              END
              FROM pg_temp._tmp_pay_wb_preview_line_seed_source AS new_family
            )
        )
      )
      AND NOT (
        source_line_retire.session_version = v_session_version
        AND source_line_retire.source_change_seq = v_source_change_seq
        AND source_line_retire.source_build_run_id = v_source_build_run_id
      );

    GET DIAGNOSTICS v_source_rows_superseded = ROW_COUNT;
  END IF;

  v_source_retire_elapsed_ms := round((extract(epoch from (clock_timestamp() - v_diag_phase_started_at)) * 1000.0)::numeric, 3);
  v_diag_phase_started_at := clock_timestamp();

  WITH source_rows_to_upsert AS (
    SELECT
      p_session_id AS session_id,
      source_rows.candidate_id AS candidate_id,
      v_session_version AS session_version,
      v_source_change_seq AS source_change_seq,
      v_source_build_run_id AS source_build_run_id,
      (COALESCE(v_cursor_source_ordinal_base, 0) + source_rows.line_ordinal)::bigint AS source_ordinal,
      source_rows.parent_line_key || ':' || source_rows.split_suffix AS line_key,
      source_rows.parent_line_key AS parent_line_key,
      source_rows.split_suffix AS split_suffix,
      source_rows.timesheet_id AS timesheet_id,
      source_rows.target_section AS section,
      jsonb_strip_nulls(
        COALESCE(source_rows.seed_line_json, '{}'::jsonb)
        || jsonb_build_object(
          'source_function', 'pay_workbench_candidate_source_build_chunk',
          'source_kind', CASE WHEN source_rows.target_section = 'internal_only' THEN 'INTERNAL_ONLY' ELSE 'VALID_PREVIEW_LINE' END,
          'session_id', p_session_id::text,
          'session_version', v_session_version,
          'candidate_id', source_rows.candidate_id::text,
          'source_build_run_id', v_source_build_run_id::text,
          'source_change_seq', v_source_change_seq,
          'source_ordinal', (COALESCE(v_cursor_source_ordinal_base, 0) + source_rows.line_ordinal),
          'line_key', source_rows.parent_line_key || ':' || source_rows.split_suffix,
          'line_ordinal', (COALESCE(v_cursor_source_ordinal_base, 0) + source_rows.line_ordinal)
        )
        || jsonb_build_object(
          'target_section', source_rows.target_section,
          'section', source_rows.target_section,
          'economic_key', source_rows.economic_key_json,
          'preview_contract', source_rows.contract_json,
          'dependency_family_kind', CASE
            WHEN NULLIF(BTRIM(COALESCE(source_rows.seed_line_json->>'finance_case_id', '')), '')
                 ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              THEN 'FINANCE_CASE'
            WHEN source_rows.timesheet_id IS NOT NULL THEN 'TIMESHEET'
            ELSE 'LINE_PARENT'
          END,
          'dependency_family_key', CASE
            WHEN NULLIF(BTRIM(COALESCE(source_rows.seed_line_json->>'finance_case_id', '')), '')
                 ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              THEN 'finance:' || (source_rows.seed_line_json->>'finance_case_id')
            WHEN source_rows.timesheet_id IS NOT NULL
              THEN 'timesheet:' || source_rows.timesheet_id::text
            ELSE 'line-parent:' || source_rows.parent_line_key
          END,
          'refresh_scope_kind', v_actual_refresh_scope_kind,
          'requested_refresh_scope_kind', v_requested_refresh_scope_kind,
          'actual_refresh_scope_kind', v_actual_refresh_scope_kind,
          'pay_channel_scope', v_pay_channel_scope,
          'overpayment_sync_attestation', COALESCE(v_sync_attestation, '{}'::jsonb),
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
        )
      ) AS source_row_json,
      COALESCE(source_rows.economic_key_json, '{}'::jsonb) AS economic_key_json,
      jsonb_strip_nulls(
        COALESCE(source_rows.contract_json, '{}'::jsonb)
        || jsonb_build_object(
          'overpayment_sync_attested', COALESCE(v_sync_attested, false),
          'overpayment_sync_result_code', v_sync_result_code,
          'overpayment_sync_scope_digest', v_sync_scope_digest,
          'overpayment_sync_negative_component_digest', v_sync_negative_digest,
          'overpayment_sync_settled_baseline_digest', v_sync_baseline_digest,
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
        )
      ) AS contract_json,
      v_pay_channel_scope AS pay_channel_scope,
      v_actual_refresh_scope_kind AS refresh_scope_kind
    FROM pg_temp._tmp_pay_wb_preview_line_seed_source AS source_rows
    WHERE source_rows.candidate_id = p_candidate_id
      AND EXISTS (
        SELECT 1
        FROM public.banking_pay_workbench_sessions AS source_write_guard
        WHERE source_write_guard.id = p_session_id
          AND UPPER(BTRIM(COALESCE(source_write_guard.status, ''))) = 'OPEN'
          AND source_write_guard.discarded_at_utc IS NULL
          AND COALESCE(source_write_guard.version, 1) = v_session_version
          AND source_write_guard.source_snapshot_run_id IS NOT DISTINCT FROM v_payload_snapshot_run_id
          AND source_write_guard.session_signature IS NOT DISTINCT FROM v_initial_session_signature
      )
  ), upserted_source_rows AS (
    INSERT INTO public.banking_pay_workbench_candidate_source_lines (
      session_id,
      candidate_id,
      session_version,
      source_change_seq,
      source_build_run_id,
      source_ordinal,
      line_key,
      parent_line_key,
      split_suffix,
      timesheet_id,
      section,
      source_row_json,
      economic_key_json,
      contract_json,
      pay_channel_scope,
      refresh_scope_kind,
      status,
      created_at_utc,
      updated_at_utc
    )
    SELECT
      source_rows_to_upsert.session_id,
      source_rows_to_upsert.candidate_id,
      source_rows_to_upsert.session_version,
      source_rows_to_upsert.source_change_seq,
      source_rows_to_upsert.source_build_run_id,
      source_rows_to_upsert.source_ordinal,
      source_rows_to_upsert.line_key,
      source_rows_to_upsert.parent_line_key,
      source_rows_to_upsert.split_suffix,
      source_rows_to_upsert.timesheet_id,
      source_rows_to_upsert.section,
      source_rows_to_upsert.source_row_json,
      source_rows_to_upsert.economic_key_json,
      source_rows_to_upsert.contract_json,
      source_rows_to_upsert.pay_channel_scope,
      source_rows_to_upsert.refresh_scope_kind,
      'CURRENT',
      v_now,
      v_now
    FROM source_rows_to_upsert
    ON CONFLICT (
      session_id,
      candidate_id,
      session_version,
      source_change_seq,
      source_build_run_id,
      (COALESCE(timesheet_id, '00000000-0000-0000-0000-000000000000'::uuid)),
      line_key
    ) WHERE status = 'CURRENT'
    DO UPDATE
    SET source_ordinal = EXCLUDED.source_ordinal,
        parent_line_key = EXCLUDED.parent_line_key,
        split_suffix = EXCLUDED.split_suffix,
        section = EXCLUDED.section,
        source_row_json = EXCLUDED.source_row_json,
        economic_key_json = EXCLUDED.economic_key_json,
        contract_json = EXCLUDED.contract_json,
        pay_channel_scope = EXCLUDED.pay_channel_scope,
        refresh_scope_kind = EXCLUDED.refresh_scope_kind,
        updated_at_utc = v_now
    RETURNING public.banking_pay_workbench_candidate_source_lines.id,
              public.banking_pay_workbench_candidate_source_lines.source_ordinal
  )
  SELECT COUNT(*)::integer,
         COALESCE(MAX(upserted_source_rows.source_ordinal), COALESCE(v_cursor_source_ordinal_base, 0))::bigint
  INTO v_source_rows_written,
       v_next_source_ordinal
  FROM upserted_source_rows;

  v_source_upsert_elapsed_ms := round((extract(epoch from (clock_timestamp() - v_diag_phase_started_at)) * 1000.0)::numeric, 3);
  v_diag_phase_started_at := clock_timestamp();

  IF COALESCE(v_materialisable_source_line_count, 0) > 0
     AND COALESCE(v_source_rows_written, 0) = 0 THEN
    SELECT final_session_row.*
    INTO v_session_row
    FROM public.banking_pay_workbench_sessions AS final_session_row
    WHERE final_session_row.id = p_session_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_SESSION_NOT_FOUND_BEFORE_SOURCE_WRITE'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_SESSION_NOT_FOUND_BEFORE_SOURCE_WRITE',
                'session_id', p_session_id::text,
                'session_lock_scope', 'LOCKLESS_FINAL_REVALIDATION_OPTIONAL_NOWAIT_PROGRESS',
                'source_rows_written', COALESCE(v_source_rows_written, 0),
                'materialisable_source_line_count', COALESCE(v_materialisable_source_line_count, 0)
              )::text;
    END IF;

    IF UPPER(BTRIM(COALESCE(v_session_row.status, ''))) <> 'OPEN'
       OR v_session_row.discarded_at_utc IS NOT NULL THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_SESSION_NOT_OPEN_BEFORE_SOURCE_WRITE'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_SESSION_NOT_OPEN_BEFORE_SOURCE_WRITE',
                'session_id', p_session_id::text,
                'status', v_session_row.status,
                'discarded_at_utc', v_session_row.discarded_at_utc,
                'session_lock_scope', 'LOCKLESS_FINAL_REVALIDATION_OPTIONAL_NOWAIT_PROGRESS',
                'source_rows_written', COALESCE(v_source_rows_written, 0),
                'materialisable_source_line_count', COALESCE(v_materialisable_source_line_count, 0)
              )::text;
    END IF;

    IF v_session_version IS DISTINCT FROM COALESCE(v_session_row.version, 1) THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_SESSION_VERSION_STALE_BEFORE_SOURCE_WRITE'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_SESSION_VERSION_STALE_BEFORE_SOURCE_WRITE',
                'payload_session_version', v_session_version,
                'current_session_version', COALESCE(v_session_row.version, 1),
                'session_lock_scope', 'LOCKLESS_FINAL_REVALIDATION_OPTIONAL_NOWAIT_PROGRESS',
                'source_rows_written', COALESCE(v_source_rows_written, 0),
                'materialisable_source_line_count', COALESCE(v_materialisable_source_line_count, 0)
              )::text;
    END IF;

    IF v_payload_snapshot_run_id IS DISTINCT FROM v_session_row.source_snapshot_run_id THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_SNAPSHOT_RUN_ID_MISMATCH_BEFORE_SOURCE_WRITE'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_SNAPSHOT_RUN_ID_MISMATCH_BEFORE_SOURCE_WRITE',
                'payload_source_snapshot_run_id', CASE WHEN v_payload_snapshot_run_id IS NULL THEN NULL ELSE v_payload_snapshot_run_id::text END,
                'session_source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
                'session_lock_scope', 'LOCKLESS_FINAL_REVALIDATION_OPTIONAL_NOWAIT_PROGRESS',
                'source_rows_written', COALESCE(v_source_rows_written, 0),
                'materialisable_source_line_count', COALESCE(v_materialisable_source_line_count, 0)
              )::text;
    END IF;

    IF v_initial_session_signature IS DISTINCT FROM v_session_row.session_signature THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_SESSION_SIGNATURE_STALE_BEFORE_SOURCE_WRITE'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_SESSION_SIGNATURE_STALE_BEFORE_SOURCE_WRITE',
                'initial_session_signature', v_initial_session_signature,
                'current_session_signature', v_session_row.session_signature,
                'session_lock_scope', 'LOCKLESS_FINAL_REVALIDATION_OPTIONAL_NOWAIT_PROGRESS',
                'source_rows_written', COALESCE(v_source_rows_written, 0),
                'materialisable_source_line_count', COALESCE(v_materialisable_source_line_count, 0)
              )::text;
    END IF;
  END IF;

  v_source_write_guard_elapsed_ms := round((extract(epoch from (clock_timestamp() - v_diag_phase_started_at)) * 1000.0)::numeric, 3);
  v_diag_phase_started_at := clock_timestamp();

  SELECT COUNT(*)::integer
  INTO v_current_source_row_count
  FROM public.banking_pay_workbench_candidate_source_lines AS current_source_rows
  WHERE current_source_rows.session_id = p_session_id
    AND current_source_rows.candidate_id = p_candidate_id
    AND current_source_rows.session_version = v_session_version
    AND current_source_rows.source_change_seq = v_source_change_seq
    AND current_source_rows.source_build_run_id = v_source_build_run_id
    AND current_source_rows.status = 'CURRENT';

  v_current_source_count_elapsed_ms := round((extract(epoch from (clock_timestamp() - v_diag_phase_started_at)) * 1000.0)::numeric, 3);
  v_diag_phase_started_at := clock_timestamp();

  IF COALESCE(v_current_source_row_count, 0) > 0 THEN
    v_source_reconcile_result := jsonb_build_object(
      'ok', true,
      'deferred', true,
      'deferred_to', 'pay_workbench_complete_job',
      'reason', 'SOURCE_BUILD_CHUNK_AVOIDS_SHARED_SESSION_ROW_FINALISATION_LOCK',
      'session_id', p_session_id::text,
      'candidate_id', p_candidate_id::text,
      'source_build_run_id', v_source_build_run_id::text,
      'source_change_seq', v_source_change_seq,
      'session_version', v_session_version,
      'source_rows_superseded', 0,
      'source_build_jobs_superseded', 0,
      'counter_reconciled', false,
      'session_lock_scope', 'LOCKLESS_FINAL_REVALIDATION_OPTIONAL_NOWAIT_PROGRESS'
    );

    v_reconciled_source_rows_superseded := 0;
    v_reconciled_source_build_jobs_superseded := 0;
  END IF;

  v_reconciliation_defer_elapsed_ms := round((extract(epoch from (clock_timestamp() - v_diag_phase_started_at)) * 1000.0)::numeric, 3);
  v_diag_phase_started_at := clock_timestamp();

  IF COALESCE(v_has_more, false) AND v_source_cursor_out_json IS NOT NULL THEN
    v_next_cursor_json := COALESCE(v_source_cursor_out_json, '{}'::jsonb)
      || jsonb_build_object(
        'last_source_ordinal', COALESCE(v_next_source_ordinal, v_cursor_source_ordinal_base, 0),
        'source_build_run_id', v_source_build_run_id::text,
        'source_change_seq', v_source_change_seq,
        'session_version', v_session_version,
        'session_id', p_session_id::text,
        'candidate_id', p_candidate_id::text,
        'source_snapshot_run_id', v_session_row.source_snapshot_run_id::text,
        'session_signature', v_session_row.session_signature,
        'source_page_limit', v_limit,
        'requested_refresh_scope_kind', v_requested_refresh_scope_kind
      );
  ELSE
    v_next_cursor_json := NULL::jsonb;
  END IF;

  v_cursor_advanced := v_next_cursor_json IS NOT NULL
    AND v_next_cursor_json IS DISTINCT FROM COALESCE(v_cursor_json, '{}'::jsonb);

  v_next_cursor_elapsed_ms := round((extract(epoch from (clock_timestamp() - v_diag_phase_started_at)) * 1000.0)::numeric, 3);
  v_diag_phase_started_at := clock_timestamp();

  UPDATE public.banking_pay_workbench_session_scope AS scope_update
  SET status = CASE
        WHEN COALESCE(v_sync_attested, false) IS NOT TRUE THEN 'SOURCE_BUILD_PENDING'
        WHEN COALESCE(v_has_more, false) THEN 'SOURCE_BUILD_PENDING'
        WHEN COALESCE(v_current_source_row_count, 0) > 0 THEN 'SOURCE_READY'
        ELSE 'SOURCE_EMPTY'
      END,
      dirty = COALESCE(v_has_more, false) OR COALESCE(v_sync_attested, false) IS NOT TRUE,
      error_json = NULL::jsonb,
      updated_at_utc = v_now
  WHERE scope_update.session_id = p_session_id
    AND scope_update.candidate_id = p_candidate_id;

  v_scope_update_elapsed_ms := round((extract(epoch from (clock_timestamp() - v_diag_phase_started_at)) * 1000.0)::numeric, 3);

  v_source_build_timing_json := jsonb_build_object(
    'timing_version', 'source_build_residual_v1',
    'complete', false,
    'source_build_run_id', v_source_build_run_id::text,
    'source_change_seq', v_source_change_seq,
    'session_version', v_session_version,
    'source_page_count', COALESCE(v_source_page_count, 0),
    'source_rows_written', COALESCE(v_source_rows_written, 0),
    'materialisable_source_line_count', COALESCE(v_materialisable_source_line_count, 0),
    'source_rows_seen', COALESCE(v_source_canonical_preview_line_count, 0),
    'phase_elapsed_ms', jsonb_build_object(
      'budget_apply', COALESCE(v_budget_apply_elapsed_ms, 0),
      'initial_validation', COALESCE(v_initial_validation_elapsed_ms, 0),
      'overpayment_sync', COALESCE(v_overpayment_sync_elapsed_ms, 0),
      'preview_context_build', COALESCE(v_preview_context_elapsed_ms, 0),
      'collect_call_wall', COALESCE(v_collect_call_wall_elapsed_ms, 0),
      'collect_reported', COALESCE(v_collect_elapsed_ms, 0),
      'canonical_call_wall', COALESCE(v_canonical_call_wall_elapsed_ms, 0),
      'canonical_reported', COALESCE(v_canonical_elapsed_ms, 0)
    )
    || jsonb_build_object(
      'temp_transform', COALESCE(v_temp_transform_elapsed_ms, 0),
      'temp_counts', COALESCE(v_temp_counts_elapsed_ms, 0),
      'scope_timesheet_temp', COALESCE(v_scope_timesheet_temp_elapsed_ms, 0),
      'final_revalidation', COALESCE(v_final_revalidation_elapsed_ms, 0),
      'source_retire', COALESCE(v_source_retire_elapsed_ms, 0),
      'source_upsert', COALESCE(v_source_upsert_elapsed_ms, 0),
      'source_write_guard', COALESCE(v_source_write_guard_elapsed_ms, 0),
      'current_source_count', COALESCE(v_current_source_count_elapsed_ms, 0)
    )
    || jsonb_build_object(
      'reconciliation_defer', COALESCE(v_reconciliation_defer_elapsed_ms, 0),
      'next_cursor', COALESCE(v_next_cursor_elapsed_ms, 0),
      'scope_update', COALESCE(v_scope_update_elapsed_ms, 0),
      'session_progress_update', COALESCE(v_session_progress_update_elapsed_ms, 0)
    )
  );

  v_diag_phase_started_at := clock_timestamp();

  BEGIN
    PERFORM 1
    FROM public.banking_pay_workbench_sessions AS session_progress_lock
    WHERE session_progress_lock.id = p_session_id
      AND UPPER(BTRIM(COALESCE(session_progress_lock.status, ''))) = 'OPEN'
      AND session_progress_lock.discarded_at_utc IS NULL
      AND COALESCE(session_progress_lock.version, 1) = v_session_version
      AND session_progress_lock.source_snapshot_run_id IS NOT DISTINCT FROM v_payload_snapshot_run_id
      AND session_progress_lock.session_signature IS NOT DISTINCT FROM v_initial_session_signature
    FOR UPDATE NOWAIT;

    IF FOUND THEN
      UPDATE public.banking_pay_workbench_sessions AS session_update
      SET progress_state = 'REFRESHING_CANDIDATES',
          progress_json = COALESCE(session_update.progress_json, '{}'::jsonb)
            || CASE
              WHEN COALESCE(v_sync_completed, false) THEN jsonb_build_object(
                'overpayment_sync_completed_by_candidate',
                CASE
                  WHEN jsonb_typeof(session_update.progress_json->'overpayment_sync_completed_by_candidate') = 'object'
                    THEN COALESCE(session_update.progress_json->'overpayment_sync_completed_by_candidate', '{}'::jsonb)
                  ELSE '{}'::jsonb
                END
                || jsonb_build_object(
                  p_candidate_id::text,
                  COALESCE(v_sync_attestation, '{}'::jsonb)
                  || jsonb_build_object(
                    'completed_at_utc', v_now::text,
                    'session_progress_marker_only', true
                  )
                )
              )
              ELSE '{}'::jsonb
            END
            || jsonb_build_object(
              'phase', 'SOURCE_BUILDING',
              'last_source_build_candidate_id', p_candidate_id::text,
              'last_source_build_run_id', v_source_build_run_id::text,
              'last_source_change_seq', v_source_change_seq,
              'last_source_build_session_version', v_session_version,
              'last_source_rows_written', COALESCE(v_source_rows_written, 0),
              'last_current_source_row_count', COALESCE(v_current_source_row_count, 0),
              'last_source_rows_superseded', COALESCE(v_source_rows_superseded, 0),
              'last_source_build_jobs_superseded', COALESCE(v_reconciled_source_build_jobs_superseded, 0),
              'last_source_build_reconciliation', COALESCE(v_source_reconcile_result, '{}'::jsonb),
              'last_source_build_has_more', COALESCE(v_has_more, false),
              'last_source_build_at_utc', v_now::text,
              'status_text', 'Preparing payment source rows.',
              'next_recommended_action', CASE WHEN COALESCE(v_has_more, false) THEN 'BUILD_SOURCE_CHUNK' ELSE 'SEED_LINE_WORK_CHUNK' END
            )
            || jsonb_build_object(
              'last_source_build_collect_diagnostics', jsonb_strip_nulls(jsonb_build_object(
                'has_more', COALESCE(v_has_more, false),
                'source_page_count', COALESCE(v_source_page_count, 0),
                'source_remaining_after_cursor_count', COALESCE(v_source_remaining_after_cursor_count, 0),
                'collect_elapsed_ms', COALESCE(v_collect_elapsed_ms, 0),
                'fallback_used', COALESCE(v_fallback_used, false),
                'fallback_reason', v_fallback_reason,
                'candidate_filter_applied_early', COALESCE(v_candidate_filter_applied_early, false),
                'timesheet_filter_applied_early', COALESCE(v_timesheet_filter_applied_early, false),
                'large_aggregation_avoided', COALESCE(v_large_aggregation_avoided, false)
              )),
              'last_source_build_canonical_diagnostics', jsonb_strip_nulls(jsonb_build_object(
                'canonical_elapsed_ms', COALESCE(v_canonical_elapsed_ms, 0),
                'collect_called_inside_canonical', COALESCE(v_collect_called_inside_canonical, false)
              )),
              'last_source_build_timing', COALESCE(v_source_build_timing_json, '{}'::jsonb),
              'terminal_readiness_deferred', true,
              'terminal_readiness_deferred_to', 'pay_workbench_complete_job',
              'session_progress_update_locking', 'NOWAIT',
              'session_progress_update_applied', true
            ),
          progress_counter_version = COALESCE(session_update.progress_counter_version, 0) + 1,
          progress_updated_at_utc = v_now,
          updated_at_utc = v_now
      WHERE session_update.id = p_session_id
        AND UPPER(BTRIM(COALESCE(session_update.status, ''))) = 'OPEN'
        AND session_update.discarded_at_utc IS NULL
        AND COALESCE(session_update.version, 1) = v_session_version
        AND session_update.source_snapshot_run_id IS NOT DISTINCT FROM v_payload_snapshot_run_id
        AND session_update.session_signature IS NOT DISTINCT FROM v_initial_session_signature;

      GET DIAGNOSTICS v_session_progress_update_row_count = ROW_COUNT;
      v_session_progress_update_applied := COALESCE(v_session_progress_update_row_count, 0) > 0;
      v_session_progress_lock_skipped := COALESCE(v_session_progress_update_row_count, 0) <= 0;
    ELSE
      v_session_progress_update_applied := false;
      v_session_progress_lock_skipped := true;
    END IF;
  EXCEPTION
    WHEN lock_not_available THEN
      v_session_progress_update_applied := false;
      v_session_progress_lock_skipped := true;
      v_session_progress_update_row_count := 0;
  END;

  v_session_progress_update_elapsed_ms := round((extract(epoch from (clock_timestamp() - v_diag_phase_started_at)) * 1000.0)::numeric, 3);

  /*
   * A continuation is authorised only by the first page's durable
   * reconciliation attestation.  If the optional NOWAIT progress update could
   * not persist that marker, returning has_more=true would enqueue a
   * continuation that can never pass its attestation fence.  Roll the page
   * back and let the normal job retry rerun the first page after contention.
   */
  IF COALESCE(v_first_source_page, true)
     AND COALESCE(v_has_more, false)
     AND COALESCE(v_sync_completed, false)
     AND COALESCE(v_session_progress_update_applied, false) IS NOT TRUE THEN
    RAISE EXCEPTION
      'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_ATTESTATION_PERSIST_DEFERRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code',
                'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_ATTESTATION_PERSIST_DEFERRED',
              'session_id', p_session_id::text,
              'candidate_id', p_candidate_id::text,
              'session_version', v_session_version,
              'source_change_seq', v_source_change_seq,
              'source_build_run_id', v_source_build_run_id::text,
              'retry_safe', true,
              'message',
                'The first source page could not persist its continuation attestation because the session progress row was busy. The page was rolled back for a safe retry.'
            )::text;
  END IF;

  v_total_elapsed_ms := round((extract(epoch from (clock_timestamp() - v_started_at_utc)) * 1000.0)::numeric, 3);
  v_residual_elapsed_ms := round(GREATEST(COALESCE(v_total_elapsed_ms, 0) - COALESCE(v_collect_elapsed_ms, 0) - COALESCE(v_canonical_elapsed_ms, 0), 0), 3);
  v_residual_wall_elapsed_ms := round(GREATEST(COALESCE(v_total_elapsed_ms, 0) - COALESCE(v_collect_call_wall_elapsed_ms, 0) - COALESCE(v_canonical_call_wall_elapsed_ms, 0), 0), 3);
  v_residual_measured_elapsed_ms := round((
    COALESCE(v_budget_apply_elapsed_ms, 0)
    + COALESCE(v_initial_validation_elapsed_ms, 0)
    + COALESCE(v_overpayment_sync_elapsed_ms, 0)
    + COALESCE(v_preview_context_elapsed_ms, 0)
    + COALESCE(v_temp_transform_elapsed_ms, 0)
    + COALESCE(v_temp_counts_elapsed_ms, 0)
    + COALESCE(v_scope_timesheet_temp_elapsed_ms, 0)
    + COALESCE(v_final_revalidation_elapsed_ms, 0)
    + COALESCE(v_source_retire_elapsed_ms, 0)
    + COALESCE(v_source_upsert_elapsed_ms, 0)
    + COALESCE(v_source_write_guard_elapsed_ms, 0)
    + COALESCE(v_current_source_count_elapsed_ms, 0)
    + COALESCE(v_reconciliation_defer_elapsed_ms, 0)
    + COALESCE(v_next_cursor_elapsed_ms, 0)
    + COALESCE(v_scope_update_elapsed_ms, 0)
    + COALESCE(v_session_progress_update_elapsed_ms, 0)
  )::numeric, 3);
  v_residual_unattributed_elapsed_ms := round(GREATEST(COALESCE(v_residual_wall_elapsed_ms, 0) - COALESCE(v_residual_measured_elapsed_ms, 0), 0), 3);

  v_source_build_timing_json := jsonb_build_object(
    'timing_version', 'source_build_residual_v1',
    'complete', true,
    'source_build_run_id', v_source_build_run_id::text,
    'source_change_seq', v_source_change_seq,
    'session_version', v_session_version,
    'source_page_count', COALESCE(v_source_page_count, 0),
    'source_rows_written', COALESCE(v_source_rows_written, 0),
    'materialisable_source_line_count', COALESCE(v_materialisable_source_line_count, 0),
    'source_rows_seen', COALESCE(v_source_canonical_preview_line_count, 0),
    'elapsed_summary_ms', jsonb_build_object(
      'total', COALESCE(v_total_elapsed_ms, 0),
      'collect_reported', COALESCE(v_collect_elapsed_ms, 0),
      'collect_call_wall', COALESCE(v_collect_call_wall_elapsed_ms, 0),
      'canonical_reported', COALESCE(v_canonical_elapsed_ms, 0),
      'canonical_call_wall', COALESCE(v_canonical_call_wall_elapsed_ms, 0),
      'residual_reported_basis', COALESCE(v_residual_elapsed_ms, 0),
      'residual_wall_basis', COALESCE(v_residual_wall_elapsed_ms, 0),
      'residual_measured_components', COALESCE(v_residual_measured_elapsed_ms, 0),
      'residual_unattributed', COALESCE(v_residual_unattributed_elapsed_ms, 0)
    )
  )
  || jsonb_build_object(
    'phase_elapsed_ms', jsonb_build_object(
      'budget_apply', COALESCE(v_budget_apply_elapsed_ms, 0),
      'initial_validation', COALESCE(v_initial_validation_elapsed_ms, 0),
      'overpayment_sync', COALESCE(v_overpayment_sync_elapsed_ms, 0),
      'preview_context_build', COALESCE(v_preview_context_elapsed_ms, 0),
      'collect_call_wall', COALESCE(v_collect_call_wall_elapsed_ms, 0),
      'collect_reported', COALESCE(v_collect_elapsed_ms, 0),
      'canonical_call_wall', COALESCE(v_canonical_call_wall_elapsed_ms, 0),
      'canonical_reported', COALESCE(v_canonical_elapsed_ms, 0)
    )
    || jsonb_build_object(
      'temp_transform', COALESCE(v_temp_transform_elapsed_ms, 0),
      'temp_counts', COALESCE(v_temp_counts_elapsed_ms, 0),
      'scope_timesheet_temp', COALESCE(v_scope_timesheet_temp_elapsed_ms, 0),
      'final_revalidation', COALESCE(v_final_revalidation_elapsed_ms, 0),
      'source_retire', COALESCE(v_source_retire_elapsed_ms, 0),
      'source_upsert', COALESCE(v_source_upsert_elapsed_ms, 0),
      'source_write_guard', COALESCE(v_source_write_guard_elapsed_ms, 0),
      'current_source_count', COALESCE(v_current_source_count_elapsed_ms, 0)
    )
    || jsonb_build_object(
      'reconciliation_defer', COALESCE(v_reconciliation_defer_elapsed_ms, 0),
      'next_cursor', COALESCE(v_next_cursor_elapsed_ms, 0),
      'scope_update', COALESCE(v_scope_update_elapsed_ms, 0),
      'session_progress_update', COALESCE(v_session_progress_update_elapsed_ms, 0)
    )
  );

  -- A full-live candidate build is paged. Correction-chain members can fall on
  -- different pages, so validating/materialising the coupled residual before
  -- the terminal page would reject a temporarily incomplete (but valid) run.
  -- The terminal page still fails closed before line-work seeding if any
  -- required component is absent.
  IF COALESCE(v_has_more, false) IS NOT TRUE THEN
    PERFORM public._ctms_materialise_candidate_correction_residuals_v1(
      p_session_id,
      p_candidate_id,
      v_source_build_run_id,
      v_now
    );

    -- Canonical correction materialisation can legitimately retire every raw
    -- row written by a targeted refresh (for example, after the correction is
    -- frozen and settled).  The continuation decision must use the resulting
    -- carrier set, not the pre-materialisation count, otherwise line-work
    -- seeding is queued for a run that has no CURRENT rows.
    SELECT COUNT(*)::integer
    INTO v_current_source_row_count
    FROM public.banking_pay_workbench_candidate_source_lines AS post_materialisation_source_rows
    WHERE post_materialisation_source_rows.session_id = p_session_id
      AND post_materialisation_source_rows.candidate_id = p_candidate_id
      AND post_materialisation_source_rows.session_version = v_session_version
      AND post_materialisation_source_rows.source_change_seq = v_source_change_seq
      AND post_materialisation_source_rows.source_build_run_id = v_source_build_run_id
      AND post_materialisation_source_rows.status = 'CURRENT';
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'stage', 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
    'job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
    'session_id', p_session_id::text,
    'candidate_id', p_candidate_id::text,
    'session_version', v_session_version,
    'source_change_seq', v_source_change_seq,
    'source_build_run_id', v_source_build_run_id::text,
    'source_snapshot_run_id', v_session_row.source_snapshot_run_id::text,
    'session_signature', v_session_row.session_signature,
    'session_lock_scope', 'LOCKLESS_FINAL_REVALIDATION_OPTIONAL_NOWAIT_PROGRESS',
    'candidate_lock_scope', 'SESSION_SCOPE_ROW_FOR_UPDATE',
    'session_progress_update_applied', COALESCE(v_session_progress_update_applied, false),
    'session_progress_lock_skipped', COALESCE(v_session_progress_lock_skipped, false),
    'session_progress_update_row_count', COALESCE(v_session_progress_update_row_count, 0),
    'limit', v_limit,
    'refresh_scope_kind', v_actual_refresh_scope_kind,
    'requested_refresh_scope_kind', v_requested_refresh_scope_kind,
    'targeted_payload_received', COALESCE(v_targeted_payload_received, false),
    'targeted_timesheet_count', jsonb_array_length(COALESCE(v_collect_result->'targeted_timesheet_ids', v_targeted_timesheet_ids_json, '[]'::jsonb)),
    'linked_timesheet_count', jsonb_array_length(COALESCE(v_collect_result->'linked_timesheet_ids', v_linked_timesheet_ids_json, '[]'::jsonb))
  )
  || jsonb_build_object(
    'source_rows_written', COALESCE(v_source_rows_written, 0),
    'current_source_row_count', COALESCE(v_current_source_row_count, 0),
    'current_source_row_count_authoritative', COALESCE(v_has_more, false) IS NOT TRUE,
    'source_rows_superseded', COALESCE(v_source_rows_superseded, 0),
    'source_rows_superseded_by_reconciliation', COALESCE(v_reconciled_source_rows_superseded, 0),
    'source_build_failed_jobs_superseded', COALESCE(v_reconciled_source_build_jobs_superseded, 0),
    'source_build_reconciliation', COALESCE(v_source_reconcile_result, '{}'::jsonb),
    'source_rows_seen', COALESCE(v_source_canonical_preview_line_count, 0),
    'source_canonical_preview_line_count', COALESCE(v_source_canonical_preview_line_count, 0),
    'materialisable_source_line_count', COALESCE(v_materialisable_source_line_count, 0),
    'contract_rejected_count', COALESCE(v_contract_rejected_count, 0),
    'timesheets_seen', COALESCE(v_timesheets_seen, 0),
    'source_page_count', COALESCE(v_source_page_count, 0),
    'source_remaining_after_cursor_count', COALESCE(v_source_remaining_after_cursor_count, 0),
    'has_more', COALESCE(v_has_more, false),
    'next_cursor', v_next_cursor_json,
    'next_cursor_json', v_next_cursor_json,
    'cursor_in', COALESCE(v_source_cursor_in_json, v_cursor_json, '{}'::jsonb),
    'cursor_out', COALESCE(v_next_cursor_json, 'null'::jsonb),
    'cursor_advanced', COALESCE(v_cursor_advanced, false)
  )
  || jsonb_build_object(
    'fallback_used', COALESCE(v_fallback_used, false),
    'legacy_path_used', true,
    'fallback_from_delta', COALESCE(v_fallback_from_delta, false),
    'fallback_reason', COALESCE(v_delta_fallback_reason, v_fallback_reason),
    'projection_run_id', v_delta_projection_run_id_text,
    'projection_class', v_delta_projection_class,
    'candidate_filter_applied_early', COALESCE(v_candidate_filter_applied_early, false),
    'timesheet_filter_applied_early', COALESCE(v_timesheet_filter_applied_early, false),
    'large_aggregation_avoided', COALESCE(v_large_aggregation_avoided, false),
    'collect_called_inside_canonical', COALESCE(v_collect_called_inside_canonical, false),
    'overpayment_sync_completed', COALESCE(v_sync_completed, false),
    'overpayment_sync_attested', COALESCE(v_sync_attested, false),
    'overpayment_sync_attestation', COALESCE(v_sync_attestation, '{}'::jsonb),
    'overpayment_sync_result', COALESCE(v_sync_result, '{}'::jsonb),
    'collect_elapsed_ms', COALESCE(v_collect_elapsed_ms, 0),
    'canonical_elapsed_ms', COALESCE(v_canonical_elapsed_ms, 0),
    'classifier_elapsed_ms', COALESCE(v_classifier_elapsed_ms, 0),
    'classifier_timing_source', 'canonical_elapsed_ms',
    'total_elapsed_ms', COALESCE(v_total_elapsed_ms, 0),
    'collect_call_wall_elapsed_ms', COALESCE(v_collect_call_wall_elapsed_ms, 0),
    'canonical_call_wall_elapsed_ms', COALESCE(v_canonical_call_wall_elapsed_ms, 0),
    'source_build_residual_elapsed_ms', COALESCE(v_residual_elapsed_ms, 0),
    'source_build_residual_wall_elapsed_ms', COALESCE(v_residual_wall_elapsed_ms, 0),
    'source_build_residual_measured_elapsed_ms', COALESCE(v_residual_measured_elapsed_ms, 0),
    'source_build_residual_unattributed_elapsed_ms', COALESCE(v_residual_unattributed_elapsed_ms, 0),
    'source_build_temp_transform_elapsed_ms', COALESCE(v_temp_transform_elapsed_ms, 0),
    'source_build_source_upsert_elapsed_ms', COALESCE(v_source_upsert_elapsed_ms, 0),
    'source_build_session_progress_update_elapsed_ms', COALESCE(v_session_progress_update_elapsed_ms, 0),
    'source_build_timing', COALESCE(v_source_build_timing_json, '{}'::jsonb),
    'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
  )
  || jsonb_build_object(
    'source_build_complete', COALESCE(v_has_more, false) IS NOT TRUE AND COALESCE(v_sync_attested, false),
    'pending', COALESCE(v_has_more, false) OR COALESCE(v_sync_attested, false) IS NOT TRUE,
    'ready', COALESCE(v_has_more, false) IS NOT TRUE AND COALESCE(v_sync_attested, false),
    'collect_result', COALESCE(v_collect_result, '{}'::jsonb),
    'canonical_result', COALESCE(v_canonical_result, '{}'::jsonb),
    'source_build_diagnostics', jsonb_build_object(
      'collect', COALESCE(v_collect_diagnostics_json, '{}'::jsonb),
      'canonical', COALESCE(v_canonical_diagnostics_json, '{}'::jsonb),
      'legacy_path_used', true,
      'fallback_from_delta', COALESCE(v_fallback_from_delta, false),
      'fallback_reason', COALESCE(v_delta_fallback_reason, v_fallback_reason),
      'projection_run_id', v_delta_projection_run_id_text,
      'projection_class', v_delta_projection_class,
      'source_table', 'public.banking_pay_workbench_candidate_source_lines',
      'session_lock_scope', 'LOCKLESS_FINAL_REVALIDATION_OPTIONAL_NOWAIT_PROGRESS',
      'candidate_lock_scope', 'SESSION_SCOPE_ROW_FOR_UPDATE',
      'session_progress_update_applied', COALESCE(v_session_progress_update_applied, false),
      'session_progress_lock_skipped', COALESCE(v_session_progress_lock_skipped, false),
      'overpayment_sync_attestation', COALESCE(v_sync_attestation, '{}'::jsonb),
      'timing', COALESCE(v_source_build_timing_json, '{}'::jsonb),
      'source_build_reconciliation_deferred_to_complete_job', COALESCE(v_current_source_row_count, 0) > 0,
      'source_row_identity', jsonb_build_object(
        'session_id', p_session_id::text,
        'candidate_id', p_candidate_id::text,
        'session_version', v_session_version,
        'source_change_seq', v_source_change_seq,
        'source_build_run_id', v_source_build_run_id::text
      )
    ),
    'dependency_closure', COALESCE(v_dependency_closure_json, '{}'::jsonb),
    'finance_case_ids', COALESCE(v_finance_case_ids_json, '[]'::jsonb)
  );
END;
$function$;

ALTER FUNCTION public.pay_workbench_candidate_source_build_chunk(p_session_id uuid, p_candidate_id uuid, p_cursor_json jsonb, p_payload_json jsonb, p_limit integer) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.pay_workbench_candidate_source_build_chunk(p_session_id uuid, p_candidate_id uuid, p_cursor_json jsonb, p_payload_json jsonb, p_limit integer) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.pay_workbench_candidate_source_build_chunk(p_session_id uuid, p_candidate_id uuid, p_cursor_json jsonb, p_payload_json jsonb, p_limit integer) TO postgres;
GRANT EXECUTE ON FUNCTION public.pay_workbench_candidate_source_build_chunk(p_session_id uuid, p_candidate_id uuid, p_cursor_json jsonb, p_payload_json jsonb, p_limit integer) TO service_role;

-- -----------------------------------------------------------------------------
-- public.pay_sync_overpayments_from_preview(p_pay_date date, p_week_ending_cutoff date, p_actor_user_id uuid, p_pay_channel_scope text, p_candidate_ids uuid[], p_mismatch_choices jsonb, p_client_filter_single uuid, p_force_include_timesheet_ids uuid[], p_exclude_timesheet_ids uuid[])
-- Installed pg_get_functiondef MD5: 0afc902dc40364a6ab500935334ef565
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.pay_sync_overpayments_from_preview(p_pay_date date, p_week_ending_cutoff date, p_actor_user_id uuid, p_pay_channel_scope text, p_candidate_ids uuid[], p_mismatch_choices jsonb DEFAULT '{}'::jsonb, p_client_filter_single uuid DEFAULT NULL::uuid, p_force_include_timesheet_ids uuid[] DEFAULT NULL::uuid[], p_exclude_timesheet_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET "plpgsql_check.mode" TO 'disabled'
 SET "plpgsql_check.profiler" TO 'off'
 SET "plpgsql_check.tracer" TO 'off'
 SET "plpgsql_check.constants_tracing" TO 'off'
 SET "plpgsql_check.cursors_leaks" TO 'off'
 SET "plpgsql_check.strict_cursors_leaks" TO 'off'
 SET "plpgsql_check.fatal_errors" TO 'off'
AS $function$
declare
  v_scope text := upper(btrim(coalesce(p_pay_channel_scope, '')));
  v_timesheet_case_count int := 0;
  v_cases_inserted int := 0;
  v_cases_touched int := 0;
  v_cases_amended int := 0;
  v_cases_reopened int := 0;
  v_cases_cleared int := 0;
  v_case_update_count int := 0;
  v_overpayment_case_count int := 0;
  v_underpayment_case_count int := 0;
  v_case_candidates_json jsonb := '[]'::jsonb;
  v_overpayment_json jsonb := '[]'::jsonb;
  v_underpayment_json jsonb := '[]'::jsonb;
  v_preview_decisions_json jsonb := '{}'::jsonb;
  v_preview_context_json jsonb := '{}'::jsonb;
  v_preview_baseline_json jsonb := '{}'::jsonb;
  v_preview_candidate_row_json jsonb := '{}'::jsonb;
  v_preview_scope_context_json jsonb := '{}'::jsonb;
  v_preview_scope_candidate_ids_json jsonb := '[]'::jsonb;
  v_preview_candidate_loop_id uuid := NULL::uuid;
  v_preview_candidate_count integer := 0;
  v_requested_candidate_count integer := 0;
  v_missing_candidate_count integer := 0;
  v_missing_candidate_ids_json jsonb := '[]'::jsonb;
  v_authoritative_timesheet_scope_requested boolean := false;
  v_authoritative_timesheet_scope boolean := false;
  v_explicit_empty_timesheet_scope boolean := false;
  v_preview_scope_strategy text := 'CANDIDATE_FULL_LIVE';
  v_sync_authority_token text := NULL::text;
  v_current_sync_authority_token text := NULL::text;
  v_workbench_session_id_text text := NULL::text;
  v_source_build_run_id_text text := NULL::text;
  v_session_version_text text := NULL::text;
  v_workbench_session_id uuid := NULL::uuid;
  v_source_build_run_id uuid := NULL::uuid;
  v_workbench_session_version bigint := NULL::bigint;
  v_authoritative_candidate_id uuid := NULL::uuid;
  v_existing_active_reserved_amount numeric(12,2) := 0;
  v_effective_case_amount_ex numeric(12,2);
  v_active_reservation_protection_applied boolean := false;
  v_correction_rewrite_result jsonb := '{}'::jsonb;
  v_resolution_pending_member_ids uuid[] := array[]::uuid[];
  v_resolution_pending_root_ids uuid[] := array[]::uuid[];

  v_target_case_row record;
  v_existing_case_row record;
  v_case_before_json jsonb;
  v_case_after_json jsonb;
  v_components_sync_result jsonb;
  v_component_case_outstanding_amount numeric(12,2) := 0;
  v_component_open_remaining_total numeric(12,2) := 0;
  v_component_case_mismatch_amount numeric(12,2) := 0;
  v_existing_recovered_amount numeric(12,2);
  v_new_outstanding_amount numeric(12,2);
  v_target_amount_is_authoritative_outstanding boolean := false;
  v_selected_finance_case_id uuid;
  v_selected_event_type text;
  v_selected_reason text;
  v_selected_note text;
  v_open_case_candidate record;
  v_target_case_amount_ex numeric(12,2);
  v_case_taxability public.pay_finance_taxability_enum := NULL;
  v_case_routing_kind public.pay_finance_routing_kind_enum := NULL;
  v_synced_case_taxability public.pay_finance_taxability_enum := NULL;
  v_synced_case_routing_kind public.pay_finance_routing_kind_enum := NULL;
  v_synced_before_taxability public.pay_finance_taxability_enum := NULL;
  v_synced_before_routing_kind public.pay_finance_routing_kind_enum := NULL;
  v_case_metadata_component_count integer := 0;
  v_synced_open_component_count integer := 0;
  v_taxability_event_before_json jsonb;
  v_taxability_event_after_json jsonb;
  v_authoritative_negative_component_count integer := 0;
  v_authoritative_negative_component_digest text := NULL::text;
  v_expected_negative_component_digest text := NULL::text;
  v_authoritative_settled_baseline_digest text := NULL::text;
  v_expected_settled_baseline_digest text := NULL::text;
  v_authoritative_session_valid boolean := false;
begin
  declare
    v_correction_candidate uuid;
    v_residuals jsonb;
    v_candidate_pending_member_ids uuid[] := array[]::uuid[];
    v_candidate_pending_root_ids uuid[] := array[]::uuid[];
  begin
    foreach v_correction_candidate in array coalesce(p_candidate_ids,array[]::uuid[]) loop
      v_residuals:=public._ctms_candidate_correction_residuals_v1(null::uuid,v_correction_candidate,null::uuid,'PAY_SYNC_OVERPAYMENTS');

      v_candidate_pending_member_ids := ARRAY(
        select distinct member_id.value::uuid
        from jsonb_array_elements(v_residuals) residual(value)
        cross join lateral jsonb_array_elements_text(
          coalesce(residual.value->'member_timesheet_ids', '[]'::jsonb)
        ) member_id(value)
        where coalesce((residual.value->>'draftable')::boolean, false) is not true
          and coalesce(residual.value->>'block_code', '')
                = 'CORRECTION_CHAIN_PAY_METHOD_RESOLUTION_REQUIRED'
          and coalesce((residual.value->>'unresolved_count')::integer, 0) > 0
          and coalesce((residual.value->>'reservation_overrun_count')::integer, 0) = 0
          and coalesce((residual.value->>'component_count')::integer, 0) > 0
          and member_id.value
                ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        order by member_id.value::uuid
      );

      v_candidate_pending_root_ids := ARRAY(
        select distinct (residual.value->>'root_timesheet_id')::uuid
        from jsonb_array_elements(v_residuals) residual(value)
        where coalesce((residual.value->>'draftable')::boolean, false) is not true
          and coalesce(residual.value->>'block_code', '')
                = 'CORRECTION_CHAIN_PAY_METHOD_RESOLUTION_REQUIRED'
          and coalesce((residual.value->>'unresolved_count')::integer, 0) > 0
          and coalesce((residual.value->>'reservation_overrun_count')::integer, 0) = 0
          and coalesce((residual.value->>'component_count')::integer, 0) > 0
          and coalesce(residual.value->>'root_timesheet_id', '')
                ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        order by (residual.value->>'root_timesheet_id')::uuid
      );

      v_resolution_pending_member_ids := ARRAY(
        select distinct pending_id
        from unnest(
          coalesce(v_resolution_pending_member_ids, array[]::uuid[])
          || coalesce(v_candidate_pending_member_ids, array[]::uuid[])
        ) pending_id
        order by pending_id
      );

      v_resolution_pending_root_ids := ARRAY(
        select distinct pending_id
        from unnest(
          coalesce(v_resolution_pending_root_ids, array[]::uuid[])
          || coalesce(v_candidate_pending_root_ids, array[]::uuid[])
        ) pending_id
        order by pending_id
      );

      if exists(
        select 1
        from jsonb_array_elements(v_residuals) r
        where coalesce((r->>'draftable')::boolean,false) is not true
          and not (
            coalesce(r->>'block_code','')
              = 'CORRECTION_CHAIN_PAY_METHOD_RESOLUTION_REQUIRED'
            and coalesce((r->>'unresolved_count')::integer,0) > 0
            and coalesce((r->>'reservation_overrun_count')::integer,0) = 0
            and coalesce((r->>'component_count')::integer,0) > 0
          )
          and not (
            coalesce(r->>'block_code','') = 'CORRECTION_CHAIN_RESERVATION_OVERRUN'
            and coalesce((r->>'reservation_overrun_count')::integer,0) > 0
            and exists (
              select 1
              from public.pay_batch_items active_batch_item
              join public.pay_batch_candidates active_batch_candidate
                on active_batch_candidate.id = active_batch_item.pay_batch_candidate_id
              join public.pay_batches active_batch
                on active_batch.id = active_batch_candidate.pay_batch_id
              where active_batch_candidate.candidate_id = v_correction_candidate
                and coalesce(active_batch_item.is_voided, false) is not true
                and active_batch.cancelled_at_utc is null
                and upper(btrim(coalesce(active_batch.status, ''))) in (
                  'DRAFT', 'DRAFT_CREATED', 'READY', 'WAITING_BANK_CONFIRM',
                  'PARTIAL', 'FAILED', 'BLOCKED_FUNDS', 'SCHEDULED', 'EXECUTING',
                  'AWAITING_AUTHORISATION', 'AUTHORISED_FOR_PAYMENT'
                )
                and coalesce(
                  active_batch_item.frozen_component_snapshot_json->>'correction_root_id',
                  active_batch_item.frozen_resolution_payload_json->>'correction_root_id',
                  ''
                ) = coalesce(r->>'root_timesheet_id','')
            )
          )
          and (
            coalesce(array_length(p_force_include_timesheet_ids,1),0)=0
            or exists (
              select 1
              from jsonb_array_elements_text(
                coalesce(r->'member_timesheet_ids','[]'::jsonb)
              ) member_id(value)
              where member_id.value::uuid
                    = any(coalesce(p_force_include_timesheet_ids,array[]::uuid[]))
            )
          )
      ) then
        raise exception 'CORRECTION_RESIDUAL_NOT_READY_FOR_OVERPAYMENT_SYNC' using errcode='P0001',detail=v_residuals::text;
      end if;
    end loop;
  end;
  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAY_SYNC_OVERPAYMENTS_FROM_PREVIEW_START',
    jsonb_build_object(
      'pay_date', p_pay_date,
      'week_ending_cutoff', p_week_ending_cutoff,
      'pay_channel_scope', p_pay_channel_scope,
      'candidate_count', COALESCE(array_length(p_candidate_ids, 1), 0),
      'force_include_timesheet_count', COALESCE(array_length(p_force_include_timesheet_ids, 1), 0),
      'exclude_timesheet_count', COALESCE(array_length(p_exclude_timesheet_ids, 1), 0)
    ),
    'pay_sync_overpayments',
    COALESCE(p_pay_date::text, 'NO_PAY_DATE'),
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  if p_pay_date is null then
    raise exception 'pay_date is required';
  end if;

  if p_week_ending_cutoff is null then
    raise exception 'week_ending_cutoff is required';
  end if;

  if p_actor_user_id is null then
    raise exception 'actor_user_id is required';
  end if;

  if v_scope not in ('PAYE', 'UMBRELLA') then
    raise exception 'Invalid pay_channel_scope (expected PAYE or UMBRELLA)';
  end if;

  v_requested_candidate_count := COALESCE(array_length(p_candidate_ids, 1), 0);

  v_authoritative_timesheet_scope_requested := LOWER(BTRIM(COALESCE(
    p_mismatch_choices->>'overpayment_sync_authoritative_timesheet_scope',
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');

  v_sync_authority_token := NULLIF(BTRIM(COALESCE(
    p_mismatch_choices->>'overpayment_sync_authority_token',
    ''
  )), '');
  v_current_sync_authority_token := NULLIF(BTRIM(COALESCE(
    current_setting('cloudtms.pay_workbench_overpayment_sync_token', true),
    ''
  )), '');

  IF COALESCE(v_authoritative_timesheet_scope_requested, false)
     AND (
       p_force_include_timesheet_ids IS NULL
       OR v_sync_authority_token IS NULL
       OR v_current_sync_authority_token IS NULL
       OR v_sync_authority_token IS DISTINCT FROM v_current_sync_authority_token
     ) THEN
    RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_AUTHORITY_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_AUTHORITY_INVALID',
              'message', 'Authoritative Timesheet scope is internal Workbench authority and requires the matching transaction-local source-build token.',
              'force_include_argument_supplied', p_force_include_timesheet_ids IS NOT NULL,
              'authority_token_supplied', v_sync_authority_token IS NOT NULL,
              'transaction_authority_present', v_current_sync_authority_token IS NOT NULL
            )::text;
  END IF;

  v_authoritative_timesheet_scope := COALESCE(v_authoritative_timesheet_scope_requested, false)
    AND p_force_include_timesheet_ids IS NOT NULL
    AND v_sync_authority_token IS NOT NULL
    AND v_sync_authority_token = v_current_sync_authority_token;

  v_explicit_empty_timesheet_scope := COALESCE(v_authoritative_timesheet_scope, false)
    AND COALESCE(array_length(p_force_include_timesheet_ids, 1), 0) = 0;

  v_preview_scope_strategy := CASE
    WHEN COALESCE(v_authoritative_timesheet_scope, false)
     AND COALESCE(array_length(p_force_include_timesheet_ids, 1), 0) > 0
      THEN 'TARGETED_TIMESHEETS'
    WHEN COALESCE(v_authoritative_timesheet_scope, false)
      THEN 'AUTHORITATIVE_EMPTY'
    ELSE 'CANDIDATE_FULL_LIVE'
  END;

  v_preview_decisions_json := (
      CASE
        WHEN jsonb_typeof(COALESCE(p_mismatch_choices, '{}'::jsonb)) = 'object'
          THEN COALESCE(p_mismatch_choices, '{}'::jsonb)
        ELSE '{}'::jsonb
      END
      - 'refresh_scope_kind'
      - 'targeted_timesheet_ids'
      - 'targeted_timesheet_ids_requested'
      - 'linked_timesheet_ids'
      - 'linked_timesheet_ids_requested'
      - 'source_build_allow_full_fallback'
      - 'overpayment_sync_authority_token'
      - 'overpayment_sync_authoritative_timesheet_scope'
      - 'authoritative_timesheet_scope'
      - 'exact_timesheet_scope'
      - 'workbench_session_id'
      - 'source_build_run_id'
      - 'source_change_seq'
      - 'session_version'
      - 'overpayment_sync_scope_digest'
      - 'overpayment_sync_negative_component_digest'
      - 'overpayment_sync_settled_baseline_digest'
      - 'policy_x_authority_scope'
    )
    || jsonb_build_object(
      'overpayment_sync_mode', true,
      'emit_raw_overpayment_components', true,
      'preview_context_mode', CASE WHEN v_requested_candidate_count = 1 THEN 'FULL_COMPAT' ELSE 'PAGE' END,
      'scope_limit', LEAST(GREATEST(COALESCE(v_requested_candidate_count, 1), 1), 100),
      'pay_channel_scope', v_scope,
      'candidate_ids', COALESCE(to_jsonb(p_candidate_ids), '[]'::jsonb),
      'force_include_timesheet_ids', COALESCE(to_jsonb(p_force_include_timesheet_ids), '[]'::jsonb),
      'exclude_timesheet_ids', COALESCE(to_jsonb(p_exclude_timesheet_ids), '[]'::jsonb),
      'overpayment_sync_preview_scope_strategy', v_preview_scope_strategy
    )
    || CASE
      WHEN v_preview_scope_strategy = 'TARGETED_TIMESHEETS' THEN
        jsonb_build_object(
          'refresh_scope_kind', 'TARGETED_TIMESHEETS',
          'targeted_timesheet_ids', COALESCE(to_jsonb(p_force_include_timesheet_ids), '[]'::jsonb),
          'targeted_timesheet_ids_requested', COALESCE(to_jsonb(p_force_include_timesheet_ids), '[]'::jsonb),
          'linked_timesheet_ids', '[]'::jsonb,
          'linked_timesheet_ids_requested', '[]'::jsonb,
          'source_build_allow_full_fallback', false,
          'overpayment_sync_explicit_empty_scope', false
        )
      ELSE
        jsonb_build_object(
          'refresh_scope_kind', 'CANDIDATE_FULL_LIVE',
          'targeted_timesheet_ids', '[]'::jsonb,
          'targeted_timesheet_ids_requested', '[]'::jsonb,
          'linked_timesheet_ids', '[]'::jsonb,
          'linked_timesheet_ids_requested', '[]'::jsonb,
          'overpayment_sync_explicit_empty_scope', COALESCE(v_explicit_empty_timesheet_scope, false)
        )
    END
    || CASE
      WHEN COALESCE(v_authoritative_timesheet_scope, false) THEN
        jsonb_build_object(
          'workbench_source_build_mode', true,
          'source_build_mode', true,
          'job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
          'overpayment_sync_authority_token', v_sync_authority_token
        )
      ELSE '{}'::jsonb
    END;


  IF EXISTS (
    SELECT 1
    FROM unnest(COALESCE(p_candidate_ids, ARRAY[]::uuid[])) AS requested_candidate(candidate_id)
    WHERE requested_candidate.candidate_id IS NULL
  ) THEN
    RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_CANDIDATE_ID_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_SYNC_OVERPAYMENTS_CANDIDATE_ID_INVALID',
              'message', 'candidate_ids must not contain null values.'
            )::text;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM unnest(COALESCE(p_force_include_timesheet_ids, ARRAY[]::uuid[])) AS included_timesheet(timesheet_id)
    WHERE included_timesheet.timesheet_id IS NULL
  ) THEN
    RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_FORCE_INCLUDE_TIMESHEET_ID_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_SYNC_OVERPAYMENTS_FORCE_INCLUDE_TIMESHEET_ID_INVALID',
              'message', 'force_include_timesheet_ids must not contain null values.'
            )::text;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM unnest(COALESCE(p_exclude_timesheet_ids, ARRAY[]::uuid[])) AS excluded_timesheet(timesheet_id)
    WHERE excluded_timesheet.timesheet_id IS NULL
  ) THEN
    RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_EXCLUDE_TIMESHEET_ID_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_SYNC_OVERPAYMENTS_EXCLUDE_TIMESHEET_ID_INVALID',
              'message', 'exclude_timesheet_ids must not contain null values.'
            )::text;
  END IF;

  IF v_requested_candidate_count > 100 THEN
    RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_CANDIDATE_SCOPE_TOO_LARGE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_SYNC_OVERPAYMENTS_CANDIDATE_SCOPE_TOO_LARGE',
              'candidate_count', v_requested_candidate_count,
              'limit', 100,
              'message', 'Supply at most 100 explicit candidate IDs per bounded reconciliation call.'
            )::text;
  END IF;

  IF COALESCE(v_authoritative_timesheet_scope, false) THEN
    IF v_requested_candidate_count IS DISTINCT FROM 1 THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_SINGLE_CANDIDATE_REQUIRED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_SINGLE_CANDIDATE_REQUIRED',
                'candidate_count', v_requested_candidate_count
              )::text;
    END IF;

    v_workbench_session_id_text := NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'workbench_session_id', '')), '');
    v_source_build_run_id_text := NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'source_build_run_id', '')), '');
    v_session_version_text := NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'session_version', '')), '');

    IF v_workbench_session_id_text IS NULL
       OR v_workbench_session_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       OR v_source_build_run_id_text IS NULL
       OR v_source_build_run_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       OR v_session_version_text IS NULL
       OR v_session_version_text !~ '^[0-9]{1,18}$'
       OR NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'overpayment_sync_scope_digest', '')), '') IS NULL
       OR NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'overpayment_sync_negative_component_digest', '')), '') IS NULL
       OR NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'overpayment_sync_settled_baseline_digest', '')), '') IS NULL
       OR UPPER(BTRIM(COALESCE(p_mismatch_choices->>'policy_x_authority_scope', ''))) <> 'PRE_DRAFT_LIVE_TRUTH' THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_METADATA_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_METADATA_INVALID',
                'workbench_session_id', v_workbench_session_id_text,
                'source_build_run_id', v_source_build_run_id_text,
                'session_version', v_session_version_text,
                'policy_x_authority_scope', NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'policy_x_authority_scope', '')), '')
              )::text;
    END IF;

    v_workbench_session_id := v_workbench_session_id_text::uuid;
    v_source_build_run_id := v_source_build_run_id_text::uuid;
    v_workbench_session_version := v_session_version_text::bigint;

    v_authoritative_candidate_id := p_candidate_ids[1];

    -- Supabase preloads plpgsql_check with fatal nested-statement inspection.
    -- Keep this predicate in its bounded owner-only SQL helper so the deeply
    -- nested PL/pgSQL frame does not corrupt pldbgapi2's parent stack.
    v_authoritative_session_valid :=
      public._pay_workbench_authoritative_scope_valid_v1(
      v_workbench_session_id,
      v_authoritative_candidate_id,
      v_workbench_session_version,
      p_actor_user_id,
      p_pay_date,
      p_week_ending_cutoff,
      v_scope
    );

    IF COALESCE(v_authoritative_session_valid, false) IS NOT TRUE THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_SESSION_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_SESSION_INVALID',
                'workbench_session_id', v_workbench_session_id::text,
                'source_build_run_id', v_source_build_run_id::text,
                'session_version', v_workbench_session_version,
                'candidate_id', v_authoritative_candidate_id::text,
                'pay_channel_scope', v_scope
              )::text;
    END IF;

    IF EXISTS (
      WITH candidate_authority_seed_timesheets AS (
        SELECT authoritative_tsfin.timesheet_id
        FROM public.timesheets_financials AS authoritative_tsfin
        WHERE authoritative_tsfin.candidate_id = v_authoritative_candidate_id
          AND authoritative_tsfin.timesheet_id IS NOT NULL

        UNION

        SELECT authoritative_case.linked_timesheet_id
        FROM public.pay_advances AS authoritative_case
        WHERE authoritative_case.candidate_id = v_authoritative_candidate_id
          AND authoritative_case.linked_timesheet_id IS NOT NULL

        UNION

        SELECT authoritative_component.linked_timesheet_id
        FROM public.pay_finance_case_components AS authoritative_component
        WHERE authoritative_component.candidate_id = v_authoritative_candidate_id
          AND authoritative_component.linked_timesheet_id IS NOT NULL

        UNION

        SELECT authoritative_override.timesheet_id
        FROM public.timesheet_payment_overrides AS authoritative_override
        WHERE authoritative_override.candidate_id = v_authoritative_candidate_id
          AND authoritative_override.timesheet_id IS NOT NULL

        UNION

        SELECT authoritative_adjustment.timesheet_id
        FROM public.ts_pay_adjustments AS authoritative_adjustment
        WHERE authoritative_adjustment.candidate_id = v_authoritative_candidate_id
          AND authoritative_adjustment.timesheet_id IS NOT NULL

        UNION

        SELECT authoritative_snooze.timesheet_id
        FROM public.pay_item_snoozes AS authoritative_snooze
        WHERE authoritative_snooze.candidate_id = v_authoritative_candidate_id
          AND authoritative_snooze.timesheet_id IS NOT NULL
          AND authoritative_snooze.cleared_at_utc IS NULL
          AND authoritative_snooze.cancelled_at_utc IS NULL

        UNION

        SELECT authoritative_batch_item.timesheet_id
        FROM public.pay_batch_candidates AS authoritative_batch_candidate
        JOIN public.pay_batch_items AS authoritative_batch_item
          ON authoritative_batch_item.pay_batch_candidate_id = authoritative_batch_candidate.id
        WHERE authoritative_batch_candidate.candidate_id = v_authoritative_candidate_id
          AND authoritative_batch_item.timesheet_id IS NOT NULL
          AND COALESCE(authoritative_batch_item.is_voided, false) IS NOT TRUE

        UNION

        SELECT authoritative_correction.timesheet_id
        FROM public.pay_payment_correction_items AS authoritative_correction
        WHERE authoritative_correction.candidate_id = v_authoritative_candidate_id
          AND authoritative_correction.timesheet_id IS NOT NULL
          AND UPPER(BTRIM(COALESCE(authoritative_correction.status, ''))) = 'APPLIED'
      ), candidate_authority_seed_array AS (
        SELECT COALESCE(
          ARRAY_AGG(
            DISTINCT candidate_authority_seed_timesheets.timesheet_id
            ORDER BY candidate_authority_seed_timesheets.timesheet_id
          ),
          ARRAY[]::uuid[]
        ) AS timesheet_ids
        FROM candidate_authority_seed_timesheets
      ), candidate_authority_timesheets AS (
        SELECT candidate_authority_seed_timesheets.timesheet_id
        FROM candidate_authority_seed_timesheets

        UNION

        SELECT authority_rotation.canonical_timesheet_id
        FROM candidate_authority_seed_array
        JOIN public._pay_timesheet_rotation_scope(
          candidate_authority_seed_array.timesheet_ids
        ) AS authority_rotation
          ON true
        WHERE authority_rotation.canonical_timesheet_id IS NOT NULL

        UNION

        SELECT authority_rotation.family_timesheet_id
        FROM candidate_authority_seed_array
        JOIN public._pay_timesheet_rotation_scope(
          candidate_authority_seed_array.timesheet_ids
        ) AS authority_rotation
          ON true
        WHERE authority_rotation.family_timesheet_id IS NOT NULL
      )
      SELECT 1
      FROM unnest(COALESCE(p_force_include_timesheet_ids, ARRAY[]::uuid[])) AS authoritative_timesheet(timesheet_id)
      WHERE NOT EXISTS (
        SELECT 1
        FROM candidate_authority_timesheets AS candidate_authority
        WHERE candidate_authority.timesheet_id = authoritative_timesheet.timesheet_id
      )
    ) THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_CANDIDATE_MISMATCH'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_CANDIDATE_MISMATCH',
                'candidate_id', v_authoritative_candidate_id::text,
                'scope_timesheet_ids', COALESCE(to_jsonb(p_force_include_timesheet_ids), '[]'::jsonb)
              )::text;
    END IF;
  END IF;

  IF COALESCE(v_explicit_empty_timesheet_scope, false) THEN
    PERFORM public._imp_debug_audit(
      p_actor_user_id,
      'PAY_SYNC_OVERPAYMENTS_FROM_PREVIEW_RESULT',
      jsonb_build_object(
        'pay_channel_scope', v_scope,
        'authoritative_timesheet_scope', true,
        'explicit_empty_timesheet_scope', true,
        'preview_scope_strategy', v_preview_scope_strategy,
        'candidate_count', v_requested_candidate_count,
        'cases_inserted', 0,
        'cases_touched', 0,
        'cases_amended', 0,
        'cases_reopened', 0,
        'cases_cleared', 0
      ),
      'pay_sync_overpayments',
      COALESCE(p_pay_date::text, 'NO_PAY_DATE'),
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );

    RETURN jsonb_build_object(
      'ok', true,
      'pay_channel_scope', v_scope,
      'authoritative_timesheet_scope', true,
      'explicit_empty_timesheet_scope', true,
      'preview_scope_strategy', v_preview_scope_strategy,
      'scope_timesheet_ids', '[]'::jsonb,
      'requested_candidate_count', v_requested_candidate_count,
      'preview_candidate_count', 0,
      'preview_candidate_coverage_complete', true,
      'negative_preview_timesheets_count', 0,
      'negative_preview_timesheets', '[]'::jsonb,
      'underpayment_case_count', 0,
      'underpayment_cases', '[]'::jsonb,
      'timesheet_finance_case_candidates_count', 0,
      'timesheet_finance_case_candidates', '[]'::jsonb,
      'cases_inserted', 0,
      'cases_touched', 0,
      'cases_amended', 0,
      'cases_reopened', 0,
      'cases_cleared', 0
    );
  END IF;

  create temporary table if not exists pg_temp.tmp_sync_timesheet_case_candidates (
    candidate_id uuid not null,
    timesheet_id uuid not null,
    client_id uuid null,
    linked_shift_date date null,
    corrected_amount_ex numeric(12,2) not null,
    baseline_signature text null,
    candidate_pay_method text not null,
    case_is_blocked boolean not null,
    needs_lifecycle_tracking boolean not null default false,
    overpayment_amount_ex numeric(12,2) not null,
    underpayment_amount_ex numeric(12,2) not null,
    desired_case_type public.pay_finance_case_type_enum null,
    desired_advance_kind public.pay_advance_kind_enum null,
    desired_reason public.pay_advance_reason_enum null,
    source_original_paid_amount numeric(12,2) null,
    source_corrected_paid_amount numeric(12,2) null,
    components_sync_json jsonb not null default '[]'::jsonb,
    primary key (candidate_id, timesheet_id)
  ) on commit drop;

  create temporary table if not exists pg_temp.tmp_sync_case_links (
    candidate_id uuid not null,
    timesheet_id uuid not null,
    finance_case_id uuid not null,
    desired_case_type public.pay_finance_case_type_enum not null,
    source_original_paid_amount numeric(12,2) not null,
    source_corrected_paid_amount numeric(12,2) not null,
    case_amount_ex numeric(12,2) not null,
    linked_shift_date date null,
    baseline_signature text null,
    components_sync_json jsonb not null,
    primary key (candidate_id, timesheet_id)
  ) on commit drop;

  create temporary table if not exists pg_temp.tmp_sync_case_clears (
    finance_case_id uuid not null primary key,
    candidate_id uuid not null,
    timesheet_id uuid not null,
    old_case_type public.pay_finance_case_type_enum not null,
    old_original_amount numeric(12,2) not null,
    old_outstanding_amount numeric(12,2) not null,
    old_source_original_paid_amount numeric(12,2) null,
    old_source_corrected_paid_amount numeric(12,2) null,
    old_linked_shift_date date null,
    old_baseline_signature text null
  ) on commit drop;

  create temporary table if not exists pg_temp.tmp_sync_preview_candidates (
    candidate_id uuid not null primary key,
    candidate_json jsonb not null
  ) on commit drop;

  create temporary table if not exists pg_temp.tmp_sync_authoritative_negative_components (
    timesheet_id uuid not null,
    key_type text not null,
    key_value text not null,
    truth_ex_vat numeric(12,2) not null,
    baseline_ex_vat numeric(12,2) not null,
    reserved_ex_vat numeric(12,2) not null,
    outstanding_ex_vat numeric(12,2) not null,
    baseline_signature text null,
    primary key (timesheet_id, key_type, key_value)
  ) on commit drop;

  create temporary table if not exists pg_temp.tmp_sync_raw_negative_timesheet_rows (
    candidate_id uuid not null,
    timesheet_id uuid not null,
    client_id uuid null,
    candidate_pay_method text not null,
    case_is_blocked boolean not null,
    case_components_json jsonb not null default '[]'::jsonb,
    primary key (candidate_id, timesheet_id)
  ) on commit drop;

  truncate table pg_temp.tmp_sync_timesheet_case_candidates;
  truncate table pg_temp.tmp_sync_case_links;
  truncate table pg_temp.tmp_sync_case_clears;
  truncate table pg_temp.tmp_sync_preview_candidates;
  truncate table pg_temp.tmp_sync_authoritative_negative_components;
  truncate table pg_temp.tmp_sync_raw_negative_timesheet_rows;

  IF COALESCE(v_authoritative_timesheet_scope, false) THEN
    INSERT INTO pg_temp.tmp_sync_authoritative_negative_components (
      timesheet_id,
      key_type,
      key_value,
      truth_ex_vat,
      baseline_ex_vat,
      reserved_ex_vat,
      outstanding_ex_vat,
      baseline_signature
    )
    WITH live_entitlement_components AS (
      SELECT
        entitlement_component.timesheet_id,
        UPPER(BTRIM(entitlement_component.key_type)) AS key_type,
        BTRIM(entitlement_component.key_value) AS key_value,
        ROUND(COALESCE(entitlement_component.truth_ex_vat, 0), 2)::numeric(12,2) AS truth_ex_vat,
        ROUND(COALESCE(entitlement_component.baseline_ex_vat, 0), 2)::numeric(12,2) AS baseline_ex_vat
      FROM public._pay_current_timesheet_entitlement_components(
        COALESCE(p_force_include_timesheet_ids, ARRAY[]::uuid[])
      ) AS entitlement_component
      WHERE NULLIF(BTRIM(COALESCE(entitlement_component.key_type, '')), '') IS NOT NULL
        AND NULLIF(BTRIM(COALESCE(entitlement_component.key_value, '')), '') IS NOT NULL
    ), active_entitlement_reservations AS (
      SELECT
        reserved_component.timesheet_id,
        UPPER(BTRIM(reserved_component.key_type)) AS key_type,
        BTRIM(reserved_component.key_value) AS key_value,
        ROUND(COALESCE(reserved_component.amount_ex_vat, 0), 2)::numeric(12,2) AS reserved_ex_vat
      FROM public._pay_reserved_components(
        COALESCE(p_force_include_timesheet_ids, ARRAY[]::uuid[]),
        NULL::uuid
      ) AS reserved_component
      WHERE NULLIF(BTRIM(COALESCE(reserved_component.key_type, '')), '') IS NOT NULL
        AND NULLIF(BTRIM(COALESCE(reserved_component.key_value, '')), '') IS NOT NULL
    ), live_economic_keys AS (
      SELECT
        live_component.timesheet_id,
        live_component.key_type,
        live_component.key_value
      FROM live_entitlement_components AS live_component

      UNION

      SELECT
        reserved_component.timesheet_id,
        reserved_component.key_type,
        reserved_component.key_value
      FROM active_entitlement_reservations AS reserved_component
    ), raw_outstanding_components AS (
      SELECT
        live_key.timesheet_id,
        live_key.key_type,
        live_key.key_value,
        ROUND(COALESCE(live_component.truth_ex_vat, 0), 2)::numeric(12,2) AS truth_ex_vat,
        ROUND(COALESCE(live_component.baseline_ex_vat, 0), 2)::numeric(12,2) AS baseline_ex_vat,
        ROUND(COALESCE(reserved_component.reserved_ex_vat, 0), 2)::numeric(12,2) AS reserved_ex_vat,
        ROUND(
          COALESCE(live_component.truth_ex_vat, 0)
          - COALESCE(live_component.baseline_ex_vat, 0)
          - COALESCE(reserved_component.reserved_ex_vat, 0),
          2
        )::numeric(12,2) AS outstanding_ex_vat
      FROM live_economic_keys AS live_key
      LEFT JOIN live_entitlement_components AS live_component
        ON live_component.timesheet_id = live_key.timesheet_id
       AND live_component.key_type = live_key.key_type
       AND live_component.key_value = live_key.key_value
      LEFT JOIN active_entitlement_reservations AS reserved_component
        ON reserved_component.timesheet_id = live_key.timesheet_id
       AND reserved_component.key_type = live_key.key_type
       AND reserved_component.key_value = live_key.key_value
    )
    SELECT
      raw_component.timesheet_id,
      raw_component.key_type,
      raw_component.key_value,
      raw_component.truth_ex_vat,
      raw_component.baseline_ex_vat,
      raw_component.reserved_ex_vat,
      raw_component.outstanding_ex_vat,
      CASE
        WHEN COALESCE(active_settled_basis.active_settled_component_count, 0) > 0
          THEN active_settled_basis.active_settled_signature
        ELSE COALESCE(
          timesheet_pay_state.last_settled_signature,
          md5(COALESCE(timesheet_pay_state.last_settled_snapshot_json::text, '{}'))
        )
      END AS baseline_signature
    FROM raw_outstanding_components AS raw_component
    LEFT JOIN public.timesheet_pay_state AS timesheet_pay_state
      ON timesheet_pay_state.timesheet_id = raw_component.timesheet_id
    LEFT JOIN LATERAL (
      SELECT
        COUNT(*)::integer AS active_settled_component_count,
        md5(COALESCE(jsonb_agg(
          jsonb_build_object(
            'key_type', active_settled_component.key_type,
            'key_value', active_settled_component.key_value,
            'amount_ex_vat', ROUND(COALESCE(active_settled_component.amount_ex_vat, 0), 2),
            'amount_inc_vat', ROUND(COALESCE(active_settled_component.amount_inc_vat, 0), 2)
          ) ORDER BY active_settled_component.key_type, active_settled_component.key_value
        )::text, '[]')) AS active_settled_signature
      FROM public._pay_active_settled_components(
        ARRAY[raw_component.timesheet_id]::uuid[]
      ) AS active_settled_component
    ) AS active_settled_basis ON true
    WHERE raw_component.outstanding_ex_vat < 0;

    PERFORM public._ctms_rewrite_sync_authoritative_correction_negative_components_v1(
      nullif(btrim(p_mismatch_choices->>'workbench_session_id'), '')::uuid,
      v_authoritative_candidate_id,
      coalesce(p_force_include_timesheet_ids, array[]::uuid[])
    );

    SELECT
      COUNT(*)::integer,
      md5(COALESCE(jsonb_agg(
        jsonb_build_object(
          'timesheet_id', negative_component.timesheet_id::text,
          'key_type', negative_component.key_type,
          'key_value', negative_component.key_value,
          'truth_ex_vat', ROUND(negative_component.truth_ex_vat, 2)::numeric(12,2),
          'baseline_ex_vat', ROUND(negative_component.baseline_ex_vat, 2)::numeric(12,2),
          'reserved_ex_vat', ROUND(negative_component.reserved_ex_vat, 2)::numeric(12,2),
          'outstanding_ex_vat', ROUND(negative_component.outstanding_ex_vat, 2)::numeric(12,2)
        ) ORDER BY negative_component.timesheet_id, negative_component.key_type, negative_component.key_value
      )::text, '[]'))
    INTO
      v_authoritative_negative_component_count,
      v_authoritative_negative_component_digest
    FROM pg_temp.tmp_sync_authoritative_negative_components AS negative_component;

    SELECT md5(COALESCE(jsonb_agg(
      jsonb_build_object(
        'timesheet_id', settled_component.timesheet_id::text,
        'key_type', settled_component.key_type,
        'key_value', settled_component.key_value,
        'amount_ex_vat', ROUND(COALESCE(settled_component.amount_ex_vat, 0), 2),
        'amount_inc_vat', ROUND(COALESCE(settled_component.amount_inc_vat, 0), 2)
      ) ORDER BY settled_component.timesheet_id, settled_component.key_type, settled_component.key_value
    )::text, '[]'))
    INTO v_authoritative_settled_baseline_digest
    FROM public._pay_active_settled_components(
      COALESCE(p_force_include_timesheet_ids, ARRAY[]::uuid[])
    ) AS settled_component;

    v_expected_negative_component_digest := NULLIF(BTRIM(COALESCE(
      p_mismatch_choices->>'overpayment_sync_negative_component_digest',
      ''
    )), '');
    v_expected_settled_baseline_digest := NULLIF(BTRIM(COALESCE(
      p_mismatch_choices->>'overpayment_sync_settled_baseline_digest',
      ''
    )), '');

    IF v_authoritative_negative_component_digest IS DISTINCT FROM v_expected_negative_component_digest
       OR v_authoritative_settled_baseline_digest IS DISTINCT FROM v_expected_settled_baseline_digest THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_COMPONENT_DIGEST_MISMATCH'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_COMPONENT_DIGEST_MISMATCH',
                'candidate_id', v_authoritative_candidate_id::text,
                'negative_component_count', COALESCE(v_authoritative_negative_component_count, 0),
                'expected_negative_component_digest', v_expected_negative_component_digest,
                'actual_negative_component_digest', v_authoritative_negative_component_digest,
                'expected_settled_baseline_digest', v_expected_settled_baseline_digest,
                'actual_settled_baseline_digest', v_authoritative_settled_baseline_digest,
                'message', 'The Workbench negative-component or settled-baseline authority changed before finance-case synchronisation.'
              )::text;
    END IF;
  END IF;
  IF v_requested_candidate_count > 0 THEN
    FOR v_preview_candidate_loop_id IN
      SELECT DISTINCT requested_candidate.candidate_id
      FROM unnest(COALESCE(p_candidate_ids, ARRAY[]::uuid[])) AS requested_candidate(candidate_id)
      WHERE requested_candidate.candidate_id IS NOT NULL
      ORDER BY requested_candidate.candidate_id
    LOOP
      v_preview_context_json := public.pay_preview_build_context(
        p_pay_date => p_pay_date,
        p_week_ending_cutoff => p_week_ending_cutoff,
        p_actor_user_id => p_actor_user_id,
        p_candidate_id => v_preview_candidate_loop_id,
        p_client_id => p_client_filter_single,
        p_preview_decisions_json => v_preview_decisions_json
      )
      || jsonb_build_object(
        'overpayment_sync_mode', true,
        'emit_raw_overpayment_components', true,
        'pay_channel_scope', v_scope,
        'candidate_ids', COALESCE(to_jsonb(p_candidate_ids), '[]'::jsonb),
        'force_include_timesheet_ids', COALESCE(to_jsonb(p_force_include_timesheet_ids), '[]'::jsonb),
        'exclude_timesheet_ids', COALESCE(to_jsonb(p_exclude_timesheet_ids), '[]'::jsonb)
      )
      || CASE
        WHEN COALESCE(v_authoritative_timesheet_scope, false) THEN
          jsonb_build_object(
            'workbench_source_build_mode', true,
            'source_build_mode', true,
            'job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
          )
        ELSE '{}'::jsonb
      END;

      v_preview_baseline_json := public.pay_preview_candidate_build_summary_fragment(
        p_context_json => v_preview_context_json,
        p_candidate_id => v_preview_candidate_loop_id
      );

      IF jsonb_typeof(COALESCE(v_preview_baseline_json, '{}'::jsonb)) <> 'object' THEN
        RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_PREVIEW_BASELINE_INVALID'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_SYNC_OVERPAYMENTS_PREVIEW_BASELINE_INVALID',
                  'candidate_id', v_preview_candidate_loop_id::text,
                  'pay_channel_scope', v_scope
                )::text;
      END IF;

      IF COALESCE(v_authoritative_timesheet_scope, false)
         AND COALESCE(v_authoritative_negative_component_count, 0) > 0
         AND to_regclass('pg_temp.timesheet_case_rollup') IS NULL THEN
        PERFORM public.pay_preview_candidate_build_case_component_rows(
          p_context_json => v_preview_context_json,
          p_candidate_id => v_preview_candidate_loop_id
        );
      END IF;

      IF COALESCE(v_authoritative_timesheet_scope, false)
         AND to_regclass('pg_temp.timesheet_case_rollup') IS NOT NULL THEN
        IF EXISTS (
          WITH correction_residuals AS (
            SELECT residual.value AS residual_json
            FROM jsonb_array_elements(public._ctms_candidate_correction_residuals_v1(
              v_workbench_session_id_text::uuid,
              v_preview_candidate_loop_id,
              NULL::uuid,
              'PAY_SYNC_OVERPAYMENTS_FROM_PREVIEW_METADATA'
            )) AS residual(value)
            WHERE COALESCE((residual.value->>'draftable')::boolean, false)
          ), correction_member_roots AS (
            SELECT DISTINCT
              member_id.value::uuid AS member_timesheet_id,
              (residual.residual_json->>'root_timesheet_id')::uuid AS root_timesheet_id
            FROM correction_residuals AS residual
            CROSS JOIN LATERAL jsonb_array_elements_text(
              COALESCE(residual.residual_json->'member_timesheet_ids', '[]'::jsonb)
            ) AS member_id(value)
            WHERE COALESCE(residual.residual_json->>'root_timesheet_id', '')
                    ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              AND member_id.value
                    ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          ), correction_component_totals AS (
            SELECT
              (residual.residual_json->>'root_timesheet_id')::uuid AS timesheet_id,
              UPPER(BTRIM(COALESCE(component.value->>'component_key_type', ''))) AS key_type,
              BTRIM(COALESCE(component.value->>'component_key_value', '')) AS key_value,
              1::integer AS preview_component_count,
              ROUND(
                (component.value->>'truth_ex_vat')::numeric,
                2
              )::numeric(12,2) AS preview_truth_ex_vat
            FROM correction_residuals AS residual
            CROSS JOIN LATERAL jsonb_array_elements(
              COALESCE(residual.residual_json->'components', '[]'::jsonb)
            ) AS component(value)
            WHERE COALESCE(residual.residual_json->>'root_timesheet_id', '')
                    ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              AND COALESCE(component.value->>'truth_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
              AND ROUND(
                    COALESCE(NULLIF(component.value->>'target_outstanding_ex_vat', '')::numeric, 0),
                    2
                  ) < 0
          ), raw_preview_component_totals AS (
            SELECT
              raw_case.timesheet_id,
              UPPER(BTRIM(COALESCE(raw_component.value->>'component_key_type', ''))) AS key_type,
              BTRIM(COALESCE(raw_component.value->>'component_key_value', '')) AS key_value,
              COUNT(*)::integer AS preview_component_count,
              ROUND(
                SUM((raw_component.value->>'component_amount_ex_vat')::numeric),
                2
              )::numeric(12,2) AS preview_truth_ex_vat
            FROM pg_temp.timesheet_case_rollup AS raw_case
            CROSS JOIN LATERAL jsonb_array_elements(
              CASE
                WHEN jsonb_typeof(raw_case.case_components_json) = 'array'
                  THEN COALESCE(raw_case.case_components_json, '[]'::jsonb)
                ELSE '[]'::jsonb
              END
            ) AS raw_component(value)
            WHERE raw_case.candidate_id = v_preview_candidate_loop_id
              AND raw_case.timesheet_id = ANY(COALESCE(p_force_include_timesheet_ids, ARRAY[]::uuid[]))
              AND NOT (raw_case.timesheet_id = ANY(COALESCE(p_exclude_timesheet_ids, ARRAY[]::uuid[])))
              AND NOT EXISTS (
                SELECT 1
                FROM correction_member_roots AS correction_member
                WHERE correction_member.member_timesheet_id = raw_case.timesheet_id
              )
              AND COALESCE(raw_component.value->>'component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            GROUP BY
              raw_case.timesheet_id,
              UPPER(BTRIM(COALESCE(raw_component.value->>'component_key_type', ''))),
              BTRIM(COALESCE(raw_component.value->>'component_key_value', ''))
          ), preview_component_totals AS (
            SELECT * FROM correction_component_totals
            UNION ALL
            SELECT * FROM raw_preview_component_totals
          )
          SELECT 1
          FROM pg_temp.tmp_sync_authoritative_negative_components AS authoritative_component
          LEFT JOIN preview_component_totals AS preview_total
            ON preview_total.timesheet_id = authoritative_component.timesheet_id
           AND preview_total.key_type = authoritative_component.key_type
           AND preview_total.key_value = authoritative_component.key_value
          WHERE (
                  (
                    preview_total.preview_component_count IS NULL
                    AND ABS(ROUND(authoritative_component.truth_ex_vat, 2)) > 0.01
                  )
                  OR (
                    preview_total.preview_component_count IS NOT NULL
                    AND ABS(ROUND(
                      preview_total.preview_truth_ex_vat
                      - authoritative_component.truth_ex_vat,
                      2
                    )) > 0.01
                  )
                )
            AND NOT (
              authoritative_component.timesheet_id
                = ANY(COALESCE(v_resolution_pending_root_ids, ARRAY[]::uuid[]))
              OR authoritative_component.timesheet_id
                = ANY(COALESCE(v_resolution_pending_member_ids, ARRAY[]::uuid[]))
            )
        ) THEN
          RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_NEGATIVE_COMPONENT_METADATA_MISMATCH'
            USING ERRCODE = 'P0001',
                  DETAIL = jsonb_build_object(
                    'code', 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_NEGATIVE_COMPONENT_METADATA_MISMATCH',
                    'candidate_id', v_preview_candidate_loop_id::text,
                    'negative_component_count', COALESCE(v_authoritative_negative_component_count, 0),
                    'negative_component_digest', v_authoritative_negative_component_digest,
                    'authoritative_component_sample', (
                      SELECT COALESCE(jsonb_agg(jsonb_build_object(
                        'timesheet_id', bounded_component.timesheet_id::text,
                        'key_type', bounded_component.key_type,
                        'key_value', bounded_component.key_value,
                        'truth_ex_vat', bounded_component.truth_ex_vat,
                        'outstanding_ex_vat', bounded_component.outstanding_ex_vat
                      ) ORDER BY bounded_component.timesheet_id, bounded_component.key_type, bounded_component.key_value), '[]'::jsonb)
                      FROM (
                        SELECT *
                        FROM pg_temp.tmp_sync_authoritative_negative_components
                        ORDER BY timesheet_id, key_type, key_value
                        LIMIT 10
                      ) AS bounded_component
                    ),
                    'correction_component_sample', (
                      SELECT COALESCE(jsonb_agg(jsonb_build_object(
                        'timesheet_id', bounded_correction.root_timesheet_id,
                        'key_type', bounded_correction.key_type,
                        'key_value', bounded_correction.key_value,
                        'truth_ex_vat', bounded_correction.truth_ex_vat,
                        'outstanding_ex_vat', bounded_correction.outstanding_ex_vat
                      ) ORDER BY bounded_correction.root_timesheet_id, bounded_correction.key_type, bounded_correction.key_value), '[]'::jsonb)
                      FROM (
                        SELECT
                          residual.value->>'root_timesheet_id' AS root_timesheet_id,
                          UPPER(BTRIM(component.value->>'component_key_type')) AS key_type,
                          BTRIM(component.value->>'component_key_value') AS key_value,
                          component.value->>'truth_ex_vat' AS truth_ex_vat,
                          component.value->>'target_outstanding_ex_vat' AS outstanding_ex_vat
                        FROM jsonb_array_elements(public._ctms_candidate_correction_residuals_v1(
                          v_workbench_session_id_text::uuid,
                          v_preview_candidate_loop_id,
                          NULL::uuid,
                          'PAY_SYNC_OVERPAYMENTS_FROM_PREVIEW_METADATA_DIAGNOSTIC'
                        )) AS residual(value)
                        CROSS JOIN LATERAL jsonb_array_elements(
                          COALESCE(residual.value->'components', '[]'::jsonb)
                        ) AS component(value)
                        WHERE COALESCE((residual.value->>'draftable')::boolean, false)
                          AND ROUND(COALESCE(NULLIF(component.value->>'target_outstanding_ex_vat', '')::numeric, 0), 2) < 0
                        ORDER BY residual.value->>'root_timesheet_id',
                                 UPPER(BTRIM(component.value->>'component_key_type')),
                                 BTRIM(component.value->>'component_key_value')
                        LIMIT 10
                      ) AS bounded_correction
                    ),
                    'message', 'Canonical negative component keys were not represented by preview metadata whose current component totals match authoritative live truth.'
                  )::text;
        END IF;

        INSERT INTO pg_temp.tmp_sync_raw_negative_timesheet_rows (
          candidate_id,
          timesheet_id,
          client_id,
          candidate_pay_method,
          case_is_blocked,
          case_components_json
        )
        SELECT
          raw_case.candidate_id,
          raw_case.timesheet_id,
          raw_case.client_id,
          COALESCE(NULLIF(UPPER(BTRIM(raw_case.cand_pay_method)), ''), v_scope),
          COALESCE(raw_case.is_blocked, false),
          COALESCE((
            WITH matching_preview_components AS (
              SELECT
                authoritative_component.timesheet_id,
                authoritative_component.key_type,
                authoritative_component.key_value,
                authoritative_component.truth_ex_vat,
                authoritative_component.baseline_ex_vat,
                authoritative_component.reserved_ex_vat,
                authoritative_component.outstanding_ex_vat,
                raw_component.value AS component_json,
                raw_component.ordinality::integer AS component_ordinality,
                ROUND(
                  (raw_component.value->>'component_amount_ex_vat')::numeric,
                  2
                )::numeric(12,2) AS preview_truth_component_ex_vat,
                COUNT(*) OVER (
                  PARTITION BY
                    authoritative_component.timesheet_id,
                    authoritative_component.key_type,
                    authoritative_component.key_value
                )::integer AS physical_component_count,
                ROUND(
                  SUM(ABS((raw_component.value->>'component_amount_ex_vat')::numeric)) OVER (
                    PARTITION BY
                      authoritative_component.timesheet_id,
                      authoritative_component.key_type,
                      authoritative_component.key_value
                  ),
                  2
                )::numeric(12,2) AS preview_truth_weight_total_ex_vat,
                ROW_NUMBER() OVER (
                  PARTITION BY
                    authoritative_component.timesheet_id,
                    authoritative_component.key_type,
                    authoritative_component.key_value
                  ORDER BY
                    COALESCE(raw_component.value->'source_basis_json', '{}'::jsonb)::text,
                    raw_component.ordinality
                )::integer AS allocation_rank
              FROM pg_temp.tmp_sync_authoritative_negative_components AS authoritative_component
              CROSS JOIN LATERAL jsonb_array_elements(
                CASE
                  WHEN jsonb_typeof(raw_case.case_components_json) = 'array'
                    THEN COALESCE(raw_case.case_components_json, '[]'::jsonb)
                  ELSE '[]'::jsonb
                END
              ) WITH ORDINALITY AS raw_component(value, ordinality)
              WHERE authoritative_component.timesheet_id = raw_case.timesheet_id
                AND authoritative_component.key_type = UPPER(BTRIM(COALESCE(raw_component.value->>'component_key_type', '')))
                AND authoritative_component.key_value = BTRIM(COALESCE(raw_component.value->>'component_key_value', ''))
                AND COALESCE(raw_component.value->>'component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            ), preliminary_allocations AS (
              SELECT
                matching_component.*,
                CASE
                  WHEN matching_component.physical_component_count = 1
                    THEN matching_component.outstanding_ex_vat
                  WHEN COALESCE(matching_component.preview_truth_weight_total_ex_vat, 0) <= 0.01
                    THEN CASE
                      WHEN matching_component.allocation_rank = 1
                        THEN matching_component.outstanding_ex_vat
                      ELSE 0::numeric
                    END
                  ELSE ROUND(
                    matching_component.outstanding_ex_vat
                    * ABS(matching_component.preview_truth_component_ex_vat)
                    / matching_component.preview_truth_weight_total_ex_vat,
                    2
                  )
                END::numeric(12,2) AS preliminary_outstanding_allocation
              FROM matching_preview_components AS matching_component
            ), final_allocations AS (
              SELECT
                preliminary_allocation.*,
                CASE
                  WHEN preliminary_allocation.allocation_rank = preliminary_allocation.physical_component_count
                    THEN ROUND(
                      preliminary_allocation.outstanding_ex_vat
                      - COALESCE(
                          SUM(preliminary_allocation.preliminary_outstanding_allocation) OVER (
                            PARTITION BY
                              preliminary_allocation.timesheet_id,
                              preliminary_allocation.key_type,
                              preliminary_allocation.key_value
                            ORDER BY preliminary_allocation.allocation_rank
                            ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
                          ),
                          0
                        ),
                      2
                    )
                  ELSE preliminary_allocation.preliminary_outstanding_allocation
                END::numeric(12,2) AS authoritative_outstanding_allocation
              FROM preliminary_allocations AS preliminary_allocation
            )
            SELECT jsonb_agg(
              allocated_component.component_json
              || jsonb_build_object(
                'component_amount_ex_vat', allocated_component.authoritative_outstanding_allocation,
                'authoritative_truth_ex_vat', allocated_component.truth_ex_vat,
                'authoritative_baseline_ex_vat', allocated_component.baseline_ex_vat,
                'authoritative_reserved_ex_vat', allocated_component.reserved_ex_vat,
                'authoritative_outstanding_ex_vat', allocated_component.outstanding_ex_vat,
                'overpayment_component_authority', 'PRE_DRAFT_LIVE_TRUTH'
              )
              ORDER BY
                allocated_component.key_type,
                allocated_component.key_value,
                COALESCE(allocated_component.component_json->'source_basis_json', '{}'::jsonb)::text,
                allocated_component.component_ordinality
            )
            FROM final_allocations AS allocated_component
          ), '[]'::jsonb)
          || COALESCE((
            SELECT jsonb_agg(
              jsonb_build_object(
                'component_key_type', authoritative_component.key_type,
                'component_key_value', authoritative_component.key_value,
                'component_amount_ex_vat', authoritative_component.outstanding_ex_vat,
                'authoritative_truth_ex_vat', authoritative_component.truth_ex_vat,
                'authoritative_baseline_ex_vat', authoritative_component.baseline_ex_vat,
                'authoritative_reserved_ex_vat', authoritative_component.reserved_ex_vat,
                'authoritative_outstanding_ex_vat', authoritative_component.outstanding_ex_vat,
                'overpayment_component_authority', 'PRE_DRAFT_LIVE_TRUTH',
                'source_pay_method', COALESCE(NULLIF(UPPER(BTRIM(raw_case.cand_pay_method)), ''), v_scope),
                'source_basis_json', jsonb_build_object(
                  'linked_timesheet_id', authoritative_component.timesheet_id::text,
                  'component_key_type', authoritative_component.key_type,
                  'component_key_value', authoritative_component.key_value,
                  'source_pay_method', COALESCE(NULLIF(UPPER(BTRIM(raw_case.cand_pay_method)), ''), v_scope),
                  'component_amount_ex_vat', ABS(authoritative_component.outstanding_ex_vat),
                  'authority_helper', '_pay_current_timesheet_entitlement_components'
                )
              )
              ORDER BY authoritative_component.key_type, authoritative_component.key_value
            )
            FROM pg_temp.tmp_sync_authoritative_negative_components AS authoritative_component
            WHERE authoritative_component.timesheet_id = raw_case.timesheet_id
              AND ABS(ROUND(authoritative_component.truth_ex_vat, 2)) <= 0.01
              AND NOT EXISTS (
                SELECT 1
                FROM jsonb_array_elements(
                  CASE
                    WHEN jsonb_typeof(raw_case.case_components_json) = 'array'
                      THEN COALESCE(raw_case.case_components_json, '[]'::jsonb)
                    ELSE '[]'::jsonb
                  END
                ) AS preview_component(value)
                WHERE authoritative_component.key_type = UPPER(BTRIM(COALESCE(preview_component.value->>'component_key_type', '')))
                  AND authoritative_component.key_value = BTRIM(COALESCE(preview_component.value->>'component_key_value', ''))
                  AND COALESCE(preview_component.value->>'component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
              )
          ), '[]'::jsonb)
        FROM pg_temp.timesheet_case_rollup AS raw_case
        WHERE raw_case.candidate_id = v_preview_candidate_loop_id
          AND raw_case.timesheet_id = ANY(COALESCE(p_force_include_timesheet_ids, ARRAY[]::uuid[]))
          AND NOT (raw_case.timesheet_id = ANY(COALESCE(p_exclude_timesheet_ids, ARRAY[]::uuid[])))
          AND NOT (
            raw_case.timesheet_id
              = ANY(COALESCE(v_resolution_pending_member_ids, ARRAY[]::uuid[]))
          )
          AND EXISTS (
            SELECT 1
            FROM pg_temp.tmp_sync_authoritative_negative_components AS authoritative_component
            WHERE authoritative_component.timesheet_id = raw_case.timesheet_id
          )
        ON CONFLICT (candidate_id, timesheet_id) DO UPDATE
        SET
          client_id = EXCLUDED.client_id,
          candidate_pay_method = EXCLUDED.candidate_pay_method,
          case_is_blocked = EXCLUDED.case_is_blocked,
          case_components_json = EXCLUDED.case_components_json;

        INSERT INTO pg_temp.tmp_sync_raw_negative_timesheet_rows (
          candidate_id,
          timesheet_id,
          client_id,
          candidate_pay_method,
          case_is_blocked,
          case_components_json
        )
        SELECT
          v_preview_candidate_loop_id,
          authoritative_component.timesheet_id,
          financial_metadata.client_id,
          COALESCE(financial_metadata.candidate_pay_method, v_scope),
          false,
          jsonb_agg(
            jsonb_build_object(
              'component_key_type', authoritative_component.key_type,
              'component_key_value', authoritative_component.key_value,
              'component_amount_ex_vat', authoritative_component.outstanding_ex_vat,
              'authoritative_truth_ex_vat', authoritative_component.truth_ex_vat,
              'authoritative_baseline_ex_vat', authoritative_component.baseline_ex_vat,
              'authoritative_reserved_ex_vat', authoritative_component.reserved_ex_vat,
              'authoritative_outstanding_ex_vat', authoritative_component.outstanding_ex_vat,
              'overpayment_component_authority', 'PRE_DRAFT_LIVE_TRUTH',
              'source_pay_method', COALESCE(financial_metadata.candidate_pay_method, v_scope),
              'source_basis_json', jsonb_build_object(
                'linked_timesheet_id', authoritative_component.timesheet_id::text,
                'component_key_type', authoritative_component.key_type,
                'component_key_value', authoritative_component.key_value,
                'source_pay_method', COALESCE(financial_metadata.candidate_pay_method, v_scope),
                'component_amount_ex_vat', ABS(authoritative_component.outstanding_ex_vat),
                'authority_helper', '_pay_current_timesheet_entitlement_components'
              )
            )
            ORDER BY authoritative_component.key_type, authoritative_component.key_value
          )
        FROM pg_temp.tmp_sync_authoritative_negative_components AS authoritative_component
        LEFT JOIN LATERAL (
          SELECT
            COALESCE(
              MIN(financial_row.client_id::text) FILTER (WHERE COALESCE(financial_row.is_current, false)),
              MIN(financial_row.client_id::text)
            )::uuid AS client_id,
            COALESCE(
              MIN(NULLIF(UPPER(BTRIM(financial_row.pay_method)), '')) FILTER (WHERE COALESCE(financial_row.is_current, false)),
              MIN(NULLIF(UPPER(BTRIM(financial_row.pay_method)), ''))
            ) AS candidate_pay_method
          FROM public.timesheets_financials AS financial_row
          WHERE financial_row.timesheet_id = authoritative_component.timesheet_id
            AND financial_row.candidate_id = v_preview_candidate_loop_id
        ) AS financial_metadata ON true
        WHERE ABS(ROUND(authoritative_component.truth_ex_vat, 2)) <= 0.01
          AND NOT (
            authoritative_component.timesheet_id
              = ANY(COALESCE(v_resolution_pending_root_ids, ARRAY[]::uuid[]))
            OR authoritative_component.timesheet_id
              = ANY(COALESCE(v_resolution_pending_member_ids, ARRAY[]::uuid[]))
          )
          AND NOT EXISTS (
            SELECT 1
            FROM pg_temp.timesheet_case_rollup AS raw_case
            WHERE raw_case.candidate_id = v_preview_candidate_loop_id
              AND raw_case.timesheet_id = authoritative_component.timesheet_id
          )
        GROUP BY
          authoritative_component.timesheet_id,
          financial_metadata.client_id,
          financial_metadata.candidate_pay_method
        ON CONFLICT (candidate_id, timesheet_id) DO UPDATE
        SET
          client_id = EXCLUDED.client_id,
          candidate_pay_method = EXCLUDED.candidate_pay_method,
          case_is_blocked = EXCLUDED.case_is_blocked,
          case_components_json = EXCLUDED.case_components_json;

        IF EXISTS (
          WITH allocated_component_totals AS (
            SELECT
              raw_timesheet.timesheet_id,
              UPPER(BTRIM(COALESCE(component.value->>'component_key_type', ''))) AS key_type,
              BTRIM(COALESCE(component.value->>'component_key_value', '')) AS key_value,
              COUNT(*)::integer AS allocated_component_count,
              ROUND(SUM((component.value->>'component_amount_ex_vat')::numeric), 2)::numeric(12,2) AS allocated_outstanding_ex_vat
            FROM pg_temp.tmp_sync_raw_negative_timesheet_rows AS raw_timesheet
            CROSS JOIN LATERAL jsonb_array_elements(raw_timesheet.case_components_json) AS component(value)
            WHERE raw_timesheet.candidate_id = v_preview_candidate_loop_id
              AND COALESCE(component.value->>'component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            GROUP BY
              raw_timesheet.timesheet_id,
              UPPER(BTRIM(COALESCE(component.value->>'component_key_type', ''))),
              BTRIM(COALESCE(component.value->>'component_key_value', ''))
          )
          SELECT 1
          FROM pg_temp.tmp_sync_authoritative_negative_components AS authoritative_component
          LEFT JOIN allocated_component_totals AS allocated_total
            ON allocated_total.timesheet_id = authoritative_component.timesheet_id
           AND allocated_total.key_type = authoritative_component.key_type
           AND allocated_total.key_value = authoritative_component.key_value
          WHERE (
                  allocated_total.allocated_component_count IS NULL
                  OR (
                  ABS(ROUND(
                    COALESCE(allocated_total.allocated_outstanding_ex_vat, 0)
                    - authoritative_component.outstanding_ex_vat,
                    2
                  )) > 0.01
                )
                )
            AND NOT (
              authoritative_component.timesheet_id
                = ANY(COALESCE(v_resolution_pending_root_ids, ARRAY[]::uuid[]))
              OR authoritative_component.timesheet_id
                = ANY(COALESCE(v_resolution_pending_member_ids, ARRAY[]::uuid[]))
            )
        ) THEN
          RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_NEGATIVE_COMPONENT_METADATA_MISMATCH'
            USING ERRCODE = 'P0001',
                  DETAIL = jsonb_build_object(
                    'code', 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_NEGATIVE_COMPONENT_METADATA_MISMATCH',
                    'candidate_id', v_preview_candidate_loop_id::text,
                    'negative_component_count', COALESCE(v_authoritative_negative_component_count, 0),
                    'negative_component_digest', v_authoritative_negative_component_digest,
                    'message', 'Canonical negative components were not represented exactly by the validated pre-draft component allocations.'
                  )::text;
        END IF;
      END IF;

      v_preview_candidate_row_json := CASE
        WHEN jsonb_typeof(v_preview_baseline_json->'candidate_row') = 'object'
          THEN COALESCE(v_preview_baseline_json->'candidate_row', '{}'::jsonb)
        ELSE '{}'::jsonb
      END;

      IF NULLIF(BTRIM(COALESCE(
           v_preview_candidate_row_json->>'candidate_id',
           v_preview_baseline_json->>'candidate_id',
           ''
         )), '') IS DISTINCT FROM v_preview_candidate_loop_id::text THEN
        RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_PREVIEW_CANDIDATE_COVERAGE_INCOMPLETE'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_SYNC_OVERPAYMENTS_PREVIEW_CANDIDATE_COVERAGE_INCOMPLETE',
                  'candidate_id', v_preview_candidate_loop_id::text,
                  'pay_channel_scope', v_scope,
                  'baseline_candidate_id', NULLIF(BTRIM(COALESCE(
                    v_preview_candidate_row_json->>'candidate_id',
                    v_preview_baseline_json->>'candidate_id',
                    ''
                  )), '')
                )::text;
      END IF;

      IF UPPER(BTRIM(COALESCE(v_preview_candidate_row_json->>'current_pay_method', ''))) IS DISTINCT FROM v_scope THEN
        RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_PREVIEW_PAY_CHANNEL_MISMATCH'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_SYNC_OVERPAYMENTS_PREVIEW_PAY_CHANNEL_MISMATCH',
                  'candidate_id', v_preview_candidate_loop_id::text,
                  'requested_pay_channel_scope', v_scope,
                  'current_pay_method', NULLIF(BTRIM(COALESCE(v_preview_candidate_row_json->>'current_pay_method', '')), '')
                )::text;
      END IF;

      v_preview_candidate_row_json := v_preview_candidate_row_json
        || jsonb_build_object(
          'candidate_id', v_preview_candidate_loop_id::text,
          'itemisation', CASE
            WHEN jsonb_typeof(v_preview_candidate_row_json->'itemisation') = 'array'
              THEN COALESCE(v_preview_candidate_row_json->'itemisation', '[]'::jsonb)
            WHEN jsonb_typeof(v_preview_baseline_json->'itemisation') = 'array'
              THEN COALESCE(v_preview_baseline_json->'itemisation', '[]'::jsonb)
            ELSE '[]'::jsonb
          END
        );

      INSERT INTO pg_temp.tmp_sync_preview_candidates (
        candidate_id,
        candidate_json
      )
      VALUES (
        v_preview_candidate_loop_id,
        v_preview_candidate_row_json
      )
      ON CONFLICT (candidate_id) DO UPDATE
      SET candidate_json = EXCLUDED.candidate_json;
    END LOOP;
  ELSE
    v_preview_scope_context_json := public.pay_preview_build_context(
      p_pay_date => p_pay_date,
      p_week_ending_cutoff => p_week_ending_cutoff,
      p_actor_user_id => p_actor_user_id,
      p_candidate_id => NULL::uuid,
      p_client_id => p_client_filter_single,
      p_preview_decisions_json => v_preview_decisions_json
        || jsonb_build_object(
          'preview_context_mode', 'PAGE',
          'scope_limit', 100
        )
    );

    v_preview_scope_candidate_ids_json := CASE
      WHEN jsonb_typeof(v_preview_scope_context_json->'candidate_ids') = 'array'
        THEN COALESCE(v_preview_scope_context_json->'candidate_ids', '[]'::jsonb)
      ELSE '[]'::jsonb
    END;

    IF LOWER(BTRIM(COALESCE(v_preview_scope_context_json->>'has_more', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_CANDIDATE_SCOPE_REQUIRES_EXPLICIT_IDS'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_CANDIDATE_SCOPE_REQUIRES_EXPLICIT_IDS',
                'message', 'The bounded candidate page is incomplete. Supply explicit candidate_ids rather than accepting a partial all-candidate reconciliation.',
                'pay_channel_scope', v_scope,
                'page_count', COALESCE(v_preview_scope_context_json->>'page_count', '0'),
                'limit', COALESCE(v_preview_scope_context_json->>'limit', '100'),
                'next_cursor_json', COALESCE(v_preview_scope_context_json->'next_cursor_json', 'null'::jsonb)
              )::text;
    END IF;

    FOR v_preview_candidate_loop_id IN
      SELECT DISTINCT scoped_candidate.value::uuid
      FROM jsonb_array_elements_text(COALESCE(v_preview_scope_candidate_ids_json, '[]'::jsonb)) AS scoped_candidate(value)
      WHERE scoped_candidate.value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      ORDER BY scoped_candidate.value::uuid
    LOOP
      v_preview_context_json := public.pay_preview_build_context(
        p_pay_date => p_pay_date,
        p_week_ending_cutoff => p_week_ending_cutoff,
        p_actor_user_id => p_actor_user_id,
        p_candidate_id => v_preview_candidate_loop_id,
        p_client_id => p_client_filter_single,
        p_preview_decisions_json => v_preview_decisions_json
      )
      || jsonb_build_object(
        'overpayment_sync_mode', true,
        'emit_raw_overpayment_components', true,
        'pay_channel_scope', v_scope,
        'force_include_timesheet_ids', COALESCE(to_jsonb(p_force_include_timesheet_ids), '[]'::jsonb),
        'exclude_timesheet_ids', COALESCE(to_jsonb(p_exclude_timesheet_ids), '[]'::jsonb)
      );

      v_preview_baseline_json := public.pay_preview_candidate_build_summary_fragment(
        p_context_json => v_preview_context_json,
        p_candidate_id => v_preview_candidate_loop_id
      );

      v_preview_candidate_row_json := CASE
        WHEN jsonb_typeof(v_preview_baseline_json->'candidate_row') = 'object'
          THEN COALESCE(v_preview_baseline_json->'candidate_row', '{}'::jsonb)
        ELSE '{}'::jsonb
      END;

      IF NULLIF(BTRIM(COALESCE(
           v_preview_candidate_row_json->>'candidate_id',
           v_preview_baseline_json->>'candidate_id',
           ''
         )), '') IS DISTINCT FROM v_preview_candidate_loop_id::text THEN
        RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_PREVIEW_CANDIDATE_COVERAGE_INCOMPLETE'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_SYNC_OVERPAYMENTS_PREVIEW_CANDIDATE_COVERAGE_INCOMPLETE',
                  'candidate_id', v_preview_candidate_loop_id::text,
                  'pay_channel_scope', v_scope
                )::text;
      END IF;

      IF UPPER(BTRIM(COALESCE(v_preview_candidate_row_json->>'current_pay_method', ''))) = v_scope THEN
        v_preview_candidate_row_json := v_preview_candidate_row_json
          || jsonb_build_object(
            'candidate_id', v_preview_candidate_loop_id::text,
            'itemisation', CASE
              WHEN jsonb_typeof(v_preview_candidate_row_json->'itemisation') = 'array'
                THEN COALESCE(v_preview_candidate_row_json->'itemisation', '[]'::jsonb)
              WHEN jsonb_typeof(v_preview_baseline_json->'itemisation') = 'array'
                THEN COALESCE(v_preview_baseline_json->'itemisation', '[]'::jsonb)
              ELSE '[]'::jsonb
            END
          );

        INSERT INTO pg_temp.tmp_sync_preview_candidates (
          candidate_id,
          candidate_json
        )
        VALUES (
          v_preview_candidate_loop_id,
          v_preview_candidate_row_json
        )
        ON CONFLICT (candidate_id) DO UPDATE
        SET candidate_json = EXCLUDED.candidate_json;
      END IF;
    END LOOP;
  END IF;

  SELECT COUNT(*)::integer
  INTO v_preview_candidate_count
  FROM pg_temp.tmp_sync_preview_candidates AS preview_candidate;

  WITH requested_candidates AS (
    SELECT DISTINCT requested_candidate.candidate_id
    FROM unnest(COALESCE(p_candidate_ids, ARRAY[]::uuid[])) AS requested_candidate(candidate_id)
    WHERE requested_candidate.candidate_id IS NOT NULL
  ), missing_candidates AS (
    SELECT requested_candidates.candidate_id
    FROM requested_candidates
    WHERE NOT EXISTS (
      SELECT 1
      FROM pg_temp.tmp_sync_preview_candidates AS preview_candidate
      WHERE preview_candidate.candidate_id = requested_candidates.candidate_id
    )
  )
  SELECT COUNT(*)::integer,
         COALESCE(jsonb_agg(missing_candidates.candidate_id::text ORDER BY missing_candidates.candidate_id), '[]'::jsonb)
  INTO v_missing_candidate_count,
       v_missing_candidate_ids_json
  FROM missing_candidates;

  IF COALESCE(v_missing_candidate_count, 0) > 0 THEN
    RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_PREVIEW_CANDIDATE_COVERAGE_INCOMPLETE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_SYNC_OVERPAYMENTS_PREVIEW_CANDIDATE_COVERAGE_INCOMPLETE',
              'pay_channel_scope', v_scope,
              'requested_candidate_count', v_requested_candidate_count,
              'preview_candidate_count', v_preview_candidate_count,
              'missing_candidate_ids', COALESCE(v_missing_candidate_ids_json, '[]'::jsonb)
            )::text;
  END IF;

  insert into pg_temp.tmp_sync_timesheet_case_candidates (
    candidate_id,
    timesheet_id,
    client_id,
    linked_shift_date,
    corrected_amount_ex,
    baseline_signature,
    candidate_pay_method,
    case_is_blocked,
    needs_lifecycle_tracking,
    overpayment_amount_ex,
    underpayment_amount_ex,
    desired_case_type,
    desired_advance_kind,
    desired_reason,
    source_original_paid_amount,
    source_corrected_paid_amount,
    components_sync_json
  )
  with candidate_rows as (
    select
      preview_candidate.candidate_id,
      upper(btrim(coalesce(preview_candidate.candidate_json->>'current_pay_method', ''))) as candidate_pay_method,
      case
        when jsonb_typeof(preview_candidate.candidate_json->'itemisation') = 'array'
          then coalesce(preview_candidate.candidate_json->'itemisation', '[]'::jsonb)
        else '[]'::jsonb
      end as itemisation_json
    from pg_temp.tmp_sync_preview_candidates as preview_candidate
    where upper(btrim(coalesce(preview_candidate.candidate_json->>'current_pay_method', ''))) = v_scope
      and (
        coalesce(array_length(p_candidate_ids, 1), 0) = 0
        or preview_candidate.candidate_id = any(p_candidate_ids)
      )
  ),
  itemisation_timesheet_rows as (
    select
      cr.candidate_id,
      cr.candidate_pay_method,
      itm.value as item_json,
      nullif(btrim(coalesce(itm.value->>'timesheet_id', '')), '')::uuid as timesheet_id,
      nullif(btrim(coalesce(itm.value->>'client_id', '')), '')::uuid as client_id,
      round(coalesce(nullif(itm.value->>'amount_ex_vat', '')::numeric, 0), 2)::numeric(12,2) as corrected_amount_ex,
      coalesce(itm.value->>'case_is_blocked', 'false')::boolean as case_is_blocked,
      coalesce(itm.value->'case_components', '[]'::jsonb) as case_components_json
    from candidate_rows cr
    cross join lateral jsonb_array_elements(coalesce(cr.itemisation_json, '[]'::jsonb)) as itm(value)
    where coalesce(itm.value->>'line_type', '') = 'TIMESHEET_PAYMENT'
      and nullif(btrim(coalesce(itm.value->>'timesheet_id', '')), '') is not null
      and (
        coalesce(array_length(p_force_include_timesheet_ids, 1), 0) = 0
        or nullif(btrim(coalesce(itm.value->>'timesheet_id', '')), '')::uuid = any(p_force_include_timesheet_ids)
        or p_force_include_timesheet_ids is null
      )
      and not (
        coalesce(array_length(p_exclude_timesheet_ids, 1), 0) > 0
        and nullif(btrim(coalesce(itm.value->>'timesheet_id', '')), '')::uuid = any(p_exclude_timesheet_ids)
      )
  ),
  authoritative_live_truth_totals AS (
    SELECT
      entitlement_component.timesheet_id,
      ROUND(COALESCE(SUM(COALESCE(entitlement_component.truth_ex_vat, 0)), 0), 2)::numeric(12,2) AS corrected_amount_ex
    FROM public._pay_current_timesheet_entitlement_components(
      CASE
        WHEN COALESCE(v_authoritative_timesheet_scope, false)
          THEN COALESCE(p_force_include_timesheet_ids, ARRAY[]::uuid[])
        ELSE ARRAY[]::uuid[]
      END
    ) AS entitlement_component
    GROUP BY entitlement_component.timesheet_id
  ),
  authoritative_negative_timesheet_rows AS (
    SELECT
      raw_timesheet.candidate_id,
      raw_timesheet.candidate_pay_method,
      jsonb_build_object(
        'line_type', 'TIMESHEET_PAYMENT',
        'timesheet_id', raw_timesheet.timesheet_id::text,
        'client_id', CASE WHEN raw_timesheet.client_id IS NULL THEN NULL ELSE raw_timesheet.client_id::text END,
        'amount_ex_vat', ROUND(COALESCE(live_truth.corrected_amount_ex, 0), 2),
        'case_is_blocked', raw_timesheet.case_is_blocked,
        'case_components', raw_timesheet.case_components_json,
        'source_authority', 'AUTHORITATIVE_NEGATIVE_COMPONENT_FALLBACK'
      ) AS item_json,
      raw_timesheet.timesheet_id,
      raw_timesheet.client_id,
      ROUND(COALESCE(live_truth.corrected_amount_ex, 0), 2)::numeric(12,2) AS corrected_amount_ex,
      raw_timesheet.case_is_blocked,
      raw_timesheet.case_components_json
    FROM pg_temp.tmp_sync_raw_negative_timesheet_rows AS raw_timesheet
    LEFT JOIN authoritative_live_truth_totals AS live_truth
      ON live_truth.timesheet_id = raw_timesheet.timesheet_id
    WHERE COALESCE(v_authoritative_timesheet_scope, false)
      AND raw_timesheet.candidate_id = v_authoritative_candidate_id
      AND EXISTS (
        SELECT 1
        FROM pg_temp.tmp_sync_authoritative_negative_components AS authoritative_component
        WHERE authoritative_component.timesheet_id = raw_timesheet.timesheet_id
      )
  ),
  timesheet_item_rows AS (
    SELECT
      itemisation_row.candidate_id,
      itemisation_row.candidate_pay_method,
      itemisation_row.item_json,
      itemisation_row.timesheet_id,
      itemisation_row.client_id,
      itemisation_row.corrected_amount_ex,
      itemisation_row.case_is_blocked,
      itemisation_row.case_components_json
    FROM itemisation_timesheet_rows AS itemisation_row
    WHERE NOT EXISTS (
      SELECT 1
      FROM authoritative_negative_timesheet_rows AS authoritative_row
      WHERE authoritative_row.candidate_id = itemisation_row.candidate_id
        AND authoritative_row.timesheet_id = itemisation_row.timesheet_id
    )

    UNION ALL

    SELECT
      authoritative_row.candidate_id,
      authoritative_row.candidate_pay_method,
      authoritative_row.item_json,
      authoritative_row.timesheet_id,
      authoritative_row.client_id,
      authoritative_row.corrected_amount_ex,
      authoritative_row.case_is_blocked,
      authoritative_row.case_components_json
    FROM authoritative_negative_timesheet_rows AS authoritative_row
  ),
  active_settled_basis AS (
    SELECT
      distinct_timesheet_rows.timesheet_id,
      active_components.active_settled_component_count,
      active_components.active_settled_amount_ex,
      active_components.active_settled_signature
    FROM (
      SELECT DISTINCT timesheet_item_rows.timesheet_id
      FROM timesheet_item_rows
      WHERE timesheet_item_rows.timesheet_id IS NOT NULL
    ) AS distinct_timesheet_rows
    LEFT JOIN LATERAL (
      SELECT
        count(*)::integer AS active_settled_component_count,
        round(COALESCE(sum(COALESCE(active_settled_rows.amount_ex_vat, 0)), 0), 2)::numeric(12,2) AS active_settled_amount_ex,
        md5(COALESCE(jsonb_agg(
          jsonb_build_object(
            'key_type', active_settled_rows.key_type,
            'key_value', active_settled_rows.key_value,
            'amount_ex_vat', round(COALESCE(active_settled_rows.amount_ex_vat, 0), 2),
            'amount_inc_vat', round(COALESCE(active_settled_rows.amount_inc_vat, 0), 2)
          )
          ORDER BY active_settled_rows.key_type, active_settled_rows.key_value
        )::text, '[]')) AS active_settled_signature
      FROM public._pay_active_settled_components(ARRAY[distinct_timesheet_rows.timesheet_id]::uuid[]) AS active_settled_rows
    ) AS active_components
      ON true
  ),
  timesheet_item_with_baseline as (
    select
      tir.candidate_id,
      tir.timesheet_id,
      tir.client_id,
      coalesce(ts.worked_start_iso::date, ts.scheduled_start_iso::date, ts.week_ending_date) as linked_shift_date,
      tir.corrected_amount_ex,
      case
        when COALESCE(active_settled_basis.active_settled_component_count, 0) > 0
          then active_settled_basis.active_settled_signature
        else coalesce(
          tps.last_settled_signature,
          md5(coalesce(tps.last_settled_snapshot_json::text, '{}'))
        )
      end as baseline_signature,
      tir.candidate_pay_method,
      tir.case_is_blocked,
      tir.case_components_json
    from timesheet_item_rows tir
    join public.timesheets ts
      on ts.timesheet_id = tir.timesheet_id
    left join public.timesheet_pay_state tps
      on tps.timesheet_id = tir.timesheet_id
    left join active_settled_basis
      on active_settled_basis.timesheet_id = tir.timesheet_id
  ),
  timesheet_exploded_components as (
    select
      tiwb.candidate_id,
      tiwb.timesheet_id,
      tiwb.client_id,
      tiwb.linked_shift_date,
      tiwb.corrected_amount_ex,
      tiwb.baseline_signature,
      tiwb.candidate_pay_method,
      tiwb.case_is_blocked,
      comp.value as component_json,
      comp.ordinality::integer as component_order,
      UPPER(NULLIF(BTRIM(COALESCE(comp.value->>'component_key_type', '')), '')) AS component_key_type,
      NULLIF(BTRIM(COALESCE(comp.value->>'component_key_value', '')), '') AS component_key_value,
      round(coalesce(nullif(comp.value->>'component_amount_ex_vat', '')::numeric, 0), 2)::numeric(12,2) as component_amount_ex
    from timesheet_item_with_baseline tiwb
    cross join lateral jsonb_array_elements(coalesce(tiwb.case_components_json, '[]'::jsonb)) with ordinality as comp(value, ordinality)
  ),
  finance_component_movements_raw as (
    select
      pa.candidate_id,
      pa.linked_timesheet_id as timesheet_id,
      upper(btrim(coalesce(pfc.component_key_type, pbi.frozen_component_key_type, ''))) as component_key_type,
      nullif(btrim(coalesce(pfc.component_key_value, pbi.frozen_component_key_value, '')), '') as component_key_value,
      upper(btrim(coalesce(pbi.item_type, ''))) as item_type,
      round(abs(coalesce(
        par.reserved_source_amount,
        public._pay_batch_item_source_reservation_amount_ex_vat(pbi.id),
        pbi.frozen_source_amount,
        pbi.amount_ex_vat,
        pbi.amount_inc_vat,
        par.reserved_amount,
        0
      )), 2)::numeric(12,2) as movement_amount_ex,
      true as is_settled_movement,
      false as is_active_reservation
    from public.pay_advances pa
    join public.pay_batch_items pbi
      on pbi.finance_case_id = pa.id
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    left join public.pay_bank_transfers pbt
      on pbt.id = pbi.pay_bank_transfer_id
    left join public.pay_advance_reservations par
      on par.pay_batch_item_id = pbi.id
    left join public.pay_finance_case_components pfc
      on pfc.id = coalesce(par.finance_component_id, pbi.finance_component_id)
    where pa.case_type in ('OVERPAYMENT'::public.pay_finance_case_type_enum, 'UNDERPAYMENT'::public.pay_finance_case_type_enum)
      and pa.linked_timesheet_id is not null
      and coalesce(pbi.is_voided, false) = false
      and upper(btrim(coalesce(pbi.item_type, ''))) in ('OVERPAYMENT_RECOVERY', 'UNDERPAYMENT_PAYMENT')
      and (
        upper(btrim(coalesce(pbc.settlement_status, ''))) = 'SETTLED'
        or pbc.settled_at_utc is not null
        or upper(btrim(coalesce(pbt.status, ''))) = 'COMPLETED'
        or pbt.completed_at_utc is not null
        or upper(btrim(coalesce(par.status, ''))) = 'SETTLED'
        or par.settled_at_utc is not null
      )
      and not exists (
        select 1
        from public.pay_payment_correction_items pci
        where pci.pay_batch_item_id = pbi.id
          and pci.status = 'APPLIED'
          and pci.correction_item_kind in ('PRE_BANK_CANCEL', 'NO_MONEY_UNWIND', 'SETTLED_REVERSAL')
      )

    union all

    select
      pa.candidate_id,
      pa.linked_timesheet_id as timesheet_id,
      upper(btrim(coalesce(pfc.component_key_type, pbi.frozen_component_key_type, ''))) as component_key_type,
      nullif(btrim(coalesce(pfc.component_key_value, pbi.frozen_component_key_value, '')), '') as component_key_value,
      upper(btrim(coalesce(
        pbi.item_type,
        case
          when pa.case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum then 'OVERPAYMENT_RECOVERY'
          when pa.case_type = 'UNDERPAYMENT'::public.pay_finance_case_type_enum then 'UNDERPAYMENT_PAYMENT'
          else null
        end,
        ''
      ))) as item_type,
      round(abs(coalesce(
        par.reserved_source_amount,
        public._pay_batch_item_source_reservation_amount_ex_vat(pbi.id),
        pbi.frozen_source_amount,
        pbi.amount_ex_vat,
        pbi.amount_inc_vat,
        par.reserved_amount,
        0
      )), 2)::numeric(12,2) as movement_amount_ex,
      false as is_settled_movement,
      true as is_active_reservation
    from public.pay_advance_reservations par
    join public.pay_advances pa
      on pa.id = par.finance_case_id
    left join public.pay_batch_items pbi
      on pbi.id = par.pay_batch_item_id
    left join public.pay_finance_case_components pfc
      on pfc.id = coalesce(par.finance_component_id, pbi.finance_component_id)
    where pa.case_type in ('OVERPAYMENT'::public.pay_finance_case_type_enum, 'UNDERPAYMENT'::public.pay_finance_case_type_enum)
      and pa.linked_timesheet_id is not null
      and upper(btrim(coalesce(par.status, ''))) in ('RESERVED', 'COMMITTED')
      and par.released_at_utc is null
      and par.settled_at_utc is null
      and (pbi.id is null or coalesce(pbi.is_voided, false) = false)
      and upper(btrim(coalesce(
        pbi.item_type,
        case
          when pa.case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum then 'OVERPAYMENT_RECOVERY'
          when pa.case_type = 'UNDERPAYMENT'::public.pay_finance_case_type_enum then 'UNDERPAYMENT_PAYMENT'
          else null
        end,
        ''
      ))) in ('OVERPAYMENT_RECOVERY', 'UNDERPAYMENT_PAYMENT')
  ),
  finance_component_movements as (
    select
      fcmr.candidate_id,
      fcmr.timesheet_id,
      fcmr.component_key_type,
      fcmr.component_key_value,
      round(coalesce(sum(fcmr.movement_amount_ex) filter (where fcmr.item_type = 'OVERPAYMENT_RECOVERY' and fcmr.is_settled_movement), 0), 2)::numeric(12,2) as settled_overpayment_recovery_ex,
      round(coalesce(sum(fcmr.movement_amount_ex) filter (where fcmr.item_type = 'OVERPAYMENT_RECOVERY' and fcmr.is_active_reservation), 0), 2)::numeric(12,2) as reserved_overpayment_recovery_ex,
      round(coalesce(sum(fcmr.movement_amount_ex) filter (where fcmr.item_type = 'UNDERPAYMENT_PAYMENT' and fcmr.is_settled_movement), 0), 2)::numeric(12,2) as settled_underpayment_payment_ex,
      round(coalesce(sum(fcmr.movement_amount_ex) filter (where fcmr.item_type = 'UNDERPAYMENT_PAYMENT' and fcmr.is_active_reservation), 0), 2)::numeric(12,2) as reserved_underpayment_payment_ex,
      true as has_finance_movement
    from finance_component_movements_raw fcmr
    where fcmr.component_key_type is not null
      and fcmr.component_key_value is not null
    group by fcmr.candidate_id, fcmr.timesheet_id, fcmr.component_key_type, fcmr.component_key_value
  ),
  timesheet_exploded_with_signed_balance as (
    select
      tec.*,
      coalesce(fcm.settled_overpayment_recovery_ex, 0) as settled_overpayment_recovery_ex,
      coalesce(fcm.reserved_overpayment_recovery_ex, 0) as reserved_overpayment_recovery_ex,
      coalesce(fcm.settled_underpayment_payment_ex, 0) as settled_underpayment_payment_ex,
      coalesce(fcm.reserved_underpayment_payment_ex, 0) as reserved_underpayment_payment_ex,
      coalesce(fcm.has_finance_movement, false) as has_finance_movement,
      case
        /* The authoritative pre-draft component amount is already the canonical
           live-truth minus settled-baseline minus active-reservation balance.
           Reapplying finance movements here would double count them. */
        when upper(btrim(coalesce(
               tec.component_json->>'overpayment_component_authority',
               ''
             ))) = 'PRE_DRAFT_LIVE_TRUTH'
          then round(coalesce(tec.component_amount_ex, 0), 2)::numeric(12,2)
        else round(
          coalesce(tec.component_amount_ex, 0)
          + coalesce(fcm.settled_overpayment_recovery_ex, 0)
          + coalesce(fcm.reserved_overpayment_recovery_ex, 0)
          - coalesce(fcm.settled_underpayment_payment_ex, 0)
          - coalesce(fcm.reserved_underpayment_payment_ex, 0),
          2
        )::numeric(12,2)
      end as signed_component_amount_ex
    from timesheet_exploded_components tec
    left join finance_component_movements fcm
      on fcm.candidate_id = tec.candidate_id
     and fcm.timesheet_id = tec.timesheet_id
     and fcm.component_key_type = tec.component_key_type
     and fcm.component_key_value = tec.component_key_value
  ),
  timesheet_case_rollup as (
    select
      tec.candidate_id,
      tec.timesheet_id,
      min(tec.client_id::text)::uuid as client_id,
      min(tec.linked_shift_date) as linked_shift_date,
      min(tec.corrected_amount_ex) as corrected_amount_ex,
      min(tec.baseline_signature) as baseline_signature,
      min(tec.candidate_pay_method) as candidate_pay_method,
      bool_or(tec.case_is_blocked) as case_is_blocked,
      bool_or(coalesce(tec.has_finance_movement, false)) as has_finance_movement,
      round(coalesce(sum(case when tec.signed_component_amount_ex < 0 and tec.component_key_type is not null and tec.component_key_value is not null then abs(tec.signed_component_amount_ex) else 0 end), 0), 2)::numeric(12,2) as overpayment_amount_ex,
      round(coalesce(sum(case when tec.signed_component_amount_ex > 0 and tec.component_key_type is not null and tec.component_key_value is not null then tec.signed_component_amount_ex else 0 end), 0), 2)::numeric(12,2) as underpayment_amount_ex,
      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'candidate_id', tec.candidate_id::text,
            'client_id', case when tec.client_id is null then null else tec.client_id::text end,
            'linked_timesheet_id', tec.timesheet_id::text,
            'source_family_key', coalesce(nullif(btrim(coalesce(tec.component_json->>'source_family_key', '')), ''), 'timesheet:' || tec.timesheet_id::text),
            'component_key_type', tec.component_key_type,
            'component_key_value', tec.component_key_value,
            'classification', CASE
              WHEN upper(btrim(coalesce(tec.component_json->>'classification', ''))) IN ('TAXABLE_CHANNEL_SENSITIVE','REIMBURSEMENT_GROSS_FIXED','NET_PAY_FIXED_RECOVERY')
                THEN upper(btrim(coalesce(tec.component_json->>'classification', '')))
              WHEN tec.component_key_type = 'EXPENSE_CODE'
                THEN 'REIMBURSEMENT_GROSS_FIXED'
              ELSE 'TAXABLE_CHANNEL_SENSITIVE'
            END,
            'source_pay_method', coalesce(nullif(btrim(coalesce(tec.component_json->>'source_pay_method', '')), ''), tec.candidate_pay_method),
            'current_target_pay_method', tec.candidate_pay_method,
            'source_basis_json', CASE
              WHEN jsonb_typeof(tec.component_json->'source_basis_json') = 'object'
                   AND coalesce(tec.component_json->'source_basis_json', '{}'::jsonb) <> '{}'::jsonb
                THEN tec.component_json->'source_basis_json'
              ELSE jsonb_strip_nulls(jsonb_build_object(
                'linked_timesheet_id', tec.timesheet_id::text,
                'source_family_key', coalesce(nullif(btrim(coalesce(tec.component_json->>'source_family_key', '')), ''), 'timesheet:' || tec.timesheet_id::text),
                'component_key_type', tec.component_key_type,
                'component_key_value', tec.component_key_value,
                'source_pay_method', coalesce(nullif(btrim(coalesce(tec.component_json->>'source_pay_method', '')), ''), tec.candidate_pay_method),
                'component_amount_ex_vat', abs(tec.signed_component_amount_ex)
              ))
            END,
            'source_amount', abs(tec.signed_component_amount_ex),
            'overpayment_component_authority', NULLIF(UPPER(BTRIM(COALESCE(
              tec.component_json->>'overpayment_component_authority',
              ''
            ))), ''),
            'remaining_source_amount', CASE
              WHEN upper(btrim(coalesce(
                     tec.component_json->>'overpayment_component_authority',
                     ''
                   ))) = 'PRE_DRAFT_LIVE_TRUTH'
                THEN abs(tec.signed_component_amount_ex)
              ELSE NULL
            END,
            'allocation_priority_group', case when tec.component_json->>'classification' = 'TAXABLE_CHANNEL_SENSITIVE' then 0 else 1 end,
            'allocation_priority_order', tec.component_order
          )
          order by coalesce(tec.component_json->>'classification',''), coalesce(tec.component_json->>'component_key_type',''), coalesce(tec.component_json->>'component_key_value','')
        ) filter (where tec.signed_component_amount_ex < 0 and tec.component_key_type is not null and tec.component_key_value is not null),
        '[]'::jsonb
      ) as overpayment_components_json,
      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'candidate_id', tec.candidate_id::text,
            'client_id', case when tec.client_id is null then null else tec.client_id::text end,
            'linked_timesheet_id', tec.timesheet_id::text,
            'source_family_key', coalesce(nullif(btrim(coalesce(tec.component_json->>'source_family_key', '')), ''), 'timesheet:' || tec.timesheet_id::text),
            'component_key_type', tec.component_key_type,
            'component_key_value', tec.component_key_value,
            'classification', CASE
              WHEN upper(btrim(coalesce(tec.component_json->>'classification', ''))) IN ('TAXABLE_CHANNEL_SENSITIVE','REIMBURSEMENT_GROSS_FIXED','NET_PAY_FIXED_RECOVERY')
                THEN upper(btrim(coalesce(tec.component_json->>'classification', '')))
              WHEN tec.component_key_type = 'EXPENSE_CODE'
                THEN 'REIMBURSEMENT_GROSS_FIXED'
              ELSE 'TAXABLE_CHANNEL_SENSITIVE'
            END,
            'source_pay_method', coalesce(nullif(btrim(coalesce(tec.component_json->>'source_pay_method', '')), ''), tec.candidate_pay_method),
            'current_target_pay_method', tec.candidate_pay_method,
            'source_basis_json', CASE
              WHEN jsonb_typeof(tec.component_json->'source_basis_json') = 'object'
                   AND coalesce(tec.component_json->'source_basis_json', '{}'::jsonb) <> '{}'::jsonb
                THEN tec.component_json->'source_basis_json'
              ELSE jsonb_strip_nulls(jsonb_build_object(
                'linked_timesheet_id', tec.timesheet_id::text,
                'source_family_key', coalesce(nullif(btrim(coalesce(tec.component_json->>'source_family_key', '')), ''), 'timesheet:' || tec.timesheet_id::text),
                'component_key_type', tec.component_key_type,
                'component_key_value', tec.component_key_value,
                'source_pay_method', coalesce(nullif(btrim(coalesce(tec.component_json->>'source_pay_method', '')), ''), tec.candidate_pay_method),
                'component_amount_ex_vat', abs(tec.signed_component_amount_ex)
              ))
            END,
            'source_amount', abs(tec.signed_component_amount_ex),
            'overpayment_component_authority', NULLIF(UPPER(BTRIM(COALESCE(
              tec.component_json->>'overpayment_component_authority',
              ''
            ))), ''),
            'remaining_source_amount', CASE
              WHEN upper(btrim(coalesce(
                     tec.component_json->>'overpayment_component_authority',
                     ''
                   ))) = 'PRE_DRAFT_LIVE_TRUTH'
                THEN abs(tec.signed_component_amount_ex)
              ELSE NULL
            END,
            'allocation_priority_group', case when tec.component_json->>'classification' = 'TAXABLE_CHANNEL_SENSITIVE' then 0 else 1 end,
            'allocation_priority_order', tec.component_order
          )
          order by coalesce(tec.component_json->>'classification',''), coalesce(tec.component_json->>'component_key_type',''), coalesce(tec.component_json->>'component_key_value','')
        ) filter (where tec.signed_component_amount_ex > 0 and tec.component_key_type is not null and tec.component_key_value is not null),
        '[]'::jsonb
      ) as underpayment_components_json
    from timesheet_exploded_with_signed_balance tec
    group by tec.candidate_id, tec.timesheet_id
  ),
  active_linked_underpayment_cases as (
    select
      pa.candidate_id,
      pa.linked_timesheet_id as timesheet_id,
      true as has_existing_active_underpayment_case
    from public.pay_advances pa
    where pa.case_type = 'UNDERPAYMENT'::public.pay_finance_case_type_enum
      and pa.linked_timesheet_id is not null
      and upper(coalesce(pa.status::text, '')) = 'ACTIVE'
      and round(coalesce(pa.outstanding_amount, 0), 2) > 0
    group by pa.candidate_id, pa.linked_timesheet_id
  ),
  timesheet_case_candidates as (
    select
      tcr.candidate_id,
      tcr.timesheet_id,
      tcr.client_id,
      tcr.linked_shift_date,
      tcr.corrected_amount_ex,
      tcr.baseline_signature,
      tcr.candidate_pay_method,
      tcr.case_is_blocked,
      (
        tcr.overpayment_amount_ex > 0
        or (
          tcr.underpayment_amount_ex > 0
          and (
            tcr.case_is_blocked = true
            or coalesce(aluc.has_existing_active_underpayment_case, false) = true
            or coalesce(tcr.has_finance_movement, false) = true
          )
        )
      ) as needs_lifecycle_tracking,
      tcr.overpayment_amount_ex,
      tcr.underpayment_amount_ex,
      case
        when tcr.overpayment_amount_ex > 0 then 'OVERPAYMENT'::public.pay_finance_case_type_enum
        when tcr.underpayment_amount_ex > 0
         and (
           tcr.case_is_blocked = true
           or coalesce(aluc.has_existing_active_underpayment_case, false) = true
           or coalesce(tcr.has_finance_movement, false) = true
         ) then 'UNDERPAYMENT'::public.pay_finance_case_type_enum
        else null::public.pay_finance_case_type_enum
      end as desired_case_type,
      case
        when tcr.overpayment_amount_ex > 0 then 'OVERPAYMENT'::public.pay_advance_kind_enum
        when tcr.underpayment_amount_ex > 0
         and (
           tcr.case_is_blocked = true
           or coalesce(aluc.has_existing_active_underpayment_case, false) = true
           or coalesce(tcr.has_finance_movement, false) = true
         ) then 'UNDERPAYMENT'::public.pay_advance_kind_enum
        else null::public.pay_advance_kind_enum
      end as desired_advance_kind,
      case
        when tcr.overpayment_amount_ex > 0 then 'OVERPAYMENT'::public.pay_advance_reason_enum
        when tcr.underpayment_amount_ex > 0
         and (
           tcr.case_is_blocked = true
           or coalesce(aluc.has_existing_active_underpayment_case, false) = true
           or coalesce(tcr.has_finance_movement, false) = true
         ) then 'UNDERPAYMENT'::public.pay_advance_reason_enum
        else null::public.pay_advance_reason_enum
      end as desired_reason,
      case
        when tcr.overpayment_amount_ex > 0 then round(tcr.corrected_amount_ex + tcr.overpayment_amount_ex, 2)::numeric(12,2)
        when tcr.underpayment_amount_ex > 0
         and (
           tcr.case_is_blocked = true
           or coalesce(aluc.has_existing_active_underpayment_case, false) = true
           or coalesce(tcr.has_finance_movement, false) = true
         ) then round(tcr.corrected_amount_ex - tcr.underpayment_amount_ex, 2)::numeric(12,2)
        else null::numeric(12,2)
      end as source_original_paid_amount,
      case
        when tcr.overpayment_amount_ex > 0 then round(tcr.corrected_amount_ex, 2)::numeric(12,2)
        when tcr.underpayment_amount_ex > 0
         and (
           tcr.case_is_blocked = true
           or coalesce(aluc.has_existing_active_underpayment_case, false) = true
           or coalesce(tcr.has_finance_movement, false) = true
         ) then round(tcr.corrected_amount_ex, 2)::numeric(12,2)
        else null::numeric(12,2)
      end as source_corrected_paid_amount,
      case
        when tcr.overpayment_amount_ex > 0 then tcr.overpayment_components_json
        when tcr.underpayment_amount_ex > 0
         and (
           tcr.case_is_blocked = true
           or coalesce(aluc.has_existing_active_underpayment_case, false) = true
           or coalesce(tcr.has_finance_movement, false) = true
         ) then tcr.underpayment_components_json
        else '[]'::jsonb
      end as components_sync_json,
      1 as candidate_priority
    from timesheet_case_rollup tcr
    left join active_linked_underpayment_cases aluc
      on aluc.candidate_id = tcr.candidate_id
     and aluc.timesheet_id = tcr.timesheet_id
    where tcr.overpayment_amount_ex > 0
       or (
         tcr.underpayment_amount_ex > 0
         and (
           tcr.case_is_blocked = true
           or coalesce(aluc.has_existing_active_underpayment_case, false) = true
           or coalesce(tcr.has_finance_movement, false) = true
         )
       )
  ),
  finance_case_item_rows as (
    select
      cr.candidate_id,
      cr.candidate_pay_method,
      itm.value as item_json,
      nullif(btrim(coalesce(itm.value->>'finance_case_id', '')), '')::uuid as finance_case_id,
      nullif(btrim(coalesce(itm.value->>'timesheet_id', '')), '')::uuid as timesheet_id,
      nullif(btrim(coalesce(itm.value->>'client_id', '')), '')::uuid as client_id,
      nullif(btrim(coalesce(itm.value->>'linked_shift_date', '')), '')::date as linked_shift_date,
      upper(btrim(coalesce(itm.value->>'case_type', ''))) as case_type_text,
      coalesce(itm.value->>'case_is_blocked', 'false')::boolean as case_is_blocked,
      round(abs(coalesce(nullif(itm.value->>'amount_ex_vat', '')::numeric, 0)), 2)::numeric(12,2) as line_amount_ex,
      coalesce(itm.value->'case_components', '[]'::jsonb) as case_components_json
    from candidate_rows cr
    cross join lateral jsonb_array_elements(coalesce(cr.itemisation_json, '[]'::jsonb)) as itm(value)
    where coalesce(itm.value->>'line_type', '') in ('OVERPAYMENT_RECOVERY', 'UNDERPAYMENT_PAYMENT')
      and nullif(btrim(coalesce(itm.value->>'finance_case_id', '')), '') is not null
      and nullif(btrim(coalesce(itm.value->>'timesheet_id', '')), '') is not null
      and (
        coalesce(array_length(p_force_include_timesheet_ids, 1), 0) = 0
        or nullif(btrim(coalesce(itm.value->>'timesheet_id', '')), '')::uuid = any(p_force_include_timesheet_ids)
        or p_force_include_timesheet_ids is null
      )
      and not (
        coalesce(array_length(p_exclude_timesheet_ids, 1), 0) > 0
        and nullif(btrim(coalesce(itm.value->>'timesheet_id', '')), '')::uuid = any(p_exclude_timesheet_ids)
      )
  ),
  finance_case_candidates_raw as (
    select
      fcir.candidate_id,
      fcir.timesheet_id,
      coalesce(fcir.client_id, pa.client_id) as client_id,
      coalesce(fcir.linked_shift_date, pa.linked_shift_date) as linked_shift_date,
      round(coalesce(pa.source_corrected_paid_amount, 0), 2)::numeric(12,2) as corrected_amount_ex,
      pa.baseline_signature,
      fcir.candidate_pay_method,
      fcir.case_is_blocked,
      true as needs_lifecycle_tracking,
      case when pa.case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum then round(coalesce(pa.original_amount, 0), 2)::numeric(12,2) else 0::numeric(12,2) end as overpayment_amount_ex,
      case when pa.case_type = 'UNDERPAYMENT'::public.pay_finance_case_type_enum then round(coalesce(pa.original_amount, 0), 2)::numeric(12,2) else 0::numeric(12,2) end as underpayment_amount_ex,
      pa.case_type as desired_case_type,
      pa.advance_kind as desired_advance_kind,
      pa.reason as desired_reason,
      round(coalesce(pa.source_original_paid_amount, 0), 2)::numeric(12,2) as source_original_paid_amount,
      round(coalesce(pa.source_corrected_paid_amount, 0), 2)::numeric(12,2) as source_corrected_paid_amount,
      coalesce(fcir.case_components_json, '[]'::jsonb) as components_sync_json,
      2 as candidate_priority
    from finance_case_item_rows fcir
    join public.pay_advances pa
      on pa.id = fcir.finance_case_id
    where pa.case_type in ('OVERPAYMENT'::public.pay_finance_case_type_enum, 'UNDERPAYMENT'::public.pay_finance_case_type_enum)
      and pa.linked_timesheet_id = fcir.timesheet_id
      and upper(coalesce(pa.status::text, '')) = 'ACTIVE'
      and round(coalesce(pa.outstanding_amount, 0), 2) > 0
  ),
  combined_case_candidates as (
    select
      tcc.candidate_id,
      tcc.timesheet_id,
      tcc.client_id,
      tcc.linked_shift_date,
      tcc.corrected_amount_ex,
      tcc.baseline_signature,
      tcc.candidate_pay_method,
      tcc.case_is_blocked,
      tcc.needs_lifecycle_tracking,
      tcc.overpayment_amount_ex,
      tcc.underpayment_amount_ex,
      tcc.desired_case_type,
      tcc.desired_advance_kind,
      tcc.desired_reason,
      tcc.source_original_paid_amount,
      tcc.source_corrected_paid_amount,
      tcc.components_sync_json,
      tcc.candidate_priority
    from timesheet_case_candidates tcc

    union all

    select
      fccr.candidate_id,
      fccr.timesheet_id,
      fccr.client_id,
      fccr.linked_shift_date,
      fccr.corrected_amount_ex,
      fccr.baseline_signature,
      fccr.candidate_pay_method,
      fccr.case_is_blocked,
      fccr.needs_lifecycle_tracking,
      fccr.overpayment_amount_ex,
      fccr.underpayment_amount_ex,
      fccr.desired_case_type,
      fccr.desired_advance_kind,
      fccr.desired_reason,
      fccr.source_original_paid_amount,
      fccr.source_corrected_paid_amount,
      fccr.components_sync_json,
      fccr.candidate_priority
    from finance_case_candidates_raw fccr
  ),
  deduped_case_candidates as (
    select
      ccc.candidate_id,
      ccc.timesheet_id,
      ccc.client_id,
      ccc.linked_shift_date,
      ccc.corrected_amount_ex,
      ccc.baseline_signature,
      ccc.candidate_pay_method,
      ccc.case_is_blocked,
      ccc.needs_lifecycle_tracking,
      ccc.overpayment_amount_ex,
      ccc.underpayment_amount_ex,
      ccc.desired_case_type,
      ccc.desired_advance_kind,
      ccc.desired_reason,
      ccc.source_original_paid_amount,
      ccc.source_corrected_paid_amount,
      ccc.components_sync_json
    from (
      select
        ccc_inner.*,
        row_number() over (
          partition by ccc_inner.candidate_id, ccc_inner.timesheet_id
          order by
            ccc_inner.candidate_priority asc,
            case when ccc_inner.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum then 0 else 1 end,
            case when ccc_inner.needs_lifecycle_tracking then 0 else 1 end
        ) as rn
      from combined_case_candidates ccc_inner
    ) ccc
    where ccc.rn = 1
  )
  select
    dcc.candidate_id,
    dcc.timesheet_id,
    dcc.client_id,
    dcc.linked_shift_date,
    dcc.corrected_amount_ex,
    dcc.baseline_signature,
    dcc.candidate_pay_method,
    dcc.case_is_blocked,
    dcc.needs_lifecycle_tracking,
    dcc.overpayment_amount_ex,
    dcc.underpayment_amount_ex,
    dcc.desired_case_type,
    dcc.desired_advance_kind,
    dcc.desired_reason,
    dcc.source_original_paid_amount,
    dcc.source_corrected_paid_amount,
    dcc.components_sync_json
  from deduped_case_candidates dcc
  where dcc.desired_case_type is not null;

  v_correction_rewrite_result :=
    public._ctms_rewrite_sync_correction_cases_v1(
    case
      when nullif(btrim(coalesce(p_mismatch_choices->>'workbench_session_id', '')), '')
        ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      then nullif(btrim(p_mismatch_choices->>'workbench_session_id'), '')::uuid
      else null::uuid
    end,
    coalesce(p_candidate_ids, array[]::uuid[]),
    coalesce(p_force_include_timesheet_ids, array[]::uuid[])
  );

  select coalesce(array_agg(distinct value::uuid order by value::uuid),array[]::uuid[])
  into v_resolution_pending_member_ids
  from jsonb_array_elements_text(
    coalesce(
      v_correction_rewrite_result
        ->'resolution_pending_member_timesheet_ids',
      '[]'::jsonb
    )
  ) pending_member(value);

  select count(*)::int into v_timesheet_case_count from pg_temp.tmp_sync_timesheet_case_candidates;
  select count(*)::int into v_overpayment_case_count from pg_temp.tmp_sync_timesheet_case_candidates where desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum;
  select count(*)::int into v_underpayment_case_count from pg_temp.tmp_sync_timesheet_case_candidates where desired_case_type = 'UNDERPAYMENT'::public.pay_finance_case_type_enum;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'candidate_id', t.candidate_id::text,
        'timesheet_id', t.timesheet_id::text,
        'client_id', case when t.client_id is null then null else t.client_id::text end,
        'linked_shift_date', case when t.linked_shift_date is null then null else t.linked_shift_date::text end,
        'baseline_signature', t.baseline_signature,
        'corrected_amount_ex', t.corrected_amount_ex,
        'case_is_blocked', t.case_is_blocked,
        'desired_case_type', case when t.desired_case_type is null then null else t.desired_case_type::text end,
        'needs_lifecycle_tracking', t.needs_lifecycle_tracking,
        'overpayment_amount_ex', t.overpayment_amount_ex,
        'underpayment_amount_ex', t.underpayment_amount_ex
      )
      order by t.candidate_id::text, t.timesheet_id::text
    ),
    '[]'::jsonb
  ) into v_case_candidates_json
  from pg_temp.tmp_sync_timesheet_case_candidates t;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'candidate_id', t.candidate_id::text,
        'timesheet_id', t.timesheet_id::text,
        'case_type', t.desired_case_type::text,
        'amount_ex', t.overpayment_amount_ex
      )
      order by t.candidate_id::text, t.timesheet_id::text
    ),
    '[]'::jsonb
  ) into v_overpayment_json
  from pg_temp.tmp_sync_timesheet_case_candidates t
  where t.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'candidate_id', t.candidate_id::text,
        'timesheet_id', t.timesheet_id::text,
        'case_type', t.desired_case_type::text,
        'amount_ex', t.underpayment_amount_ex
      )
      order by t.candidate_id::text, t.timesheet_id::text
    ),
    '[]'::jsonb
  ) into v_underpayment_json
  from pg_temp.tmp_sync_timesheet_case_candidates t
  where t.desired_case_type = 'UNDERPAYMENT'::public.pay_finance_case_type_enum;

  for v_target_case_row in
    select
      t.*
    from pg_temp.tmp_sync_timesheet_case_candidates t
    order by t.candidate_id, t.timesheet_id
  loop
    v_selected_event_type := NULL;
    v_selected_reason := NULL;
    v_selected_note := NULL;
    v_case_update_count := 0;

    if v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum then
      v_target_case_amount_ex := round(v_target_case_row.overpayment_amount_ex, 2)::numeric(12,2);
    elsif v_target_case_row.desired_case_type = 'UNDERPAYMENT'::public.pay_finance_case_type_enum then
      v_target_case_amount_ex := round(v_target_case_row.underpayment_amount_ex, 2)::numeric(12,2);
    else
      v_target_case_amount_ex := null;
    end if;

    SELECT EXISTS (
      SELECT 1
      FROM jsonb_array_elements(
        CASE
          WHEN jsonb_typeof(v_target_case_row.components_sync_json) = 'array'
            THEN v_target_case_row.components_sync_json
          ELSE '[]'::jsonb
        END
      ) AS authoritative_component(value)
      WHERE UPPER(BTRIM(COALESCE(
        authoritative_component.value->>'overpayment_component_authority',
        ''
      ))) = 'PRE_DRAFT_LIVE_TRUTH'
    )
    INTO v_target_amount_is_authoritative_outstanding;

    v_case_taxability := NULL;
    v_case_routing_kind := NULL;
    v_case_metadata_component_count := 0;
    IF v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum THEN
      SELECT
        COUNT(*)::integer,
        CASE
          WHEN COUNT(*) = 0 THEN NULL::public.pay_finance_taxability_enum
          WHEN BOOL_AND(COALESCE(normalized_component.classification = 'TAXABLE_CHANNEL_SENSITIVE', false)) THEN 'TAXABLE'::public.pay_finance_taxability_enum
          WHEN BOOL_AND(COALESCE(normalized_component.classification IN ('REIMBURSEMENT_GROSS_FIXED','NET_PAY_FIXED_RECOVERY'), false)) THEN 'NON_TAXABLE'::public.pay_finance_taxability_enum
          ELSE NULL::public.pay_finance_taxability_enum
        END,
        CASE
          WHEN COUNT(*) = 0 THEN NULL::public.pay_finance_routing_kind_enum
          WHEN upper(coalesce(v_target_case_row.candidate_pay_method, '')) = 'PAYE' THEN 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum
          WHEN upper(coalesce(v_target_case_row.candidate_pay_method, '')) = 'UMBRELLA' THEN 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum
          ELSE NULL::public.pay_finance_routing_kind_enum
        END
      INTO
        v_case_metadata_component_count,
        v_case_taxability,
        v_case_routing_kind
      FROM (
        SELECT
          upper(nullif(btrim(coalesce(component_element.value->>'classification', '')), '')) AS classification,
          upper(nullif(btrim(coalesce(
            component_element.value->>'source_pay_method',
            component_element.value->>'current_target_pay_method',
            v_target_case_row.candidate_pay_method,
            ''
          )), '')) AS source_pay_method
        FROM jsonb_array_elements(
          CASE
            WHEN jsonb_typeof(v_target_case_row.components_sync_json) = 'array' THEN v_target_case_row.components_sync_json
            ELSE '[]'::jsonb
          END
        ) AS component_element(value)
      ) AS normalized_component;
    END IF;

    select
      pa.id as finance_case_id,
      pa.case_type as old_case_type,
      pa.status as old_status,
      round(coalesce(pa.original_amount, 0), 2)::numeric(12,2) as old_original_amount,
      round(coalesce(pa.outstanding_amount, 0), 2)::numeric(12,2) as old_outstanding_amount,
      round(coalesce(pa.source_original_paid_amount, 0), 2)::numeric(12,2) as old_source_original_paid_amount,
      round(coalesce(pa.source_corrected_paid_amount, 0), 2)::numeric(12,2) as old_source_corrected_paid_amount,
      pa.linked_shift_date as old_linked_shift_date,
      pa.baseline_signature as old_baseline_signature,
      pa.taxability as old_taxability,
      pa.routing_kind as old_routing_kind,
      pa.written_off_at_utc as old_written_off_at_utc,
      pa.cleared_at_utc as old_cleared_at_utc,
      exists (
        select 1
        from public.pay_finance_case_events sync_safety_events
        where sync_safety_events.finance_case_id = pa.id
          and (
            upper(btrim(coalesce(sync_safety_events.event_type, ''))) like '%WRITE%OFF%'
            or upper(btrim(coalesce(sync_safety_events.event_type, ''))) in (
              'MANUAL_ECONOMIC_OVERRIDE',
              'MANUAL_WRITE_OFF',
              'CASE_MANUAL_ECONOMIC_OVERRIDE',
              'COMPONENT_MANUAL_ECONOMIC_OVERRIDE'
            )
            or upper(btrim(coalesce(sync_safety_events.reason, ''))) in (
              'MANUAL_ECONOMIC_OVERRIDE',
              'WRITE_OFF',
              'COMPONENT_MANUAL_ECONOMIC_OVERRIDE'
            )
          )
      ) as old_has_manual_or_restructure_event,
      exists (
        select 1
        from public.pay_finance_case_events automatic_clear_event
        where automatic_clear_event.finance_case_id = pa.id
          and (
            (
              upper(btrim(coalesce(automatic_clear_event.event_type, ''))) = 'CASE_CLEARED'
              and lower(btrim(coalesce(automatic_clear_event.reason, ''))) = 'rail_settlement'
            )
            or (
              upper(btrim(coalesce(automatic_clear_event.event_type, ''))) = 'CLEARED'
              and upper(btrim(coalesce(automatic_clear_event.reason, ''))) = 'PREVIEW_FINANCE_SYNC'
            )
          )
      ) as old_has_automatic_reconcilable_clear,
      round(coalesce((
        select sum(abs(coalesce(
          settled_reservation.reserved_source_amount,
          public._pay_batch_item_source_reservation_amount_ex_vat(settled_item.id),
          settled_item.frozen_source_amount,
          settled_item.amount_ex_vat,
          settled_item.amount_inc_vat,
          settled_reservation.reserved_amount,
          0
        )))
        from public.pay_batch_items as settled_item
        join public.pay_batch_candidates as settled_candidate
          on settled_candidate.id = settled_item.pay_batch_candidate_id
        join public.pay_batches as settled_batch
          on settled_batch.id = settled_candidate.pay_batch_id
        left join public.pay_bank_transfers as settled_transfer
          on settled_transfer.id = settled_item.pay_bank_transfer_id
        left join public.pay_advance_reservations as settled_reservation
          on settled_reservation.pay_batch_item_id = settled_item.id
        where coalesce(settled_item.is_voided, false) is not true
          and coalesce(
            settled_reservation.finance_case_id,
            settled_item.finance_case_id,
            case
              when upper(btrim(split_part(coalesce(settled_item.source_ref, ''), ':', 1))) = 'ADVANCE'
               and nullif(btrim(split_part(coalesce(settled_item.source_ref, ''), ':', 2)), '')
                   ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              then nullif(btrim(split_part(coalesce(settled_item.source_ref, ''), ':', 2)), '')::uuid
              else null::uuid
            end
          ) = pa.id
          and (
            (
              v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum
              and upper(btrim(coalesce(settled_item.item_type, ''))) = 'OVERPAYMENT_RECOVERY'
            )
            or (
              v_target_case_row.desired_case_type = 'UNDERPAYMENT'::public.pay_finance_case_type_enum
              and upper(btrim(coalesce(settled_item.item_type, ''))) = 'UNDERPAYMENT_PAYMENT'
            )
          )
          and not exists (
            select 1
            from public.pay_payment_correction_items as settled_correction
            where settled_correction.pay_batch_item_id = settled_item.id
              and settled_correction.status = 'APPLIED'
              and settled_correction.correction_item_kind in (
                'PRE_BANK_CANCEL',
                'NO_MONEY_UNWIND',
                'SETTLED_REVERSAL'
              )
          )
          and (
            upper(btrim(coalesce(settled_candidate.settlement_status, ''))) = 'SETTLED'
            or settled_candidate.settled_at_utc is not null
            or upper(btrim(coalesce(settled_transfer.status, ''))) = 'COMPLETED'
            or settled_transfer.completed_at_utc is not null
            or upper(btrim(coalesce(settled_reservation.status, ''))) = 'SETTLED'
            or settled_reservation.settled_at_utc is not null
          )
      ), 0), 2)::numeric(12,2) as old_active_recovered_amount
    into v_existing_case_row
    from public.pay_advances pa
    where pa.candidate_id = v_target_case_row.candidate_id
      and pa.linked_timesheet_id = v_target_case_row.timesheet_id
      and pa.case_type = v_target_case_row.desired_case_type
    order by
      case when upper(coalesce(pa.status::text,'')) = 'ACTIVE' then 0 else 1 end,
      pa.updated_at desc,
      pa.created_at desc,
      pa.id desc
    limit 1
    for update;

    v_existing_recovered_amount := greatest(
      coalesce(v_existing_case_row.old_active_recovered_amount, 0),
      0
    );

    v_existing_active_reserved_amount := 0::numeric(12,2);

    IF v_existing_case_row.finance_case_id IS NOT NULL THEN
      SELECT ROUND(COALESCE(SUM(ABS(COALESCE(
        advance_reservation.reserved_source_amount,
        advance_reservation.reserved_amount,
        batch_item.frozen_source_amount,
        batch_item.amount_ex_vat,
        batch_item.amount_inc_vat,
        0
      ))), 0), 2)::numeric(12,2)
      INTO v_existing_active_reserved_amount
      FROM public.pay_advance_reservations AS advance_reservation
      LEFT JOIN public.pay_batch_items AS batch_item
        ON batch_item.id = advance_reservation.pay_batch_item_id
      WHERE advance_reservation.finance_case_id = v_existing_case_row.finance_case_id
        AND UPPER(BTRIM(COALESCE(advance_reservation.status, ''))) IN ('RESERVED', 'COMMITTED')
        AND advance_reservation.released_at_utc IS NULL
        AND (batch_item.id IS NULL OR COALESCE(batch_item.is_voided, false) IS NOT TRUE);
    END IF;

    if v_existing_case_row.finance_case_id is not null
       and (
         v_existing_case_row.old_written_off_at_utc is not null
         or (
           v_existing_case_row.old_cleared_at_utc is not null
           and not (
             upper(coalesce(v_existing_case_row.old_status::text, '')) = 'PAID_OFF'
             and coalesce(v_existing_case_row.old_has_automatic_reconcilable_clear, false)
             and coalesce(v_existing_case_row.old_has_manual_or_restructure_event, false) is not true
             and (
               (
                 coalesce(v_target_amount_is_authoritative_outstanding, false)
                 and round(coalesce(v_target_case_amount_ex, 0), 2) > 0
               )
               or (
                 coalesce(v_target_amount_is_authoritative_outstanding, false) is not true
                 and round(
                   coalesce(v_target_case_amount_ex, 0)
                   - coalesce(v_existing_recovered_amount, 0),
                   2
                 ) > 0
               )
             )
           )
         )
         or upper(coalesce(v_existing_case_row.old_status::text,'')) not in ('ACTIVE','PAID_OFF')
         or coalesce(v_existing_case_row.old_has_manual_or_restructure_event, false)
       ) then
      insert into public.pay_finance_case_events (
        finance_case_id,
        event_type,
        event_at_utc,
        actor_user_id,
        pay_batch_id,
        reservation_id,
        before_json,
        after_json,
        reason,
        note
      )
      values (
        v_existing_case_row.finance_case_id,
        'SYNC_SKIPPED',
        now(),
        p_actor_user_id,
        null,
        null,
        jsonb_build_object(
          'case_type', v_existing_case_row.old_case_type::text,
          'status', v_existing_case_row.old_status::text,
          'original_amount', v_existing_case_row.old_original_amount,
          'outstanding_amount', v_existing_case_row.old_outstanding_amount,
          'source_original_paid_amount', v_existing_case_row.old_source_original_paid_amount,
          'source_corrected_paid_amount', v_existing_case_row.old_source_corrected_paid_amount,
          'linked_shift_date', case when v_existing_case_row.old_linked_shift_date is null then null else v_existing_case_row.old_linked_shift_date::text end,
          'baseline_signature', v_existing_case_row.old_baseline_signature,
          'written_off_at_utc', v_existing_case_row.old_written_off_at_utc,
          'cleared_at_utc', v_existing_case_row.old_cleared_at_utc,
          'has_manual_or_restructure_event', v_existing_case_row.old_has_manual_or_restructure_event,
          'has_automatic_reconcilable_clear', v_existing_case_row.old_has_automatic_reconcilable_clear,
          'existing_recovered_amount', v_existing_recovered_amount
        ),
        jsonb_build_object(
          'sync_skipped', true,
          'component_sync_skipped', true,
          'component_authority_preserved', true,
          'target_case_type', case when v_target_case_row.desired_case_type is null then null else v_target_case_row.desired_case_type::text end,
          'target_original_amount', v_target_case_amount_ex,
          'target_source_original_paid_amount', v_target_case_row.source_original_paid_amount,
          'target_source_corrected_paid_amount', v_target_case_row.source_corrected_paid_amount,
          'target_baseline_signature', v_target_case_row.baseline_signature,
          'target_pay_channel_scope', v_scope,
          'workbench_session_id', NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'workbench_session_id', '')), ''),
          'source_build_run_id', NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'source_build_run_id', '')), ''),
          'session_version', NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'session_version', '')), ''),
          'overpayment_sync_scope_digest', NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'overpayment_sync_scope_digest', '')), ''),
          'overpayment_sync_negative_component_digest', NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'overpayment_sync_negative_component_digest', '')), ''),
          'overpayment_sync_settled_baseline_digest', NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'overpayment_sync_settled_baseline_digest', '')), ''),
          'policy_x_authority_scope', NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'policy_x_authority_scope', '')), '')
        ),
        'PREVIEW_FINANCE_SYNC_SKIPPED_PROTECTED_CASE',
        'Skipped case and component synchronisation because the existing case is written-off, cleared, closed, paused, manually resolved, or restructured.'
      );

      /* A protected case must not be inserted into tmp_sync_case_links with an
         empty component payload.  Every row in tmp_sync_case_links is processed
         later by pay_finance_components_sync_from_preview; an empty payload is
         authoritative removal input and can close open components.  The case
         clear pass already excludes protected cases by lifecycle state/event,
         so omitting the link preserves the complete protected case/component
         authority without allowing automatic sync to rewrite it. */
      continue;
    end if;

    IF v_existing_case_row.finance_case_id IS NOT NULL
       AND v_existing_case_row.old_case_type IS DISTINCT FROM v_target_case_row.desired_case_type
       AND COALESCE(v_existing_active_reserved_amount, 0) > 0 THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_ACTIVE_RESERVATION_DIRECTION_CONFLICT'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_ACTIVE_RESERVATION_DIRECTION_CONFLICT',
                'finance_case_id', v_existing_case_row.finance_case_id::text,
                'candidate_id', v_target_case_row.candidate_id::text,
                'timesheet_id', v_target_case_row.timesheet_id::text,
                'existing_case_type', v_existing_case_row.old_case_type::text,
                'target_case_type', v_target_case_row.desired_case_type::text,
                'active_reserved_amount', COALESCE(v_existing_active_reserved_amount, 0),
                'message', 'The finance-case direction cannot change while a frozen recovery or payment reservation remains active. Settle or cancel the active batch before reconciling the opposite direction.'
              )::text;
    END IF;

    IF COALESCE(v_target_amount_is_authoritative_outstanding, false) THEN
      /* PRE_DRAFT_LIVE_TRUTH supplies the canonical amount that remains after
         settled baseline movements and active reservations.  Keep historic
         consumption in the case lifetime total, but do not subtract it from
         the authoritative remaining amount a second time. */
      v_active_reservation_protection_applied := COALESCE(v_existing_active_reserved_amount, 0) > 0
        AND COALESCE(v_target_case_amount_ex, 0) < COALESCE(v_existing_active_reserved_amount, 0);
      v_new_outstanding_amount := GREATEST(
        COALESCE(v_target_case_amount_ex, 0),
        COALESCE(v_existing_active_reserved_amount, 0),
        0
      )::numeric(12,2);
      v_effective_case_amount_ex := ROUND(
        COALESCE(v_existing_recovered_amount, 0) + v_new_outstanding_amount,
        2
      )::numeric(12,2);
    ELSE
      v_active_reservation_protection_applied := COALESCE(v_existing_active_reserved_amount, 0) > 0
        AND COALESCE(v_target_case_amount_ex, 0) < ROUND(COALESCE(v_existing_recovered_amount, 0) + COALESCE(v_existing_active_reserved_amount, 0), 2);
      v_effective_case_amount_ex := GREATEST(
        COALESCE(v_target_case_amount_ex, 0),
        ROUND(COALESCE(v_existing_recovered_amount, 0) + COALESCE(v_existing_active_reserved_amount, 0), 2)
      )::numeric(12,2);
      v_new_outstanding_amount := greatest(v_effective_case_amount_ex - v_existing_recovered_amount, COALESCE(v_existing_active_reserved_amount, 0), 0)::numeric(12,2);
    END IF;

    if v_existing_case_row.finance_case_id is null then
      insert into public.pay_advances (
        candidate_id,
        client_id,
        case_type,
        advance_kind,
        reason,
        linked_timesheet_id,
        linked_shift_date,
        baseline_signature,
        source_original_paid_amount,
        source_corrected_paid_amount,
        original_amount,
        outstanding_amount,
        status,
        created_by,
        updated_at,
        created_at,
        cleared_at_utc,
        cleared_by_user_id,
        write_off_reason,
        written_off_at_utc,
        written_off_by_user_id,
        taxability,
        routing_kind
      )
      values (
        v_target_case_row.candidate_id,
        v_target_case_row.client_id,
        v_target_case_row.desired_case_type,
        v_target_case_row.desired_advance_kind,
        v_target_case_row.desired_reason,
        v_target_case_row.timesheet_id,
        v_target_case_row.linked_shift_date,
        v_target_case_row.baseline_signature,
        v_target_case_row.source_original_paid_amount,
        v_target_case_row.source_corrected_paid_amount,
        v_effective_case_amount_ex,
        v_new_outstanding_amount,
        'ACTIVE'::public.pay_advance_status_enum,
        p_actor_user_id,
        now(),
        now(),
        null,
        null,
        null,
        null,
        null,
        v_case_taxability,
        v_case_routing_kind
      )
      returning id into v_selected_finance_case_id;

      v_cases_inserted := v_cases_inserted + 1;
      v_selected_event_type := 'CREATED';
      v_selected_reason := 'PREVIEW_FINANCE_SYNC';
      v_selected_note := case when v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum then 'Created overpayment finance case from component-aware preview sync' else 'Created lifecycle-tracked underpayment finance case from component-aware preview sync' end;
      v_case_before_json := null;
      v_case_after_json := jsonb_build_object(
        'case_type', v_target_case_row.desired_case_type::text,
        'candidate_id', v_target_case_row.candidate_id::text,
        'linked_timesheet_id', v_target_case_row.timesheet_id::text,
        'linked_shift_date', case when v_target_case_row.linked_shift_date is null then null else v_target_case_row.linked_shift_date::text end,
        'baseline_signature', v_target_case_row.baseline_signature,
        'original_amount', v_effective_case_amount_ex,
        'outstanding_amount', v_new_outstanding_amount,
        'source_original_paid_amount', v_target_case_row.source_original_paid_amount,
        'source_corrected_paid_amount', v_target_case_row.source_corrected_paid_amount,
        'taxability', CASE WHEN v_case_taxability IS NULL THEN NULL ELSE v_case_taxability::text END,
        'routing_kind', CASE WHEN v_case_routing_kind IS NULL THEN NULL ELSE v_case_routing_kind::text END,
        'status', 'ACTIVE'
      )
      || CASE
        WHEN v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum
         AND v_case_metadata_component_count > 0
         AND (v_case_taxability IS NOT NULL OR v_case_routing_kind IS NOT NULL) THEN jsonb_build_object(
          'before_taxability', null,
          'after_taxability', CASE WHEN v_case_taxability IS NULL THEN NULL ELSE v_case_taxability::text END,
          'before_routing_kind', null,
          'after_routing_kind', CASE WHEN v_case_routing_kind IS NULL THEN NULL ELSE v_case_routing_kind::text END,
          'inferred_from_open_components', true
        )
        ELSE '{}'::jsonb
      END;
    else
      v_case_before_json := jsonb_build_object(
        'case_type', v_existing_case_row.old_case_type::text,
        'status', v_existing_case_row.old_status::text,
        'original_amount', v_existing_case_row.old_original_amount,
        'outstanding_amount', v_existing_case_row.old_outstanding_amount,
        'source_original_paid_amount', v_existing_case_row.old_source_original_paid_amount,
        'source_corrected_paid_amount', v_existing_case_row.old_source_corrected_paid_amount,
        'taxability', CASE WHEN v_existing_case_row.old_taxability IS NULL THEN NULL ELSE v_existing_case_row.old_taxability::text END,
        'routing_kind', CASE WHEN v_existing_case_row.old_routing_kind IS NULL THEN NULL ELSE v_existing_case_row.old_routing_kind::text END,
        'linked_shift_date', case when v_existing_case_row.old_linked_shift_date is null then null else v_existing_case_row.old_linked_shift_date::text end,
        'baseline_signature', v_existing_case_row.old_baseline_signature
      )
      || CASE
        WHEN v_existing_case_row.old_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum THEN jsonb_build_object(
          'before_taxability', CASE WHEN v_existing_case_row.old_taxability IS NULL THEN NULL ELSE v_existing_case_row.old_taxability::text END,
          'before_routing_kind', CASE WHEN v_existing_case_row.old_routing_kind IS NULL THEN NULL ELSE v_existing_case_row.old_routing_kind::text END
        )
        ELSE '{}'::jsonb
      END;

      update public.pay_advances pa
      set
        client_id = v_target_case_row.client_id,
        case_type = v_target_case_row.desired_case_type,
        advance_kind = v_target_case_row.desired_advance_kind,
        reason = v_target_case_row.desired_reason,
        linked_shift_date = v_target_case_row.linked_shift_date,
        baseline_signature = v_target_case_row.baseline_signature,
        source_original_paid_amount = v_target_case_row.source_original_paid_amount,
        source_corrected_paid_amount = v_target_case_row.source_corrected_paid_amount,
        original_amount = v_effective_case_amount_ex,
        outstanding_amount = v_new_outstanding_amount,
        status = case when v_new_outstanding_amount > 0 then 'ACTIVE'::public.pay_advance_status_enum else 'PAID_OFF'::public.pay_advance_status_enum end,
        cleared_at_utc = case when v_new_outstanding_amount > 0 then null else coalesce(pa.cleared_at_utc, now()) end,
        cleared_by_user_id = case when v_new_outstanding_amount > 0 then null else coalesce(pa.cleared_by_user_id, p_actor_user_id) end,
        taxability = case
          when v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum and v_case_metadata_component_count > 0 then v_case_taxability
          else pa.taxability
        end,
        routing_kind = case
          when v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum and v_case_metadata_component_count > 0 then v_case_routing_kind
          else pa.routing_kind
        end,
        updated_at = now()
      where pa.id = v_existing_case_row.finance_case_id
        and row(
          pa.client_id,
          pa.case_type,
          pa.advance_kind,
          pa.reason,
          pa.linked_shift_date,
          pa.baseline_signature,
          pa.source_original_paid_amount,
          pa.source_corrected_paid_amount,
          pa.original_amount,
          pa.outstanding_amount,
          pa.status,
          pa.cleared_at_utc,
          pa.cleared_by_user_id,
          pa.taxability,
          pa.routing_kind
        ) is distinct from row(
          v_target_case_row.client_id,
          v_target_case_row.desired_case_type,
          v_target_case_row.desired_advance_kind,
          v_target_case_row.desired_reason,
          v_target_case_row.linked_shift_date,
          v_target_case_row.baseline_signature,
          v_target_case_row.source_original_paid_amount,
          v_target_case_row.source_corrected_paid_amount,
          v_effective_case_amount_ex,
          v_new_outstanding_amount,
          case when v_new_outstanding_amount > 0 then 'ACTIVE'::public.pay_advance_status_enum else 'PAID_OFF'::public.pay_advance_status_enum end,
          case when v_new_outstanding_amount > 0 then null else coalesce(pa.cleared_at_utc, now()) end,
          case when v_new_outstanding_amount > 0 then null else coalesce(pa.cleared_by_user_id, p_actor_user_id) end,
          case
            when v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum and v_case_metadata_component_count > 0 then v_case_taxability
            else pa.taxability
          end,
          case
            when v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum and v_case_metadata_component_count > 0 then v_case_routing_kind
            else pa.routing_kind
          end
        );

      get diagnostics v_case_update_count = row_count;

      v_selected_finance_case_id := v_existing_case_row.finance_case_id;
      v_cases_touched := v_cases_touched + 1;

      if v_case_update_count > 0
         and upper(coalesce(v_existing_case_row.old_status::text,'')) = 'PAID_OFF'
         and v_new_outstanding_amount > 0 then
        v_cases_reopened := v_cases_reopened + 1;
        v_selected_event_type := 'REOPENED';
        v_selected_reason := 'PREVIEW_FINANCE_SYNC';
        v_selected_note := case when v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum then 'Reopened overpayment finance case from component-aware preview sync' else 'Reopened lifecycle-tracked underpayment finance case from component-aware preview sync' end;
      elsif v_case_update_count > 0 then
        v_cases_amended := v_cases_amended + 1;
        v_selected_event_type := 'AMENDED';
        v_selected_reason := 'PREVIEW_FINANCE_SYNC';
        v_selected_note := case when v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum then 'Amended overpayment finance case from component-aware preview sync' else 'Amended lifecycle-tracked underpayment finance case from component-aware preview sync' end;
      end if;

      v_case_after_json := jsonb_build_object(
        'case_type', v_target_case_row.desired_case_type::text,
        'status', case when v_new_outstanding_amount > 0 then 'ACTIVE' else 'PAID_OFF' end,
        'original_amount', v_effective_case_amount_ex,
        'outstanding_amount', v_new_outstanding_amount,
        'source_original_paid_amount', v_target_case_row.source_original_paid_amount,
        'source_corrected_paid_amount', v_target_case_row.source_corrected_paid_amount,
        'taxability', CASE
          WHEN v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum AND v_case_metadata_component_count > 0 THEN CASE WHEN v_case_taxability IS NULL THEN NULL ELSE v_case_taxability::text END
          ELSE CASE WHEN v_existing_case_row.old_taxability IS NULL THEN NULL ELSE v_existing_case_row.old_taxability::text END
        END,
        'routing_kind', CASE
          WHEN v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum AND v_case_metadata_component_count > 0 THEN CASE WHEN v_case_routing_kind IS NULL THEN NULL ELSE v_case_routing_kind::text END
          ELSE CASE WHEN v_existing_case_row.old_routing_kind IS NULL THEN NULL ELSE v_existing_case_row.old_routing_kind::text END
        END,
        'linked_shift_date', case when v_target_case_row.linked_shift_date is null then null else v_target_case_row.linked_shift_date::text end,
        'baseline_signature', v_target_case_row.baseline_signature
      )
      || CASE
        WHEN v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum
         AND v_case_metadata_component_count > 0
         AND (
           v_existing_case_row.old_taxability IS DISTINCT FROM v_case_taxability
           OR v_existing_case_row.old_routing_kind IS DISTINCT FROM v_case_routing_kind
         ) THEN jsonb_build_object(
          'before_taxability', CASE WHEN v_existing_case_row.old_taxability IS NULL THEN NULL ELSE v_existing_case_row.old_taxability::text END,
          'after_taxability', CASE WHEN v_case_taxability IS NULL THEN NULL ELSE v_case_taxability::text END,
          'before_routing_kind', CASE WHEN v_existing_case_row.old_routing_kind IS NULL THEN NULL ELSE v_existing_case_row.old_routing_kind::text END,
          'after_routing_kind', CASE WHEN v_case_routing_kind IS NULL THEN NULL ELSE v_case_routing_kind::text END,
          'inferred_from_open_components', true
        )
        ELSE '{}'::jsonb
      END;
    end if;

    insert into pg_temp.tmp_sync_case_links (
      candidate_id,
      timesheet_id,
      finance_case_id,
      desired_case_type,
      source_original_paid_amount,
      source_corrected_paid_amount,
      case_amount_ex,
      linked_shift_date,
      baseline_signature,
      components_sync_json
    )
    values (
      v_target_case_row.candidate_id,
      v_target_case_row.timesheet_id,
      v_selected_finance_case_id,
      v_target_case_row.desired_case_type,
      v_target_case_row.source_original_paid_amount,
      v_target_case_row.source_corrected_paid_amount,
      COALESCE(v_effective_case_amount_ex, v_target_case_amount_ex),
      v_target_case_row.linked_shift_date,
      v_target_case_row.baseline_signature,
      v_target_case_row.components_sync_json
    )
    on conflict (candidate_id, timesheet_id) do update
    set
      finance_case_id = excluded.finance_case_id,
      desired_case_type = excluded.desired_case_type,
      source_original_paid_amount = excluded.source_original_paid_amount,
      source_corrected_paid_amount = excluded.source_corrected_paid_amount,
      case_amount_ex = excluded.case_amount_ex,
      linked_shift_date = excluded.linked_shift_date,
      baseline_signature = excluded.baseline_signature,
      components_sync_json = excluded.components_sync_json;

    if v_selected_event_type is not null then
    insert into public.pay_finance_case_events (
      finance_case_id,
      event_type,
      event_at_utc,
      actor_user_id,
      pay_batch_id,
      reservation_id,
      before_json,
      after_json,
      reason,
      note
    )
    values (
      v_selected_finance_case_id,
      v_selected_event_type,
      now(),
      p_actor_user_id,
      null,
      null,
      v_case_before_json,
      v_case_after_json,
      v_selected_reason,
      v_selected_note
    );
    end if;

    IF COALESCE(v_active_reservation_protection_applied, false)
       AND NOT EXISTS (
         SELECT 1
         FROM public.pay_finance_case_events AS protection_event
         WHERE protection_event.finance_case_id = v_selected_finance_case_id
           AND protection_event.event_type = 'SYNC_SHRINK_DEFERRED_ACTIVE_RESERVATION'
           AND protection_event.reason = 'PREVIEW_FINANCE_SYNC_ACTIVE_RESERVATION_PROTECTION'
           AND protection_event.before_json IS NOT DISTINCT FROM v_case_before_json
           AND protection_event.after_json = jsonb_build_object(
             'target_case_amount_ex', v_target_case_amount_ex,
             'effective_case_amount_ex', v_effective_case_amount_ex,
             'active_reserved_recovery_amount', v_existing_active_reserved_amount,
             'existing_recovered_amount', v_existing_recovered_amount,
             'outstanding_amount', v_new_outstanding_amount
           )
       ) THEN
      insert into public.pay_finance_case_events (
        finance_case_id,
        event_type,
        event_at_utc,
        actor_user_id,
        pay_batch_id,
        reservation_id,
        before_json,
        after_json,
        reason,
        note
      )
      values (
        v_selected_finance_case_id,
        'SYNC_SHRINK_DEFERRED_ACTIVE_RESERVATION',
        now(),
        p_actor_user_id,
        null,
        null,
        v_case_before_json,
        jsonb_build_object(
          'target_case_amount_ex', v_target_case_amount_ex,
          'effective_case_amount_ex', v_effective_case_amount_ex,
          'active_reserved_recovery_amount', v_existing_active_reserved_amount,
          'existing_recovered_amount', v_existing_recovered_amount,
          'outstanding_amount', v_new_outstanding_amount
        ),
        'PREVIEW_FINANCE_SYNC_ACTIVE_RESERVATION_PROTECTION',
        'Deferred overpayment/underpayment case shrink because an active recovery reservation exists.'
      );
    END IF;
  end loop;

  for v_open_case_candidate in
    select
      pa.id as finance_case_id,
      pa.candidate_id,
      pa.linked_timesheet_id as timesheet_id,
      pa.case_type as old_case_type,
      round(coalesce(pa.original_amount,0),2)::numeric(12,2) as old_original_amount,
      round(coalesce(pa.outstanding_amount,0),2)::numeric(12,2) as old_outstanding_amount,
      round(coalesce(pa.source_original_paid_amount,0),2)::numeric(12,2) as old_source_original_paid_amount,
      round(coalesce(pa.source_corrected_paid_amount,0),2)::numeric(12,2) as old_source_corrected_paid_amount,
      pa.linked_shift_date as old_linked_shift_date,
      pa.baseline_signature as old_baseline_signature
    from public.pay_advances pa
    where pa.case_type in ('OVERPAYMENT'::public.pay_finance_case_type_enum, 'UNDERPAYMENT'::public.pay_finance_case_type_enum)
      and pa.linked_timesheet_id is not null
      and (
        coalesce(array_length(p_candidate_ids, 1), 0) = 0
        or pa.candidate_id = any(p_candidate_ids)
      )
      and (
        p_client_filter_single is null
        or pa.client_id = p_client_filter_single
      )
      and (
        coalesce(array_length(p_force_include_timesheet_ids, 1), 0) = 0
        or pa.linked_timesheet_id = any(p_force_include_timesheet_ids)
        or p_force_include_timesheet_ids is null
      )
      and not (
        coalesce(array_length(p_exclude_timesheet_ids, 1), 0) > 0
        and pa.linked_timesheet_id = any(p_exclude_timesheet_ids)
      )
      and not (
        coalesce(array_length(v_resolution_pending_member_ids, 1), 0) > 0
        and pa.linked_timesheet_id
              = any(v_resolution_pending_member_ids)
      )
      and not exists (
        select 1
        from pg_temp.tmp_sync_case_links l
        where l.finance_case_id = pa.id
      )
      and exists (
        select 1
        from public.candidates c
        where c.id = pa.candidate_id
          and upper(coalesce(c.pay_method,'')) = v_scope
      )
      and upper(coalesce(pa.status::text, '')) = 'ACTIVE'
      and pa.written_off_at_utc is null
      and pa.cleared_at_utc is null
      and not exists (
        select 1
        from public.pay_finance_case_events sync_clear_safety_events
        where sync_clear_safety_events.finance_case_id = pa.id
          and (
            upper(btrim(coalesce(sync_clear_safety_events.event_type, ''))) like '%WRITE%OFF%'
            or upper(btrim(coalesce(sync_clear_safety_events.event_type, ''))) in (
              'MANUAL_ECONOMIC_OVERRIDE',
              'MANUAL_WRITE_OFF',
              'CASE_MANUAL_ECONOMIC_OVERRIDE',
              'COMPONENT_MANUAL_ECONOMIC_OVERRIDE'
            )
            or upper(btrim(coalesce(sync_clear_safety_events.reason, ''))) in (
              'MANUAL_ECONOMIC_OVERRIDE',
              'WRITE_OFF',
              'COMPONENT_MANUAL_ECONOMIC_OVERRIDE'
            )
          )
      )
  loop
    SELECT ROUND(COALESCE(SUM(ABS(COALESCE(advance_reservation.reserved_source_amount, advance_reservation.reserved_amount, batch_item.frozen_source_amount, batch_item.amount_ex_vat, batch_item.amount_inc_vat, 0))), 0), 2)::numeric(12,2)
    INTO v_existing_active_reserved_amount
    FROM public.pay_advance_reservations AS advance_reservation
    LEFT JOIN public.pay_batch_items AS batch_item
      ON batch_item.id = advance_reservation.pay_batch_item_id
    WHERE advance_reservation.finance_case_id = v_open_case_candidate.finance_case_id
      AND UPPER(BTRIM(COALESCE(advance_reservation.status, ''))) IN ('RESERVED', 'COMMITTED')
      AND advance_reservation.released_at_utc IS NULL
      AND (batch_item.id IS NULL OR COALESCE(batch_item.is_voided, false) IS NOT TRUE);

    IF COALESCE(v_existing_active_reserved_amount, 0) > 0 THEN
      IF NOT EXISTS (
        SELECT 1
        FROM public.pay_finance_case_events AS protection_event
        WHERE protection_event.finance_case_id = v_open_case_candidate.finance_case_id
          AND protection_event.event_type = 'SYNC_CLEAR_DEFERRED_ACTIVE_RESERVATION'
          AND protection_event.reason = 'PREVIEW_FINANCE_SYNC_ACTIVE_RESERVATION_PROTECTION'
          AND protection_event.before_json = jsonb_build_object(
            'case_type', v_open_case_candidate.old_case_type::text,
            'status', 'ACTIVE',
            'original_amount', v_open_case_candidate.old_original_amount,
            'outstanding_amount', v_open_case_candidate.old_outstanding_amount
          )
          AND protection_event.after_json = jsonb_build_object(
            'clear_deferred', true,
            'active_reserved_recovery_amount', v_existing_active_reserved_amount
          )
      ) THEN
        insert into public.pay_finance_case_events (
          finance_case_id,
          event_type,
          event_at_utc,
          actor_user_id,
          pay_batch_id,
          reservation_id,
          before_json,
          after_json,
          reason,
          note
        )
        values (
          v_open_case_candidate.finance_case_id,
          'SYNC_CLEAR_DEFERRED_ACTIVE_RESERVATION',
          now(),
          p_actor_user_id,
          null,
          null,
          jsonb_build_object(
            'case_type', v_open_case_candidate.old_case_type::text,
            'status', 'ACTIVE',
            'original_amount', v_open_case_candidate.old_original_amount,
            'outstanding_amount', v_open_case_candidate.old_outstanding_amount
          ),
          jsonb_build_object(
            'clear_deferred', true,
            'active_reserved_recovery_amount', v_existing_active_reserved_amount
          ),
          'PREVIEW_FINANCE_SYNC_ACTIVE_RESERVATION_PROTECTION',
          'Deferred finance case clear because an active recovery reservation exists.'
        );
      END IF;

      CONTINUE;
    END IF;

    insert into pg_temp.tmp_sync_case_clears (
      finance_case_id,
      candidate_id,
      timesheet_id,
      old_case_type,
      old_original_amount,
      old_outstanding_amount,
      old_source_original_paid_amount,
      old_source_corrected_paid_amount,
      old_linked_shift_date,
      old_baseline_signature
    )
    values (
      v_open_case_candidate.finance_case_id,
      v_open_case_candidate.candidate_id,
      v_open_case_candidate.timesheet_id,
      v_open_case_candidate.old_case_type,
      v_open_case_candidate.old_original_amount,
      v_open_case_candidate.old_outstanding_amount,
      v_open_case_candidate.old_source_original_paid_amount,
      v_open_case_candidate.old_source_corrected_paid_amount,
      v_open_case_candidate.old_linked_shift_date,
      v_open_case_candidate.old_baseline_signature
    )
    on conflict (finance_case_id) do nothing;
  end loop;

  for v_existing_case_row in
    select *
    from pg_temp.tmp_sync_case_clears
    order by candidate_id, timesheet_id, finance_case_id
  loop
    update public.pay_advances pa
    set
      status = 'PAID_OFF'::public.pay_advance_status_enum,
      outstanding_amount = 0,
      cleared_at_utc = coalesce(pa.cleared_at_utc, now()),
      cleared_by_user_id = coalesce(pa.cleared_by_user_id, p_actor_user_id),
      updated_at = now()
    where pa.id = v_existing_case_row.finance_case_id;

    insert into public.pay_finance_case_events (
      finance_case_id,
      event_type,
      event_at_utc,
      actor_user_id,
      pay_batch_id,
      reservation_id,
      before_json,
      after_json,
      reason,
      note
    )
    values (
      v_existing_case_row.finance_case_id,
      'CLEARED',
      now(),
      p_actor_user_id,
      null,
      null,
      jsonb_build_object(
        'case_type', v_existing_case_row.old_case_type::text,
        'status', 'ACTIVE',
        'original_amount', v_existing_case_row.old_original_amount,
        'outstanding_amount', v_existing_case_row.old_outstanding_amount,
        'source_original_paid_amount', v_existing_case_row.old_source_original_paid_amount,
        'source_corrected_paid_amount', v_existing_case_row.old_source_corrected_paid_amount,
        'linked_shift_date', case when v_existing_case_row.old_linked_shift_date is null then null else v_existing_case_row.old_linked_shift_date::text end,
        'baseline_signature', v_existing_case_row.old_baseline_signature
      ),
      jsonb_build_object(
        'case_type', v_existing_case_row.old_case_type::text,
        'status', 'PAID_OFF',
        'original_amount', v_existing_case_row.old_original_amount,
        'outstanding_amount', 0,
        'source_original_paid_amount', v_existing_case_row.old_source_original_paid_amount,
        'source_corrected_paid_amount', v_existing_case_row.old_source_corrected_paid_amount,
        'linked_shift_date', case when v_existing_case_row.old_linked_shift_date is null then null else v_existing_case_row.old_linked_shift_date::text end,
        'baseline_signature', v_existing_case_row.old_baseline_signature
      ),
      'PREVIEW_FINANCE_SYNC',
      'Cleared finance case because the current preview no longer requires a persistent lifecycle-tracked overpayment/underpayment header'
    );

    v_components_sync_result := public.pay_finance_components_sync_from_preview(
      v_existing_case_row.finance_case_id,
      '[]'::jsonb,
      p_actor_user_id
    );

    IF jsonb_typeof(COALESCE(v_components_sync_result, '{}'::jsonb)) <> 'object'
       OR LOWER(BTRIM(COALESCE(v_components_sync_result->>'ok', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on') THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_COMPONENT_SYNC_FAILED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_COMPONENT_SYNC_FAILED',
                'finance_case_id', v_existing_case_row.finance_case_id::text,
                'candidate_id', v_existing_case_row.candidate_id::text,
                'timesheet_id', v_existing_case_row.timesheet_id::text,
                'operation', 'CLEAR',
                'component_sync_result', COALESCE(v_components_sync_result, '{}'::jsonb)
              )::text;
    END IF;

    v_cases_cleared := v_cases_cleared + 1;
  end loop;

  for v_target_case_row in
    select l.*
    from pg_temp.tmp_sync_case_links l
    order by l.candidate_id, l.timesheet_id
  loop
    v_components_sync_result := public.pay_finance_components_sync_from_preview(
      v_target_case_row.finance_case_id,
      v_target_case_row.components_sync_json,
      p_actor_user_id
    );

    IF jsonb_typeof(COALESCE(v_components_sync_result, '{}'::jsonb)) <> 'object'
       OR LOWER(BTRIM(COALESCE(v_components_sync_result->>'ok', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on') THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_COMPONENT_SYNC_FAILED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_COMPONENT_SYNC_FAILED',
                'finance_case_id', v_target_case_row.finance_case_id::text,
                'candidate_id', v_target_case_row.candidate_id::text,
                'timesheet_id', v_target_case_row.timesheet_id::text,
                'desired_case_type', v_target_case_row.desired_case_type::text,
                'operation', 'RECONCILE',
                'component_sync_result', COALESCE(v_components_sync_result, '{}'::jsonb)
              )::text;
    END IF;

    SELECT
      round(coalesce(pa.outstanding_amount, 0), 2)::numeric(12,2),
      round(coalesce(sum(coalesce(pfc.remaining_source_amount, 0)) FILTER (WHERE pfc.closed_at_utc IS NULL), 0), 2)::numeric(12,2)
    INTO
      v_component_case_outstanding_amount,
      v_component_open_remaining_total
    FROM public.pay_advances AS pa
    LEFT JOIN public.pay_finance_case_components AS pfc
      ON pfc.finance_case_id = pa.id
    WHERE pa.id = v_target_case_row.finance_case_id
    GROUP BY pa.outstanding_amount;

    v_component_case_mismatch_amount := round(
      coalesce(v_component_case_outstanding_amount, 0) - coalesce(v_component_open_remaining_total, 0),
      2
    )::numeric(12,2);

    IF abs(coalesce(v_component_case_mismatch_amount, 0)) > 0.01 THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_COMPONENT_CASE_RECONCILIATION_FAILED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_COMPONENT_CASE_RECONCILIATION_FAILED',
                'finance_case_id', v_target_case_row.finance_case_id::text,
                'candidate_id', v_target_case_row.candidate_id::text,
                'timesheet_id', v_target_case_row.timesheet_id::text,
                'desired_case_type', v_target_case_row.desired_case_type::text,
                'case_outstanding_amount', coalesce(v_component_case_outstanding_amount, 0),
                'open_component_remaining_total', coalesce(v_component_open_remaining_total, 0),
                'mismatch_amount', coalesce(v_component_case_mismatch_amount, 0),
                'component_sync_result', COALESCE(v_components_sync_result, '{}'::jsonb)
              )::text;
    END IF;

    if v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum then
      v_synced_open_component_count := 0;
      v_synced_case_taxability := NULL;
      v_synced_case_routing_kind := NULL;

      select
        pa.taxability,
        pa.routing_kind
      into
        v_synced_before_taxability,
        v_synced_before_routing_kind
      from public.pay_advances pa
      where pa.id = v_target_case_row.finance_case_id
      limit 1;

      select
        count(*)::integer,
        case
          when count(*) = 0 then null::public.pay_finance_taxability_enum
          when bool_and(pfc.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum) then 'TAXABLE'::public.pay_finance_taxability_enum
          when bool_and(pfc.classification in (
            'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum,
            'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum
          )) then 'NON_TAXABLE'::public.pay_finance_taxability_enum
          else null::public.pay_finance_taxability_enum
        end,
        case
          when count(*) = 0 then null::public.pay_finance_routing_kind_enum
          when v_scope = 'PAYE' then 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum
          when v_scope = 'UMBRELLA' then 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum
          else null::public.pay_finance_routing_kind_enum
        end
      into
        v_synced_open_component_count,
        v_synced_case_taxability,
        v_synced_case_routing_kind
      from public.pay_finance_case_components pfc
      where pfc.finance_case_id = v_target_case_row.finance_case_id
        and pfc.closed_at_utc is null
        and round(coalesce(pfc.remaining_source_amount, 0), 2) > 0;

      if v_synced_open_component_count > 0
         and (v_synced_before_taxability is distinct from v_synced_case_taxability
              or v_synced_before_routing_kind is distinct from v_synced_case_routing_kind) then
        v_taxability_event_before_json := jsonb_build_object(
          'case_type', 'OVERPAYMENT',
          'taxability', case when v_synced_before_taxability is null then null else v_synced_before_taxability::text end,
          'routing_kind', case when v_synced_before_routing_kind is null then null else v_synced_before_routing_kind::text end
        );

        v_taxability_event_after_json := jsonb_build_object(
          'case_type', 'OVERPAYMENT',
          'taxability', case when v_synced_case_taxability is null then null else v_synced_case_taxability::text end,
          'routing_kind', case when v_synced_case_routing_kind is null then null else v_synced_case_routing_kind::text end,
          'before_taxability', case when v_synced_before_taxability is null then null else v_synced_before_taxability::text end,
          'after_taxability', case when v_synced_case_taxability is null then null else v_synced_case_taxability::text end,
          'before_routing_kind', case when v_synced_before_routing_kind is null then null else v_synced_before_routing_kind::text end,
          'after_routing_kind', case when v_synced_case_routing_kind is null then null else v_synced_case_routing_kind::text end,
          'inferred_from_open_components', true
        );

        update public.pay_advances pa
        set
          taxability = v_synced_case_taxability,
          routing_kind = v_synced_case_routing_kind,
          updated_at = now()
        where pa.id = v_target_case_row.finance_case_id;

        insert into public.pay_finance_case_events (
          finance_case_id,
          event_type,
          event_at_utc,
          actor_user_id,
          pay_batch_id,
          reservation_id,
          before_json,
          after_json,
          reason,
          note
        )
        values (
          v_target_case_row.finance_case_id,
          case
            when v_synced_before_taxability is distinct from v_synced_case_taxability
             and v_synced_before_routing_kind is distinct from v_synced_case_routing_kind then 'HEADER_METADATA_INFERRED'
            when v_synced_before_taxability is distinct from v_synced_case_taxability then 'TAXABILITY_INFERRED'
            else 'ROUTING_KIND_INFERRED'
          end,
          now(),
          p_actor_user_id,
          null,
          null,
          v_taxability_event_before_json,
          v_taxability_event_after_json,
          'PREVIEW_FINANCE_SYNC',
          'Inferred overpayment taxability/routing metadata from open finance case components after component sync'
        );
      end if;
    end if;
  end loop;

  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAY_SYNC_OVERPAYMENTS_FROM_PREVIEW_RESULT',
    jsonb_build_object(
      'pay_channel_scope', v_scope,
      'requested_candidate_count', v_requested_candidate_count,
      'preview_candidate_count', v_preview_candidate_count,
      'preview_candidate_coverage_complete', COALESCE(v_missing_candidate_count, 0) = 0,
      'authoritative_timesheet_scope', COALESCE(v_authoritative_timesheet_scope, false),
      'explicit_empty_timesheet_scope', COALESCE(v_explicit_empty_timesheet_scope, false),
      'preview_scope_strategy', v_preview_scope_strategy,
      'overpayment_case_count', v_overpayment_case_count,
      'underpayment_case_count', v_underpayment_case_count,
      'cases_inserted', v_cases_inserted,
      'cases_touched', v_cases_touched,
      'cases_amended', v_cases_amended,
      'cases_reopened', v_cases_reopened,
      'cases_cleared', v_cases_cleared
    ),
    'pay_sync_overpayments',
    COALESCE(p_pay_date::text, 'NO_PAY_DATE'),
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  return jsonb_build_object(
    'ok', true,
    'pay_channel_scope', v_scope,
    'requested_candidate_count', v_requested_candidate_count,
    'preview_candidate_count', v_preview_candidate_count,
    'preview_candidate_coverage_complete', COALESCE(v_missing_candidate_count, 0) = 0,
    'missing_candidate_ids', COALESCE(v_missing_candidate_ids_json, '[]'::jsonb),
    'authoritative_timesheet_scope', COALESCE(v_authoritative_timesheet_scope, false),
    'explicit_empty_timesheet_scope', COALESCE(v_explicit_empty_timesheet_scope, false),
    'preview_scope_strategy', v_preview_scope_strategy,
    'scope_timesheet_ids', COALESCE(to_jsonb(p_force_include_timesheet_ids), '[]'::jsonb),
    'negative_preview_timesheets_count', v_overpayment_case_count,
    'negative_preview_timesheets', v_overpayment_json,
    'underpayment_case_count', v_underpayment_case_count,
    'underpayment_cases', v_underpayment_json,
    'timesheet_finance_case_candidates_count', v_timesheet_case_count,
    'timesheet_finance_case_candidates', v_case_candidates_json,
    'correction_resolution_pending_chain_count',
      coalesce(
        nullif(
          v_correction_rewrite_result
            ->>'resolution_pending_chain_count',
          ''
        )::integer,
        0
      ),
    'correction_resolution_pending_member_timesheet_ids',
      to_jsonb(v_resolution_pending_member_ids),
    'cases_inserted', v_cases_inserted,
    'cases_touched', v_cases_touched,
    'cases_amended', v_cases_amended,
    'cases_reopened', v_cases_reopened,
    'cases_cleared', v_cases_cleared
  );
exception
  when others then
    PERFORM public._imp_debug_audit(
      p_actor_user_id,
      'PAY_SYNC_OVERPAYMENTS_FROM_PREVIEW_ERROR',
      jsonb_build_object(
        'pay_date', p_pay_date,
        'week_ending_cutoff', p_week_ending_cutoff,
        'pay_channel_scope', p_pay_channel_scope,
        'candidate_count', COALESCE(array_length(p_candidate_ids, 1), 0),
        'sqlstate', SQLSTATE,
        'error_message', SQLERRM
      ),
      'pay_sync_overpayments',
      COALESCE(p_pay_date::text, 'NO_PAY_DATE'),
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );
    RAISE;
end;
$function$;

ALTER FUNCTION public.pay_sync_overpayments_from_preview(p_pay_date date, p_week_ending_cutoff date, p_actor_user_id uuid, p_pay_channel_scope text, p_candidate_ids uuid[], p_mismatch_choices jsonb, p_client_filter_single uuid, p_force_include_timesheet_ids uuid[], p_exclude_timesheet_ids uuid[]) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.pay_sync_overpayments_from_preview(p_pay_date date, p_week_ending_cutoff date, p_actor_user_id uuid, p_pay_channel_scope text, p_candidate_ids uuid[], p_mismatch_choices jsonb, p_client_filter_single uuid, p_force_include_timesheet_ids uuid[], p_exclude_timesheet_ids uuid[]) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.pay_sync_overpayments_from_preview(p_pay_date date, p_week_ending_cutoff date, p_actor_user_id uuid, p_pay_channel_scope text, p_candidate_ids uuid[], p_mismatch_choices jsonb, p_client_filter_single uuid, p_force_include_timesheet_ids uuid[], p_exclude_timesheet_ids uuid[]) TO postgres;
GRANT EXECUTE ON FUNCTION public.pay_sync_overpayments_from_preview(p_pay_date date, p_week_ending_cutoff date, p_actor_user_id uuid, p_pay_channel_scope text, p_candidate_ids uuid[], p_mismatch_choices jsonb, p_client_filter_single uuid, p_force_include_timesheet_ids uuid[], p_exclude_timesheet_ids uuid[]) TO service_role;

-- -----------------------------------------------------------------------------
-- public.pay_workbench_enqueue_stage_continuation(p_session_id uuid, p_candidate_id uuid, p_job_type text, p_cursor_json jsonb, p_source_job_id uuid, p_result_json jsonb, p_actor_user_id uuid, p_reason text, p_priority integer, p_limit integer)
-- Installed pg_get_functiondef MD5: 803e138de6df05528ee35ece87357573
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.pay_workbench_enqueue_stage_continuation(p_session_id uuid, p_candidate_id uuid DEFAULT NULL::uuid, p_job_type text DEFAULT NULL::text, p_cursor_json jsonb DEFAULT NULL::jsonb, p_source_job_id uuid DEFAULT NULL::uuid, p_result_json jsonb DEFAULT '{}'::jsonb, p_actor_user_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text, p_priority integer DEFAULT NULL::integer, p_limit integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_scope_row public.banking_pay_workbench_session_scope%ROWTYPE;
  v_source_job_row public.banking_pay_workbench_jobs%ROWTYPE;
  v_job_type text := CASE
    WHEN UPPER(BTRIM(COALESCE(p_job_type, ''))) IN (
      'WORKBENCH_CANDIDATE_SOURCE_BUILD',
      'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK',
      'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE',
      'CANDIDATE_SOURCE_BUILD',
      'CANDIDATE_SOURCE_BUILD_CHUNK',
      'SOURCE_BUILD',
      'SOURCE_BUILD_PAGE',
      'WORKBENCH_SOURCE_BUILD'
    ) THEN 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
    WHEN UPPER(BTRIM(COALESCE(p_job_type, ''))) IN (
      'WORKBENCH_CANDIDATE_DELTA_REFRESH',
      'CANDIDATE_DELTA_REFRESH',
      'DELTA_REFRESH'
    ) THEN 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
    WHEN UPPER(BTRIM(COALESCE(p_job_type, ''))) IN (
      'WORKBENCH_SESSION_CLONE_REBASE',
      'SESSION_CLONE_REBASE',
      'CLONE_REBASE'
    ) THEN 'WORKBENCH_SESSION_CLONE_REBASE'
    ELSE UPPER(BTRIM(COALESCE(p_job_type, '')))
  END;
  v_reason text := COALESCE(NULLIF(BTRIM(COALESCE(p_reason, '')), ''), 'WORKBENCH_STAGE_CONTINUATION');
  v_result_json jsonb := CASE WHEN jsonb_typeof(COALESCE(p_result_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_result_json, '{}'::jsonb) ELSE '{}'::jsonb END;
  v_actor_user_id uuid := p_actor_user_id;
  v_cursor_json jsonb := NULL::jsonb;
  v_cursor_token text := 'none';
  v_session_signature_token text := 'none';
  v_candidate_key text := 'ALL';
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 100);
  v_priority integer := 50;
  v_line_work_action text := NULL::text;
  v_next_recommended_action text := NULL::text;
  v_progress_state text := NULL::text;
  v_scope_status text := NULL::text;
  v_source_job_session_version bigint := NULL::bigint;
  v_payload_core_json jsonb := '{}'::jsonb;
  v_payload_stage_json jsonb := '{}'::jsonb;
  v_payload_cursor_json jsonb := '{}'::jsonb;
  v_payload_source_json jsonb := '{}'::jsonb;
  v_payload_result_summary_json jsonb := '{}'::jsonb;
  v_payload_json jsonb := '{}'::jsonb;
  v_reuse_patch_json jsonb := '{}'::jsonb;
  v_dedupe_key text := NULL::text;
  v_job_id uuid := NULL::uuid;
  v_job_status text := NULL::text;
  v_job_was_inserted boolean := false;
  v_stale_running_seconds integer := 180;
  v_stale_cutoff timestamptz := NULL::timestamptz;
  v_superseded_stale_count integer := 0;
  v_source_build_run_id_token text := 'none';
  v_source_change_seq_token text := 'none';
  v_projection_run_id_token text := 'none';
  v_projection_class text := 'UNKNOWN';
  v_delta_phase text := 'INIT_PREFLIGHT';
  v_delta_write_phase_token text := 'none';
  v_delta_next_phase text := NULL::text;
  v_refresh_scope_kind text := NULL::text;
  v_source_build_allow_full_fallback boolean := false;
  v_pay_channel_scope text := NULL::text;
  v_targeted_timesheet_ids_json jsonb := '[]'::jsonb;
  v_linked_timesheet_ids_json jsonb := '[]'::jsonb;
  v_source_seed_cursor_json jsonb := '{}'::jsonb;
  v_clone_source_session_id_text text := NULL::text;
  v_clone_target_session_id_text text := NULL::text;
  v_clone_mode text := NULL::text;
  v_candidate_cursor_json jsonb := '{}'::jsonb;
  v_feature_flags_json jsonb := '{}'::jsonb;
  v_session_progress_update_applied boolean := false;
  v_session_progress_lock_skipped boolean := false;
  v_session_progress_lock_skip_reason text := NULL::text;
  v_session_progress_update_row_count integer := 0;
  v_original_dedupe_key text := NULL::text;
  v_self_reuse_prevented boolean := false;
  v_self_reuse_retry_count integer := 0;
  v_insert_row_count integer := 0;
  v_live_candidate_source_change_seq bigint := 0;
  v_cursor_source_change_seq bigint := 0;
  v_projection_run_source_change_seq bigint := 0;
  v_effective_continuation_source_seq bigint := 0;
  v_normalised_delta_family_key text := NULL::text;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_SESSION_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_CONTINUATION_SESSION_ID_REQUIRED')::text;
  END IF;

  IF v_job_type = '' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_JOB_TYPE_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_CONTINUATION_JOB_TYPE_REQUIRED', 'session_id', p_session_id::text)::text;
  END IF;

  IF v_job_type NOT IN (
    'WORKBENCH_SESSION_SCOPE_SEED',
    'WORKBENCH_CANDIDATE_SOURCE_BUILD',
    'WORKBENCH_CANDIDATE_DELTA_REFRESH',
    'WORKBENCH_SESSION_CLONE_REBASE',
    'WORKBENCH_CANDIDATE_LINE_WORK_SEED',
    'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS',
    'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_UNSUPPORTED_JOB_TYPE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CONTINUATION_UNSUPPORTED_JOB_TYPE',
              'session_id', p_session_id::text,
              'job_type', v_job_type
            )::text;
  END IF;

  IF p_cursor_json IS NOT NULL AND jsonb_typeof(p_cursor_json) <> 'object' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_CURSOR_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CONTINUATION_CURSOR_MUST_BE_OBJECT',
              'session_id', p_session_id::text,
              'job_type', v_job_type,
              'cursor_type', jsonb_typeof(p_cursor_json)
            )::text;
  END IF;

  SELECT session_row.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_SESSION_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CONTINUATION_SESSION_NOT_FOUND',
              'session_id', p_session_id::text
            )::text;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_session_row.status, ''))) <> 'OPEN'
     OR v_session_row.discarded_at_utc IS NOT NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_SESSION_NOT_OPEN'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CONTINUATION_SESSION_NOT_OPEN',
              'session_id', p_session_id::text,
              'status', v_session_row.status,
              'discarded_at_utc', v_session_row.discarded_at_utc
            )::text;
  END IF;

  v_actor_user_id := COALESCE(v_actor_user_id, v_session_row.actor_user_id);
  v_session_signature_token := md5(COALESCE(v_session_row.session_signature, ''));
  v_stale_running_seconds := 25;
  v_stale_cutoff := v_now - make_interval(secs => v_stale_running_seconds);

  IF p_source_job_id IS NOT NULL THEN
    SELECT source_job.*
    INTO v_source_job_row
    FROM public.banking_pay_workbench_jobs AS source_job
    WHERE source_job.id = p_source_job_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_SOURCE_JOB_NOT_FOUND'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_CONTINUATION_SOURCE_JOB_NOT_FOUND',
                'session_id', p_session_id::text,
                'source_job_id', p_source_job_id::text,
                'job_type', v_job_type
              )::text;
    END IF;

    IF v_source_job_row.session_id IS DISTINCT FROM p_session_id THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_SOURCE_JOB_SESSION_MISMATCH'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_CONTINUATION_SOURCE_JOB_SESSION_MISMATCH',
                'session_id', p_session_id::text,
                'source_job_id', p_source_job_id::text,
                'source_job_session_id', CASE WHEN v_source_job_row.session_id IS NULL THEN NULL ELSE v_source_job_row.session_id::text END,
                'job_type', v_job_type
              )::text;
    END IF;

    IF v_source_job_row.snapshot_run_id IS DISTINCT FROM v_session_row.source_snapshot_run_id THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_SOURCE_JOB_SNAPSHOT_MISMATCH'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_CONTINUATION_SOURCE_JOB_SNAPSHOT_MISMATCH',
                'session_id', p_session_id::text,
                'source_job_id', p_source_job_id::text,
                'source_job_snapshot_run_id', CASE WHEN v_source_job_row.snapshot_run_id IS NULL THEN NULL ELSE v_source_job_row.snapshot_run_id::text END,
                'session_snapshot_run_id', v_session_row.source_snapshot_run_id::text,
                'job_type', v_job_type
              )::text;
    END IF;

    IF COALESCE(v_source_job_row.payload_json->>'session_version', '') ~ '^[0-9]+$' THEN
      v_source_job_session_version := (v_source_job_row.payload_json->>'session_version')::bigint;

      IF COALESCE(v_source_job_session_version, 0) <> COALESCE(v_session_row.version, 0) THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_SOURCE_JOB_SESSION_VERSION_STALE'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_WORKBENCH_CONTINUATION_SOURCE_JOB_SESSION_VERSION_STALE',
                  'session_id', p_session_id::text,
                  'source_job_id', p_source_job_id::text,
                  'source_job_session_version', v_source_job_session_version,
                  'current_session_version', COALESCE(v_session_row.version, 0),
                  'job_type', v_job_type
                )::text;
      END IF;
    END IF;
  END IF;

  v_source_build_run_id_token := COALESCE(
    NULLIF(BTRIM(COALESCE(v_result_json->>'source_build_run_id', '')), ''),
    NULLIF(BTRIM(COALESCE(v_source_job_row.payload_json->>'source_build_run_id', '')), ''),
    NULLIF(BTRIM(COALESCE(v_source_job_row.payload_json#>>'{source_build,source_build_run_id}', '')), ''),
    NULLIF(BTRIM(COALESCE(p_cursor_json->>'source_build_run_id', '')), ''),
    'none'
  );
  v_source_change_seq_token := COALESCE(
    NULLIF(BTRIM(COALESCE(v_result_json->>'source_change_seq', '')), ''),
    NULLIF(BTRIM(COALESCE(v_source_job_row.payload_json->>'source_change_seq', '')), ''),
    NULLIF(BTRIM(COALESCE(v_source_job_row.payload_json->>'source_change_sequence', '')), ''),
    NULLIF(BTRIM(COALESCE(p_cursor_json->>'source_change_seq', '')), ''),
    'none'
  );

  v_projection_run_id_token := COALESCE(
    NULLIF(BTRIM(COALESCE(v_result_json->>'projection_run_id', '')), ''),
    NULLIF(BTRIM(COALESCE(v_result_json#>>'{cursor,projection_run_id}', '')), ''),
    NULLIF(BTRIM(COALESCE(v_result_json#>>'{next_cursor_json,projection_run_id}', '')), ''),
    NULLIF(BTRIM(COALESCE(v_result_json#>>'{next_cursor_json,cursor,projection_run_id}', '')), ''),
    NULLIF(BTRIM(COALESCE(v_source_job_row.payload_json->>'projection_run_id', '')), ''),
    NULLIF(BTRIM(COALESCE(v_source_job_row.payload_json#>>'{cursor,projection_run_id}', '')), ''),
    NULLIF(BTRIM(COALESCE(v_source_job_row.payload_json#>>'{cursor_json,projection_run_id}', '')), ''),
    NULLIF(BTRIM(COALESCE(v_source_job_row.payload_json#>>'{cursor_json,cursor,projection_run_id}', '')), ''),
    NULLIF(BTRIM(COALESCE(p_cursor_json->>'projection_run_id', '')), ''),
    NULLIF(BTRIM(COALESCE(p_cursor_json#>>'{cursor,projection_run_id}', '')), ''),
    'none'
  );
  v_projection_class := COALESCE(
    NULLIF(UPPER(BTRIM(COALESCE(v_result_json->>'projection_class', ''))), ''),
    NULLIF(UPPER(BTRIM(COALESCE(v_source_job_row.payload_json->>'projection_class', ''))), ''),
    NULLIF(UPPER(BTRIM(COALESCE(p_cursor_json->>'projection_class', ''))), ''),
    'UNKNOWN'
  );
  v_delta_phase := COALESCE(
    NULLIF(UPPER(BTRIM(COALESCE(v_result_json->>'next_phase', ''))), ''),
    NULLIF(UPPER(BTRIM(COALESCE(v_result_json->>'phase', ''))), ''),
    NULLIF(UPPER(BTRIM(COALESCE(v_source_job_row.payload_json->>'next_phase', ''))), ''),
    NULLIF(UPPER(BTRIM(COALESCE(v_source_job_row.payload_json->>'phase', ''))), ''),
    NULLIF(UPPER(BTRIM(COALESCE(p_cursor_json->>'phase', ''))), ''),
    'INIT_PREFLIGHT'
  );
  v_delta_next_phase := COALESCE(
    NULLIF(UPPER(BTRIM(COALESCE(v_result_json->>'next_phase', ''))), ''),
    NULLIF(UPPER(BTRIM(COALESCE(v_source_job_row.payload_json->>'next_phase', ''))), ''),
    NULL::text
  );
  v_delta_write_phase_token := COALESCE(
    NULLIF(UPPER(BTRIM(COALESCE(p_cursor_json->>'write_phase', ''))), ''),
    NULLIF(UPPER(BTRIM(COALESCE(v_result_json->>'write_phase', ''))), ''),
    NULLIF(UPPER(BTRIM(COALESCE(v_source_job_row.payload_json->>'write_phase', ''))), ''),
    'none'
  );
  /*
    A source-build result reports two related but different scopes:
      - requested_refresh_scope_kind: the caller's semantic scope for this run;
      - refresh_scope_kind / actual_refresh_scope_kind: the collection strategy used for this page.

    Full-live candidate builds intentionally page through internally targeted timesheet
    sets to avoid large aggregation.  Cursor continuations must preserve the requested
    scope, not the page's actual internal strategy; otherwise a CANDIDATE_FULL_LIVE
    run can be mis-enqueued as TARGETED_TIMESHEETS with no requested ids.
  */
  IF v_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
     AND UPPER(BTRIM(COALESCE(v_reason, ''))) = 'SOURCE_BUILD_CURSOR_CONTINUATION' THEN
    v_refresh_scope_kind := COALESCE(
      NULLIF(UPPER(BTRIM(COALESCE(p_cursor_json->>'requested_refresh_scope_kind', ''))), ''),
      NULLIF(UPPER(BTRIM(COALESCE(v_result_json->>'requested_refresh_scope_kind', ''))), ''),
      NULLIF(UPPER(BTRIM(COALESCE(v_result_json#>>'{source_build_diagnostics,collect,requested_refresh_scope_kind}', ''))), ''),
      NULLIF(UPPER(BTRIM(COALESCE(v_source_job_row.payload_json->>'refresh_scope_kind', ''))), ''),
      NULLIF(UPPER(BTRIM(COALESCE(v_source_job_row.payload_json#>>'{source_build,refresh_scope_kind}', ''))), ''),
      NULLIF(UPPER(BTRIM(COALESCE(v_result_json->>'refresh_scope_kind', ''))), ''),
      NULL::text
    );
  ELSIF v_job_type IN ('WORKBENCH_CANDIDATE_SOURCE_BUILD', 'WORKBENCH_CANDIDATE_LINE_WORK_SEED') THEN
    v_refresh_scope_kind := COALESCE(
      NULLIF(UPPER(BTRIM(COALESCE(v_result_json->>'requested_refresh_scope_kind', ''))), ''),
      NULLIF(UPPER(BTRIM(COALESCE(v_result_json#>>'{source_build_diagnostics,collect,requested_refresh_scope_kind}', ''))), ''),
      NULLIF(UPPER(BTRIM(COALESCE(v_source_job_row.payload_json->>'refresh_scope_kind', ''))), ''),
      NULLIF(UPPER(BTRIM(COALESCE(v_source_job_row.payload_json#>>'{source_build,refresh_scope_kind}', ''))), ''),
      NULLIF(UPPER(BTRIM(COALESCE(p_cursor_json->>'requested_refresh_scope_kind', ''))), ''),
      NULLIF(UPPER(BTRIM(COALESCE(v_result_json->>'refresh_scope_kind', ''))), ''),
      NULL::text
    );
  ELSE
    v_refresh_scope_kind := COALESCE(
      NULLIF(UPPER(BTRIM(COALESCE(v_result_json->>'refresh_scope_kind', ''))), ''),
      NULLIF(UPPER(BTRIM(COALESCE(v_source_job_row.payload_json->>'refresh_scope_kind', ''))), ''),
      NULLIF(UPPER(BTRIM(COALESCE(v_source_job_row.payload_json#>>'{source_build,refresh_scope_kind}', ''))), ''),
      NULLIF(UPPER(BTRIM(COALESCE(p_cursor_json->>'requested_refresh_scope_kind', ''))), ''),
      NULL::text
    );
  END IF;

  IF v_refresh_scope_kind NOT IN ('TARGETED_TIMESHEETS', 'CANDIDATE_FULL_LIVE') THEN
    v_refresh_scope_kind := CASE
      WHEN v_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD' THEN 'CANDIDATE_FULL_LIVE'
      ELSE NULL::text
    END;
  END IF;

  v_pay_channel_scope := COALESCE(
    NULLIF(UPPER(BTRIM(COALESCE(v_result_json->>'pay_channel_scope', ''))), ''),
    NULLIF(UPPER(BTRIM(COALESCE(v_source_job_row.payload_json->>'pay_channel_scope', ''))), ''),
    NULLIF(UPPER(BTRIM(COALESCE(v_source_job_row.payload_json#>>'{source_build,pay_channel_scope}', ''))), ''),
    NULL::text
  );

  SELECT scope_arrays.array_json
  INTO v_targeted_timesheet_ids_json
  FROM (
    VALUES
      (10, v_source_job_row.payload_json->'targeted_timesheet_ids_requested'),
      (20, v_source_job_row.payload_json#>'{source_build,targeted_timesheet_ids_requested}'),
      (30, v_source_job_row.payload_json->'targeted_timesheet_ids'),
      (40, v_source_job_row.payload_json#>'{source_build,targeted_timesheet_ids}'),
      (50, v_result_json->'targeted_timesheet_ids_requested'),
      (60, v_result_json#>'{source_build,targeted_timesheet_ids_requested}'),
      (70, v_result_json->'targeted_timesheet_ids'),
      (80, v_result_json#>'{source_build,targeted_timesheet_ids}'),
      (90, p_cursor_json->'targeted_timesheet_ids')
  ) AS scope_arrays(priority, array_json)
  WHERE jsonb_typeof(scope_arrays.array_json) = 'array'
    AND jsonb_array_length(scope_arrays.array_json) > 0
  ORDER BY scope_arrays.priority
  LIMIT 1;

  v_targeted_timesheet_ids_json := COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb);

  SELECT scope_arrays.array_json
  INTO v_linked_timesheet_ids_json
  FROM (
    VALUES
      (10, v_source_job_row.payload_json->'linked_timesheet_ids_requested'),
      (20, v_source_job_row.payload_json#>'{source_build,linked_timesheet_ids_requested}'),
      (30, v_source_job_row.payload_json->'linked_timesheet_ids'),
      (40, v_source_job_row.payload_json#>'{source_build,linked_timesheet_ids}'),
      (50, v_result_json->'linked_timesheet_ids_requested'),
      (60, v_result_json#>'{source_build,linked_timesheet_ids_requested}'),
      (70, v_result_json->'linked_timesheet_ids'),
      (80, v_result_json#>'{source_build,linked_timesheet_ids}'),
      (90, p_cursor_json->'linked_timesheet_ids')
  ) AS scope_arrays(priority, array_json)
  WHERE jsonb_typeof(scope_arrays.array_json) = 'array'
    AND jsonb_array_length(scope_arrays.array_json) > 0
  ORDER BY scope_arrays.priority
  LIMIT 1;

  v_linked_timesheet_ids_json := COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb);

  IF v_job_type IN ('WORKBENCH_CANDIDATE_SOURCE_BUILD', 'WORKBENCH_CANDIDATE_LINE_WORK_SEED')
     AND v_refresh_scope_kind = 'CANDIDATE_FULL_LIVE' THEN
    v_targeted_timesheet_ids_json := '[]'::jsonb;
    v_linked_timesheet_ids_json := '[]'::jsonb;
  END IF;


  IF v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
     AND p_candidate_id IS NOT NULL THEN
    SELECT COALESCE(change_counter.seq, 0)
    INTO v_live_candidate_source_change_seq
    FROM public.app_change_counters AS change_counter
    WHERE change_counter.entity_key = 'pay_candidate:' || p_candidate_id::text;

    v_cursor_source_change_seq := GREATEST(
      COALESCE(CASE WHEN COALESCE(p_cursor_json->>'source_change_seq', '') ~ '^\d{1,18}$' THEN (p_cursor_json->>'source_change_seq')::bigint END, 0),
      COALESCE(CASE WHEN COALESCE(p_cursor_json->>'source_change_sequence', '') ~ '^\d{1,18}$' THEN (p_cursor_json->>'source_change_sequence')::bigint END, 0),
      COALESCE(CASE WHEN COALESCE(p_cursor_json#>>'{cursor,source_change_seq}', '') ~ '^\d{1,18}$' THEN (p_cursor_json#>>'{cursor,source_change_seq}')::bigint END, 0),
      COALESCE(CASE WHEN COALESCE(p_cursor_json#>>'{cursor_json,source_change_seq}', '') ~ '^\d{1,18}$' THEN (p_cursor_json#>>'{cursor_json,source_change_seq}')::bigint END, 0),
      COALESCE(CASE WHEN COALESCE(p_cursor_json#>>'{cursor_json,cursor,source_change_seq}', '') ~ '^\d{1,18}$' THEN (p_cursor_json#>>'{cursor_json,cursor,source_change_seq}')::bigint END, 0),
      COALESCE(CASE WHEN COALESCE(v_result_json#>>'{cursor,source_change_seq}', '') ~ '^\d{1,18}$' THEN (v_result_json#>>'{cursor,source_change_seq}')::bigint END, 0),
      COALESCE(CASE WHEN COALESCE(v_result_json#>>'{next_cursor_json,source_change_seq}', '') ~ '^\d{1,18}$' THEN (v_result_json#>>'{next_cursor_json,source_change_seq}')::bigint END, 0),
      COALESCE(CASE WHEN COALESCE(v_result_json#>>'{next_cursor_json,cursor,source_change_seq}', '') ~ '^\d{1,18}$' THEN (v_result_json#>>'{next_cursor_json,cursor,source_change_seq}')::bigint END, 0),
      COALESCE(CASE WHEN COALESCE(v_source_job_row.payload_json#>>'{cursor,source_change_seq}', '') ~ '^\d{1,18}$' THEN (v_source_job_row.payload_json#>>'{cursor,source_change_seq}')::bigint END, 0),
      COALESCE(CASE WHEN COALESCE(v_source_job_row.payload_json#>>'{cursor_json,source_change_seq}', '') ~ '^\d{1,18}$' THEN (v_source_job_row.payload_json#>>'{cursor_json,source_change_seq}')::bigint END, 0),
      COALESCE(CASE WHEN COALESCE(v_source_job_row.payload_json#>>'{cursor_json,cursor,source_change_seq}', '') ~ '^\d{1,18}$' THEN (v_source_job_row.payload_json#>>'{cursor_json,cursor,source_change_seq}')::bigint END, 0),
      COALESCE(CASE WHEN v_source_change_seq_token ~ '^\d{1,18}$' THEN v_source_change_seq_token::bigint END, 0)
    );

    IF v_projection_run_id_token ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      SELECT COALESCE(projection_run.source_change_seq, 0)
      INTO v_projection_run_source_change_seq
      FROM public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run
      WHERE projection_run.id = v_projection_run_id_token::uuid;
    END IF;

    v_effective_continuation_source_seq := GREATEST(
      COALESCE(CASE WHEN v_source_change_seq_token ~ '^\d{1,18}$' THEN v_source_change_seq_token::bigint END, 0),
      COALESCE(v_cursor_source_change_seq, 0),
      COALESCE(v_projection_run_source_change_seq, 0)
    );

    v_normalised_delta_family_key := COALESCE(
      NULLIF(BTRIM(COALESCE(v_result_json->>'normalised_delta_family_key', '')), ''),
      NULLIF(BTRIM(COALESCE(v_result_json->>'delta_family_key', '')), ''),
      NULLIF(BTRIM(COALESCE(v_result_json->>'delta_coalescing_key', '')), ''),
      NULLIF(BTRIM(COALESCE(v_source_job_row.payload_json->>'normalised_delta_family_key', '')), ''),
      NULLIF(BTRIM(COALESCE(v_source_job_row.payload_json->>'delta_family_key', '')), ''),
      NULLIF(BTRIM(COALESCE(v_source_job_row.payload_json->>'delta_coalescing_key', '')), ''),
      NULL::text
    );

    IF (
      (COALESCE(v_cursor_source_change_seq, 0) > 0 AND COALESCE(v_live_candidate_source_change_seq, 0) > COALESCE(v_cursor_source_change_seq, 0))
      OR (COALESCE(v_projection_run_source_change_seq, 0) > 0 AND COALESCE(v_live_candidate_source_change_seq, 0) > COALESCE(v_projection_run_source_change_seq, 0))
      OR (COALESCE(v_cursor_source_change_seq, 0) > 0 AND v_source_change_seq_token ~ '^\d{1,18}$' AND v_source_change_seq_token::bigint > COALESCE(v_cursor_source_change_seq, 0))
      OR (COALESCE(v_projection_run_source_change_seq, 0) > 0 AND v_source_change_seq_token ~ '^\d{1,18}$' AND v_source_change_seq_token::bigint > COALESCE(v_projection_run_source_change_seq, 0))
    ) THEN
      PERFORM public._audit_insert(
        'banking_pay_workbench_job',
        COALESCE(p_source_job_id::text, p_session_id::text || ':' || p_candidate_id::text),
        'CONTINUATION_SUPPRESSED_NEWER_SOURCE_SEQ',
        NULL::jsonb,
        jsonb_build_object(
          'source_job_id', CASE WHEN p_source_job_id IS NULL THEN NULL ELSE p_source_job_id::text END,
          'session_id', p_session_id::text,
          'candidate_id', p_candidate_id::text,
          'job_type', v_job_type,
          'projection_run_id', NULLIF(v_projection_run_id_token, 'none'),
          'normalised_delta_family_key', v_normalised_delta_family_key,
          'cursor_source_change_seq', v_cursor_source_change_seq,
          'projection_run_source_change_seq', v_projection_run_source_change_seq,
          'payload_source_change_seq', CASE WHEN v_source_change_seq_token ~ '^\d{1,18}$' THEN v_source_change_seq_token::bigint ELSE NULL::bigint END,
          'live_candidate_source_change_seq', v_live_candidate_source_change_seq,
          'targeted_timesheet_ids', v_targeted_timesheet_ids_json,
          'linked_timesheet_ids', v_linked_timesheet_ids_json,
          'continuation_not_enqueued', true,
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
        ),
        'CONTINUATION_SUPPRESSED_NEWER_SOURCE_SEQ',
        v_actor_user_id
      );

      RETURN jsonb_build_object(
        'ok', true,
        'job_id', NULL::text,
        'job_type', v_job_type,
        'session_id', p_session_id::text,
        'candidate_id', p_candidate_id::text,
        'source_job_id', CASE WHEN p_source_job_id IS NULL THEN NULL ELSE p_source_job_id::text END,
        'continuation_not_enqueued', true,
        'stale_continuation_suppressed', true,
        'more_due', false,
        'has_more', false,
        'made_progress', true,
        'reason', 'CONTINUATION_SUPPRESSED_NEWER_SOURCE_SEQ',
        'normalised_delta_family_key', v_normalised_delta_family_key,
        'projection_run_id', NULLIF(v_projection_run_id_token, 'none'),
        'cursor_source_change_seq', v_cursor_source_change_seq,
        'projection_run_source_change_seq', v_projection_run_source_change_seq,
        'live_candidate_source_change_seq', v_live_candidate_source_change_seq,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
      );
    END IF;
  END IF;

  v_source_build_allow_full_fallback := LOWER(BTRIM(COALESCE(
    NULLIF(BTRIM(COALESCE(v_result_json->>'source_build_allow_full_fallback', '')), ''),
    NULLIF(BTRIM(COALESCE(v_result_json#>>'{source_build,allow_full_fallback}', '')), ''),
    NULLIF(BTRIM(COALESCE(v_source_job_row.payload_json->>'source_build_allow_full_fallback', '')), ''),
    NULLIF(BTRIM(COALESCE(v_source_job_row.payload_json#>>'{source_build,allow_full_fallback}', '')), ''),
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');

  IF v_job_type = 'WORKBENCH_SESSION_CLONE_REBASE' THEN
    v_clone_source_session_id_text := COALESCE(
      NULLIF(BTRIM(COALESCE(v_result_json->>'source_session_id', '')), ''),
      NULLIF(BTRIM(COALESCE(v_source_job_row.payload_json->>'source_session_id', '')), ''),
      NULLIF(BTRIM(COALESCE(v_source_job_row.payload_json->>'clone_from_session_id', '')), ''),
      NULLIF(BTRIM(COALESCE(p_cursor_json->>'source_session_id', '')), ''),
      NULLIF(BTRIM(COALESCE(p_cursor_json->>'clone_from_session_id', '')), '')
    );
    v_clone_target_session_id_text := COALESCE(
      NULLIF(BTRIM(COALESCE(v_result_json->>'target_session_id', '')), ''),
      NULLIF(BTRIM(COALESCE(v_source_job_row.payload_json->>'target_session_id', '')), ''),
      NULLIF(BTRIM(COALESCE(v_source_job_row.payload_json->>'session_id', '')), ''),
      p_session_id::text
    );
    v_clone_mode := COALESCE(
      NULLIF(UPPER(BTRIM(COALESCE(v_result_json->>'clone_mode', ''))), ''),
      NULLIF(UPPER(BTRIM(COALESCE(v_source_job_row.payload_json->>'clone_mode', ''))), ''),
      NULLIF(UPPER(BTRIM(COALESCE(p_cursor_json->>'clone_mode', ''))), ''),
      'CERTIFIED_SIMPLE_ONLY'
    );
    v_candidate_cursor_json := CASE
      WHEN jsonb_typeof(p_cursor_json->'candidate_cursor') = 'object' THEN COALESCE(p_cursor_json->'candidate_cursor', '{}'::jsonb)
      WHEN jsonb_typeof(v_source_job_row.payload_json->'candidate_cursor') = 'object' THEN COALESCE(v_source_job_row.payload_json->'candidate_cursor', '{}'::jsonb)
      ELSE '{}'::jsonb
    END;
    v_feature_flags_json := CASE
      WHEN jsonb_typeof(v_source_job_row.payload_json->'feature_flags') = 'object' THEN COALESCE(v_source_job_row.payload_json->'feature_flags', '{}'::jsonb)
      WHEN jsonb_typeof(p_cursor_json->'feature_flags') = 'object' THEN COALESCE(p_cursor_json->'feature_flags', '{}'::jsonb)
      ELSE '{}'::jsonb
    END;
  END IF;

  IF v_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
     AND v_refresh_scope_kind = 'TARGETED_TIMESHEETS'
     AND jsonb_array_length(COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb)) = 0
     AND jsonb_array_length(COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb)) = 0
     AND COALESCE(v_source_build_allow_full_fallback, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_TARGETED_IDS_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CONTINUATION_TARGETED_IDS_REQUIRED',
              'session_id', p_session_id::text,
              'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
              'job_type', v_job_type,
              'source_job_id', CASE WHEN p_source_job_id IS NULL THEN NULL ELSE p_source_job_id::text END,
              'reason', v_reason,
              'refresh_scope_kind', v_refresh_scope_kind,
              'cursor_requested_refresh_scope_kind', NULLIF(UPPER(BTRIM(COALESCE(p_cursor_json->>'requested_refresh_scope_kind', ''))), ''),
              'message', 'Refusing to enqueue TARGETED_TIMESHEETS source-build continuation without targeted_timesheet_ids or linked_timesheet_ids.'
            )::text;
  END IF;
  v_source_seed_cursor_json := jsonb_strip_nulls(jsonb_build_object(
    'source_build_run_id', NULLIF(v_source_build_run_id_token, 'none'),
    'projection_run_id', NULLIF(v_projection_run_id_token, 'none'),
    'projection_class', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN v_projection_class ELSE NULL::text END,
    'phase', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN v_delta_phase ELSE NULL::text END,
    'source_change_seq', CASE WHEN v_source_change_seq_token ~ '^[0-9]{1,18}$' THEN v_source_change_seq_token::bigint ELSE NULL::bigint END,
    'session_version', COALESCE(v_session_row.version, 0),
    'source_snapshot_run_id', v_session_row.source_snapshot_run_id::text,
    'session_signature', v_session_row.session_signature,
    'source_row_cursor', 'START'
  ));

  IF v_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
     AND COALESCE(v_source_build_run_id_token, 'none') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_SOURCE_BUILD_RUN_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CONTINUATION_SOURCE_BUILD_RUN_ID_REQUIRED',
              'session_id', p_session_id::text,
              'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
              'job_type', v_job_type,
              'source_job_id', CASE WHEN p_source_job_id IS NULL THEN NULL ELSE p_source_job_id::text END,
              'message', 'WORKBENCH_CANDIDATE_SOURCE_BUILD continuation requires source_build_run_id from result, source payload, or cursor.'
            )::text;
  END IF;

  IF v_job_type = 'WORKBENCH_SESSION_SCOPE_SEED' OR v_job_type = 'WORKBENCH_SESSION_CLONE_REBASE' THEN
    IF p_candidate_id IS NOT NULL THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_SESSION_JOB_CANDIDATE_NOT_ALLOWED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_CONTINUATION_SESSION_JOB_CANDIDATE_NOT_ALLOWED',
                'session_id', p_session_id::text,
                'candidate_id', p_candidate_id::text,
                'job_type', v_job_type
              )::text;
    END IF;

    IF v_job_type = 'WORKBENCH_SESSION_CLONE_REBASE' THEN
      v_line_work_action := 'CLONE_REBASE';
      v_next_recommended_action := 'CLONE_REBASE_CHUNK';
      v_progress_state := 'CLONE_REBASING';
      v_priority := COALESCE(p_priority, 42);
    ELSE
      v_line_work_action := 'SCOPE_SEED';
      v_next_recommended_action := 'SEED_SCOPE_CHUNK';
      v_progress_state := 'REFRESHING_CANDIDATES';
      v_priority := COALESCE(p_priority, 40);
    END IF;
  ELSE
    IF p_candidate_id IS NULL THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_CANDIDATE_ID_REQUIRED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_CONTINUATION_CANDIDATE_ID_REQUIRED',
                'session_id', p_session_id::text,
                'job_type', v_job_type
              )::text;
    END IF;

    SELECT scope_row.*
    INTO v_scope_row
    FROM public.banking_pay_workbench_session_scope AS scope_row
    WHERE scope_row.session_id = p_session_id
      AND scope_row.candidate_id = p_candidate_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_CANDIDATE_NOT_IN_SCOPE'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_CONTINUATION_CANDIDATE_NOT_IN_SCOPE',
                'session_id', p_session_id::text,
                'candidate_id', p_candidate_id::text,
                'job_type', v_job_type
              )::text;
    END IF;

    IF p_source_job_id IS NOT NULL
       AND v_source_job_row.candidate_id IS NOT NULL
       AND v_source_job_row.candidate_id IS DISTINCT FROM p_candidate_id THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_SOURCE_JOB_CANDIDATE_MISMATCH'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_CONTINUATION_SOURCE_JOB_CANDIDATE_MISMATCH',
                'session_id', p_session_id::text,
                'candidate_id', p_candidate_id::text,
                'source_job_id', p_source_job_id::text,
                'source_job_candidate_id', v_source_job_row.candidate_id::text,
                'job_type', v_job_type
              )::text;
    END IF;

    v_candidate_key := p_candidate_id::text;

    IF v_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD' THEN
      v_line_work_action := 'SOURCE_BUILD';
      v_next_recommended_action := 'BUILD_SOURCE_CHUNK';
      v_progress_state := 'REFRESHING_CANDIDATES';
      v_scope_status := 'SOURCE_BUILD_PENDING';
      v_priority := COALESCE(p_priority, 44);
    ELSIF v_job_type = 'WORKBENCH_CANDIDATE_LINE_WORK_SEED' THEN
      v_line_work_action := 'SEED';
      v_next_recommended_action := 'SEED_LINE_WORK_CHUNK';
      v_progress_state := 'REFRESHING_CANDIDATES';
      v_scope_status := CASE
        WHEN UPPER(BTRIM(COALESCE(v_scope_row.status, ''))) = 'PENDING' THEN 'PENDING'
        ELSE 'LINE_WORK_PENDING'
      END;
      v_priority := COALESCE(p_priority, 45);
    ELSIF v_job_type = 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS' THEN
      v_line_work_action := 'PROCESS';
      v_next_recommended_action := 'PROCESS_LINE_WORK_CHUNK';
      v_progress_state := 'PROCESSING_LINE_WORK';
      v_scope_status := 'LINE_WORK_PENDING';
      v_priority := COALESCE(p_priority, 42);
    ELSIF v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN
      v_line_work_action := 'DELTA_REFRESH';
      v_next_recommended_action := 'DELTA_REFRESH_CHUNK';
      v_progress_state := 'DELTA_REFRESHING';
      v_scope_status := 'DELTA_REFRESH_PENDING';
      v_priority := COALESCE(p_priority, 43);
    ELSE
      v_line_work_action := 'MATERIALISE';
      v_next_recommended_action := 'MATERIALISE_PREVIEW_ROWS_CHUNK';
      v_progress_state := 'MATERIALISING_PREVIEW_ROWS';
      v_scope_status := 'LINE_WORK_READY';
      v_priority := COALESCE(p_priority, 41);
    END IF;
  END IF;

  v_priority := LEAST(GREATEST(COALESCE(v_priority, 50), 1), 999);

  IF p_cursor_json IS NOT NULL AND jsonb_typeof(p_cursor_json) = 'object' THEN
    v_cursor_json := p_cursor_json;
    v_cursor_token := md5(p_cursor_json::text);
  ELSE
    v_cursor_json := NULL::jsonb;
    v_cursor_token := 'none';
  END IF;

  IF v_job_type = 'WORKBENCH_SESSION_CLONE_REBASE' THEN
    v_dedupe_key := 'WORKBENCH_SESSION_CLONE_REBASE'
      || ':session:' || p_session_id::text
      || ':source:' || COALESCE(v_clone_source_session_id_text, 'none')
      || ':target:' || COALESCE(v_clone_target_session_id_text, p_session_id::text)
      || ':cursor_hash:' || v_cursor_token;
  ELSIF v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN
    v_dedupe_key := 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
      || ':session:' || p_session_id::text
      || ':candidate:' || COALESCE(v_candidate_key, 'ALL')
      || ':projection_run:' || COALESCE(v_projection_run_id_token, 'none')
      || ':phase:' || COALESCE(v_delta_phase, 'INIT_PREFLIGHT')
      || ':write_phase:' || COALESCE(v_delta_write_phase_token, 'none')
      || ':cursor_hash:' || v_cursor_token;
  ELSE
    v_dedupe_key := 'WORKBENCH_STAGE_CONTINUATION'
      || ':' || v_job_type
      || ':session:' || p_session_id::text
      || ':version:' || COALESCE(v_session_row.version, 0)::text
      || ':snapshot:' || v_session_row.source_snapshot_run_id::text
      || ':signature:' || v_session_signature_token
      || ':candidate:' || COALESCE(v_candidate_key, 'ALL')
      || ':source_build:' || COALESCE(v_source_build_run_id_token, 'none')
      || ':source_change:' || COALESCE(v_source_change_seq_token, 'none')
      || ':cursor:' || v_cursor_token;
  END IF;

  v_payload_core_json := jsonb_build_object(
    'session_id', p_session_id::text,
    'session_version', COALESCE(v_session_row.version, 0),
    'snapshot_run_id', v_session_row.source_snapshot_run_id::text,
    'session_signature', v_session_row.session_signature,
    'session_signature_token', v_session_signature_token,
    'actor_user_id', CASE WHEN v_actor_user_id IS NULL THEN NULL ELSE v_actor_user_id::text END,
    'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
    'candidate_serial_key', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE public._pay_workbench_candidate_serial_key(p_candidate_id) END,
    'candidate_serial_candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
    'candidate_serial_active_chain_id', CASE
      WHEN p_candidate_id IS NULL THEN NULL
      ELSE COALESCE(
        NULLIF(BTRIM(COALESCE(v_source_job_row.payload_json->>'candidate_serial_active_chain_id', '')), ''),
        CASE WHEN p_source_job_id IS NULL THEN NULL ELSE p_source_job_id::text END
      )
    END,
    'candidate_serial_source_job_id', CASE WHEN p_source_job_id IS NULL THEN NULL ELSE p_source_job_id::text END,
    'candidate_serial_reason', 'CANDIDATE_SERIAL_CONTINUATION_QUEUED',
    'candidate_serial_continuation', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE true END,
    'job_type', v_job_type,
    'dedupe_key', v_dedupe_key,
    'continuation', true
  );

  v_payload_stage_json := jsonb_build_object(
    'reason', v_reason,
    'continuation_reason', v_reason,
    'line_work_action', v_line_work_action,
    'next_recommended_action', v_next_recommended_action,
    'limit', v_limit,
    'line_limit', v_limit,
    'chunk_size', v_limit,
    'run_mode', 'BOUNDED_CONTINUATION',
    'source_build_required', v_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
    'line_work_required', v_job_type NOT IN ('WORKBENCH_SESSION_SCOPE_SEED', 'WORKBENCH_SESSION_CLONE_REBASE', 'WORKBENCH_CANDIDATE_SOURCE_BUILD', 'WORKBENCH_CANDIDATE_DELTA_REFRESH'),
    'line_work_only', v_job_type NOT IN ('WORKBENCH_SESSION_SCOPE_SEED', 'WORKBENCH_SESSION_CLONE_REBASE', 'WORKBENCH_CANDIDATE_SOURCE_BUILD', 'WORKBENCH_CANDIDATE_DELTA_REFRESH'),
    'delta_refresh_required', v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
    'clone_rebase_required', v_job_type = 'WORKBENCH_SESSION_CLONE_REBASE'
  );

  v_payload_cursor_json := jsonb_build_object(
    'cursor_json', v_cursor_json,
    'cursor', v_cursor_json,
    'cursor_token', v_cursor_token,
    'has_cursor', v_cursor_json IS NOT NULL
  );

  v_payload_source_json := jsonb_build_object(
    'source_job_id', CASE WHEN p_source_job_id IS NULL THEN NULL ELSE p_source_job_id::text END,
    'source_result_has_more', COALESCE(v_result_json->'has_more', 'false'::jsonb),
    'source_result_next_cursor_present', COALESCE((v_result_json ? 'next_cursor') OR (v_result_json ? 'next_cursor_json') OR (v_result_json ? 'nextCursor'), false),
    'created_by_helper', 'pay_workbench_enqueue_stage_continuation',
    'created_at_utc', v_now::text
  );

  v_payload_result_summary_json := jsonb_build_object(
    'source_result_summary', jsonb_strip_nulls(jsonb_build_object(
      'ok', COALESCE(v_result_json->'ok', 'true'::jsonb),
      'seeded_count', v_result_json->'seeded_count',
      'new_scope_count', v_result_json->'new_scope_count',
      'enqueued_count', v_result_json->'enqueued_count',
      'reused_count', v_result_json->'reused_count',
      'processed_count', v_result_json->'processed_count',
      'ready_count_delta', v_result_json->'ready_count_delta',
      'materialised_count', v_result_json->'materialised_count',
      'materialized_count', v_result_json->'materialized_count',
      'new_preview_row_count', v_result_json->'new_preview_row_count',
      'new_selected_row_count', v_result_json->'new_selected_row_count',
      'source_rows_written', v_result_json->'source_rows_written',
      'current_source_row_count', v_result_json->'current_source_row_count',
      'source_page_count', v_result_json->'source_page_count',
      'timesheets_seen', v_result_json->'timesheets_seen',
      'fallback_used', v_result_json->'fallback_used',
      'cursor_advanced', v_result_json->'cursor_advanced',
      'error_count', v_result_json->'error_count',
      'has_more', v_result_json->'has_more'
    ))
  );

  v_payload_json := jsonb_strip_nulls(
    CASE
      WHEN p_source_job_id IS NOT NULL THEN
        COALESCE(v_source_job_row.payload_json, '{}'::jsonb) - ARRAY[
          'worker_id',
          'worker_claimed_at_utc',
          'worker_lease_seconds',
          'worker_lease_expires_at_utc',
          'worker_function',
          'result_json',
          'completion_json',
          'cursor_json',
          'cursor',
          'next_cursor_json',
          'next_cursor'
        ]::text[]
      ELSE '{}'::jsonb
    END
    || v_payload_core_json
    || v_payload_stage_json
    || v_payload_cursor_json
    || v_payload_source_json
    || v_payload_result_summary_json
    || CASE
      WHEN v_job_type IN ('WORKBENCH_CANDIDATE_SOURCE_BUILD', 'WORKBENCH_CANDIDATE_LINE_WORK_SEED') THEN
        jsonb_build_object(
          'source_build_run_id', NULLIF(v_source_build_run_id_token, 'none'),
          'source_change_seq', CASE WHEN v_source_change_seq_token ~ '^[0-9]{1,18}$' THEN v_source_change_seq_token::bigint ELSE NULL::bigint END,
          'source_change_sequence', CASE WHEN v_source_change_seq_token ~ '^[0-9]{1,18}$' THEN v_source_change_seq_token::bigint ELSE NULL::bigint END,
          'session_version', COALESCE(v_session_row.version, 0),
          'source_snapshot_run_id', v_session_row.source_snapshot_run_id::text,
          'snapshot_run_id', v_session_row.source_snapshot_run_id::text,
          'session_signature', v_session_row.session_signature
        )
        || jsonb_build_object(
          'refresh_scope_kind', v_refresh_scope_kind,
          'targeted_timesheet_ids', COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb),
          'linked_timesheet_ids', COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb),
          'targeted_timesheet_ids_requested', COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb),
          'linked_timesheet_ids_requested', COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb),
          'pay_channel_scope', v_pay_channel_scope,
          'source_build_allow_full_fallback', COALESCE(v_source_build_allow_full_fallback, false),
          'source_build_cursor', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_LINE_WORK_SEED' THEN v_source_seed_cursor_json ELSE v_cursor_json END
        )
        || jsonb_build_object(
          'source_build', jsonb_strip_nulls(
            CASE
              WHEN jsonb_typeof(v_source_job_row.payload_json->'source_build') = 'object'
                THEN COALESCE(v_source_job_row.payload_json->'source_build', '{}'::jsonb)
              ELSE '{}'::jsonb
            END
            || jsonb_build_object(
              'required', v_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
              'run_id', NULLIF(v_source_build_run_id_token, 'none'),
              'source_build_run_id', NULLIF(v_source_build_run_id_token, 'none'),
              'source_change_seq', CASE WHEN v_source_change_seq_token ~ '^[0-9]{1,18}$' THEN v_source_change_seq_token::bigint ELSE NULL::bigint END,
              'source_change_sequence', CASE WHEN v_source_change_seq_token ~ '^[0-9]{1,18}$' THEN v_source_change_seq_token::bigint ELSE NULL::bigint END,
              'session_version', COALESCE(v_session_row.version, 0),
              'source_snapshot_run_id', v_session_row.source_snapshot_run_id::text,
              'session_signature', v_session_row.session_signature,
              'refresh_scope_kind', v_refresh_scope_kind,
              'targeted_timesheet_ids', COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb),
              'linked_timesheet_ids', COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb),
              'targeted_timesheet_ids_requested', COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb),
              'linked_timesheet_ids_requested', COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb),
              'pay_channel_scope', v_pay_channel_scope,
              'allow_full_fallback', COALESCE(v_source_build_allow_full_fallback, false),
              'limit', v_limit,
              'cursor', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_LINE_WORK_SEED' THEN v_source_seed_cursor_json ELSE v_cursor_json END,
              'reason', v_reason
            )
          )
        )
      ELSE '{}'::jsonb
    END
    || CASE
      WHEN v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN
        jsonb_build_object(
          'projection_run_id', NULLIF(v_projection_run_id_token, 'none'),
          'projection_class', v_projection_class,
          'projection_mode', 'DELTA',
          'phase', v_delta_phase,
          'next_phase', v_delta_next_phase,
          'cursor_json', v_cursor_json,
          'targeted_timesheet_ids', COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb),
          'linked_timesheet_ids', COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb),
          'source_change_seq', CASE WHEN v_source_change_seq_token ~ '^[0-9]{1,18}$' THEN v_source_change_seq_token::bigint ELSE NULL::bigint END,
          'source_change_sequence', CASE WHEN v_source_change_seq_token ~ '^[0-9]{1,18}$' THEN v_source_change_seq_token::bigint ELSE NULL::bigint END,
          'latest_source_change_seq', CASE WHEN v_source_change_seq_token ~ '^[0-9]{1,18}$' THEN v_source_change_seq_token::bigint ELSE NULL::bigint END,
          'normalised_delta_family_key', v_normalised_delta_family_key,
          'delta_family_key', v_normalised_delta_family_key,
          'delta_coalescing_key', v_normalised_delta_family_key,
          'source_snapshot_run_id', v_session_row.source_snapshot_run_id::text,
          'delta_refresh_required', true,
          'source_build_required', false,
          'line_work_required', false,
          'legacy_fallback_job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
        )
      ELSE '{}'::jsonb
    END
    || CASE
      WHEN v_job_type = 'WORKBENCH_SESSION_CLONE_REBASE' THEN
        jsonb_build_object(
          'source_session_id', v_clone_source_session_id_text,
          'target_session_id', COALESCE(v_clone_target_session_id_text, p_session_id::text),
          'cursor_json', COALESCE(v_cursor_json, '{}'::jsonb),
          'candidate_cursor', COALESCE(v_candidate_cursor_json, '{}'::jsonb),
          'limit', v_limit,
          'line_limit', v_limit,
          'clone_mode', v_clone_mode,
          'feature_flags', COALESCE(v_feature_flags_json, '{}'::jsonb),
          'clone_rebase_required', true,
          'source_build_required', false,
          'line_work_required', false,
          'delta_refresh_required', false
        )
      ELSE '{}'::jsonb
    END
  );

  v_reuse_patch_json := jsonb_build_object(
    'last_reused_at_utc', v_now::text,
    'last_reuse_reason', v_reason,
    'last_source_job_id', CASE WHEN p_source_job_id IS NULL THEN NULL ELSE p_source_job_id::text END,
    'last_actor_user_id', CASE WHEN v_actor_user_id IS NULL THEN NULL ELSE v_actor_user_id::text END
  );

  WITH superseded_stale_jobs AS (
    UPDATE public.banking_pay_workbench_jobs AS superseded_job
    SET status = 'FAILED',
        updated_at_utc = v_now,
        failed_at_utc = v_now,
        last_error_json = jsonb_build_object(
          'code', 'WORKBENCH_JOB_SUPERSEDED_BY_NEWER_SESSION_VERSION',
          'message', 'Superseded stale running workbench preview job while enqueueing newer session-version continuation.',
          'session_id', p_session_id::text,
          'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
          'job_type', v_job_type,
          'current_session_version', COALESCE(v_session_row.version, 0),
          'job_session_version', CASE
            WHEN COALESCE(superseded_job.payload_json->>'session_version', '') ~ '^[0-9]+$'
              THEN (superseded_job.payload_json->>'session_version')::bigint
            ELSE NULL::bigint
          END,
          'stale_running_seconds', v_stale_running_seconds,
          'last_activity_at_utc', COALESCE(superseded_job.updated_at_utc, superseded_job.started_at_utc, superseded_job.run_at_utc, superseded_job.created_at_utc),
          'superseded_at_utc', v_now
        ),
        payload_json = COALESCE(superseded_job.payload_json, '{}'::jsonb) || jsonb_build_object(
          'superseded_by_newer_session_version_at_utc', v_now::text,
          'superseded_by_session_version', COALESCE(v_session_row.version, 0),
          'superseded_by_dedupe_key', v_dedupe_key
        )
    WHERE superseded_job.session_id = p_session_id
      AND superseded_job.candidate_id IS NOT DISTINCT FROM p_candidate_id
      AND superseded_job.snapshot_run_id IS NOT DISTINCT FROM v_session_row.source_snapshot_run_id
      AND UPPER(BTRIM(COALESCE(superseded_job.job_type, ''))) = v_job_type
      AND UPPER(BTRIM(COALESCE(superseded_job.status, ''))) IN ('RUNNING', 'PROCESSING', 'CLAIMED', 'IN_PROGRESS')
      AND superseded_job.completed_at_utc IS NULL
      AND superseded_job.failed_at_utc IS NULL
      AND COALESCE(superseded_job.payload_json->>'cursor_token', 'none') = v_cursor_token
      AND COALESCE(superseded_job.payload_json->>'session_signature_token', 'none') = v_session_signature_token
      AND COALESCE(superseded_job.updated_at_utc, superseded_job.started_at_utc, superseded_job.run_at_utc, superseded_job.created_at_utc) <= v_stale_cutoff
      AND COALESCE(superseded_job.payload_json->>'session_version', '') ~ '^[0-9]+$'
      AND (superseded_job.payload_json->>'session_version')::bigint < COALESCE(v_session_row.version, 0)
    RETURNING superseded_job.id
  )
  SELECT COUNT(*)::integer
  INTO v_superseded_stale_count
  FROM superseded_stale_jobs;

  v_original_dedupe_key := v_dedupe_key;

  <<continuation_insert_attempt>>
  LOOP
    v_job_id := NULL::uuid;
    v_job_status := NULL::text;
    v_job_was_inserted := false;
    v_insert_row_count := 0;

  INSERT INTO public.banking_pay_workbench_jobs AS target_job (
    job_type,
    status,
    priority,
    run_at_utc,
    attempt_count,
    max_attempts,
    dedupe_key,
    snapshot_run_id,
    session_id,
    candidate_id,
    payload_json,
    created_at_utc,
    updated_at_utc,
    started_at_utc,
    completed_at_utc,
    failed_at_utc,
    last_error_json
  )
  VALUES (
    v_job_type,
    'QUEUED',
    v_priority,
    v_now,
    0,
    8,
    v_dedupe_key,
    v_session_row.source_snapshot_run_id,
    p_session_id,
    p_candidate_id,
    v_payload_json,
    v_now,
    v_now,
    NULL::timestamptz,
    NULL::timestamptz,
    NULL::timestamptz,
    NULL::jsonb
  )
  ON CONFLICT (dedupe_key) WHERE status IN ('QUEUED', 'RUNNING')
  DO UPDATE
  SET status = CASE
        WHEN UPPER(BTRIM(COALESCE(target_job.status, ''))) = 'RUNNING'
             AND target_job.completed_at_utc IS NULL
             AND target_job.failed_at_utc IS NULL
             AND COALESCE(target_job.updated_at_utc, target_job.started_at_utc, target_job.run_at_utc, target_job.created_at_utc) <= v_stale_cutoff
             AND COALESCE(target_job.attempt_count, 0) >= GREATEST(COALESCE(target_job.max_attempts, 8), 1)
          THEN 'FAILED'
        WHEN UPPER(BTRIM(COALESCE(target_job.status, ''))) = 'RUNNING'
             AND target_job.completed_at_utc IS NULL
             AND target_job.failed_at_utc IS NULL
             AND COALESCE(target_job.updated_at_utc, target_job.started_at_utc, target_job.run_at_utc, target_job.created_at_utc) <= v_stale_cutoff
          THEN 'QUEUED'
        ELSE target_job.status
      END,
      priority = CASE
        WHEN UPPER(BTRIM(COALESCE(target_job.status, ''))) = 'RUNNING'
             AND COALESCE(target_job.updated_at_utc, target_job.started_at_utc, target_job.run_at_utc, target_job.created_at_utc) > v_stale_cutoff
          THEN target_job.priority
        ELSE LEAST(target_job.priority, EXCLUDED.priority)
      END,
      run_at_utc = CASE
        WHEN UPPER(BTRIM(COALESCE(target_job.status, ''))) = 'RUNNING'
             AND target_job.completed_at_utc IS NULL
             AND target_job.failed_at_utc IS NULL
             AND COALESCE(target_job.updated_at_utc, target_job.started_at_utc, target_job.run_at_utc, target_job.created_at_utc) <= v_stale_cutoff
             AND COALESCE(target_job.attempt_count, 0) >= GREATEST(COALESCE(target_job.max_attempts, 8), 1)
          THEN target_job.run_at_utc
        WHEN UPPER(BTRIM(COALESCE(target_job.status, ''))) = 'RUNNING'
             AND target_job.completed_at_utc IS NULL
             AND target_job.failed_at_utc IS NULL
             AND COALESCE(target_job.updated_at_utc, target_job.started_at_utc, target_job.run_at_utc, target_job.created_at_utc) <= v_stale_cutoff
          THEN v_now
        WHEN target_job.status = 'RUNNING' THEN target_job.run_at_utc
        ELSE LEAST(target_job.run_at_utc, EXCLUDED.run_at_utc)
      END,
      started_at_utc = CASE
        WHEN UPPER(BTRIM(COALESCE(target_job.status, ''))) = 'RUNNING'
             AND target_job.completed_at_utc IS NULL
             AND target_job.failed_at_utc IS NULL
             AND COALESCE(target_job.updated_at_utc, target_job.started_at_utc, target_job.run_at_utc, target_job.created_at_utc) <= v_stale_cutoff
             AND COALESCE(target_job.attempt_count, 0) >= GREATEST(COALESCE(target_job.max_attempts, 8), 1)
          THEN target_job.started_at_utc
        WHEN UPPER(BTRIM(COALESCE(target_job.status, ''))) = 'RUNNING'
             AND target_job.completed_at_utc IS NULL
             AND target_job.failed_at_utc IS NULL
             AND COALESCE(target_job.updated_at_utc, target_job.started_at_utc, target_job.run_at_utc, target_job.created_at_utc) <= v_stale_cutoff
          THEN NULL::timestamptz
        ELSE target_job.started_at_utc
      END,
      completed_at_utc = target_job.completed_at_utc,
      failed_at_utc = CASE
        WHEN UPPER(BTRIM(COALESCE(target_job.status, ''))) = 'RUNNING'
             AND target_job.completed_at_utc IS NULL
             AND target_job.failed_at_utc IS NULL
             AND COALESCE(target_job.updated_at_utc, target_job.started_at_utc, target_job.run_at_utc, target_job.created_at_utc) <= v_stale_cutoff
             AND COALESCE(target_job.attempt_count, 0) >= GREATEST(COALESCE(target_job.max_attempts, 8), 1)
          THEN v_now
        WHEN UPPER(BTRIM(COALESCE(target_job.status, ''))) = 'RUNNING'
             AND target_job.completed_at_utc IS NULL
             AND target_job.failed_at_utc IS NULL
             AND COALESCE(target_job.updated_at_utc, target_job.started_at_utc, target_job.run_at_utc, target_job.created_at_utc) <= v_stale_cutoff
          THEN NULL::timestamptz
        ELSE target_job.failed_at_utc
      END,
      last_error_json = CASE
        WHEN UPPER(BTRIM(COALESCE(target_job.status, ''))) = 'RUNNING'
             AND target_job.completed_at_utc IS NULL
             AND target_job.failed_at_utc IS NULL
             AND COALESCE(target_job.updated_at_utc, target_job.started_at_utc, target_job.run_at_utc, target_job.created_at_utc) <= v_stale_cutoff
          THEN jsonb_build_object(
            'code', CASE
              WHEN COALESCE(target_job.attempt_count, 0) >= GREATEST(COALESCE(target_job.max_attempts, 8), 1)
                THEN 'STALE_RUNNING_WORKBENCH_JOB_MAX_ATTEMPTS'
              ELSE 'STALE_RUNNING_WORKBENCH_JOB_RECOVERED'
            END,
            'message', 'Recovered stale running workbench preview job during continuation enqueue.',
            'job_type', v_job_type,
            'session_id', p_session_id::text,
            'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
            'stale_running_seconds', v_stale_running_seconds,
            'recovered_at_utc', v_now
          )
        ELSE target_job.last_error_json
      END,
      payload_json = COALESCE(target_job.payload_json, '{}'::jsonb)
        || v_reuse_patch_json
        || CASE
          WHEN UPPER(BTRIM(COALESCE(target_job.status, ''))) = 'RUNNING'
               AND target_job.completed_at_utc IS NULL
               AND target_job.failed_at_utc IS NULL
               AND COALESCE(target_job.updated_at_utc, target_job.started_at_utc, target_job.run_at_utc, target_job.created_at_utc) <= v_stale_cutoff
            THEN jsonb_build_object(
              'stale_running_recovered_at_utc', v_now::text,
              'stale_running_recovered_by', 'pay_workbench_enqueue_stage_continuation'
            )
          ELSE '{}'::jsonb
        END,
      updated_at_utc = CASE
        WHEN UPPER(BTRIM(COALESCE(target_job.status, ''))) = 'RUNNING'
             AND COALESCE(target_job.updated_at_utc, target_job.started_at_utc, target_job.run_at_utc, target_job.created_at_utc) > v_stale_cutoff
          THEN target_job.updated_at_utc
        ELSE v_now
      END
  WHERE p_source_job_id IS NULL
     OR target_job.id IS DISTINCT FROM p_source_job_id
  RETURNING target_job.id,
            target_job.status,
            (xmax = 0)
  INTO v_job_id,
       v_job_status,
       v_job_was_inserted;

    GET DIAGNOSTICS v_insert_row_count = ROW_COUNT;

    IF COALESCE(v_insert_row_count, 0) = 0 THEN
      IF p_source_job_id IS NOT NULL
         AND EXISTS (
           SELECT 1
           FROM public.banking_pay_workbench_jobs AS self_reuse_source_job
           WHERE self_reuse_source_job.id = p_source_job_id
             AND self_reuse_source_job.dedupe_key = v_dedupe_key
             AND UPPER(BTRIM(COALESCE(self_reuse_source_job.status, ''))) IN ('QUEUED', 'RUNNING')
         ) THEN
        IF v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN
          RETURN jsonb_build_object(
            'ok', true,
            'job_id', NULL::text,
            'job_type', v_job_type,
            'status', 'NOT_ENQUEUED',
            'session_id', p_session_id::text,
            'session_version', COALESCE(v_session_row.version, 0),
            'snapshot_run_id', v_session_row.source_snapshot_run_id::text,
            'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
            'dedupe_key', v_dedupe_key,
            'cursor_token', v_cursor_token,
            'has_cursor', v_cursor_json IS NOT NULL,
            'limit', v_limit,
            'line_limit', v_limit,
            'source_build_run_id', NULLIF(v_source_build_run_id_token, 'none'),
            'source_change_seq', CASE WHEN v_source_change_seq_token ~ '^[0-9]{1,18}$' THEN v_source_change_seq_token::bigint ELSE NULL::bigint END,
            'refresh_scope_kind', v_refresh_scope_kind,
            'targeted_timesheet_ids', COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb),
            'linked_timesheet_ids', COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb),
            'line_work_action', v_line_work_action,
            'next_recommended_action', v_next_recommended_action,
            'reused', false,
            'created', false,
            'superseded_stale_running_count', COALESCE(v_superseded_stale_count, 0),
            'projection_run_id', NULLIF(v_projection_run_id_token, 'none'),
            'projection_class', NULLIF(v_projection_class, ''),
            'phase', NULLIF(v_delta_phase, ''),
            'next_phase', NULLIF(v_delta_next_phase, ''),
            'delta_refresh_required', true,
            'source_job_id', CASE WHEN p_source_job_id IS NULL THEN NULL ELSE p_source_job_id::text END,
            'continuation_reason', v_reason,
            'continuation_not_enqueued', true,
            'identical_cursor_self_reuse_suppressed', true,
            'self_reuse_prevented', true,
            'original_dedupe_key', COALESCE(v_original_dedupe_key, v_dedupe_key),
            'self_reuse_retry_count', COALESCE(v_self_reuse_retry_count, 0) + 1,
            'no_op', true,
            'reason', 'DELTA_IDENTICAL_CURSOR_SELF_REUSE_SUPPRESSED'
          );
        END IF;
        IF v_self_reuse_prevented IS TRUE THEN
          RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_SELF_REUSE_BLOCKED'
            USING ERRCODE = 'P0001',
                  DETAIL = jsonb_build_object(
                    'code', 'PAY_WORKBENCH_CONTINUATION_SELF_REUSE_BLOCKED',
                    'session_id', p_session_id::text,
