        COALESCE(app_counter.seq, 0)::bigint AS live_candidate_change_seq
      FROM poisoned_scope
      JOIN LATERAL (
        SELECT poisoned_scope.bad_job_id_text::uuid AS bad_job_id
        WHERE poisoned_scope.bad_job_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      ) AS bad_job_id ON true
      JOIN public.banking_pay_workbench_jobs AS bad_job
        ON bad_job.id = bad_job_id.bad_job_id
      LEFT JOIN public.app_change_counters AS app_counter
        ON app_counter.entity_key = 'pay_candidate:' || poisoned_scope.candidate_id::text
      WHERE bad_job.session_id = poisoned_scope.session_id
        AND bad_job.candidate_id = poisoned_scope.candidate_id
        AND UPPER(BTRIM(COALESCE(bad_job.job_type, ''))) IN (
          'WORKBENCH_CANDIDATE_SOURCE_BUILD',
          'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK',
          'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE',
          'CANDIDATE_SOURCE_BUILD',
          'CANDIDATE_SOURCE_BUILD_CHUNK',
          'SOURCE_BUILD',
          'SOURCE_BUILD_PAGE'
        )
        AND UPPER(BTRIM(COALESCE(bad_job.status, ''))) IN ('FAILED', 'DEAD')
        AND NULLIF(BTRIM(COALESCE(
          bad_job.payload_json->>'source_build_run_id',
          bad_job.payload_json#>>'{source_build,source_build_run_id}',
          bad_job.payload_json#>>'{source_build,run_id}',
          bad_job.payload_json#>>'{cursor,source_build_run_id}',
          bad_job.payload_json#>>'{cursor_json,source_build_run_id}',
          bad_job.payload_json#>>'{result_json,source_build_run_id}',
          ''
        )), '') IS NULL
        AND (
          COALESCE(bad_job.last_error_json, '{}'::jsonb)::text ILIKE '%PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_RUN_ID_REQUIRED%'
          OR COALESCE(poisoned_scope.scope_error_json, '{}'::jsonb)::text ILIKE '%STALE_RUNNING_WORKBENCH_SOURCE_BUILD_FAILED%'
          OR COALESCE(poisoned_scope.scope_error_json, '{}'::jsonb)::text ILIKE '%WORKBENCH_SOURCE_BUILD_JOB_FAILED%'
          OR COALESCE(bad_job.payload_json, '{}'::jsonb)::text ILIKE '%CLONE_REBASE_INELIGIBLE_SOURCE_BUILD%'
        )
    ), candidate_runs AS (
      SELECT
        bad_scope.*,
        source_line.source_build_run_id,
        source_line.source_change_seq,
        COUNT(*)::integer AS source_rows_error_count,
        MIN(source_line.created_at_utc) AS source_rows_first_created_at_utc,
        MAX(source_line.updated_at_utc) AS source_rows_last_updated_at_utc
      FROM bad_scope
      JOIN public.banking_pay_workbench_candidate_source_lines AS source_line
        ON source_line.session_id = bad_scope.session_id
       AND source_line.candidate_id = bad_scope.candidate_id
       AND UPPER(BTRIM(COALESCE(source_line.status, ''))) = 'ERROR'
      GROUP BY
        bad_scope.scope_id,
        bad_scope.session_id,
        bad_scope.candidate_id,
        bad_scope.scope_status,
        bad_scope.scope_pending_job_id,
        bad_scope.scope_dirty,
        bad_scope.scope_error_json,
        bad_scope.scope_updated_at_utc,
        bad_scope.bad_job_id_text,
        bad_scope.bad_job_id,
        bad_scope.bad_job_type,
        bad_scope.bad_job_status,
        bad_scope.bad_job_attempt_count,
        bad_scope.bad_job_max_attempts,
        bad_scope.bad_job_dedupe_key,
        bad_scope.bad_job_payload_json,
        bad_scope.bad_job_last_error_json,
        bad_scope.bad_job_created_at_utc,
        bad_scope.bad_job_updated_at_utc,
        bad_scope.bad_job_failed_at_utc,
        bad_scope.bad_source_build_run_id_text,
        bad_scope.live_candidate_change_seq,
        source_line.source_build_run_id,
        source_line.source_change_seq
    ), repair_choices AS (
      SELECT
        candidate_runs.*,
        good_source_job.id AS good_source_build_job_id,
        good_source_job.status AS good_source_build_job_status,
        good_source_job.updated_at_utc AS good_source_build_job_updated_at_utc,
        line_seed_job.id AS line_seed_job_id,
        line_seed_job.status AS line_seed_job_status,
        line_seed_job.attempt_count AS line_seed_attempt_count,
        line_seed_job.max_attempts AS line_seed_max_attempts,
        line_seed_job.updated_at_utc AS line_seed_updated_at_utc,
        line_seed_job.last_error_json AS line_seed_last_error_json
      FROM candidate_runs
      JOIN LATERAL (
        SELECT source_job.*
        FROM public.banking_pay_workbench_jobs AS source_job
        CROSS JOIN LATERAL (
          SELECT
            NULLIF(BTRIM(COALESCE(
              source_job.payload_json->>'source_build_run_id',
              source_job.payload_json#>>'{source_build,source_build_run_id}',
              source_job.payload_json#>>'{source_build,run_id}',
              source_job.payload_json#>>'{cursor,source_build_run_id}',
              source_job.payload_json#>>'{cursor_json,source_build_run_id}',
              source_job.payload_json#>>'{result_json,source_build_run_id}',
              ''
            )), '') AS source_build_run_id_text,
            COALESCE(
              CASE WHEN COALESCE(source_job.payload_json->>'source_change_seq', '') ~ '^[0-9]{1,18}$' THEN (source_job.payload_json->>'source_change_seq')::bigint ELSE NULL::bigint END,
              CASE WHEN COALESCE(source_job.payload_json->>'source_change_sequence', '') ~ '^[0-9]{1,18}$' THEN (source_job.payload_json->>'source_change_sequence')::bigint ELSE NULL::bigint END,
              CASE WHEN COALESCE(source_job.payload_json#>>'{source_build,source_change_seq}', '') ~ '^[0-9]{1,18}$' THEN (source_job.payload_json#>>'{source_build,source_change_seq}')::bigint ELSE NULL::bigint END,
              CASE WHEN COALESCE(source_job.payload_json#>>'{result_json,source_change_seq}', '') ~ '^[0-9]{1,18}$' THEN (source_job.payload_json#>>'{result_json,source_change_seq}')::bigint ELSE NULL::bigint END
            ) AS source_change_seq
        ) AS source_job_extract
        WHERE source_job.session_id = candidate_runs.session_id
          AND source_job.candidate_id = candidate_runs.candidate_id
          AND source_job.id <> candidate_runs.bad_job_id
          AND UPPER(BTRIM(COALESCE(source_job.job_type, ''))) IN (
            'WORKBENCH_CANDIDATE_SOURCE_BUILD',
            'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK',
            'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE',
            'CANDIDATE_SOURCE_BUILD',
            'CANDIDATE_SOURCE_BUILD_CHUNK',
            'SOURCE_BUILD',
            'SOURCE_BUILD_PAGE'
          )
          AND UPPER(BTRIM(COALESCE(source_job.status, ''))) = 'SUCCEEDED'
          AND source_job_extract.source_build_run_id_text = candidate_runs.source_build_run_id::text
          AND (
            source_job_extract.source_change_seq IS NULL
            OR source_job_extract.source_change_seq = candidate_runs.source_change_seq
          )
        ORDER BY source_job.updated_at_utc DESC NULLS LAST, source_job.created_at_utc DESC NULLS LAST, source_job.id DESC
        LIMIT 1
      ) AS good_source_job ON true
      JOIN LATERAL (
        SELECT line_job.*
        FROM public.banking_pay_workbench_jobs AS line_job
        CROSS JOIN LATERAL (
          SELECT NULLIF(BTRIM(COALESCE(
            line_job.payload_json->>'source_build_run_id',
            line_job.payload_json#>>'{source_build,source_build_run_id}',
            line_job.payload_json#>>'{source_build,run_id}',
            line_job.payload_json#>>'{cursor,source_build_run_id}',
            line_job.payload_json#>>'{cursor_json,source_build_run_id}',
            line_job.payload_json#>>'{source_build_cursor,source_build_run_id}',
            line_job.payload_json#>>'{result_json,source_build_run_id}',
            ''
          )), '') AS source_build_run_id_text
        ) AS line_job_extract
        WHERE line_job.session_id = candidate_runs.session_id
          AND line_job.candidate_id = candidate_runs.candidate_id
          AND UPPER(BTRIM(COALESCE(line_job.job_type, ''))) IN (
            'WORKBENCH_CANDIDATE_LINE_WORK_SEED',
            'WORKBENCH_CANDIDATE_LINE_WORK_SEED_PAGE',
            'CANDIDATE_LINE_WORK_SEED',
            'CANDIDATE_LINE_WORK_SEED_PAGE',
            'LINE_WORK_SEED_PAGE',
            'SNAPSHOT_CANDIDATE_REFRESH',
            'CANDIDATE_REFRESH'
          )
          AND UPPER(BTRIM(COALESCE(line_job.status, ''))) IN ('FAILED', 'DEAD')
          AND line_job_extract.source_build_run_id_text = candidate_runs.source_build_run_id::text
          AND COALESCE(line_job.last_error_json, '{}'::jsonb)::text ILIKE '%SOURCE_ROWS_MISSING%'
        ORDER BY line_job.updated_at_utc DESC NULLS LAST, line_job.created_at_utc DESC NULLS LAST, line_job.id DESC
        LIMIT 1
      ) AS line_seed_job ON true
      ORDER BY
        CASE WHEN candidate_runs.source_change_seq = candidate_runs.live_candidate_change_seq THEN 0 ELSE 1 END,
        candidate_runs.source_change_seq DESC,
        good_source_job.updated_at_utc DESC NULLS LAST,
        line_seed_job.updated_at_utc DESC NULLS LAST
      LIMIT v_limit
    )
    SELECT *
    FROM repair_choices
  LOOP
    v_processed_count := v_processed_count + 1;
    v_restored_source_row_count := 0;
    v_progress_recompute_json := '{}'::jsonb;
    v_progress_recompute_failed := false;
    v_progress_recompute_error_json := NULL::jsonb;
    v_line_seed_before_json := NULL::jsonb;
    v_line_seed_after_json := NULL::jsonb;
    v_scope_before_json := NULL::jsonb;
    v_scope_after_json := NULL::jsonb;
    v_session_before_json := NULL::jsonb;
    v_session_after_json := NULL::jsonb;
    v_source_row_object_id := v_repair_row.source_build_run_id::text;

    v_bad_job_audit_before_json := jsonb_build_object(
      'session_id', v_repair_row.session_id::text,
      'candidate_id', v_repair_row.candidate_id::text,
      'bad_job_id', v_repair_row.bad_job_id::text,
      'job_type', v_repair_row.bad_job_type,
      'status', v_repair_row.bad_job_status,
      'attempt_count', v_repair_row.bad_job_attempt_count,
      'max_attempts', v_repair_row.bad_job_max_attempts,
      'source_build_run_id', NULL::text,
      'source_change_seq', v_repair_row.source_change_seq,
      'last_error_json', v_repair_row.bad_job_last_error_json,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    );
    SELECT COALESCE(jsonb_agg(status_counts.status_json ORDER BY status_counts.status), '[]'::jsonb)
    INTO v_source_rows_before_json
    FROM (
      SELECT
        source_line.status,
        jsonb_build_object(
          'status', source_line.status,
          'count', COUNT(*)::integer
        ) AS status_json
      FROM public.banking_pay_workbench_candidate_source_lines AS source_line
      WHERE source_line.session_id = v_repair_row.session_id
        AND source_line.candidate_id = v_repair_row.candidate_id
        AND source_line.source_build_run_id = v_repair_row.source_build_run_id
        AND source_line.source_change_seq = v_repair_row.source_change_seq
      GROUP BY source_line.status
    ) AS status_counts;

    WITH restored_source_rows AS (
      UPDATE public.banking_pay_workbench_candidate_source_lines AS source_line
      SET status = 'CURRENT',
          source_row_json = jsonb_strip_nulls(
            (COALESCE(source_line.source_row_json, '{}'::jsonb) - 'stale_source_build_error' - 'source_build_error')
            || jsonb_build_object(
              'source_build_poison_repair', jsonb_build_object(
                'code', 'SOURCE_BUILD_ROWS_RESTORED',
                'repaired_at_utc', v_now::text,
                'session_id', v_repair_row.session_id::text,
                'candidate_id', v_repair_row.candidate_id::text,
                'bad_job_id', v_repair_row.bad_job_id::text,
                'source_build_run_id', v_repair_row.source_build_run_id::text,
                'source_change_seq', v_repair_row.source_change_seq,
                'line_seed_job_id', v_repair_row.line_seed_job_id::text,
                'reason', v_reason,
                'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
              )
            )
          ),
          updated_at_utc = v_now
      WHERE source_line.session_id = v_repair_row.session_id
        AND source_line.candidate_id = v_repair_row.candidate_id
        AND source_line.source_build_run_id = v_repair_row.source_build_run_id
        AND source_line.source_change_seq = v_repair_row.source_change_seq
        AND UPPER(BTRIM(COALESCE(source_line.status, ''))) = 'ERROR'
        AND NOT EXISTS (
          SELECT 1
          FROM public.banking_pay_workbench_candidate_source_lines AS existing_current_source_line
          WHERE existing_current_source_line.id <> source_line.id
            AND existing_current_source_line.session_id = source_line.session_id
            AND existing_current_source_line.candidate_id = source_line.candidate_id
            AND existing_current_source_line.session_version = source_line.session_version
            AND existing_current_source_line.source_change_seq = source_line.source_change_seq
            AND existing_current_source_line.source_build_run_id = source_line.source_build_run_id
            AND COALESCE(existing_current_source_line.timesheet_id, '00000000-0000-0000-0000-000000000000'::uuid) = COALESCE(source_line.timesheet_id, '00000000-0000-0000-0000-000000000000'::uuid)
            AND existing_current_source_line.line_key = source_line.line_key
            AND UPPER(BTRIM(COALESCE(existing_current_source_line.status, ''))) = 'CURRENT'
        )
      RETURNING source_line.id
    )
    SELECT COUNT(*)::integer
    INTO v_restored_source_row_count
    FROM restored_source_rows;

    SELECT COALESCE(jsonb_agg(status_counts.status_json ORDER BY status_counts.status), '[]'::jsonb)
    INTO v_source_rows_after_json
    FROM (
      SELECT
        source_line.status,
        jsonb_build_object(
          'status', source_line.status,
          'count', COUNT(*)::integer
        ) AS status_json
      FROM public.banking_pay_workbench_candidate_source_lines AS source_line
      WHERE source_line.session_id = v_repair_row.session_id
        AND source_line.candidate_id = v_repair_row.candidate_id
        AND source_line.source_build_run_id = v_repair_row.source_build_run_id
        AND source_line.source_change_seq = v_repair_row.source_change_seq
      GROUP BY source_line.status
    ) AS status_counts;

    PERFORM public._audit_insert(
      'banking_pay_workbench_candidate_source_lines',
      v_source_row_object_id,
      'SOURCE_BUILD_ROWS_RESTORED',
      jsonb_build_object(
        'session_id', v_repair_row.session_id::text,
        'candidate_id', v_repair_row.candidate_id::text,
        'bad_job_id', v_repair_row.bad_job_id::text,
        'good_source_build_job_id', v_repair_row.good_source_build_job_id::text,
        'source_build_run_id', v_repair_row.source_build_run_id::text,
        'source_change_seq', v_repair_row.source_change_seq,
        'status_counts', COALESCE(v_source_rows_before_json, '[]'::jsonb),
        'old_status', 'ERROR',
        'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
      ),
      jsonb_build_object(
        'session_id', v_repair_row.session_id::text,
        'candidate_id', v_repair_row.candidate_id::text,
        'bad_job_id', v_repair_row.bad_job_id::text,
        'good_source_build_job_id', v_repair_row.good_source_build_job_id::text,
        'source_build_run_id', v_repair_row.source_build_run_id::text,
        'source_change_seq', v_repair_row.source_change_seq,
        'source_rows_restored_count', COALESCE(v_restored_source_row_count, 0),
        'affected_row_count', COALESCE(v_restored_source_row_count, 0),
        'status_counts', COALESCE(v_source_rows_after_json, '[]'::jsonb),
        'new_status', 'CURRENT',
        'reason', v_reason,
        'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
      ),
      'SOURCE_BUILD_ROWS_RESTORED',
      NULL
    );

    IF COALESCE(v_restored_source_row_count, 0) <= 0 THEN
      v_skipped_count := v_skipped_count + 1;
      v_skips_json := v_skips_json || jsonb_build_array(jsonb_build_object(
        'session_id', v_repair_row.session_id::text,
        'candidate_id', v_repair_row.candidate_id::text,
        'bad_job_id', v_repair_row.bad_job_id::text,
        'source_build_run_id', v_repair_row.source_build_run_id::text,
        'source_change_seq', v_repair_row.source_change_seq,
        'reason', 'NO_ERROR_SOURCE_ROWS_RESTORED',
        'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
      ));
      CONTINUE;
    END IF;

    UPDATE public.banking_pay_workbench_jobs AS bad_job_update
    SET payload_json = jsonb_strip_nulls(
          COALESCE(bad_job_update.payload_json, '{}'::jsonb)
          || jsonb_build_object(
            'invalid_source_build_without_run_id_failed_closed', true,
            'invalid_source_build_without_run_id_non_blocking', true,
            'non_blocking_terminal_failure', true,
            'non_blocking_terminal_failure_reason', 'MISSING_SOURCE_BUILD_RUN_ID_IS_NOT_AUTHORITATIVE',
            'non_blocking_terminal_failure_at_utc', v_now::text,
            'source_build_poison_repair_resolved', true,
            'source_build_poison_repair_resolved_at_utc', v_now::text,
            'source_build_poison_repair_reason', v_reason,
            'source_build_poison_repair_good_source_build_job_id', v_repair_row.good_source_build_job_id::text,
            'source_build_poison_repair_source_build_run_id', v_repair_row.source_build_run_id::text,
            'source_build_poison_repair_source_change_seq', v_repair_row.source_change_seq,
            'source_build_poison_repair_line_seed_job_id', v_repair_row.line_seed_job_id::text,
            'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
          )
        ),
        updated_at_utc = v_now
    WHERE bad_job_update.id = v_repair_row.bad_job_id
    RETURNING jsonb_build_object(
      'session_id', v_repair_row.session_id::text,
      'candidate_id', v_repair_row.candidate_id::text,
      'bad_job_id', bad_job_update.id::text,
      'job_type', bad_job_update.job_type,
      'status', bad_job_update.status,
      'retained_terminal', true,
      'hard_deleted', false,
      'bad_job_mutated', true,
      'source_build_run_id', NULL::text,
      'source_change_seq', v_repair_row.source_change_seq,
      'non_blocking_terminal_failure', true,
      'invalid_source_build_without_run_id_non_blocking', true,
      'good_source_build_job_id', v_repair_row.good_source_build_job_id::text,
      'repaired_source_build_run_id', v_repair_row.source_build_run_id::text,
      'line_seed_job_id', v_repair_row.line_seed_job_id::text,
      'reason', v_reason,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_bad_job_audit_after_json;

    PERFORM public._audit_insert(
      'banking_pay_workbench_job',
      v_repair_row.bad_job_id::text,
      'FAILED',
      v_bad_job_audit_before_json,
      v_bad_job_audit_after_json,
      'WORKBENCH_INVALID_SOURCE_BUILD_WITHOUT_RUN_ID_FAILED_CLOSED',
      NULL
    );

    SELECT jsonb_build_object(
      'id', line_seed_job.id::text,
      'job_type', line_seed_job.job_type,
      'status', line_seed_job.status,
      'run_at_utc', line_seed_job.run_at_utc,
      'attempt_count', line_seed_job.attempt_count,
      'max_attempts', line_seed_job.max_attempts,
      'session_id', CASE WHEN line_seed_job.session_id IS NULL THEN NULL ELSE line_seed_job.session_id::text END,
      'candidate_id', CASE WHEN line_seed_job.candidate_id IS NULL THEN NULL ELSE line_seed_job.candidate_id::text END,
      'source_build_run_id', v_repair_row.source_build_run_id::text,
      'source_change_seq', v_repair_row.source_change_seq,
      'last_error_json', line_seed_job.last_error_json,
      'failed_at_utc', line_seed_job.failed_at_utc,
      'updated_at_utc', line_seed_job.updated_at_utc,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_line_seed_before_json
    FROM public.banking_pay_workbench_jobs AS line_seed_job
    WHERE line_seed_job.id = v_repair_row.line_seed_job_id
    FOR UPDATE;

    UPDATE public.banking_pay_workbench_jobs AS line_seed_job
    SET status = 'QUEUED',
        attempt_count = 0,
        run_at_utc = v_now,
        started_at_utc = NULL::timestamptz,
        completed_at_utc = NULL::timestamptz,
        failed_at_utc = NULL::timestamptz,
        last_error_json = NULL::jsonb,
        payload_json = jsonb_strip_nulls(
          (COALESCE(line_seed_job.payload_json, '{}'::jsonb) - 'last_failure_json')
          || jsonb_build_object(
            'source_build_poison_repair', jsonb_build_object(
              'code', 'WORKBENCH_LINE_SEED_REQUEUED_AFTER_SOURCE_BUILD_POISON_REPAIR',
              'requeued_at_utc', v_now::text,
              'session_id', v_repair_row.session_id::text,
              'candidate_id', v_repair_row.candidate_id::text,
              'bad_job_id', v_repair_row.bad_job_id::text,
              'source_build_run_id', v_repair_row.source_build_run_id::text,
              'source_change_seq', v_repair_row.source_change_seq,
              'restored_source_row_count', COALESCE(v_restored_source_row_count, 0),
              'attempt_count_reset_to', 0,
              'reason', v_reason,
              'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
            )
          )
        ),
        updated_at_utc = v_now
    WHERE line_seed_job.id = v_repair_row.line_seed_job_id
      AND UPPER(BTRIM(COALESCE(line_seed_job.status, ''))) IN ('FAILED', 'DEAD')
    RETURNING jsonb_build_object(
      'id', line_seed_job.id::text,
      'job_type', line_seed_job.job_type,
      'status', line_seed_job.status,
      'run_at_utc', line_seed_job.run_at_utc,
      'attempt_count', line_seed_job.attempt_count,
      'max_attempts', line_seed_job.max_attempts,
      'session_id', CASE WHEN line_seed_job.session_id IS NULL THEN NULL ELSE line_seed_job.session_id::text END,
      'candidate_id', CASE WHEN line_seed_job.candidate_id IS NULL THEN NULL ELSE line_seed_job.candidate_id::text END,
      'source_build_run_id', v_repair_row.source_build_run_id::text,
      'source_change_seq', v_repair_row.source_change_seq,
      'last_error_json', line_seed_job.last_error_json,
      'failed_at_utc', line_seed_job.failed_at_utc,
      'updated_at_utc', line_seed_job.updated_at_utc,
      'reason', v_reason,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_line_seed_after_json;

    PERFORM public._audit_insert(
      'banking_pay_workbench_job',
      v_repair_row.line_seed_job_id::text,
      'REQUEUED',
      v_line_seed_before_json,
      v_line_seed_after_json,
      'WORKBENCH_LINE_SEED_REQUEUED_AFTER_SOURCE_BUILD_POISON_REPAIR',
      NULL
    );

    IF v_line_seed_after_json IS NOT NULL THEN
      v_line_seed_attempt_count_reset_count := v_line_seed_attempt_count_reset_count + 1;
    END IF;

    SELECT jsonb_build_object(
      'id', scope_row.id::text,
      'session_id', scope_row.session_id::text,
      'candidate_id', scope_row.candidate_id::text,
      'status', scope_row.status,
      'dirty', scope_row.dirty,
      'pending_job_id', CASE WHEN scope_row.pending_job_id IS NULL THEN NULL ELSE scope_row.pending_job_id::text END,
      'error_json', scope_row.error_json,
      'source_build_run_id', v_repair_row.source_build_run_id::text,
      'source_change_seq', v_repair_row.source_change_seq,
      'bad_job_id', v_repair_row.bad_job_id::text,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_scope_before_json
    FROM public.banking_pay_workbench_session_scope AS scope_row
    WHERE scope_row.id = v_repair_row.scope_id
    FOR UPDATE;

    UPDATE public.banking_pay_workbench_session_scope AS scope_row
    SET status = 'LINE_WORK_PENDING',
        dirty = true,
        pending_job_id = v_repair_row.line_seed_job_id,
        error_json = NULL::jsonb,
        updated_at_utc = v_now
    WHERE scope_row.id = v_repair_row.scope_id
      AND scope_row.session_id = v_repair_row.session_id
      AND scope_row.candidate_id = v_repair_row.candidate_id
    RETURNING jsonb_build_object(
      'id', scope_row.id::text,
      'session_id', scope_row.session_id::text,
      'candidate_id', scope_row.candidate_id::text,
      'status', scope_row.status,
      'dirty', scope_row.dirty,
      'pending_job_id', CASE WHEN scope_row.pending_job_id IS NULL THEN NULL ELSE scope_row.pending_job_id::text END,
      'error_json', scope_row.error_json,
      'source_build_run_id', v_repair_row.source_build_run_id::text,
      'source_change_seq', v_repair_row.source_change_seq,
      'bad_job_id', v_repair_row.bad_job_id::text,
      'restored_source_row_count', COALESCE(v_restored_source_row_count, 0),
      'reason', v_reason,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_scope_after_json;

    PERFORM public._audit_insert(
      'banking_pay_workbench_session_scope',
      v_repair_row.candidate_id::text,
      'SOURCE_BUILD_POISON_REPAIRED',
      v_scope_before_json,
      v_scope_after_json,
      'SOURCE_BUILD_POISON_REPAIRED',
      NULL
    );

    SELECT jsonb_build_object(
      'id', session_row.id::text,
      'status', session_row.status,
      'progress_state', session_row.progress_state,
      'progress_counter_version', session_row.progress_counter_version,
      'progress_updated_at_utc', session_row.progress_updated_at_utc,
      'progress_json', public.pay_workbench_session_compact_progress_json(COALESCE(session_row.progress_json, '{}'::jsonb), true),
      'session_id', session_row.id::text,
      'candidate_id', v_repair_row.candidate_id::text,
      'bad_job_id', v_repair_row.bad_job_id::text,
      'source_build_run_id', v_repair_row.source_build_run_id::text,
      'source_change_seq', v_repair_row.source_change_seq,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_session_before_json
    FROM public.banking_pay_workbench_sessions AS session_row
    WHERE session_row.id = v_repair_row.session_id
    FOR UPDATE;

    UPDATE public.banking_pay_workbench_sessions AS session_row
    SET progress_state = 'REFRESHING_CANDIDATES',
        progress_json = jsonb_strip_nulls(
          (
            public.pay_workbench_session_compact_progress_json(COALESCE(session_row.progress_json, '{}'::jsonb), true)
            - 'last_source_build_failure_at_utc'
            - 'last_source_build_failure_job_id'
            - 'last_source_build_failure_code'
            - 'last_source_build_failure_source_build_run_id'
            - 'last_source_build_source_rows_marked_error_count'
            - 'blocker_codes'
            - 'draft_blocker_codes'
            - 'session_blocker_codes'
          )
          || jsonb_build_object(
            'source_build_poison_repair', jsonb_build_object(
              'code', 'PROGRESS_REPAIRED_AFTER_SOURCE_BUILD_POISON',
              'repaired_at_utc', v_now::text,
              'session_id', v_repair_row.session_id::text,
              'candidate_id', v_repair_row.candidate_id::text,
              'bad_job_id', v_repair_row.bad_job_id::text,
              'source_build_run_id', v_repair_row.source_build_run_id::text,
              'source_change_seq', v_repair_row.source_change_seq,
              'line_seed_job_id', v_repair_row.line_seed_job_id::text,
              'restored_source_row_count', COALESCE(v_restored_source_row_count, 0),
              'reason', v_reason,
              'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
            )
          )
        ),
        progress_counter_version = COALESCE(session_row.progress_counter_version, 0) + 1,
        progress_updated_at_utc = v_now,
        updated_at_utc = v_now
    WHERE session_row.id = v_repair_row.session_id;

    BEGIN
      v_progress_recompute_json := public.pay_workbench_session_recompute_progress_counters(
        p_session_id => v_repair_row.session_id,
        p_apply => true,
        p_reason => 'SOURCE_BUILD_POISON_REPAIRED',
        p_write_progress_json => true
      );
    EXCEPTION WHEN OTHERS THEN
      v_progress_recompute_failed := true;
      v_progress_recompute_error_json := jsonb_build_object(
        'code', SQLSTATE,
        'message', SQLERRM,
        'session_id', v_repair_row.session_id::text,
        'candidate_id', v_repair_row.candidate_id::text,
        'bad_job_id', v_repair_row.bad_job_id::text,
        'source_build_run_id', v_repair_row.source_build_run_id::text,
        'source_change_seq', v_repair_row.source_change_seq,
        'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
      );
      v_progress_recompute_json := COALESCE(v_progress_recompute_error_json, '{}'::jsonb);
    END;

    SELECT jsonb_build_object(
      'id', session_row.id::text,
      'status', session_row.status,
      'progress_state', session_row.progress_state,
      'progress_counter_version', session_row.progress_counter_version,
      'progress_updated_at_utc', session_row.progress_updated_at_utc,
      'progress_json', public.pay_workbench_session_compact_progress_json(COALESCE(session_row.progress_json, '{}'::jsonb), true),
      'session_id', session_row.id::text,
      'candidate_id', v_repair_row.candidate_id::text,
      'bad_job_id', v_repair_row.bad_job_id::text,
      'source_build_run_id', v_repair_row.source_build_run_id::text,
      'source_change_seq', v_repair_row.source_change_seq,
      'line_seed_job_id', v_repair_row.line_seed_job_id::text,
      'restored_source_row_count', COALESCE(v_restored_source_row_count, 0),
      'recompute_failed', v_progress_recompute_failed,
      'recompute_json', COALESCE(v_progress_recompute_json, '{}'::jsonb),
      'reason', v_reason,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_session_after_json
    FROM public.banking_pay_workbench_sessions AS session_row
    WHERE session_row.id = v_repair_row.session_id;

    PERFORM public._audit_insert(
      'banking_pay_workbench_session',
      v_repair_row.session_id::text,
      'PROGRESS_REPAIRED_AFTER_SOURCE_BUILD_POISON',
      v_session_before_json,
      v_session_after_json,
      'PROGRESS_REPAIRED_AFTER_SOURCE_BUILD_POISON',
      NULL
    );

    v_repaired_count := v_repaired_count + 1;
    v_total_restored_source_row_count := v_total_restored_source_row_count + COALESCE(v_restored_source_row_count, 0);
    v_requeued_line_seed_count := v_requeued_line_seed_count + 1;
    v_repaired_scope_count := v_repaired_scope_count + 1;
    v_repaired_session_count := v_repaired_session_count + 1;

    v_repairs_json := v_repairs_json || jsonb_build_array(jsonb_build_object(
      'session_id', v_repair_row.session_id::text,
      'candidate_id', v_repair_row.candidate_id::text,
      'bad_job_id', v_repair_row.bad_job_id::text,
      'good_source_build_job_id', v_repair_row.good_source_build_job_id::text,
      'source_build_run_id', v_repair_row.source_build_run_id::text,
      'source_change_seq', v_repair_row.source_change_seq,
      'line_seed_job_id', v_repair_row.line_seed_job_id::text,
      'source_rows_restored_count', COALESCE(v_restored_source_row_count, 0),
      'line_seed_requeued', true,
      'line_seed_attempt_count_reset', v_line_seed_after_json IS NOT NULL,
      'scope_repaired', true,
      'session_progress_repaired', true,
      'progress_recompute_failed', v_progress_recompute_failed,
      'reason', v_reason,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    ));
  END LOOP;

  FOR v_zero_repair_row IN
    WITH zero_poisoned_scope AS (
      SELECT
        scope_row.id AS scope_id,
        scope_row.session_id,
        scope_row.candidate_id,
        scope_row.status AS scope_status,
        scope_row.pending_job_id AS scope_pending_job_id,
        scope_row.dirty AS scope_dirty,
        scope_row.error_json AS scope_error_json,
        scope_row.updated_at_utc AS scope_updated_at_utc,
        NULLIF(BTRIM(COALESCE(
          scope_row.error_json->>'job_id',
          scope_row.error_json#>>'{job,job_id}',
          scope_row.error_json#>>'{source_build,job_id}',
          scope_row.error_json#>>'{last_error_json,job_id}',
          scope_row.error_json#>>'{job_error_json,job_id}',
          ''
        )), '') AS bad_job_id_text
      FROM public.banking_pay_workbench_session_scope AS scope_row
      WHERE UPPER(BTRIM(COALESCE(scope_row.status, ''))) = 'SOURCE_BUILD_ERROR'
        AND (p_session_id IS NULL OR scope_row.session_id = p_session_id)
        AND (p_candidate_id IS NULL OR scope_row.candidate_id = p_candidate_id)
      ORDER BY scope_row.updated_at_utc ASC, scope_row.id ASC
      LIMIT GREATEST(v_limit - v_processed_count, 0)
      FOR UPDATE OF scope_row SKIP LOCKED
    ), zero_bad_scope AS (
      SELECT
        zero_poisoned_scope.*,
        bad_job.id AS bad_job_id,
        bad_job.job_type AS bad_job_type,
        bad_job.status AS bad_job_status,
        bad_job.attempt_count AS bad_job_attempt_count,
        bad_job.max_attempts AS bad_job_max_attempts,
        bad_job.dedupe_key AS bad_job_dedupe_key,
        COALESCE(bad_job.payload_json, '{}'::jsonb) AS bad_job_payload_json,
        bad_job.last_error_json AS bad_job_last_error_json,
        bad_job.created_at_utc AS bad_job_created_at_utc,
        bad_job.updated_at_utc AS bad_job_updated_at_utc,
        bad_job.failed_at_utc AS bad_job_failed_at_utc,
        target_session.version AS target_session_version,
        target_session.session_signature AS target_session_signature,
        target_session.source_snapshot_run_id AS target_source_snapshot_run_id,
        COALESCE(app_counter.seq, 0)::bigint AS live_candidate_change_seq,
        NULLIF(BTRIM(COALESCE(
          bad_job.payload_json->>'source_build_run_id',
          bad_job.payload_json#>>'{source_build,source_build_run_id}',
          bad_job.payload_json#>>'{source_build,run_id}',
          bad_job.payload_json#>>'{cursor,source_build_run_id}',
          bad_job.payload_json#>>'{cursor_json,source_build_run_id}',
          bad_job.payload_json#>>'{result_json,source_build_run_id}',
          ''
        )), '') AS bad_source_build_run_id_text,
        COALESCE(
          CASE WHEN COALESCE(zero_poisoned_scope.scope_error_json->>'source_rows_marked_error_count', '') ~ '^[0-9]+$' THEN (zero_poisoned_scope.scope_error_json->>'source_rows_marked_error_count')::integer ELSE NULL::integer END,
          CASE WHEN COALESCE(zero_poisoned_scope.scope_error_json#>>'{job_error_json,source_rows_marked_error_count}', '') ~ '^[0-9]+$' THEN (zero_poisoned_scope.scope_error_json#>>'{job_error_json,source_rows_marked_error_count}')::integer ELSE NULL::integer END,
          CASE WHEN COALESCE(bad_job.last_error_json->>'source_rows_marked_error_count', '') ~ '^[0-9]+$' THEN (bad_job.last_error_json->>'source_rows_marked_error_count')::integer ELSE NULL::integer END,
          CASE WHEN COALESCE(bad_job.payload_json#>>'{last_failure_json,source_rows_marked_error_count}', '') ~ '^[0-9]+$' THEN (bad_job.payload_json#>>'{last_failure_json,source_rows_marked_error_count}')::integer ELSE NULL::integer END,
          0
        ) AS source_rows_marked_error_count,
        NULLIF(BTRIM(COALESCE(
          bad_job.payload_json->>'source_session_id',
          bad_job.payload_json->>'clone_from_session_id',
          bad_job.payload_json#>>'{source_build,source_session_id}',
          bad_job.payload_json#>>'{source_build,clone_from_session_id}',
          zero_poisoned_scope.scope_error_json->>'source_session_id',
          zero_poisoned_scope.scope_error_json->>'clone_from_session_id',
          ''
        )), '') AS source_session_id_text,
        COALESCE(
          CASE WHEN COALESCE(bad_job.payload_json->>'source_change_seq', '') ~ '^[0-9]{1,18}$' THEN (bad_job.payload_json->>'source_change_seq')::bigint ELSE NULL::bigint END,
          CASE WHEN COALESCE(bad_job.payload_json->>'source_change_sequence', '') ~ '^[0-9]{1,18}$' THEN (bad_job.payload_json->>'source_change_sequence')::bigint ELSE NULL::bigint END,
          CASE WHEN COALESCE(bad_job.payload_json#>>'{source_build,source_change_seq}', '') ~ '^[0-9]{1,18}$' THEN (bad_job.payload_json#>>'{source_build,source_change_seq}')::bigint ELSE NULL::bigint END,
          CASE WHEN COALESCE(zero_poisoned_scope.scope_error_json->>'source_change_seq', '') ~ '^[0-9]{1,18}$' THEN (zero_poisoned_scope.scope_error_json->>'source_change_seq')::bigint ELSE NULL::bigint END,
          COALESCE(app_counter.seq, 0)::bigint,
          0::bigint
        ) AS repaired_source_change_seq,
        COALESCE(
          CASE WHEN COALESCE(bad_job.payload_json->>'session_version', '') ~ '^[0-9]{1,18}$' THEN (bad_job.payload_json->>'session_version')::bigint ELSE NULL::bigint END,
          CASE WHEN COALESCE(bad_job.payload_json#>>'{source_build,session_version}', '') ~ '^[0-9]{1,18}$' THEN (bad_job.payload_json#>>'{source_build,session_version}')::bigint ELSE NULL::bigint END,
          target_session.version,
          1::bigint
        ) AS repaired_session_version,
        COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
          bad_job.payload_json->>'refresh_scope_kind',
          bad_job.payload_json#>>'{source_build,refresh_scope_kind}',
          zero_poisoned_scope.scope_error_json->>'refresh_scope_kind',
          ''
        ))), ''), 'CANDIDATE_FULL_LIVE') AS repaired_refresh_scope_kind,
        COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
          bad_job.payload_json->>'pay_channel_scope',
          bad_job.payload_json#>>'{source_build,pay_channel_scope}',
          zero_poisoned_scope.scope_error_json->>'pay_channel_scope',
          ''
        ))), ''), 'ALL') AS repaired_pay_channel_scope,
        COALESCE(NULLIF(BTRIM(COALESCE(
          bad_job.payload_json->>'fallback_reason',
          bad_job.payload_json->>'refresh_reason',
          bad_job.payload_json->>'reason',
          bad_job.payload_json#>>'{source_build,reason}',
          zero_poisoned_scope.scope_error_json->>'reason',
          ''
        )), ''), 'CLONE_REBASE_INELIGIBLE') AS repaired_reason
      FROM zero_poisoned_scope
      JOIN LATERAL (
        SELECT zero_poisoned_scope.bad_job_id_text::uuid AS bad_job_id
        WHERE zero_poisoned_scope.bad_job_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      ) AS bad_job_id ON true
      JOIN public.banking_pay_workbench_jobs AS bad_job
        ON bad_job.id = bad_job_id.bad_job_id
      JOIN public.banking_pay_workbench_sessions AS target_session
        ON target_session.id = zero_poisoned_scope.session_id
      LEFT JOIN public.app_change_counters AS app_counter
        ON app_counter.entity_key = 'pay_candidate:' || zero_poisoned_scope.candidate_id::text
      WHERE bad_job.session_id = zero_poisoned_scope.session_id
        AND bad_job.candidate_id = zero_poisoned_scope.candidate_id
        AND UPPER(BTRIM(COALESCE(bad_job.job_type, ''))) IN (
          'WORKBENCH_CANDIDATE_SOURCE_BUILD',
          'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK',
          'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE',
          'CANDIDATE_SOURCE_BUILD',
          'CANDIDATE_SOURCE_BUILD_CHUNK',
          'SOURCE_BUILD',
          'SOURCE_BUILD_PAGE'
        )
        AND UPPER(BTRIM(COALESCE(bad_job.status, ''))) IN ('FAILED', 'DEAD')
        AND NULLIF(BTRIM(COALESCE(
          bad_job.payload_json->>'source_build_run_id',
          bad_job.payload_json#>>'{source_build,source_build_run_id}',
          bad_job.payload_json#>>'{source_build,run_id}',
          bad_job.payload_json#>>'{cursor,source_build_run_id}',
          bad_job.payload_json#>>'{cursor_json,source_build_run_id}',
          bad_job.payload_json#>>'{result_json,source_build_run_id}',
          ''
        )), '') IS NULL
        AND (
          COALESCE(bad_job.last_error_json, '{}'::jsonb)::text ILIKE '%PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_RUN_ID_REQUIRED%'
          OR COALESCE(zero_poisoned_scope.scope_error_json, '{}'::jsonb)::text ILIKE '%PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_RUN_ID_REQUIRED%'
          OR COALESCE(bad_job.payload_json, '{}'::jsonb)::text ILIKE '%CLONE_REBASE_INELIGIBLE_SOURCE_BUILD%'
          OR COALESCE(zero_poisoned_scope.scope_error_json, '{}'::jsonb)::text ILIKE '%CLONE_REBASE_INELIGIBLE_SOURCE_BUILD%'
        )
        AND COALESCE(
          CASE WHEN COALESCE(zero_poisoned_scope.scope_error_json->>'source_rows_marked_error_count', '') ~ '^[0-9]+$' THEN (zero_poisoned_scope.scope_error_json->>'source_rows_marked_error_count')::integer ELSE NULL::integer END,
          CASE WHEN COALESCE(zero_poisoned_scope.scope_error_json#>>'{job_error_json,source_rows_marked_error_count}', '') ~ '^[0-9]+$' THEN (zero_poisoned_scope.scope_error_json#>>'{job_error_json,source_rows_marked_error_count}')::integer ELSE NULL::integer END,
          CASE WHEN COALESCE(bad_job.last_error_json->>'source_rows_marked_error_count', '') ~ '^[0-9]+$' THEN (bad_job.last_error_json->>'source_rows_marked_error_count')::integer ELSE NULL::integer END,
          CASE WHEN COALESCE(bad_job.payload_json#>>'{last_failure_json,source_rows_marked_error_count}', '') ~ '^[0-9]+$' THEN (bad_job.payload_json#>>'{last_failure_json,source_rows_marked_error_count}')::integer ELSE NULL::integer END,
          0
        ) = 0
        AND NOT EXISTS (
          SELECT 1
          FROM public.banking_pay_workbench_candidate_source_lines AS error_source_line
          WHERE error_source_line.session_id = zero_poisoned_scope.session_id
            AND error_source_line.candidate_id = zero_poisoned_scope.candidate_id
            AND UPPER(BTRIM(COALESCE(error_source_line.status, ''))) = 'ERROR'
        )
    ), zero_authority AS (
      SELECT
        zero_bad_scope.*,
        source_session.id AS source_session_id,
        source_session.version AS source_session_version,
        source_session.session_signature AS source_session_signature,
        source_session.source_snapshot_run_id AS source_snapshot_run_id,
        COALESCE(targeted_ids.targeted_timesheet_ids_json, '[]'::jsonb) AS targeted_timesheet_ids_json,
        COALESCE(linked_ids.linked_timesheet_ids_json, '[]'::jsonb) AS linked_timesheet_ids_json,
        CASE
          WHEN zero_bad_scope.source_session_id_text IS NULL THEN true
          WHEN zero_bad_scope.source_session_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
               AND source_session.id IS NOT NULL THEN true
          ELSE false
        END AS authority_ok,
        CASE
          WHEN zero_bad_scope.source_session_id_text IS NOT NULL
               AND zero_bad_scope.source_session_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN 'ZERO_SOURCE_ROW_REPAIR_INVALID_SOURCE_SESSION_ID'
          WHEN zero_bad_scope.source_session_id_text IS NOT NULL
               AND source_session.id IS NULL
            THEN 'ZERO_SOURCE_ROW_REPAIR_SOURCE_SESSION_NOT_FOUND'
          WHEN zero_bad_scope.target_session_signature IS NULL
               OR zero_bad_scope.target_source_snapshot_run_id IS NULL
            THEN 'ZERO_SOURCE_ROW_REPAIR_INSUFFICIENT_SOURCE_BUILD_AUTHORITY'
          ELSE NULL::text
        END AS authority_skip_reason
      FROM zero_bad_scope
      LEFT JOIN public.banking_pay_workbench_sessions AS source_session
        ON source_session.id = CASE
          WHEN zero_bad_scope.source_session_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN zero_bad_scope.source_session_id_text::uuid
          ELSE NULL::uuid
        END
      CROSS JOIN LATERAL (
        SELECT COALESCE(jsonb_agg(targeted_sorted.timesheet_id_text ORDER BY targeted_sorted.timesheet_id_text), '[]'::jsonb) AS targeted_timesheet_ids_json
        FROM (
          SELECT DISTINCT targeted_raw.timesheet_id_text
          FROM (
            SELECT NULLIF(BTRIM(targeted_value.value), '') AS timesheet_id_text
            FROM jsonb_array_elements_text(
              CASE
                WHEN jsonb_typeof(COALESCE(zero_bad_scope.bad_job_payload_json, '{}'::jsonb)->'targeted_timesheet_ids') = 'array'
                  THEN COALESCE(zero_bad_scope.bad_job_payload_json, '{}'::jsonb)->'targeted_timesheet_ids'
                WHEN jsonb_typeof(COALESCE(zero_bad_scope.bad_job_payload_json, '{}'::jsonb)->'targeted_timesheet_ids') = 'string'
                  THEN jsonb_build_array(COALESCE(zero_bad_scope.bad_job_payload_json, '{}'::jsonb)->>'targeted_timesheet_ids')
                ELSE '[]'::jsonb
              END
            ) AS targeted_value(value)
            UNION ALL
            SELECT NULLIF(BTRIM(targeted_nested_value.value), '') AS timesheet_id_text
            FROM jsonb_array_elements_text(
              CASE
                WHEN jsonb_typeof((COALESCE(zero_bad_scope.bad_job_payload_json, '{}'::jsonb)#>'{source_build,targeted_timesheet_ids}')) = 'array'
                  THEN COALESCE(zero_bad_scope.bad_job_payload_json, '{}'::jsonb)#>'{source_build,targeted_timesheet_ids}'
                WHEN jsonb_typeof((COALESCE(zero_bad_scope.bad_job_payload_json, '{}'::jsonb)#>'{source_build,targeted_timesheet_ids}')) = 'string'
                  THEN jsonb_build_array(COALESCE(zero_bad_scope.bad_job_payload_json, '{}'::jsonb)#>>'{source_build,targeted_timesheet_ids}')
                ELSE '[]'::jsonb
              END
            ) AS targeted_nested_value(value)
          ) AS targeted_raw
          WHERE targeted_raw.timesheet_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        ) AS targeted_sorted
      ) AS targeted_ids
      CROSS JOIN LATERAL (
        SELECT COALESCE(jsonb_agg(linked_sorted.timesheet_id_text ORDER BY linked_sorted.timesheet_id_text), '[]'::jsonb) AS linked_timesheet_ids_json
        FROM (
          SELECT DISTINCT linked_raw.timesheet_id_text
          FROM (
            SELECT NULLIF(BTRIM(linked_value.value), '') AS timesheet_id_text
            FROM jsonb_array_elements_text(
              CASE
                WHEN jsonb_typeof(COALESCE(zero_bad_scope.bad_job_payload_json, '{}'::jsonb)->'linked_timesheet_ids') = 'array'
                  THEN COALESCE(zero_bad_scope.bad_job_payload_json, '{}'::jsonb)->'linked_timesheet_ids'
                WHEN jsonb_typeof(COALESCE(zero_bad_scope.bad_job_payload_json, '{}'::jsonb)->'linked_timesheet_ids') = 'string'
                  THEN jsonb_build_array(COALESCE(zero_bad_scope.bad_job_payload_json, '{}'::jsonb)->>'linked_timesheet_ids')
                ELSE '[]'::jsonb
              END
            ) AS linked_value(value)
            UNION ALL
            SELECT NULLIF(BTRIM(linked_nested_value.value), '') AS timesheet_id_text
            FROM jsonb_array_elements_text(
              CASE
                WHEN jsonb_typeof((COALESCE(zero_bad_scope.bad_job_payload_json, '{}'::jsonb)#>'{source_build,linked_timesheet_ids}')) = 'array'
                  THEN COALESCE(zero_bad_scope.bad_job_payload_json, '{}'::jsonb)#>'{source_build,linked_timesheet_ids}'
                WHEN jsonb_typeof((COALESCE(zero_bad_scope.bad_job_payload_json, '{}'::jsonb)#>'{source_build,linked_timesheet_ids}')) = 'string'
                  THEN jsonb_build_array(COALESCE(zero_bad_scope.bad_job_payload_json, '{}'::jsonb)#>>'{source_build,linked_timesheet_ids}')
                ELSE '[]'::jsonb
              END
            ) AS linked_nested_value(value)
          ) AS linked_raw
          WHERE linked_raw.timesheet_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        ) AS linked_sorted
      ) AS linked_ids
    )
    SELECT *
    FROM zero_authority
  LOOP
    v_processed_count := v_processed_count + 1;
    v_progress_recompute_json := '{}'::jsonb;
    v_progress_recompute_failed := false;
    v_progress_recompute_error_json := NULL::jsonb;
    v_zero_corrected_job_id := NULL::uuid;
    v_zero_corrected_job_status := NULL::text;
    v_zero_corrected_job_payload_json := '{}'::jsonb;
    v_zero_existing_corrected_failed_job_id := NULL::uuid;
    v_zero_corrected_job_action := NULL::text;
    v_zero_source_change_seq := COALESCE(v_zero_repair_row.repaired_source_change_seq, 0);
    v_zero_session_version := COALESCE(v_zero_repair_row.repaired_session_version, v_zero_repair_row.target_session_version, 1);
    v_zero_refresh_scope_kind := COALESCE(NULLIF(UPPER(BTRIM(v_zero_repair_row.repaired_refresh_scope_kind)), ''), 'CANDIDATE_FULL_LIVE');
    v_zero_pay_channel_scope := COALESCE(NULLIF(UPPER(BTRIM(v_zero_repair_row.repaired_pay_channel_scope)), ''), 'ALL');
    v_zero_reason := COALESCE(NULLIF(BTRIM(v_zero_repair_row.repaired_reason), ''), 'CLONE_REBASE_INELIGIBLE');
    v_zero_source_session_id := v_zero_repair_row.source_session_id;
    v_zero_source_session_id_text := v_zero_repair_row.source_session_id_text;
    v_zero_source_session_version := v_zero_repair_row.source_session_version;
    v_zero_source_session_signature := v_zero_repair_row.source_session_signature;
    v_zero_source_snapshot_run_id := v_zero_repair_row.source_snapshot_run_id;
    v_zero_targeted_timesheet_ids_json := COALESCE(v_zero_repair_row.targeted_timesheet_ids_json, '[]'::jsonb);
    v_zero_linked_timesheet_ids_json := COALESCE(v_zero_repair_row.linked_timesheet_ids_json, '[]'::jsonb);

    IF COALESCE(v_zero_repair_row.authority_ok, false) IS NOT TRUE THEN
      v_skipped_count := v_skipped_count + 1;
      v_zero_source_row_skips_json := v_zero_source_row_skips_json || jsonb_build_array(jsonb_build_object(
        'session_id', v_zero_repair_row.session_id::text,
        'candidate_id', v_zero_repair_row.candidate_id::text,
        'bad_job_id', v_zero_repair_row.bad_job_id::text,
        'reason', COALESCE(v_zero_repair_row.authority_skip_reason, 'ZERO_SOURCE_ROW_REPAIR_INSUFFICIENT_SOURCE_BUILD_AUTHORITY'),
        'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
      ));
      v_skips_json := v_skips_json || jsonb_build_array(jsonb_build_object(
        'session_id', v_zero_repair_row.session_id::text,
        'candidate_id', v_zero_repair_row.candidate_id::text,
        'bad_job_id', v_zero_repair_row.bad_job_id::text,
        'reason', COALESCE(v_zero_repair_row.authority_skip_reason, 'ZERO_SOURCE_ROW_REPAIR_INSUFFICIENT_SOURCE_BUILD_AUTHORITY'),
        'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
      ));
      CONTINUE;
    END IF;

    v_zero_source_build_seed_text := concat_ws(
      ':',
      'WORKBENCH_CANDIDATE_SOURCE_BUILD',
      'ZERO_SOURCE_ROW_POISON_REPAIR',
      'target_session_id', v_zero_repair_row.session_id::text,
      'target_session_version', COALESCE(v_zero_session_version, 1)::text,
      'target_session_signature', COALESCE(v_zero_repair_row.target_session_signature, ''),
      'target_snapshot_run_id', COALESCE(v_zero_repair_row.target_source_snapshot_run_id::text, ''),
      'source_session_id', COALESCE(v_zero_source_session_id::text, COALESCE(v_zero_source_session_id_text, '')),
      'source_session_version', COALESCE(v_zero_source_session_version::text, ''),
      'source_session_signature', COALESCE(v_zero_source_session_signature, ''),
      'source_snapshot_run_id', COALESCE(v_zero_source_snapshot_run_id::text, ''),
      'candidate_id', v_zero_repair_row.candidate_id::text,
      'source_change_seq', COALESCE(v_zero_source_change_seq, 0)::text,
      'refresh_scope_kind', v_zero_refresh_scope_kind,
      'targeted_timesheet_ids', COALESCE(v_zero_targeted_timesheet_ids_json, '[]'::jsonb)::text,
      'linked_timesheet_ids', COALESCE(v_zero_linked_timesheet_ids_json, '[]'::jsonb)::text,
      'pay_channel_scope', v_zero_pay_channel_scope,
      'clone_from_session_id', COALESCE(v_zero_source_session_id::text, COALESCE(v_zero_source_session_id_text, '')),
      'clone_to_session_id', v_zero_repair_row.session_id::text,
      'reason', v_zero_reason
    );
    v_zero_source_build_hash := md5(v_zero_source_build_seed_text);
    v_zero_source_build_run_id := (
      substr(v_zero_source_build_hash, 1, 8) || '-' ||
      substr(v_zero_source_build_hash, 9, 4) || '-' ||
      substr(v_zero_source_build_hash, 13, 4) || '-' ||
      substr(v_zero_source_build_hash, 17, 4) || '-' ||
      substr(v_zero_source_build_hash, 21, 12)
    )::uuid;
    v_zero_corrected_dedupe_key := 'WORKBENCH_CANDIDATE_SOURCE_BUILD:session:' || v_zero_repair_row.session_id::text || ':candidate:' || v_zero_repair_row.candidate_id::text || ':clone_ineligible:corrected:' || v_zero_source_build_run_id::text;

    v_zero_corrected_payload_json := jsonb_strip_nulls(
      jsonb_build_object(
        'session_id', v_zero_repair_row.session_id::text,
        'candidate_id', v_zero_repair_row.candidate_id::text,
        'session_version', v_zero_session_version,
        'source_change_seq', COALESCE(v_zero_source_change_seq, 0),
        'source_change_sequence', COALESCE(v_zero_source_change_seq, 0),
        'source_build_run_id', v_zero_source_build_run_id::text,
        'operation_type', 'CLONE_REBASE_INELIGIBLE_SOURCE_BUILD',
        'fallback_reason', v_zero_reason,
        'refresh_reason', v_zero_reason,
        'reason', v_zero_reason,
        'refresh_scope_kind', v_zero_refresh_scope_kind,
        'pay_channel_scope', v_zero_pay_channel_scope,
        'source_snapshot_run_id', v_zero_repair_row.target_source_snapshot_run_id::text,
        'snapshot_run_id', v_zero_repair_row.target_source_snapshot_run_id::text,
        'source_session_id', CASE WHEN v_zero_source_session_id IS NULL THEN NULL ELSE v_zero_source_session_id::text END,
        'clone_from_session_id', COALESCE(v_zero_source_session_id::text, v_zero_source_session_id_text),
        'clone_to_session_id', v_zero_repair_row.session_id::text,
        'target_session_signature', v_zero_repair_row.target_session_signature,
        'source_session_signature', v_zero_source_session_signature,
        'force_legacy', true,
        'source_build_required', true,
        'line_work_required', true,
        'delta_refresh_required', false
      )
      || jsonb_build_object(
        'targeted_timesheet_ids', COALESCE(v_zero_targeted_timesheet_ids_json, '[]'::jsonb),
        'linked_timesheet_ids', COALESCE(v_zero_linked_timesheet_ids_json, '[]'::jsonb),
        'zero_source_row_poison_repair', true,
        'zero_source_row_bad_job_id', v_zero_repair_row.bad_job_id::text,
        'zero_source_row_original_dedupe_key', v_zero_repair_row.bad_job_dedupe_key,
        'source_build_run_id_source', jsonb_build_object(
          'method', 'DETERMINISTIC_MD5_UUID_FROM_AUTHORITY_INPUTS',
          'seed_text', v_zero_source_build_seed_text,
          'target_session_id', v_zero_repair_row.session_id::text,
          'target_session_version', v_zero_session_version,
          'target_session_signature', v_zero_repair_row.target_session_signature,
          'target_snapshot_run_id', v_zero_repair_row.target_source_snapshot_run_id::text,
          'source_session_id', CASE WHEN v_zero_source_session_id IS NULL THEN NULL ELSE v_zero_source_session_id::text END,
          'source_session_version', v_zero_source_session_version,
          'source_session_signature', v_zero_source_session_signature,
          'source_snapshot_run_id', CASE WHEN v_zero_source_snapshot_run_id IS NULL THEN NULL ELSE v_zero_source_snapshot_run_id::text END,
          'candidate_id', v_zero_repair_row.candidate_id::text,
          'source_change_seq', COALESCE(v_zero_source_change_seq, 0),
          'refresh_scope_kind', v_zero_refresh_scope_kind,
          'targeted_timesheet_ids', COALESCE(v_zero_targeted_timesheet_ids_json, '[]'::jsonb),
          'linked_timesheet_ids', COALESCE(v_zero_linked_timesheet_ids_json, '[]'::jsonb),
          'pay_channel_scope', v_zero_pay_channel_scope,
          'clone_from_session_id', COALESCE(v_zero_source_session_id::text, v_zero_source_session_id_text),
          'clone_to_session_id', v_zero_repair_row.session_id::text
        )
      )
      || jsonb_build_object(
        'source_build', jsonb_build_object(
          'required', true,
          'run_id', v_zero_source_build_run_id::text,
          'source_build_run_id', v_zero_source_build_run_id::text,
          'source_change_seq', COALESCE(v_zero_source_change_seq, 0),
          'source_change_sequence', COALESCE(v_zero_source_change_seq, 0),
          'session_version', v_zero_session_version,
          'refresh_scope_kind', v_zero_refresh_scope_kind,
          'pay_channel_scope', v_zero_pay_channel_scope,
          'targeted_timesheet_ids', COALESCE(v_zero_targeted_timesheet_ids_json, '[]'::jsonb),
          'linked_timesheet_ids', COALESCE(v_zero_linked_timesheet_ids_json, '[]'::jsonb),
          'reason', v_zero_reason
        ),
        'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
      )
    );

    SELECT corrected_job.id,
           corrected_job.status,
           COALESCE(corrected_job.payload_json, '{}'::jsonb)
    INTO v_zero_corrected_job_id,
         v_zero_corrected_job_status,
         v_zero_corrected_job_payload_json
    FROM public.banking_pay_workbench_jobs AS corrected_job
    WHERE corrected_job.session_id = v_zero_repair_row.session_id
      AND corrected_job.candidate_id = v_zero_repair_row.candidate_id
      AND corrected_job.dedupe_key = v_zero_corrected_dedupe_key
      AND corrected_job.status IN ('QUEUED', 'RUNNING')
    ORDER BY CASE WHEN corrected_job.status = 'QUEUED' THEN 0 ELSE 1 END,
             corrected_job.updated_at_utc DESC NULLS LAST,
             corrected_job.created_at_utc DESC NULLS LAST,
             corrected_job.id DESC
    LIMIT 1
    FOR UPDATE SKIP LOCKED;

    IF v_zero_corrected_job_id IS NOT NULL THEN
      v_zero_corrected_job_action := 'REUSED_ACTIVE_CORRECTED_SOURCE_BUILD_JOB';
      v_corrected_source_build_job_reused_count := v_corrected_source_build_job_reused_count + 1;
    ELSE
      SELECT corrected_job.id,
             corrected_job.status,
             COALESCE(corrected_job.payload_json, '{}'::jsonb)
      INTO v_zero_corrected_job_id,
           v_zero_corrected_job_status,
           v_zero_corrected_job_payload_json
      FROM public.banking_pay_workbench_jobs AS corrected_job
      WHERE corrected_job.session_id = v_zero_repair_row.session_id
        AND corrected_job.candidate_id = v_zero_repair_row.candidate_id
        AND corrected_job.dedupe_key = v_zero_corrected_dedupe_key
        AND corrected_job.status IN ('QUEUED', 'RUNNING')
      ORDER BY CASE WHEN corrected_job.status = 'QUEUED' THEN 0 ELSE 1 END,
               corrected_job.updated_at_utc DESC NULLS LAST,
               corrected_job.created_at_utc DESC NULLS LAST,
               corrected_job.id DESC
      LIMIT 1;

      IF v_zero_corrected_job_id IS NOT NULL THEN
        v_zero_corrected_job_action := 'REUSED_ACTIVE_CORRECTED_SOURCE_BUILD_JOB_NOT_LOCKED';
        v_corrected_source_build_job_reused_count := v_corrected_source_build_job_reused_count + 1;
      ELSE
        SELECT corrected_job.id,
               corrected_job.status,
               COALESCE(corrected_job.payload_json, '{}'::jsonb)
        INTO v_zero_corrected_job_id,
             v_zero_corrected_job_status,
             v_zero_corrected_job_payload_json
        FROM public.banking_pay_workbench_jobs AS corrected_job
        WHERE corrected_job.session_id = v_zero_repair_row.session_id
          AND corrected_job.candidate_id = v_zero_repair_row.candidate_id
          AND corrected_job.dedupe_key = v_zero_corrected_dedupe_key
          AND corrected_job.status = 'SUCCEEDED'
        ORDER BY corrected_job.completed_at_utc DESC NULLS LAST,
                 corrected_job.updated_at_utc DESC NULLS LAST,
                 corrected_job.created_at_utc DESC NULLS LAST,
                 corrected_job.id DESC
        LIMIT 1;

        IF v_zero_corrected_job_id IS NOT NULL THEN
          v_zero_corrected_job_action := 'REUSED_SUCCEEDED_CORRECTED_SOURCE_BUILD_JOB';
          v_corrected_source_build_job_succeeded_reused_count := v_corrected_source_build_job_succeeded_reused_count + 1;
        ELSE
          SELECT corrected_job.id
          INTO v_zero_existing_corrected_failed_job_id
          FROM public.banking_pay_workbench_jobs AS corrected_job
          CROSS JOIN LATERAL (
            SELECT NULLIF(BTRIM(COALESCE(
              corrected_job.payload_json->>'source_build_run_id',
              corrected_job.payload_json#>>'{source_build,source_build_run_id}',
              corrected_job.payload_json#>>'{source_build,run_id}',
              corrected_job.payload_json#>>'{cursor,source_build_run_id}',
              corrected_job.payload_json#>>'{cursor_json,source_build_run_id}',
              corrected_job.payload_json#>>'{result_json,source_build_run_id}',
              ''
            )), '') AS source_build_run_id_text
          ) AS corrected_extract
          WHERE corrected_job.session_id = v_zero_repair_row.session_id
            AND corrected_job.candidate_id = v_zero_repair_row.candidate_id
            AND corrected_job.dedupe_key = v_zero_corrected_dedupe_key
            AND corrected_job.status IN ('FAILED', 'DEAD')
            AND corrected_extract.source_build_run_id_text = v_zero_source_build_run_id::text
          ORDER BY corrected_job.updated_at_utc DESC NULLS LAST,
                   corrected_job.created_at_utc DESC NULLS LAST,
                   corrected_job.id DESC
          LIMIT 1;

          IF v_zero_existing_corrected_failed_job_id IS NOT NULL THEN
            v_skipped_count := v_skipped_count + 1;
            v_zero_source_row_skips_json := v_zero_source_row_skips_json || jsonb_build_array(jsonb_build_object(
              'session_id', v_zero_repair_row.session_id::text,
              'candidate_id', v_zero_repair_row.candidate_id::text,
              'bad_job_id', v_zero_repair_row.bad_job_id::text,
              'corrected_failed_job_id', v_zero_existing_corrected_failed_job_id::text,
              'corrected_source_build_run_id', v_zero_source_build_run_id::text,
              'reason', 'ZERO_SOURCE_ROW_CORRECTED_JOB_ALREADY_FAILED_OR_DEAD',
              'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
            ));
            v_skips_json := v_skips_json || jsonb_build_array(jsonb_build_object(
              'session_id', v_zero_repair_row.session_id::text,
              'candidate_id', v_zero_repair_row.candidate_id::text,
              'bad_job_id', v_zero_repair_row.bad_job_id::text,
              'corrected_failed_job_id', v_zero_existing_corrected_failed_job_id::text,
              'reason', 'ZERO_SOURCE_ROW_CORRECTED_JOB_ALREADY_FAILED_OR_DEAD',
              'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
            ));
            CONTINUE;
          END IF;

          INSERT INTO public.banking_pay_workbench_jobs (
            job_type,
            status,
            priority,
            run_at_utc,
            dedupe_key,
            snapshot_run_id,
            session_id,
            candidate_id,
            payload_json,
            created_at_utc,
            updated_at_utc
          )
          VALUES (
            'WORKBENCH_CANDIDATE_SOURCE_BUILD',
            'QUEUED',
            60,
            v_now,
            v_zero_corrected_dedupe_key,
            v_zero_repair_row.target_source_snapshot_run_id,
            v_zero_repair_row.session_id,
            v_zero_repair_row.candidate_id,
            v_zero_corrected_payload_json,
            v_now,
            v_now
          )
          ON CONFLICT (dedupe_key) WHERE status IN ('QUEUED', 'RUNNING')
          DO UPDATE
          SET run_at_utc = LEAST(public.banking_pay_workbench_jobs.run_at_utc, EXCLUDED.run_at_utc),
              priority = LEAST(public.banking_pay_workbench_jobs.priority, EXCLUDED.priority),
              payload_json = jsonb_strip_nulls(COALESCE(public.banking_pay_workbench_jobs.payload_json, '{}'::jsonb) || EXCLUDED.payload_json),
              updated_at_utc = v_now
          WHERE public.banking_pay_workbench_jobs.status = 'QUEUED'
          RETURNING id, status, payload_json
          INTO v_zero_corrected_job_id, v_zero_corrected_job_status, v_zero_corrected_job_payload_json;

          IF v_zero_corrected_job_id IS NOT NULL THEN
            v_zero_corrected_job_action := 'QUEUED_CORRECTED_SOURCE_BUILD_JOB';
            v_corrected_source_build_job_queued_count := v_corrected_source_build_job_queued_count + 1;
          ELSE
            SELECT corrected_job.id,
                   corrected_job.status,
                   COALESCE(corrected_job.payload_json, '{}'::jsonb)
            INTO v_zero_corrected_job_id,
                 v_zero_corrected_job_status,
                 v_zero_corrected_job_payload_json
            FROM public.banking_pay_workbench_jobs AS corrected_job
            WHERE corrected_job.session_id = v_zero_repair_row.session_id
              AND corrected_job.candidate_id = v_zero_repair_row.candidate_id
              AND corrected_job.dedupe_key = v_zero_corrected_dedupe_key
              AND corrected_job.status IN ('QUEUED', 'RUNNING', 'SUCCEEDED')
            ORDER BY CASE WHEN corrected_job.status = 'QUEUED' THEN 0 WHEN corrected_job.status = 'RUNNING' THEN 1 ELSE 2 END,
                     corrected_job.updated_at_utc DESC NULLS LAST,
                     corrected_job.created_at_utc DESC NULLS LAST,
                     corrected_job.id DESC
            LIMIT 1;

            IF v_zero_corrected_job_id IS NOT NULL THEN
              v_zero_corrected_job_action := 'REUSED_CORRECTED_SOURCE_BUILD_JOB_AFTER_CONFLICT';
              IF v_zero_corrected_job_status = 'SUCCEEDED' THEN
                v_corrected_source_build_job_succeeded_reused_count := v_corrected_source_build_job_succeeded_reused_count + 1;
              ELSE
                v_corrected_source_build_job_reused_count := v_corrected_source_build_job_reused_count + 1;
              END IF;
            END IF;
          END IF;
        END IF;
      END IF;
    END IF;

    IF v_zero_corrected_job_id IS NULL THEN
      v_skipped_count := v_skipped_count + 1;
      v_zero_source_row_skips_json := v_zero_source_row_skips_json || jsonb_build_array(jsonb_build_object(
        'session_id', v_zero_repair_row.session_id::text,
        'candidate_id', v_zero_repair_row.candidate_id::text,
        'bad_job_id', v_zero_repair_row.bad_job_id::text,
        'corrected_source_build_run_id', v_zero_source_build_run_id::text,
        'reason', 'ZERO_SOURCE_ROW_CORRECTED_JOB_ENQUEUE_FAILED',
        'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
      ));
      v_skips_json := v_skips_json || jsonb_build_array(jsonb_build_object(
        'session_id', v_zero_repair_row.session_id::text,
        'candidate_id', v_zero_repair_row.candidate_id::text,
        'bad_job_id', v_zero_repair_row.bad_job_id::text,
        'reason', 'ZERO_SOURCE_ROW_CORRECTED_JOB_ENQUEUE_FAILED',
        'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
      ));
      CONTINUE;
    END IF;

    SELECT jsonb_build_object(
      'session_id', v_zero_repair_row.session_id::text,
      'candidate_id', v_zero_repair_row.candidate_id::text,
      'bad_job_id', bad_job.id::text,
      'job_type', bad_job.job_type,
      'status', bad_job.status,
      'attempt_count', bad_job.attempt_count,
      'max_attempts', bad_job.max_attempts,
      'dedupe_key', bad_job.dedupe_key,
      'payload_json', bad_job.payload_json,
      'last_error_json', bad_job.last_error_json,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_zero_bad_job_before_json
    FROM public.banking_pay_workbench_jobs AS bad_job
    WHERE bad_job.id = v_zero_repair_row.bad_job_id
    FOR UPDATE;

    UPDATE public.banking_pay_workbench_jobs AS bad_job_update
    SET payload_json = jsonb_strip_nulls(
          COALESCE(bad_job_update.payload_json, '{}'::jsonb)
          || jsonb_build_object(
            'invalid_source_build_without_run_id_failed_closed', true,
            'invalid_source_build_without_run_id_non_blocking', true,
            'non_blocking_terminal_failure', true,
            'non_blocking_terminal_failure_reason', 'MISSING_SOURCE_BUILD_RUN_ID_IS_NOT_AUTHORITATIVE',
            'non_blocking_terminal_failure_at_utc', v_now::text,
            'zero_source_row_repair_resolved', true,
            'zero_source_row_repair_resolved_at_utc', v_now::text,
            'zero_source_row_corrected_job_id', v_zero_corrected_job_id::text,
            'zero_source_row_corrected_source_build_run_id', v_zero_source_build_run_id::text,
            'zero_source_row_corrected_dedupe_key', v_zero_corrected_dedupe_key,
            'source_rows_marked_error_count', COALESCE(v_zero_repair_row.source_rows_marked_error_count, 0),
            'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
          )
        ),
        updated_at_utc = v_now
    WHERE bad_job_update.id = v_zero_repair_row.bad_job_id
    RETURNING jsonb_build_object(
      'session_id', v_zero_repair_row.session_id::text,
      'candidate_id', v_zero_repair_row.candidate_id::text,
      'bad_job_id', bad_job_update.id::text,
      'job_type', bad_job_update.job_type,
      'status', bad_job_update.status,
      'retained_terminal', true,
      'hard_deleted', false,
      'bad_job_mutated', true,
      'zero_source_row_repair_resolved', true,
      'non_blocking_terminal_failure', true,
      'invalid_source_build_without_run_id_non_blocking', true,
      'corrected_source_build_job_id', v_zero_corrected_job_id::text,
      'corrected_source_build_run_id', v_zero_source_build_run_id::text,
      'corrected_dedupe_key', v_zero_corrected_dedupe_key,
      'reason', v_reason,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_zero_bad_job_after_json;

    PERFORM public._audit_insert(
      'banking_pay_workbench_job',
      v_zero_repair_row.bad_job_id::text,
      'ZERO_SOURCE_ROW_BAD_JOB_MARKED_NON_BLOCKING',
      v_zero_bad_job_before_json,
      v_zero_bad_job_after_json,
      'ZERO_SOURCE_ROW_INVALID_SOURCE_BUILD_WITHOUT_RUN_ID_FAILED_CLOSED',
      NULL
    );

    SELECT jsonb_build_object(
      'id', corrected_job.id::text,
      'job_type', corrected_job.job_type,
      'status', corrected_job.status,
      'dedupe_key', corrected_job.dedupe_key,
      'session_id', CASE WHEN corrected_job.session_id IS NULL THEN NULL ELSE corrected_job.session_id::text END,
      'candidate_id', CASE WHEN corrected_job.candidate_id IS NULL THEN NULL ELSE corrected_job.candidate_id::text END,
      'source_build_run_id', v_zero_source_build_run_id::text,
      'payload_json', corrected_job.payload_json,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_zero_corrected_job_after_json
    FROM public.banking_pay_workbench_jobs AS corrected_job
    WHERE corrected_job.id = v_zero_corrected_job_id;

    PERFORM public._audit_insert(
      'banking_pay_workbench_job',
      v_zero_corrected_job_id::text,
      COALESCE(v_zero_corrected_job_action, 'CORRECTED_SOURCE_BUILD_JOB_REUSED'),
      v_zero_corrected_job_before_json,
      v_zero_corrected_job_after_json,
      'ZERO_SOURCE_ROW_CORRECTED_SOURCE_BUILD_JOB_READY',
      NULL
    );

    SELECT jsonb_build_object(
      'id', scope_row.id::text,
      'session_id', scope_row.session_id::text,
      'candidate_id', scope_row.candidate_id::text,
      'status', scope_row.status,
      'dirty', scope_row.dirty,
      'seeded', scope_row.seeded,
      'pending_job_id', CASE WHEN scope_row.pending_job_id IS NULL THEN NULL ELSE scope_row.pending_job_id::text END,
      'error_json', scope_row.error_json,
      'bad_job_id', v_zero_repair_row.bad_job_id::text,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_zero_scope_before_json
    FROM public.banking_pay_workbench_session_scope AS scope_row
    WHERE scope_row.id = v_zero_repair_row.scope_id
    FOR UPDATE;

    UPDATE public.banking_pay_workbench_session_scope AS scope_row
    SET status = 'SOURCE_BUILD_PENDING',
        pending_job_id = v_zero_corrected_job_id,
        seeded = false,
        dirty = true,
        error_json = NULL::jsonb,
        updated_at_utc = v_now
    WHERE scope_row.id = v_zero_repair_row.scope_id
      AND scope_row.session_id = v_zero_repair_row.session_id
      AND scope_row.candidate_id = v_zero_repair_row.candidate_id
    RETURNING jsonb_build_object(
      'id', scope_row.id::text,
      'session_id', scope_row.session_id::text,
      'candidate_id', scope_row.candidate_id::text,
      'status', scope_row.status,
      'dirty', scope_row.dirty,
      'seeded', scope_row.seeded,
      'pending_job_id', CASE WHEN scope_row.pending_job_id IS NULL THEN NULL ELSE scope_row.pending_job_id::text END,
      'error_json', scope_row.error_json,
      'bad_job_id', v_zero_repair_row.bad_job_id::text,
      'corrected_source_build_job_id', v_zero_corrected_job_id::text,
      'corrected_source_build_run_id', v_zero_source_build_run_id::text,
      'reason', v_reason,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_zero_scope_after_json;

    PERFORM public._audit_insert(
      'banking_pay_workbench_session_scope',
      v_zero_repair_row.candidate_id::text,
      'ZERO_SOURCE_ROW_SOURCE_BUILD_POISON_REPAIRED',
      v_zero_scope_before_json,
      v_zero_scope_after_json,
      'ZERO_SOURCE_ROW_SOURCE_BUILD_POISON_REPAIRED',
      NULL
    );

    SELECT jsonb_build_object(
      'id', session_row.id::text,
      'status', session_row.status,
      'progress_state', session_row.progress_state,
      'scope_failed_count', session_row.scope_failed_count,
      'scope_pending_count', session_row.scope_pending_count,
      'scope_ready_count', session_row.scope_ready_count,
      'blocker_codes', COALESCE(session_row.progress_json->'blocker_codes', '[]'::jsonb),
      'draft_blocker_codes', COALESCE(session_row.progress_json->'draft_blocker_codes', '[]'::jsonb),
      'session_blocker_codes', COALESCE(session_row.progress_json->'session_blocker_codes', '[]'::jsonb),
      'progress_json', public.pay_workbench_session_compact_progress_json(COALESCE(session_row.progress_json, '{}'::jsonb), true),
      'bad_job_id', v_zero_repair_row.bad_job_id::text,
      'corrected_source_build_job_id', v_zero_corrected_job_id::text,
      'corrected_source_build_run_id', v_zero_source_build_run_id::text,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_zero_session_before_json
    FROM public.banking_pay_workbench_sessions AS session_row
    WHERE session_row.id = v_zero_repair_row.session_id
    FOR UPDATE;

    UPDATE public.banking_pay_workbench_sessions AS session_row
    SET progress_state = 'REFRESHING_CANDIDATES',
        progress_json = jsonb_strip_nulls(
          public.pay_workbench_session_compact_progress_json(COALESCE(session_row.progress_json, '{}'::jsonb), true)
          - 'last_source_build_failure_at_utc'
          - 'last_source_build_failure_job_id'
          - 'last_source_build_failure_code'
          - 'last_source_build_failure_source_build_run_id'
          - 'last_source_build_source_rows_marked_error_count'
          - 'blocker_codes'
          - 'draft_blocker_codes'
          - 'session_blocker_codes'
        ),
        progress_counter_version = COALESCE(session_row.progress_counter_version, 0) + 1,
        progress_updated_at_utc = v_now,
        updated_at_utc = v_now
    WHERE session_row.id = v_zero_repair_row.session_id;

    BEGIN
      v_progress_recompute_json := public.pay_workbench_session_recompute_progress_counters(
        p_session_id => v_zero_repair_row.session_id,
        p_apply => true,
        p_reason => 'ZERO_SOURCE_ROW_SOURCE_BUILD_POISON_REPAIRED',
        p_write_progress_json => true
      );
    EXCEPTION WHEN OTHERS THEN
      v_progress_recompute_failed := true;
      v_progress_recompute_error_json := jsonb_build_object(
        'code', SQLSTATE,
        'message', SQLERRM,
        'session_id', v_zero_repair_row.session_id::text,
        'candidate_id', v_zero_repair_row.candidate_id::text,
        'bad_job_id', v_zero_repair_row.bad_job_id::text,
        'corrected_source_build_job_id', v_zero_corrected_job_id::text,
        'corrected_source_build_run_id', v_zero_source_build_run_id::text,
        'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
      );
      v_progress_recompute_json := COALESCE(v_progress_recompute_error_json, '{}'::jsonb);
    END;

    SELECT session_row.progress_state,
           session_row.scope_failed_count,
           session_row.scope_pending_count,
           jsonb_build_object(
             'id', session_row.id::text,
             'status', session_row.status,
             'progress_state', session_row.progress_state,
             'scope_failed_count', session_row.scope_failed_count,
             'scope_pending_count', session_row.scope_pending_count,
             'scope_ready_count', session_row.scope_ready_count,
             'blocker_codes', COALESCE(session_row.progress_json->'blocker_codes', '[]'::jsonb),
             'draft_blocker_codes', COALESCE(session_row.progress_json->'draft_blocker_codes', '[]'::jsonb),
             'session_blocker_codes', COALESCE(session_row.progress_json->'session_blocker_codes', '[]'::jsonb),
             'progress_json', public.pay_workbench_session_compact_progress_json(COALESCE(session_row.progress_json, '{}'::jsonb), true),
             'bad_job_id', v_zero_repair_row.bad_job_id::text,
             'corrected_source_build_job_id', v_zero_corrected_job_id::text,
             'corrected_source_build_run_id', v_zero_source_build_run_id::text,
             'recompute_failed', v_progress_recompute_failed,
             'recompute_json', COALESCE(v_progress_recompute_json, '{}'::jsonb),
             'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
           )
    INTO v_post_recompute_progress_state,
         v_post_recompute_scope_failed_count,
         v_post_recompute_scope_pending_count,
         v_zero_session_after_json
    FROM public.banking_pay_workbench_sessions AS session_row
    WHERE session_row.id = v_zero_repair_row.session_id;

    PERFORM public._audit_insert(
      'banking_pay_workbench_session',
      v_zero_repair_row.session_id::text,
      'ZERO_SOURCE_ROW_PROGRESS_REPAIRED_AFTER_SOURCE_BUILD_POISON',
      v_zero_session_before_json,
      v_zero_session_after_json,
      'ZERO_SOURCE_ROW_PROGRESS_REPAIRED_AFTER_SOURCE_BUILD_POISON',
      NULL
    );

    v_zero_source_row_repaired_count := v_zero_source_row_repaired_count + 1;
    v_repaired_count := v_repaired_count + 1;
    v_repaired_scope_count := v_repaired_scope_count + 1;
    v_repaired_session_count := v_repaired_session_count + 1;

    v_zero_source_row_repairs_json := v_zero_source_row_repairs_json || jsonb_build_array(jsonb_build_object(
      'session_id', v_zero_repair_row.session_id::text,
      'candidate_id', v_zero_repair_row.candidate_id::text,
      'bad_job_id', v_zero_repair_row.bad_job_id::text,
      'corrected_source_build_job_id', v_zero_corrected_job_id::text,
      'corrected_source_build_job_status', v_zero_corrected_job_status,
      'corrected_source_build_run_id', v_zero_source_build_run_id::text,
      'corrected_dedupe_key', v_zero_corrected_dedupe_key,
      'source_change_seq', COALESCE(v_zero_source_change_seq, 0),
      'scope_repaired', true,
      'session_progress_repaired', true,
      'progress_recompute_failed', v_progress_recompute_failed,
      'post_recompute_progress_state', v_post_recompute_progress_state,
      'post_recompute_scope_failed_count', v_post_recompute_scope_failed_count,
      'post_recompute_scope_pending_count', v_post_recompute_scope_pending_count,
      'corrected_job_action', v_zero_corrected_job_action,
      'reason', v_reason,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    ));

    v_repairs_json := v_repairs_json || jsonb_build_array(jsonb_build_object(
      'session_id', v_zero_repair_row.session_id::text,
      'candidate_id', v_zero_repair_row.candidate_id::text,
      'bad_job_id', v_zero_repair_row.bad_job_id::text,
      'corrected_source_build_job_id', v_zero_corrected_job_id::text,
      'corrected_source_build_run_id', v_zero_source_build_run_id::text,
      'zero_source_row_repair', true,
      'scope_repaired', true,
      'session_progress_repaired', true,
      'reason', v_reason,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    ));
  END LOOP;

  FOR v_orphan_repair_row IN
    SELECT
      scope_row.id AS scope_id,
      scope_row.session_id,
      scope_row.candidate_id,
      scope_row.status AS scope_status,
      scope_row.pending_job_id AS bad_job_id,
      scope_row.dirty AS scope_dirty,
      scope_row.seeded AS scope_seeded,
      scope_row.error_json AS scope_error_json,
      scope_row.updated_at_utc AS scope_updated_at_utc,
      bad_job.job_type AS bad_job_type,
      bad_job.status AS bad_job_status,
      bad_job.dedupe_key AS bad_job_dedupe_key,
      COALESCE(bad_job.payload_json, '{}'::jsonb) AS bad_job_payload_json,
      bad_job.last_error_json AS bad_job_last_error_json,
      bad_job.failed_at_utc AS bad_job_failed_at_utc,
      target_session.actor_user_id AS session_actor_user_id,
      target_session.version AS session_version,
      target_session.session_signature,
      target_session.source_snapshot_run_id,
      COALESCE(app_counter.seq, 0)::bigint AS live_candidate_change_seq
    FROM public.banking_pay_workbench_session_scope AS scope_row
    JOIN public.banking_pay_workbench_jobs AS bad_job
      ON bad_job.id = scope_row.pending_job_id
    JOIN public.banking_pay_workbench_sessions AS target_session
      ON target_session.id = scope_row.session_id
    LEFT JOIN public.app_change_counters AS app_counter
      ON app_counter.entity_key = 'pay_candidate:' || scope_row.candidate_id::text
    WHERE UPPER(BTRIM(COALESCE(scope_row.status, ''))) = 'SOURCE_BUILD_PENDING'
      AND COALESCE(scope_row.dirty, false) IS TRUE
      AND scope_row.pending_job_id IS NOT NULL
      AND UPPER(BTRIM(COALESCE(bad_job.job_type, ''))) IN (
        'WORKBENCH_CANDIDATE_SOURCE_BUILD',
        'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK',
        'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE',
        'CANDIDATE_SOURCE_BUILD',
        'CANDIDATE_SOURCE_BUILD_CHUNK',
        'SOURCE_BUILD',
        'SOURCE_BUILD_PAGE'
      )
      AND UPPER(BTRIM(COALESCE(bad_job.status, ''))) IN ('FAILED', 'DEAD')
      AND bad_job.session_id = scope_row.session_id
      AND bad_job.candidate_id = scope_row.candidate_id
      AND NULLIF(BTRIM(COALESCE(
        bad_job.payload_json->>'source_build_run_id',
        bad_job.payload_json#>>'{source_build,source_build_run_id}',
        bad_job.payload_json#>>'{source_build,run_id}',
        bad_job.payload_json#>>'{cursor,source_build_run_id}',
        bad_job.payload_json#>>'{cursor_json,source_build_run_id}',
        bad_job.payload_json#>>'{result_json,source_build_run_id}',
        ''
      )), '') IS NULL
      AND (
        COALESCE(bad_job.last_error_json, '{}'::jsonb)::text ILIKE '%PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_RUN_ID_REQUIRED%'
        OR COALESCE(bad_job.payload_json#>'{last_failure_json}', '{}'::jsonb)::text ILIKE '%PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_RUN_ID_REQUIRED%'
        OR (
          lower(BTRIM(COALESCE(bad_job.payload_json->>'non_blocking_terminal_failure', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          AND UPPER(BTRIM(COALESCE(bad_job.payload_json->>'non_blocking_terminal_failure_reason', ''))) = 'MISSING_SOURCE_BUILD_RUN_ID_IS_NOT_AUTHORITATIVE'
        )
        OR lower(BTRIM(COALESCE(bad_job.payload_json->>'invalid_source_build_without_run_id_failed_closed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      )
      AND UPPER(BTRIM(COALESCE(target_session.status, ''))) = 'OPEN'
      AND target_session.discarded_at_utc IS NULL
      AND target_session.source_snapshot_run_id IS NOT NULL
      AND (p_session_id IS NULL OR scope_row.session_id = p_session_id)
      AND (p_candidate_id IS NULL OR scope_row.candidate_id = p_candidate_id)
    ORDER BY scope_row.updated_at_utc ASC, scope_row.id ASC
    LIMIT GREATEST(v_limit - v_processed_count, 0)
  LOOP
    PERFORM 1
    FROM public.banking_pay_workbench_sessions AS locked_session
    WHERE locked_session.id = v_orphan_repair_row.session_id
      AND UPPER(BTRIM(COALESCE(locked_session.status, ''))) = 'OPEN'
      AND locked_session.discarded_at_utc IS NULL
      AND locked_session.source_snapshot_run_id IS NOT NULL
    FOR UPDATE;

    IF NOT FOUND THEN
      v_skipped_count := v_skipped_count + 1;
      v_orphan_pending_skips_json := v_orphan_pending_skips_json || jsonb_build_array(jsonb_build_object(
        'session_id', v_orphan_repair_row.session_id::text,
        'candidate_id', v_orphan_repair_row.candidate_id::text,
        'bad_job_id', v_orphan_repair_row.bad_job_id::text,
        'reason', 'ORPHANED_PENDING_REPAIR_SESSION_NO_LONGER_OPEN',
        'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
      ));
      CONTINUE;
    END IF;

    PERFORM 1
    FROM public.banking_pay_workbench_session_scope AS locked_scope
    JOIN public.banking_pay_workbench_jobs AS locked_bad_job
      ON locked_bad_job.id = locked_scope.pending_job_id
    WHERE locked_scope.id = v_orphan_repair_row.scope_id
      AND locked_scope.session_id = v_orphan_repair_row.session_id
      AND locked_scope.candidate_id = v_orphan_repair_row.candidate_id
      AND UPPER(BTRIM(COALESCE(locked_scope.status, ''))) = 'SOURCE_BUILD_PENDING'
      AND COALESCE(locked_scope.dirty, false) IS TRUE
      AND locked_scope.pending_job_id = v_orphan_repair_row.bad_job_id
      AND UPPER(BTRIM(COALESCE(locked_bad_job.status, ''))) IN ('FAILED', 'DEAD')
      AND locked_bad_job.session_id = locked_scope.session_id
      AND locked_bad_job.candidate_id = locked_scope.candidate_id
    FOR UPDATE OF locked_scope, locked_bad_job;

    IF NOT FOUND THEN
      v_skipped_count := v_skipped_count + 1;
      v_orphan_pending_skips_json := v_orphan_pending_skips_json || jsonb_build_array(jsonb_build_object(
        'session_id', v_orphan_repair_row.session_id::text,
        'candidate_id', v_orphan_repair_row.candidate_id::text,
        'bad_job_id', v_orphan_repair_row.bad_job_id::text,
        'reason', 'ORPHANED_PENDING_REPAIR_STATE_ALREADY_CHANGED',
        'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
      ));
      CONTINUE;
    END IF;

    v_processed_count := v_processed_count + 1;
    v_orphan_enqueue_result := '{}'::jsonb;
    v_orphan_enqueue_error_json := NULL::jsonb;
    v_orphan_enqueue_job_id_text := NULL::text;
    v_orphan_enqueue_job_id := NULL::uuid;
    v_orphan_enqueue_job_type := NULL::text;
    v_orphan_enqueue_job_status := NULL::text;
    v_orphan_enqueue_source_build_run_id_text := NULL::text;
    v_orphan_enqueue_valid := false;
    v_progress_recompute_json := '{}'::jsonb;
    v_progress_recompute_failed := false;
    v_progress_recompute_error_json := NULL::jsonb;

    WITH targeted_arrays(value_json) AS (
      VALUES
        (v_orphan_repair_row.bad_job_payload_json->'targeted_timesheet_ids'),
        (v_orphan_repair_row.bad_job_payload_json->'targeted_timesheet_ids_requested'),
        (v_orphan_repair_row.bad_job_payload_json#>'{source_build,targeted_timesheet_ids}'),
        (v_orphan_repair_row.bad_job_payload_json#>'{source_build,targeted_timesheet_ids_requested}')
    ), targeted_values(timesheet_id_text) AS (
      SELECT NULLIF(BTRIM(targeted_value.value), '')
      FROM targeted_arrays AS targeted_array
      CROSS JOIN LATERAL jsonb_array_elements_text(
        CASE WHEN jsonb_typeof(targeted_array.value_json) = 'array' THEN targeted_array.value_json ELSE '[]'::jsonb END
      ) AS targeted_value(value)
    )
    SELECT COALESCE(jsonb_agg(targeted_ids.timesheet_id_text ORDER BY targeted_ids.timesheet_id_text), '[]'::jsonb)
    INTO v_orphan_targeted_timesheet_ids_json
    FROM (
      SELECT DISTINCT targeted_value.timesheet_id_text
      FROM targeted_values AS targeted_value
      WHERE targeted_value.timesheet_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ) AS targeted_ids;

    WITH linked_arrays(value_json) AS (
      VALUES
        (v_orphan_repair_row.bad_job_payload_json->'linked_timesheet_ids'),
        (v_orphan_repair_row.bad_job_payload_json->'linked_timesheet_ids_requested'),
        (v_orphan_repair_row.bad_job_payload_json#>'{source_build,linked_timesheet_ids}'),
        (v_orphan_repair_row.bad_job_payload_json#>'{source_build,linked_timesheet_ids_requested}')
    ), linked_values(timesheet_id_text) AS (
      SELECT NULLIF(BTRIM(linked_value.value), '')
      FROM linked_arrays AS linked_array
      CROSS JOIN LATERAL jsonb_array_elements_text(
        CASE WHEN jsonb_typeof(linked_array.value_json) = 'array' THEN linked_array.value_json ELSE '[]'::jsonb END
      ) AS linked_value(value)
    )
    SELECT COALESCE(jsonb_agg(linked_ids.timesheet_id_text ORDER BY linked_ids.timesheet_id_text), '[]'::jsonb)
    INTO v_orphan_linked_timesheet_ids_json
    FROM (
      SELECT DISTINCT linked_value.timesheet_id_text
      FROM linked_values AS linked_value
      WHERE linked_value.timesheet_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ) AS linked_ids;

    v_orphan_refresh_scope_kind := UPPER(BTRIM(COALESCE(
      NULLIF(v_orphan_repair_row.bad_job_payload_json->>'refresh_scope_kind', ''),
      NULLIF(v_orphan_repair_row.bad_job_payload_json#>>'{source_build,refresh_scope_kind}', ''),
      CASE
        WHEN jsonb_array_length(COALESCE(v_orphan_targeted_timesheet_ids_json, '[]'::jsonb)) > 0
          OR jsonb_array_length(COALESCE(v_orphan_linked_timesheet_ids_json, '[]'::jsonb)) > 0
        THEN 'TARGETED_TIMESHEETS'
        ELSE 'CANDIDATE_FULL_LIVE'
      END
    )));

    IF v_orphan_refresh_scope_kind NOT IN ('TARGETED_TIMESHEETS', 'CANDIDATE_FULL_LIVE') THEN
      v_orphan_refresh_scope_kind := CASE
        WHEN jsonb_array_length(COALESCE(v_orphan_targeted_timesheet_ids_json, '[]'::jsonb)) > 0
          OR jsonb_array_length(COALESCE(v_orphan_linked_timesheet_ids_json, '[]'::jsonb)) > 0
        THEN 'TARGETED_TIMESHEETS'
        ELSE 'CANDIDATE_FULL_LIVE'
      END;
    END IF;

    v_orphan_pay_channel_scope := UPPER(BTRIM(COALESCE(
      NULLIF(v_orphan_repair_row.bad_job_payload_json->>'pay_channel_scope', ''),
      NULLIF(v_orphan_repair_row.bad_job_payload_json#>>'{source_build,pay_channel_scope}', ''),
      'ALL'
    )));

    IF v_orphan_pay_channel_scope NOT IN ('PAYE', 'UMBRELLA', 'ALL', 'LOANS') THEN
      v_orphan_pay_channel_scope := 'ALL';
    END IF;

    v_orphan_source_change_seq := COALESCE(
      CASE WHEN COALESCE(v_orphan_repair_row.bad_job_payload_json->>'source_change_seq', '') ~ '^[0-9]{1,18}$' THEN (v_orphan_repair_row.bad_job_payload_json->>'source_change_seq')::bigint ELSE NULL::bigint END,
      CASE WHEN COALESCE(v_orphan_repair_row.bad_job_payload_json->>'source_change_sequence', '') ~ '^[0-9]{1,18}$' THEN (v_orphan_repair_row.bad_job_payload_json->>'source_change_sequence')::bigint ELSE NULL::bigint END,
      v_orphan_repair_row.live_candidate_change_seq,
      0::bigint
    );

    v_orphan_scope_before_json := jsonb_build_object(
      'id', v_orphan_repair_row.scope_id::text,
      'session_id', v_orphan_repair_row.session_id::text,
      'candidate_id', v_orphan_repair_row.candidate_id::text,
      'status', v_orphan_repair_row.scope_status,
      'dirty', v_orphan_repair_row.scope_dirty,
      'seeded', v_orphan_repair_row.scope_seeded,
      'pending_job_id', v_orphan_repair_row.bad_job_id::text,
      'error_json', v_orphan_repair_row.scope_error_json,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    );

    v_orphan_bad_job_before_json := jsonb_build_object(
      'id', v_orphan_repair_row.bad_job_id::text,
      'session_id', v_orphan_repair_row.session_id::text,
      'candidate_id', v_orphan_repair_row.candidate_id::text,
      'job_type', v_orphan_repair_row.bad_job_type,
      'status', v_orphan_repair_row.bad_job_status,
      'dedupe_key', v_orphan_repair_row.bad_job_dedupe_key,
      'source_build_run_id', NULL::text,
      'last_error_json', v_orphan_repair_row.bad_job_last_error_json,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    );

    BEGIN
      v_orphan_enqueue_result := public.pay_workbench_enqueue_candidate_refresh(
        p_snapshot_run_id => v_orphan_repair_row.source_snapshot_run_id,
        p_candidate_id => v_orphan_repair_row.candidate_id,
        p_reason => 'ORPHANED_PENDING_SOURCE_BUILD_POISON_REPAIR',
        p_actor_user_id => v_orphan_repair_row.session_actor_user_id,
        p_payload_json => jsonb_strip_nulls(
          jsonb_build_object(
            'session_id', v_orphan_repair_row.session_id::text,
            'source_session_id', v_orphan_repair_row.session_id::text,
            'source_snapshot_run_id', v_orphan_repair_row.source_snapshot_run_id::text,
            'snapshot_run_id', v_orphan_repair_row.source_snapshot_run_id::text,
            'session_version', v_orphan_repair_row.session_version,
            'session_signature', v_orphan_repair_row.session_signature,
            'force_legacy', true,
            'fallback_reason', 'MISSING_SOURCE_BUILD_RUN_ID_IS_NOT_AUTHORITATIVE',
            'projection_class', COALESCE(NULLIF(BTRIM(v_orphan_repair_row.bad_job_payload_json->>'projection_class'), ''), 'POST_DRAFT_PATCH_COMPLEX')
          )
          || jsonb_build_object(
            'source_change_seq', COALESCE(v_orphan_source_change_seq, 0),
            'refresh_scope_kind', v_orphan_refresh_scope_kind,
            'pay_channel_scope', v_orphan_pay_channel_scope,
            'targeted_timesheet_ids', COALESCE(v_orphan_targeted_timesheet_ids_json, '[]'::jsonb),
            'linked_timesheet_ids', COALESCE(v_orphan_linked_timesheet_ids_json, '[]'::jsonb),
            'source_build_required', true,
            'line_work_required', true,
            'delta_refresh_required', false,
            'enqueue_origin', 'PAY_WORKBENCH_REPAIR_INVALID_SOURCE_BUILD_POISON',
            'source_build_poison_repair', true,
            'invalid_source_build_bad_job_id', v_orphan_repair_row.bad_job_id::text,
            'repair_request_reason', v_reason,
            'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
          )
        )
      );
    EXCEPTION WHEN OTHERS THEN
      v_orphan_enqueue_error_json := jsonb_build_object(
        'code', SQLSTATE,
        'message', SQLERRM,
        'session_id', v_orphan_repair_row.session_id::text,
        'candidate_id', v_orphan_repair_row.candidate_id::text,
        'bad_job_id', v_orphan_repair_row.bad_job_id::text,
        'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
      );
    END;

    v_orphan_enqueue_job_id_text := NULLIF(BTRIM(COALESCE(v_orphan_enqueue_result->>'job_id', '')), '');

    IF v_orphan_enqueue_error_json IS NULL
       AND v_orphan_enqueue_job_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_orphan_enqueue_job_id := v_orphan_enqueue_job_id_text::uuid;

      SELECT
        successor_job.job_type,
        successor_job.status,
        NULLIF(BTRIM(COALESCE(
          successor_job.payload_json->>'source_build_run_id',
          successor_job.payload_json#>>'{source_build,source_build_run_id}',
          successor_job.payload_json#>>'{source_build,run_id}',
          ''
        )), '')
      INTO
        v_orphan_enqueue_job_type,
        v_orphan_enqueue_job_status,
        v_orphan_enqueue_source_build_run_id_text
      FROM public.banking_pay_workbench_jobs AS successor_job
      WHERE successor_job.id = v_orphan_enqueue_job_id
        AND successor_job.session_id = v_orphan_repair_row.session_id
        AND successor_job.candidate_id = v_orphan_repair_row.candidate_id
      FOR UPDATE;

      v_orphan_enqueue_valid := FOUND
        AND UPPER(BTRIM(COALESCE(v_orphan_enqueue_job_type, ''))) = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
        AND UPPER(BTRIM(COALESCE(v_orphan_enqueue_job_status, ''))) IN ('QUEUED', 'RUNNING')
        AND v_orphan_enqueue_source_build_run_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
    END IF;

    IF v_orphan_enqueue_valid IS NOT TRUE THEN
      v_orphan_enqueue_error_json := COALESCE(
        v_orphan_enqueue_error_json,
        jsonb_build_object(
          'code', 'SOURCE_BUILD_POISON_REPAIR_CANONICAL_SUCCESSOR_REQUIRED',
          'session_id', v_orphan_repair_row.session_id::text,
          'candidate_id', v_orphan_repair_row.candidate_id::text,
          'bad_job_id', v_orphan_repair_row.bad_job_id::text,
          'enqueue_result', COALESCE(v_orphan_enqueue_result, '{}'::jsonb),
          'successor_job_id', v_orphan_enqueue_job_id_text,
          'successor_job_type', v_orphan_enqueue_job_type,
          'successor_job_status', v_orphan_enqueue_job_status,
          'successor_source_build_run_id', v_orphan_enqueue_source_build_run_id_text,
          'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
        )
      );

      UPDATE public.banking_pay_workbench_session_scope AS failed_scope
      SET status = 'SOURCE_BUILD_ERROR',
          dirty = true,
          pending_job_id = NULL::uuid,
          error_json = jsonb_build_object(
            'code', 'SOURCE_BUILD_POISON_REPAIR_CANONICAL_SUCCESSOR_REQUIRED',
            'job_id', v_orphan_repair_row.bad_job_id::text,
            'repair_error_json', v_orphan_enqueue_error_json,
            'reason', v_reason,
            'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
          ),
          updated_at_utc = v_now
      WHERE failed_scope.id = v_orphan_repair_row.scope_id
        AND failed_scope.session_id = v_orphan_repair_row.session_id
        AND failed_scope.candidate_id = v_orphan_repair_row.candidate_id
        AND (
          failed_scope.pending_job_id = v_orphan_repair_row.bad_job_id
          OR (v_orphan_enqueue_job_id IS NOT NULL AND failed_scope.pending_job_id = v_orphan_enqueue_job_id)
        );

      UPDATE public.banking_pay_workbench_jobs AS bad_job_update
      SET payload_json = jsonb_strip_nulls(
            COALESCE(bad_job_update.payload_json, '{}'::jsonb)
            || jsonb_build_object(
              'source_build_poison_repair_attempted', true,
              'source_build_poison_repair_attempted_at_utc', v_now::text,
              'source_build_poison_repair_successor_created', false,
              'source_build_poison_repair_error_json', v_orphan_enqueue_error_json,
              'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
            )
          ),
          updated_at_utc = v_now
      WHERE bad_job_update.id = v_orphan_repair_row.bad_job_id;

      BEGIN
        v_progress_recompute_json := public.pay_workbench_session_recompute_progress_counters(
          p_session_id => v_orphan_repair_row.session_id,
          p_apply => true,
          p_reason => 'SOURCE_BUILD_POISON_REPAIR_SUCCESSOR_FAILED_CLOSED',
          p_write_progress_json => true
        );
      EXCEPTION WHEN OTHERS THEN
        v_progress_recompute_failed := true;
        v_progress_recompute_error_json := jsonb_build_object(
          'code', SQLSTATE,
          'message', SQLERRM,
          'session_id', v_orphan_repair_row.session_id::text,
          'candidate_id', v_orphan_repair_row.candidate_id::text,
          'bad_job_id', v_orphan_repair_row.bad_job_id::text,
          'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
        );
      END;

      SELECT jsonb_build_object(
        'id', failed_scope.id::text,
        'session_id', failed_scope.session_id::text,
        'candidate_id', failed_scope.candidate_id::text,
        'status', failed_scope.status,
        'dirty', failed_scope.dirty,
        'seeded', failed_scope.seeded,
        'pending_job_id', CASE WHEN failed_scope.pending_job_id IS NULL THEN NULL ELSE failed_scope.pending_job_id::text END,
        'error_json', failed_scope.error_json,
        'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
      )
      INTO v_orphan_scope_after_json
      FROM public.banking_pay_workbench_session_scope AS failed_scope
      WHERE failed_scope.id = v_orphan_repair_row.scope_id;

      PERFORM public._audit_insert(
        'banking_pay_workbench_session_scope',
        v_orphan_repair_row.candidate_id::text,
        'SOURCE_BUILD_POISON_REPAIR_SUCCESSOR_FAILED_CLOSED',
        v_orphan_scope_before_json,
        v_orphan_scope_after_json,
        'SOURCE_BUILD_POISON_REPAIR_SUCCESSOR_FAILED_CLOSED',
        NULL
      );

      v_skipped_count := v_skipped_count + 1;
      v_orphan_pending_failed_closed_count := v_orphan_pending_failed_closed_count + 1;
      v_orphan_pending_skips_json := v_orphan_pending_skips_json || jsonb_build_array(jsonb_build_object(
        'session_id', v_orphan_repair_row.session_id::text,
        'candidate_id', v_orphan_repair_row.candidate_id::text,
        'bad_job_id', v_orphan_repair_row.bad_job_id::text,
        'scope_failed_closed', true,
        'failed_job_reference_cleared', true,
        'repair_error_json', v_orphan_enqueue_error_json,
        'progress_recompute_failed', v_progress_recompute_failed,
        'progress_recompute_error_json', v_progress_recompute_error_json,
        'reason', v_reason,
        'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
      ));
      CONTINUE;
    END IF;

    PERFORM 1
    FROM public.banking_pay_workbench_session_scope AS repaired_scope
    WHERE repaired_scope.id = v_orphan_repair_row.scope_id
      AND repaired_scope.session_id = v_orphan_repair_row.session_id
      AND repaired_scope.candidate_id = v_orphan_repair_row.candidate_id
      AND UPPER(BTRIM(COALESCE(repaired_scope.status, ''))) = 'SOURCE_BUILD_PENDING'
      AND COALESCE(repaired_scope.dirty, false) IS TRUE
      AND repaired_scope.pending_job_id = v_orphan_enqueue_job_id
      AND repaired_scope.error_json IS NULL;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'SOURCE_BUILD_POISON_REPAIR_SCOPE_REBIND_REQUIRED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'SOURCE_BUILD_POISON_REPAIR_SCOPE_REBIND_REQUIRED',
                'session_id', v_orphan_repair_row.session_id::text,
                'candidate_id', v_orphan_repair_row.candidate_id::text,
                'bad_job_id', v_orphan_repair_row.bad_job_id::text,
                'successor_job_id', v_orphan_enqueue_job_id::text,
                'successor_source_build_run_id', v_orphan_enqueue_source_build_run_id_text,
                'message', 'The canonical candidate refresh helper did not replace the failed pending job reference with the validated successor.'
              )::text;
    END IF;

    UPDATE public.banking_pay_workbench_jobs AS bad_job_update
    SET payload_json = jsonb_strip_nulls(
          COALESCE(bad_job_update.payload_json, '{}'::jsonb)
          || jsonb_build_object(
            'source_build_poison_repair_resolved', true,
            'source_build_poison_repair_resolved_at_utc', v_now::text,
            'source_build_poison_repair_reason', v_reason,
            'source_build_poison_repair_successor_job_id', v_orphan_enqueue_job_id::text,
            'source_build_poison_repair_successor_source_build_run_id', v_orphan_enqueue_source_build_run_id_text,
            'source_build_poison_repair_successor_status', v_orphan_enqueue_job_status,
            'non_blocking_terminal_failure', true,
            'non_blocking_terminal_failure_reason', 'MISSING_SOURCE_BUILD_RUN_ID_IS_NOT_AUTHORITATIVE',
            'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
          )
        ),
        updated_at_utc = v_now
    WHERE bad_job_update.id = v_orphan_repair_row.bad_job_id
    RETURNING jsonb_build_object(
      'id', bad_job_update.id::text,
      'session_id', v_orphan_repair_row.session_id::text,
      'candidate_id', v_orphan_repair_row.candidate_id::text,
      'job_type', bad_job_update.job_type,
      'status', bad_job_update.status,
      'retained_terminal', true,
      'successor_job_id', v_orphan_enqueue_job_id::text,
      'successor_source_build_run_id', v_orphan_enqueue_source_build_run_id_text,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_orphan_bad_job_after_json;

    SELECT jsonb_build_object(
      'id', repaired_scope.id::text,
      'session_id', repaired_scope.session_id::text,
      'candidate_id', repaired_scope.candidate_id::text,
      'status', repaired_scope.status,
      'dirty', repaired_scope.dirty,
      'seeded', repaired_scope.seeded,
      'pending_job_id', CASE WHEN repaired_scope.pending_job_id IS NULL THEN NULL ELSE repaired_scope.pending_job_id::text END,
      'error_json', repaired_scope.error_json,
      'successor_source_build_run_id', v_orphan_enqueue_source_build_run_id_text,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_orphan_scope_after_json
    FROM public.banking_pay_workbench_session_scope AS repaired_scope
    WHERE repaired_scope.id = v_orphan_repair_row.scope_id;

    SELECT jsonb_build_object(
      'id', session_row.id::text,
      'status', session_row.status,
      'progress_state', session_row.progress_state,
      'scope_pending_count', session_row.scope_pending_count,
      'scope_failed_count', session_row.scope_failed_count,
      'progress_counter_version', session_row.progress_counter_version,
      'progress_json', public.pay_workbench_session_compact_progress_json(COALESCE(session_row.progress_json, '{}'::jsonb), true),
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_orphan_session_before_json
    FROM public.banking_pay_workbench_sessions AS session_row
    WHERE session_row.id = v_orphan_repair_row.session_id
    FOR UPDATE;

    BEGIN
      v_progress_recompute_json := public.pay_workbench_session_recompute_progress_counters(
        p_session_id => v_orphan_repair_row.session_id,
        p_apply => true,
        p_reason => 'ORPHANED_PENDING_SOURCE_BUILD_POISON_REPAIRED',
        p_write_progress_json => true
      );
    EXCEPTION WHEN OTHERS THEN
      v_progress_recompute_failed := true;
      v_progress_recompute_error_json := jsonb_build_object(
        'code', SQLSTATE,
        'message', SQLERRM,
        'session_id', v_orphan_repair_row.session_id::text,
        'candidate_id', v_orphan_repair_row.candidate_id::text,
        'bad_job_id', v_orphan_repair_row.bad_job_id::text,
        'successor_job_id', v_orphan_enqueue_job_id::text,
        'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
      );
      v_progress_recompute_json := COALESCE(v_progress_recompute_error_json, '{}'::jsonb);
    END;

    SELECT jsonb_build_object(
      'id', session_row.id::text,
      'status', session_row.status,
      'progress_state', session_row.progress_state,
      'scope_pending_count', session_row.scope_pending_count,
      'scope_failed_count', session_row.scope_failed_count,
      'progress_counter_version', session_row.progress_counter_version,
      'progress_json', public.pay_workbench_session_compact_progress_json(COALESCE(session_row.progress_json, '{}'::jsonb), true),
      'recompute_failed', v_progress_recompute_failed,
      'recompute_json', COALESCE(v_progress_recompute_json, '{}'::jsonb),
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_orphan_session_after_json
    FROM public.banking_pay_workbench_sessions AS session_row
    WHERE session_row.id = v_orphan_repair_row.session_id;

    PERFORM public._audit_insert(
      'banking_pay_workbench_job',
      v_orphan_repair_row.bad_job_id::text,
      'ORPHANED_PENDING_SOURCE_BUILD_POISON_REPAIRED',
      v_orphan_bad_job_before_json,
      v_orphan_bad_job_after_json,
      'ORPHANED_PENDING_SOURCE_BUILD_POISON_REPAIRED',
      NULL
    );

    PERFORM public._audit_insert(
      'banking_pay_workbench_session_scope',
      v_orphan_repair_row.candidate_id::text,
      'ORPHANED_PENDING_SOURCE_BUILD_POISON_REPAIRED',
      v_orphan_scope_before_json,
      v_orphan_scope_after_json,
      'ORPHANED_PENDING_SOURCE_BUILD_POISON_REPAIRED',
      NULL
    );

    PERFORM public._audit_insert(
      'banking_pay_workbench_session',
      v_orphan_repair_row.session_id::text,
      'PROGRESS_RECOMPUTED_AFTER_ORPHANED_SOURCE_BUILD_POISON',
      v_orphan_session_before_json,
      v_orphan_session_after_json,
      'PROGRESS_RECOMPUTED_AFTER_ORPHANED_SOURCE_BUILD_POISON',
      NULL
    );

    v_repaired_count := v_repaired_count + 1;
    v_repaired_scope_count := v_repaired_scope_count + 1;
    v_repaired_session_count := v_repaired_session_count + 1;
    v_orphan_pending_repaired_count := v_orphan_pending_repaired_count + 1;

    IF lower(BTRIM(COALESCE(v_orphan_enqueue_result->>'reused', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN
      v_corrected_source_build_job_reused_count := v_corrected_source_build_job_reused_count + 1;
    ELSE
      v_corrected_source_build_job_queued_count := v_corrected_source_build_job_queued_count + 1;
    END IF;

    v_orphan_pending_repairs_json := v_orphan_pending_repairs_json || jsonb_build_array(jsonb_build_object(
      'session_id', v_orphan_repair_row.session_id::text,
      'candidate_id', v_orphan_repair_row.candidate_id::text,
      'bad_job_id', v_orphan_repair_row.bad_job_id::text,
      'successor_job_id', v_orphan_enqueue_job_id::text,
      'successor_job_status', v_orphan_enqueue_job_status,
      'successor_source_build_run_id', v_orphan_enqueue_source_build_run_id_text,
      'refresh_scope_kind', v_orphan_refresh_scope_kind,
      'targeted_timesheet_ids', COALESCE(v_orphan_targeted_timesheet_ids_json, '[]'::jsonb),
      'linked_timesheet_ids', COALESCE(v_orphan_linked_timesheet_ids_json, '[]'::jsonb),
      'failed_job_reference_replaced', true,
      'scope_dirty_preserved', true,
      'session_progress_recomputed', true,
      'progress_recompute_failed', v_progress_recompute_failed,
      'reason', v_reason,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    ));

    v_repairs_json := v_repairs_json || jsonb_build_array(jsonb_build_object(
      'session_id', v_orphan_repair_row.session_id::text,
      'candidate_id', v_orphan_repair_row.candidate_id::text,
      'bad_job_id', v_orphan_repair_row.bad_job_id::text,
      'corrected_source_build_job_id', v_orphan_enqueue_job_id::text,
      'corrected_source_build_run_id', v_orphan_enqueue_source_build_run_id_text,
      'orphaned_pending_repair', true,
      'scope_repaired', true,
      'session_progress_repaired', true,
      'reason', v_reason,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    ));
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'server_utc', v_now,
    'reason', v_reason,
    'filtered_session_id', CASE WHEN p_session_id IS NULL THEN NULL ELSE p_session_id::text END,
    'filtered_candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
    'limit', v_limit,
    'processed_count', v_processed_count,
    'repaired_count', v_repaired_count,
    'skipped_count', v_skipped_count,
    'source_rows_restored_count', v_total_restored_source_row_count,
    'line_seed_requeued_count', v_requeued_line_seed_count,
    'scope_repaired_count', v_repaired_scope_count,
    'session_progress_repaired_count', v_repaired_session_count,
    'zero_source_row_repaired_count', v_zero_source_row_repaired_count,
    'corrected_source_build_job_queued_count', v_corrected_source_build_job_queued_count,
    'corrected_source_build_job_reused_count', v_corrected_source_build_job_reused_count,
    'corrected_source_build_job_succeeded_reused_count', v_corrected_source_build_job_succeeded_reused_count,
    'line_seed_attempt_count_reset_count', v_line_seed_attempt_count_reset_count,
    'post_recompute_progress_state', v_post_recompute_progress_state,
    'post_recompute_scope_failed_count', v_post_recompute_scope_failed_count,
    'post_recompute_scope_pending_count', v_post_recompute_scope_pending_count,
    'zero_source_row_repairs', COALESCE(v_zero_source_row_repairs_json, '[]'::jsonb),
    'zero_source_row_skips', COALESCE(v_zero_source_row_skips_json, '[]'::jsonb),
    'orphaned_pending_repaired_count', v_orphan_pending_repaired_count,
    'orphaned_pending_failed_closed_count', v_orphan_pending_failed_closed_count,
    'orphaned_pending_repairs', COALESCE(v_orphan_pending_repairs_json, '[]'::jsonb),
    'orphaned_pending_skips', COALESCE(v_orphan_pending_skips_json, '[]'::jsonb),
    'repairs', COALESCE(v_repairs_json, '[]'::jsonb),
    'skips', COALESCE(v_skips_json, '[]'::jsonb),
    'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
  );
END;
$function$;
ALTER FUNCTION public.pay_workbench_repair_invalid_source_build_poison(uuid, uuid, integer, timestamptz, text) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.pay_workbench_repair_invalid_source_build_poison(uuid, uuid, integer, timestamptz, text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.pay_workbench_repair_invalid_source_build_poison(uuid, uuid, integer, timestamptz, text) TO authenticated, service_role;

-- Installed pg_get_functiondef MD5: 18402c3c313ed5f69fb20e3e7ceef249
CREATE OR REPLACE FUNCTION public.pay_workbench_session_clone_eligible_rows_v1(p_target_session_id uuid, p_source_session_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 100, p_cursor_json jsonb DEFAULT '{}'::jsonb, p_options_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_cursor_json jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_cursor_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_cursor_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_options_json jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_options_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_options_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_target_session public.banking_pay_workbench_sessions%ROWTYPE;
  v_source_session public.banking_pay_workbench_sessions%ROWTYPE;
  v_source_session_id uuid := p_source_session_id;
  v_source_session_id_text text := NULL::text;
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 250);
  v_after_scope_ordinal bigint := NULL::bigint;
  v_after_candidate_id uuid := NULL::uuid;
  v_after_candidate_id_text text := NULL::text;
  v_processed_candidate_count integer := 0;
  v_copied_candidate_count integer := 0;
  v_copied_source_row_count integer := 0;
  v_copied_line_work_count integer := 0;
  v_copied_preview_row_count integer := 0;
  v_legacy_refresh_enqueued_count integer := 0;
  v_ready_empty_candidate_count integer := 0;
  v_last_scope_ordinal bigint := NULL::bigint;
  v_last_candidate_id uuid := NULL::uuid;
  v_more_due boolean := false;
  v_next_cursor_json jsonb := NULL::jsonb;
  v_clone_eligibility jsonb := '{}'::jsonb;
  v_candidate_state_result jsonb := '{}'::jsonb;
  v_candidate_id uuid := NULL::uuid;
  v_scope_ordinal bigint := NULL::bigint;
  v_job_id uuid := NULL::uuid;
  v_ineligible_source_change_seq bigint := 0;
  v_ineligible_source_build_seed_text text := NULL::text;
  v_ineligible_source_build_hash text := NULL::text;
  v_ineligible_source_build_run_id uuid := NULL::uuid;
  v_ineligible_source_build_base_dedupe_key text := NULL::text;
  v_ineligible_source_build_dedupe_key text := NULL::text;
  v_ineligible_source_build_payload_json jsonb := '{}'::jsonb;
  v_ineligible_source_build_job_status text := NULL::text;
  v_ineligible_source_build_job_payload_json jsonb := '{}'::jsonb;
  v_existing_source_build_job_id uuid := NULL::uuid;
  v_existing_source_build_job_status text := NULL::text;
  v_existing_source_build_job_payload_json jsonb := '{}'::jsonb;
  v_existing_source_build_run_id_text text := NULL::text;
  v_running_fail_close_result jsonb := '{}'::jsonb;
  v_ineligible_source_build_corrected_dedupe_key text := NULL::text;
  v_running_conflict_replacement_enqueued boolean := false;
  v_running_conflict_job_id uuid := NULL::uuid;
  v_running_conflict_status text := NULL::text;
  v_running_conflict_run_id_text text := NULL::text;
  v_active_conflict_replacement_enqueued boolean := false;
  v_active_conflict_job_id uuid := NULL::uuid;
  v_active_conflict_status text := NULL::text;
  v_active_conflict_run_id_text text := NULL::text;
  v_ineligible_refresh_scope_kind text := 'CANDIDATE_FULL_LIVE';
  v_fallback_targeted_timesheet_ids_json jsonb := '[]'::jsonb;
  v_fallback_linked_timesheet_ids_json jsonb := '[]'::jsonb;
  v_fallback_targeted_timesheet_count integer := 0;
  v_current_authority_timesheet_ids_json jsonb := '[]'::jsonb;
  v_current_authority_timesheet_count integer := 0;
  v_current_authority_scope_digest text := md5('[]');
  v_ineligible_final_pay_channel_scope text := 'ALL';
  v_existing_source_build_contract_valid boolean := false;
  v_target_invalidated_preview_count integer := 0;
  v_target_invalidated_source_count integer := 0;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  IF p_target_session_id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'clone_rebase_applied', false,
      'fallback_required', true,
      'fallback_reason', 'TARGET_SESSION_ID_REQUIRED',
      'copied_candidate_count', 0,
      'copied_preview_row_count', 0,
      'legacy_refresh_enqueued_count', 0,
      'more_due', false,
      'next_cursor_json', NULL::jsonb
    );
  END IF;

  IF v_source_session_id IS NULL THEN
    v_source_session_id_text := NULLIF(BTRIM(COALESCE(v_options_json->>'source_session_id', v_options_json->>'replacement_source_session_id', '')), '');
    IF v_source_session_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_source_session_id := v_source_session_id_text::uuid;
    END IF;
  END IF;

  IF v_source_session_id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'clone_rebase_applied', false,
      'fallback_required', true,
      'fallback_reason', 'SOURCE_SESSION_ID_REQUIRED',
      'copied_candidate_count', 0,
      'copied_preview_row_count', 0,
      'legacy_refresh_enqueued_count', 0,
      'more_due', false,
      'next_cursor_json', NULL::jsonb
    );
  END IF;

  SELECT target_session.*
  INTO v_target_session
  FROM public.banking_pay_workbench_sessions AS target_session
  WHERE target_session.id = p_target_session_id
    AND UPPER(BTRIM(COALESCE(target_session.status, ''))) = 'OPEN'
    AND target_session.discarded_at_utc IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'ok', false,
      'clone_rebase_applied', false,
      'fallback_required', true,
      'fallback_reason', 'TARGET_SESSION_NOT_OPEN',
      'copied_candidate_count', 0,
      'copied_preview_row_count', 0,
      'legacy_refresh_enqueued_count', 0,
      'more_due', false,
      'next_cursor_json', NULL::jsonb
    );
  END IF;

  SELECT source_session.*
  INTO v_source_session
  FROM public.banking_pay_workbench_sessions AS source_session
  WHERE source_session.id = v_source_session_id
    AND (
      (
        UPPER(BTRIM(COALESCE(source_session.status, ''))) = 'OPEN'
        AND source_session.discarded_at_utc IS NULL
      )
      OR (
        UPPER(BTRIM(COALESCE(source_session.status, ''))) = 'DISCARDED'
        AND source_session.discarded_at_utc IS NOT NULL
        AND source_session.replacement_session_id = p_target_session_id
      )
    )
  FOR SHARE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'ok', false,
      'clone_rebase_applied', false,
      'fallback_required', true,
      'fallback_reason', 'SOURCE_SESSION_NOT_OPEN',
      'copied_candidate_count', 0,
      'copied_preview_row_count', 0,
      'legacy_refresh_enqueued_count', 0,
      'more_due', false,
      'next_cursor_json', NULL::jsonb
    );
  END IF;

  IF COALESCE(v_cursor_json->>'after_scope_ordinal', v_cursor_json->>'last_scope_ordinal', '') ~ '^[0-9]{1,18}$' THEN
    v_after_scope_ordinal := COALESCE(v_cursor_json->>'after_scope_ordinal', v_cursor_json->>'last_scope_ordinal')::bigint;
  END IF;

  v_after_candidate_id_text := NULLIF(BTRIM(COALESCE(v_cursor_json->>'after_candidate_id', v_cursor_json->>'last_candidate_id', '')), '');
  IF v_after_candidate_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_after_candidate_id := v_after_candidate_id_text::uuid;
  END IF;

  DROP TABLE IF EXISTS pg_temp._bpay_clone_candidate_page;
  CREATE TEMP TABLE _bpay_clone_candidate_page ON COMMIT DROP AS
  SELECT paged_source_scope.candidate_id,
         paged_source_scope.scope_ordinal,
         ROW_NUMBER() OVER (ORDER BY paged_source_scope.scope_ordinal, paged_source_scope.candidate_id) AS page_index
  FROM public.banking_pay_workbench_session_scope AS paged_source_scope
  WHERE paged_source_scope.session_id = v_source_session_id
    AND paged_source_scope.candidate_id IS NOT NULL
    AND (
      v_after_scope_ordinal IS NULL
      OR paged_source_scope.scope_ordinal > v_after_scope_ordinal
      OR (
        paged_source_scope.scope_ordinal = v_after_scope_ordinal
        AND v_after_candidate_id IS NOT NULL
        AND paged_source_scope.candidate_id > v_after_candidate_id
      )
    )
  ORDER BY paged_source_scope.scope_ordinal, paged_source_scope.candidate_id
  LIMIT (v_limit + 1);

  SELECT COUNT(*)::integer
  INTO v_processed_candidate_count
  FROM pg_temp._bpay_clone_candidate_page AS page_row
  WHERE page_row.page_index <= v_limit;

  SELECT EXISTS (
    SELECT 1
    FROM pg_temp._bpay_clone_candidate_page AS page_row
    WHERE page_row.page_index > v_limit
  )
  INTO v_more_due;

  SELECT page_row.scope_ordinal,
         page_row.candidate_id
  INTO v_last_scope_ordinal,
       v_last_candidate_id
  FROM pg_temp._bpay_clone_candidate_page AS page_row
  WHERE page_row.page_index <= v_limit
  ORDER BY page_row.page_index DESC
  LIMIT 1;

  IF v_more_due IS TRUE THEN
    v_next_cursor_json := jsonb_build_object(
      'after_scope_ordinal', v_last_scope_ordinal,
      'after_candidate_id', CASE WHEN v_last_candidate_id IS NULL THEN NULL ELSE v_last_candidate_id::text END,
      'source_session_id', v_source_session_id::text,
      'target_session_id', p_target_session_id::text
    );
  END IF;

  FOR v_candidate_id, v_scope_ordinal IN
    SELECT page_row.candidate_id, page_row.scope_ordinal
    FROM pg_temp._bpay_clone_candidate_page AS page_row
    WHERE page_row.page_index <= v_limit
    ORDER BY page_row.scope_ordinal, page_row.candidate_id
  LOOP
    INSERT INTO public.banking_pay_workbench_session_scope (
      session_id,
      candidate_id,
      scope_ordinal,
      status,
      pending_job_id,
      seeded,
      dirty,
      error_json,
      created_at_utc,
      updated_at_utc
    )
    VALUES (
      p_target_session_id,
      v_candidate_id,
      v_scope_ordinal,
      'PENDING',
      NULL::uuid,
      true,
      false,
      NULL::jsonb,
      v_now,
      v_now
    )
    ON CONFLICT (session_id, candidate_id)
    DO UPDATE
    SET scope_ordinal = LEAST(public.banking_pay_workbench_session_scope.scope_ordinal, EXCLUDED.scope_ordinal),
        status = CASE
          WHEN UPPER(BTRIM(COALESCE(public.banking_pay_workbench_session_scope.status, ''))) IN ('READY', 'MATERIALISED', 'MATERIALIZED', 'SOURCE_EMPTY') THEN public.banking_pay_workbench_session_scope.status
          ELSE 'PENDING'
        END,
        seeded = true,
        dirty = false,
        error_json = NULL::jsonb,
        updated_at_utc = v_now;

    v_clone_eligibility := public.pay_workbench_session_clone_eligibility_v1(
      v_source_session_id,
      p_target_session_id,
      v_candidate_id,
      v_options_json
    );

    IF COALESCE((v_clone_eligibility->>'clone_eligible')::boolean, false) IS TRUE THEN
      IF COALESCE((v_clone_eligibility->>'ready_empty')::boolean, false) IS TRUE THEN
        UPDATE public.banking_pay_workbench_session_scope AS target_scope_update
        SET status = 'SOURCE_EMPTY',
            seeded = true,
            dirty = false,
            pending_job_id = NULL,
            error_json = NULL::jsonb,
            updated_at_utc = v_now
        WHERE target_scope_update.session_id = p_target_session_id
          AND target_scope_update.candidate_id = v_candidate_id;

        v_ready_empty_candidate_count := v_ready_empty_candidate_count + 1;
      ELSE
        WITH copied_source_rows AS (
          INSERT INTO public.banking_pay_workbench_candidate_source_lines (
            session_id,
            candidate_id,
            session_version,
            source_change_seq,
            source_build_run_id,
            source_ordinal,
            line_key,
            parent_line_key,
            split_suffix,
            timesheet_id,
            section,
            source_row_json,
            economic_key_json,
            contract_json,
            pay_channel_scope,
            refresh_scope_kind,
            status,
            created_at_utc,
            updated_at_utc
          )
          SELECT
            p_target_session_id,
            source_line.candidate_id,
            v_target_session.version,
            COALESCE(source_line.source_change_seq, 0),
            p_target_session_id,
            source_line.source_ordinal,
            source_line.line_key,
            source_line.parent_line_key,
            source_line.split_suffix,
            source_line.timesheet_id,
            source_line.section,
            jsonb_strip_nulls(
              COALESCE(source_line.source_row_json, '{}'::jsonb)
              || jsonb_build_object(
                'clone_certified', true,
                'clone_from_session_id', v_source_session_id::text,
                'clone_to_session_id', p_target_session_id::text,
                'clone_applied_at_utc', v_now::text,
                'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
              )
            ),
            source_line.economic_key_json,
            jsonb_strip_nulls(
              COALESCE(source_line.contract_json, '{}'::jsonb)
              || jsonb_build_object(
                'clone_certified', true,
                'clone_from_session_id', v_source_session_id::text,
                'clone_to_session_id', p_target_session_id::text,
                'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
              )
            ),
            source_line.pay_channel_scope,
            'CLONE_REBASE',
            'CURRENT',
            v_now,
            v_now
          FROM public.banking_pay_workbench_candidate_source_lines AS source_line
          WHERE source_line.session_id = v_source_session_id
            AND source_line.candidate_id = v_candidate_id
            AND source_line.session_version = v_source_session.version
            AND source_line.status = 'CURRENT'
          ON CONFLICT (
            session_id,
            candidate_id,
            session_version,
            source_change_seq,
            source_build_run_id,
            (COALESCE(timesheet_id, '00000000-0000-0000-0000-000000000000'::uuid)),
            line_key
          ) WHERE status = 'CURRENT'
          DO UPDATE
          SET source_ordinal = EXCLUDED.source_ordinal,
              parent_line_key = EXCLUDED.parent_line_key,
              split_suffix = EXCLUDED.split_suffix,
              section = EXCLUDED.section,
              source_row_json = EXCLUDED.source_row_json,
              economic_key_json = EXCLUDED.economic_key_json,
              contract_json = EXCLUDED.contract_json,
              pay_channel_scope = EXCLUDED.pay_channel_scope,
              refresh_scope_kind = EXCLUDED.refresh_scope_kind,
              updated_at_utc = v_now
          RETURNING public.banking_pay_workbench_candidate_source_lines.id
        )
        SELECT v_copied_source_row_count + COUNT(*)::integer
        INTO v_copied_source_row_count
        FROM copied_source_rows;

        WITH copied_line_rows AS (
          INSERT INTO public.banking_pay_workbench_candidate_line_work (
            session_id,
            candidate_id,
            timesheet_id,
            line_key,
            line_ordinal,
            status,
            work_payload_json,
            result_row_json,
            error_json,
            created_at_utc,
            updated_at_utc
          )
          SELECT
            p_target_session_id,
            line_work.candidate_id,
            line_work.timesheet_id,
            line_work.line_key,
            line_work.line_ordinal,
            CASE WHEN UPPER(BTRIM(COALESCE(line_work.status, ''))) IN ('MATERIALISED', 'MATERIALIZED') THEN 'MATERIALISED' ELSE 'SKIPPED' END,
            jsonb_strip_nulls(
              COALESCE(line_work.work_payload_json, '{}'::jsonb)
              || jsonb_build_object(
                'clone_certified', true,
                'clone_from_session_id', v_source_session_id::text,
                'clone_to_session_id', p_target_session_id::text,
                'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
              )
            ),
            jsonb_strip_nulls(
              COALESCE(line_work.result_row_json, '{}'::jsonb)
              || jsonb_build_object(
                'clone_certified', true,
                'clone_from_session_id', v_source_session_id::text,
                'clone_to_session_id', p_target_session_id::text,
                'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
              )
            ),
            NULL::jsonb,
            v_now,
            v_now
          FROM public.banking_pay_workbench_candidate_line_work AS line_work
          WHERE line_work.session_id = v_source_session_id
            AND line_work.candidate_id = v_candidate_id
            AND UPPER(BTRIM(COALESCE(line_work.status, ''))) IN ('MATERIALISED', 'MATERIALIZED', 'SKIPPED', 'SUPERSEDED', 'SOURCE_EMPTY', 'NOT_APPLICABLE', 'OBSOLETE')
          ON CONFLICT (session_id, candidate_id, (COALESCE(timesheet_id, '00000000-0000-0000-0000-000000000000'::uuid)), line_key)
          DO UPDATE
          SET line_ordinal = EXCLUDED.line_ordinal,
              status = EXCLUDED.status,
              work_payload_json = EXCLUDED.work_payload_json,
              result_row_json = EXCLUDED.result_row_json,
              error_json = NULL::jsonb,
              updated_at_utc = v_now
          RETURNING public.banking_pay_workbench_candidate_line_work.id
        )
        SELECT v_copied_line_work_count + COUNT(*)::integer
        INTO v_copied_line_work_count
        FROM copied_line_rows;

        WITH copied_preview_rows AS (
          INSERT INTO public.banking_pay_workbench_preview_rows (
            session_id,
            candidate_id,
            section,
            row_key,
            row_ordinal,
            row_json,
            timesheet_id,
            key_type,
            key_value,
            selected,
            selection_state,
            status,
            session_version,
            created_at_utc,
            updated_at_utc
          )
          SELECT
            p_target_session_id,
            preview_row.candidate_id,
            preview_row.section,
            preview_row.row_key,
            preview_row.row_ordinal,
            jsonb_strip_nulls(
              COALESCE(preview_row.row_json, '{}'::jsonb)
              || jsonb_build_object(
                'clone_certified', true,
                'clone_from_session_id', v_source_session_id::text,
                'clone_to_session_id', p_target_session_id::text,
                'clone_applied_at_utc', v_now::text,
                'selected', COALESCE(preview_row.selected, false),
                'selection_state', COALESCE(NULLIF(BTRIM(preview_row.selection_state), ''), CASE WHEN COALESCE(preview_row.selected, false) THEN 'SELECTED' ELSE 'NOT_SELECTABLE' END),
                'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
              )
            ),
            preview_row.timesheet_id,
            preview_row.key_type,
            preview_row.key_value,
            COALESCE(preview_row.selected, false),
            COALESCE(NULLIF(BTRIM(preview_row.selection_state), ''), CASE WHEN COALESCE(preview_row.selected, false) THEN 'SELECTED' ELSE 'NOT_SELECTABLE' END),
            'READY',
            v_target_session.version,
            v_now,
            v_now
          FROM public.banking_pay_workbench_preview_rows AS preview_row
          WHERE preview_row.session_id = v_source_session_id
            AND preview_row.candidate_id = v_candidate_id
            AND preview_row.session_version = v_source_session.version
            AND UPPER(BTRIM(COALESCE(preview_row.status, ''))) = 'READY'
          ON CONFLICT (session_id, section, candidate_id, row_key)
          DO UPDATE
          SET row_ordinal = EXCLUDED.row_ordinal,
              row_json = EXCLUDED.row_json,
              timesheet_id = EXCLUDED.timesheet_id,
              key_type = EXCLUDED.key_type,
              key_value = EXCLUDED.key_value,
              selected = EXCLUDED.selected,
              selection_state = EXCLUDED.selection_state,
              status = 'READY',
              session_version = EXCLUDED.session_version,
              updated_at_utc = v_now
          RETURNING public.banking_pay_workbench_preview_rows.id
        )
        SELECT v_copied_preview_row_count + COUNT(*)::integer
        INTO v_copied_preview_row_count
        FROM copied_preview_rows;

        INSERT INTO public.banking_pay_workbench_session_candidate_state AS candidate_state (
          session_id,
          candidate_id,
          status,
          effective_candidate_fragment_json,
          effective_summary_fragment_json,
          effective_paye_candidate_json,
          effective_non_paye_payee_json,
          effective_payees_json,
          effective_case_resolution_states_json,
          effective_canonical_preview_lines_json,
          source_change_seq,
          session_version,
          pending_job_id,
          created_at_utc,
          updated_at_utc,
          last_recomputed_at_utc,
          last_error_json
        )
        SELECT
          p_target_session_id,
          v_candidate_id,
          'READY',
          jsonb_build_object(
            'candidate_id', v_candidate_id::text,
            'session_id', p_target_session_id::text,
            'clone_certified', true,
            'clone_from_session_id', v_source_session_id::text
          ),
          jsonb_build_object(
            'candidate_id', v_candidate_id::text,
            'session_id', p_target_session_id::text,
            'status', 'READY',
            'clone_certified', true,
            'clone_from_session_id', v_source_session_id::text,
            'total_preview_rows', COUNT(*)::integer,
            'selected_rows', COUNT(*) FILTER (
              WHERE preview_row.selected IS TRUE
                AND UPPER(BTRIM(COALESCE(preview_row.selection_state, ''))) = 'SELECTED'
            )::integer
          ),
          NULL::jsonb,
          NULL::jsonb,
          '[]'::jsonb,
          '[]'::jsonb,
          COALESCE(jsonb_agg(preview_row.row_json ORDER BY preview_row.row_ordinal, preview_row.id) FILTER (WHERE preview_row.section = 'canonical_preview_lines'), '[]'::jsonb),
          CASE
            WHEN COALESCE(v_clone_eligibility->>'current_source_change_seq', '') ~ '^[0-9]{1,18}$'
              THEN (v_clone_eligibility->>'current_source_change_seq')::bigint
            ELSE 0::bigint
          END,
          v_target_session.version,
          NULL::uuid,
          v_now,
          v_now,
          v_now,
          NULL::jsonb
        FROM public.banking_pay_workbench_preview_rows AS preview_row
        WHERE preview_row.session_id = p_target_session_id
          AND preview_row.candidate_id = v_candidate_id
          AND preview_row.session_version = v_target_session.version
          AND preview_row.status = 'READY'
        ON CONFLICT (session_id, candidate_id)
        DO UPDATE
        SET status = 'READY',
            effective_candidate_fragment_json = EXCLUDED.effective_candidate_fragment_json,
            effective_summary_fragment_json = EXCLUDED.effective_summary_fragment_json,
            effective_paye_candidate_json = EXCLUDED.effective_paye_candidate_json,
            effective_non_paye_payee_json = EXCLUDED.effective_non_paye_payee_json,
            effective_payees_json = EXCLUDED.effective_payees_json,
            effective_case_resolution_states_json = EXCLUDED.effective_case_resolution_states_json,
            effective_canonical_preview_lines_json = EXCLUDED.effective_canonical_preview_lines_json,
            source_change_seq = EXCLUDED.source_change_seq,
            session_version = EXCLUDED.session_version,
            pending_job_id = NULL::uuid,
            updated_at_utc = v_now,
            last_recomputed_at_utc = v_now,
            last_error_json = NULL::jsonb;

        UPDATE public.banking_pay_workbench_session_scope AS target_scope_update
        SET status = 'READY',
            seeded = true,
            dirty = false,
            pending_job_id = NULL,
            error_json = NULL::jsonb,
            updated_at_utc = v_now
        WHERE target_scope_update.session_id = p_target_session_id
          AND target_scope_update.candidate_id = v_candidate_id;

        v_copied_candidate_count := v_copied_candidate_count + 1;
      END IF;

      IF to_regprocedure('public.pay_workbench_delta_update_candidate_state_v1(uuid,uuid,uuid,jsonb)') IS NOT NULL THEN
        v_candidate_state_result := public.pay_workbench_delta_update_candidate_state_v1(
          p_target_session_id,
          v_candidate_id,
          p_target_session_id,
          jsonb_build_object(
            'context', 'CLONE_REBASE',
            'source_session_id', v_source_session_id::text,
            'target_session_id', p_target_session_id::text,
            'clone_certified', true,
            'session_version', COALESCE(v_target_session.version, 1)
          )
        );
      END IF;
    ELSE
      v_ineligible_source_change_seq := 0;
      v_ineligible_final_pay_channel_scope := 'ALL';
      v_current_authority_timesheet_ids_json := '[]'::jsonb;
      v_current_authority_timesheet_count := 0;
      v_current_authority_scope_digest := md5('[]');
      v_target_invalidated_preview_count := 0;
      v_target_invalidated_source_count := 0;
      v_existing_source_build_contract_valid := false;

      SELECT COALESCE(
               (
                 SELECT app_counter.seq
                 FROM public.app_change_counters AS app_counter
                 WHERE app_counter.entity_key = 'pay_candidate:' || v_candidate_id::text
                 LIMIT 1
               ),
               0::bigint
             )::bigint
      INTO v_ineligible_source_change_seq;

      /* Clone-ineligible work is always rebuilt from the complete current candidate
         authority.  Source-visible READY rows are diagnostic only and can never
         narrow this fallback scope. */
      DROP TABLE IF EXISTS pg_temp._bpay_clone_ineligible_authority_timesheets;
      CREATE TEMP TABLE _bpay_clone_ineligible_authority_timesheets ON COMMIT DROP AS
      WITH authority_seed AS (
        SELECT current_tsfin.timesheet_id
        FROM public.timesheets_financials AS current_tsfin
        JOIN public.timesheets AS current_timesheet
          ON current_timesheet.timesheet_id = current_tsfin.timesheet_id
         AND current_timesheet.is_current = true
        WHERE current_tsfin.candidate_id = v_candidate_id
          AND current_tsfin.is_current = true

        UNION

        SELECT source_preview.timesheet_id
        FROM public.banking_pay_workbench_preview_rows AS source_preview
        WHERE source_preview.candidate_id = v_candidate_id
          AND source_preview.timesheet_id IS NOT NULL
          AND (
            (source_preview.session_id = v_source_session_id AND source_preview.session_version = v_source_session.version)
            OR (source_preview.session_id = p_target_session_id AND source_preview.session_version = v_target_session.version)
          )

        UNION

        SELECT source_line.timesheet_id
        FROM public.banking_pay_workbench_candidate_source_lines AS source_line
        WHERE source_line.candidate_id = v_candidate_id
          AND source_line.timesheet_id IS NOT NULL
          AND UPPER(BTRIM(COALESCE(source_line.status, ''))) IN ('CURRENT', 'DIRTY', 'ERROR')
          AND (
            (source_line.session_id = v_source_session_id AND source_line.session_version = v_source_session.version)
            OR (source_line.session_id = p_target_session_id AND source_line.session_version = v_target_session.version)
          )

        UNION

        SELECT snapshot_line.timesheet_id
        FROM public.banking_pay_snapshot_line_state AS snapshot_line
        WHERE snapshot_line.snapshot_run_id IN (v_source_session.source_snapshot_run_id, v_target_session.source_snapshot_run_id)
          AND snapshot_line.candidate_id = v_candidate_id
          AND snapshot_line.timesheet_id IS NOT NULL

        UNION

        SELECT advance_row.linked_timesheet_id
        FROM public.pay_advances AS advance_row
        WHERE advance_row.candidate_id = v_candidate_id
          AND advance_row.linked_timesheet_id IS NOT NULL
          AND UPPER(BTRIM(COALESCE(advance_row.status::text, ''))) IN ('ACTIVE', 'PAUSED')
          AND advance_row.cleared_at_utc IS NULL
          AND advance_row.written_off_at_utc IS NULL

        UNION

        SELECT component_row.linked_timesheet_id
        FROM public.pay_finance_case_components AS component_row
        WHERE component_row.candidate_id = v_candidate_id
          AND component_row.linked_timesheet_id IS NOT NULL
          AND component_row.closed_at_utc IS NULL

        UNION

        SELECT override_row.timesheet_id
        FROM public.timesheet_payment_overrides AS override_row
        WHERE override_row.candidate_id = v_candidate_id
          AND override_row.timesheet_id IS NOT NULL
          AND override_row.consumed_at_utc IS NULL
          AND override_row.cleared_at_utc IS NULL

        UNION

        SELECT adjustment_row.timesheet_id
        FROM public.ts_pay_adjustments AS adjustment_row
        WHERE adjustment_row.candidate_id = v_candidate_id
          AND adjustment_row.timesheet_id IS NOT NULL
          AND adjustment_row.paid_at_utc IS NULL

        UNION

        SELECT snooze_row.timesheet_id
        FROM public.pay_item_snoozes AS snooze_row
        WHERE snooze_row.candidate_id = v_candidate_id
          AND snooze_row.timesheet_id IS NOT NULL
          AND snooze_row.cleared_at_utc IS NULL
          AND snooze_row.cancelled_at_utc IS NULL

        UNION

        SELECT resolution_row.timesheet_id
        FROM public.banking_pay_workbench_session_case_resolutions AS resolution_row
        WHERE resolution_row.session_id IN (v_source_session_id, p_target_session_id)
          AND resolution_row.candidate_id = v_candidate_id
          AND resolution_row.timesheet_id IS NOT NULL

        UNION

        SELECT batch_item.timesheet_id
        FROM public.pay_batch_candidates AS batch_candidate
        JOIN public.pay_batch_items AS batch_item
          ON batch_item.pay_batch_candidate_id = batch_candidate.id
        WHERE batch_candidate.candidate_id = v_candidate_id
          AND batch_item.timesheet_id IS NOT NULL
          AND COALESCE(batch_item.is_voided, false) IS NOT TRUE

        UNION

        SELECT correction_item.timesheet_id
        FROM public.pay_payment_correction_items AS correction_item
        WHERE correction_item.candidate_id = v_candidate_id
          AND correction_item.timesheet_id IS NOT NULL
          AND UPPER(BTRIM(COALESCE(correction_item.status, ''))) = 'APPLIED'
      ),
      authority_seed_array AS (
        SELECT COALESCE(array_agg(authority_seed.timesheet_id ORDER BY authority_seed.timesheet_id), ARRAY[]::uuid[]) AS timesheet_ids
        FROM authority_seed
        WHERE authority_seed.timesheet_id IS NOT NULL
      ),
      authority_expanded AS (
        SELECT authority_seed.timesheet_id
        FROM authority_seed
        WHERE authority_seed.timesheet_id IS NOT NULL

        UNION

        SELECT rotation_scope.family_timesheet_id
        FROM authority_seed_array
        CROSS JOIN LATERAL public._pay_timesheet_rotation_scope(authority_seed_array.timesheet_ids) AS rotation_scope
        WHERE rotation_scope.family_timesheet_id IS NOT NULL

        UNION

        SELECT rotation_scope.canonical_timesheet_id
        FROM authority_seed_array
        CROSS JOIN LATERAL public._pay_timesheet_rotation_scope(authority_seed_array.timesheet_ids) AS rotation_scope
        WHERE rotation_scope.canonical_timesheet_id IS NOT NULL
      )
      SELECT DISTINCT authority_expanded.timesheet_id
      FROM authority_expanded
      WHERE authority_expanded.timesheet_id IS NOT NULL;

      SELECT COALESCE(jsonb_agg(authority_timesheet.timesheet_id::text ORDER BY authority_timesheet.timesheet_id), '[]'::jsonb),
             COUNT(*)::integer,
             md5(COALESCE(jsonb_agg(authority_timesheet.timesheet_id::text ORDER BY authority_timesheet.timesheet_id), '[]'::jsonb)::text)
      INTO v_current_authority_timesheet_ids_json,
           v_current_authority_timesheet_count,
           v_current_authority_scope_digest
      FROM pg_temp._bpay_clone_ineligible_authority_timesheets AS authority_timesheet;

      SELECT COALESCE(app_counter.seq, 0)
      INTO v_ineligible_source_change_seq
      FROM (SELECT 1) AS authority_anchor
      LEFT JOIN public.app_change_counters AS app_counter
        ON app_counter.entity_key = 'pay_candidate:' || v_candidate_id::text;

      SELECT CASE
               WHEN UPPER(BTRIM(COALESCE(candidate_row.pay_method, ''))) IN ('PAYE', 'UMBRELLA')
                 THEN UPPER(BTRIM(candidate_row.pay_method))
               ELSE 'ALL'
             END
      INTO v_ineligible_final_pay_channel_scope
      FROM public.candidates AS candidate_row
      WHERE candidate_row.id = v_candidate_id
      LIMIT 1;

      v_ineligible_final_pay_channel_scope := COALESCE(NULLIF(v_ineligible_final_pay_channel_scope, ''), 'ALL');
      v_fallback_targeted_timesheet_ids_json := '[]'::jsonb;
      v_fallback_linked_timesheet_ids_json := '[]'::jsonb;
      v_fallback_targeted_timesheet_count := 0;
      v_ineligible_refresh_scope_kind := 'CANDIDATE_FULL_LIVE';

      v_ineligible_source_build_base_dedupe_key := 'WORKBENCH_CANDIDATE_SOURCE_BUILD:session:' || p_target_session_id::text || ':candidate:' || v_candidate_id::text || ':clone_ineligible';
      v_ineligible_source_build_dedupe_key := v_ineligible_source_build_base_dedupe_key;

      v_ineligible_source_build_seed_text := concat_ws(
        ':',
        'WORKBENCH_CANDIDATE_SOURCE_BUILD',
        'CLONE_REBASE_INELIGIBLE_SOURCE_BUILD',
        'target_session_id', p_target_session_id::text,
        'target_session_version', COALESCE(v_target_session.version, 1)::text,
        'target_session_signature', COALESCE(v_target_session.session_signature, ''),
        'target_snapshot_run_id', COALESCE(v_target_session.source_snapshot_run_id::text, ''),
        'source_session_id', v_source_session_id::text,
        'source_session_version', COALESCE(v_source_session.version, 1)::text,
        'source_session_signature', COALESCE(v_source_session.session_signature, ''),
        'source_snapshot_run_id', COALESCE(v_source_session.source_snapshot_run_id::text, ''),
        'candidate_id', v_candidate_id::text,
        'source_change_seq', COALESCE(v_ineligible_source_change_seq, 0)::text,
        'refresh_scope_kind', 'CANDIDATE_FULL_LIVE',
        'current_authority_scope_digest', COALESCE(v_current_authority_scope_digest, md5('[]')),
        'pay_channel_scope', v_ineligible_final_pay_channel_scope,
        'clone_from_session_id', v_source_session_id::text,
        'clone_to_session_id', p_target_session_id::text,
        'overpayment_sync_attestation_required', 'true',
        'terminal_coverage_required', 'true',
        'reason', COALESCE(v_clone_eligibility->>'reason', 'CLONE_REBASE_INELIGIBLE')
      );
      v_ineligible_source_build_hash := md5(v_ineligible_source_build_seed_text);
      v_ineligible_source_build_run_id := (
        substr(v_ineligible_source_build_hash, 1, 8) || '-' ||
        substr(v_ineligible_source_build_hash, 9, 4) || '-' ||
        substr(v_ineligible_source_build_hash, 13, 4) || '-' ||
        substr(v_ineligible_source_build_hash, 17, 4) || '-' ||
        substr(v_ineligible_source_build_hash, 21, 12)
      )::uuid;
      v_ineligible_source_build_corrected_dedupe_key := v_ineligible_source_build_base_dedupe_key || ':corrected:' || v_ineligible_source_build_run_id::text;

      v_ineligible_source_build_payload_json := jsonb_strip_nulls(
        jsonb_build_object(
          'session_id', p_target_session_id::text,
          'target_session_id', p_target_session_id::text,
          'candidate_id', v_candidate_id::text,
          'session_version', v_target_session.version,
          'target_session_version', v_target_session.version,
          'source_change_seq', COALESCE(v_ineligible_source_change_seq, 0),
          'source_change_sequence', COALESCE(v_ineligible_source_change_seq, 0),
          'source_build_run_id', v_ineligible_source_build_run_id::text,
          'operation_type', 'CLONE_REBASE_INELIGIBLE_SOURCE_BUILD',
          'fallback_reason', COALESCE(v_clone_eligibility->>'reason', 'CLONE_REBASE_INELIGIBLE'),
          'refresh_reason', COALESCE(v_clone_eligibility->>'reason', 'CLONE_REBASE_INELIGIBLE'),
          'reason', COALESCE(v_clone_eligibility->>'reason', 'CLONE_INELIGIBLE'),
          'refresh_scope_kind', 'CANDIDATE_FULL_LIVE',
          'pay_channel_scope', v_ineligible_final_pay_channel_scope,
          'source_snapshot_run_id', v_target_session.source_snapshot_run_id::text,
          'snapshot_run_id', v_target_session.source_snapshot_run_id::text,
          'target_snapshot_run_id', v_target_session.source_snapshot_run_id::text,
          'source_session_id', v_source_session_id::text,
          'source_session_version', v_source_session.version,
          'source_session_snapshot_run_id', v_source_session.source_snapshot_run_id::text,
          'clone_from_session_id', v_source_session_id::text,
          'clone_to_session_id', p_target_session_id::text,
          'target_session_signature', v_target_session.session_signature,
          'source_session_signature', v_source_session.session_signature,
          'force_legacy', true,
          'source_build_required', true,
          'line_work_required', true,
          'delta_refresh_required', false
        )
        || jsonb_build_object(
          'targeted_timesheet_ids', '[]'::jsonb,
          'linked_timesheet_ids', '[]'::jsonb,
          'targeted_payload_received', false,
          'source_visible_timesheet_count', 0,
          'current_authority_timesheet_ids', COALESCE(v_current_authority_timesheet_ids_json, '[]'::jsonb),
          'current_authority_timesheet_count', COALESCE(v_current_authority_timesheet_count, 0),
          'current_authority_scope_digest', v_current_authority_scope_digest,
          'source_build_allow_full_fallback', true,
          'source_build_fallback_reason', COALESCE(v_clone_eligibility->>'reason', 'CLONE_REBASE_INELIGIBLE'),
          'overpayment_sync_completed', false,
          'overpayment_sync_attestation_required', true,
          'terminal_coverage_required', true,
          'discard_source_session_completion_markers', true,
          'source_session_completion_marker_authoritative', false,
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
        )
        || jsonb_build_object(
          'source_build_run_id_source', jsonb_build_object(
            'method', 'DETERMINISTIC_MD5_UUID_FROM_CURRENT_AUTHORITY_INPUTS',
            'seed_text', v_ineligible_source_build_seed_text,
            'target_session_id', p_target_session_id::text,
            'target_session_version', COALESCE(v_target_session.version, 1),
            'target_session_signature', v_target_session.session_signature,
            'target_snapshot_run_id', v_target_session.source_snapshot_run_id::text,
            'source_session_id', v_source_session_id::text,
            'source_session_version', COALESCE(v_source_session.version, 1),
            'source_session_signature', v_source_session.session_signature,
            'source_snapshot_run_id', v_source_session.source_snapshot_run_id::text,
            'candidate_id', v_candidate_id::text,
            'source_change_seq', COALESCE(v_ineligible_source_change_seq, 0),
            'refresh_scope_kind', 'CANDIDATE_FULL_LIVE',
            'current_authority_scope_digest', v_current_authority_scope_digest,
            'pay_channel_scope', v_ineligible_final_pay_channel_scope,
            'clone_from_session_id', v_source_session_id::text,
            'clone_to_session_id', p_target_session_id::text
          )
        )
        || jsonb_build_object(
          'source_build', jsonb_build_object(
            'required', true,
            'run_id', v_ineligible_source_build_run_id::text,
            'source_build_run_id', v_ineligible_source_build_run_id::text,
            'source_change_seq', COALESCE(v_ineligible_source_change_seq, 0),
            'source_change_sequence', COALESCE(v_ineligible_source_change_seq, 0),
            'session_id', p_target_session_id::text,
            'target_session_id', p_target_session_id::text,
            'target_session_version', v_target_session.version,
            'source_session_id', v_source_session_id::text,
            'source_session_version', v_source_session.version,
            'session_version', v_target_session.version,
            'refresh_scope_kind', 'CANDIDATE_FULL_LIVE',
            'pay_channel_scope', v_ineligible_final_pay_channel_scope,
            'targeted_timesheet_ids', '[]'::jsonb,
            'linked_timesheet_ids', '[]'::jsonb,
            'targeted_payload_received', false,
            'current_authority_timesheet_ids', COALESCE(v_current_authority_timesheet_ids_json, '[]'::jsonb),
            'current_authority_scope_digest', v_current_authority_scope_digest,
            'overpayment_sync_attestation_required', true,
            'terminal_coverage_required', true,
            'discard_source_session_completion_markers', true,
            'reason', COALESCE(v_clone_eligibility->>'reason', 'CLONE_INELIGIBLE')
          )
        )
      );

      v_job_id := NULL::uuid;
      v_ineligible_source_build_job_status := NULL::text;
      v_ineligible_source_build_job_payload_json := '{}'::jsonb;
      v_existing_source_build_job_id := NULL::uuid;
      v_existing_source_build_job_status := NULL::text;
      v_existing_source_build_job_payload_json := '{}'::jsonb;
      v_existing_source_build_run_id_text := NULL::text;
      v_running_fail_close_result := '{}'::jsonb;
      v_running_conflict_replacement_enqueued := false;
      v_running_conflict_job_id := NULL::uuid;
      v_running_conflict_status := NULL::text;
      v_running_conflict_run_id_text := NULL::text;
      v_active_conflict_replacement_enqueued := false;
      v_active_conflict_job_id := NULL::uuid;
      v_active_conflict_status := NULL::text;
      v_active_conflict_run_id_text := NULL::text;

      SELECT corrected_job.id,
             corrected_job.status,
             COALESCE(corrected_job.payload_json, '{}'::jsonb)
      INTO v_job_id,
           v_ineligible_source_build_job_status,
           v_ineligible_source_build_job_payload_json
      FROM public.banking_pay_workbench_jobs AS corrected_job
      WHERE corrected_job.dedupe_key = v_ineligible_source_build_corrected_dedupe_key
        AND corrected_job.status IN ('QUEUED', 'RUNNING')
      ORDER BY CASE WHEN corrected_job.status = 'QUEUED' THEN 0 ELSE 1 END,
               corrected_job.updated_at_utc DESC NULLS LAST,
               corrected_job.created_at_utc DESC NULLS LAST,
               corrected_job.id DESC
      LIMIT 1
      FOR UPDATE SKIP LOCKED;

      IF v_job_id IS NOT NULL THEN
        v_ineligible_source_build_dedupe_key := v_ineligible_source_build_corrected_dedupe_key;
      ELSE
        SELECT corrected_job.id,
               corrected_job.status,
               COALESCE(corrected_job.payload_json, '{}'::jsonb)
        INTO v_job_id,
             v_ineligible_source_build_job_status,
             v_ineligible_source_build_job_payload_json
        FROM public.banking_pay_workbench_jobs AS corrected_job
        WHERE corrected_job.dedupe_key = v_ineligible_source_build_corrected_dedupe_key
          AND corrected_job.status IN ('QUEUED', 'RUNNING')
        ORDER BY CASE WHEN corrected_job.status = 'QUEUED' THEN 0 ELSE 1 END,
                 corrected_job.updated_at_utc DESC NULLS LAST,
                 corrected_job.created_at_utc DESC NULLS LAST,
                 corrected_job.id DESC
        LIMIT 1;

        IF v_job_id IS NOT NULL THEN
          v_ineligible_source_build_dedupe_key := v_ineligible_source_build_corrected_dedupe_key;
        END IF;
      END IF;

      IF v_job_id IS NOT NULL THEN
        SELECT (
          COALESCE(
            v_ineligible_source_build_job_payload_json->>'source_build_run_id',
            v_ineligible_source_build_job_payload_json#>>'{source_build,source_build_run_id}',
            v_ineligible_source_build_job_payload_json#>>'{source_build,run_id}',
            ''
          ) = v_ineligible_source_build_run_id::text
          AND COALESCE(v_ineligible_source_build_job_payload_json->>'session_id', v_ineligible_source_build_job_payload_json->>'target_session_id', '') = p_target_session_id::text
          AND COALESCE(v_ineligible_source_build_job_payload_json->>'candidate_id', '') = v_candidate_id::text
          AND COALESCE(v_ineligible_source_build_job_payload_json->>'session_version', v_ineligible_source_build_job_payload_json->>'target_session_version', '') = v_target_session.version::text
          AND COALESCE(v_ineligible_source_build_job_payload_json->>'source_session_id', '') = v_source_session_id::text
          AND COALESCE(v_ineligible_source_build_job_payload_json->>'source_session_version', '') = v_source_session.version::text
          AND COALESCE(v_ineligible_source_build_job_payload_json->>'source_change_seq', v_ineligible_source_build_job_payload_json->>'source_change_sequence', '') = v_ineligible_source_change_seq::text
          AND UPPER(BTRIM(COALESCE(v_ineligible_source_build_job_payload_json->>'refresh_scope_kind', v_ineligible_source_build_job_payload_json#>>'{source_build,refresh_scope_kind}', ''))) = 'CANDIDATE_FULL_LIVE'
          AND UPPER(BTRIM(COALESCE(v_ineligible_source_build_job_payload_json->>'pay_channel_scope', v_ineligible_source_build_job_payload_json#>>'{source_build,pay_channel_scope}', ''))) = v_ineligible_final_pay_channel_scope
          AND COALESCE(v_ineligible_source_build_job_payload_json->>'target_session_signature', '') = COALESCE(v_target_session.session_signature, '')
          AND COALESCE(v_ineligible_source_build_job_payload_json->>'source_session_signature', '') = COALESCE(v_source_session.session_signature, '')
          AND COALESCE(v_ineligible_source_build_job_payload_json->>'target_snapshot_run_id', v_ineligible_source_build_job_payload_json->>'snapshot_run_id', '') = COALESCE(v_target_session.source_snapshot_run_id::text, '')
          AND COALESCE(v_ineligible_source_build_job_payload_json->>'source_session_snapshot_run_id', '') = COALESCE(v_source_session.source_snapshot_run_id::text, '')
          AND COALESCE(v_ineligible_source_build_job_payload_json->>'current_authority_scope_digest', '') = COALESCE(v_current_authority_scope_digest, '')
          AND jsonb_typeof(v_ineligible_source_build_job_payload_json->'targeted_timesheet_ids') = 'array'
          AND jsonb_array_length(CASE WHEN jsonb_typeof(v_ineligible_source_build_job_payload_json->'targeted_timesheet_ids') = 'array' THEN v_ineligible_source_build_job_payload_json->'targeted_timesheet_ids' ELSE '[]'::jsonb END) = 0
          AND jsonb_typeof(v_ineligible_source_build_job_payload_json->'linked_timesheet_ids') = 'array'
          AND jsonb_array_length(CASE WHEN jsonb_typeof(v_ineligible_source_build_job_payload_json->'linked_timesheet_ids') = 'array' THEN v_ineligible_source_build_job_payload_json->'linked_timesheet_ids' ELSE '[]'::jsonb END) = 0
          AND LOWER(BTRIM(COALESCE(v_ineligible_source_build_job_payload_json->>'overpayment_sync_attestation_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          AND LOWER(BTRIM(COALESCE(v_ineligible_source_build_job_payload_json->>'terminal_coverage_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          AND LOWER(BTRIM(COALESCE(v_ineligible_source_build_job_payload_json->>'discard_source_session_completion_markers', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          AND LOWER(BTRIM(COALESCE(v_ineligible_source_build_job_payload_json->>'overpayment_sync_completed', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
        )
        INTO v_existing_source_build_contract_valid;

        IF UPPER(BTRIM(COALESCE(v_ineligible_source_build_job_status, ''))) = 'QUEUED' THEN
          UPDATE public.banking_pay_workbench_jobs AS corrected_queued_job
          SET run_at_utc = LEAST(corrected_queued_job.run_at_utc, v_now),
              priority = LEAST(corrected_queued_job.priority, 60),
              payload_json = jsonb_strip_nulls(
                COALESCE(corrected_queued_job.payload_json, '{}'::jsonb)
                || v_ineligible_source_build_payload_json
                || jsonb_build_object(
                  'queued_payload_repaired_at_utc', v_now::text,
                  'queued_payload_repaired_reason', 'CLONE_REBASE_FULL_LIVE_AUTHORITY_CONTRACT_REASSERTED',
                  'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
                )
              ),
              updated_at_utc = v_now
          WHERE corrected_queued_job.id = v_job_id
            AND corrected_queued_job.status = 'QUEUED'
          RETURNING corrected_queued_job.id, corrected_queued_job.status, corrected_queued_job.payload_json
          INTO v_job_id, v_ineligible_source_build_job_status, v_ineligible_source_build_job_payload_json;
          v_existing_source_build_contract_valid := true;
          v_ineligible_source_build_dedupe_key := v_ineligible_source_build_corrected_dedupe_key;
        ELSIF UPPER(BTRIM(COALESCE(v_ineligible_source_build_job_status, ''))) = 'RUNNING'
              AND COALESCE(v_existing_source_build_contract_valid, false) IS NOT TRUE THEN
          v_active_conflict_replacement_enqueued := true;
          v_active_conflict_job_id := v_job_id;
          v_active_conflict_status := v_ineligible_source_build_job_status;
          v_active_conflict_run_id_text := COALESCE(
            v_ineligible_source_build_job_payload_json->>'source_build_run_id',
            v_ineligible_source_build_job_payload_json#>>'{source_build,source_build_run_id}',
            v_ineligible_source_build_job_payload_json#>>'{source_build,run_id}'
          );
          v_running_conflict_replacement_enqueued := true;
          v_running_conflict_job_id := v_job_id;
          v_running_conflict_status := v_ineligible_source_build_job_status;
          v_running_conflict_run_id_text := v_active_conflict_run_id_text;
          v_job_id := NULL::uuid;
          v_ineligible_source_build_job_status := NULL::text;
          v_ineligible_source_build_job_payload_json := '{}'::jsonb;
          v_ineligible_source_build_dedupe_key := v_ineligible_source_build_base_dedupe_key;
        ELSE
          v_ineligible_source_build_dedupe_key := v_ineligible_source_build_corrected_dedupe_key;
        END IF;
      END IF;

      IF v_job_id IS NULL THEN
        SELECT existing_job.id,
             existing_job.status,
             COALESCE(existing_job.payload_json, '{}'::jsonb)
      INTO v_existing_source_build_job_id,
           v_existing_source_build_job_status,
           v_existing_source_build_job_payload_json
      FROM public.banking_pay_workbench_jobs AS existing_job
      WHERE existing_job.dedupe_key = v_ineligible_source_build_dedupe_key
        AND existing_job.status IN ('QUEUED', 'RUNNING')
      ORDER BY CASE WHEN existing_job.status = 'QUEUED' THEN 0 ELSE 1 END,
               existing_job.updated_at_utc DESC NULLS LAST,
               existing_job.created_at_utc DESC NULLS LAST,
               existing_job.id DESC
      LIMIT 1
      FOR UPDATE SKIP LOCKED;

      IF v_existing_source_build_job_id IS NOT NULL THEN
        v_existing_source_build_run_id_text := NULLIF(BTRIM(COALESCE(
          v_existing_source_build_job_payload_json->>'source_build_run_id',
          v_existing_source_build_job_payload_json#>>'{source_build,source_build_run_id}',
          v_existing_source_build_job_payload_json#>>'{source_build,run_id}',
          v_existing_source_build_job_payload_json#>>'{cursor,source_build_run_id}',
          v_existing_source_build_job_payload_json#>>'{cursor_json,source_build_run_id}',
          v_existing_source_build_job_payload_json#>>'{result_json,source_build_run_id}',
          ''
        )), '');

        SELECT (
          COALESCE(
            v_existing_source_build_job_payload_json->>'source_build_run_id',
            v_existing_source_build_job_payload_json#>>'{source_build,source_build_run_id}',
            v_existing_source_build_job_payload_json#>>'{source_build,run_id}',
            ''
          ) = v_ineligible_source_build_run_id::text
          AND COALESCE(v_existing_source_build_job_payload_json->>'session_id', v_existing_source_build_job_payload_json->>'target_session_id', '') = p_target_session_id::text
          AND COALESCE(v_existing_source_build_job_payload_json->>'candidate_id', '') = v_candidate_id::text
          AND COALESCE(v_existing_source_build_job_payload_json->>'session_version', v_existing_source_build_job_payload_json->>'target_session_version', '') = v_target_session.version::text
          AND COALESCE(v_existing_source_build_job_payload_json->>'source_session_id', '') = v_source_session_id::text
          AND COALESCE(v_existing_source_build_job_payload_json->>'source_session_version', '') = v_source_session.version::text
          AND COALESCE(v_existing_source_build_job_payload_json->>'source_change_seq', v_existing_source_build_job_payload_json->>'source_change_sequence', '') = v_ineligible_source_change_seq::text
          AND UPPER(BTRIM(COALESCE(v_existing_source_build_job_payload_json->>'refresh_scope_kind', v_existing_source_build_job_payload_json#>>'{source_build,refresh_scope_kind}', ''))) = 'CANDIDATE_FULL_LIVE'
          AND UPPER(BTRIM(COALESCE(v_existing_source_build_job_payload_json->>'pay_channel_scope', v_existing_source_build_job_payload_json#>>'{source_build,pay_channel_scope}', ''))) = v_ineligible_final_pay_channel_scope
          AND COALESCE(v_existing_source_build_job_payload_json->>'target_session_signature', '') = COALESCE(v_target_session.session_signature, '')
          AND COALESCE(v_existing_source_build_job_payload_json->>'source_session_signature', '') = COALESCE(v_source_session.session_signature, '')
          AND COALESCE(v_existing_source_build_job_payload_json->>'target_snapshot_run_id', v_existing_source_build_job_payload_json->>'snapshot_run_id', '') = COALESCE(v_target_session.source_snapshot_run_id::text, '')
          AND COALESCE(v_existing_source_build_job_payload_json->>'source_session_snapshot_run_id', '') = COALESCE(v_source_session.source_snapshot_run_id::text, '')
          AND COALESCE(v_existing_source_build_job_payload_json->>'current_authority_scope_digest', '') = COALESCE(v_current_authority_scope_digest, '')
          AND jsonb_typeof(v_existing_source_build_job_payload_json->'targeted_timesheet_ids') = 'array'
          AND jsonb_array_length(CASE WHEN jsonb_typeof(v_existing_source_build_job_payload_json->'targeted_timesheet_ids') = 'array' THEN v_existing_source_build_job_payload_json->'targeted_timesheet_ids' ELSE '[]'::jsonb END) = 0
          AND jsonb_typeof(v_existing_source_build_job_payload_json->'linked_timesheet_ids') = 'array'
          AND jsonb_array_length(CASE WHEN jsonb_typeof(v_existing_source_build_job_payload_json->'linked_timesheet_ids') = 'array' THEN v_existing_source_build_job_payload_json->'linked_timesheet_ids' ELSE '[]'::jsonb END) = 0
          AND LOWER(BTRIM(COALESCE(v_existing_source_build_job_payload_json->>'overpayment_sync_attestation_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          AND LOWER(BTRIM(COALESCE(v_existing_source_build_job_payload_json->>'terminal_coverage_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          AND LOWER(BTRIM(COALESCE(v_existing_source_build_job_payload_json->>'discard_source_session_completion_markers', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          AND LOWER(BTRIM(COALESCE(v_existing_source_build_job_payload_json->>'overpayment_sync_completed', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
        )
        INTO v_existing_source_build_contract_valid;

        IF UPPER(BTRIM(COALESCE(v_existing_source_build_job_status, ''))) = 'QUEUED' THEN
          UPDATE public.banking_pay_workbench_jobs AS queued_job
          SET run_at_utc = LEAST(queued_job.run_at_utc, v_now),
              priority = LEAST(queued_job.priority, 60),
              payload_json = jsonb_strip_nulls(
                COALESCE(queued_job.payload_json, '{}'::jsonb)
                || v_ineligible_source_build_payload_json
                || jsonb_build_object(
                  'queued_payload_repaired_at_utc', v_now::text,
                  'queued_payload_repaired_reason', 'CLONE_REBASE_INELIGIBLE_SOURCE_BUILD_ENSURED_RUN_ID',
                  'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
                )
              ),
              updated_at_utc = v_now
          WHERE queued_job.id = v_existing_source_build_job_id
            AND queued_job.status = 'QUEUED'
          RETURNING queued_job.id, queued_job.status, queued_job.payload_json
          INTO v_job_id, v_ineligible_source_build_job_status, v_ineligible_source_build_job_payload_json;
        ELSIF UPPER(BTRIM(COALESCE(v_existing_source_build_job_status, ''))) = 'RUNNING'
              AND COALESCE(v_existing_source_build_contract_valid, false) IS NOT TRUE
              AND to_regprocedure('public.pay_workbench_fail_job(uuid,jsonb,integer)') IS NOT NULL THEN
          v_running_fail_close_result := public.pay_workbench_fail_job(
            v_existing_source_build_job_id,
            jsonb_build_object(
              'code', 'CLONE_REBASE_RUNNING_SOURCE_BUILD_AUTHORITY_CONTRACT_INVALID_FAILED_CLOSED',
              'message', 'Running clone-ineligible source-build job was locked by clone rebase, failed the complete current-authority payload contract, and was failed closed before a corrected full-live source-build job was created.',
              'job_id', v_existing_source_build_job_id::text,
              'session_id', p_target_session_id::text,
              'candidate_id', v_candidate_id::text,
              'source_change_seq', COALESCE(v_ineligible_source_change_seq, 0),
              'replacement_source_build_run_id', v_ineligible_source_build_run_id::text,
              'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
            ),
            NULL::integer
          );

          INSERT INTO public.banking_pay_workbench_jobs (
            job_type,
            status,
            priority,
            run_at_utc,
            dedupe_key,
            snapshot_run_id,
            session_id,
            candidate_id,
            payload_json,
            created_at_utc,
            updated_at_utc
          )
          VALUES (
            'WORKBENCH_CANDIDATE_SOURCE_BUILD',
            'QUEUED',
            60,
            v_now,
            v_ineligible_source_build_dedupe_key,
            v_target_session.source_snapshot_run_id,
            p_target_session_id,
            v_candidate_id,
            v_ineligible_source_build_payload_json || jsonb_build_object(
              'running_malformed_predecessor_failed_closed_job_id', v_existing_source_build_job_id::text,
              'running_malformed_predecessor_failed_closed_result', COALESCE(v_running_fail_close_result, '{}'::jsonb),
              'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
            ),
            v_now,
            v_now
          )
          ON CONFLICT (dedupe_key) WHERE status IN ('QUEUED', 'RUNNING')
          DO UPDATE
          SET run_at_utc = LEAST(public.banking_pay_workbench_jobs.run_at_utc, EXCLUDED.run_at_utc),
              priority = LEAST(public.banking_pay_workbench_jobs.priority, EXCLUDED.priority),
              payload_json = jsonb_strip_nulls(COALESCE(public.banking_pay_workbench_jobs.payload_json, '{}'::jsonb) || EXCLUDED.payload_json),
              updated_at_utc = v_now
          WHERE public.banking_pay_workbench_jobs.status = 'QUEUED'
          RETURNING id, status, payload_json
          INTO v_job_id, v_ineligible_source_build_job_status, v_ineligible_source_build_job_payload_json;
        ELSE
          v_job_id := v_existing_source_build_job_id;
          v_ineligible_source_build_job_status := v_existing_source_build_job_status;
          v_ineligible_source_build_job_payload_json := v_existing_source_build_job_payload_json;
        END IF;
      ELSE
        SELECT existing_job.id,
               existing_job.status,
               COALESCE(existing_job.payload_json, '{}'::jsonb)
        INTO v_existing_source_build_job_id,
             v_existing_source_build_job_status,
             v_existing_source_build_job_payload_json
        FROM public.banking_pay_workbench_jobs AS existing_job
        WHERE existing_job.dedupe_key = v_ineligible_source_build_dedupe_key
          AND existing_job.status IN ('QUEUED', 'RUNNING')
        ORDER BY CASE WHEN existing_job.status = 'QUEUED' THEN 0 ELSE 1 END,
                 existing_job.updated_at_utc DESC NULLS LAST,
                 existing_job.created_at_utc DESC NULLS LAST,
                 existing_job.id DESC
        LIMIT 1;

        IF v_existing_source_build_job_id IS NOT NULL THEN
          v_job_id := v_existing_source_build_job_id;
          v_ineligible_source_build_job_status := v_existing_source_build_job_status;
          v_ineligible_source_build_job_payload_json := v_existing_source_build_job_payload_json;
        ELSE
          INSERT INTO public.banking_pay_workbench_jobs (
            job_type,
            status,
            priority,
            run_at_utc,
            dedupe_key,
            snapshot_run_id,
            session_id,
            candidate_id,
            payload_json,
            created_at_utc,
            updated_at_utc
          )
          VALUES (
            'WORKBENCH_CANDIDATE_SOURCE_BUILD',
            'QUEUED',
            60,
            v_now,
            v_ineligible_source_build_dedupe_key,
            v_target_session.source_snapshot_run_id,
            p_target_session_id,
            v_candidate_id,
            v_ineligible_source_build_payload_json,
            v_now,
            v_now
          )
          ON CONFLICT (dedupe_key) WHERE status IN ('QUEUED', 'RUNNING')
          DO UPDATE
          SET run_at_utc = LEAST(public.banking_pay_workbench_jobs.run_at_utc, EXCLUDED.run_at_utc),
              priority = LEAST(public.banking_pay_workbench_jobs.priority, EXCLUDED.priority),
              payload_json = jsonb_strip_nulls(COALESCE(public.banking_pay_workbench_jobs.payload_json, '{}'::jsonb) || EXCLUDED.payload_json),
              updated_at_utc = v_now
          WHERE public.banking_pay_workbench_jobs.status = 'QUEUED'
          RETURNING id, status, payload_json
          INTO v_job_id, v_ineligible_source_build_job_status, v_ineligible_source_build_job_payload_json;
        END IF;
      END IF;

      IF v_job_id IS NULL THEN
        SELECT existing_job.id,
               existing_job.status,
               COALESCE(existing_job.payload_json, '{}'::jsonb)
        INTO v_job_id,
             v_ineligible_source_build_job_status,
             v_ineligible_source_build_job_payload_json
        FROM public.banking_pay_workbench_jobs AS existing_job
        WHERE existing_job.dedupe_key = v_ineligible_source_build_dedupe_key
          AND existing_job.status IN ('QUEUED', 'RUNNING')
        ORDER BY CASE WHEN existing_job.status = 'QUEUED' THEN 0 ELSE 1 END,
                 existing_job.updated_at_utc DESC NULLS LAST,
                 existing_job.created_at_utc DESC NULLS LAST,
                 existing_job.id DESC
        LIMIT 1;
      END IF;

      END IF;

      IF v_job_id IS NOT NULL
         AND UPPER(BTRIM(COALESCE(v_ineligible_source_build_job_status, ''))) IN ('QUEUED', 'RUNNING') THEN
        v_existing_source_build_run_id_text := NULLIF(BTRIM(COALESCE(
          v_ineligible_source_build_job_payload_json->>'source_build_run_id',
          v_ineligible_source_build_job_payload_json#>>'{source_build,source_build_run_id}',
          v_ineligible_source_build_job_payload_json#>>'{source_build,run_id}',
          v_ineligible_source_build_job_payload_json#>>'{cursor,source_build_run_id}',
          v_ineligible_source_build_job_payload_json#>>'{cursor_json,source_build_run_id}',
          v_ineligible_source_build_job_payload_json#>>'{result_json,source_build_run_id}',
          ''
        )), '');

        SELECT (
          COALESCE(
            v_ineligible_source_build_job_payload_json->>'source_build_run_id',
            v_ineligible_source_build_job_payload_json#>>'{source_build,source_build_run_id}',
            v_ineligible_source_build_job_payload_json#>>'{source_build,run_id}',
            ''
          ) = v_ineligible_source_build_run_id::text
          AND COALESCE(v_ineligible_source_build_job_payload_json->>'session_id', v_ineligible_source_build_job_payload_json->>'target_session_id', '') = p_target_session_id::text
          AND COALESCE(v_ineligible_source_build_job_payload_json->>'candidate_id', '') = v_candidate_id::text
          AND COALESCE(v_ineligible_source_build_job_payload_json->>'session_version', v_ineligible_source_build_job_payload_json->>'target_session_version', '') = v_target_session.version::text
          AND COALESCE(v_ineligible_source_build_job_payload_json->>'source_session_id', '') = v_source_session_id::text
          AND COALESCE(v_ineligible_source_build_job_payload_json->>'source_session_version', '') = v_source_session.version::text
          AND COALESCE(v_ineligible_source_build_job_payload_json->>'source_change_seq', v_ineligible_source_build_job_payload_json->>'source_change_sequence', '') = v_ineligible_source_change_seq::text
          AND UPPER(BTRIM(COALESCE(v_ineligible_source_build_job_payload_json->>'refresh_scope_kind', v_ineligible_source_build_job_payload_json#>>'{source_build,refresh_scope_kind}', ''))) = 'CANDIDATE_FULL_LIVE'
          AND UPPER(BTRIM(COALESCE(v_ineligible_source_build_job_payload_json->>'pay_channel_scope', v_ineligible_source_build_job_payload_json#>>'{source_build,pay_channel_scope}', ''))) = v_ineligible_final_pay_channel_scope
          AND COALESCE(v_ineligible_source_build_job_payload_json->>'target_session_signature', '') = COALESCE(v_target_session.session_signature, '')
          AND COALESCE(v_ineligible_source_build_job_payload_json->>'source_session_signature', '') = COALESCE(v_source_session.session_signature, '')
          AND COALESCE(v_ineligible_source_build_job_payload_json->>'target_snapshot_run_id', v_ineligible_source_build_job_payload_json->>'snapshot_run_id', '') = COALESCE(v_target_session.source_snapshot_run_id::text, '')
          AND COALESCE(v_ineligible_source_build_job_payload_json->>'source_session_snapshot_run_id', '') = COALESCE(v_source_session.source_snapshot_run_id::text, '')
          AND COALESCE(v_ineligible_source_build_job_payload_json->>'current_authority_scope_digest', '') = COALESCE(v_current_authority_scope_digest, '')
          AND jsonb_typeof(v_ineligible_source_build_job_payload_json->'targeted_timesheet_ids') = 'array'
          AND jsonb_array_length(CASE WHEN jsonb_typeof(v_ineligible_source_build_job_payload_json->'targeted_timesheet_ids') = 'array' THEN v_ineligible_source_build_job_payload_json->'targeted_timesheet_ids' ELSE '[]'::jsonb END) = 0
          AND jsonb_typeof(v_ineligible_source_build_job_payload_json->'linked_timesheet_ids') = 'array'
          AND jsonb_array_length(CASE WHEN jsonb_typeof(v_ineligible_source_build_job_payload_json->'linked_timesheet_ids') = 'array' THEN v_ineligible_source_build_job_payload_json->'linked_timesheet_ids' ELSE '[]'::jsonb END) = 0
          AND LOWER(BTRIM(COALESCE(v_ineligible_source_build_job_payload_json->>'overpayment_sync_attestation_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          AND LOWER(BTRIM(COALESCE(v_ineligible_source_build_job_payload_json->>'terminal_coverage_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          AND LOWER(BTRIM(COALESCE(v_ineligible_source_build_job_payload_json->>'discard_source_session_completion_markers', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          AND LOWER(BTRIM(COALESCE(v_ineligible_source_build_job_payload_json->>'overpayment_sync_completed', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
        )
        INTO v_existing_source_build_contract_valid;

        IF COALESCE(v_existing_source_build_contract_valid, false) IS NOT TRUE THEN
          v_active_conflict_job_id := v_job_id;
          v_active_conflict_status := v_ineligible_source_build_job_status;
          v_active_conflict_run_id_text := v_existing_source_build_run_id_text;
          v_active_conflict_replacement_enqueued := true;
          IF UPPER(BTRIM(COALESCE(v_ineligible_source_build_job_status, ''))) = 'RUNNING' THEN
            v_running_conflict_job_id := v_job_id;
            v_running_conflict_status := v_ineligible_source_build_job_status;
            v_running_conflict_run_id_text := v_existing_source_build_run_id_text;
            v_running_conflict_replacement_enqueued := true;
          END IF;
          v_job_id := NULL::uuid;
          v_ineligible_source_build_job_status := NULL::text;
          v_ineligible_source_build_job_payload_json := '{}'::jsonb;

          INSERT INTO public.banking_pay_workbench_jobs (
            job_type,
            status,
            priority,
            run_at_utc,
            dedupe_key,
            snapshot_run_id,
            session_id,
            candidate_id,
            payload_json,
            created_at_utc,
            updated_at_utc
          )
          VALUES (
            'WORKBENCH_CANDIDATE_SOURCE_BUILD',
            'QUEUED',
            60,
            v_now,
            v_ineligible_source_build_corrected_dedupe_key,
            v_target_session.source_snapshot_run_id,
            p_target_session_id,
            v_candidate_id,
            v_ineligible_source_build_payload_json || jsonb_build_object(
              'active_malformed_predecessor_not_mutated_job_id', v_active_conflict_job_id::text,
              'active_malformed_predecessor_status', v_active_conflict_status,
              'active_malformed_predecessor_run_id_text', v_active_conflict_run_id_text,
              'running_malformed_predecessor_not_mutated_job_id', CASE WHEN v_running_conflict_job_id IS NULL THEN NULL ELSE v_running_conflict_job_id::text END,
              'running_malformed_predecessor_status', v_running_conflict_status,
              'running_malformed_predecessor_run_id_text', v_running_conflict_run_id_text,
              'original_source_build_dedupe_key', v_ineligible_source_build_dedupe_key,
              'corrected_source_build_dedupe_key', v_ineligible_source_build_corrected_dedupe_key,
              'replacement_enqueued_because_active_job_not_mutated', true,
              'replacement_enqueued_because_running_job_not_mutated', COALESCE(v_running_conflict_replacement_enqueued, false),
              'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
            ),
            v_now,
            v_now
          )
          ON CONFLICT (dedupe_key) WHERE status IN ('QUEUED', 'RUNNING')
          DO UPDATE
          SET run_at_utc = LEAST(public.banking_pay_workbench_jobs.run_at_utc, EXCLUDED.run_at_utc),
              priority = LEAST(public.banking_pay_workbench_jobs.priority, EXCLUDED.priority),
              payload_json = jsonb_strip_nulls(COALESCE(public.banking_pay_workbench_jobs.payload_json, '{}'::jsonb) || EXCLUDED.payload_json),
              updated_at_utc = v_now
          WHERE public.banking_pay_workbench_jobs.status = 'QUEUED'
          RETURNING id, status, payload_json
          INTO v_job_id, v_ineligible_source_build_job_status, v_ineligible_source_build_job_payload_json;

          IF v_job_id IS NULL THEN
            SELECT corrected_job.id,
                   corrected_job.status,
                   COALESCE(corrected_job.payload_json, '{}'::jsonb)
            INTO v_job_id,
                 v_ineligible_source_build_job_status,
                 v_ineligible_source_build_job_payload_json
            FROM public.banking_pay_workbench_jobs AS corrected_job
            WHERE corrected_job.dedupe_key = v_ineligible_source_build_corrected_dedupe_key
              AND corrected_job.status IN ('QUEUED', 'RUNNING')
            ORDER BY CASE WHEN corrected_job.status = 'QUEUED' THEN 0 ELSE 1 END,
                     corrected_job.updated_at_utc DESC NULLS LAST,
                     corrected_job.created_at_utc DESC NULLS LAST,
                     corrected_job.id DESC
            LIMIT 1;
          END IF;

          IF v_job_id IS NOT NULL THEN
            v_ineligible_source_build_dedupe_key := v_ineligible_source_build_corrected_dedupe_key;
          END IF;
        ELSE
          v_ineligible_source_build_run_id := v_existing_source_build_run_id_text::uuid;
        END IF;
      END IF;

      IF v_job_id IS NULL THEN
        RAISE EXCEPTION 'Unable to enqueue or reuse clone-ineligible source-build job for session %, candidate %', p_target_session_id, v_candidate_id
          USING ERRCODE = '55000';
      END IF;

      SELECT (
        COALESCE(
          v_ineligible_source_build_job_payload_json->>'source_build_run_id',
          v_ineligible_source_build_job_payload_json#>>'{source_build,source_build_run_id}',
          v_ineligible_source_build_job_payload_json#>>'{source_build,run_id}',
          ''
        ) = v_ineligible_source_build_run_id::text
        AND COALESCE(v_ineligible_source_build_job_payload_json->>'session_id', v_ineligible_source_build_job_payload_json->>'target_session_id', '') = p_target_session_id::text
        AND COALESCE(v_ineligible_source_build_job_payload_json->>'candidate_id', '') = v_candidate_id::text
        AND COALESCE(v_ineligible_source_build_job_payload_json->>'session_version', v_ineligible_source_build_job_payload_json->>'target_session_version', '') = v_target_session.version::text
        AND COALESCE(v_ineligible_source_build_job_payload_json->>'source_session_id', '') = v_source_session_id::text
        AND COALESCE(v_ineligible_source_build_job_payload_json->>'source_session_version', '') = v_source_session.version::text
        AND COALESCE(v_ineligible_source_build_job_payload_json->>'source_change_seq', v_ineligible_source_build_job_payload_json->>'source_change_sequence', '') = v_ineligible_source_change_seq::text
        AND UPPER(BTRIM(COALESCE(v_ineligible_source_build_job_payload_json->>'refresh_scope_kind', v_ineligible_source_build_job_payload_json#>>'{source_build,refresh_scope_kind}', ''))) = 'CANDIDATE_FULL_LIVE'
        AND UPPER(BTRIM(COALESCE(v_ineligible_source_build_job_payload_json->>'pay_channel_scope', v_ineligible_source_build_job_payload_json#>>'{source_build,pay_channel_scope}', ''))) = v_ineligible_final_pay_channel_scope
        AND COALESCE(v_ineligible_source_build_job_payload_json->>'target_session_signature', '') = COALESCE(v_target_session.session_signature, '')
        AND COALESCE(v_ineligible_source_build_job_payload_json->>'source_session_signature', '') = COALESCE(v_source_session.session_signature, '')
        AND COALESCE(v_ineligible_source_build_job_payload_json->>'target_snapshot_run_id', v_ineligible_source_build_job_payload_json->>'snapshot_run_id', '') = COALESCE(v_target_session.source_snapshot_run_id::text, '')
        AND COALESCE(v_ineligible_source_build_job_payload_json->>'source_session_snapshot_run_id', '') = COALESCE(v_source_session.source_snapshot_run_id::text, '')
        AND COALESCE(v_ineligible_source_build_job_payload_json->>'current_authority_scope_digest', '') = COALESCE(v_current_authority_scope_digest, '')
        AND jsonb_typeof(v_ineligible_source_build_job_payload_json->'targeted_timesheet_ids') = 'array'
        AND jsonb_array_length(CASE WHEN jsonb_typeof(v_ineligible_source_build_job_payload_json->'targeted_timesheet_ids') = 'array' THEN v_ineligible_source_build_job_payload_json->'targeted_timesheet_ids' ELSE '[]'::jsonb END) = 0
        AND jsonb_typeof(v_ineligible_source_build_job_payload_json->'linked_timesheet_ids') = 'array'
        AND jsonb_array_length(CASE WHEN jsonb_typeof(v_ineligible_source_build_job_payload_json->'linked_timesheet_ids') = 'array' THEN v_ineligible_source_build_job_payload_json->'linked_timesheet_ids' ELSE '[]'::jsonb END) = 0
        AND LOWER(BTRIM(COALESCE(v_ineligible_source_build_job_payload_json->>'source_build_allow_full_fallback', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(v_ineligible_source_build_job_payload_json->>'overpayment_sync_attestation_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(v_ineligible_source_build_job_payload_json->>'terminal_coverage_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(v_ineligible_source_build_job_payload_json->>'discard_source_session_completion_markers', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(v_ineligible_source_build_job_payload_json->>'source_session_completion_marker_authoritative', 'true'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(v_ineligible_source_build_job_payload_json->>'overpayment_sync_completed', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
      )
      INTO v_existing_source_build_contract_valid;

      IF COALESCE(v_existing_source_build_contract_valid, false) IS NOT TRUE THEN
        RAISE EXCEPTION 'Clone-ineligible source-build job contract could not be proven for session %, candidate %, job %', p_target_session_id, v_candidate_id, v_job_id
          USING ERRCODE = '55000',
                DETAIL = jsonb_build_object(
                  'code', 'CLONE_REBASE_SOURCE_BUILD_JOB_AUTHORITY_CONTRACT_UNPROVEN',
                  'session_id', p_target_session_id::text,
                  'candidate_id', v_candidate_id::text,
                  'job_id', v_job_id::text,
                  'expected_source_build_run_id', v_ineligible_source_build_run_id::text,
                  'expected_source_change_seq', COALESCE(v_ineligible_source_change_seq, 0),
                  'expected_refresh_scope_kind', 'CANDIDATE_FULL_LIVE',
                  'expected_authority_scope_digest', v_current_authority_scope_digest,
                  'expected_pay_channel_scope', v_ineligible_final_pay_channel_scope
                )::text;
      END IF;

      PERFORM public._audit_insert(
        'banking_pay_workbench_job',
        v_job_id::text,
        CASE
          WHEN UPPER(BTRIM(COALESCE(v_ineligible_source_build_job_status, ''))) = 'QUEUED' THEN 'QUEUED'
          WHEN UPPER(BTRIM(COALESCE(v_ineligible_source_build_job_status, ''))) = 'RUNNING' THEN 'RUNNING_NOT_MUTATED'
          ELSE 'REUSED'
        END,
        NULL::jsonb,
        jsonb_build_object(
          'id', v_job_id::text,
          'job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
          'status', v_ineligible_source_build_job_status,
          'session_id', p_target_session_id::text,
          'candidate_id', v_candidate_id::text,
          'bad_job_id', CASE WHEN COALESCE(v_running_fail_close_result, '{}'::jsonb) = '{}'::jsonb THEN NULL::text ELSE COALESCE(v_running_fail_close_result->>'job_id', v_existing_source_build_job_id::text) END,
          'source_build_run_id', v_ineligible_source_build_run_id::text,
          'source_change_seq', COALESCE(v_ineligible_source_change_seq, 0),
          'dedupe_key', v_ineligible_source_build_dedupe_key,
          'operation_type', 'CLONE_REBASE_INELIGIBLE_SOURCE_BUILD',
          'running_job_payload_mutated', false,
          'running_malformed_job_failed_closed', COALESCE(v_running_fail_close_result, '{}'::jsonb) <> '{}'::jsonb,
          'active_conflict_replacement_enqueued', COALESCE(v_active_conflict_replacement_enqueued, false),
          'active_conflict_job_id', CASE WHEN v_active_conflict_job_id IS NULL THEN NULL ELSE v_active_conflict_job_id::text END,
          'active_conflict_status', v_active_conflict_status,
          'running_conflict_replacement_enqueued', COALESCE(v_running_conflict_replacement_enqueued, false),
          'running_conflict_job_id', CASE WHEN v_running_conflict_job_id IS NULL THEN NULL ELSE v_running_conflict_job_id::text END,
          'corrected_source_build_dedupe_key', v_ineligible_source_build_corrected_dedupe_key,
          'deterministic_source_build_run_id_seed_text', v_ineligible_source_build_seed_text,
          'reason', COALESCE(v_clone_eligibility->>'reason', 'CLONE_REBASE_INELIGIBLE'),
          'refresh_scope_kind', v_ineligible_refresh_scope_kind,
          'targeted_timesheet_ids', '[]'::jsonb,
          'linked_timesheet_ids', '[]'::jsonb,
          'targeted_payload_received', false,
          'current_authority_timesheet_ids', COALESCE(v_current_authority_timesheet_ids_json, '[]'::jsonb),
          'current_authority_timesheet_count', COALESCE(v_current_authority_timesheet_count, 0),
          'current_authority_scope_digest', v_current_authority_scope_digest,
          'pay_channel_scope', v_ineligible_final_pay_channel_scope,
          'overpayment_sync_attestation_required', true,
          'terminal_coverage_required', true,
          'source_session_completion_marker_authoritative', false,
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
        ),
        CASE
          WHEN UPPER(BTRIM(COALESCE(v_ineligible_source_build_job_status, ''))) = 'RUNNING'
            THEN 'WORKBENCH_CLONE_REBASE_INELIGIBLE_SOURCE_BUILD_RUNNING_NOT_MUTATED'
          ELSE 'WORKBENCH_CLONE_REBASE_INELIGIBLE_SOURCE_BUILD_ENQUEUED_WITH_RUN_ID'
        END,
        NULL
      );

      UPDATE public.banking_pay_workbench_preview_rows AS stale_target_preview
      SET status = 'DIRTY',
          selected = false,
          selection_state = 'NOT_SELECTABLE',
          row_json = jsonb_strip_nulls(
            COALESCE(stale_target_preview.row_json, '{}'::jsonb)
            || jsonb_build_object(
              'clone_rebase_live_refresh_required', true,
              'clone_rebase_live_refresh_reason', COALESCE(v_clone_eligibility->>'reason', 'CLONE_REBASE_INELIGIBLE'),
              'clone_rebase_invalidated_at_utc', v_now::text,
              'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
            )
          ),
          updated_at_utc = v_now
      WHERE stale_target_preview.session_id = p_target_session_id
        AND stale_target_preview.candidate_id = v_candidate_id
        AND stale_target_preview.session_version = v_target_session.version
        AND UPPER(BTRIM(COALESCE(stale_target_preview.status, ''))) = 'READY';

      GET DIAGNOSTICS v_target_invalidated_preview_count = ROW_COUNT;

      UPDATE public.banking_pay_workbench_candidate_source_lines AS stale_target_source
      SET status = 'DIRTY',
          updated_at_utc = v_now
      WHERE stale_target_source.session_id = p_target_session_id
        AND stale_target_source.candidate_id = v_candidate_id
        AND stale_target_source.session_version = v_target_session.version
        AND stale_target_source.status = 'CURRENT';

      GET DIAGNOSTICS v_target_invalidated_source_count = ROW_COUNT;

      UPDATE public.banking_pay_workbench_session_candidate_state AS stale_candidate_state
      SET status = 'PENDING',
          source_change_seq = COALESCE(v_ineligible_source_change_seq, 0),
          session_version = v_target_session.version,
          pending_job_id = v_job_id,
          updated_at_utc = v_now,
          last_error_json = NULL::jsonb
      WHERE stale_candidate_state.session_id = p_target_session_id
        AND stale_candidate_state.candidate_id = v_candidate_id;

      UPDATE public.banking_pay_workbench_session_scope AS target_scope_update
      SET status = 'SOURCE_BUILD_PENDING',
          seeded = false,
          dirty = true,
          pending_job_id = v_job_id,
          error_json = NULL::jsonb,
          updated_at_utc = v_now
      WHERE target_scope_update.session_id = p_target_session_id
        AND target_scope_update.candidate_id = v_candidate_id;

      v_legacy_refresh_enqueued_count := v_legacy_refresh_enqueued_count + 1;
    END IF;
  END LOOP;

  IF v_more_due IS TRUE THEN
    UPDATE public.banking_pay_workbench_sessions AS session_update
    SET scope_seed_complete = false,
        scope_next_cursor_json = COALESCE(v_next_cursor_json, '{}'::jsonb),
        scope_total_count = GREATEST(COALESCE(session_update.scope_total_count, 0) + COALESCE(v_processed_candidate_count, 0), 0),
        scope_seeded_count = GREATEST(COALESCE(session_update.scope_seeded_count, 0) + COALESCE(v_copied_candidate_count, 0) + COALESCE(v_ready_empty_candidate_count, 0), 0),
        scope_ready_count = GREATEST(COALESCE(session_update.scope_ready_count, 0) + COALESCE(v_copied_candidate_count, 0) + COALESCE(v_ready_empty_candidate_count, 0), 0),
        scope_pending_count = GREATEST(COALESCE(session_update.scope_pending_count, 0) + COALESCE(v_legacy_refresh_enqueued_count, 0), 0),
        line_units_total = GREATEST(COALESCE(session_update.line_units_total, 0) + COALESCE(v_copied_line_work_count, 0), 0),
        line_units_ready = GREATEST(COALESCE(session_update.line_units_ready, 0) + COALESCE(v_copied_line_work_count, 0), 0),
        preview_row_count = GREATEST(COALESCE(session_update.preview_row_count, 0) + COALESCE(v_copied_preview_row_count, 0), 0),
        progress_state = 'CLONE_REBASING',
        progress_json = jsonb_strip_nulls(
          COALESCE(session_update.progress_json, '{}'::jsonb)
          || jsonb_build_object(
            'clone_rebase_applied', true,
            'clone_rebase_counter_source', 'chunk_delta',
            'clone_rebase_last_source_session_id', v_source_session_id::text,
            'clone_rebase_last_at_utc', v_now::text,
            'clone_rebase_copied_candidate_count', COALESCE(v_copied_candidate_count, 0),
            'clone_rebase_ready_empty_candidate_count', COALESCE(v_ready_empty_candidate_count, 0),
            'clone_rebase_copied_preview_row_count', COALESCE(v_copied_preview_row_count, 0),
            'clone_rebase_legacy_refresh_enqueued_count', COALESCE(v_legacy_refresh_enqueued_count, 0),
            'clone_rebase_more_due', true,
            'clone_rebase_next_cursor_json', v_next_cursor_json
          )
        ),
        progress_counter_version = COALESCE(session_update.progress_counter_version, 0) + 1,
        progress_updated_at_utc = v_now,
        updated_at_utc = v_now
    WHERE session_update.id = p_target_session_id;
  ELSE
    UPDATE public.banking_pay_workbench_sessions AS session_update
    SET scope_seed_complete = COALESCE(v_more_due, false) IS NOT TRUE,
        scope_next_cursor_json = COALESCE(v_next_cursor_json, '{}'::jsonb),
        scope_total_count = (
          SELECT COUNT(*)::integer
          FROM public.banking_pay_workbench_session_scope AS scope_row
          WHERE scope_row.session_id = p_target_session_id
        ),
        progress_state = CASE
          WHEN v_more_due IS TRUE THEN 'CLONE_REBASING'
          WHEN EXISTS (
            SELECT 1
            FROM public.banking_pay_workbench_session_scope AS failed_scope
            WHERE failed_scope.session_id = p_target_session_id
              AND UPPER(BTRIM(COALESCE(failed_scope.status, ''))) IN ('FAILED', 'ERROR', 'LINE_WORK_ERROR', 'LINE_WORK_PROCESS_ERROR', 'SOURCE_BUILD_ERROR')
          ) OR EXISTS (
            SELECT 1
            FROM public.banking_pay_workbench_candidate_line_work AS failed_line_work
            WHERE failed_line_work.session_id = p_target_session_id
              AND UPPER(BTRIM(COALESCE(failed_line_work.status, ''))) IN ('ERROR', 'FAILED')
          ) THEN 'ERROR'
          WHEN COALESCE(v_legacy_refresh_enqueued_count, 0) > 0
            OR EXISTS (
              SELECT 1
              FROM public.banking_pay_workbench_session_scope AS pending_scope
              WHERE pending_scope.session_id = p_target_session_id
                AND (
                  COALESCE(pending_scope.dirty, false) IS TRUE
                  OR UPPER(BTRIM(COALESCE(pending_scope.status, ''))) NOT IN ('READY', 'MATERIALISED', 'MATERIALIZED', 'SOURCE_EMPTY', 'FAILED', 'ERROR', 'LINE_WORK_ERROR', 'LINE_WORK_PROCESS_ERROR', 'SOURCE_BUILD_ERROR')
                )
            ) THEN 'REFRESHING_CANDIDATES'
          ELSE 'READY'
        END,
        scope_ready_count = (
          SELECT COUNT(*)::integer
          FROM public.banking_pay_workbench_session_scope AS scope_row
          WHERE scope_row.session_id = p_target_session_id
            AND UPPER(BTRIM(COALESCE(scope_row.status, ''))) IN ('READY', 'MATERIALISED', 'MATERIALIZED', 'SOURCE_EMPTY')
        ),
        scope_pending_count = (
          SELECT COUNT(*)::integer
          FROM public.banking_pay_workbench_session_scope AS scope_row
          WHERE scope_row.session_id = p_target_session_id
            AND UPPER(BTRIM(COALESCE(scope_row.status, ''))) NOT IN ('READY', 'MATERIALISED', 'MATERIALIZED', 'SOURCE_EMPTY', 'FAILED', 'ERROR', 'LINE_WORK_ERROR', 'LINE_WORK_PROCESS_ERROR', 'SOURCE_BUILD_ERROR')
        ),
        scope_failed_count = (
          SELECT COUNT(*)::integer
          FROM public.banking_pay_workbench_session_scope AS scope_row
          WHERE scope_row.session_id = p_target_session_id
            AND UPPER(BTRIM(COALESCE(scope_row.status, ''))) IN ('FAILED', 'ERROR', 'LINE_WORK_ERROR', 'LINE_WORK_PROCESS_ERROR', 'SOURCE_BUILD_ERROR')
        ),
        scope_seeded_count = (
          SELECT COUNT(*)::integer
          FROM public.banking_pay_workbench_session_scope AS scope_row
          WHERE scope_row.session_id = p_target_session_id
            AND COALESCE(scope_row.seeded, false) IS TRUE
        ),
        line_units_total = (
          SELECT COUNT(*)::integer
          FROM public.banking_pay_workbench_candidate_line_work AS line_work
          WHERE line_work.session_id = p_target_session_id
        ),
        line_units_ready = (
          SELECT COUNT(*)::integer
          FROM public.banking_pay_workbench_candidate_line_work AS line_work
          WHERE line_work.session_id = p_target_session_id
            AND UPPER(BTRIM(COALESCE(line_work.status, ''))) IN ('MATERIALISED', 'MATERIALIZED', 'SKIPPED', 'SUPERSEDED', 'SOURCE_EMPTY', 'NOT_APPLICABLE', 'OBSOLETE')
        ),
        line_units_pending = (
          SELECT COUNT(*)::integer
          FROM public.banking_pay_workbench_candidate_line_work AS line_work
          WHERE line_work.session_id = p_target_session_id
            AND UPPER(BTRIM(COALESCE(line_work.status, ''))) IN ('PENDING', 'READY')
        ),
        line_units_failed = (
          SELECT COUNT(*)::integer
          FROM public.banking_pay_workbench_candidate_line_work AS line_work
          WHERE line_work.session_id = p_target_session_id
            AND UPPER(BTRIM(COALESCE(line_work.status, ''))) IN ('ERROR', 'FAILED')
        ),
        section_counts_json = (
          SELECT COALESCE(jsonb_object_agg(section_count.section, section_count.row_count ORDER BY section_count.section), '{}'::jsonb)
          FROM (
            SELECT preview_row.section, COUNT(*)::integer AS row_count
            FROM public.banking_pay_workbench_preview_rows AS preview_row
            WHERE preview_row.session_id = p_target_session_id
              AND preview_row.session_version = v_target_session.version
              AND preview_row.status = 'READY'
            GROUP BY preview_row.section
          ) AS section_count
        ),
        candidate_sample_rows_json = (
          SELECT COALESCE(jsonb_agg(sample_row.sample_json ORDER BY sample_row.scope_ordinal), '[]'::jsonb)
          FROM (
            SELECT scope_row.scope_ordinal,
                   jsonb_build_object('candidate_id', scope_row.candidate_id::text, 'status', scope_row.status) AS sample_json
            FROM public.banking_pay_workbench_session_scope AS scope_row
            WHERE scope_row.session_id = p_target_session_id
            ORDER BY scope_row.scope_ordinal
            LIMIT 10
          ) AS sample_row
        ),
        preview_row_count = (
          SELECT COUNT(*)::integer
          FROM public.banking_pay_workbench_preview_rows AS preview_row
          WHERE preview_row.session_id = p_target_session_id
            AND preview_row.session_version = v_target_session.version
            AND preview_row.status = 'READY'
        ),
        selected_row_count = (
          SELECT COUNT(*)::integer
          FROM public.banking_pay_workbench_preview_rows AS preview_row
          WHERE preview_row.session_id = p_target_session_id
            AND preview_row.session_version = v_target_session.version
            AND preview_row.status = 'READY'
            AND preview_row.selected IS TRUE
            AND preview_row.selection_state = 'SELECTED'
        ),
        progress_json = jsonb_strip_nulls(
          COALESCE(session_update.progress_json, '{}'::jsonb)
          || jsonb_build_object(
            'clone_rebase_applied', true,
            'clone_rebase_last_source_session_id', v_source_session_id::text,
            'clone_rebase_last_at_utc', v_now::text,
            'clone_rebase_copied_candidate_count', COALESCE(v_copied_candidate_count, 0),
            'clone_rebase_legacy_refresh_enqueued_count', COALESCE(v_legacy_refresh_enqueued_count, 0),
            'clone_rebase_case_resolution_carry_forward_disabled', true,
            'clone_rebase_case_resolution_carried_forward_count', 0,
            'clone_rebase_case_resolution_stale_review_count', 0,
            'clone_rebase_case_resolution_preview_row_count', 0,
            'clone_rebase_more_due', COALESCE(v_more_due, false),
            'clone_rebase_next_cursor_json', v_next_cursor_json
          )
        ),
        progress_counter_version = COALESCE(session_update.progress_counter_version, 0) + 1,
        progress_updated_at_utc = v_now,
        updated_at_utc = v_now
    WHERE session_update.id = p_target_session_id;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'clone_rebase_applied', true,
    'copied_candidate_count', COALESCE(v_copied_candidate_count, 0),
    'ready_empty_candidate_count', COALESCE(v_ready_empty_candidate_count, 0),
    'copied_source_row_count', COALESCE(v_copied_source_row_count, 0),
    'copied_line_work_count', COALESCE(v_copied_line_work_count, 0),
    'copied_preview_row_count', COALESCE(v_copied_preview_row_count, 0),
    'case_resolution_carry_forward_disabled', true,
    'case_resolution_carried_forward_count', 0,
    'case_resolution_stale_review_count', 0,
    'case_resolution_preview_row_count', 0,
    'legacy_refresh_enqueued_count', COALESCE(v_legacy_refresh_enqueued_count, 0),
    'more_due', COALESCE(v_more_due, false),
    'next_cursor_json', v_next_cursor_json
  );
END;
$function$;
ALTER FUNCTION public.pay_workbench_session_clone_eligible_rows_v1(uuid, uuid, integer, jsonb, jsonb) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.pay_workbench_session_clone_eligible_rows_v1(uuid, uuid, integer, jsonb, jsonb) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.pay_workbench_session_clone_eligible_rows_v1(uuid, uuid, integer, jsonb, jsonb) TO authenticated, service_role;

-- Installed pg_get_functiondef MD5: d9c1502c1ebc162205b27dd0d80aa1a9
CREATE OR REPLACE FUNCTION public.pay_workbench_session_replay_replaced_queue_v1(
  p_source_session_id uuid,
  p_target_session_id uuid,
  p_reason text DEFAULT 'REPLACED_SESSION_QUEUE_REPLAY'::text,
  p_options_json jsonb DEFAULT '{}'::jsonb
)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_reason text := COALESCE(NULLIF(BTRIM(p_reason), ''), 'REPLACED_SESSION_QUEUE_REPLAY');
  v_options_json jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_options_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_options_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_source_session public.banking_pay_workbench_sessions%ROWTYPE;
  v_target_session public.banking_pay_workbench_sessions%ROWTYPE;
  v_candidate_scope_missing_count integer := 0;
  v_source_active_job_count integer := 0;
  v_source_queued_job_count integer := 0;
  v_source_running_job_count integer := 0;
  v_replayed_job_count integer := 0;
  v_source_queued_terminalised_count integer := 0;
  v_replay_job_ids jsonb := '[]'::jsonb;
  v_source_job_ids jsonb := '[]'::jsonb;
  v_terminalise_source_queued boolean := true;
BEGIN
  IF p_source_session_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_QUEUE_REPLAY_SOURCE_SESSION_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code','PAY_WORKBENCH_QUEUE_REPLAY_SOURCE_SESSION_REQUIRED')::text;
  END IF;

  IF p_target_session_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_QUEUE_REPLAY_TARGET_SESSION_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code','PAY_WORKBENCH_QUEUE_REPLAY_TARGET_SESSION_REQUIRED')::text;
  END IF;

  SELECT source_session.*
  INTO v_source_session
  FROM public.banking_pay_workbench_sessions AS source_session
  WHERE source_session.id = p_source_session_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_QUEUE_REPLAY_SOURCE_SESSION_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code','PAY_WORKBENCH_QUEUE_REPLAY_SOURCE_SESSION_NOT_FOUND',
              'source_session_id', p_source_session_id::text
            )::text;
  END IF;

  SELECT target_session.*
  INTO v_target_session
  FROM public.banking_pay_workbench_sessions AS target_session
  WHERE target_session.id = p_target_session_id
    AND UPPER(BTRIM(COALESCE(target_session.status, ''))) = 'OPEN'
    AND target_session.discarded_at_utc IS NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_QUEUE_REPLAY_TARGET_SESSION_NOT_OPEN'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code','PAY_WORKBENCH_QUEUE_REPLAY_TARGET_SESSION_NOT_OPEN',
              'target_session_id', p_target_session_id::text
            )::text;
  END IF;

  IF p_source_session_id = p_target_session_id THEN
    RETURN jsonb_build_object(
      'ok', true,
      'source_session_id', p_source_session_id::text,
      'target_session_id', p_target_session_id::text,
      'skipped', true,
      'skip_reason', 'SOURCE_AND_TARGET_IDENTICAL',
      'replayed_job_count', 0,
      'source_queued_terminalised_count', 0,
      'source_running_job_count', 0
    );
  END IF;

  v_terminalise_source_queued := LOWER(BTRIM(COALESCE(v_options_json->>'terminalise_source_queued', 'true'))) NOT IN ('false','f','0','no','n','off');

  DROP TABLE IF EXISTS pg_temp._bpay_replaced_session_queue_replay_jobs;
  CREATE TEMP TABLE _bpay_replaced_session_queue_replay_jobs ON COMMIT DROP AS
  SELECT
    source_job.id AS source_job_id,
    source_job.job_type,
    UPPER(BTRIM(COALESCE(source_job.status, ''))) AS source_status,
    source_job.priority,
    source_job.run_at_utc,
    source_job.attempt_count,
    source_job.max_attempts,
    source_job.snapshot_run_id,
    source_job.session_id,
    source_job.candidate_id,
    COALESCE(source_job.payload_json, '{}'::jsonb) AS payload_json,
    (
      'REPLAY_REPLACED_SESSION:'
      || p_target_session_id::text
      || ':source_job:'
      || source_job.id::text
    ) AS replay_dedupe_key
  FROM public.banking_pay_workbench_jobs AS source_job
  WHERE source_job.session_id = p_source_session_id
    AND UPPER(BTRIM(COALESCE(source_job.status, ''))) IN ('QUEUED','RUNNING')
    AND UPPER(BTRIM(COALESCE(source_job.job_type, ''))) IN (
      'WORKBENCH_SESSION_SCOPE_SEED',
      'WORKBENCH_CANDIDATE_SOURCE_BUILD',
      'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK',
      'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE',
      'WORKBENCH_CANDIDATE_DELTA_REFRESH',
      'WORKBENCH_CANDIDATE_LINE_WORK_SEED',
      'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS',
      'WORKBENCH_PREVIEW_ROWS_MATERIALISE',
      'CANDIDATE_SOURCE_BUILD',
      'CANDIDATE_SOURCE_BUILD_CHUNK',
      'SOURCE_BUILD',
      'SOURCE_BUILD_PAGE'
    );

  SELECT COUNT(*)::integer,
         COUNT(*) FILTER (WHERE source_status = 'QUEUED')::integer,
         COUNT(*) FILTER (WHERE source_status = 'RUNNING')::integer,
         COALESCE(jsonb_agg(source_job_id::text ORDER BY source_job_id::text), '[]'::jsonb)
  INTO v_source_active_job_count,
       v_source_queued_job_count,
       v_source_running_job_count,
       v_source_job_ids
  FROM pg_temp._bpay_replaced_session_queue_replay_jobs;

  IF COALESCE(v_source_active_job_count, 0) = 0 THEN
    RETURN jsonb_build_object(
      'ok', true,
      'source_session_id', p_source_session_id::text,
      'target_session_id', p_target_session_id::text,
      'reason', v_reason,
      'source_active_job_count', 0,
      'source_queued_job_count', 0,
      'source_running_job_count', 0,
      'replayed_job_count', 0,
      'source_queued_terminalised_count', 0,
      'replay_job_ids', '[]'::jsonb,
      'source_job_ids', '[]'::jsonb
    );
  END IF;

  SELECT COUNT(*)::integer
  INTO v_candidate_scope_missing_count
  FROM pg_temp._bpay_replaced_session_queue_replay_jobs AS replay_job
  WHERE replay_job.candidate_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1
      FROM public.banking_pay_workbench_session_scope AS target_scope
      WHERE target_scope.session_id = p_target_session_id
        AND target_scope.candidate_id = replay_job.candidate_id
    );

  WITH replayed_jobs AS (
    INSERT INTO public.banking_pay_workbench_jobs (
      job_type,
      status,
      priority,
      run_at_utc,
      attempt_count,
      max_attempts,
      dedupe_key,
      snapshot_run_id,
      session_id,
      candidate_id,
      payload_json,
      created_at_utc,
      updated_at_utc
    )
    SELECT
      CASE
        WHEN UPPER(BTRIM(replay_job.job_type)) IN ('CANDIDATE_SOURCE_BUILD','CANDIDATE_SOURCE_BUILD_CHUNK','SOURCE_BUILD','SOURCE_BUILD_PAGE')
          THEN 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
        ELSE replay_job.job_type
      END,
      'QUEUED',
      replay_job.priority,
      LEAST(COALESCE(replay_job.run_at_utc, v_now), v_now),
      0,
      GREATEST(COALESCE(replay_job.max_attempts, 8), 1),
      replay_job.replay_dedupe_key,
      v_target_session.source_snapshot_run_id,
      p_target_session_id,
      replay_job.candidate_id,
      jsonb_strip_nulls(
        (replay_job.payload_json - ARRAY[
          'worker_id',
          'worker_claimed_at_utc',
          'worker_lease_seconds',
          'worker_lease_expires_at_utc',
          'worker_function',
          'result_json',
          'completion_json',
          'session_id',
          'sessionId',
          'source_session_id',
          'sourceSessionId',
          'target_session_id',
          'targetSessionId',
          'snapshot_run_id',
          'source_snapshot_run_id',
          'session_version',
          'sessionVersion'
        ]::text[])
        || jsonb_build_object(
          'session_id', p_target_session_id::text,
          'target_session_id', p_target_session_id::text,
          'snapshot_run_id', CASE WHEN v_target_session.source_snapshot_run_id IS NULL THEN NULL ELSE v_target_session.source_snapshot_run_id::text END,
          'source_snapshot_run_id', CASE WHEN v_target_session.source_snapshot_run_id IS NULL THEN NULL ELSE v_target_session.source_snapshot_run_id::text END,
          'session_version', v_target_session.version,
          'replayed_from_replaced_session', true,
          'replayed_from_session_id', p_source_session_id::text,
          'replayed_from_job_id', replay_job.source_job_id::text,
          'replayed_from_job_status', replay_job.source_status,
          'replay_reason', v_reason,
          'replayed_at_utc', v_now::text
        )
      ),
      v_now,
      v_now
    FROM pg_temp._bpay_replaced_session_queue_replay_jobs AS replay_job
    ON CONFLICT (dedupe_key) WHERE status IN ('QUEUED','RUNNING')
    DO UPDATE SET
      priority = LEAST(public.banking_pay_workbench_jobs.priority, EXCLUDED.priority),
      run_at_utc = LEAST(public.banking_pay_workbench_jobs.run_at_utc, EXCLUDED.run_at_utc),
      payload_json = COALESCE(public.banking_pay_workbench_jobs.payload_json, '{}'::jsonb)
        || EXCLUDED.payload_json
        || jsonb_build_object(
          'queue_replay_reused', true,
          'queue_replay_reused_at_utc', v_now::text
        ),
      updated_at_utc = v_now
    RETURNING id
  )
  SELECT COUNT(*)::integer,
         COALESCE(jsonb_agg(replayed_jobs.id::text ORDER BY replayed_jobs.id::text), '[]'::jsonb)
  INTO v_replayed_job_count,
       v_replay_job_ids
  FROM replayed_jobs;

  IF COALESCE(v_terminalise_source_queued, true) THEN
    UPDATE public.banking_pay_workbench_jobs AS old_job
    SET status = 'DEAD',
        failed_at_utc = COALESCE(old_job.failed_at_utc, v_now),
        updated_at_utc = v_now,
        last_error_json = jsonb_strip_nulls(
          jsonb_build_object(
            'code', 'REPLACED_SESSION_QUEUE_REPLAYED',
            'message', 'Queued work was replayed against the replacement Banking Pay workbench session.',
            'source_session_id', p_source_session_id::text,
            'replacement_session_id', p_target_session_id::text,
            'replay_reason', v_reason,
            'replayed_at_utc', v_now::text
          )
        ),
        payload_json = COALESCE(old_job.payload_json, '{}'::jsonb)
          || jsonb_build_object(
            'terminalised_as_replaced_session_queue_replayed', true,
            'replacement_session_id', p_target_session_id::text,
            'terminalised_at_utc', v_now::text
          )
    FROM pg_temp._bpay_replaced_session_queue_replay_jobs AS replay_job
    WHERE old_job.id = replay_job.source_job_id
      AND old_job.status = 'QUEUED';

    GET DIAGNOSTICS v_source_queued_terminalised_count = ROW_COUNT;
  END IF;

  PERFORM public._audit_insert(
    'banking_pay_workbench_session',
    p_source_session_id::text,
    'WORKBENCH_REPLACED_SESSION_QUEUE_REPLAYED',
    jsonb_build_object(
      'source_session_id', p_source_session_id::text,
      'target_session_id', p_target_session_id::text,
      'source_active_job_count', COALESCE(v_source_active_job_count, 0),
      'source_queued_job_count', COALESCE(v_source_queued_job_count, 0),
      'source_running_job_count', COALESCE(v_source_running_job_count, 0),
      'source_job_ids', COALESCE(v_source_job_ids, '[]'::jsonb)
    ),
    jsonb_build_object(
      'replayed_job_count', COALESCE(v_replayed_job_count, 0),
      'source_queued_terminalised_count', COALESCE(v_source_queued_terminalised_count, 0),
      'candidate_scope_missing_count', COALESCE(v_candidate_scope_missing_count, 0),
      'replay_job_ids', COALESCE(v_replay_job_ids, '[]'::jsonb)
    ),
    v_reason,
    NULL::uuid
  );

  RETURN jsonb_build_object(
    'ok', true,
    'source_session_id', p_source_session_id::text,
    'target_session_id', p_target_session_id::text,
    'reason', v_reason,
    'source_active_job_count', COALESCE(v_source_active_job_count, 0),
    'source_queued_job_count', COALESCE(v_source_queued_job_count, 0),
    'source_running_job_count', COALESCE(v_source_running_job_count, 0),
    'replayed_job_count', COALESCE(v_replayed_job_count, 0),
    'source_queued_terminalised_count', COALESCE(v_source_queued_terminalised_count, 0),
    'candidate_scope_missing_count', COALESCE(v_candidate_scope_missing_count, 0),
    'source_job_ids', COALESCE(v_source_job_ids, '[]'::jsonb),
    'replay_job_ids', COALESCE(v_replay_job_ids, '[]'::jsonb),
    'running_source_jobs_left_to_complete_stale', COALESCE(v_source_running_job_count, 0)
  );
END;
$function$;
ALTER FUNCTION public.pay_workbench_session_replay_replaced_queue_v1(uuid, uuid, text, jsonb) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.pay_workbench_session_replay_replaced_queue_v1(uuid, uuid, text, jsonb) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.pay_workbench_session_replay_replaced_queue_v1(uuid, uuid, text, jsonb) TO PUBLIC, anon, authenticated, service_role;

