DROP TRIGGER IF EXISTS trg_bpay_wb_transfers_delete_dirty_v1 ON public.pay_bank_transfers;

-- Drop the two public delivery RPCs and seven private helpers only after exact
-- installed callers have been restored above.
DROP FUNCTION IF EXISTS public.pay_workbench_source_build_attempt_execute_v1(
  uuid,uuid,text,uuid,uuid,text,text
);
DROP FUNCTION IF EXISTS public.pay_workbench_source_build_attempt_claim_start_v1(
  text,text,integer,timestamptz,uuid,uuid
);
