  uuid,uuid,jsonb,integer,uuid[],uuid[],uuid[],uuid
);
DROP FUNCTION IF EXISTS private.pay_workbench_financial_scope_dirty_transition_v1();
DROP FUNCTION IF EXISTS private.pay_workbench_scope_invalidate_v1(uuid[],uuid[],text,uuid,jsonb);

-- Remove changed-table indexes/constraints/columns, restoring the exact
-- installed table surfaces. Private-table indexes disappear with their tables.
DROP INDEX IF EXISTS public.bpay_wb_jobs_source_claim_idx;
DROP INDEX IF EXISTS public.bpay_advances_candidate_open_timesheet_idx;
DROP INDEX IF EXISTS public.bpay_finance_components_candidate_open_timesheet_idx;
DROP INDEX IF EXISTS public.bpay_timesheet_overrides_candidate_active_idx;
